COLLDATA("muslim","ur",[[1427,"عبدالواحد بن زیاد نے ہمیں حدیث سنائی ، کہا : ہم سے عثمان بن حکیم نے حدیث بیان کی ، کہا : ہمیں عبدالرحمان بن ابی عمرہ نے حدیث سنائی ، کہا : سیدنا عثمان بن عفان رضی اللہ عنہ مغر ب کی نماز کے بعد مسجد میں تشریف لائے اور اکیلے بیٹھ گئے ، میں بھی ان کے پاس بیٹھ گیا ، وہ کہنے لگے : بھتیجے ! میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : ’’ جس نے عشاء کی نماز باجماعت ادا کی تو گویا اس نے آدھی رات کا قیام کیا اور جس نے صبح کی نماز ( بھی ) جماعت کے ساتھ پڑھی تو گویا اس نے ساری رات نماز پڑھی ۔ ‘‘","",{"u2":"عبدالواحد بن زیاد نے ہمیں حدیث سنائی، کہا: ہم سے عثمان بن حکیم نے حدیث بیان کی، کہا: ہمیں عبدالرحمان بن ابی عمرہ نے حدیث سنائی، کہا: حضرت عثمان بن عفان رضی اللہ عنہ مغر ب کی نماز کے بعد مسجد میں تشریف لائے اور اکیلے بیٹھ گئے، میں بھی ان کے پاس بیٹھ گیا، وہ کہنے لگے: بھتیجے! میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’ جس نے عشاء کی نماز باجماعت ادا کی تو گویا اس نے آدھی رات کا قیام کیا اور جس نےصبح کی نماز (بھی) جماعت کے ساتھ پڑھی تو گویا اس نے ساری رات نماز پڑھی۔‘‘"}],[1428,"سفیان نے ابو سہل عثمان بن حکیم سے اسی سند کے ساتھ اسی طرح روایت کی ۔","",{"u2":"سفیان نے ابو سہل عثمان بن حکیم سے اسی سند کے ساتھ اسی طرح روایت کی۔"}],[1429,"بشر ، یعنی ابن مفضل نے ہمیں حدیث سنائی ، انھوں نے خالد سے اور انھوں نے انس بن سیرین سے روایت کی ، کہا : میں نے سیدنا جندب بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جس شخص نے صبح کی نماز پڑھی و ہ اللہ تعالیٰ کی ذمہ داری ( امان ) میں ہے ۔ تو ایسانہ ہو کہ ( ایسے شخص کو کسی طرح نقصان پہنچانے کی بناپر ) اللہ تعالیٰ تم ( میں سے کسی شخص ) سے اپنے ذمے کے بارے میں کسی چیز کا مطالبہ کرے ، پھر وہ اسے پکڑ لے ، پھر اسے اوندھے منہ جہنم میں ڈال دے ۔ ‘‘","",{"u2":"بشر، یعنی ابن مفضل نے ہمیں حدیث سنائی، انھوں نے خالد سے اور انھوں نے انس بن سیرین سے روایت کی،کہا: میں نے حضرت جندب بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے صبح کی نماز پڑھی و ہ اللہ تعالیٰ کی ذمہ داری (امان)میں ہے۔ تو ایسانہ ہو کہ (ایسے شخص کو کسی طرح نقصان پہنچانے کی بناپر)اللہ تعالیٰ تم (میں سے کسی شخص) سے اپنے ذمے کے بارے میں کسی چیز کا مطالبہ کرے، پھر وہ اسے پکڑ لے، پھر اسے اوندھے منہ جہنم میں ڈال دے۔‘‘"}],[1430,"اسماعیل نے خالد سے او ر انھوں نے انس بن سیرین سے روایت کی ، کہا : میں نے جندب ( بن عبداللہ ) قسری رضی اللہ عنہ سےسنا ، وہ کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جس نے صبح کی نماز ادا کی ، وہ اللہ کے ذمے میں آگیا ، ( دعا ہے ) اللہ تم سے اپنے ذمے کے حوالے سے کوئی مطالبہ نہ کرے کیونکہ جس سے وہ اپنے ذمے میں سے کسی چیز کا مطالبہ کر لے ، اسے پالیتا ہے ، پھر اسے اوندھے منہ جہنم کی آگ میں ڈال دیتا ہے ۔ ‘‘","",{"u2":"اسماعیل نے خالد سے او ر انھوں نے انس بن سیرین سے روایت کی، کہا: میں نے جندب (بن عبداللہ)قسری رضی اللہ عنہ سےسنا، وہ کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جس نے صبح کی نماز ادا کی، وہ اللہ کے ذمے میں آگیا، (دعا ہے)اللہ تم سے اپنے ذمے کے حوالے سے کوئی مطالبہ نہ کرے کیونکہ جس سے وہ اپنے ذمے میں سے کسی چیز کا مطالبہ کر لے، اسے پالیتا ہے، پھر اسے اوندھے منہ جہنم کی آگ میں ڈال دیتا ہے۔‘‘"}],[1431,"یہی روایت حسن بصری نے جندب بن سفیان کے حوالے سے نبی صلی اللہ علیہ وسلم سے روایت کی ( لیکن آخری فقرہ ) فیکبہ فی نار جہنم ( اس کو جہنم میں اوندھے منہ پھینک دیتا ہے ) بیان نہیں کیا ۔","",{"u2":"یہی روایت حسن بصری نے جندب بن سفیان کے حوالے سے نبی صلی اللہ علیہ وسلم سے روایت کی (لیکن آخری فقرہ)فیکبہ فی نار جہنم (اس کو جہنم میں اوندھے منہ پھینک دیتا ہے)بیان نہیں کیا۔"}],[1432,"یونس نے ابن شہاب سےروایت کی کہ محمود بن ربیع انصاری رضی اللہ عنہ نے ان سے بیان کیاکہ سیدنا عتبان بن مالک رضی اللہ عنہ نے جو ان صحابہ کرام میں سے تھے جو انصار میں سے جنگ بدر میں شریک ہوئے تھے ، ( بیان کیا ) کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو ئے اور عرض کی : اے اللہ کے رسول ! میری نظر خراب ہو گئی ہے ، میں اپنی قوم کو نماز پڑھتا ہوں اور جب بارشیں ہوتی ہیں تو میرے اور ان کےدرمیان والی وادی میں سیلاب آجاتا ہے ، اس کی وجہ سے میں ان کی مسجد میں نہیں پہنچ سکتا کہ میں انھیں نماز پڑھاؤں تو اے اللہ کے رسول! میں چاہتا ہوں کہ آپ ( میرگھر ) تشریف لائیں اور نماز پڑھنے کی کسی ایک جگہ پر نماز پڑھیں تاکہ میں اس جگہ کو ( مستقل طور پر ) جائے نماز بنالوں ۔ کہا : آپ صلی اللہ علیہ وسلم نے فرمایا : ’’ ان شاء اللہ میں ایسا کروں گا ۔ ‘‘ عتبان رضی اللہ عنہ نے کہا : تو صبح کے وقت دن چڑھتے ہی آپ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ تشریف لائے ، رسول اللہ صلی اللہ علیہ وسلم نے ( اندر آنے کی ) اجازت طلب فرمائی ، میں نے تشریف آوری کا کہا ، آپ آ کر بیٹھے نہیں یہاں تک کہ گھر کے اندر ( کے حصے میں ) داخل ہوئے ، پھر پوچھا : ’’تم اپنے گھر میں کس جگہ چاہتے ہو کہ میں ( وہاں ) نماز پڑھوں ؟ ‘‘ میں نے گھر کے ایک کونے کی طرف اشارہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے کھڑے ہو کر تکبیر ( تحریمہ ) کہی اور ہم آپ کے پیچھے کھڑے ہو گئے ، آپ نے دورکعتیں ادا فرمائیں ، پھر سلام پھیر دیا ۔ اس کے بعد ہم نے آپ کو خزیر ( گوشت کے چھوٹے ٹکڑوں سے بنے ہوئے کھا نے ) کے لیے روک لیا جو ہم نے آپ کے لیے تیار کیا تھا ۔ ( عتبان رضی اللہ عنہ نے ) کہا : ( آپ کی آمد کا سن کر ) اردگرد سے محلے کے لوگ آگئے حتی کہ گھر میں خاصی تعدا د میں لوگ اکٹھے ہو گئے ۔ ان میں سے ایک بات کرنے والے نے کہا : مالک بن دخشن کہاں ہے ؟ ان میں سے کسی نے کہا : وہ تو منافق ہے ، اللہ اور اس کے رسول سے محبت نہیں رکھتا ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ اس کے بارے میں ایسا نہ کہو ، کیا تمھیں معلوم نہیں کہ اس نے اللہ کی رضا حاصل کرنے کے لیے لاالہ الاللہ کہا ہے ؟ ‘‘ ( عتبان رضی اللہ عنہ نے ) کہا : تو لوگوں نے کہا : اللہ اور اس سکے رسول ہی زیادہ جاننے والے ہیں ۔ اس ( الزام لگانے والے ) نےکہا : ہم تو اس کی وجہ اور اس کی خیر خواہی منافقوں ہی کے لے دیکھتے ہیں ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’بے شک اللہ تعالیٰ نے اسے شخص کو آگ پر حرام قرار دیا ہے جو لاالہ الا اللہ کہتا ہے اور اس کے ذریعے سے اللہ کی رضا کا طلب گار ہے ۔ ‘‘ ابن شہاب نے کہا : میں نے ( بعد میں ) حصین بن محمد انصاری سے ، جو بنو سالم سے تعلق رکھتے ہیں ان کے سرداروں میں سے ہیں ، محمود بن ربیع رضی اللہ عنہ کی اس حدیث کے بارے میں پوچھا تو انھوں نے اس میں ان ( محمود رضی اللہ عنہ ) کی تصدیق کی ۔","",{"u2":"یونس نے ابن شہاب سےروایت کی کہ محمود بن ربیع انصاری رضی اللہ عنہا نے ان سے بیان کیاکہ حضرت عتبان بن مالک رضی اللہ عنہ نے جو ان صحابہ کرام میں سے تھے جو انصار میں سے جنگ بدر میں شریک ہوئے تھے، (بیان کیا)کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو ئے اور عرض کی: اے اللہ کے رسول! میری نظر خراب ہو گئی ہے، میں اپنی قوم کو نماز پڑھتا ہوں اور جب بارشیں ہوتی ہیں تو میرے اور ان کےدرمیان والی وادی میں سیلاب آجاتا ہے، اس کی وجہ سے میں ان کی مسجد میں نہیں پہنچ سکتا کہ میں انھیں نماز پڑھاؤں تو اے اللہ کے رسول! میں چاہتا ہوں کہ آپ (میرگھر)تشریف لائیں اور نماز پڑھنے کی کسی ایک جگہ پر نماز پڑھیں تاکہ میں اس جگہ کو (مستقل طور پر)جائے نماز بنالوں۔ کہا: آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ ان شاء اللہ میں ایسا کروں گا۔‘‘ عتبان رضی اللہ عنہ نے کہا: تو صبح کے وقت دن چڑھتے ہی آپ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ تشریف لائے، رسول اللہ صلی اللہ علیہ وسلم نے (اندر آنے کی)اجازت طلب فرمائی، میں نے تشریف آوری کا کہا،آپ آ کر بیٹھے نہیں یہاں تک کہ گھر کے اندر (کے حصے میں)داخل ہوئے، پھر پوچھا:’’تم اپنے گھر میں کس جگہ چاہتے ہو کہ میں (وہاں)نماز پڑھوں؟‘‘ میں نے گھر کے ایک کونے کی طرف اشارہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے کھڑے ہو کر تکبیر (تحریمہ) کہی اور ہم آپ کے پیچھے کھڑے ہو گئے، آپ نے دورکعتیں ادا فرمائیں، پھر سلام پھیر دیا۔ اس کے بعد ہم نے آپ کو خزیر (گوشت کے چھوٹے ٹکڑوں سے بنے ہوئے کھا نے)کے لیے روک لیا جو ہم نے آپ کے لیے تیار کیا تھا۔ (عتبان رضی اللہ عنہ نے)کہا: (آپ کی آمد کا سن کر)اردگرد سے محلے کے لوگ آگئے حتی کہ گھر میں خاصی تعدا د میں لوگ اکٹھے ہو گئے۔ ان میں سے ایک بات کرنے والے نے کہا: مالک بن دخشن کہاں ہے؟ ان میں سے کسی نے کہا: وہ تو منافق ہے، اللہ اور اس کے رسول سے محبت نہیں رکھتا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ اس کے بارے میں ایسا نہ کہو، کیا تمھیں معلوم نہیں کہ اس نے اللہ کی رضا حاصل کرنے کے لیے لاالہ الاللہ کہا ہے؟‘‘ (عتبان رضی اللہ عنہ نے)کہا: تو لوگوں نے کہا: اللہ اور اس سکے رسول ہی زیادہ جاننے والے ہیں۔ اس (الزام لگانے والے)نےکہا: ہم تو اس کی وجہ اور اس کی خیر خواہی منافقوں ہی کے لے دیکھتے ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بے شک اللہ تعالیٰ نے اسے شخص کو آگ پر حرام قرار دیا ہے جو لاالہ الا اللہ کہتا ہے اور اس کے ذریعے سے اللہ کی رضا کا طلب گار ہے۔‘‘\nابن شہاب نے کہا: میں نے (بعد میں)حصین بن محمد انصاری سے، جو بنو سالم سے تعلق رکھتے ہیں ان کے سرداروں میں سے ہیں، محمود بن ربیع رضی اللہ عنہا کی اس حدیث کے بارے میں پوچھا تو انھوں نے اس میں ان (محمود رضی اللہ عنہ)کی تصدیق کی۔"}],[1433,"معمر نے زہر ی سے روایت کی ، کہا : مجھے محمود بن ربیع رضی اللہ عنہ نے عتبان بن مالک رضی اللہ عنہ سے حدیث سنائی ، کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا ۔ ۔ ۔ ۔ ۔ پھر یونس کی حدیث کے ہم معنی حدیث بیان کی ، البتہ یہ کہا : تو ایک آدمی نے کہا : مالک بن دخشن یا دخیشن کہاں ہے ؟ اور حدیث میں یہ اضافہ کیا : محمود رضی اللہ عنہ نے کہاں : میں نے یہ حدیث چند لوگوں کو ، جن میں ابو ایوب انصاری رضی اللہ عنہ بھی موجود تھے ، سنائی تو انھوں نے کہا : میں نہیں سمجھتا کہ جو بات تم بیان کرتے ہو رسول اللہ صلی اللہ علیہ وسلم نے فرمائی ہو ۔ اس پر میں نے ( دل میں ) قسم کھائی کہ اگر میں عتبان رضی اللہ عنہ کے ہاں دوبارہ گیا تو ان سے ( اس کے بارے میں ضرور ) پوچھوں گا ۔ تو میں دوبارہ ان کے پاس آیا ، میں نے دیکھا کہ وہ بہت بوڑھے ہو چکے ہیں ، ان کی بینائی ختم ہو چکی تھی لیکن وہ ( اب بھی ) اپنی قوم کے امام تھے ۔ میں ان کے پہلو میں بیٹھ گیا اور ان سے اس حدیث کے بارے میں پوچھا تو انھوں نے مجھے بالکل اسی طرح ( ساری ) حدیث سنائی جس طرح پہلے سنائی تھی ۔ زہری نے کہا : اس واقعے کے بعد بہت سے فرائض اور دیگر امور ( احکام ) نازل ہوئے اور ہماری نظر میں معاملہ انھی پر تمام ہوا ، لہٰذا جو انسان چاہتا ہےکہ ( عتبان رضی اللہ عنہ کی حدیث کے ظاہری مفہوم سے ) دھو کا نہ کھائے ، وہ دھوکا کھا نے سے بچے ۔","",{"u2":"معمر نے زہر ی سے روایت کی، کہا: مجھے محمود بن ربیع رضی اللہ عنہا نے عتبان بن مالک رضی اللہ عنہ سے حدیث سنائی، کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا۔۔۔۔۔پھر یونس کی حدیث کے ہم معنی حدیث بیان کی، البتہ یہ کہا: تو ایک آدمی نے کہا: مالک بن دخشن یا دخیشن کہاں ہے؟ اور حدیث میں یہ اضافہ کیا: محمود رضی اللہ عنہ نے کہاں: میں نے یہ حدیث چند لوگوں کو، جن میں ابو ایوب انصاری رضی اللہ عنہ بھی موجود تھے،سنائی تو انھوں نے کہا: میں نہیں سمجھتا کہ جو بات تم بیان کرتے ہو رسول اللہ صلی اللہ علیہ وسلم نے فرمائی ہو۔ اس پر میں نے (دل میں)قسم کھائی کہ اگر میں عتبان رضی اللہ عنہ کے ہاں دوبارہ گیا تو ان سے (اس کے بارے میں ضرور)پوچھوں گا۔ تو میں دوبارہ ان کے پاس آیا، میں نے دیکھا کہ وہ بہت بوڑھے ہو چکے ہیں، ان کی بینائی ختم ہو چکی تھی لیکن وہ (اب بھی)اپنی قوم کے امام تھے۔ میں ان کے پہلو میں بیٹھ گیا اور ان سے اس حدیث کے بارے میں پوچھا تو انھوں نے مجھے بالکل اسی طرح (ساری) حدیث سنائی جس طرح پہلے سنائی تھی۔\nزہری نے کہا: اس واقعے کے بعد بہت سے فرائض اور دیگر امور (احکام)نازل ہوئے اور ہماری نظر میں معاملہ انھی پر تمام ہوا، لہذا جو انسان چاہتا ہےکہ (عتبان رضی اللہ عنہ کی حدیث کے ظاہری مفہوم سے)دھو کا نہ کھائے، وہ دھوکا کھا نے سے بچے۔"}],[1434,"اوزاعی سے روایت ہے ، کہا : مجھے زہری نے سیدنا محمود بن ربیع رضی اللہ عنہ سے حدیث سنائی ، کہا : مجھے رسول اللہ صلی اللہ علیہ وسلم کا وہ کلی کرنا اچھی طرح یا د ہے جو آپ نے ہمارے گھر میں ایک ڈول سے ( پانی لے کر ) کی تھی ( اور اس کا پانی میر منہ پر ڈالا تھا ) ۔ محمود رضی اللہ عنہ نے کہا کہ مجھے عتبان بن مالک رضی اللہ عنہ نے بتایا کہ میں نے عرض کی : اے اللہ کے رسول! میری نظر میں خرابی پیداہو گئی ہےغاور اس بات تک حدیث بیان کی کہ آپ صلی اللہ علیہ وسلم نے دو رکعات نماز پڑھائی اور یہ کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کو جشیشہ ( خزیر سے ملتے جلتے کھانے ) کے لیے روک لیا جو ہم نے آپ کے لیے بنایا تھا ۔ انھوں ( اوزاعی ) نےاس کے بعد یونس اور معمر والا اضافہ بیان نہیں کیا","",{"u2":"اوزاعی سے روایت ہے، کہا: مجھے زہری نے حضرت محمود بن ربیع رضی اللہ عنہا سے حدیث سنائی، کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم کا وہ کلی کرنا اچھی طرح یا د ہے جو آپ نے ہمارے گھر میں ایک ڈول سے (پانی لے کر)کی تھی (اور اس کا پانی میر منہ پر ڈالا تھا)۔ محمود رضی اللہ عنہ نے کہا کہ مجھے عتبان بن مالک رضی اللہ عنہ نے بتایا کہ میں نے عرض کی: اے اللہ کے رسول! میری نظر میں خرابی پیداہو گئی ہےغاور اس بات تک حدیث بیان کی کہ آپ صلی اللہ علیہ وسلم نے دو رکعات نماز پڑھائی اور یہ کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کو جشیشہ (خزیر سے ملتے جلتے کھانے)کے لیے روک لیا جو ہم نے آپ کے لیے بنایا تھا۔انھوں (اوزاعی)نےاس کے بعد یونس اور معمر والا اضافہ بیان نہیں کیا"}],[1435,"اسحاق بن عبداللہ بن ابی طلحہ نےسیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ ان کی نانی ملیکہ رضی اللہ تعالیٰ عنہا نے رسول اللہ صلی اللہ علیہ وسلم کو کھانے پر بلایا جو انھوں نے تیار کیا تھا ۔ آپ صلی اللہ علیہ وسلم نے اس میں سے ( کچھ ) تناول کیا ، پھر فرمایا : ’’کھڑے ہو جاؤ میں تمھاری ( برکت کی ) خاطر نماز پڑھوں ۔ ‘‘ انس بن مالک رضی اللہ عنہ نے کہا : میں کھڑا ہوا اور اپنی ایک چٹائی کی طرف بڑھا جو لمبا عرصہ استعمال ہونے کی وجہ سے کالی ہو چکی تھی ، میں نے ( اسے صاف کرنے کےلیے ) اس پر پانی بہایا تو رسول اللہ صلی اللہ علیہ وسلم اس پر کھڑے ہوئے ، میں اور ( وہاں موجود ایک ) یتیم بچے نے آپ کے پیچھے صف بنائی ، بوڑھی خاتون ہمارے پیچھے ( کھڑی ) ہوگئیں ۔ رسول اللہ صلی اللہ علیہ وسلم نے ہمارے ( حصول برکت کے ) لیے دو رکعت نماز پڑھی ، پھر تشریف لے گئے ۔","",{"u2":"اسحاق بن عبداللہ بن ابی طلحہ نےحضرت انس بن مالک رضی اللہ عنہ سے روایت کی کہ ان کی نانی ملیکہ رضی اللہ تعالیٰ عنہا نے رسول اللہ صلی اللہ علیہ وسلم کوکھانے پر بلایا جو انھوں نے تیار کیا تھا۔ آپ صلی اللہ علیہ وسلم نے اس میں سے (کچھ)تناول کیا، پھر فرمایا:’’کھڑے ہو جاؤ میں تمھاری (برکت کی)خاطر نماز پڑھوں۔ ‘‘ انس بن مالک رضی اللہ عنہ نے کہا: میں کھڑا ہوا اور اپنی ایک چٹائی کی طرف بڑھا جو لمبا عرصہ استعمال ہونےکی وجہ سے کالی ہو چکی تھی، میں نے (اسےصاف کرنے کےلیے)اس پر پانی بہایا تو رسول اللہ صلی اللہ علیہ وسلم اس پر کھڑے ہوئے، میں اور (وہاں موجود ایک)یتیم بچے نے آپ کے پیچھے صف بنائی، بوڑھی خاتون ہمارے پیچھے (کھڑی)ہوگئیں۔ رسول اللہ صلی اللہ علیہ وسلم نے ہمارے (حصول برکت کے)لیے دو رکعت نماز پڑھی، پھر تشریف لے گئے۔"}],[1436,"ابو التیاح نےسیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم تمام انسانوں میں سب سے زیادہ خوبصورت اخلاق کے مالک تھے ۔ بسا اوقات آپ ہمارے گھر میں ہوتے اور نماز کا وقت ہو جاتا ، پھر آپ اس چٹائی کے بارے میں حکم دیتے جو آپ کے نیچے ہوتی ، اسے جھاڑا جاتا ، پھر اس پر پانی چھڑکا جاتا ، پھر آپ امامت فرماتے اور ہم آپ کے پیچھے کھڑے ہوتے اور آپ ہمیں نماز پڑھاتے ۔ کہا : ان کی چٹائی کجھور کے پتوں کی ہوتی تھی ۔","",{"u2":"ابو التیاح نےحضرت انس بن مالک رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم تمام انسانوں میں سب سے زیادہ خوبصورت اخلاق کے مالک تھے۔ بسا اوقات آپ ہمارے گھر میں ہوتے اور نماز کا وقت ہو جاتا،پھر آپ اس چٹائی کے بارے میں حکم دیتے جو آپ کے نیچے ہوتی، اسے جھاڑا جاتا، پھر اس پر پانی چھڑکا جاتا، پھر آپ امامت فرماتے اور ہم آپ کے پیچھے کھڑے ہوتے اور آپ ہمیں نماز پڑھاتے۔ کہا: ان کی چٹائی کجھور کے پتوں کی ہوتی تھی۔"}],[1437,"سیدنا انس رضی اللہ عنہ سےروایت کی ، کہا : نبی صلی اللہ علیہ وسلم ہمارے ہاں تشریف لائے وہاں میرے ، میری والدہ اور میری خالہ ام حرام کے سوا کوئی نہ تھا ، آپ نے فرمایا : ‘‘ کھڑے ہو جاؤ میں تمھیں نماز پڑھا دوں ۔ ٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗ’ ( فرض ) نماز کے وقت کے بغیر ، آپ نے ہمیں نماز پڑھائی ۔ ایک آدمی نے ثابت سے پوچھا : آپ صلی اللہ علیہ وسلم نے انس رضی اللہ عنہ کو اپنی کس جانب کھڑا کیا تھا؟ انھوں نے کہا : آپ صلی اللہ علیہ وسلم نے انہیں اپنے دائیں ہاتھ کھڑا کیا تھا ۔ پھر آپ نے ہمارے ، سب گھر والوں کے لئے دنیا اور آخرت کی تمام بھلائیوں کی دعا فرمائی ، اس کے بعد میری ماں کہنے لگی : اللہ کے رسول! ( یہ ) آپ کا چھوٹا سا خدمت گزار ہے ، اللہ سے اس کے لئے ( خصوصی ) دعا کریں ۔ کہا : آپ نے میرے لئےہر بھلائی کی دعا کی اور میرے لئے آپ نے جو دعا کی اس کے آخر میں یہ تھا ، آپ نے فرمایا : ‘‘ اے اللہ!اس کا مال اور اس کی اولاد زیادہ کر اور اس کے لئے ان میں برکت ڈال دے ۔ ’’","",{"u2":"حضرت انس رضی اللہ عنہ سےروایت کی،کہا:نبی صلی اللہ علیہ وسلم ہمارے ہاں تشریف لائے وہاں میرے،میری والدہ اور میری خالہ ام حرام کے سوا کوئی نہ تھا،آپ نے فرمایا:‘‘کھڑے ہو جاؤ میں تمھیں نماز پڑھا دوں۔ٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗٗ’(فرض) نماز کے وقت کے بغیر، آپ نے ہمیں نماز پڑھائی۔ایک آدمی نے ثابت سے پوچھا:آپ صلی اللہ علیہ وسلم نے انس رضی اللہ عنہ کو اپنی کس جانب کھڑا کیا تھا؟ انھوں نے کہا:آپ صلی اللہ علیہ وسلم نے انہیں اپنے دائیں ہاتھ کھڑا کیا تھا۔پھر آپ نے ہمارے،سب گھر والوں کے لئے دنیا اور آخرت کی تمام بھلائیوں کی دعا فرمائی،اس کے بعد میری ماں کہنے لگی:اللہ کے رسول! (یہ)آپ کا چھوٹا سا خدمت گزار ہے،اللہ سے اس کے لئے (خصوصی) دعا کریں۔\nکہا:آپ نے میرے لئےہر بھلائی کی دعا کی اور میرے لئے آپ نے جو دعا کی اس کے آخر میں یہ تھا،آپ نے فرمایا:‘‘اے اللہ!اس کا مال اور اس کی اولاد زیادہ کر اور اس کے لئے ان میں برکت ڈال دے۔’’"}],[1438,"معاذ عنبری نے کہا : ہمیں شعبہ نے عبداللہ بن مختار سے حدیث سنائی ، انھوں نے موسیٰ بن انس سے سنا ، وہ سیدنا انس بن مالک رضی اللہ عنہ سے حدیث بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے انھیں اور ان کی والدہ یا ان کی خالہ کو نماز پڑھائی ، کہا : آپ نے مجھے اپنی دائیں جانب اور عورت کو ہمارے پیچھے کھڑا کیا ۔","",{"u2":"معاذ عنبری نے کہا: ہمیں شعبہ نے عبداللہ بن مختار سے حدیث سنائی،انھوں نے موسیٰ بن انس سے سنا، وہ حضرت انس بن مالک رضی اللہ عنہ سے حدیث بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے انھیں اور ان کی والدہ یا ان کی خالہ کو نماز پڑھائی،کہا:آپ نے مجھے اپنی دائیں جانب اور عورت کو ہمارے پیچھے کھڑا کیا۔"}],[1439,"محمد بن جعفر اور عبدالرحمان بن مہدی نے شعبہ سے اسی سند کے ساتھ یہی حریث بیان کی","",{"u2":"محمد بن جعفر اور عبدالرحمان بن مہدی نے شعبہ سے اسی سند کے ساتھ یہی حریث بیان کی"}],[1440,"عبداللہ بن شداد سے روایت ہے ، کہا : مجھے نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہ رضی اللہ عنہا نے حدیث بیان کی ، فرمایا : ٰ رسول اللہ صلی اللہ علیہ وسلم نماز پڑھتے اور میں آپ کے سامنے ہوتی اور اکثر ایسا ہوتا کہ جب آپ سجدہ کرتے تو آپ کا کپڑا مجھے لگتا اور آپ ( کھجور کے پتوں اور دھاگوں سے بنی ہوئی ) ایک جائے نماز پر نماز پڑھتے تھے ۔","",{"u2":"عبداللہ بن شداد سے روایت ہے، کہا:مجھے نبی صلی اللہ علیہ وسلم کی زوجہ حضرت میمونہ رضی اللہ عنہا نے حدیث بیان کی،فرمایا:ٰ رسول اللہ صلی اللہ علیہ وسلم نماز پڑھتے اور میں آپ کے سامنے ہوتی اور اکثر ایسا ہوتا کہ جب آپ سجدہ کرتے تو آپ کا کپڑا مجھے لگتا اور آپ(کھجور کے پتوں اور دھاگوں سے بنی ہوئی) ایک جائے نماز پر نماز پڑھتے تھے۔"}],[1441,"سیدنا جابر رضی اللہ عنہ سے روایت ہے ، کہا : ہمیں سیدنا ابو سعید خرری رضی اللہ عنہ نے حدیث سنائی کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر ہوئے تو دیکھا کہ آپ ایک چٹائی پر نماز پڑھ رہے ہیں ، اسی پر سجدہ کر رہے ہیں ۔","",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے، کہا: ہمیں حضرت ابو سعید خرری رضی اللہ عنہ نے حدیث سنائی کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر ہوئے تو دیکھا کہ آپ ایک چٹائی پر نماز پڑھ رہے ہیں،اسی پر سجدہ کر رہے ہیں۔"}],[1442,"ابو معاویہ نے اعمش سے حدیث بیان کی ، انھوں نے ابو صالح سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ آدمی کی باجماعت ( ادا کی گئی ) نماز اس کی گھر میں یا بازار میں پڑھی ہوئی نماز کی نسبت بیس سے زیادہ درجے بڑھ کر ہے اور وہ یوں کہ جب ان میں سے کوئی وضو کرتا ہے اور اچھی طرح وضو کرتا ہے ، پھر مسجد آتا ہے ، اسے نماز ہی نے اٹھایا ہے اور نماز کے علاوہ کچھ نہیں چاہتا ۔ تو وہ کوئی قدم نہیں اٹھاتا مگر اس کے سبب سے اس کا درجہ بلند کر دیا جاتا ہے اور اس کا ایک گناہ مٹا دیا جاتا ہے ، یہاں تک کہ مسجد میں داخل ہو جاتا ہے ، پھر جب مسجد میں داخل ہو جاتا ہے تو جب تک نماز اسے روکے رکھتی ہے وہ نماز ہی میں ہوتا ہے ( اس کے انتظار کا وقت نماز میں شمار ہوتا ہے ) اور تم میں سے کوئی شخص جب تک اس جگہ رہتا ہے جہاں اس نے نماز پڑھی ہے تو فرشتے اس کے حق میں دعا کرتے رہتے ہیں ۔ وہ کہتے ہیں : ‘‘ اے اللہ اس پر رحم فرما !اے اللہ ! اس کی توبہ قبول فرما! جب تک وہ اس جگہ ( پر کسی کو ) تکلیف نہیں پہنچاتا اور جب تک وہ اس جگہ بے وضو نہیں ہوتا ۔ ’’","",{"u2":"ابو معاویہ نے اعمش سے حدیث بیان کی، انھوں نے ابو صالح سے اور انھوں نے حضرت ابو ہریرہ رضی اللہ عنہ سے روایت کی،کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘آدمی کی باجماعت (ادا کی گئی) نماز اس کی گھر میں یا بازار میں پڑھی ہوئی نماز کی نسبت بیس سے زیادہ درجے بڑھ کر ہے اور وہ یوں کہ جب ان میں سے کوئی وضو کرتا ہے اور اچھی طرح وضو کرتا ہے،پھر مسجد آتا ہے، اسے نماز ہی نے اٹھایا ہے اور نماز کے علاوہ کچھ نہیں چاہتا۔ تو وہ کوئی قدم نہیں اٹھاتا مگر اس کے سبب سے اس کا درجہ بلند کر دیا جاتا ہے اور اس کا ایک گناہ مٹا دیا جاتا ہے،یہاں تک کہ مسجد میں داخل ہو جاتا ہے، پھر جب مسجد میں داخل ہو جاتا ہے تو جب تک نماز اسے روکے رکھتی ہے وہ نماز ہی میں ہوتا ہے (اس کے انتظار کا وقت نماز میں شمار ہوتا ہے) اور تم میں سے کوئی شخص جب تک اس جگہ رہتا ہے جہاں اس نے نماز پڑھی ہے تو فرشتے اس کے حق میں دعا کرتے رہتے ہیں۔ وہ کہتے ہیں:‘‘اے اللہ اس پر رحم فرما!اے اللہ! اس کی توبہ قبول فرما! جب تک وہ اس جگہ (پر کسی کو)تکلیف نہیں پہنچاتا اور جب تک وہ اس جگہ بے وضو نہیں ہوتا۔’’"}],[1443,"عبثر رضی اللہ عنہ ، اسماعیل بن زکریا اور شعبہ ، سب نے اعمش کی اسی سند کے ساتھ اس کے ہم معنی روایت بیان کی","",{"u2":"عبثر علیہ السلام، اسماعیل بن زکریا اور شعبہ، سب نے اعمش کی اسی سند کے ساتھ اس کے ہم معنی روایت بیان کی"}],[1444,"ابن سیرین نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ تم میں سے کوئی شخص جب تک اپنی ( نماز پڑھنے کی ) جگہ پر بیٹھا رہتا ہے ، فرشتے اس کے حق میں دعا کرتے رہتے ہیں ، کہتے ہیں : اے اللہ! اسے بخش دے! اے اللہ اس پر رحم فرما! جب تک وہ بے وضو نہیں ہوتا ، نیز جب تک تم میں سے کسی شخض کو نماز روکے رکھتی ہے ، وہ نماز ہی میں ہوتا ہے ۔ ’’","",{"u2":"ابن سیرین نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی،کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘تم میں سے کوئی شخص جب تک اپنی (نماز پڑھنے کی)جگہ پر بیٹھا رہتا ہے، فرشتے اس کے حق میں دعا کرتے رہتے ہیں، کہتے ہیں: اے اللہ! اسے بخش دے! اے اللہ اس پر رحم فرما! جب تک وہ بے وضو نہیں ہوتا، نیز جب تک تم میں سے کسی شخض کو نماز روکے رکھتی ہے، وہ نماز ہی میں ہوتا ہے۔’’"}],[1445,"ابو رافع نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ بندہ مسلسل نماز ہی میں ہوتا ہے جب تک وہ نماز کی جگہ پر نماز کے انتظار میں رہتا ہے اور فرشتے کہتے رہتے ہیں : اے اللہ! اسے معاف فرما!اے اللہ!اس پررحم فرما! یہاں تک کہ وہ چلا جاتا ہے یا بے وضو ہو جاتا ہے ۔ ‘‘ ( ابو رافع کہتے ہیں : ) میں نے ابوہریرہ رضی اللہ عنہ سے پوچھا : يحدث كا مطلب کیا ہے؟ انھوں نے کہا : آواز کے بغیر یا آواز کے ساتھ ہوا خارج کر دے ۔","",{"u2":"ابو رافع نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘بندہ مسلسل نماز ہی میں ہوتا ہے جب تک وہ نماز کی جگہ پر نماز کے انتظار میں رہتا ہے اور فرشتے کہتے رہتے ہیں: اے اللہ! اسے معاف فرما!اے اللہ!اس پررحم فرما! یہاں تک کہ وہ چلا جاتا ہے یا بے وضو ہو جاتا ہے۔‘‘(ابو رافع کہتے ہیں:) میں نے ابوہریرہ رضی اللہ عنہ سے پوچھا: یحدث کا مطلب کیا ہے؟ انھوں نے کہا: آواز کے بغیر یا آواز کے ساتھ ہوا خارج کر دے۔"}],[1446,"ابو زناد نے اعرج سے اور انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ جب تک تم میں سے کسی کو نماز روکے رکھتی ہے وہ مسلسل نماز میں ہوتا ہے ، اسے گھر کی طرف لوٹنے سے نماز کے علاوہ اور کسی چیز نے نہیں روکا ہوتا ۔ ’’","",{"u2":"ابو زناد نے اعرج سے اور انھوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘جب تک تم میں سے کسی کو نماز روکے رکھتی ہے وہ مسلسل نماز میں ہوتا ہے،اسے گھر کی طرف لوٹنے سے نماز کے علاوہ اور کسی چیز نے نہیں روکا ہوتا۔’’"}],[1447,"ابن شہاب نے ( عبدالرحمان ) بن ہرمز ( اعرج ) سے اور انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ تم میں سے کوئی شخص جتنی دیر نماز کے انتظار میں بیٹھا ہے نماز ہی میں رہتا ہے جب تک بے وضو نہ ہو جائے ۔ فرشتے اس کے لئے دعا کرتے رہتے : اے اللہ ! اسے معاف فرما! اے اللہ!اس پؓر رحم فرما ۔ ’’","",{"u2":"ابن شہاب نے (عبدالرحمان) بن ہرمز (اعرج)سے اور انھوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘تم میں سے کوئی شخص جتنی دیر نماز کے انتظار میں بیٹھا ہے نماز ہی میں رہتا ہے جب تک بے وضو نہ ہو جائے۔فرشتے اس کے لئے دعا کرتے رہتے: اے اللہ! اسے معاف فرما! اے اللہ!اس پ رضی اللہ عنہ ر رحم فرما۔’’"}],[1448,"ہمام بن منبہ نے سیدنا ابوہریرہ رضی اللہ عنہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مطابق روایت کی ۔","",{"u2":"ہمام بن منبہ نے حضرت ابوہریرہ رضی اللہ عنہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مطابق روایت کی۔"}],[1449,"عبداللہ بن براداشعری اور ابو کریب دونوں نے کہا : ہم سے ابو اسامہ نے برید سے حدیث بیان کی ، انھوں نے ابوبردہ سے اور انھوں نے سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ نماز میں سب سے زیادہ ثواب اس کا ہے جو اس کے لیے زیادہ دور سے چل کر آتا ہے ۔ پھر ( اس کے بعد ) جو ان میں سے سب سے زیادہ دور سے چل کر آتا ہے ۔ اور جو آدمی نماز کا انتظار کرتا ہے تاکہ اسے امام کے ساتھ ادا کرے ، اجر میں اس سے بہت بڑھ کر ہے جو نماز پڑھتا ہے ، پھر سو جاتا ہے ۔ ’’ ابو کریب کی روایت میں ہے : ‘‘ یہاں تک کہ وہ اسے امام کے ساتھ جماعت میں ادا کرے ۔ ’’","",{"u2":"عبداللہ بن براداشعری اور ابو کریب دونوں نے کہا: ہم سے ابو اسامہ نے برید سے حدیث بیان کی، انھوں نے ابوبردہ سے اور انھوں نے حضرت ابو موسیٰ رضی اللہ عنہ سے روایت کی، کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘ نماز میں سب سے زیادہ ثواب اس کا ہے جو اس کے لیے زیادہ دور سے چل کر آتا ہے۔پھر (اس کے بعد)جو ان میں سے سب سے زیادہ دور سے چل کر آتا ہے۔ اور جوآدمی نماز کا انتظار کرتا ہے تاکہ اسے امام کے ساتھ ادا کرے، اجر میں اس سے بہت بڑھ کر ہے جو نماز پڑھتا ہے،پھر سو جاتا ہے۔’’\nابو کریب کی روایت میں ہے: ‘‘یہاں تک کہ وہ اسے امام کے ساتھ جماعت میں ادا کرے۔’’"}],[1450,"عبثر نے ہمیں خبر دی ، انھوں نے سلیمان تیمی سے ، انھوں نے ابوعثمان نہدی سے اور انھوں نے سیدنا ابی بن کعب رضی اللہ عنہ سے روایت کی ، کہا : ایک آدمی تھا ، میرے علم میں کوئی اور آدمی اس کی نسبت مسجد سے زیادہ فاصلے پر نہیں رہتا تھا اور اس کی کوئی نماز نہیں چوکتی تھی ، اس سے کہا گیا-یا میں نے ( اس سے ) کہا- : اگر آپ گدھا خرید لیں کہ ( رات کی ) تاریکی اور ( دوپہر کی ) گرمی میں آپ اس پر سوار ہو جایا کریں ۔ اس نے جواب دیا : مجھے یہ بات پسند نہیں ہے کہ میرا گھر مسجد کے پڑوس میں ہو ، میں چاہتا ہوں میرا مسجد تک چل کر جانا اور جب میں گھر والوں کی طرف لوٹوں تو میرا لٹنا میرے لئے لکھا جائے ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ اللہ تعالیٰ نے یہ سب کچھ تمھارے لئے اکٹھا کر دیا ہے ۔ ’’","",{"u2":"عبثر نے ہمیں خبر دی،انھوں نے سلیمان تیمی سے،انھوں نے ابوعثمان نہدی سے اور انھوں نے حضرت ابی بن کعب رضی اللہ عنہ سے روایت کی، کہا: ایک آدمی تھا،میرے علم میں کوئی اور آدمی اس کی نسبت مسجد سے زیادہ فاصلے پر نہیں رہتا تھا اور اس کی کوئی نماز نہیں چوکتی تھی، اس سے کہا گیا-یا میں نے (اس سے)کہا-:اگر آپ گدھا خرید لیں کہ(رات کی) تاریکی اور (دوپہر کی) گرمی میں آپ اس پر سوار ہو جایا کریں۔ اس نے جواب دیا: مجھے یہ بات پسند نہیں ہے کہ میرا گھر مسجد کے پڑوس میں ہو، میں چاہتا ہوں میرا مسجد تک چل کر جانا اور جب میں گھر والوں کی طرف لوٹوں تو میرا لٹنا میرے لئے لکھا جائے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘اللہ تعالیٰ نے یہ سب کچھ تمھارے لئے اکٹھا کر دیا ہے۔’’"}],[1451,"عتمر بن سلیمان اور جریر دونوں نے تیمی سے اسی سند کے ساتھ اسی کے مطابق روایت کی ۔","",{"u2":"عتمر بن سلیمان اور جریر دونوں نے تیمی سے اسی سند کے ساتھ اسی کے مطابق روایت کی۔"}],[1452,"عباد بن عباد نے ہمیں حدیث سنائی ، کہا : ہمیں عاصم نے ابو عثمان سے حدیث سنائی ، کہا : انصار میں ایک آدمی تھا ، اس کا گھر ، مدینہ میں سب سے دور ( واقع ) تھا اور اس کی کوئی نماز رسول اللہ صلی اللہ علیہ وسلم کی اقتدا میں پڑھنے سے چوکتی نہیں تھی ، ہم نے اس کے لئے ہمدردی محسوس کی تو میں نے اسے کہا : جناب ! اگر آپ ایک گدھا خرید لیں جو آپ کو گرمی اور زمین کے ( زہریلے ) کیڑوں سے بچائے ( تو کتنا اچھا ہو! ) اس نے کہا : مکر اللہ کی قسم! جھے یہ نہیں کہ میرا گھر ( خیمے کی طرح ) کنابوں کے ذریعے سے محمد صلی اللہ علیہ وسلم کے گھر سے بندھا ہوا ہو ۔ مجھے اس کی یہ بات بہت گراں گزری حتی کہ میں اسی کیقیت میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ کو اس بات کی خبر دی ۔ آپ نے اسے بلوایا تو اس نے آپ کو بھی وہی جواب دیا اور آپ کو بتایا کہ وہ آنے جانے پر اجر کی امید رکھتا ہے ۔ تو نبی رضی اللہ عنہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ تمھیں یقینا وہی اجر ملے گا جسے تم حاصل کرنا چاہتے ہو ۔ ’’","",{"u2":"عباد بن عباد نے ہمیں حدیث سنائی،کہا: ہمیں عاصم نے ابو عثمان سے حدیث سنائی،کہا: انصار میں ایک آدمی تھا،اس کا گھر،مدینہ میں سب سے دور (واقع) تھا اور اس کی کوئی نماز رسول اللہ صلی اللہ علیہ وسلم کی اقتدا میں پڑھنے سے چوکتی نہیں تھی، ہم نے اس کے لئے ہمدردی محسوس کی تو میں نے اسے کہا:جناب! اگر آپ ایک گدھا خرید لیں جو آپ کو گرمی اور زمین کے(زہریلے)کیڑوں سے بچائے(تو کتنا اچھا ہو!) اس نے کہا:مکر اللہ کی قسم! جھے یہ نہیں کہ میرا گھر(خیمے کی طرح)کنابوں کے ذریعے سے محمد صلی اللہ علیہ وسلم کے گھر سے بندھا ہوا ہو۔ مجھے اس کی یہ بات بہت گراں گزری حتی کہ میں اسی کیقیت میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ کو اس بات کی خبر دی۔ آپ نے اسے بلوایا تو اس نے آپ کو بھی وہی جواب دیا اور آپ کو بتایا کہ وہ آنے جانے پر اجر کی امید رکھتا ہے۔ تو نبی رضی اللہ عنہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘تمھیں یقینا وہی اجر ملے گا جسے تم حاصل کرنا چاہتے ہو۔’’"}],[1453,"ابن عینیہ اور وکیع نے اپنے والد کے حوالے سے عاصم سے اسی سند کے ساتھ اسی طرح روایت کی ۔","",{"u2":"ابن عینیہ اور وکیع نے اپنے والد کے حوالے سے عاصم سے اسی سند کے ساتھ اسی طرح روایت کی۔"}],[1454,"ابوزبیر نے ہمیں حدیث سنائی ، کہا : میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، کہا : ہمارے گھر مسجد سے دور واقع تھے ، ہم نے چاہا کہ ہم اپنے گھروں کو فروخت کر کے مسجد کے قریب آجائیں تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں روک دیا اور فرمایا : ‘‘ تمھارے لئے ہر قدم کے بدلے میں ایک درجہ ہے ۔ ’’","",{"u2":"ابوزبیر نے ہمیں حدیث سنائی،کہا: میں نے حضرت جابر بن عبداللہ رضی اللہ عنہ سے سنا،کہا: ہمارے گھر مسجد سے دور واقع تھے، ہم نے چاہا کہ ہم اپنے گھروں کو فروخت کر کے مسجد کے قریب آجائیں تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں روک دیا اور فرمایا: ‘‘تمھارے لئے ہر قدم کے بدلے میں ایک درجہ ہے۔’’"}],[1455,"جریری نے ابونضرہ سے اور انھوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہا سے روایت کی ، کہا : ( رسول اللہ صلی اللہ علیہ وسلم کی ) مسجد کے ارد گرد کی جگہیں خالی ہوئیں تو ( ان کے قبیلے ) بنو سلمہ کے لوگوں نے ارادہ کیا کہ مسجد کے قریب منتقل ہو جائیں ، رسول اللہ صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے ان سے کہا : ’’مجھے خبر پہنچی ہے کہ تم مسجد کے قریب منتقل ہونا چاہتے ہو ۔ ‘‘ انھوں نے عرض کی : جی ہاں ، اے اللہ کے رسول! ہم یہی چاہتے ہیں ۔ تو آپ نے فرمایا : ‘‘ بنو سلمہ! اپنے گھروں میں رہو ، تمھارے قدموں کے نشان لکھے جاتے ہیں ، ( پھر فرمایا : ) اپنے گھروں ہی میں رہو ، تمھارے قدموں کے نشان لکھے جاتے ہیں ۔ ’’","",{"u2":"جریری نے ابونضرہ سے اور انھوں نے حضرت جابر بن عبداللہ رضی اللہ عنہا سے روایت کی، کہا: (رسول اللہ صلی اللہ علیہ وسلم کی) مسجد کے ارد گرد کی جگہیں خالی ہوئیں تو (ان کے قبیلے) بنو سلمہ کے لوگوں نے ارادہ کیا کہ مسجد کے قریب منتقل ہو جائیں،رسول اللہ صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے ان سے کہا: ’’مجھے خبر پہنچی ہے کہ تم مسجد کے قریب منتقل ہونا چاہتے ہو۔‘‘انھوں نے عرض کی:جی ہاں،اے اللہ کے رسول! ہم یہی چاہتے ہیں۔ تو آپ نے فرمایا: ‘‘بنو سلمہ! اپنے گھروں میں رہو، تمھارے قدموں کے نشان لکھے جاتے ہیں،(پھر فرمایا:)اپنے گھروں ہی میں رہو،تمھارے قدموں کے نشان لکھے جاتے ہیں۔’’"}],[1456,"کہمس نے ابو نضرہ سے اور انھوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہا سے روایت کی ، کہا : بنو سلمہ نے مسجد کے قریب منتقل ہونے کا ارادہ کیا ، کہا : اور ( مسجد کے قریب ) جگہیں ( بھی ) خالی تھیں ۔ نبی اکرم صلی اللہ علیہ وسلم کو یہ خبر پہنچی تو آپ نے فرمایا : ‘‘ اے بنو سلمہ!اپنے گھروں میں رہو ، تمھارے قدموں کے نشان لکھے جاتے ہیں ۔ ’’ تو انھوں نے کہا : ( اس کے بعد ) ہمیں یہ بات اچھی ( بھی ) نہ لگتی کہ ہم منتقل ہو چکے ہو تے ۔","",{"u2":"کہمس نے ابو نضرہ سے اور انھوں نے حضرت جابر بن عبداللہ رضی اللہ عنہا سے روایت کی،کہا: بنو سلمہ نے مسجد کے قریب منتقل ہونے کا ارادہ کیا،کہا: اور (مسجد کے قریب) جگہیں (بھی)خالی تھیں۔نبی اکرم صلی اللہ علیہ وسلم کو یہ خبر پہنچی تو آپ نے فرمایا: ‘‘اے بنو سلمہ!اپنے گھروں میں رہو،تمھارے قدموں کے نشان لکھے جاتے ہیں۔’’ تو انھوں نے کہا: (اس کے بعد) ہمیں یہ بات اچھی (بھی)نہ لگتی کہ ہم منتقل ہو چکے ہو تے۔"}],[1457,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ جس نے اپنے گھر میں وضو کیا ، پھر اللہ کے گھروں میں سے اس کے کسی گھر کی طرف چل کر گیا تاکہ اللہ کے فرضوں میں سے ایک فریضے کو ادا کرے تو اس کے دونوں قدم ( یہ کرتے ہیں کہ ) ان میں سے ایک گناہ نٹاتا ہے اور دوسرا درجہ بلند کرتا ہے","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے،کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘جس نے اپنے گھر میں وضو کیا،پھر اللہ کے گھروں میں سے اس کے کسی گھر کی طرف چل کر گیا تاکہ اللہ کے فرضوں میں سے ایک فریضے کو ادا کرے تو اس کے دونوں قدم (یہ کرتے ہیں کہ) ان میں سے ایک گناہ نٹاتا ہے اور دوسرا درجہ بلند کرتا ہے"}],[1458,"لیث اور بکر دونوں نے ہاد سے ، انھوں نے محمد بن ابراہیم سے ، انھوں نے ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا-اور بکر کی روایت میں ہے کہ انھوں ( ابوہریرہ رضی اللہ عنہ ) نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آ پ نے فرمایا- ‘‘ تم کیا سمجھتے ہو اگر تم میں سے کسی کے گھر کے سامنے نہر ہو جس سے وہ ہر روز پانچ مرتبہ نہاتا ہو ، کیا اس ( کے جسم ) کا کوئی میا کچیل باقی رہ جائے گا؟’’ صحابہ نے عرض کی : اس کا کوئی میل کچیل باقی نہیں رہے گا ۔ آپ نے فرمایا یہی پانچ نمازوں کی مثال ہے ، اللہ تعالیٰ ان کے ذریعے سے گناہوں کو صاف کر دیتا ہے ۔ ’’","",{"u2":"لیث اور بکر دونوں نے ہاد سے،انھوں نے محمد بن ابراہیم سے، انھوں نے ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا-اور بکر کی روایت میں ہے کہ انھوں (ابوہریرہ رضی اللہ عنہ)نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آ پ نے فرمایا-‘‘تم کیا سمجھتے ہو اگر تم میں سے کسی کے گھر کے سامنے نہر ہو جس سے وہ ہر روز پانچ مرتبہ نہاتا ہو،کیا اس (کے جسم) کا کوئی میا کچیل باقی رہ جائے گا؟’’ صحابہ نے عرض کی: اس کا کوئی میل کچیل باقی نہیں رہے گا۔ آپ نے فرمایا یہی پانچ نمازوں کی مثال ہے،اللہ تعالیٰ ان کے ذریعے سے گناہوں کو صاف کر دیتا ہے۔’’"}],[1459,"اعمش نے ابو سفیان ( طلحہ بن نافع ) سے ، انھوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ رضی اللہ عنہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ پانچ نمازوں کی مثال تم میں سے کسی ایک کے دروازے پر چلتی ہویئ بہت بڑی نہر کی سی ہے ، وہ اس میں سے روزانہ پانچ دفعہ غسل کرتا ہو ۔ ’’ ( اعمش نے ابوسفیان کی بجائے حسن کے حوالے سے روایت کرتے ہوئے ) کہا : حسن نے کہا : یہ غسل اس کے جسم پر کوئی میل کچیل نہیں چھوڑے گا ۔","",{"u2":"اعمش نے ابو سفیان (طلحہ بن نافع) سے، انھوں نے حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ رضی اللہ عنہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘پانچ نمازوں کی مثال تم میں سے کسی ایک کے دروازے پر چلتی ہویئ بہت بڑی نہر کی سی ہے، وہ اس میں سے روزانہ پانچ دفعہ غسل کرتا ہو۔’’ (اعمش نے ابوسفیان کی بجائے حسن کے حوالے سے روایت کرتے ہوئے) کہا: حسن نے کہا:یہ غسل اس کے جسم پر کوئی میل کچیل نہیں چھوڑے گا۔"}],[1460,"سیدنا ابوہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی : ‘‘ جو شخص دن کے پہلے حصے میں یا دن کے دوسرے حصے میں مسجد کی طرف گیا اللہ تعالیٰ ( ہر دفعہ آنے پر ) اس کے لئے جنت میں میزبانی کا انتظام فرماتا ہے ، جب بھی وہ ( آئے ) صبح کو آئے یا شام کو آئے ۔ ’’","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی: ‘‘جو شخص دن کے پہلے حصے میں یا دن کے دوسرے حصے میں مسجد کی طرف گیا اللہ تعالیٰ (ہر دفعہ آنے پر)اس کے لئے جنت میں میزبانی کا انتظام فرماتا ہے،جب بھی وہ (آئے)صبح کو آئے یا شام کو آئے۔’’"}],[1461,"ابو حثیمہ نے سماک بن حرب سے روایت کرتے ہوئے خبر دی ، کہا : میں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے کہا : کیا آپ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مجالس میں شریک ہوتے تھے؟ کہا : ہاں! بہت ۔ آپ جس جگہ صبح یا دن کے ابتدائی حصے کی نماز ادا فرماتے ، سورج طلوع ہونے تک وہاں سے نہ اٹھتے ۔ جب سورج طلوع ہو جاتا تو اٹھ کھڑے ہوتے ، لوگ دور جاہلیت میں کیے کاموں کے متعلق باتیں کرتے اور ہنستے تھے اور آپ ( بھی ان کی باتیں سن کر ) مسکراتے تھے ۔","",{"u2":"ابو حثیمہ نے سماک بن حرب سے روایت کرتے ہوئے خبر دی، کہا: میں نے حضرت جابر بن سمرہ رضی اللہ عنہ سے کہا: کیا آپ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مجالس میں شریک ہوتے تھے؟ کہا: ہاں! بہت۔ آپ جس جگہ صبح یا دن کے ابتدائی حصے کی نماز ادا فرماتے، سورج طلوع ہونے تک وہاں سے نہ اٹھتے۔جب سورج طلوع ہو جاتا تو اٹھ کھڑے ہوتے، لوگ دور جاہلیت میں کیے کاموں کے متعلق باتیں کرتے اور ہنستے تھے اور آپ (بھی ان کی باتیں سن کر) مسکراتے تھے۔"}],[1462,"سفیان اور زکریا دونوں نے سماک سے اور انھوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم جب فجر پڑھتے تھے تو اپنی نماز کی جگہ پر بیٹھے رہتے حتی کہ سورج اچھی طرح نکل آتا ۔","",{"u2":"سفیان اور زکریا دونوں نے سماک سے اور انھوں نے حضرت جابر بن سمرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم جب فجر پڑھتے تھے تو اپنی نماز کی جگہ پر بیٹھے رہتے حتی کہ سورج اچھی طرح نکل آتا۔"}],[1463,"ابواحوص اور شعبہ دونوں نے سماک سے اسی سند کے ساتھ یہی روایت بیان کی لیکن حسنا ‘‘ اچھی طرح’’ ( سورج نکل آتا ) نہیں کہا","",{"u2":"ابواحوص اور شعبہ دونوں نے سماک سے اسی سند کے ساتھ یہی روایت بیان کی لیکن حسنا ‘‘اچھی طرح’’ (سورج نکل آتا) نہیں کہا"}],[1464,"سیدنا ابوہریرہ رضی اللہ عنہٗ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘شہروں میں پیاری جگہ اللہ كے نزدیك مسجدیں ہیں اور ‘ اللہ کے نزدیک ( انسانی ) آبادیوں کا سب سے ناپسندیدہ حصہ ان کے بازار ہیں ۔ ’’","",{"u2":") حضرت ابوہریرہ رضی اللہ عنہٗ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘اللہ کے نزدیک (انسانی) آبادیوں کا سب سے ناپسندیدہ حصہ ان کے بازار ہیں۔’’"}],[1465,"ابوعوانہ نے ہمیں قتادہ سے حدیث سنائی ، انھوں نے ابو نضرہ سے اور انھوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ جب ( نماز پڑھنے والے ) تین ہوں تو ان میں سے ایک ان کی امامت کرائے اور ان میں سے امامت کا زیادہ حقدار وہ ہے جو ان میں سے زیادہ ( قرآن ) پڑھا ہو ۔ ’’","",{"u2":"ابوعوانہ نے ہمیں قتادہ سے حدیث سنائی، انھوں نے ابو نضرہ سے اور انھوں نے حضرت ابوسعید خدری رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘ جب (نماز پڑھنے والے) تین ہوں تو ان میں سے ایک ان کی امامت کرائے اور ان میں سے امامت کا زیادہ حقدار وہ ہے جو ان میں سے زیادہ (قرآن) پڑھا ہو۔’’"}],[1466,"شعبہ ، سعید بن ابی عروبہ اور معاذ ( بن ہشام ) نے اپنے والد کے واسطے سے ، سب نے قتادہ سے اپنے اپنے شاگردوں کی اسی سند کے ساتھ اس کے مانند روایت بیان کی ۔","",{"u2":"شعبہ، سعید بن ابی عروبہ اور معاذ (بن ہشام) نے اپنے والد کے واسطے سے، سب نے قتادہ سے اپنے اپنے شاگردوں کی اسی سند کے ساتھ اس کے مانند روایت بیان کی۔"}],[1467,"(قتادہ کے بجائے ) جریدی نے ابو نضرہ سے ، انھوں نے سیدنا ابوسعید رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت کی ۔","",{"u2":"قتادہ کے بجائے) جریدی نے ابو نضرہ سے، انھوں نے حضرت ابوسعید رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت کی۔"}],[1468,"ابوبکر بن ابی شیبہ اور ابوسعید اشج نے ابو خالد احمر سے ، انھوں نے اوس بن ضمعج سے اور انھوں نے سیدنا ابو مسعود انصاری رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ لوگوں کی امامت وہ کرائے جو ان میں سے کتاب اللہ کو زیادہ پڑھنے والا ہو ، اگر پڑھنے میں برابر ہو ں تو وہ جو ان میں سے سنت کا زیادہ عالم ہو ، اگر وہ سنت ( کے علم ) میں بھی برابر ہوں تو وہ جس نے ان سب کی نسبت پہلے ہجرت کی ہو ، اگر وہ ہجرت میں برابر ہوں تو وہ جو اسلام قبول کرنے میں سبقت رکھتا ہو ۔ کوئی انسان وہاں دوسرے انسان کی امامت نہ کرے جہاں اس ( دوسرے ) کا اختیار ہو اور اس کے گھر میں اس کی قابل احترام نشست پر اس کی اجازت کے بغیر کوئی نہ بیٹھے ۔ ’’ ( ابوسعید ) اشج نے اپنی روایت میں ’’اسلام قبول کرنے میں’’ ( سبقت ) کے بجائے ’’عمر میں’’ ( سبقت ) رکھتا ہے","",{"u2":"ابوبکر بن ابی شیبہ اور ابوسعید اشج نے ابو خالد احمر سے، انھوں نے اوس بن ضمعج سے اور انھوں نے حضرت ابو مسعود انصاری رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘ لوگوں کی امامت وہ کرائے جو ان میں سے کتاب اللہ کو زیادہ پڑھنے والا ہو، اگر پڑھنے میں برابر ہو ں تو وہ جو ان میں سے سنت کا زیادہ عالم ہو، اگر وہ سنت (کے علم) میں بھی برابر ہوں تو وہ جس نے ان سب کی نسبت پہلے ہجرت کی ہو، اگر وہ ہجرت میں برابر ہوں تو وہ جو اسلام قبول کرنے میں سبقت رکھتا ہو۔ کوئی انسان وہاں دوسرے انسان کی امامت نہ کرے جہاں اس (دوسرے) کا اختیار ہو اور اس کے گھر میں اس کی قابل احترام نشست پر اس کی اجازت کے بغیر کوئی نہ بیٹھے۔’’ (ابوسعید) اشج نے اپنی روایت میں ’’اسلام قبول کرنے میں’’ (سبقت) کے بجائے ’’عمر میں’’ (سبقت)رکھتا ہے"}],[1469,"ابو معاویہ ، جریر ، ابن فضیل اور سفیان سب نے اعمش سے اسی سند کے ساتھ اسی مانند روایت بیان کی ہے","",{"u2":"ابو معاویہ، جریر، ابن فضیل اور سفیان سب نے اعمش سے اسی سند کے ساتھ اسی مانند روایت بیان کی ہے"}],[1470,"شعبہ نے اسماعیل بن رجاء سے روایت کی ، کہا : میں نے اوس بن ضمعج سے سنا ، کہتے تھے : میں نے سیدنا ابو مسعود رضی اللہ عنہ سے سنا ، وہ کہتے تھے : رسول اللہ صلی اللہ علیہ وسلم نے ہم سے کہا : ‘‘ قوم کی امامت وہ کرے جو اللہ کی کتاب کو زیادہ پڑھنے والا اور پڑھنے میں دوسروں سے زیادہ قدیم ہو ، اگر ان سب کا پڑھنا ایک سا ہو تو وہ امامت کرے جو ہجرت میں قدیم تر ہو ، اگر ہجرت میں سب برابر ہوں تو وہ امامت کرے جو ان سب سے عمر میں بڑا ہو اور تم کسی شخص کے گھر اور اس کے دائرہ اختیار میں اس کے امام نہ ہی اس کے گھر میں اس کی قابل احترام نشست پر بیٹھو ، ہاں اس صورت میں کہ وہ تمھیں ( اس بات کی ) اجازت دے-یا ( فرمایا : ) اس کی اجازت سے ۔ ’’","",{"u2":"شعبہ نے اسماعیل بن رجاء سے روایت کی، کہا: میں نے اوس بن ضمعج سے سنا، کہتے تھے: میں نے حضرت ابو مسعود رضی اللہ عنہ سے سنا، وہ کہتے تھے:رسول اللہ صلی اللہ علیہ وسلم نے ہم سے کہا: ‘‘ قوم کی امامت وہ کرے جو اللہ کی کتاب کو زیادہ پڑھنے والا اور پڑھنے میں دوسروں سے زیادہ قدیم ہو،اگر ان سب کا پڑھنا ایک سا ہو تو وہ امامت کرے جو ہجرت میں قدیم تر ہو، اگر ہجرت میں سب برابر ہوں تو وہ امامت کرے جو ان سب سے عمر میں بڑا ہو اور تم کسی شخص کے گھر اور اس کے دائرہ اختیار میں اس کے امام نہ ہی اس کے گھر میں اس کی قابل احترام نشست پر بیٹھو، ہاں اس صورت میں کہ وہ تمھیں (اس بات کی) اجازت دے-یا (فرمایا:) اس کی اجازت سے۔’’"}],[1471,"اسماعیل بن ابراہیم ( ابن علیہ ) نے ہمیں حدیث بیان کی ، کہا : ہم سے ایوب نے ابو قلابہ سے حدیث بیان کی ، انھوں نے مالک بن حویرث رضی اللہ عنہ سے روایت کی ، کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور ہم سب نوجوان اور ہم عمر تھے ، ہم نے آپ کے پاس بیس راتیں قیام کیا ۔ اللہ کے رسول صلی اللہ علیہ وسلم بہت مہربان اور نرم دل تھے ، آپ نے خیال فرمایا کہ ہمیں گھر والوں کے پاس جانے کا اشتیاق ہو گا ، آپ نے ہم سے ہمارے ان گھر والوں کے بارے میں سوال کیا جنھیں ہم چھوڑ آئے تھے ، ہم نے آپ کو بتایا تو آپ نے فرمایا : ‘‘ اپنے گھر والوں کے پاس لوٹ جاؤ ، انھی کے درمیان رہو ، انھیں تعلیم دو اور انھیں ( اچھائی پر چلنے کا ) حکم دو ، چنانچہ جب نماز کا وقت آئے تو ایک آدمی تم سب کے لئے اذان کہے ، پھر تم میں سے ( جو عمر میں ) سب سے بڑا ہو وہ تمھاری امامت کرے ۔","",{"u2":"اسماعیل بن ابراہیم (ابن علیہ) نے ہمیں حدیث بیان کی، کہا: ہم سے ایوب نے ابو قلابہ سے حدیث بیان کی، انھوں نے مالک بن حویرث رضی اللہ عنہ سے روایت کی، کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور ہم سب نوجوان اور ہم عمر تھے، ہم نے آپ کے پاس بیس راتیں قیام کیا۔ اللہ کے رسول صلی اللہ علیہ وسلم بہت مہربان اور نرم دل تھے، آپ نے خیال فرمایا کہ ہمیں گھر والوں کے پاس جانے کا اشتیاق ہو گا، آپ نے ہم سے ہمارے ان گھر والوں کے بارے میں سوال کیا جنھیں ہم چھوڑ آئے تھے، ہم نے آپ کو بتایا تو آپ نے فرمایا: ‘‘اپنے گھر والوں کے پاس لوٹ جاؤ، انھی کے درمیان رہو، انھیں تعلیم دو اور انھیں (اچھائی پر چلنے کا) حکم دو، چنانچہ جب نماز کا وقت آئے تو ایک آدمی تم سب کے لئے اذان کہے، پھر تم میں سے (جو عمر میں) سب سے بڑا ہو وہ تمھاری امامت کرے۔"}],[1472,"حماد نے ایوب سے اسی سند کے ساتھ یہ حدیث بیان کی ۔"],[1473,"اور یہی حدیث ہمیں ابن ابی عمر نے سنائی ، کہا : عبدالوہاب نے بھی ایوب سے ہمیں حدیث بیان کی ، کہا : مجھ سے ابو قلابہ نے بیان کیا ، کہا : ہمیں ابو سلیمان مالک بن حویرث رضی اللہ عنہ نے حدیث سنائی ، کہا : میں کچھ لوگوں ( کی معیت ) میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا ، ہم تقریبا ہم عمر نوجوان تھے......آگے دونوں ( حماد اور عبدالوہاب ) نے ابن علیہ کی حدیث کی طرح حدیث بیان کی ۔ عبدالوہاب ثقفی نے خالد حذاء سے ، انھوں نے ابو قلابہ سے اور انھوں نے سیدنا مالک بن حویرث رضی اللہ عنہ سے روایت کی ، کہا : میں اور میرا ساتھی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ، جب ہم نے آپ کے ہاں سے واپسی کا ارادہ کیا تو آپ نے ہم سے فرمایا : ‘‘ جب نماز ( کا وقت ) آئے تو اذان کہو ، پھر اقامت کہو اور تم دونوں میں جو بڑا ہو وہ تمھاری امامت کر لے ۔ ’’","",{"u2":"اور یہی حدیث ہمیں ابن ابی عمر نے سنائی، کہا: عبدالوہاب نے بھی ایوب سے ہمیں حدیث بیان کی، کہا: مجھ سے ابو قلابہ نے بیان کیا، کہا: ہمیں ابو سلیمان مالک بن حویرث رضی اللہ عنہ نے حدیث سنائی، کہا: میں کچھ لوگوں (کی معیت) میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا، ہم تقریبا ہم عمر نوجوان تھے......آگے دونوں (حماد اور عبدالوہاب) نے ابن علیہ کی حدیث کی طرح حدیث بیان کی۔\nعبدالوہاب ثقفی نے خالد حذاء سے، انھوں نے ابو قلابہ سے اور انھوں نے حضرت مالک بن حویرث رضی اللہ عنہ سے روایت کی، کہا: میں اور میرا ساتھی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے،جب ہم نے آپ کے ہاں سے واپسی کا ارادہ کیا تو آپ نے ہم سے فرمایا: ‘‘جب نماز (کا وقت) آئے تو اذان کہو، پھر اقامت کہو اور تم دونوں میں جو بڑا ہو وہ تمھاری امامت کر لے۔’’"}],[1474,"عبدالوہاب ثقفی نے خالد حذاء سے ، انھوں نے ابو قلابہ سے اور انھوں نے سیدنا مالک بن حویرث رضی اللہ عنہ سے روایت کی ، کہا : میں اور میرا ساتھی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ، جب ہم نے آپ کے ہاں سے واپسی کا ارادہ کیا تو آپ نے ہم سے فرمایا : ‘‘ جب نماز ( کا وقت ) آئے تو اذان کہو ، پھر اقامت کہو اور تم دونوں میں جو بڑا ہو وہ تمھاری امامت کر لے ۔ ’’","",{"u2":"عبدالوہاب ثقفی نے خالد حذاء سے، انھوں نے ابو قلابہ سے اور انھوں نے حضرت مالک بن حویرث رضی اللہ عنہ سے روایت کی، کہا: میں اور میرا ساتھی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے،جب ہم نے آپ کے ہاں سے واپسی کا ارادہ کیا تو آپ نے ہم سے فرمایا: ‘‘جب نماز (کا وقت) آئے تو اذان کہو، پھر اقامت کہو اور تم دونوں میں جو بڑا ہو وہ تمھاری امامت کر لے۔’’"}],[1475,"حفص بن غیاث نے خالد حذاء سے اسی سند کے ساتھ روایت کی اور ( اپنی روایت میں ) یہ اضافہ کیا کہ حذاء نے کہا : دونوں قراءت میں ایک جیسے تھے ۔","",{"u2":"حفص بن غیاث نے خالد حذاء سے اسی سند کے ساتھ روایت کی اور (اپنی روایت میں)یہ اضافہ کیا کہ حذاء نے کہا: دونوں قراءت میں ایک جیسے تھے۔"}],[1476,"یونس بن یزید نے ابن شہاب سے روایت کرتے ہوئے خبر دی ، کہا : مجھے سعید بن مسیب اور ابو سلمہ بن عبدالرحمان بن عوف نے بتایا کہ ان دونوں نے سیدنا ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز فجر کی قراءت سے فارغ ہوتے اور ( رکوع میں جانے کے لیے ) تکبیر کہتے تو سر اٹھانے کے بعد سمع اللہ لمن حمدہ ربنا ولک الحمد ( اللہ نے سن لیا جس نے اس کی حمد کی ، اے ہمارے رب! اور ٰحمدتیرے ہی لیے ہے ) کہتے ، پھر حالت قیام ہی میں آپ فرماتے : ‘‘ اے اللہ!ولید بن ولید ، سلمہ بن ہشام ، عیاش بن ابی ربیعہ اور مومنوں میں سے ان لوگوں کو جنھیں ( کافروں نے ) کمزور پایا ، نجات عطا فرما ۔ اے اللہ!قبیلہ مضر پر اپنے روندنے کو سخت کر ، ان پر اپنے اس مؤاخذے کو یوسف علیہ السلام کے زمانے کے قحط کی طرح کر د ۔ اے اللہ! الحیان ، رعل ، ذکوان اور عصیہ پر ، جنھوں نے اللہ اور اس کے رسول کی نافرمانی کی ، لعنت نازل کر ۔ ’’پھر ہم تک یہ بات پہنچی کہ اس کے بعد جب آپ پر یہ آیت اتری : ‘‘ آپ کا اس معاملے سے کوئی سروکار نہیں ، ( اللہ تعالیٰ ) چاہے ان کو توبہ کا موقع عطا کرے ، چاہے ان کو عذاب دے کہ و ہ یقینا ظلم کرنے والے ہیں’’ تو آپ نے یہ دعا چھوڑ دی ۔","",{"u2":"یونس بن یزید نے ابن شہاب سے روایت کرتے ہوئے خبر دی، کہا: مجھے سعید بن مسیب اور ابو سلمہ بن عبدالرحمان بن عوف نے بتایا کہ ان دونوں نے حضرت ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز فجر کی قراءت سے فارغ ہوتے اور (رکوع میں جانے کے لیے) تکبیر کہتے تو سر اٹھانے کے بعد سمع اللہ لمن حمدہ ربنا ولک الحمد(اللہ نے سن لیا جس نے اس کی حمد کی، اے ہمارے رب! اور ٰحمدتیرے ہی لیے ہے) کہتے،پھر حالت قیام ہی میں آپ فرماتے:‘‘اے اللہ!ولید بن ولید، سلمہ بن ہشام،عیاش بن ابی ربیعہ اور مومنوں میں سے ان لوگوں کو جنھیں (کافروں نے)کمزور پایا، نجات عطا فرما۔ اے اللہ!قبیلہ مضر پر اپنے روندنے کو سخت کر،ان پر اپنے اس مؤاخذے کو یوسف علیہ السلام کے زمانے کے قحط کی طرح کر د۔اے اللہ! الحیان،رعل،ذکوان اور عصیہ پر، جنھوں نے اللہ اور اس کے رسول کی نافرمانی کی، لعنت نازل کر۔’’پھر ہم تک یہ بات پہنچی کہ اس کے بعد جب آپ پر یہ آیت اتری: ‘‘آپ کا اس معاملے سے کوئی سروکار نہیں، (اللہ تعالیٰ) چاہے ان کو توبہ کا موقع عطا کرے، چاہے ان کو عذاب دے کہ و ہ یقینا ظلم کرنے والے ہیں’’ تو آپ نے یہ دعا چھوڑ دی۔"}],[1477,"ابن عینیہ نے زہری سے ، انھوں نے سعید بن مسیب سے ، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے ان الفاظ تک روایت کی : ‘‘ اس سختی کو ان پر یوسف علیہ السلام کے زمانے کے قحط کی طرح کر دے’’ جو اس کے بعد ہے اسے بیان نہیں کیا ۔","",{"u2":"ابن عینیہ نے زہری سے،انھوں نے سعید بن مسیب سے، انھوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے ان الفاظ تک روایت کی: ‘‘اس سختی کو ان پر یوسف علیہ السلام کے زمانے کے قحط کی طرح کر دے’’ جو اس کے بعد ہے اسے بیان نہیں کیا۔"}],[1478,"ہمیں اوزاعی نے یحییٰ بن ابی کثیر سے حدیث سنائی ، انھوں نے ابو سلمہ سے روایت کی کہ سیدنا ابوہریرہ رضی اللہ عنہ نے انھیں حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم نے ایک مہینے تک رکوع کے بعد قنوت ( عاجزی سے دعا ) کی ، جب آپ سمع اللہ لمن حمدہ کہہ لیتے ( تو ) اپنی قنوت میں یہ ( الفاظ ) کہتے : اے اللہ! ولید بن ولید کو نجات دے ، اے اللہ عیاش بن ابی ربیعہ کو نجات دے ، اے اللہ کمزور سمجھے جانے والے ( دوسرے ) مومنوں کو نجات عطا کر ، اے اللہ ! ان پر اپنے روندنے کو سخت تر کر اور اسے ان پر ، یوسف علیہ السلام کے ( زمانے کے ) قحط کے مانند کر دے ۔ ’’ مسجدوں اور نماز کی جگہوں کے احکام ابوہریرہ رضی اللہ عنہ نے کہا : پھر میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ نے یہ دعا چھوڑ دی ، میں نے ( ساتھیوں سے ) کہا : میں دیکھتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ دعا چھوڑ دی ہے ۔ کہا : ( جواب میں ) مجھ سے کہا گیا ، تم انھیں دیکھتے نہیں ، ( جن کے لیے دعا ہوئی تھی ) وہ سب آچکے ہیں ۔","",{"u2":"ہمیں اوزاعی نے یحییٰ بن ابی کثیر سے حدیث سنائی، انھوں نے ابو سلمہ سے روایت کی کہ حضرت ابوہریرہ رضی اللہ عنہ نے انھیں حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم نے ایک مہینے تک رکوع کے بعد قنوت (عاجزی سے دعا)کی، جب آپ سمع اللہ لمن حمدہ کہہ لیتے (تو) اپنی قنوت میں یہ (الفاظ) کہتے: اے اللہ! ولید بن ولیدکو نجات دے،اے اللہ عیاش بن ابی ربیعہ کو نجات دے،اے اللہ کمزور سمجھے جانے والے (دوسرے)مومنوں کو نجات عطا کر،اے اللہ! ان پر اپنے روندنے کو سخت تر کر اور اسے ان پر، یوسف علیہ السلام کے (زمانے کے) قحط کے مانند کر دے۔’’\nمسجدوں اور نماز کی جگہوں کے احکام\nابوہریرہ رضی اللہ عنہ نے کہا: پھر میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ نے یہ دعا چھوڑ دی، میں نے (ساتھیوں سے) کہا: میں دیکھتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ دعا چھوڑ دی ہے۔ کہا: (جواب میں) مجھ سے کہا گیا،تم انھیں دیکھتے نہیں،(جن کے لیے دعا ہوئی تھی) وہ سب آچکے ہیں۔"}],[1479,"کہ سیدنا ابوہریرہ رضی اللہ عنہ نے انھیں خبر دی کہ ( ایک روز ) رسول اللہ صلی اللہ علیہ وسلم عشاء کی نماز پڑھ رہے تھے ، جب آپ نے فرمایا : سمع اللہ لمن حمدہ تو سجدے میں جانے سے پہلے آپ نے ( دعا مانگتے ہوئے ) فرمایا : ‘‘ اے اللہ عیاش بن ابی ربیعہ کو نجات عطا فرما ۔ ’’ کے الفاظ تک اوزاعی کی روایت کردہ حدیث کی طرح حدیث بیان کی ، بعد کے الفاظ بیان نہیں کیے اوزاعی کے بجائے ) شیبان نے یحییٰ سے ، انھوں نے ابوسلمہ سے روایت کی","",{"u2":"کہ حضرت ابوہریرہ رضی اللہ عنہ نے انھیں خبر دی کہ (ایک روز) رسول اللہ صلی اللہ علیہ وسلم عشاء کی نماز پڑھ رہے تھے،جب آپ نے فرمایا: سمع اللہ لمن حمدہ تو سجدے میں جانے سے پہلے آپ نے (دعا مانگتے ہوئے) فرمایا:‘‘ اے اللہ عیاش بن ابی ربیعہ کو نجات عطا فرما۔’’ کے الفاظ تک اوزاعی کی روایت کردہ حدیث کی طرح حدیث بیان کی، بعد کے الفاظ بیان نہیں کیےاوزاعی کے بجائے) شیبان نے یحییٰ سے، انھوں نے ابوسلمہ سے روایت کی"}],[1480,"ابو سلمہ بن عبدالرحمان نے سیدنا ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا : اللہ کی قسم! ضرور رسول اللہ صلی اللہ علیہ وسلم کی نماز کو تم لوگوں کے بہت قریب کروں گا ، اس کے بعد سیدنا ابوہریرہ رضی اللہ عنہ ظہر ، عشاء اور صبح کی نماز میں قنوت کرتے اور مسلمانوں کے حق میں رضی اللہ عنہ دعا کرتے اور کافروں پر لعنت بھیجتے","",{"u2":"ابو سلمہ بن عبدالرحمان نے حضرت ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا: اللہ کی قسم! ضرور رسول اللہ صلی اللہ علیہ وسلم کی نماز کو تم لوگوں کے بہت قریب کروں گا،اس کے بعد حضرت ابوہریرہ رضی اللہ عنہ ظہر،عشاء اور صبح کی نماز میں قنوت کرتے اور مسلمانوں کے حق میں رحمہ اللہ دعا کرتے اور کافروں پر لعنت بھیجتے"}],[1481,"اسحاق بن عبداللہ بن ابی طلحہ نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے ان لوگوں کے خلاف کنھوں نے بئر معونہ والوں کو قتل کیا تھا ، تیس ( دن تک ) صبح ( کی نمازوں ) میں بدعا کی ۔ آپ نے رعل ، ذکوان ، لحیان اور عصیہ کے خلاف ، جنھوں نے اللہ اور اس کے رسول کی نافرمانی کی ، بد دعا کی ۔ انس رضی اللہ عنہ نے کہا : اللہ نے ان لوگوں کے متعلق جو بئر معونہ پر قتل ہوئے ، قرآن ( کا کچھ حصہ ) نازل فرمایا جو بعد میں منسوخ ہو نے تک ہم پڑھتے رہے ( اس میں شہداء کا پیغام تھا ) کہ ہماری قوم کو بتا دیں کہ ہم اپنے رب سے جا ملے ہیں ، وہ ہم سے راضی ہو گیا ہے اور ہم اس سے راضی ہیں ۔","",{"u2":") اسحاق بن عبداللہ بن ابی طلحہ نے حضرت انس بن مالک رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے ان لوگوں کے خلاف کنھوں نے بئر معونہ والوں کو قتل کیا تھا، تیس (دن تک) صبح (کی نمازوں) میں بدعا کی۔ آپ نے رعل، ذکوان،لحیان اور عصیہ کے خلاف، جنھوں نے اللہ اور اس کے رسول کی نافرمانی کی، بد دعا کی۔ انس رضی اللہ عنہ نے کہا: اللہ نے ان لوگوں کے متعلق جو بئر معونہ پر قتل ہوئے،قرآن (کا کچھ حصہ) نازل فرمایا جو بعد میں منسوخ ہو نے تک ہم پڑھتے رہے(اس میں شہداء کا پیغام تھا) کہ ہماری قوم کو بتا دیں کہ ہم اپنے رب سے جا ملے ہیں، وہ ہم سے راضی ہو گیا ہے اور ہم اس سے راضی ہیں۔"}],[1482,"محمد ( بن سیرین ) سے روایت ہے ، کہا : میں نے سیدنا انس بن مالک رضی اللہ عنہ سے پوچھا : کیا رسول اللہ صلی اللہ علیہ وسلم نے ( کبھی ) صبح کی نماز میں قنو ت کی تھی؟ کہا : ہاں ، رکوع سے تھوڑی دیر بعد ۔","",{"u2":"محمد (بن سیرین) سے روایت ہے، کہا: میں نے حضرت انس بن مالک رضی اللہ عنہ سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم نے (کبھی) صبح کی نماز میں قنو ت کی تھی؟ کہا: ہاں، رکوع سے تھوڑی دیر بعد۔"}],[1483,"ابو مجلز نے سیدنا انس رضی اللہ عنہ سے روایت کو کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینے تک صبح کی نماز میں رکوع کے بعد قنوت کی ، آپ رعل اور ذکوان کے خلاف بددعا فرماتے تھے اور کہتے تھے : ‘‘ عصیہ نے اللہ اور اس کے رسول کی نافرمانی کی ۔ ’’","",{"u2":"ابو مجلز نے حضرت انس رضی اللہ عنہ سے روایت کو کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینے تک صبح کی نماز میں رکوع کے بعد قنوت کی،آپ رعل اور ذکوان کے خلاف بددعا فرماتے تھے اور کہتے تھے: ‘‘عصیہ نے اللہ اور اس کے رسول کی نافرمانی کی۔’’"}],[1484,"انس بن سیرین نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینے تک نماز فجر میں رکوع کے بعد قنوت کی ، آپ بنو عصیہ کے خلاف بددعا کرتے رہے","",{"u2":"انس بن سیرین نے حضرت انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینے تک نماز فجر میں رکوع کے بعد قنوت کی، آپ بنو عصیہ کے خلاف بددعا کرتے رہے"}],[1485,"ابو معاویہ نے عاصم سے اور انھوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، کہا : میں نے ان ( انس رضی اللہ عنہ ) سے قنو ت کے بارے میں پوچھا : رکوع سے پہلے ہے یا رکوع کے بعد؟ تو انھوں نے کہا : رکوع سے پہلے ۔ کہا : میں نے عرض کی : بہت سے لوگ سمجھتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے رکوع کے بعد قنوت کی ۔ تو انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینے کی ، ان لوگوں کو خلاف بددعا فرماتے رہے جنھوں نے آپ کے صحابہ میں سے کچھ لوگوں کو قتل کیا تھا جنھیں قراء ( قرآن پڑھنے والے ) کہا جاتا تھا ۔","",{"u2":") ابو معاویہ نے عاصم سے اور انھوں نے حضرت انس رضی اللہ عنہ سے روایت کی، کہا: میں نے ان (انس رضی اللہ عنہ) سے قنو ت کے بارے میں پوچھا: رکوع سے پہلے ہے یا رکوع کے بعد؟ تو انھوں نے کہا: رکوع سے پہلے۔کہا: میں نے عرض کی: بہت سے لوگ سمجھتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے رکوع کے بعد قنوت کی۔ تو انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینے کی، ان لوگوں کو خلاف بددعا فرماتے رہے جنھوں نے آپ کے صحابہ میں سے کچھ لوگوں کو قتل کیا تھا جنھیں قراء (قرآن پڑھنے والے) کہا جاتا تھا۔"}],[1486,"سفیان نے عاصم سے روایت کی ، کہا : میں نے انس رضی اللہ عنہ کو کہتے سنا ، میں نے رسول اللہ صلی اللہ علیہ وسلم کو نہیں دیکھا کہ آپ کو کسی اور جنگ پر اتنا غم محسوس ہوا ہو جتنا ان ستر ( ساتھیوں ) پر ہوا جو بئر معونہ کے واقعے کے روز شہید کیے گئے ، انھیں قراء کہا جاتا تھا ، آپ ایک مہینے تک ان کے قالوں کے خلاف بد دعا کرتے رہے ۔","",{"u2":"سفیان نے عاصم سے روایت کی، کہا: میں نے انس رضی اللہ عنہ کو کہتے سنا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو نہیں دیکھا کہ آپ کو کسی اور جنگ پر اتنا غم محسوس ہوا ہو جتنا ان ستر (ساتھیوں) پر ہوا جو بئر معونہ کے واقعے کے روز شہید کیے گئے، انھیں قراء کہا جاتا تھا، آپ ایک مہینے تک ان کے قالوں کے خلاف بد دعا کرتے رہے۔"}],[1487,"حفص ، ابن فضیل اور مروان سب نے عاصم سے ، انھوں نے سیدنا انس رضی اللہ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے یہی حدیث روایت کی ، ان میں سے بعض نے بعض سے کچھ زیادہ روایت کیا ہے ۔","",{"u2":"حفص، ابن فضیل اور مروان سب نے عاصم سے، انھوں نے حضرت انس رضی اللہ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے یہی حدیث روایت کی، ان میں سے بعض نے بعض سے کچھ زیادہ روایت کیا ہے۔"}],[1488,"شعبہ نے قتادہ سے اور انھوں نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ایک مہینے تک قنوت کی ، آپ رعل ، ذکوان اور عصیہ پر لعنت بھیجتے تھے جنھوں نے اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی معصیت کی تھی ۔","",{"u2":") شعبہ نے قتادہ سے اور انھوں نے حضرت انس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ایک مہینے تک قنوت کی، آپ رعل، ذکوان اور عصیہ پر لعنت بھیجتے تھے جنھوں نے اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی معصیت کی تھی۔"}],[1489,"موسیٰ بن انس نے رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اس طرح روایت کی ۔","",{"u2":") موسیٰ بن انس نے رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اس طرح روایت کی۔"}],[1490,"ہشام نے قتادہ کے حوالے سے سیدنا انس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینے تک عرب کے قبائل میں سے کچھ قبیلوں کے خلاف بددعا کرتے ہوئے قنوت کی ، پھر چھوڑ دی ۔","",{"u2":"ہشام نے قتادہ کے حوالے سے حضرت انس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینے تک عرب کے قبائل میں سے کچھ قبیلوں کے خلاف بددعا کرتے ہوئے قنوت کی، پھر چھوڑ دی۔"}],[1491,"شعبہ نے عمروہ بن مرہ سے روایت کی ، کہا : میں نے ابن ابی لیلی ٰ سے سنا ، کہا : ہمیں سیدنا براء بن عازب رضی اللہ عنہا نے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم فجر اور مغرب ( کی نمازوں ) مین قنوت کیا کرتے تھے","",{"u2":"شعبہ نے عمروہ بن مرہ سے روایت کی، کہا: میں نے ابن ابی لیلی ٰ سے سنا، کہا: ہمیں حضرت براء بن عازب رضی اللہ عنہا نے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم فجر اور مغرب (کی نمازوں)مین قنوت کیا کرتے تھے"}],[1492,"سفیان نے عمرو بن مرہ سے ، انھوں نے عبدالرحمن بن ابی لیلیٰ سے اور انھوں نےسیدنا براء رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فجر اور مغرب ( کی نمازوں ) میں قنوت کی","",{"u2":"سفیان نے عمرو بن مرہ سے، انھوں نے عبدالرحمن بن ابی لیلیٰ سے اور انھوں نےحضرت براء رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نےفجر اور مغرب (کی نمازوں)میں قنوت کی"}],[1493,"عمران بن ابی انس نے حنظلہ بن علی سے اور انھوں نے خفاف بن ایما ء غفاری رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے نماز میں ( دعا کرتے ہوئے ) کہا : ’’ اے اللہ ! بنو لحیان : رعل ، ذکوان اور عصیہ پر لعنت بھیج جنھوں نے اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی کی ۔ غفار کی اللہ مغفرت کر ے اور اسلم کو اللہ سلامتی عطا فرمائے ۔ ‘‘","",{"u2":"عمران بن ابی انس نے حنظلہ بن علی سے اور انھوں نے خفاف بن ایما ء غفاری رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے نماز میں (دعا کرتے ہوئے)کہا: ’’ اے اللہ! بنو لحیان: رعل، ذکوان اور عصیہ پر لعنت بھیج جنھوں نے اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی کی۔ غفار کی اللہ مغفرت کر ے اور اسلم کو اللہ سلامتی عطا فرمائے۔‘‘"}],[1494,"حارث بن خفاف سے روایت ہے ، انھوں نے کہا : سیدنا خفاف بن ایما رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے رکوع کیا ، پھر سر اٹھا کر فرمایا : غفار کی اللہ مغفرت کرے ، اسلم کو اللہ سلامتی عطا کرے ۔ اور عصیہ نے اللہ اور اس کے رسول کی نافرمانی کی ۔ اے اللہ ! بنو لحیان پر لعنت بھیج اور رعل اور ذکوان پر لعنت بھیج ۔ ‘‘ پھر آپ سجدے میں چلے گئے ۔ خفاف رضی اللہ عنہ نے کہا : کافروں پر اسی کے سبب سے لعنت کی گئی ۔ ( لعنت کا طریقہ اختیار کیا گیا ۔)","",{"u2":"حارث بن خفاف سے روایت ہے، انھوں نے کہا: حضرت خفاف بن ایما رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے رکوع کیا، پھر سر اٹھا کر فرمایا: غفار کی اللہ مغفرت کرے، اسلم کو اللہ سلامتی عطا کرے۔ اور عصیہ نے اللہ اور اس کے رسول کی نافرمانی کی۔ اے اللہ! بنو لحیان پر لعنت بھیج اور رعل اور ذکوان پر لعنت بھیج۔‘‘ پھر آپ سجدے میں چلے گئے۔ خفاف رضی اللہ عنہ نے کہا: کافروں پر اسی کے سبب سے لعنت کی گئی۔ (لعنت کا طریقہ اختیار کیا گیا۔)"}],[1495,"(عمران کے بجائے ) عبدالرحمان بن حرملہ نے حنظلہ بن علی بن اسقع سے اور انھوں نے سیدنا خفاف بن ایماء رضی اللہ عنہ سے اسی کے مانند روایت کی ، سوائے اس کے کہ انھوں نے ’’کافروں پر اسی کے سبب لعنت کی گئی ‘‘ کے الفاظ نہیں کہے ۔","",{"u2":"عمران کے بجائے)عبدالرحمان بن حرملہ نے حنظلہ بن علی بن اسقع سے اور انھوں نے حضرت خفاف بن ایماء رضی اللہ عنہ سے اسی کے مانند روایت کی، سوائے اس کے کہ انھوں نے ’’کافروں پر اسی کے سبب لعنت کی گئی ‘‘ کے الفاظ نہیں کہے۔"}],[1496,"یونس نے ابن شہاب کے حوالے سے خبردی ، انھوں نے سعید بن مسیب سے اور انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب جنگ خیبر سے واپس ہوئے تو رات بھر چلتے رہے یہاں تک کہ جب آپ کو نیند نے آلیا ، آپ نے ( سواری سے ) اتر کر پڑاؤ کیا اور بلال رضی اللہ عنہ سے کہا : ’’ہمارے لیے رات کا پہرہ دو ( نظر رکھو کہ کب صبح ہوتی ہے ؟ ) ‘‘ بلال رضی اللہ عنہ نے مقدور بھر نماز پڑھی ، رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ سو گئے ۔ جب فجر قریب ہوئی تو بلال رضی اللہ عنہ نے ( مطلع ) فجر کی طرف رخ کرتے ہوئے اپنی سواری کے ساتھ ٹیک لگائی ، جب وہ ٹیک لگائے ہوئے تھے تو ان پر نیند غالب آگئی ، چنانچہ رسول اللہ صلی اللہ علیہ وسلم بیدار ہوئے نہ بلال اور نہی ہی ان کے صحابہ میں سے کوئی بیدار ہوا یہاں تک کہ ان پر دھوپ پڑنے لگی ، سب سے پہلے رسول اللہ صلی اللہ علیہ وسلم بیدار ہوئے اور گھبرا گئے ۔ فرمانے لگے : ’’اے بلال! ‘‘ تو بلال رضی اللہ عنہ نے کہا : میری جان کو بھی اسی نے قبضے میں لیا تھا جس نے ۔ میرے ماں باپ آپ پر قربان اے اللہ کے رسول ! ---آپ کی جان کو قبضے میں لے لیا تھا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : ’’سواریاں آگے بڑھاؤ ۔ ‘‘ وہ اپنی سواریوں کو لے کر کچھ آگے بڑھے ، پھر رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا اور بلال رضی اللہ عنہ کو حکم دیا ، انھوں نے نماز کی اقامت کہی ، پھر آپ نے ان کو صبح کی نماز پڑھائی ، جب نماز ختم کی تو فرمایا : ’’ جو شخص نماز ( پڑھنا ) بھول جائے تو جب اسے یاد آئے اسے پڑھے ، اللہ تعالیٰ نے فرمایا : ’’ میری یاد کے وقت نماز قائم کرو ۔ ‘‘ یونس نے کہا : ابن شہاب سے ’’للذکرٰی ‘‘ ( یاد کرنے کےلیے ) پڑھتے تھے","",{"u2":") یونس نے ابن شہاب کے حوالے سے خبردی، انھوں نے سعید بن مسیب سے اور انھوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب جنگ خیبر سے واپس ہوئے تو رات بھر چلتے رہے یہاں تک کہ جب آپ کو نیند نے آلیا، آپ نے (سواری سے)اتر کر پڑاؤ کیا اور بلال رضی اللہ عنہ سے کہا: ’’ہمارے لیے رات کا پہرہ دو (نظر رکھو کہ کب صبح ہوتی ہے؟)‘‘ بلال رضی اللہ عنہ نے مقدور بھر نماز پڑھی،رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ سو گئے۔ جب فجر قریب ہوئی تو بلال رضی اللہ عنہ نے (مطلع)فجر کی طرف رخ کرتے ہوئے اپنی سواری کے ساتھ ٹیک لگائی، جب وہ ٹیک لگائے ہوئے تھے تو ان پر نیند غالب آگئی، چنانچہ رسول اللہ صلی اللہ علیہ وسلم بیدار ہوئے نہ بلال اور نہی ہی ان کے صحابہ میں سے کوئی بیدار ہوا یہاں تک کہ ان پر دھوپ پڑنے لگی، سب سے پہلے رسول اللہ صلی اللہ علیہ وسلم بیدار ہوئے اور گھبرا گئے۔ فرمانے لگے: ’’اے بلال!‘‘ تو بلال رضی اللہ عنہ نے کہا: میری جان کو بھی اسی نے قبضے میں لیا تھا جس نے۔میرے ماں باپ آپ پر قربان اے اللہ کے رسول! ---آپ کی جان کو قبضے میں لے لیا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’سواریاں آگے بڑھاؤ۔‘‘ وہ اپنی سواریوں کو لے کر کچھ آگے بڑھے، پھر رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا اور بلال رضی اللہ عنہ کو حکم دیا، انھوں نے نماز کی اقامت کہی، پھر آپ نے ان کو صبح کی نماز پڑھائی، جب نماز ختم کی تو فرمایا: ’’ جو شخص نماز (پڑھنا)بھول جائے تو جب اسے یاد آئے اسے پڑھے، اللہ تعالیٰ نے فرمایا: ’’ میری یاد کے وقت نماز قائم کرو۔‘‘\nیونس نے کہا: ابن شہاب سے ’’للذکرٰی ‘‘ (یاد کرنے کےلیے)پڑھتے تھے"}],[1497,"ابوہریرہ رضی االله عنہ نے کہا کہ ایک شب ہم آخر رات میں نبی صلی اللہ علیہ وسلم کے ساتھ اترے اور نہ جاگے یہاں تک کہ سورج نکل آیا تب نبی صلی اللہ علیہ وسلم نے فرمایا کہ ہر شخص اونٹ کی نکیل پکڑے کہ یہ مکان ہے شیطان کا ۔ پھر ہم نے ایسا ہی کیا ( یعنی اس میدان سے باہر ہوگئے ) ۔ پھر پانی منگایا اور وضو کیا اور دو رکعت نماز پڑھی ۔ اور یعقوب نے سجدہ کی بجائے صلی کہا پھر نماز کی تکبیر ہوئی اور صبح کی فرض نماز ادا کی ۔"],[1498,"ثابت نے عبداللہ بن رباح سے اور انھوں نے سیدنا ابو قتادہ رضی اللہ عنہ سےر وایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطاب فرمایا اور کہا : ’’تم اپنی ( پوری ) شام اور ( پوری ) رات چلتے رہو گے تو ان شاء اللہ کل تک پانی پر پہنچ جاؤ گے ۔ ‘‘ لوگ چل پڑے ، کوئی مڑ کر دوسرے کی طرف دیکھتا بھی نہ تھا ۔ ابو قتادہ رضی اللہ عنہ نے کہا : اسی عالم میں رسول اللہ صلی اللہ علیہ وسلم چلتے رہے یہاں تک کہ رات آدھی گزر گئی ، میں آپ کے پہلو میں چل رہا تھا ، کہا : تو رسول اللہ صلی اللہ علیہ وسلم کو اونگھ آگئی اور آپ سواری سے ایک طرف جھک گئے ، میں آپ کے پاس آیا اور آپ کو جگائے بغیر آپ کو سہارا دیا حتی کہ آپ اپنی سواری پر سیدھے ہو گئے ، پھر آپ چلتے رہے یہا ں تک کہ رات کا بیشتر حصہ گزر گیا ، آپ ( پھر ) سواری پر ( ایک طرف ) جھکے ، کہا : میں نے آپ کو جگائے بغیر آپ کو سہارا دیا یہاں تک کہ آپ اپنی سواری پر سیدھے ہو گئے ، کہا : پھر چلتے رہے حتی کہ سحری کا آخری وقت تھا تو آپ ( پھر ) جھکے ، یہ جھکنا پہلے دونزں بار کے جھکنے سے زیادہ تھا ، قریب تھا کہ آپ اونٹ سے گر پڑتے ، میں آپ کے پاس آیا اور آپ کو سہارا دیا تو آپ نے اپنا سر مبارک اٹھایا اور فرمایا : ’’یہ کون ہے ؟ ‘‘ میں نے عرض کی : ابو قتادہ ہوں ۔ فرمایا : ’’تم کب سے میرے ساتھ اس طرح چل رہے ہو؟ ‘‘ میں نے عرض کی : میں رات ہی سے اس طرح سفر کر رہا ہوں ۔ فرمایا : ’’ اللہ اسی طرح تمھاری حفاظت کرے جس طر ح تم نے اس کے نبی کی حفاظت کی ۔ ‘‘ پھر فرمایا : ’’ کیا تم دیکھ رہے ہو ( کہ ) ہم لوگوں سے اوجھل ہیں ؟ ‘‘ پھر پوچھا : ’’تمھیں کوئی ( اور ) نظر آر ہا ہے ؟ ‘‘ میں نے عرض کی : یہ ایک سوار ہے ۔ پھر عرض کی : یہ ایک اور سوار ہے حتی کہ ہم اکٹھے ہوئے تو سات سوار تھے ، کہا : رسول اللہ صلی اللہ علیہ وسلم راستے سے ایک طرف ہٹے ، پھر سر ( نیچے ) رکھ دیا ( اور لیٹ گئے ) پھر فرمایا : ’’ ہمارے لیے ہماری نماز کا خیال رکھنا ۔ ‘‘ پھر جو سب سے پہلے جاگے وہ رسول اللہ صلی اللہ علیہ وسلم ہی تھے ، سورج آپ کی پشت پر ( چمک رہا ) تھا ، کہا : ہم سخت تشویش کے عالم میں کھڑے ہوئے ، پھر آپ نے فرمایا : ’’سوار ہوجاؤ ۔ ‘‘ ہم سوار ہوئے اور ( آگے ) چل پڑے حتی کہ جب سورج بلند ہو گیا تو آپ اترے ، پھر آپ نے وضو کا برتن مانگا جو میرے ساتھ تھا ، اسی میں کچھ پانی تھا ، کہا : پھر آپ نے اس سے ( مکمل ) وضو کے مقابلے میں کچھ ہلکا وضو کیا ، اور ا س میں کچھ پانی بچ بھی گیا ، پھر آپ نے ( مجھے ) ابو قتادہ رضی اللہ عنہ سے فرمایا : ’’ ہمارے لیے اپنے وضو کا برتن محفوظ رکھنا ، اس کی ایک خبر ہو گی ۔ ‘‘ پھر بلال ر رضی اللہ عنہ نے نماز کے لیے اذان کہی ، رسول اللہ صلی اللہ علیہ وسلم نے دو رکعتیں پڑھیں ، پھر آپ نے اسی طرح جس طرح روز کرتے تھے صبح کی نماز پڑھائی ، کہا : اور رسول اللہ صلی اللہ علیہ وسلم سوار ہو گئے ہم بھی آپ کی معیت میں سوار ہو گئے ، کہا : ہم میں سے کچھ لوگ ایک دوسرے سے کھسر پھر کرنے لگے کہ ہم نے نماز میں جو کوتاہی کی ہے اس کا کفارہ کیا ہے ؟ اس پر آپ نے فرمایا : ’’ کیا تمھارے لیے میر ے عمل میں نمونہ نہیں ؟ ‘‘ پھر آپ نے فرمایا : ’’ سمجھ لو ! نیند ( آجانے ) میں ( کسی کی ) کوئی کوتاہی نہیں ۔ ‘‘ کوتاہی اس کی ہے جس نے ( جاگنے کے بعد ) دوسری نماز کا وقت آجانے تک نماز نہیں پڑھی ، جو اس طرح ( نیند ) کرے تو جب اس کے لیے جاگے تو یہ نماز پڑھ لے ، پھر جب دوسرا دن آئے تو اسے وقت پر ادا کرے ۔ ‘‘ پھر فرمایا : ’’تم کیا دیکھتے ہو ( دوسرے ) لوگوں نے کیا کیا ؟ ‘‘ کہا : پھر آپ نے فرمایا : ’’لوگوں نے صبح کی تو اپنے نبی کو گم پایا ۔ ابو بکر اور عمر رضی اللہ عنہ نے کہا : اللہ کے رسول صلی اللہ علیہ وسلم تمھارے پیچھے ہیں ، وہ ایسے نہیں کہ تمھیں پیچھے چھوڑ دیں ۔ ( دوسرے ) لوگوں نے کہا : بے شک رسول اللہ صلی اللہ علیہ وسلم تم سے آگے ہیں ۔ اگر وہ ابو بکر اور عمر رضی اللہ عنہ کی ا رضی اللہ عنہ اعت کریں تو صحیح راستے پر چلیں گے ۔ ‘‘ کیا : تو ہم لوگوں تک ( اس وقت ) پہنچ پائے جب دن چڑھ آیا تھا اور ہر شے تپ گئی تھی اور وہ کہہ رہے تھے : اے اللہ کے رسول ! ہم پیا سے مر گئے ۔ تو آپ نے فرمایا : ’’ تم پر کوئی ہلاکت نہیں آئی ۔ ‘‘ پھر فرمایا : ’’میرا چھوٹا پیالہ میرے پاس آنے دو ۔ ‘‘ کہا : پھر وضو کے پانی والا برتن منگوایا ، رسول اللہ صلی اللہ علیہ وسلم ( اس سے پیالے میں ) انڈیلتے گئے اور ابو قتادہ رضی اللہ عنہ لوگوں کو پلاتے گئے ، زیاد دیر نہ گزری تھ کہ لوگوں نے وضو کے برتن کیں جو ( تھوڑا سا پانی ) تھا ، دیکھ لیا ، اس بر جھرمٹ بناکر اکٹھے ہو گے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ اچھا طریقہ اختیار کرو ، تم میں سے ہر ایک اچھی طرح پیاس بجھا لے گا ۔ ‘‘ کہا : لوگوں نے ایسا ہی کیا ، رسول اللہ صلی اللہ علیہ وسلم پانی ( پیالے میں ) انڈیلتے گئے اور میں لوگوں کو پلاتا گیا یہاں تک کہ میرے اور رسول اللہ صلی اللہ علیہ وسلم کے سوا اور کوئی نہ بچا ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے پھر پانی ڈالا اور مجھ سے فرمایا : ’’ پیو ۔ ‘‘ میں نے عرض کی : اے اللہ کے رسول ! جب تک آپ نہیں پی لیں گے میں نہیں پیوں گا ۔ فرمایا : ’’ قوم کو پانی پلانے والا ان سب سے آخر میں پیتا ہے ۔ ‘‘ کہا : تب میں نے پی لیا اور رسول اللہ صلی اللہ علیہ وسلم نے بھی نوش فرمایا ، کہا : اس کے بعد لوگ اس حالت میں ( اگلے ) پانی پر پہنچے کہ سب ( نے اپنے ) برتن پانی سے بھرے ہوئے تھے اور ( خوب ) سیراب تھے ۔ ( ثابت نے ) کہا ، عبداللہ بن رباح نے کہا : میں یہ حدیث جامع مسجد میں سب لوگوں کو سناؤں گا ۔ تب عمران بن حصین رضی اللہ عنہ نے فرمایا : اے جوان ! خیال رکھنا کہ تم کس طرح حدیث بیان کرتے ہو ، اس رات میں بھی قافلے کے سواروں میں سے ایک تھا ۔ کہا : میں نے عرض کی : آپ اس حدیث کو زیادہ جاننے والے ہیں ۔ تو انھوں نے پوچھا : تم کس قبیلے سے ہو ؟ میں میں نے کہا انصار سے ۔ فرمایا : حدیث بیان کرو تم اپنی احادیث سے زیادہ آگاہ ہو ( انصار میں سے ابو قتادہ رضی اللہ عنہ نے اس سارے واقعے کا سب سے زیادہ اور باریکی سے مشاہدہ کیا تھا بلکہ و ہ اس سارے واقعے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ساتھ تھے ، آگے ان سے سننے والے عبداللہ بن رباح بھی انصار میں سے تھے ۔ ) کہا : میں نے لوگوں کو حدیث سنائی تو عمران رضی اللہ عنہ نے کہا : اس رات میں میں بھی موجود تھا اور مین نہیں سمجھتاکہ اسے کسی نے اس طرح یا در کھا جس طرح تم نے اسے یا درکھا ہے ۔","",{"u2":"ثابت نے عبداللہ بن رباح سے اور انھوں نے حضرت ابو قتادہ رضی اللہ عنہ سےر وایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطاب فرمایا اور کہا: ’’تم اپنی (پوری)شام اور (پوری)رات چلتے رہو گے تو ان شاء اللہ کل تک پانی پر پہنچ جاؤ گے۔‘‘ لوگ چل پڑے، کوئی مڑ کر دوسرے کی طرف دیکھتا بھی نہ تھا۔ ابو قتادہ رضی اللہ عنہ نے کہا: اسی عالم میں رسول اللہ صلی اللہ علیہ وسلم چلتے رہے یہاں تک کہ رات آدھی گزر گئی، میں آپ کے پہلو میں چل رہا تھا، کہا: تو رسول اللہ صلی اللہ علیہ وسلم کو اونگھ آگئی اور آپ سواری سے ایک طرف جھک گئے،میں آپ کے پاس آیا اور آپ کو جگائے بغیر آپ کو سہارا دیا حتی کہ آپ اپنی سواری پر سیدھے ہو گئے، پھر آپ چلتے رہے یہا ں تک کہ رات کا بیشتر حصہ گزر گیا، آپ (پھر)سواری پر (ایک طرف)جھکے، کہا: میں نے آپ کو جگائے بغیر آپ کو سہارا دیا یہاں تک کہ آپ اپنی سواری پر سیدھے ہو گئے، کہا: پھر چلتے رہے حتی کہ سحری کا آخری وقت تھا تو آپ (پھر)جھکے، یہ جھکنا پہلے دونزں بار کے جھکنے سے زیادہ تھا، قریب تھا کہ آپ اونٹ سے گر پڑتے، میں آپ کے پاس آیا اور آپ کو سہارا دیاتو آپ نے اپنا سر مبارک اٹھایا اور فرمایا: ’’یہ کون ہے؟ ‘‘ میں نے عرض کی: ابو قتادہ ہوں۔ فرمایا:’’تم کب سے میرے ساتھ اس طرح چل رہے ہو؟ ‘‘ میں نے عرض کی: میں رات ہی سے اس طرح سفر کر رہا ہوں۔ فرمایا: ’’ اللہ اسی طرح تمھاری حفاظت کرے جس طر ح تم نے اس کے نبی کی حفاظت کی۔ ‘‘ پھر فرمایا:’’ کیا تم دیکھ رہے ہو (کہ)ہم لوگوں سے اوجھل ہیں؟ ‘‘ پھر پوچھا: ’’تمھیں کوئی (اور)نظر آر ہا ہے؟ ‘‘ میں نے عرض کی: یہ ایک سوار ہے۔ پھر عرض کی: یہ ایک اور سوار ہے حتی کہ ہم اکٹھے ہوئے تو سات سوار تھے، کہا: رسول اللہ صلی اللہ علیہ وسلم راستے سے ایک طرف ہٹے، پھر سر (نیچے)رکھ دیا (اور لیٹ گئے)پھر فرمایا:’’ ہمارے لیے ہماری نماز کا خیال رکھنا۔‘‘ پھر جو سب سے پہلے جاگے وہ رسول اللہ صلی اللہ علیہ وسلم ہی تھے، سورج آپ کی پشت پر (چمک رہا)تھا، کہا: ہم سخت تشویش کے عالم میں کھڑے ہوئے، پھر آپ نے فرمایا: ’’سوار ہوجاؤ۔‘‘ ہم سوار ہوئے اور (آگے)چل پڑے حتی کہ جب سورج بلند ہو گیا تو آپ اترے، پھر آپ نے وضو کا برتن مانگا جو میرے ساتھ تھا، اسی میں کچھ پانی تھا، کہا: پھر آپ نے اس سے (مکمل)وضو کے مقابلے میں کچھ ہلکا وضو کیا، اور ا س میں کچھ پانی بچ بھی گیا، پھر آپ نے (مجھے)ابو قتادہ رضی اللہ عنہ سے فرمایا:’’ ہمارے لیے اپنے وضو کا برتن محفوظ رکھنا، اس کی ایک خبر ہو گی۔‘‘ پھر بلال ر رضی اللہ عنہ نے نماز کے لیے اذان کہی، رسول اللہ صلی اللہ علیہ وسلم نے دو رکعتیں پڑھیں، پھر آپ نے اسی طرح جس طرح روز کرتے تھے صبح کی نماز پڑھائی، کہا: اور رسول اللہ صلی اللہ علیہ وسلم سوار ہو گئے ہم بھی آپ کی معیت میں سوار ہو گئے، کہا: ہم میں سے کچھ لوگ ایک دوسرے سے کھسر پھر کرنے لگے کہ ہم نے نماز میں جو کوتاہی کی ہے اس کا کفارہ کیا ہے؟ اس پر آپ نے فرمایا:’’ کیا تمھارے لیے میر ے عمل میں نمونہ نہیں؟ ‘‘ پھر آپ نے فرمایا:’’ سمجھ لو! نیند (آجانے)میں (کسی کی)کوئی کوتاہی نہیں۔ ‘‘ کوتاہی اس کی ہے جس نے (جاگنے کے بعد)دوسری نماز کا وقت آجانے تک نماز نہیں پڑھی، جو اس طرح (نیند)کرے تو جب اس کے لیے جاگے تو یہ نماز پڑھ لے، پھر جب دوسرا دن آئے تو اسے وقت پر ادا کرے۔ ‘‘ پھر فرمایا: ’’تم کیا دیکھتے ہو (دوسرے)لوگوں نےکیا کیا؟ ‘‘ کہا: پھر آپ نے فرمایا: ’’لوگوں نے صبح کی تو اپنے نبی کو گم پایا۔ ابو بکر اور عمر رضی اللہ عنہما نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم تمھارے پیچھے ہیں، وہ ایسے نہیں کہ تمھیں پیچھے چھوڑ دیں۔(دوسرے)لوگوں نے کہا: بے شک رسول اللہ صلی اللہ علیہ وسلم تم سے آگے ہیں۔ اگر وہ ابو بکر اور عمر رضی اللہ عنہما کی ا﷾اعت کریں تو صحیح راستے پر چلیں گے۔‘‘ کیا: تو ہم لوگوں تک (اس وقت)پہنچ پائے جب دن چڑھ آیا تھا اور ہر شے تپ گئی تھی اور وہ کہہ رہے تھے: اے اللہ کے رسول! ہم پیا سے مر گئے۔ تو آپ نے فرمایا: ’’ تم پر کوئی ہلاکت نہیں آئی۔ ‘‘ پھر فرمایا: ’’میرا چھوٹا پیالہ میرے پاس آنے دو۔‘‘ کہا: پھر وضو کے پانی والا برتن منگوایا، رسول اللہ صلی اللہ علیہ وسلم (اس سے پیالے میں)انڈیلتے گئے اور ابو قتادہ رضی اللہ عنہ لوگوں کو پلاتے گئے، زیاد دیر نہ گزری تھ کہ لوگوں نے وضو کے برتن کیں جو (تھوڑا سا پانی)تھا، دیکھ لیا، اس بر جھرمٹ بناکر اکٹھے ہو گے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اچھا طریقہ اختیار کرو، تم میں سے ہر ایک اچھی طرح پیاس بجھا لے گا۔‘‘ کہا: لوگوں نے ایسا ہی کیا، رسول اللہ صلی اللہ علیہ وسلم پانی (پیالے میں)انڈیلتے گئے اور میں لوگوں کو پلاتا گیا یہاں تک کہ میرے اور رسول اللہ صلی اللہ علیہ وسلم کے سوا اور کوئی نہ بچا، کہا: رسول اللہ صلی اللہ علیہ وسلم نے پھر پانی ڈالا اور مجھ سے فرمایا: ’’ پیو۔‘‘ میں نے عرض کی: اے اللہ کے رسول! جب تک آپ نہیں پی لیں گے میں نہیں پیوں گا۔ فرمایا: ’’ قوم کو پانی پلانے والا ان سب سے آخر میں پیتا ہے۔‘‘ کہا: تب میں نے پی لیا اور رسول اللہ صلی اللہ علیہ وسلم نے بھی نوش فرمایا، کہا: اس کے بعد لوگ اس حالت میں (اگلے)پانی پر پہنچے کہ سب(نے اپنے)برتن پانی سے بھرے ہوئے تھے اور (خوب) سیراب تھے۔\n(ثابت نے)کہا، عبداللہ بن رباح نے کہا: میں یہ حدیث جامع مسجد میں سب لوگوں کو سناؤں گا۔ تب عمران بن حصین رضی اللہ عنہ نے فرمایا: اے جوان! خیال رکھنا کہ تم کس طرح حدیث بیان کرتے ہو، اس رات میں بھی قافلے کے سواروں میں سے ایک تھا۔ کہا: میں نے عرض کی: آپ اس حدیث کو زیادہ جاننے والے ہیں۔ تو انھوں نے پوچھا: تم کس قبیلے سے ہو؟ میں میں نے کہا انصار سے۔ فرمایا: حدیث بیان کرو تم اپنی احادیث سے زیادہ آگاہ ہو (انصار میں سے ابو قتادہ رضی اللہ عنہ نے اس سارے واقعے کا سب سے زیادہ اور باریکی سے مشاہدہ کیا تھا بلکہ و ہ اس سارے واقعے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ساتھ تھے، آگے ان سے سننے والے عبداللہ بن رباح بھی انصار میں سے تھے۔)کہا: میں نے لوگوں کو حدیث سنائی تو عمران رضی اللہ عنہ نے کہا: اس رات میں میں بھی موجود تھا اور مین نہیں سمجھتاکہ اسے کسی نے اس طرح یا در کھا جس طرح تم نے اسے یا درکھا ہے۔"}],[1499,"سلم بن زریر عطاری نے کہا : میں نے ابو رجاء عطاری سے سنا ‘ وہ سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کر رہے تھے ‘ کہا : میں نبی صلی اللہ علیہ وسلم کے ایک میں آپ صلی اللہ علیہ وسلم کے ہمراہ تھا ‘ ہم اس رات چلتے رہے حتی کہ جب صبح قریب آئی تو ہم ( تھکاوٹ کے سبب ) اتر پڑے ‘ ہم پر ( نینج میں ڈوبی ) آنکھیں غالب آگئیں یہاں تک کہ سورج چمکنے لگا ۔ ہم میں جو سب سے پہلے بیدار ہوئے وہ سیدنا ابو بکر رضی اللہ عنہ تھے ۔ جب نبی صلی اللہ علیہ وسلم سو جاتے تو ہم آپ صلی اللہ علیہ وسلم کو جگایا نہیں کرتے تھے حتی کہ آپ صلی اللہ علیہ وسلم خود بیدار ہو جاتے ‘ پھر عمر رضی اللہ عنہ جاگے ‘ وہ اللہ کے نبی صلی اللہ علیہ وسلم کے قریب کھڑے ہو گے اور اللہ اکبر پکارنے لگے اور ( اس ) تکبیر میں آواز اونچی کرنے لگے یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم بھی جاگ گئے ‘ جب آپ صلی اللہ علیہ وسلم نے سر اٹھایا اور دیکھا کہ سورج چمک رہا ہےتو فرمایا : ’ ( آگے ) چلو ۔ آپ صلی اللہ علیہ وسلم ہمیں لے کر چلے یہاں تک کہ سورج ( روشن ) ہو کر سفید ہو گیا ‘ آپ اتر ے ‘ ہمیں صبح کی نماز پڑھائی ۔ لوگوں میں سے ایک آدمی الگ ہو گیا اور اس نے ہمارے ساتھ نماز نہ پڑھی ‘ جب سلام پھیرا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے کہا : ’’فلاں!تم نے ہمارے ساتھ نماز کیوں نہیں پڑھی ؟ ‘‘ اس نے کہا : اے اللہ کے نبی !مجھے جنابت لاحق ہوگی ہے ۔ آپ صلی اللہ علیہ وسلم نے اسے حکم دیا ۔ اس نے مٹی سے تیمم کیا اور نماز پڑھی ‘ پھرآپ صلی اللہ علیہ وسلم نے مجھے چند سواروں سمیت پانی کی تلاش میں جلدی اپنے آگے روانہ کیا ‘ ہم سخت پیاسے تھے ‘ جب ہم چل رہے تھے تو ہمیں ایک عورت ملی جس نے اپنے پاؤں دو مشکوں کے درمیان لٹکارکھے تھے ( بقڑی مشکوں سمیت پاؤں لٹکائے ‘ اونٹ پر سوار تھی ) ‘ ہم نے اس سے پوچھا : پانی کہا ں ہے ؟کہنے لگی : افسوس !تمہارے لیے پانی نہیں ہے ۔ ہم نے پوچھا : تمہارے گھر اور پانی کے دریمان کتنا فاصلہ ہے ؟اس نے کہا : ایک دن اور رات کی مسافت ہے ۔ ہم نے کہا : اللہ کے رسول صلی اللہ علیہ وسلم کے پاس چلو ۔ کہنے لگی : اللہ کا رسول کیا ہوتا ہے ؟ہم نے اسے اس کے معاملے میں ( فیصلے کا ) کچھاختیار نہ دیا حتی کہ اسے لے آئےاس کے ساتھ ہم رسول اللہ صلی اللہ علیہ وسلم کے سامنے حاضر ہوئے ‘ آپنے اس سے پوچھا تو اس نے آپکو اسی طرح بتایا جس طرح ہمیں بتایا تھا ‘ اور آپ کو یہ بھی بتایا کہ وہ یتیم بچوں والی ہے ‘ اس کے ( زیر کفالت ) بہت سے یتیم بچے ہیں ۔ آپ نے اس کی پانی ڈھونے والی اونٹنی کے بارے میں حکم دیا ‘ اسے بھٹا دیا گیا اور آپ نے کلی کر کے مسکوں کے اوپر کے دونوں سوراخوں میں پانی ڈالا ‘ پھر آپ نے اس کی اونٹنی کوکھرا کیا تو ہم سب نے اور ہم چالیس ( شدید ) پیاسے افراد تھے ( ان مشکوں سے ) پانی پیا یہاں تک کہ ہم سیراب ہو گے اور ےہمارے پاس جتنی مشکیں اور پانی کے برتن تھے سب بھر لیے اور اپنے ساتھی کو غسل بھی کرا یا ‘ التبہ ہم نے کسی اونٹ کو پانی نہ پیلایا اور وہ یعنی دونوں مشکیں پانی ( کی مقدار زیادہ ہو جانے کے سبب ) پھٹنے والی ہو گیئں ‘ پھر آپ نے فرمایا : ’’تمہارے پاس جو کچھ ہے ‘ لے آؤ ۔ ‘‘ ہم نے ٹکڑے اور کھجوریں اکٹھی کیں ‘ اس کے لیے ایک تھیلی کا منہ بند کر دیا گیا تو آپ نےاس سے کہا : ’’جاؤ اور یہ خوراک اپنے بچوں کو کھلا ؤ اور جان لو !ہم نے تمہارے پانی میں کمی نہیں ۔ ‘‘ جب وہ اپنے گھر والوں کے پاس پہنچی تو کہا : میں انسانوں کے سب سے بڑے ساحر سے مل کر آئی ہوں یا پھر جس طرحکہ وہ خود کو سمجھتا ہے ‘ وہ نبی ہے ‘ اور اس کا معملہ اس اس کرح سے ہے ۔ پھر ( آخر کار ) اللہ نے اس عورت کے سبب سے لوگوں سے کٹی ہوئی اس آبادی کو ہدایت عطا کر دی ‘ وہ مسلمان ہوگی اور ( باقی ) لوگ بھی مسلمان ہو گے ۔ ( یہ پچھلے واقعے سے ملتا جلتا ایک اور واقعہ ہے ۔)","",{"u2":"سلم بن زریر عطاری نے کہا:میں نے ابو رجاء عطاری سے سنا ‘وہ حضرت عمران بن حصین رضی اللہ عنہ سے روایت کر رہے تھے ‘کہا:میں نبی صلی اللہ علیہ وسلم کے ایک میں آپ صلی اللہ علیہ وسلم کے ہمراہ تھا ‘ہم اس رات چلتے رہے حتی کہ جب صبح قریب آئی تو ہم (تھکاوٹ کے سبب)اتر پڑے ‘ہم پر (نینج میں ڈوبی)آنکھیں غالب آگئیں یہاں تک کہ سورج چمکنے لگا۔ہم میں جو سب سے پہلے بیدار ہوئے وہ حضرت ابو بکر رضی اللہ عنہ تھے۔جب نبی صلی اللہ علیہ وسلم سو جاتے تو ہم آپ صلی اللہ علیہ وسلم کو جگایا نہیں کرتے تھے حتی کہ آپ صلی اللہ علیہ وسلم خود بیدار ہو جاتے‘پھر عمر رضی اللہ عنہ جاگے ‘وہ اللہ کے نبی صلی اللہ علیہ وسلم کے قریب کھڑے ہو گے اور اللہ اکبر پکارنے لگے اور (اس)تکبیر میں آواز اونچی کرنے لگے یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم بھی جاگ گئے‘جب آپ صلی اللہ علیہ وسلم نے سر اٹھایا اور دیکھا کہ سورج چمک رہا ہےتو فرمایا:’(آگے)چلو۔ آپ صلی اللہ علیہ وسلم ہمیں لے کر چلے یہاں تک کہ سورج (روشن)ہو کر سفید ہو گیا ‘آپ اتر ے‘ہمیں صبح کی نماز پڑھائی۔لوگوں میں سے ایک آدمی الگ ہو گیا اور اس نے ہمارے ساتھ نماز نہ پڑھی ‘جب سلام پھیرا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے کہا:’’فلاں!تم نے ہمارے ساتھ نماز کیوں نہیں پڑھی؟‘‘اس نے کہا:اے اللہ کے نبی!مجھےےجنابت لاحق ہوگی ہے۔آپ صلی اللہ علیہ وسلم نے اسے حکم دیا۔اس نے مٹی سے تیمم کیا اور نماز پڑھی ‘پھرآپ صلی اللہ علیہ وسلم نے مجھےےچند سواروں سمیت پانی کی تلاش میں جلدی اپنے آگے روانہ کیا ‘ہم سخت پیاسے تھے ‘جب ہم چل رہے تھے تو ہمیں ایک عورت ملی جس نے اپنے پاؤں دو مشکوں کے درمیان لٹکارکھےے تھے (بقڑی مشکوں سمیت پاؤں لٹکائے ‘اونٹ پر سوار تھی)‘ہم نے اس سے پوچھا:پانی کہا ں ہے؟کہنے لگی:افسوس!تمہارے لیے پانی نہیں ہے۔ہم نے پوچھا:تمہارے گھر اور پانی کے دریمان کتنا فاصلہ ہے؟اس نے کہا:ایک دن اور رات کی مسافت ہے۔ہم نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم کے پاس چلو۔کہنے لگی:اللہ کا رسول کیا ہوتا ہے؟ہم نے اسے اس کے معاملے میں (فیصلےکا)کچھاختیار نہ دیا حتی کہ اسے لے آئےاس کے ساتھ ہم رسول اللہ صلی اللہ علیہ وسلم کے سامنے حاضر ہوئے ‘آپنے اس سے پوچھا تو اس نے آپکو اسی طرح بتایا جس طرح ہمیں بتایا تھا‘اور آپ کو یہ بھی بتایا کہ وہ یتیم بچوں والی ہے ‘اس کے (زیر کفالت)بہت سے یتیم بچے ہیں۔آپ نے اس کی پانی ڈھونے والی اونٹنی کے بارے میں حکم دیا ‘ اسے بھٹا دیا گیا اور آپ نے کلی کر کے مسکوں کے اوپر کے دونوں سوراخوں میں پانی ڈالا‘پھر آپ نے اس کی اونٹنی کوکھرا کیا تو ہم سب نے اور ہم چالیس (شدید)پیاسے افراد تھے(ان مشکوں سے)پانی پیا یہاں تک کہ ہم سیراب ہو گے اور ےہمارے پاس جتنی مشکیں اور پانی کے برتن تھے سب بھر لیے اور اپنے ساتھی کو غسل بھی کرا یا ‘التبہ ہم نےکسی اونٹ کو پانی نہ پیلایا اور وہ یعنی دونوں مشکیں پانی (کی مقدار زیادہ ہو جانے کے سبب)پھٹنے والی ہو گیئں ‘پھر آپ نے فرمایا:’’تمہارےپاس جو کچھ ہے ‘لے آؤ۔‘‘ہم نے ٹکڑے اور کھجوریں اکٹھی کیں ‘اس کے لیے ایک تھیلی کا منہ بند کر دیا گیا تو آپ نےاس سے کہا:’’جاؤ اور یہ خوراک اپنے بچوں کو کھلا ؤ اور جان لو!ہم نے تمہارے پانی میں کمی نہیں۔‘‘جب وہ اپنے گھر والوں کے پاس پہنچی تو کہا:میں انسانوں کے سب سے بڑے ساحر سے مل کر آئی ہوں یا پھر جس طرحکہ وہ خود کو سمجھتا ہے‘وہ نبی ہے ‘اور اس کا معملہ اس اس کرح سے ہے۔پھر (آخر کار)اللہ نے اس عورت کے سبب سے لوگوں سے کٹی ہوئی اس آبادی کو ہدایت عطا کر دی ‘وہ مسلمان ہوگی اور (باقی)لوگ بھی مسلمان ہو گے۔(یہ پچھلے واقعے سے ملتا جلتا ایک اور واقعہ ہے۔)"}],[1500,"عوف بن ابی جمیلہ اعرابی نے ابو رجاء عطاری سے ‘ انھوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی ‘ کہا : ہم ایک سفر کے دوران میں رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ تھے ‘ ہم ایک رات چلے ‘ جب رات کا آخری حصہ آیا ‘ صبح سے ٹھوڑی دیر پہلے ہم اس طرح پڑکر سو گئے کہ اس سے زیادہ میٹھی نیند ایک مسافر کے لیے اور کوئی نہیں ہو سکتی ‘ ہمیں سورج کی حرارت ہی نے جگایا ....پھر سلم بن زریر کی حدیث کی طرح حدیث سنائی اور کچھ کمی بیشی بھی اور ( اپنی روایت کردہ ) حدیث میں انھوں نے کہا : جب عمر بن خطاب رضی اللہ عنہ جاگے اور لوگوں کی صورت حال دیکھی ‘ اور وہ بلند آواز آدمی تھے تو انھوں نے اونچی آواز سے اللہ اکبر کہا حتی کہ رسول اللہ صلی اللہ علیہ وسلم ان کے اونچے اللہ اکبر کہنے سے جاگ گئے ‘ جب اللہ کے رسول صلی اللہ علیہ وسلم جاگ گئے تو لوگوں نے اپنے اس معاملے کی شکایت کی تو آپ صلی اللہ علیہ وسلم نے فرمایا : ’’کوئی ( بڑا ) نقصان نہیں ہوا ‘ ( آگئے ) چلو ۔ ‘‘ ......آگے وہی حدیث بیان کی ۔","",{"u2":")عوف بن ابی جمیلہ اعرابی نے ابو رجاء عطاری سے ‘انھوں نے حضرت عمران بن حصین رضی اللہ عنہ سے روایت کی ‘کہا:ہم ایک سفر کے دوران میں رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ تھے ‘ہم ایک رات چلے ‘جب رات کا آخری حصہ آیا‘صبح سے ٹھوڑی دیر پہلے ہم اس طرح پڑکر سو گئے کہ اس سے زیادہ میٹھی نیند ایک مسافر کے لیے اور کوئی نہیں ہو سکتی‘ہمیں سورج کی حرارت ہی نے جگایا ....پھر سلم بن زریر کی حدیث کی طرح حدیث سنائی اور کچھ کمی بیشی بھی اور (اپنی روایت کردہ) حدیث میں انھوں نے کہا: جب عمر بن خطاب رضی اللہ عنہ جاگے اور لوگوں کی صورت حال دیکھی ‘اور وہ بلند آواز آدمی تھے تو انھوں نے اونچی آواز سے اللہ اکبر کہا حتی کہ رسول اللہ صلی اللہ علیہ وسلم ان کے اونچے اللہ اکبرکہنے سے جاگ گئے ‘جب اللہ کے رسول صلی اللہ علیہ وسلم جاگ گئے تو لوگوں نے اپنے اس معاملے کی شکایت کی تو آپ صلی اللہ علیہ وسلم نے فرمایا:’’کوئی (بڑا)نقصان نہیں ہوا ‘(آگئے)چلو۔‘‘......آگے وہی حدیث بیان کی۔"}],[1501,"سیدنا ابو قتادہ رضی اللہ عنہ سے روایت ہے ‘ کہا : رسول اللہ صلی اللہ علیہ وسلم جب سفر میں ہوتے اور رات ( کے آخری حصے ) میں آرام کے لیے لیٹے تو دائیں پہلو پر لیٹتے اور جب صبح سے ذرا پہلو پر لیٹتے تو اپنی کہنی کھڑی کر لیتے اور سر ہتھیلی پر ٹکا لیتے ۔ ( تاکہ زیادہ گہری نیند نہ آئے ۔ اس حدیث کے الفاظ بھی اس بات کی تائید کرتے ہیں کہ اوپر بیان کیے گئے دو الگ الگواقعے ہیں ۔)","",{"u2":"حضرت ابو قتادہ رضی اللہ عنہ سے روایت ہے ‘کہا:رسول اللہ صلی اللہ علیہ وسلم جب سفر میں ہوتے اور رات (کے آخری حصے)میں آرام کے لیے لیٹے تو دائیں پہلو پر لیٹتے اور جب صبح سے ذرا پہلو پر لیٹتے تو اپنی کہنی کھڑی کر لیتے اور سر ہتھیلی پر ٹکا لیتے۔(تاکہ زیادہ گہری نیند نہ آئے۔ اس حدیث کے الفاظ بھی اس بات کی تائید کرتے ہیں کہ اوپر بیان کیے گئے دو الگ الگواقعے ہیں۔)"}],[1502,"ہمام نے ہمیں حدیث سنائی ‘ کہا : ہمیں قتادہ نے سیدنا انس بن مالک رضی اللہ عنہ کے حوالے سے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جو شخص کوئی نماز بھول جائے تو جیسے ہی وہ اسے یاد آئے ‘ وہ نماز پڑھ لے ‘ اس نماز کا اس کے علاوہ اور کوئی کفارہ نہیں ۔ ‘‘","",{"u2":"ہمام نے ہمیں حدیث سنائی ‘کہا:ہمیں قتادہ نے حضرت انس بن مالک رضی اللہ عنہ کے حوالے سے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جو شخص کوئی نماز بھول جائے تو جیسے ہی وہ اسے یاد آئے ‘وہ نماز پڑھ لے ‘اس نماز کا اس کے علاوہ اور کوئی کفارہ نہیں۔‘‘"}],[1503,"ابو عوانہ نے قتادہ سے ‘ انھوں نے سیدنا انس رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے یہ ( یہی حدیث ) روایت کی ‘ البتہ انھوں نے ’’اس کے علاوہ اس کا اور کوئی کفارہ نہیں ‘‘ کے الفاظ روایت نہیں کیے ۔","",{"u2":"ابو عوانہ نے قتادہ سے ‘انھوں نے حضرت انس رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے یہ(یہی حدیث)روایت کی ‘البتہ انھوں نے ’’اس کے علاوہ اس کا اور کوئی کفارہ نہیں ‘‘کے الفاظ روایت نہیں کیے۔"}],[1504,"سعید نے قتادہ سے اور انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے حدیث سنائی ‘ کہا : اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا : ‘‘ جو شخص کوئی نماز بھول گیا یا اسے ادا کرتے وقت سوتا رہ گیا تو اس ( نماز ) کا کفارہ یہی ہے کہ جب اسے یاد آئے وہ اس نماز کو پڑھ لے ۔ ‘‘","",{"u2":"سعید نے قتادہ سے اور انھوں نے حضرت انس بن مالک رضی اللہ عنہ سےحدیث سنائی ‘کہا:اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا:‘‘جو شخص کوئی نماز بھول گیا یا اسے ادا کرتے وقت سوتا رہ گیا تو اس (نماز)کا کفارہ یہی ہے کہ جب اسے یاد آئے وہ اس نماز کو پڑھ لے۔‘‘"}],[1505,"مثنیٰ نے قتادہ کے حوالے سے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ‘ کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کوئی نماز ( پڑھنے کے وقت اس ) سے سویا رہے یا اس سے غافل ہو جائے تو جب اسے یاد آئےوہ ( نماز ) پڑھ لے ‘ بے شک اللہ تعالیٰ نے ( خود ) ارشاد فرمایا ہے : اور میر ییاد کے وقت نماز قائم کرو ۔ ‘‘","",{"u2":"مثنیٰ نے قتادہ کے حوالے سے حضرت انس بن مالک رضی اللہ عنہ سے روایت کی ‘کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب تم میں سے کوئی نماز (پڑھنے کے وقت اس)سے سویا رہے یا اس سے غافل ہو جائے تو جب اسے یاد آئےوہ (نماز)پڑھ لے ‘بے شک اللہ تعالیٰ نے (خود)ارشاد فرمایا ہے:اور میر ییاد کے وقت نماز قائم کرو۔‘‘"}],[1506,"صالح بن کیسان نے عروہ بن زبیر سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا ، سفر اور حضر ( مقیم ہونے کی حالت ) میں نماز دو دور رکعت فرض کی گئی تھی ، پھر سفر کی نماز ( پہلی حالت پر ) قائم رکھی گئی اور حضر کی نماز میں اضافہ کردیا گیا ۔","",{"u2":"صالح بن کیسان نے عروہ بن زبیر سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا،سفر اور حضر(مقیم ہونے کی حالت) میں نماز دو دور رکعت فرض کی گئی تھی،پھر سفر کی نماز(پہلی حالت پر) قائم رکھی گئی اور حضر کی نماز میں اضافہ کردیا گیا۔"}],[1507,"یونس نے ابن شہاب سے روایت کی ، انھوں نے کہا ، مجھے عروہ بن زبیر نے حدیث بیان کی ، کہ نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ صدیقہ رضی اللہ تعالیٰ عنہا نے کہا : جب اللہ تعالیٰ نے نماز فرض کی تو وہ دو رکعت فرض کی ، پھر حضر کی صورت میں اسے مکمل کردیا اور سفر کی نماز کو پہلے فریضے پر قائم رکھاگیا ۔","",{"u2":"یونس نے ابن شہاب سے روایت کی،انھوں نے کہا،مجھے عروہ بن زبیر نے حدیث بیان کی،کہ نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ صدیقہ رضی اللہ تعالیٰ عنہا نے کہا:جب اللہ تعالیٰ نےنماز فرض کی تو وہ دو رکعت فرض کی،پھر حضر کی صورت میں اسے مکمل کردیا اور سفر کی نماز کو پہلے فریضے پر قائم رکھاگیا۔"}],[1508,"ابن عینیہ نے زہری سے انھوں نے عروہ سے اور انھوں نے سیدہ عائشہ صدیقہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ ابتدا میں نماز دو رکعت فرض کی گئی ، پھر سفر کی نماز ، ( اسی حالت میں ) برقرار رکھی گئی اور حضر کی نماز مکمل کردی گئی ۔ امام زہری نے کہا : میں نے عروہ سے پوچھا سیدہ عائشہ رضی اللہ تعالیٰ عنہا کا موقف کیا ہے ۔ وہ سفر میں پوری نماز ( کیوں ) پڑھتی تھیں؟انھوں نے کہا : انھوں نے اس کا ایک مفہوم لے لیا ہے جس طرح عثمان رضی اللہ تعالیٰ عنہ نے لیا ۔","",{"u2":"ابن عینیہ نے زہری سے انھوں نے عروہ سے اور انھوں نے حضرت عائشہ صدیقہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ ابتدا میں نماز دو رکعت فرض کی گئی،پھر سفر کی نماز،(اسی حالت میں) برقرار رکھی گئی اور حضر کی نماز مکمل کردی گئی۔\nامام زہری نے کہا: میں نے عروہ سے پوچھا حضرت عائشہ رضی اللہ تعالیٰ عنہا کا موقف کیا ہے۔وہ سفر میں پوری نماز(کیوں) پڑھتی تھیں؟انھوں نے کہا:انھوں نے اس کا ایک مفہوم لے لیا ہے جس طرح عثمان رضی اللہ تعالیٰ عنہ نے لیا۔"}],[1509,"عبداللہ بن ادریس نے ابن جریج سے ، انھوں نے ابن ابی عمار سے ، انھوں نے عبداللہ بن بابیہ سے اور انھوں نے یعلیٰ بن امیہ رضی اللہ تعالیٰ عنہ سے روایت کی : کہا : میں نے سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ سے عرض کی ( کہ اللہ تعالیٰ کا فرمان ہے ) \" اگر تمھیں خوف ہو کہ کافر تمھیں فتنے میں ڈال دیں گے تو تم پر کوئی حرج نہیں ہے کہ تم نماز قصر کرلو \" اب تو لوگ امن میں ہیں ( پھر قصر کیوں کرتے ہیں؟تو انھوں نے جواب دیا مجھے بھی اس بات پر تعجب ہو ا تھا جس پر تمھیں تعجب ہوا ہے ۔ تو میں نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں سوا ل کیا تھا ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" ( یہ ) صدقہ ( رعایت ) ہے جو اللہ تعالیٰ نے تم پر کیا ہے اس لئے تم اس کا صدقہ قبول کرو ۔","",{"u2":"عبداللہ بن ادریس نے ابن جریج سے،انھوں نے ابن ابی عمار سے،انھوں نے عبداللہ بن بابیہ سے اور انھوں نے یعلیٰ بن امیہ رضی اللہ تعالیٰ عنہ سے روایت کی:کہا:میں نے حضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ سے عرض کی(کہ اللہ تعالیٰ کا فرمان ہے)\"اگر تمھیں خوف ہو کہ کافر تمھیں فتنے میں ڈال دیں گے تو تم پر کوئی حرج نہیں ہے کہ تم نماز قصر کرلو\"اب تو لوگ امن میں ہیں(پھر قصر کیوں کرتے ہیں؟تو انھوں نے جواب دیا مجھے بھی اس بات پر تعجب ہو ا تھا جس پر تمھیں تعجب ہوا ہے۔تو میں نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں سوا ل کیا تھا،آپ صلی اللہ علیہ وسلم نے فرمایا:\"(یہ) صدقہ (رعایت) ہے جو اللہ تعالیٰ نے تم پر کیا ہے اس لئے تم اس کا صدقہ قبول کرو۔\""}],[1510,"یحییٰ نے ابن جریج سے سابقہ سند کے ساتھ سیدنا یعلیٰ بن امیہ رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا! میں نے سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ سے عرض کی ۔ ۔ ۔ ( بقیہ روایت ) ابن ادریس کی حدیث کی طرح ہے ۔","",{"u2":"یحییٰ نے ابن جریج سے سابقہ سند کے ساتھ حضرت یعلیٰ بن امیہ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا! میں نے حضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ سے عرض کی۔۔۔(بقیہ روایت) ابن ادریس کی حدیث کی طرح ہے۔"}],[1511,"ابو عوانہ نے بکیر بن اخنس سے ، انھوں نے مجاہد سے ، انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : اللہ تعالیٰ نے تمھارے نبی صلی اللہ علیہ وسلم کی زبان سے نماز فرض کی ، حضر ( جب مقیم ہوں ) میں چار رکعتیں ، سفر میں دو رکعتیں اور خوف ( جنگ ) میں ( امام کے ساتھ ) ایک رکعت ( پھر اس کی امامت کے بغیر ایک رکعت ) ۔","",{"u2":"ابو عوانہ نے بکیر بن اخنس سے،انھوں نے مجاہد سے،انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:اللہ تعالیٰ نے تمھارے نبی صلی اللہ علیہ وسلم کی زبان سے نماز فرض کی،حضر(جب مقیم ہوں) میں چار رکعتیں،سفر میں دو رکعتیں اور خوف (جنگ) میں (امام کے ساتھ) ایک رکعت (پھر اس کی امامت کے بغیر ایک رکعت)۔"}],[1512,"ایوب بن عائد طائی نے بکیر بن اخنس سے ، انھوں نے م مجاہد سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے حدیث بیان کی ، کہا!بے شک اللہ تعالیٰ نے تمھارے نبی صلی اللہ علیہ وسلم کی زبان سے نماز فرض کی ، مسافر پردو رکعتیں ، مقیم پر چار اور ( جنگ کے ) خوف کے عالم میں ( امام کی اقتداء میں ) ایک رکعت ( اور اقتدا کے بغیر ایک رکعت ) ۔","",{"u2":"ایوب بن عائد طائی نے بکیر بن اخنس سے،انھوں نے م مجاہد سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے حدیث بیان کی،کہا!بے شک اللہ تعالیٰ نے تمھارے نبی صلی اللہ علیہ وسلم کی زبان سے نماز فرض کی،مسافر پردو رکعتیں،مقیم پر چار اور (جنگ کے) خوف کے عالم میں (امام کی اقتداء میں) ایک رکعت (اور اقتدا کے بغیر ایک رکعت)۔"}],[1513,"شعبہ نے کہا : میں نے قتادہ سے سنا ، وہ موسیٰ بن سلمہ ہذلی ( بصری ) سے حدیث بیان کررہے تھے ۔ کہا : میں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے پوچھا : جب میں مکہ میں ہوں اور امام کے ساتھ نماز نہ پڑھوں تو پھر کیسے نماز پڑھوں؟تو انھوں نے جواب دیا : دو رکعتیں ، ( یہی ) ابو القاسم صلی اللہ علیہ وسلم کی سنت ہے ۔","",{"u2":"شعبہ نے کہا:میں نے قتادہ سے سنا،وہ موسیٰ بن سلمہ ہذلی (بصری) سے حدیث بیان کررہے تھے۔کہا: میں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے پوچھا:جب میں مکہ میں ہوں اور امام کے ساتھ نماز نہ پڑھوں تو پھر کیسے نماز پڑھوں؟تو انھوں نے جواب دیا:دو رکعتیں،(یہی) ابو القاسم صلی اللہ علیہ وسلم کی سنت ہے۔"}],[1514,"(شعبہ کی بجائے ) سعید بن ابی عروبہ اور معاذ بن ہشام نے اپنے والد کے واسطے سے قتادہ سے ، اسی مذکورہ سند کےساتھ اسی طرح ( حدیث بیان کی ) ۔","",{"u2":"(شعبہ کی بجائے) سعید بن ابی عروبہ اور معاذ بن ہشام نے اپنے والد کے واسطے سے قتادہ سے،اسی مذکورہ سند کےساتھ اسی طرح (حدیث بیان کی)۔"}],[1515,"عیسیٰ بن حضص بن عاصم بن عمر بن خطاب رضی اللہ تعالیٰ عنہ نے اپنے والد ( حفص ) سے روایت کی ، انھوں نے کہا : میں نے مکہ کے راستے میں سیدنا ابن عمر رضی اللہ تعالیٰ عنہ کے ساتھ سفر کیا ، انھوں نے ہمیں ظہر کی نماز دو رکعتیں پڑھائی ، پھر وہ اور ہم آگے بڑھے اور اپنی قیام گاہ پر آئے اور بیٹھ گئے ، ہم بھی ان کے ساتھ بیٹھ گئے ۔ پھر اچانک ان کی توجہ اس طرف ہوئی جہاں انھوں نے نماز پڑھی تھی ، انھوں نے ( وہاں ) لوگوں کو قیام کی حالت میں دیکھا انھوں نے پوچھا ، یہ لوگ کیا کررہے ہیں؟میں نے کہا : سنتیں پڑھ رہے ہیں ۔ انھوں نے کہا : اگر مجھے سنتیں پڑھنی ہوتیں تو میں نماز ( بھی ) پوری کرتا ( قصر نہ کرتا ) بھتیجے!میں سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رہا آپ نے دو رکعت سے زائد نماز نہ پڑھی یہاں تک کہ اللہ تعالیٰ نے آپ کو اپنے پاس بلا لیا اور میں سیدنا ابو بکر رضی اللہ تعالیٰ عنہ کے ہمرا ہ رہا انھوں نے بھی دو رکعت سے زائد نماز نہ پڑھی یہاں تک کہ اللہ تعالیٰ نے انھیں بھی بلا لیا ، اور میں سیدنا عمر رضی اللہ تعالیٰ عنہ کے ہمراہ رہا ، انھوں نے بھی دو رکعت نما ز سے زائد نہ پڑھی ۔ یہاں تک کہ اللہ تعالیٰ نے انھیں بھی بلا لیا ۔ پھر میں عثمان رضی اللہ تعالیٰ عنہ کے ساتھ رہا انہوں نے بھی دو سے زائد رکعتیں نہیں پڑھیں ، یہا ں تک کہ اللہ نے انھیں بلا لیا اور اللہ تعالیٰ کا فرمان ہے : \" بے شک تمہارے لئے رسول اللہ صلی اللہ علیہ وسلم ( کے عمل ) میں بہترین نمونہ ہے ۔","",{"u2":"عیسیٰ بن حضص بن عاصم بن عمر بن خطاب رضی اللہ تعالیٰ عنہ نے اپنے والد (حفص) سے روایت کی،انھوں نے کہا:میں نے مکہ کے راستے میں حضرت ابن عمر رضی اللہ تعالیٰ عنہ کے ساتھ سفر کیا،انھوں نے ہمیں ظہر کی نماز دو رکعتیں پڑھائی،پھر وہ اور ہم آگے بڑھے اور اپنی قیام گاہ پر آئے اور بیٹھ گئے،ہم بھی ان کے ساتھ بیٹھ گئے۔پھر اچانک ان کی توجہ اس طرف ہوئی جہاں انھوں نے نماز پڑھی تھی،انھوں نے(وہاں) لوگوں کو قیام کی حالت میں دیکھاانھوں نےپوچھا،یہ لوگ کیا کررہے ہیں؟میں نے کہا:سنتیں پڑھ رہے ہیں۔انھوں نے کہا:اگر مجھے سنتیں پڑھنی ہوتیں تو میں نماز (بھی) پوری کرتا(قصر نہ کرتا)بھتیجے!میں سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رہا آپ نے دو رکعت سے زائد نماز نہ پڑھی یہاں تک کہ اللہ تعالیٰ نے آپ کو اپنے پاس بلا لیا اور میں حضرت ابو بکر رضی اللہ تعالیٰ عنہ کے ہمرا ہ رہا انھوں نے بھی دو رکعت سے زائد نماز نہ پڑھی یہاں تک کہ اللہ تعالیٰ نے انھیں بھی بلا لیا،اور میں حضرت عمر رضی اللہ تعالیٰ عنہ کے ہمراہ رہا، انھوں نے بھی دورکعت نما ز سے زائد نہ پڑھی۔یہاں تک کہ اللہ تعالیٰ نے انھیں بھی بلا لیا۔پھر میں عثمان رضی اللہ تعالیٰ عنہ کے ساتھ رہا انہوں نے بھی دو سے زائد رکعتیں نہیں پڑھیں،یہا ں تک کہ اللہ نے انھیں بلا لیا اور اللہ تعالیٰ کا فرمان ہے:\"بے شک تمہارے لئے رسول اللہ صلی اللہ علیہ وسلم (کے عمل) میں بہترین نمونہ ہے۔\""}],[1516,"عمر بن محمد نے حفص بن عاصم سے روایت کی ، کہا : میں بیمار ہوا تو ( عبداللہ ) بن عمر رضی اللہ تعالیٰ عنہ میر عیادت کرنے آئے کہا : میں نے ان سے سفر میں سنتیں پڑھنے کے بارے میں سوال کیا ۔ انھوں نے کہا : میں سفر کے دوران رسول اللہ صلی اللہ علیہ وسلم کے ہمرا رہا ہوں ۔ میں نے دیکھا کہ آپ سنتیں پڑھتے ہوں ، اور اگر مجھے سنتیں پڑھنی ہوتیں تو میں نماز ہی پوری پڑھتا ۔ اللہ تعالیٰ نے فرمایا ہے : \" بے شک تمہارے لئے رسول اللہ صلی اللہ علیہ وسلم ( کے عمل ) میں بہترین نمونہ ہے ۔","",{"u2":"عمر بن محمد نے حفص بن عاصم سے روایت کی،کہا:میں بیمار ہواتو(عبداللہ) بن عمر رضی اللہ تعالیٰ عنہ میر عیادت کرنے آئےکہا:میں نے ان سے سفر میں سنتیں پڑھنے کے بارے میں سوال کیا۔انھوں نے کہا:میں سفر کے دوران رسول اللہ صلی اللہ علیہ وسلم کے ہمرا رہا ہوں۔میں نے دیکھا کہ آپ سنتیں پڑھتے ہوں،اور اگر مجھے سنتیں پڑھنی ہوتیں تو میں نماز ہی پوری پڑھتا۔اللہ تعالیٰ نے فرمایا ہے:\" بے شک تمہارے لئے رسول اللہ صلی اللہ علیہ وسلم (کے عمل) میں بہترین نمونہ ہے۔"}],[1517,"ابو قلابہ نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ میں ظہر کی چار رکعات پڑھیں اور ذوالحلیفہ میں عصر کی دو رکعتیں پڑھیں ۔","",{"u2":"ابو قلابہ نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ میں ظہر کی چار رکعات پڑھیں اور ذوالحلیفہ میں عصر کی دو رکعتیں پڑھیں۔"}],[1518,"محمد بن منکدر اور ابراہیم بن میسرہ دونوں نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے سنا کہہ رہے تھے : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ میں ظہر کی چار رکعات پڑھیں اور آ پ کے ساتھ ذوالحلیفہ میں عصر کی دو رکعتیں پڑھیں ۔","",{"u2":"محمد بن منکدر اور ابراہیم بن میسرہ دونوں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے سنا کہہ رہے تھے: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ میں ظہر کی چار رکعات پڑھیں اور آ پ کے ساتھ ذوالحلیفہ میں عصر کی دو رکعتیں پڑھیں۔"}],[1519,"شعبہ نے یحییٰ بن یزید ہنائی سے روایت کی ، کہا : کہا میں نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے نماز قصر کرنے کے بارے میں پوچھا توانھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب تین میل یا تین فرسخ کی مسافت پر نکلتے ۔ مسافت کے بارے میں شک کرنے والے شعبہ ہیں ۔ تو دو رکعت نماز پڑھتے ۔","",{"u2":"شعبہ نے یحییٰ بن یزید ہنائی سے روایت کی،کہا: کہا میں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے نماز قصر کرنے کے بارے میں پوچھا توانھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم جب تین میل یا تین فرسخ کی مسافت پر نکلتے۔مسافت کے بارے میں شک کرنے والے شعبہ ہیں۔تو دو رکعت نماز پڑھتے۔"}],[1520,"عبدالرحمان بن مہدی ، نے حدیث بیان کی کہا : ہمیں شعبہ نے یزید بن خمیر سے حدیث سنائی ۔ انہوں نے حبیب بن عبید سے انھوں نے جبیر بن نفیر سے روایت کی ، انھوں نے کہا : می شرجیل بن سمط ( الکندی ) کی معیت میں ایک بستی کو گیا جو سترہ یا اٹھارہ میل کے فاصلے پر تھی تو انھوں نے دو رکعت نماز پڑھی ، میں نے ان سے پوچھا ، انھوں نے جواب دیا : میں نے سیدنا عمر رضی اللہ تعالیٰ عنہ کو ذوالحلیفہ میں دو رکعت پڑھتے دیکھا ہے ، تو میں نے ان ( سیدنا عمر رضی اللہ تعالیٰ عنہ ) سے پوچھا ، انھوں نے جواب دیا : میں اسی طرح کرتا ہوں جس طرح میں نے رسول اللہ صلی اللہ علیہ وسلم کو کرتے دیکھا ہے ۔","",{"u2":"عبدالرحمان بن مہدی، نے حدیث بیان کی کہا:ہمیں شعبہ نے یزید بن خمیر سے حدیث سنائی۔انہوں نے حبیب بن عبید سے انھوں نے جبیر بن نفیر سے روایت کی،انھوں نے کہا:می شرجیل بن سمط(الکندی) کی معیت میں ایک بستی کو گیا جو سترہ یا اٹھارہ میل کے فاصلے پر تھی تو انھوں نے دو رکعت نماز پڑھی،میں نے ان سے پوچھا،انھوں نے جواب دیا:میں نے حضرت عمر رضی اللہ تعالیٰ عنہ کو ذوالحلیفہ میں دو رکعت پڑھتے دیکھا ہے،تو میں نے ان (حضرت عمر رضی اللہ تعالیٰ عنہ) سے پوچھا،انھوں نے جواب دیا: میں اسی طرح کرتا ہوں جس طرح میں نے رسول اللہ صلی اللہ علیہ وسلم کو کرتے دیکھا ہے۔"}],[1521,"محمد بن جعفر نے کہا : ہمیں شعبہ نے اسی سند کے ساتھ یہ حدیث بیان کی اور کہا : ابن سمط سے روایت ہے اور انھوں نے شرجیل کا نام لیا اور کہا : وہ حمص کی دومین نامی جگہ پر پہنچے جو اٹھارہ میل کے فاصلے پر تھی ( اور وہاں نماز قصر پڑھی ) ۔","",{"u2":"محمد بن جعفر نے کہا: ہمیں شعبہ نے اسی سند کے ساتھ یہ حدیث بیان کی اور کہا:ابن سمط سے روایت ہے اور انھوں نے شرجیل کا نام لیا اور کہا:وہ حمص کی دومین نامی جگہ پر پہنچے جو اٹھارہ میل کے فاصلے پر تھی(اور وہاں نماز قصر پڑھی)۔"}],[1522,"ہشیم نے یحییٰ بن ابی اسحاق سے ، انھوں نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ سے مکہ جانے کے لئے نکلے تو آپ دو رکعت نماز پڑھتے رہے یہاں تک کہ مدینہ واپس پہنچ گئے ۔ راوی نے سیدنا انس رضی اللہ تعالیٰ عنہ سے پوچھا : آپ مکہ کتنا عرصہ ٹھرے؟انھوں نے جواب دیا : دس دن ( آپ صلی اللہ علیہ وسلم نے حجۃ الوداع کے موقع پر مکہ آکر خود مکہ ، منیٰ ، عرفات اور مزدلفۃ مختلف مقامات پردس دن گزارے ۔)","",{"u2":"ہشیم نے یحییٰ بن ابی اسحاق سے،انھوں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی،کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ سے مکہ جانے کے لئے نکلے تو آپ دو رکعت نماز پڑھتے رہے یہاں تک کہ مدینہ واپس پہنچ گئے۔\nراوی نے حضرت انس رضی اللہ تعالیٰ عنہ سے پوچھا:آپ مکہ کتنا عرصہ ٹھرے؟انھوں نے جواب دیا:دس دن (آپ صلی اللہ علیہ وسلم نے حجۃ الوداع کے موقع پر مکہ آکر خود مکہ،منیٰ،عرفات اور مزدلفۃ مختلف مقامات پردس دن گزارے۔)"}],[1523,"ابو عوانہ اور ( اسماعیل ) ابن علیہ نے یحییٰ بن ابی اسحاق سے انھو ں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے ہشیم کی حدیث کے مانند حدیث بیان کی ۔","",{"u2":"ابو عوانہ اور (اسماعیل) ابن علیہ نے یحییٰ بن ابی اسحاق سے انھو ں نے حضرت انس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے ہشیم کی حدیث کے مانند حدیث بیان کی۔"}],[1524,"شعبہ نے کہا : مجھے یحییٰ بن ابی اسحاق نے حدیث سنائی ، کہا : میں نےسیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے سنا ، وہ بیان کرتے تھے کہ ہم حج کے لئے مدینہ سے چلے ۔ ۔ ۔ پھر مذکورہ بالا روایت بیان کی ۔","",{"u2":"شعبہ نے کہا:مجھے یحییٰ بن ابی اسحاق نے حدیث سنائی،کہا: میں نےحضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے سنا،وہ بیان کرتے تھے کہ ہم حج کے لئے مدینہ سے چلے۔۔۔پھر مذکورہ بالا روایت بیان کی۔"}],[1525,"(سفیان ) ثوری نے یحییٰ بن ابی اسحاق سے ، انھوں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی سابقہ حدیث کے مانند حدیث وروایت کی اور ( اس میں ) حج کاتذکرہ نہیں کیا ۔","",{"u2":"(سفیان) ثوری نے یحییٰ بن ابی اسحاق سے،انھوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی سابقہ حدیث کے مانند حدیث وروایت کی اور (اس میں) حج کاتذکرہ نہیں کیا۔"}],[1526,"عمرو بن حارث نے ابن شہاب سے ، انھوں نے سالم بن عبداللہ ( بن عمر ) سے ، انھوں نے اپنے والد ( سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ ) سے اور ا نھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے منیٰ اور دوسری جگہوں ، یعنی اس کے نواح میں اور ( آپ صلی اللہ علیہ وسلم کے بعد ) سیدنا ابو بکر اور سیدنا عمر رضی اللہ تعالیٰ عنہ نے مسافر کی نماز ، یعنی دو رکعتیں پڑھیں ۔ اور عثمان رضی اللہ تعالیٰ عنہ نے بھی اپنی خلافت کے ابتدائی سالوں میں دو رکعتیں پڑھیں ، بعد میں پوری چار پڑھنے لگے ۔","",{"u2":"عمرو بن حارث نے ابن شہاب سے،انھوں نے سالم بن عبداللہ(بن عمر) سے،انھوں نے اپنے والد (حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ) سے اور ا نھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے منیٰ اور دوسری جگہوں،یعنی اس کے نواح میں اور (آپ صلی اللہ علیہ وسلم کے بعد) حضرت ابو بکر اورحضرت عمر رضی اللہ تعالیٰ عنہ نے مسافر کی نماز،یعنی دو رکعتیں پڑھیں۔اورعثمان رضی اللہ تعالیٰ عنہ نے بھی اپنی خلافت کے ابتدائی سالوں میں دو رکعتیں پڑھیں،بعد میں پوری چار پڑھنے لگے۔"}],[1527,"اوزاعی اور معمر نے ( اپنی اپنی سند سے روایت کرتے ہوئے ) زہری سے باقی ماندہ اسی سند کے ساتھ یہی حدیث روایت کی ، انھوں نے \" منیٰ میں \" کہا اور \" دوسری جگہوں \" کے الفاظ نہیں کہے ۔","",{"u2":"اوزاعی اور معمر نے(اپنی اپنی سند سے روایت کرتے ہوئے) زہری سے باقی ماندہ اسی سند کے ساتھ یہی حدیث روایت کی،انھوں نے \"منیٰ میں\" کہا اور\" دوسری جگہوں \" کے الفاظ نہیں کہے۔"}],[1528,"ابو اسامہ نے کہا : ہمیں عبیداللہ بن عمر نے نافع سے حدیث سنائی ، انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے منیٰ میں دو رکعتیں پڑھیں ، آپ کے بعد سیدنا ابو بکر رضی اللہ تعالیٰ عنہ نے اور سیدنا ابو بکر رضی اللہ تعالیٰ عنہ کے بعد سیدنا عمر رضی اللہ تعالیٰ عنہ نے اور سیدنا عثمان رضی اللہ تعالیٰ عنہ نے اپنی خلافت کے ابتدائی سالوں میں ( دورکعتیں پڑھیں ) پھر عثمان رضی اللہ تعالیٰ عنہ نے اس کے بعد چار رکعتیں پڑھیں ۔ اس لئے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ جب امام کے ساتھ نماز پڑھتے تو چار رکعات پڑھتے اور جب اکیلے پڑھتے تو وہ رکعتیں پڑھتے ۔","",{"u2":"ابو اسامہ نے کہا:ہمیں عبیداللہ بن عمر نے نافع سے حدیث سنائی،انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،کہا: رسول اللہ صلی اللہ علیہ وسلم نے منیٰ میں دو رکعتیں پڑھیں،آپ کے بعد حضرت ابو بکر رضی اللہ تعالیٰ عنہ نے اور حضرت ابو بکر رضی اللہ تعالیٰ عنہ کے بعد حضرت عمر رضی اللہ تعالیٰ عنہ نے اور حضرت عثمان رضی اللہ تعالیٰ عنہ نے اپنی خلافت کے ابتدائی سالوں میں (دورکعتیں پڑھیں) پھر عثمان رضی اللہ تعالیٰ عنہ نے اس کے بعد چار رکعتیں پڑھیں۔\nاس لئے حضرت ابن عمر رضی اللہ تعالیٰ عنہ جب امام کے ساتھ نماز پڑھتے تو چار رکعات پڑھتے اور جب اکیلے پڑھتے تو وہ رکعتیں پڑھتے۔"}],[1529,"یحییٰ قطان ، ابن ابی زائدہ اور عقبہ بن خالد نے عبیداللہ سے اسی سند کے ساتھ اسی طرح روایت کی ۔","",{"u2":"یحییٰ قطان،ابن ابی زائدہ اور عقبہ بن خالد نے عبیداللہ سے اسی سند کے ساتھ اسی طرح روایت کی۔"}],[1530,"عبیداللہ بن معاذ نے حدیث بیان کی ، کہا : میرے والد نے ہمیں حدیث سنائی ، کہا : ہمیں شعبہ نے خبیب بن عبدالرحمان سے حدیث سنائی ، انھوں نے حفص بن عاصم سے سنا ، انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : نبی صلی اللہ علیہ وسلم ابو بکر ، عمر ، اور عثمان ، رضوان اللہ عنھم اجمعین نے ( پہلے ) آٹھ سال یا کہا : چھ سال ۔ ۔ ۔ منیٰ میں مسافر والی نماز پڑھی ۔ حفص نے کہا : ابن عمر رضی اللہ تعالیٰ عنہ منیٰ میں دو رکعت نماز پڑھتے تھے ۔ پھر اپنے بستر پر آجاتے تھے ۔ میں نے کہا : چچا جان! اگر آپ فرض نماز کے بعددوسنتیں بھی پڑھ لیا کریں! تو انھوں نے کہا : اگر میں ایسا کروں تو ( گویا ) پوری نماز پڑھوں ۔","",{"u2":"عبیداللہ بن معاذ نے حدیث بیان کی،کہا:میرے والد نے ہمیں حدیث سنائی،کہا:ہمیں شعبہ نے خبیب بن عبدالرحمان سے حدیث سنائی،انھوں نے حفص بن عاصم سے سنا،انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:نبی صلی اللہ علیہ وسلم ابو بکر،عمر،اور عثمان، رضوان اللہ عنھم اجمعین نے(پہلے) آٹھ سال یا کہا:چھ سال۔۔۔منیٰ میں مسافر والی نماز پڑھی۔حفص نے کہا: ابن عمر رضی اللہ تعالیٰ عنہ منیٰ میں دو رکعت نماز پڑھتے تھے۔پھر اپنے بستر پر آجاتے تھے۔میں نے کہا: چچا جان! اگر آپ فرض نماز کے بعددوسنتیں بھی پڑھ لیا کریں! تو انھوں نے کہا: اگر میں ایسا کروں تو(گویا) پوری نماز پڑھوں۔"}],[1531,"خالد بن حارث اور عبدالصمد نے کہا : ہمیں شعبہ نے ( باقی ماندہ ) اسی سند کے ساتھ یہی روایت بیان کی لیکن ان دونوں نے اس حدیث میں \" منیٰ میں \" کے الفاظ نہیں کہے لیکن دونوں نے یہ کہا : \" آپ نے سفر میں نماز پڑھی ۔","",{"u2":"خالد بن حارث اور عبدالصمد نے کہا:ہمیں شعبہ نے(باقی ماندہ) اسی سند کے ساتھ یہی روایت بیان کی لیکن ان دونوں نے اس حدیث میں \"منیٰ میں\" کے الفاظ نہیں کہے لیکن دونوں نے یہ کہا:\" آپ نے سفر میں نماز پڑھی۔\""}],[1532,"عبدالواحد نے اعمش سے حدیث بیان کی ، کہا : ہمیں ابراہیم نے حدیث سنائی ، کہا : میں نے عبدالرحمان بن یزید سے سنا ، کہہ رہے تھے : سیدنا عثمان رضی اللہ تعالیٰ عنہ نے ہمیں منیٰ میں چار رکعات پڑھائیں ، یہ بات عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کو بتائی گئی تو انھوں نے انا للہ وانا الیہ راجعون پڑھا پھر کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ منیٰ میں دو رکعات نما ز پڑھی ، ابو بکر رضی اللہ تعالیٰ عنہ کے ساتھ منیٰ میں دو رکعات نماز پڑھی ۔ اور عمر بن خطاب رضی اللہ تعالیٰ عنہ کےساتھ منیٰ میں دو رکعات نماز پڑھی ، کاش! میرے نصیب میں چار رکعات کے بدلے شرف قبولیت حاصل کرنے والی دو رکعتیں ہوں ۔","",{"u2":"عبدالواحد نے اعمش سے حدیث بیان کی،کہا:ہمیں ابراہیم نے حدیث سنائی،کہا: میں نے عبدالرحمان بن یزید سے سنا،کہہ رہے تھے:حضرت عثمان رضی اللہ تعالیٰ عنہ نے ہمیں منیٰ میں چار رکعات پڑھائیں،یہ بات عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کو بتائی گئی تو انھوں نے انا للہ وانا الیہ راجعون پڑھا پھر کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ منیٰ میں دو رکعات نما ز پڑھی،ابو بکر رضی اللہ تعالیٰ عنہ کے ساتھ منیٰ میں دو رکعات نماز پڑھی۔اور عمر بن خطاب رضی اللہ تعالیٰ عنہ کےساتھ منیٰ میں دو رکعات نماز پڑھی،کاش! میرے نصیب میں چار رکعات کے بدلے شرف قبولیت حاصل کرنے والی دو رکعتیں ہوں۔"}],[1533,"ابو معاویہ ، جریر اور عیسیٰ سب نے ( مختلف سندوں سے روایت کرتے ہوئے ) اعمش سے اسی سند کے ساتھ اسی طرح حدیث بیان کی ہے ۔","",{"u2":"ابو معاویہ،جریر اور عیسیٰ سب نے(مختلف سندوں سے روایت کرتے ہوئے)اعمش سے اسی سند کے ساتھ اسی طرح حدیث بیان کی ہے۔"}],[1534,"ابو احوص نے ابو اسحاق سے اور انھوں نے سیدنا حارثہ بن وہب رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ منیٰ میں دو رکعات نماز پڑھی ، ( جب ) لوگ سب سے زیادہ امن میں اور کثیر تعداد میں تھے ۔ ( یہ اللہ کی رخصت کو قبول کرنے کا معاملہ تھا ، خوف ، بدامنی یا جنگ کا معاملہ نہ تھا ۔)","",{"u2":"ابو احوص نے ابو اسحاق سے اور انھوں نے حضرت حارثہ بن وہب رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ منیٰ میں دو رکعات نماز پڑھی،(جب) لوگ سب سے زیادہ امن میں اور کثیر تعداد میں تھے۔(یہ اللہ کی رخصت کو قبول کرنے کا معاملہ تھا،خوف،بدامنی یا جنگ کا معاملہ نہ تھا۔)"}],[1535,"زہیر نے حدیث بیان کی ، کہا : ہمیں ابو اسحاق نے حدیث سنائی ، کہا ، مجھ سے حارثہ بن وہب خزاعی رضی اللہ تعالیٰ عنہ نے حدیث بیان کی کہا : میں نے منیٰ میں رسول اللہ صلی اللہ علیہ وسلم کی اقتداء میں نماز پڑھی جبکہ لوگ ( تعداد میں ) جتنے زیادہ ہوسکتے تھے ( موجود تھے ) آپ نے حجۃ الوداع کے موقع پر دو رکعت نماز پڑھائی ۔ امام مسلم ؒ نے کہا : حارثہ بن وہب خزاعی رضی اللہ تعالیٰ عنہ ماں ( ملیکہ بنت جرول الخزاعیہ ) کی طرف سے عبیداللہ بن عمر بن خطاب رضی اللہ تعالیٰ عنہ کے بھائی تھے ۔","",{"u2":"زہیر نے حدیث بیان کی،کہا:ہمیں ابو اسحاق نے حدیث سنائی،کہا،مجھ سے حارثہ بن وہب خزاعی رضی اللہ تعالیٰ عنہ نے حدیث بیان کی کہا:میں نے منیٰ میں رسول اللہ صلی اللہ علیہ وسلم کی اقتداء میں نماز پڑھی جبکہ لوگ(تعداد میں)جتنے زیادہ ہوسکتے تھے(موجود تھے) آپ نے حجۃ الوداع کے موقع پر دو رکعت نماز پڑھائی۔\nامام مسلم رحمہ اللہ نے کہا:حارثہ بن وہب خزاعی رضی اللہ تعالیٰ عنہ ماں(ملیکہ بنت جرول الخزاعیہ) کی طرف سے عبیداللہ بن عمر بن خطاب رضی اللہ تعالیٰ عنہ کے بھائی تھے۔"}],[1536,"امام مالک نے نافع سے روایت کی کہ ابن عمر رضی اللہ تعالیٰ عنہ نے سردی اور ہوا والی ایک رات اذان کہی اور اس کے آخر میں کہا : ( «أَلَا صَلُّوا فِي الرِّحَالِ» ) سنو! ( اپنے ) ٹھکانوں میں نماز پڑھ لو ۔ \" پھر کہا کہ جب رات سرد اور بارش والی ہوتی تو رسول اللہ صلی اللہ علیہ وسلم موذن کو حکم دیتے کہ وہ کہے ( «أَلَا صَلُّوا فِي الرِّحَالِ» ) سنو! ( اپنے ) ٹھکانوں پر نماز پڑھ لو ۔","",{"u2":"امام مالک نے نافع سے روایت کی کہ ابن عمر رضی اللہ تعالیٰ عنہ نے سردی اور ہوا والی ایک رات اذان کہی اور اس کے آخر میں کہا:(أَلَا صَلُّوا فِی الرِّحَالِ) سنو!(اپنے)ٹھکانوں میں نماز پڑھ لو۔\"پھر کہا کہ جب رات سرد اور بارش والی ہوتی تو رسول اللہ صلی اللہ علیہ وسلم موذن کو حکم دیتے کہ وہ کہے(أَلَا صَلُّوا فِی الرِّحَالِ) سنو!(اپنے) ٹھکانوں پر نماز پڑھ لو۔\""}],[1537,"(محمد بن عبداللہ بن نمیر نے حدیث بیان کی ، کہا : مجھے میرے والد نے حدیث سنائی ، کہا : ہمیں عبیداللہ نے حدیث سنائی ، کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ انھوں نے سردی ، ہوا اور بارش و الی ایک رات میں اذان دی اور اذان کے آخر میں کہا : \" سنو! اپنے ٹھکانوں میں نماز پڑھ لو ، سنو! ٹھکانوں میں نماز پڑھو ، \" پھر کہا : جب سفر میں رات سرد یا بارش والی ہوتی تو رسول اللہ صلی اللہ علیہ وسلم موذن کو یہ کہنے کا حکم دیتے \" «أَلَا صَلُّوا» فِي الرِّحَالِکُم ) \" سنو!اپنی قیام گاہوں میں نماز پڑھ لو ۔","",{"u2":"محمد بن عبداللہ بن نمیر نے حدیث بیان کی،کہا:مجھے میرے والد نے حدیث سنائی،کہا:ہمیں عبیداللہ نے حدیث سنائی،کہا:مجھے نافع نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ انھوں نے سردی،ہوا اور بارش و الی ایک رات میں اذان دی اور اذان کے آخر میں کہا:\" سنو! اپنے ٹھکانوں میں نماز پڑھ لو،سنو! ٹھکانوں میں نماز پڑھو،\"پھر کہا: جب سفر میں رات سرد یا بارش والی ہوتی تو رسول اللہ صلی اللہ علیہ وسلم موذن کو یہ کہنے کا حکم دیتے\" أَلَا صَلُّوا فِی الرِّحَالِکُم) \"سنو!اپنی قیام گاہوں میں نماز پڑھ لو۔\""}],[1538,"ابو اسامہ نے کہا : ہمیں عبیداللہ نے نافع سے حدیث سنائی ، انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے ر وایت کی کہ انھوں نے ( مکہ سے چھ میل کے فاصلے پر واقع ) بضَجنانَ پہاڑ پر اذان کہی ۔ ۔ ۔ پھر اوپر والی حدیث کے مانند بیان کیا اور ( ابو اسامہ نے ) کہا : \" «أَلَا صَلُّوا» فِي الرِّحَالِکُم \" اور انھوں نے ابن عمر رضی اللہ تعالیٰ عنہ کے دوبارہ \" «أَلَا صَلُّوا فِي الرِّحَالِ» \" کہنے کا ذکر نہیں کیا ۔","",{"u2":"ابو اسامہ نے کہا:ہمیں عبیداللہ نے نافع سے حدیث سنائی،انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے ر وایت کی کہ انھوں نے(مکہ سے چھ میل کے فاصلے پر واقع) بضَجنانَ پہاڑ پر اذان کہی۔۔۔پھر اوپر والی حدیث کے مانند بیان کیا اور (ابو اسامہ نے) کہا:\" أَلَا صَلُّوا فِی الرِّحَالِکُم \" اور انھوں نے ابن عمر رضی اللہ تعالیٰ عنہ کے دوبارہ\" أَلَا صَلُّوا فِی الرِّحَالِ\" کہنے کا ذکر نہیں کیا۔"}],[1539,"سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت ہے انھوں نے کہا : ایک سفر میں ہم رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ نکلے تو بارش ہوگئی ، آپ صلی اللہ علیہ وسلم نے فرمایا ، \" تم میں سے جو چاہے اپنی قیام گاہ میں نماز پڑھ لے ۔"],[1540,"سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت ہے انھوں نے کہا : ایک سفر میں ہم رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ نکلے تو بارش ہوگئی ، آپ صلی اللہ علیہ وسلم نے فرمایا ، \" تم میں سے جو چاہے اپنی قیام گاہ میں نماز پڑھ لے ۔",""],[1541,"اسماعیل ( ابن علیہ ) نے ( ابن ابی سفیان ) الزیادی کے ساتھی عبدالحمید سے ، انھوں نے عبداللہ بن حارث سے اور انھوں نے سیدنا عبداللہ بن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے ایک بارش والے دن اپنے موذن سے فرمایا : جب تم اشهد ان لا اله الا اللہ اشهد ان محمد ا رسول اللہ کہہ چکو تو حيي علي الصلوة نہ کہنا ( بلکہ ) «صَلُّوا فِي بُيُوتِكُمْ» ( اپنے گھروں میں نماز پڑھو ) کہنا ۔ کہا : لوگوں نے گویا اس کو ایک غیر معروف کام سمجھا تو ابن عباس رضی اللہ تعالیٰ عنہ نے کہا : کیاتم اس پر تعجب کررہے ہو؟ یہ کام انھوں نے کیا جو مجھ سے بہت زیادہ بہتر تھے ۔ جمعہ پڑھنا لازم ہے اور مجھے برا معلوم ہوا کہ میں تمھیں تنگی میں مبتلا کروں اور تم کیچڑاور پھسلن میں چل کر آؤ ۔","",{"u2":"اسماعیل(ابن علیہ) نے (ابن ابی سفیان) الزیادی کے ساتھی عبدالحمید سے،انھوں نے عبداللہ بن حارث سے اور انھوں نے حضرت عبداللہ بن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے ایک بارش والے دن اپنے موذن سے فرمایا:جب تم اشہد ان لا الہ الا اللہ اشہد ان محمد ا رسول اللہ کہہ چکو تو حیی علی الصلوۃ نہ کہنا(بلکہ) صَلُّوا فِی بُیُوتِکُمْ (اپنے گھروں میں نماز پڑھو)کہنا۔\nکہا: لوگوں نے گویا اس کو ایک غیر معروف کام سمجھا تو ابن عباس رضی اللہ تعالیٰ عنہ نے کہا:کیاتم اس پر تعجب کررہے ہو؟ یہ کام انھوں نے کیا جو مجھ سے بہت زیادہ بہترتھے۔جمعہ پڑھنالازم ہے اور مجھے برا معلوم ہوا کہ میں تمھیں تنگی میں مبتلا کروں اور تم کیچڑاور پھسلن میں چل کر آؤ۔"}],[1542,"ابو کامل جحدری نے کہا : ہمیں حماد ، یعنی ابن زید نے عبدالحمید سے حدیث بیان کی ، انھوں نے کہا : میں نے عبداللہ بن حارث سے سنا ، انھوں نے کہا : سیدنا عبداللہ بن عباس رضی اللہ تعالیٰ عنہ نے ایک پھسلن والے دن ہمارے سامنے خطبہ دیا ۔ ۔ ۔ آگے ابن علیہ کی حدیث کےہم معنی روایت بیان کی ، لیکن جمعے کا نام نہیں لیا ، اور کہا : یہ کام اس شخصیت نے کیا ہے جو مجھ سے بہت زیادہ بہتر تھے ، یعنی نبی اکرم صلی اللہ علیہ وسلم نے ( یہ کام کیا ہے ) ابو کامل نے کہا : حماد نے ہم سے یہ حدیث ( عبدالحمید کی بجائے ) عاصم سے ، انھوں نے عبداللہ بن حارث سے اسی طرح روایت کی ہے ۔"],[1543,"ابو کامل جحدری نے کہا : ہمیں حماد ، یعنی ابن زید نے عبدالحمید سے حدیث بیان کی ، انھوں نے کہا : میں نے عبداللہ بن حارث سے سنا ، انھوں نے کہا : سیدنا عبداللہ بن عباس رضی اللہ تعالیٰ عنہ نے ایک پھسلن والے دن ہمارے سامنے خطبہ دیا ۔ ۔ ۔ آگے ابن علیہ کی حدیث کےہم معنی روایت بیان کی ، لیکن جمعے کا نام نہیں لیا ، اور کہا : یہ کام اس شخصیت نے کیا ہے جو مجھ سے بہت زیادہ بہتر تھے ، یعنی نبی اکرم صلی اللہ علیہ وسلم نے ( یہ کام کیا ہے ) ابو کامل نے کہا : حماد نے ہم سے یہ حدیث ( عبدالحمید کی بجائے ) عاصم سے ، انھوں نے عبداللہ بن حارث سے اسی طرح روایت کی ہے ۔"],[1544,"ابو ربیع عتکی زہرانی نے کہا : ہمیں حماد یعنی ابن زید نے حدیث سنائی ، کہا : ہمیں ایوب اور عاصم احول نے اس سند کےساتھ حدیث سنائی ، البتہ انھوں ( ابو ربیع ) نے اپنی حدیث میں یعنی النبي صلی اللہ علیہ وسلم کے الفاظ ذکر نہیں کیے ۔","",{"u2":"ابو ربیع عتکی زہرانی نے کہا:ہمیں حماد یعنی ابن زید نے حدیث سنائی،کہا:ہمیں ایوب اور عاصم احول نے اس سند کےساتھ حدیث سنائی،البتہ انھوں (ابو ربیع) نے اپنی حدیث میں یعنی النبی صلی اللہ علیہ وسلم کے الفاظ ذکر نہیں کیے۔"}],[1545,"شعبہ نے کہا : ہمیں عبدالحمید صاحب الزیادی نے حدیث سنائی ، کہا : میں نے عبداللہ بن حارث سے سنا ، انھوں نے کہا ، سیدنا ابن عباس رضی اللہ تعالیٰ عنہ کے موذن نے جمعے کے روز بارش والے دن اذان دی ۔ ۔ ۔ پھر ابن علیہ کی حدیث کی طرح بیان کیا ، اور کہا : میں نے اس بات کو ناپسند کیا کہ تم پھسلن میں چل کرآؤ ۔","",{"u2":"شعبہ نے کہا:ہمیں عبدالحمید صاحب الزیادی نے حدیث سنائی،کہا: میں نے عبداللہ بن حارث سے سنا،انھوں نے کہا،حضرت ابن عباس رضی اللہ تعالیٰ عنہ کے موذن نے جمعے کے روز بارش والے دن اذان دی۔۔۔پھر ابن علیہ کی حدیث کی طرح بیان کیا،اورکہا: میں نے اس بات کو ناپسند کیا کہ تم پھسلن میں چل کرآؤ۔"}],[1546,"شعبہ اور معمر دونوں نے ( اپنی اپنی سند سے روایت کرتے ہوئے ) عاصم احول سے اور انھوں نے عبداللہ بن حارث سے روایت کی کہ سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے اپنے موذن کو حکم دیا ۔ معمر کی روایت میں ہے : جمعے کے روز بارش کے دن ۔ ۔ ۔ ( آگے ) سابقہ راویوں کی روایت کی طرح ہے ۔ اور معمر کی حدیث میں یہ بھی ہے : یہ کام انھوں نے کیا جو مجھ سے بہت زیادہ بہتر ہیں ، یعنی نبی اکرم صلی اللہ علیہ وسلم نے ۔","",{"u2":"شعبہ اور معمر دونوں نے (اپنی اپنی سند سے روایت کرتے ہوئے) عاصم احول سے اور انھوں نے عبداللہ بن حارث سے روایت کی کہ حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے اپنے موذن کو حکم دیا۔معمر کی روایت میں ہے:جمعے کے روز بارش کے دن۔۔۔(آگے)سابقہ راویوں کی روایت کی طرح ہے۔اور معمر کی حدیث میں یہ بھی ہے:یہ کام انھوں نے کیا جو مجھ سے بہت زیادہ بہتر ہیں،یعنی نبی اکرم صلی اللہ علیہ وسلم نے۔"}],[1547,"وہیب نے کہا : ہمیں ایوب نے عبداللہ بن حارث سے حدیث بیان کی ۔ وہیب نے کہا : ایوب نے یہ حدیث عبداللہ بن حارث سے نہیں سنی ۔ ( جبکہ ابن حجر ؒ کی تحقیق ہ کہ وہیب کہ بات درست نہیں بلکہ ایوب نے یہ حدیث سنی ہے ) انھوں نے کہا : ابن عباس رضی اللہ تعالیٰ عنہ نے جمعے کے روز بارش کے دن اپنے موذن کو حکم دیا ۔ ۔ ۔ ( آگے اسی طرح ہے ) جس طرح دوسرے راویوں نے بیان کیا ۔","",{"u2":"وہیب نے کہا: ہمیں ایوب نے عبداللہ بن حارث سے حدیث بیان کی۔وہیب نے کہا:ایوب نے یہ حدیث عبداللہ بن حارث سے نہیں سنی۔(جبکہ ابن حجر رحمہ اللہ کی تحقیق ہ کہ وہیب کہ بات درست نہیں بلکہ ایوب نے یہ حدیث سنی ہے) انھوں نے کہا: ابن عباس رضی اللہ تعالیٰ عنہ نے جمعے کے روز بارش کے دن اپنے موذن کو حکم دیا۔۔۔(آگے اسی طرح ہے)جس طرح دوسرے راویوں نے بیان کیا۔"}],[1548,"محمد بن عبداللہ بن نمیر نے حدیث بیان کی ، کہا : ہمیں میرے والد نے حدیث بیان کی ، کہا : ہمیں عبیداللہ نے نافع سے انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم ( سفر میں سواری پر ) اپنی نفل نماز پڑھتے تھے آپ کی اونٹنی جس طرف بھی آپ کو لئے ہوئے رخ کرلیتی ۔","",{"u2":"محمد بن عبداللہ بن نمیر نے حدیث بیان کی،کہا:ہمیں میرے والد نے حدیث بیان کی،کہا:ہمیں عبیداللہ نے نافع سے انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم (سفر میں سواری پر) اپنی نفل نماز پڑھتے تھے آپ کی اونٹنی جس طرف بھی آپ کو لئے ہوئے رخ کرلیتی۔"}],[1549,"ابو خالد احمر نے عبیداللہ سے انھوں نے نافع سے اور انھوں نے ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم اپنی سواری پر نماز پڑھتے تھے ۔ وہ چاہے آپ کو لئے ہوئے جس طرف بھی رخ کرلیتی ۔","",{"u2":"ابو خالد احمر نے عبیداللہ سے انھوں نے نافع سے اور انھوں نے ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم اپنی سواری پر نماز پڑھتے تھے۔وہ چاہے آپ کو لئے ہوئے جس طرف بھی رخ کرلیتی۔"}],[1550,"یحییٰ بن سعید نے عبدالملک بن ابی سلیمان سے روایت کی ، کہا : ہمیں سعید بن جبیر نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم جب مکہ سے مدینہ کی طرف آرہے ہوتے ، اپنی سواری پر نماز پڑھتے تھے ، جس طرف بھی آپ کا رخ ہوجاتا ۔ کہا : اسی کے بارے میں یہ آیت اتری : \" سو جس طرف تم رخ کرو ، وہیں اللہ کا چہرہ ہے ۔","",{"u2":"یحییٰ بن سعید نے عبدالملک بن ابی سلیمان سے روایت کی،کہا: ہمیں سعید بن جبیر نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم جب مکہ سے مدینہ کی طرف آرہے ہوتے،اپنی سواری پر نماز پڑھتے تھے،جس طرف بھی آپ کا رخ ہوجاتا۔کہا: اسی کے بارے میں یہ آیت اتری:\"سو جس طرف تم رخ کرو،وہیں اللہ کا چہرہ ہے۔\""}],[1551,"ابن مبارک ، ابن ابی زائدہ اور ابن نمیر نے اپنے والد کے حوالے سے ، سب نے عبدالملک سے اسی سند کے ساتھ یہ حدیث روایت کی اور ان میں سے ابن مبارک اور ابن ابی زائدہ کی روایت میں ہے کہ پھر سیدنا ابن عمر رضی اللہ تعالیٰ عنہ نے آیت تلاوت کی ( «فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ» اللہِہہہ ) \" تم جس طرف بھی رخ کرو وہیں اللہ کا چہرہ ہے \" اور کہا : یہ اسی کے بارے میں اتری ہے ۔","",{"u2":"ابن مبارک،ابن ابی زائدہ اور ابن نمیر نے اپنے والد کے حوالے سے،سب نے عبدالملک سے اسی سند کے ساتھ یہ حدیث روایت کی اور ان میں سے ابن مبارک اور ابن ابی زائدہ کی روایت میں ہے کہ پھر حضرت ابن عمر رضی اللہ تعالیٰ عنہ نےآیت تلاوت کی(فَأَیْنَمَا تُوَلُّوا فَثَمَّ وَجْہُ اللہِہہہ)\"تم جس طرف بھی رخ کرو وہیں اللہ کا چہرہ ہے\"اور کہا:یہ اسی کے بارے میں اتری ہے۔"}],[1552,"عمرو بن یحییٰ مازنی نے سعید بن یسار سے اور انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا میں نے رسول اللہ صلی اللہ علیہ وسلم کو گدھے پر نماز پڑھتے دیکھا جبکہ آپ نے خیبر کا رخ کیا ہوا تھا ۔","",{"u2":"عمرو بن یحییٰ مازنی نے سعید بن یسار سے اور انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،کہا میں نے رسول اللہ صلی اللہ علیہ وسلم کو گدھے پر نمازپڑھتے دیکھا جبکہ آپ نے خیبر کا رخ کیا ہوا تھا۔"}],[1553,"ابو بکر بن عمر بن عبدالرحمان ، بن عبداللہ بن عمر بن خطاب رضی اللہ تعالیٰ عنہ نے سعید بن یسار سے روایت کی کہ انھوں نے کہا : میں مکہ کے راستے میں سیدنا ابن عمر رضی اللہ تعالیٰ عنہ کے ساتھ سفر کررہا تھا ۔ پھر جب مجھے صبح ہوجانے کا اندیشہ ہوا تو میں سواری سے اترا اور وتر پڑھے ، پھر میں ان سے جا ملا تو سیدنا ابن عمر رضی اللہ تعالیٰ عنہ نے مجھ سے پوچھا : تم کہاں ( رہ گئے ) تھے؟میں نے ان سے کہا : مجھے فجر ہوجانے کا اندیشہ ہوا ، اس لئے میں نے اتر کروترپڑھے ۔ تو سیدنا عبداللہ رضی اللہ تعالیٰ عنہ نے کہا : کیا تمہارے لئے رسول اللہ صلی اللہ علیہ وسلم کے عمل میں نمونہ نہیں ہے؟میں نے کہا : کیوں نہیں ، اللہ کی قسم ہے انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم اونٹ پر وتر پڑھتے تھے ۔","",{"u2":"ابو بکر بن عمر بن عبدالرحمان،بن عبداللہ بن عمر بن خطاب رضی اللہ تعالیٰ عنہ نے سعید بن یسار سے روایت کی کہ انھوں نے کہا: میں مکہ کے راستے میں حضرت ابن عمر رضی اللہ تعالیٰ عنہ کے ساتھ سفر کررہا تھا۔پھر جب مجھے صبح ہوجانے کا اندیشہ ہوا تو میں سواری سے اترا اور وتر پڑھے،پھر میں ان سے جا ملا تو حضرت ابن عمر رضی اللہ تعالیٰ عنہ نے مجھ سے پوچھا:تم کہاں(رہ گئے) تھے؟میں نے ان سے کہا:مجھے فجر ہوجانے کا اندیشہ ہوا،اس لئے میں نے اتر کروترپڑھے۔تو حضرت عبداللہ رضی اللہ تعالیٰ عنہ نے کہا:کیا تمہارے لئے رسول اللہ صلی اللہ علیہ وسلم کے عمل میں نمونہ نہیں ہے؟میں نے کہا:کیوں نہیں،اللہ کی قسم ہے انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم اونٹ پر وتر پڑھتے تھے۔"}],[1554,"امام مالکؒ نے عبداللہ بن دینار سے اور انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم اپنی سواری پر نماز پڑھتے تھے وہ آپ کو لئے ہوئے جدھر کا بھی رخ کرلیتی ۔ عبداللہ بن دینار نے کہا : سیدنا ابن عمر رضی اللہ تعالیٰ عنہ بھی یہی کرتے تھے ۔","",{"u2":"امام مالک رحمہ اللہ نے عبداللہ بن دینار سے اور انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم اپنی سواری پر نماز پڑھتے تھے وہ آپ کو لئے ہوئے جدھر کا بھی رخ کرلیتی۔\nعبداللہ بن دینار نے کہا: حضرت ابن عمر رضی اللہ تعالیٰ عنہ بھی یہی کرتے تھے۔"}],[1555,"ابن ہاد نے عبداللہ بن دینا ر سے اور انھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم اپنی سواری پر وتر ادا کرتے تھے ۔","",{"u2":"ابن ہاد نے عبداللہ بن دینا ر سے اور انھوں نے حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم اپنی سواری پر وتر ادا کرتے تھے۔"}],[1556,"سالم بن عبداللہ نے اپنے والد ( عبداللہ بن عمر رضی اللہ تعالیٰ عنہ ) سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم اپنی سواری پر نفل پڑھتے جدھر بھی آپ کا رخ ہوجاتا اور اسی پر وتر بھی پڑھتے ، البتہ آپ فرض نماز اس پر نہیں پڑھتے تھے ۔","",{"u2":"سالم بن عبداللہ نے اپنے والد(عبداللہ بن عمر رضی اللہ تعالیٰ عنہ) سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم اپنی سواری پر نفل پڑھتے جدھر بھی آپ کا رخ ہوجاتا اور اسی پر وتر بھی پڑھتے،البتہ آپ فرض نماز اس پر نہیں پڑھتے تھے۔"}],[1557,"سیدنا عبداللہ بن عامر بن ربیعہ رضی اللہ تعالیٰ عنہ نے خبر دی کہ انھیں ان کے والد نے بتایا کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ، آپ سفر میں رات کے وقت سواری پر نفل پڑھتے تھے جدھر کا بھی وہ رخ کرلیتی تھی ۔","",{"u2":"حضرت عبداللہ بن عامر بن ربیعہ رضی اللہ تعالیٰ عنہ نے خبر دی کہ انھیں ان کے والد نے بتایا کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا،آپ سفر میں رات کے وقت سواری پر نفل پڑھتے تھے جدھر کا بھی وہ رخ کرلیتی تھی۔"}],[1558,"ہمام نے کہا : ہمیں انس بن سیرین نے حدیث بیان کی کہ جب سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ شام سے آئے تو ہم نے ان کا استقبال کیا ، ہم عین التمر کے مقام پر جا کر ان سے ملے تو میں نے انھیں دیکھا ، وہ گدھے پر نماز پڑھ رہے تھے اور ان کا رخ اس طرف تھا ۔ ہمام نے قبلے کی بائیں طرف اشارہ کیا ۔ تو میں ( انس بن سیرین ) نے ان سے کہا : میں نے آپ کو قبلے کی بائیں طرف نماز پڑھتے دیکھا ہے انھوں نے کہا : اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسا کرتے ہوئے نہ دیکھا ہوتا تو میں ( کبھی ) ایسا نہ کرتا ۔","",{"u2":"ہمام نے کہا: ہمیں انس بن سیرین نے حدیث بیان کی کہ جب حضرت انس بن مالک رضی اللہ تعالیٰ عنہ شام سے آئے تو ہم نے ان کا استقبال کیا،ہم عین التمر کے مقام پر جا کر ان سے ملے تو میں نے انھیں دیکھا،وہ گدھے پر نماز پڑھ رہے تھے اور ان کا رخ اس طرف تھا۔ہمام نے قبلے کی بائیں طرف اشارہ کیا۔تو میں(انس بن سیرین) نے ان سے کہا:میں نے آپ کو قبلے کی بائیں طرف نماز پڑھتے دیکھا ہے انھوں نے کہا:اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسا کرتے ہوئے نہ دیکھا ہوتا تو میں (کبھی) ایسا نہ کرتا۔"}],[1559,"امام مالک ؒ نے نافع سے اور ا نھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم کو جب چلنے کی جلدی ہوتی تو مغرب اور عشاء کی نمازیں جمع کرلیتے ۔","",{"u2":"امام مالک رحمہ اللہ نے نافع سے اور ا نھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم کو جب چلنے کی جلدی ہوتی تو مغرب اور عشاء کی نمازیں جمع کرلیتے۔"}],[1560,"عبیداللہ سے روایت ہے کہا : مجھے نافع نے خبردی کہ سیدنا عمر رضی اللہ تعالیٰ عنہ کو جب ( سفر کے لئے ) جلدی چلنا ہوتا تو شفق ( سورج کی سرخی ) غائب ہونے کے بعد ( یعنی عشاء کا وقت شروع ہونے کے بعد ) مغرب اور عشاء کو جمع کرکے پڑھتے تھے اور بتاتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کو جب جلد چلنا ہوتا تو آپ صلی اللہ علیہ وسلم مغرب اور عشاء کو جمع کرلیتے تھے ۔","",{"u2":"عبیداللہ سے روایت ہےکہا: مجھے نافع نے خبردی کہ حضرت عمر رضی اللہ تعالیٰ عنہ کو جب(سفر کے لئے)جلدی چلنا ہوتا تو شفق(سورج کی سرخی) غائب ہونے کے بعد(یعنی عشاء کاوقت شروع ہونے کے بعد)مغرب اور عشاء کو جمع کرکے پڑھتے تھے اور بتاتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کو جب جلد چلنا ہوتا تو آپ صلی اللہ علیہ وسلم مغرب اور عشاء کو جمع کرلیتے تھے۔"}],[1561,"سفیان نے ( ابن شہاب ) زہری سے ، انھوں نے سالم سے اور انھوں نے اپنے والد ( ابن عمر رضی اللہ تعالیٰ عنہ رضی اللہ تعالیٰ عنہ سے ر وایت کی کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ، جب آپ کو چلنے کی جلدی ہوتی تو آپ مغرب اور عشاء کو جمع کرلیتے تھے ۔)","",{"u2":"سفیان نے(ابن شہاب) زہری سے،انھوں نے سالم سے اور انھوں نے اپنے والد (ابن عمر رضی اللہ تعالیٰ عنہ رضی اللہ تعالیٰ عنہ سے ر وایت کی کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا،جب آپ کو چلنے کی جلدی ہوتی تو آپ مغرب اور عشاء کو جمع کرلیتے تھے۔"}],[1562,"یونس نے ابن شہاب سے روایت کی ، کہا : مجھے سالم بن عبداللہ نے خبر دی کہ ان کے والد نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا جب آپ نے سفر میں جلد چلنا ہوتا تو مغرب کی نماز کو موخر کردیتے حتیٰ کہ اسے اور عشاء کی نماز کو جمع کرکرتے ۔","",{"u2":"یونس نے ابن شہاب سے روایت کی،کہا: مجھےسالم بن عبداللہ نے خبر دی کہ ان کے والد نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا جب آپ نے سفر میں جلد چلنا ہوتا تو مغرب کی نماز کو موخر کردیتے حتیٰ کہ اسے اور عشاء کی نماز کو جمع کرکرتے۔"}],[1563,"مفضل بن فضالہ نے عقیل سے ، انھوں نے ابن شہاب سے اور انھوں نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب سورج ڈھلنے سے پہلے کوچ کرتے تو ظہر کو اس وقت تک موخر فرماتے کہ عصر کا وقت ہوجاتا ، پھر آپ ( سواری سے ) اترتے ، دونوں نمازوں کوجمع کرتے ، اور اگر آپ کے کوچ کرنے سے پہلے سورج ڈھل جاتا تو ظہر پڑھ کر سوار ہوتے ۔","",{"u2":"مفضل بن فضالہ نے عقیل سے،انھوں نے ابن شہاب سے اور انھوں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم جب سورج ڈھلنے سے پہلے کوچ کرتے تو ظہر کو اس وقت تک موخر فرماتے کہ عصر کا وقت ہوجاتا،پھر آپ (سواری سے)اترتے،دونوں نمازوں کوجمع کرتے،اور اگر آپ کے کوچ کرنے سے پہلے سورج ڈھل جاتا تو ظہر پڑھ کر سوار ہوتے۔"}],[1564,"لیس بن سعد نے عقیل بن خالد سے باقی ماندہ اسی سند کے ساتھ روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سفر میں جب دو نمازوں کو جمع کرنا چاہتے تو ظہر کو موخر کرتے حتیٰ کہ عصر کا اول وقت ہوجاتا ، پھر آپ دونوں نمازوں کو جمع کرتے ۔","",{"u2":"لیس بن سعد نے عقیل بن خالد سے باقی ماندہ اسی سند کے ساتھ روایت کی کہ ر سول اللہ صلی اللہ علیہ وسلم سفر میں جب دو نمازوں کو جمع کرنا چاہتے توظہر کو موخر کرتے حتیٰ کہ عصر کا اول وقت ہوجاتا،پھر آپ دونوں نمازوں کو جمع کرتے۔"}],[1565,"جابر بن اسماعیل نے بھی عقیل بن خالد سے باقی ماندہ اسی سند کے ساتھ روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم کو جب سفر میں جلدی ہوتی تو ظہر کو عصر کے اول وقت تک موخر کردیتے ، پھر دونوں کو جمع کرلیتے اور مغرب کو موخر کرتے اور عشاء کے ساتھ اکٹھا کرکے پڑھتے جب شفق غائب ہوجاتی ۔","",{"u2":"جابر بن اسماعیل نے بھی عقیل بن خالد سے باقی ماندہ اسی سند کے ساتھ روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم کو جب سفر میں جلدی ہوتی تو ظہر کو عصر کے اول وقت تک موخر کردیتے،پھر دونوں کو جمع کرلیتے اور مغرب کو موخر کرتے اور عشاء کے ساتھ اکٹھا کرکے پڑھتے جب شفق غائب ہوجاتی۔"}],[1566,"امام مالک ؒ نے ابو زبیر سے ، انھوں نے سعید بن جبیر سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ظہر اور عصر کو اکھٹا پڑھا اور مغرب اور عشاء کو اکھٹا پڑھا کسی خوف اور سفر کے بغیر ۔","",{"u2":"امام مالک رحمہ اللہ نے ابو زبیر سے،انھوں نے سعید بن جبیر سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ظہر اور عصر کو اکھٹا پڑھا اور مغرب اور عشاء کو اکھٹا پڑھا کسی خوف اور سفر کے بغیر۔"}],[1567,"زہیر نے کہا : ہمیں ابو زبیر نے سعید بن جبیر سے حدیث سنائی ، انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ظہر اور عصر کو مدینہ میں کسی خوف اور سفر کے بغیر جمع کرکے پڑھا ۔ ابوزبیر نے کہا : میں نے ( ابن عباس رضی اللہ تعالیٰ عنہ کے شاگرد ) سعید سے پوچھا : آپ صلی اللہ علیہ وسلم ؤ نے ایسا کیوں کیا تھا؟انھوں نےجواب دیا : میں بھی سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے سوا ل کیا تھا جیسے تم نے مجھ سے سوال کیا ہے تو انھوں نے کہا : آپ نے چاہا کہ اپنی امت کے کسی فرد کو تنگی اور دشواری میں نہ ڈالیں ۔","",{"u2":"زہیر نے کہا:ہمیں ابو زبیر نے سعید بن جبیر سے حدیث سنائی،انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ظہر اور عصر کو مدینہ میں کسی خوف اور سفر کے بغیر جمع کرکے پڑھا۔\nابوزبیر نے کہا: میں نے(ابن عباس رضی اللہ تعالیٰ عنہ کے شاگرد) سعید سے پوچھا:آپ صلی اللہ علیہ وسلم ؤ نے ایسا کیوں کیاتھا؟انھوں نےجواب دیا: میں بھی حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے سوا ل کیاتھا جیسے تم نے مجھ سے سوال کیا ہے تو انھوں نے کہا:آپ نے چاہا کہ اپنی امت کےکسی فرد کو تنگی اور دشواری میں نہ ڈالیں۔"}],[1568,"قزہ بن خالد نے کہا : ہمیں ابو زبیر نے حدیث بیا ن کی ، کہا : ہمیں سعید بن جبیر نے حدیث سنائی ، انھوں نے کہا : ہمیں سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے حدیث بیا ن کی کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوہ تبوک کے دوران ایک سفر میں نمازوں کو جمع کیا ، ظہراورعصر کو اکھٹا پڑھا اور مغرب اور عشاء کو اکھٹا پڑھا ۔ سعید نے کہا میں نے ابن عباس رضی اللہ تعالیٰ عنہ سے پوچھا : آپ صلی اللہ علیہ وسلم نے ایسا کیوں کیا تھا؟انھوں نے کہا : آپ نے چاہا اپنی امت کو حرج ( اور تنگی ) میں نہ ڈالیں ۔","",{"u2":"قزہ بن خالد نے کہا:ہمیں ابو زبیر نے حدیث بیا ن کی،کہا:ہمیں سعید بن جبیر نے حدیث سنائی،انھوں نے کہا:ہمیں حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے حدیث بیا ن کی کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوہ تبوک کے دوران ایک سفر میں نمازوں کو جمع کیا،ظہراورعصر کو اکھٹا پڑھا اور مغرب اور عشاء کو اکھٹا پڑھا۔\nسعید نے کہا میں نے ابن عباس رضی اللہ تعالیٰ عنہ سے پوچھا:آپ صلی اللہ علیہ وسلم نے ایسا کیوں کیا تھا؟انھوں نے کہا:آپ نے چاہا اپنی امت کو حرج(اور تنگی) میں نہ ڈالیں۔"}],[1569,"زہیر نے کہا : ہمیں ابو زبیر نے ابو طفیل عامر سے حدیث سنائی اور انھوں نے سیدنا معاذ رضی اللہ تعالیٰ عنہ سے روایت کی کہ ہم غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے تو ( اس دوران میں ) آپ ظہر اور عصر اکھٹی پڑھتے رہے اور مغرب اور عشاء کو جمع کرتے رہے ۔","",{"u2":"زہیر نے کہا:ہمیں ابو زبیر نے ابو طفیل عامر سے حدیث سنائی اور انھوں نے حضرت معاذ رضی اللہ تعالیٰ عنہ سے روایت کی کہ ہم غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے تو (اس دوران میں) آپ ظہر اور عصر اکھٹی پڑھتے رہے اور مغرب اور عشاء کو جمع کرتے رہے۔"}],[1570,"قرہ بن خالد نے کہا : ہمیں ابو زبیر نے حدیث بیا ن کی ، کہا : ہمیں عامر بن واثلہ ابو طفیل نے حدیث بیا ن کی ، کہا : ہمیں سیدنا معاذ بن جبل رضی اللہ تعالیٰ عنہ نے حدیث بیان کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے غزوہ تبوک میں ظہر ، عصر کو اور مغرب ، عشاء کو جمع کیا ۔ ( عامر بن واثلہ نے ) کہا : میں نے ( سیدنا معاذ رضی اللہ تعالیٰ عنہ سے ) پوچھا : آپ نے ایسا کیوں کیا؟تو انھوں نے کہا : آپ نے چاہا کہ اپنی امت کو دشواری میں نہ ڈالیں ۔","",{"u2":"قرہ بن خالد نے کہا:ہمیں ابو زبیر نے حدیث بیا ن کی،کہا: ہمیں عامر بن واثلہ ابو طفیل نے حدیث بیا ن کی،کہا:ہمیں حضرت معاذ بن جبل رضی اللہ تعالیٰ عنہ نے حدیث بیان کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے غزوہ تبوک میں ظہر،عصر کو اور مغرب،عشاء کو جمع کیا۔\n(عامر بن واثلہ نے) کہا: میں نے (حضرت معاذ رضی اللہ تعالیٰ عنہ سے) پوچھا:آپ نے ایسا کیوں کیا؟تو انھوں نے کہا: آپ نے چاہا کہ اپنی امت کو دشواری میں نہ ڈالیں۔"}],[1571,"ابو معاویہ اور وکیع دونوں نے اعمش سے روایت کی ، انھوں نے حبیب بن ثابت سے انھوں نے سعید بن جبیر سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ظہر ، عصر اور مغرب ، عشاء کو مدینہ میں کسی خوف اور بارش کے بغیر جمع کیا ۔ وکیع کی روایت میں ہے ( سعید نے ) کہا : میں نے ابن عباس رضی اللہ تعالیٰ عنہ سے پوچھا : آپ صلی اللہ علیہ وسلم نے ایسا کیوں کیا؟ انھوں نے کہا : تاکہ اپنی امت کو دشواری میں مبتلا نہ کریں اور ابو معاویہ کی حدیث میں ہے ابن عباس رضی اللہ تعالیٰ عنہ سے پوچھا گیا : آپ صلی اللہ علیہ وسلم نے کہا چاہتے ہوئے ایسا کیا؟انھوں نے کہا : آپ نے چاہا اپنی امت کو دشواری میں نہ ڈالیں ۔","",{"u2":"ابو معاویہ اور وکیع دونوں نے اعمش سے روایت کی،انھوں نے حبیب بن ثابت سے انھوں نے سعید بن جبیر سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے ظہر،عصر اور مغرب،عشاء کو مدینہ میں کسی خوف اور بارش کے بغیر جمع کیا۔وکیع کی روایت میں ہے(سعید نے) کہا: میں نے ابن عباس رضی اللہ تعالیٰ عنہ سے پوچھا:آپ صلی اللہ علیہ وسلم نے ایسا کیوں کیا؟ انھوں نے کہا:تاکہ اپنی امت کو دشواری میں مبتلا نہ کریں اور ابو معاویہ کی حدیث میں ہے ابن عباس رضی اللہ تعالیٰ عنہ سے پوچھا گیا: آپ صلی اللہ علیہ وسلم نے کہا چاہتے ہوئے ایسا کیا؟انھوں نے کہا: آپ نے چاہا اپنی امت کو دشواری میں نہ ڈالیں۔"}],[1572,"سفیان بن عینیہ نے عمرو بن دینار سے انھوں نے ( ابوشعشاء ) جابر بن زید سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ آٹھ رکعات ( ظہر اور عصر ) اکھٹی اور سات رکعات ( مغرب اور عشاء ) اکھٹی پڑھیں ۔ ( عمرو نے کہا ) میں نے ابو شعشاء ( جابر بن زید ) سے کہا کہ میرا خیال ہے آپ نے ظہر کو موخر کیا اور عصر جلدی پڑھی اور مغرب کو موخر کیا اور عشاء میں جلدی کی ۔ انھوں نے کہا : میرا بھی یہی خیال ہے ۔","",{"u2":"سفیان بن عینیہ نے عمرو بن دینار سے انھوں نے (ابوشعشاء) جابر بن زید سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:میں نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ آٹھ رکعات (ظہر اورعصر) اکھٹی اور سات رکعات(مغرب اور عشاء) اکھٹی پڑھیں۔\n(عمرو نے کہا)میں نے ابو شعشاء(جابر بن زید) سے کہا کہ میرا خیال ہے آپ نے ظہر کو موخر کیا اور عصر جلدی پڑھی اور مغرب کو موخر کیا اور عشاء میں جلدی کی۔انھوں نے کہا:میرا بھی یہی خیال ہے۔"}],[1573,"حماد بن زید نے عمرو بن دینار سے انھوں نے جابر بن زید سے اور انھوں نے سیدنا ا بن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ میں سات رکعات اور آٹھ رکعات نماز پڑھی ۔ یعنی ظہر ، عصر ، مغرب اور عشاء ( ملا کرپڑھیں ) ۔","",{"u2":"حماد بن زید نے عمرو بن دینار سے انھوں نے جابر بن زید سے اور انھوں نے حضرت ا بن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ میں سات رکعات اور آٹھ رکعات نماز پڑھی۔یعنی ظہر،عصر،مغرب اور عشاء(ملا کرپڑھیں)۔"}],[1574,"زبیر بن خریت نے عبداللہ بن شفیق سے روایت کی انھوں نے کہا : ایک دن سیدنا ابن عباس رضی اللہ تعالیٰ عنہ عصر کے بعد ہمیں خطاب کرنے لگے حتیٰ کہ سورج غروب ہوگیا اور ستارے نمودار ہوگئے اور لوگ کہنے لگے : نماز ، نماز! پھر ان کے پاس بنو تمیم کا ایک آدمی آیا جو نہ تھکتا تھا اور نہ باز آرہاتھا نماز ، نماز کہے جارہاتھا ، سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے کہا تیری ماں نہ ہو!تو مجھے سنت سکھا رہا ہے؟پھر کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ نے ظہر وعصر کو اور مغرب وعشاء کو جمع کیا ۔ عبداللہ بن شفیق نے کہا : تو اس سے میرے دل میں کچھ کھٹکنے لگا ، چنانچہ میں حضر ت ابو ہریرۃ رضی اللہ تعالیٰ عنہ کی خدمت میں حاضر ہوا اور ان سے پوچھا تو ا نھوں نے ان ( ابن عباس رضی اللہ تعالیٰ عنہ ) کے قول کی تصدیق کی ۔","",{"u2":"زبیر بن خریت نے عبداللہ بن شفیق سے روایت کی انھوں نے کہا:ایک دن حضرت ابن عباس رضی اللہ تعالیٰ عنہ عصر کے بعد ہمیں خطاب کرنے لگے حتیٰ کہ سورج غروب ہوگیا اور ستارے نمودار ہوگئے اور لوگ کہنے لگے:نماز،نماز! پھر ان کے پاس بنو تمیم کا ایک آدمی آیا جو نہ تھکتا تھا اور نہ باز آرہاتھا نماز،نماز کہے جارہاتھا،حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے کہا تیری ماں نہ ہو!تو مجھے سنت سکھا رہا ہے؟پھر کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ نے ظہر وعصر کو اور مغرب وعشاء کو جمع کیا۔\nعبداللہ بن شفیق نے کہا:تو اس سے میرے دل میں کچھ کھٹکنے لگا،چنانچہ میں حضر ت ابو ہریرۃ رضی اللہ تعالیٰ عنہ کی خدمت میں حاضر ہوا اور ان سے پوچھا تو ا نھوں نے ان (ابن عباس رضی اللہ تعالیٰ عنہ) کے قول کی تصدیق کی۔"}],[1575,"عمران بن خدیرنے عبداللہ بن شقیق عقیلی سے روایت کی ، انھوں نے کہا : ایک شخص نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے کہا : نماز! آپ خاموش رہے اس نے پھر کہا : نماز! آپ پھر چپ رہے ، اس نے پھر کہا : نماز! تو آپ ( کچھ دیر ) چپ رہے ، پھر فرمایا : تیری ماں نہ ہو! کیا تو ہمیں نماز کی تعلیم دیتا ہے؟ہم رسول اللہ صلی اللہ علیہ وسلم کے دور میں دو نمازیں جمع کرلیاکرتے تھے ۔","",{"u2":"عمران بن خدیرنے عبداللہ بن شقیق عقیلی سے روایت کی،انھوں نے کہا:ایک شخص نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے کہا:نماز! آپ خاموش رہے اس نے پھر کہا:نماز! آپ پھر چپ رہے،اس نے پھر کہا:نماز! تو آپ (کچھ دیر) چپ رہے،پھر فرمایا:تیری ماں نہ ہو! کیاتو ہمیں نماز کی تعلیم دیتا ہے؟ہم رسول اللہ صلی اللہ علیہ وسلم کے دور میں دو نمازیں جمع کرلیاکرتے تھے۔"}],[1576,"ابو معاویہ اور وکیع نے اعمش سے ، انھوں نے عمارہ سے ، انھوں نے اسود سے اور انھوں نے سیدنا عبداللہ رضی اللہ تعالیٰ عنہ ( بن مسعود ) سے روایت کی ، کہا : تم میں سے کوئی شخص اپنی ذات میں سے شیطان کا حصہ نہ رکھے ( وہم اور وسوسے کا شکار نہ ہو ) یہ خیال نہ کرے کہ اس پر لازم ہے کہ وہ نماز سے دائیں کے علاوہ کسی اور جانب سے رخ نہ موڑے ، میں نے رسول اللہ صلی اللہ علیہ وسلم کو اکثر دیکھا تھا ، آپ بائیں جانب سے رخ مبارک موڑتے تھے ۔","",{"u2":"ابو معاویہ اور وکیع نے اعمش سے،انھوں نے عمارہ سے،انھوں نے اسود سے اور انھوں نے حضرت عبداللہ رضی اللہ تعالیٰ عنہ (بن مسعود) سے روایت کی،کہا: تم میں سے کوئی شخص اپنی ذات میں سے شیطان کاحصہ نہ رکھے(وہم اور وسوسے کا شکار نہ ہو) یہ خیال نہ کرے کہ اس پر لازم ہے کہ وہ نماز سےدائیں کے علاوہ کسی اور جانب سے رخ نہ موڑے،میں نے رسول اللہ صلی اللہ علیہ وسلم کو اکثر دیکھا تھا،آپ بائیں جانب سے رخ مبارک موڑتے تھے۔"}],[1577,"جریر اور عیسیٰ بن یونس نے اسی سند کے ساتھ سابقہ حدیث کے مانند حدیث بیان کی ۔","",{"u2":"جریراور عیسیٰ بن یونس نے اسی سند کے ساتھ سابقہ حدیث کے مانند حدیث بیان کی۔"}],[1578,"ابو عوانہ نے ( اسماعیل بن عبدالرحمان ) سدی سے روایت کہ ، انھوں نے کہا : میں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے پوچھا : جب میں نماز پڑھ لوں تو اپنارخ کیسے موڑوں ، اپنی دائیں طرف یا اپنی بائیں طرف سے؟انھوں نے کہا : میں نے تو رسول اللہ صلی اللہ علیہ وسلم کو زیادہ تردائیں طرف سے رخ پھیرتے دیکھا ہے ۔","",{"u2":"ابو عوانہ نے(اسماعیل بن عبدالرحمان) سدی سے روایت کہ،انھوں نے کہا: میں نے حضرت انس رضی اللہ تعالیٰ عنہ سے پوچھا: جب میں نماز پڑھ لوں تو اپنارخ کیسے موڑوں،اپنی دائیں طرف یا اپنی بائیں طرف سے؟انھوں نے کہا:میں نے تو رسول اللہ صلی اللہ علیہ وسلم کو زیادہ تردائیں طرف سے رخ پھیرتے دیکھا ہے۔"}],[1579,"سفیان بن عینیہ نے سدی سے اور انھوں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم اپنی دائیں طرف سے رخ پھیرا کرتے تھے ۔","",{"u2":"سفیان بن عینیہ نے سدی سے اور انھوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم اپنی دائیں طرف سے رخ پھیراکرتے تھے۔"}],[1580,"ا بن ابی زائدہ نے مسعر سے ، انھوں نے ثابت بن عبید سے انھوں نے سیدنا براء رضی اللہ تعالیٰ عنہ کے بیٹے ( عبید ) سے اور انھوں نے سیدنا براء رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھتے تو پسند کرتے تھے کہ ہم آپ کی دائیں طرف ہوں ، آپ ہماری طرف رخ فرمائیں ۔ ( براء رضی اللہ تعالیٰ عنہ نے ) کہا : میں نے ( ایسے ہی ایک موقع پر ) آپ کو یہ فرماتے ہوئےسنا : \" اے میرےرب ! تو جب اپنے بندوں کو اٹھائے گا یا جمع کرے گا اس دن مجھے اپنے عذاب سے بچانا ۔","",{"u2":"ا بن ابی زائدہ نے مسعر سے،انھوں نے ثابت بن عبید سے انھوں نے حضرت براء رضی اللہ تعالیٰ عنہ کے بیٹے (عبید) سے اور انھوں نے حضرت براء رضی اللہ تعالیٰ عنہ سے روایت کی،کہا کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھتے تو پسند کرتے تھے کہ ہم آپ کی دائیں طرف ہوں،آپ ہماری طرف رخ فرمائیں۔(براء رضی اللہ تعالیٰ عنہ نے) کہا: میں نے(ایسے ہی ایک موقع پر)آپ کو یہ فرماتے ہوئےسنا:\"اے میرےرب! تو جب اپنے بندوں کو اٹھائے گا یا جمع کرے گا اس دن مجھے اپنے عذاب سے بچانا۔\""}],[1581,"وکیع نے مسعر سے اسی سند کے ساتھ یہ حدیث بیان کی اور ا نھوں نےيُقْبِلُ «عَلَيْنَا بِوَجْهِهِ» ( آپ ہماری طرف رخ فرمائیں ) کے الفاظ ذکر نہیں کئے ۔","",{"u2":"وکیع نے مسعر سے اسی سند کے ساتھ یہ حدیث بیان کی اور ا نھوں نےیُقْبِلُ عَلَیْنَا بِوَجْہِہِ (آپ ہماری طرف رخ فرمائیں) کے الفاظ ذکر نہیں کئے۔"}],[1582,"شعبہ نے ورقاء سے انھوں نے عمرو بن دینار سے ، انھوں نے عطاء بن یسار سے ، انہوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ صلی اللہ علیہ وسلم نے فرمایا ، \" جب نماز کے لئے اقامت ہوجائے تو فرض نماز کے سوا کوئی نماز نہیں ۔","",{"u2":"شعبہ نے ورقاء سے انھوں نے عمرو بن دینار سے،انھوں نے عطاء بن یسار سے،انہوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی،آپ صلی اللہ علیہ وسلم نے فرمایا،\"جب نماز کے لئے اقامت ہوجائے تو فرض نماز کے سوا کوئی نماز نہیں۔\""}],[1583,"شعبہ نے ورقاء سے انھوں نے عمرو بن دینار سے ، انھوں نے عطاء بن یسار سے ، انہوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ صلی اللہ علیہ وسلم نے فرمایا ، \" جب نماز کے لئے اقامت ہوجائے تو فرض نماز کے سوا کوئی نماز نہیں ۔","",{"u2":"(شعبہ کی بجائے) شبابہ نے ورقاء سے یہی روایت اسی سند کے ساتھ بیان کی ہے۔"}],[1584,"(شعبہ کی بجائے ) شبابہ نے ورقاء سے یہی روایت اسی سند کے ساتھ بیان کی ہے ۔","",{"u2":"روح نے کہا:ہمیں زکریا بن اسحاق نے حدیث سنائی،انھوں نے کہا،ہمیں عمرو بن دینار نے حدیث سنائی،انہوں نے کہا: میں نے عطاء بن یسار سے سنا وہ کہہ رہے تھے:حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت ہے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا:\"جب نماز کے لئے اقامت کہی جائے تو فرض نماز کے سوا کوئی نماز نہیں ہوتی۔\""}],[1585,"روح نے کہا : ہمیں زکریا بن اسحاق نے حدیث سنائی ، انھوں نے کہا ، ہمیں عمرو بن دینار نے حدیث سنائی ، انہوں نے کہا : میں نے عطاء بن یسار سے سنا وہ کہہ رہے تھے : سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت ہے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جب نماز کے لئے اقامت کہی جائے تو فرض نماز کے سوا کوئی نماز نہیں ہوتی ۔","",{"u2":"(روح کی بجائے) عبدالرزاق نے خبر دی کہ ہمیں زکریا بن اسحاق نے اسی سند کے ساتھ اسی طرح خبر دی۔"}],[1586,"(روح کی بجائے ) عبدالرزاق نے خبر دی کہ ہمیں زکریا بن اسحاق نے اسی سند کے ساتھ اسی طرح خبر دی ۔","",{"u2":"حماد بن زید نے ایوب سے روایت کی،انھوں نے عمرو بن دینار سے انھوں نے عطاء بن یسار سے انہوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے سابقہ حدیث کی مانند روایت کی۔حماد نے کہا:پھر میں (براہ راست) عمرو(بن دینار) سے ملا تو انھوں نے مجھے یہ حدیث سنائی لیکن انہوں نے اس حدیث کو رسول اللہ صلی اللہ علیہ وسلم کی طرف منسوب نہیں کیا۔(ابو ہریرہ رضی اللہ تعالیٰ عنہ کا قول روایت کیا)"}],[1587,"عبداللہ بن مسلمہ قعنبی نے ہمیں حدیث بیان کی ، کہا ہمیں ابراہیم بن سعد نے اپنے والد سے حدیث سنائی ۔ انھوں نے حفص بن عاصم سے اور ا نھوں نے عبداللہ بن مالک ابن بحینہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک شخص کے پاس سے گزرے جو نماز پڑھ رہاتھا جب صبح کی نماز کے لئے اقامت کہی جاچکی تھی آپ نے کسی چیز کے بارے میں اس سے گفتگو فرمائی ہم نہ جان سکے کہ وہ کیا تھی جب ہم نماز سے فارغ ہوئے تو ہم نے اسے گھیرلیا ہم پوچھ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے تم سے کیا کہا؟اس نے بتایا : آپ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \"\" لگتا ہے کہ تم میں سے کوئی صبح کی چار رکعات پڑھنے لگے گا ۔ \"\" قعنبی نے کہا : عبداللہ بن مالک ابن بحینہ نے رضی اللہ تعالیٰ عنہ نے اپنے والد سے روایت کی ۔ ابو الحسین مسلم ؒ ( مولف کتاب ) نے کہا : قعنبی کا اس حدیث میں \"\" «عَنْ أَبِيهِ» \"\" ( والد سے روایت کی ) کہنا درست نہیں ۔ ( عبداللہ کے والد صحابی مالک صحابی تو ہیں لیکن ان سے کوئی حدیث مروی نہیں)","",{"u2":"عبداللہ بن مسلمہ قعنبی نے ہمیں حدیث بیان کی،کہا ہمیں ابراہیم بن سعد نے اپنے والد سے حدیث سنائی۔انھوں نے حفص بن عاصم سے اور ا نھوں نے عبداللہ بن مالک ابن بحینہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک شخص کے پاس سے گزرے جو نماز پڑھ رہاتھا جب صبح کی نماز کے لئے اقامت کہی جاچکی تھی آپ نے کسی چیز کے بارے میں اس سے گفتگو فرمائی ہم نہ جان سکے کہ وہ کیا تھی جب ہم نماز سے فارغ ہوئے تو ہم نے اسے گھیرلیا ہم پوچھ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے تم سے کیا کہا؟اس نے بتایا:آپ صلی اللہ علیہ وسلم نے مجھ سے فرمایا:\" لگتا ہے کہ تم میں سے کوئی صبح کی چار رکعات پڑھنے لگے گا۔\"\nقعنبی نے کہا:عبداللہ بن مالک ابن بحینہ نے رضی اللہ تعالیٰ عنہ نے اپنے والد سے روایت کی۔\nابو الحسین مسلم رحمہ اللہ (مولف کتاب) نے کہا:قعنبی کا اس حدیث میں \" عَنْ أَبِیہِ\"(والد سے روایت کی) کہنا درست نہیں۔(عبداللہ کے والد صحابی مالک صحابی تو ہیں لیکن ان سے کوئی حدیث مروی نہیں)-"}],[1588,"ابو عوانہ نے سعد بن ابراہیم سے ، انہوں نے حفص بن عاصم سے ، اور انہوں نے سیدنا ( عبداللہ ) ابن بحینہ رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : صبح کی نماز کی اقامت ( شروع ) ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو نماز پڑھتے دیکھا جبکہ موذن اقامت کہہ رہا ہے تو آپ نے فرمایا : \" کیا تم صبح کی چار رکعتیں پڑھو گے؟","",{"u2":"ابو عوانہ نے سعد بن ابراہیم سے،انہوں نے حفص بن عاصم سے،اورانہوں نے حضرت (عبداللہ) ابن بحینہ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:صبح کی نماز کی اقامت(شروع) ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو نماز پڑھتے دیکھا جبکہ موذن اقامت کہہ رہا ہے تو آپ نے فرمایا:\" کیا تم صبح کی چار رکعتیں پڑھو گے؟\""}],[1589,"سیدنا عبداللہ بن سرجس ( المزنی حلیف بنی مخزوم رضی اللہ تعالیٰ عنہ ) سے روایت ہے ، انھوں نے کہا : ایک آدمی مسجد میں آیا جبکہ رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز پڑھا رہے تھے ، اس نے مسجد کے ایک کونے میں دو رکعتیں پڑھیں ، پھر رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز میں شریک ہوگیا ، جب رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا تو فرمایا : \" اے فلاں! تو نے دو نمازوں میں سے کون سی نماز کو شمار کیا ہے؟اپنی اس نماز کو جو تم نے اکیلے پڑھی ہے یا اس کو جو ہمارے ساتھ پڑھی ہے؟","",{"u2":"حضرت عبداللہ بن سرجس(المزنی حلیف بنی مخزوم رضی اللہ تعالیٰ عنہ) سے روایت ہے،انھوں نے کہا:ایک آدمی مسجد میں آیا جبکہ رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز پڑھا رہے تھے،اس نے مسجد کے ایک کونے میں دو رکعتیں پڑھیں،پھر رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز میں شریک ہوگیا،جب ر سول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا تو فرمایا:\" اے فلاں! تو نے دو نمازوں میں سے کون سی نماز کو شمار کیا ہے؟اپنی اس نماز کو جو تم نے اکیلے پڑھی ہے یا اس کو جو ہمارے ساتھ پڑھی ہے؟\""}],[1590,"(یحییٰ بن یحییٰ نے کہا : ہمیں سلمان بن بلال نے ربعیہ بن عبدالرحمان سے خبر دی ، انھوں نے عبدالملک بن سعید سے ، اور انھوں نے سیدنا ابو حمید رضی اللہ تعالیٰ عنہ ۔ یا سیدنا ابو اسید رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا \"\" جب تم میں سے کوئی شخص مسجد میں داخل ہوتو کہے \"\" «اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ» \"\" اے اللہ! میرے لئے اپنی رحمت کے دروازے کھول دے ۔ اور جب مسجد سے نکلے تو کہے \"\" «اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ» \"\" اے اللہ! میں تجھ سے تیرے فضل کا سوال کرتاہوں ۔ \"\" امام مسلم ؒ نے کہا : میں نے یحییٰ بن یحییٰ س سنا ، وہ کہتے تھے ، میں نے یہ حدیث سلیمان بن بلال کی کتاب سے لکھی ہے ، انھوں نے کہا : مجھے یہ خبر پہنچی ہے ۔ کہ یحییٰ حمانی شک کے بغیر ) \"\" وأبي أسيداور ابو اسید \"\" سے کہتے تھے ۔","",{"u2":"یحییٰ بن یحییٰ نے کہا: ہمیں سلمان بن بلال نے ربعیہ بن عبدالرحمان سے خبر دی،انھوں نے عبدالملک بن سعید سے، اور انھوں نے حضرت ابو حمید رضی اللہ تعالیٰ عنہ۔یا حضرت ابو اسید رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا،رسول اللہ صلی اللہ علیہ وسلم نے فرمایا\"جب تم میں سے کوئی شخص مسجد میں داخل ہوتو کہے\"اللَّہُمَّ افْتَحْ لِی أَبْوَابَ رَحْمَتِکَ\"اے اللہ! میرے لئے اپنی رحمت کے دروازے کھول دے۔اور جب مسجد سے نکلے تو کہے\"اللَّہُمَّ إِنِّی أَسْأَلُکَ مِنْ فَضْلِکَ\"اے اللہ! میں تجھ سے تیرے فضل کا سوال کرتاہوں۔\"\nامام مسلم رحمہ اللہ نے کہا: میں نے یحییٰ بن یحییٰ س سنا،وہ کہتے تھے،میں نے یہ حدیث سلیمان بن بلال کی کتاب سے لکھی ہے،انھوں نے کہا:مجھے یہ خبر پہنچی ہے۔کہ یحییٰ حمانی شک کے بغیر)\" وأبی أسیداور ابو اسید\" سے کہتے تھے۔"}],[1591,"(سلیمان بن بلال کے بجائے ) عمارہ بن غزیہ نے ربیعہ بن ابی عبدالرحمان سے روایت کی ، انھوں نے عبدالملک بن سعید بن سوید انصاری سے ۔ انھوں نے سیدنا ابو حمید ۔ ۔ ۔ یا سیدنا ابو اسید رضی اللہ تعالیٰ عنہ سے اور ا نھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"(سلیمان بن بلال کے بجائے) عمارہ بن غزیہ نے ربیعہ بن ابی عبدالرحمان سے روایت کی،انھوں نے عبدالملک بن سعید بن سوید انصاری سے۔انھوں نے حضرت ابو حمید۔۔۔یا حضرت ابو اسید رضی اللہ تعالیٰ عنہ سے اور ا نھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[1592,"عامر بن عبداللہ بن زبیر نے عمرو بن سلیم زرقی سے اور انھوں نے سیدنا ابو قتادہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص مسجد میں داخل ہوتو بیٹھنے سے پہلے دو رکعت نماز پڑھے ۔","",{"u2":"عامر بن عبداللہ بن زبیر نے عمرو بن سلیم زرقی سے اور انھوں نے حضرت ابو قتادہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جب تم میں سے کوئی شخص مسجد میں داخل ہوتو بیٹھنے سے پہلے دو رکعت نماز پڑھے۔\""}],[1593,"محمد بن یحییٰ بن حبان نے عمرو بن سلیم بن خلدہ انصاری سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے صحابی سیدنا ابو قتادہ رضی اللہ تعالیٰ عنہ سے ر وایت کی ، کہا : میں مسجد میں داخل ہوا جبکہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کے درمیان تشریف فرما تھے کہا : تو میں بھی بیٹھ گیا ، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تمھیں بیٹھنے سے پہلے دو رکعات نماز پڑھنے سے کس چیز نے روکا ہے؟ \" میں نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم !میں نے آپ کو بیٹھتے دیکھا ہے اور لوگ بھی بیٹھے تھے ( اس لئے میں بھی بیٹھ گیا ) آپ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص مسجد میں آئے تو دو رکعت نماز پڑھےبغير نہ بیٹھے ۔","",{"u2":"محمد بن یحییٰ بن حبان نے عمرو بن سلیم بن خلدہ انصاری سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے صحابی حضرت ابو قتادہ رضی اللہ تعالیٰ عنہ سے ر وایت کی،کہا: میں مسجد میں داخل ہوا جبکہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کے درمیان تشریف فرما تھے کہا:تو میں بھی بیٹھ گیا،اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تمھیں بیٹھنے سے پہلے دو رکعات نماز پڑھنے سے کس چیز نے روکا ہے؟\" میں نے عرض کی:اےا للہ کے رسول صلی اللہ علیہ وسلم!میں نے آپ کو بیٹھتے دیکھا ہے اور لوگ بھی بیٹھے تھے(اس لئے میں بھی بیٹھ گیا) آپ صلی اللہ علیہ وسلم نے فرمایا:\" جب تم میں سے کوئی شخص مسجد میں آئے تو دو رکعت نماز پڑھےبغیر نہ بیٹھے۔"}],[1594,"سفیان بن محارب بن وثار سے اور انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میرا نبی اکرم صلی اللہ علیہ وسلم کے ذمے قرض تھا ، آپ نے اسے ادا کیا اور مجھے زائد رقم دی اور جب میں آپ کی مسجد میں داخل ہوا تو آپ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \" دو رکعت نماز ادا کرلو ۔","",{"u2":"سفیان بن محارب بن وثار سے اور انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:میرا نبی اکرم صلی اللہ علیہ وسلم کے ذمے قرض تھا،آپ نے اسے ادا کیا اور مجھے زائد رقم دی اور جب میں آپ کی مسجد میں داخل ہوا تو آپ صلی اللہ علیہ وسلم نے مجھ سے فرمایا:\"دو رکعت نماز ادا کرلو۔\""}],[1595,"شعبہ نے محارب سے روایت کی ، انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے سنا ، کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے ایک اونٹ خریدا ، جب آپ صلی اللہ علیہ وسلم مدینہ پہنچے تو آپ صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ میں مسجد میں آؤں ، اور دو رکعتیں پڑھوں ۔","",{"u2":"شعبہ نے محارب سے روایت کی،انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے سنا،کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے ایک اونٹ خریدا،جب آپ صلی اللہ علیہ وسلم مدینہ پہنچے تو آپ صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ میں مسجد میں آؤں،اور دو رکعتیں پڑھوں۔"}],[1596,"وہب بن کیسان نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں ایک غزوے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلا ، میرے اونٹ نے مجھے دیر کرادی اور تھک گیا ۔ رسول اللہ صلی اللہ علیہ وسلم مجھ سے پہلے مدینہ میں آگئے اور میں اگلے دن پہنچا ، میں مسجد میں آیا تو میں نے آپ صلی اللہ علیہ وسلم کو مسجد کے دروازے پر پایا ۔ آپ صلی اللہ علیہ وسلم نے پوچھا : \" تم اب اس وقت تک پہنچے ہو؟ \" میں نے کہا : جی ہاں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اپنا اونٹ چھوڑ دو اور مسجد میں داخل ہوکر دو رکعتیں پڑھو ۔ \" میں مسجد میں داخل ہوا ، نماز پڑھی ، پر واپس ( آپ صلی اللہ علیہ وسلم کے پاس ) آیا ۔","",{"u2":"وہب بن کیسان نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا: میں ایک غزوے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلا،میرے اونٹ نے مجھے دیر کرادی اور تھک گیا۔رسول اللہ صلی اللہ علیہ وسلم مجھ سے پہلے مدینہ میں آگئے اور میں اگلے دن پہنچا،میں مسجد میں آیا تو میں نے آپ صلی اللہ علیہ وسلم کو مسجد کے دروازے پر پایا۔آپ صلی اللہ علیہ وسلم نے پوچھا:\"تم اب اس وقت تک پہنچے ہو؟\"میں نے کہا:جی ہاں۔آپ صلی اللہ علیہ وسلم نے فرمایا:\" اپنا اونٹ چھوڑ دو اور مسجد میں داخل ہوکر دو رکعتیں پڑھو۔\"میں مسجد میں داخل ہوا،نماز پڑھی،پر واپس (آپ صلی اللہ علیہ وسلم کے پاس) آیا۔"}],[1597,"سیدنا کعب بن مالک رضی اللہ تعالیٰ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم دن میں چاشت کے وقت کے سوا ( کسی اور وقت ) سفر سے واپس تشریف نہ لاتے ، پھر جب تشریف لاتے تو مسجد جاتے ، اس میں دو رکعتیں ادا کرتے ، پھر ( کچھ دیر ) وہیں تشریف رکھتے ( تاکہ گھر والوں کو آپ صلی اللہ علیہ وسلم کی آمد کا علم ہوجائے ) ۔","",{"u2":"حضرت کعب بن مالک رضی اللہ تعالیٰ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم دن میں چاشت کے وقت کے سوا(کسی اور وقت) سفر سے واپس تشریف نہ لاتے،پھر جب تشریف لاتے تو مسجد جاتے،اس میں دو رکعتیں ادا کرتے،پھر(کچھ دیر) وہیں تشریف رکھتے(تاکہ گھر والوں کو آپ صلی اللہ علیہ وسلم کی آمد کا علم ہوجائے)۔"}],[1598,"سعید جزیری نے عبداللہ بن شقیق سے روایت کی ، انھوں نےکہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا : کیا نبی اکرم صلی اللہ علیہ وسلم چاشت کی نماز پڑھتے تھے؟انھوں نے کہا : نہیں ، الا یہ کہ باہر ( سفر ) سے واپس آئے ہوں ۔","",{"u2":"سعید جزیری نے عبداللہ بن شقیق سے روایت کی،انھوں نےکہا: میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا: کیا نبی اکرم صلی اللہ علیہ وسلم چاشت کی نماز پڑھتے تھے؟انھوں نے کہا: نہیں،الا یہ کہ باہر(سفر) سے واپس آئے ہوں۔"}],[1599,"کیمس بن حسن قیسی نے عبداللہ بن شقیق سے روایت کی ، انھوں نے کہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا : کیا نبی اکرم صلی اللہ علیہ وسلم چاشت کی نماز پڑھا کرتے تھے؟ انھوں نے جواب دیا : نہیں الا یہ کہ سفر سے واپس آئے ہوں ۔","",{"u2":"کیمس بن حسن قیسی نے عبداللہ بن شقیق سے روایت کی،انھوں نے کہا:میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا: کیانبی اکرم صلی اللہ علیہ وسلم چاشت کی نماز پڑھا کرتے تھے؟\nانھوں نے جواب دیا:نہیں الا یہ کہ سفر سے واپس آئے ہوں۔"}],[1600,"سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت ہے ، انھوں نے کہا : میں نے کبھی رسول اللہ صلی اللہ علیہ وسلم کو ( گھر میں قیام کے دوران میں ) چاشت کے نفل پڑھتے نہیں دیکھا ، جبکہ میں چاشت کی نماز پڑھتی ہوں ۔ یہ بات یقینی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کسی کام کو کرنا پسند فرماتے تھے ۔ لیکن اس ڈر سے کہ لوگ ( بھی آپ کو دیکھ کر ) وہ کام کریں گےاور ( ان کی د لچسپی کی بناء پر ) وہ کام ان پر فرض کردیا جائے گا ، آپ صلی اللہ علیہ وسلم اس کام کو چھوڑ دیتے تھے ۔","",{"u2":"حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت ہے،انھوں نے کہا:میں نے کبھی ر سول اللہ صلی اللہ علیہ وسلم کو (گھر میں قیام کے دوران میں) چاشت کے نفل پڑھتے نہیں دیکھا،جبکہ میں چاشت کی نماز پڑھتی ہوں۔یہ بات یقینی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کسی کام کو کرنا پسند فرماتے تھے۔لیکن اس ڈر سے کہ لوگ(بھی آپ کو دیکھ کر) وہ کام کریں گےاور (ان کی د لچسپی کی بناء پر) وہ کام ان پر فرض کردیا جائے گا،آپ صلی اللہ علیہ وسلم اس کام کو چھوڑ دیتے تھے۔"}],[1601,"عبدالوارث نے کہا : ہمیں یزید رشک نے حدیث سنائی ، انھوں نے کہا ، مجھے معاذہ نے حدیث سنائی ، انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے سوال کیا کہ رسول اللہ صلی اللہ علیہ وسلم چاشت کی نماز کتنی ( رکعتیں ) پڑھتے تھے؟انھوں نے جواب دیا چار رکعتیں اور جس قدر زیادہ پڑھنا چاہتے ( پڑھ لیتے ) ۔","",{"u2":"عبدالوارث نے کہا: ہمیں یزید رشک نے حدیث سنائی،انھوں نے کہا،مجھے معاذہ نے حدیث سنائی،انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے سوال کیا کہ رسول اللہ صلی اللہ علیہ وسلم چاشت کی نماز کتنی (رکعتیں) پڑھتے تھے؟انھوں نے جواب دیا چار رکعتیں اور جس قدر زیادہ پڑھنا چاہتے(پڑھ لیتے)۔"}],[1602,"شعبہ نے یزید سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی اور یزید نے ( ماشاء کے بجائے ) ماشاء اللہ ( جتنی اللہ چاہتا ) کہا ۔","",{"u2":"شعبہ نے یزید سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی اور یزید نے(ماشاء کے بجائے) ماشاء اللہ (جتنی اللہ چاہتا) کہا۔"}],[1603,"سعید نے کہا : قتادہ نے ہمیں حدیث بیان کی کہ معاذہ عدویہ نے ان ( حدیث سننے والوں ) کو سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے حدیث سنائی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم چاشت کی نماز چار رکعتیں پڑھتے تھے ۔ اور اللہ تعالیٰ جس قدر چاہتا زیادہ ( بھی ) پڑھ لیتے ۔","",{"u2":"سعید نے کہا:قتادہ نے ہمیں حدیث بیان کی کہ معاذہ عدویہ نے ان (حدیث سننے والوں) کو حضرت عائشہ رضی اللہ تعالیٰ عنہا سے حدیث سنائی،انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم چاشت کی نماز چار رکعتیں پڑھتے تھے۔اور اللہ تعالیٰ جس قدر چاہتا زیادہ (بھی) پڑھ لیتے۔"}],[1604,"معاذ بن ہشام نے روایت کی ، کہا : مجھے میرے والد نے قتادہ سے اسی سند کےساتھ یہی حدیث بیان کی ۔","",{"u2":"معاذ بن ہشام نے روایت کی،کہا: مجھے میرے والد نے قتادہ سے اسی سند کےساتھ یہی حدیث بیان کی۔"}],[1605,"محمد بن مثنیٰ اور ابن بشار نے ہمیں حدیث بیان کی ، کہا : ہمیں محمد بن جعفر نے حدیث سنائی ، کہا : ہمیں شعبہ نے عمرو بن مرہ سے انھوں نے عبدالرحمان بن ابی لیلیٰ سے حدیث سنائی ، انھوں نے کہا : مجھے ام ہانی رضی اللہ تعالیٰ عنہا کے سوا کسی نے یہ نہیں بتایا کہ اس نے نبی اکرم صلی اللہ علیہ وسلم کو چاشت کی نماز پڑھتے دیکھا ۔ انھوں نے بتایا کہ فتح مکہ کے دن نبی اکرم صلی اللہ علیہ وسلم ان کے گھر میں تشریف لائے اور آپ نے آٹھ رکعتیں پڑھیں ، میں نے آپ کو کبھی اس سے ہلکی نماز پڑھتے نہیں دیکھا ، ہاں آپ رکوع اور سجود مکمل طریقے سے کررہے تھے ۔ ابن بشار نے اپنی روایات میں قط ( کبھی ) کا لفظ بیان نہیں کیا ۔","",{"u2":"محمد بن مثنیٰ اور ابن بشار نے ہمیں حدیث بیان کی،کہا:ہمیں محمد بن جعفر نے حدیث سنائی،کہا:ہمیں شعبہ نے عمرو بن مرہ سے انھوں نے عبدالرحمان بن ابی لیلیٰ سے حدیث سنائی،انھوں نے کہا:مجھے ام ہانی رضی اللہ تعالیٰ عنہا کے سوا کسی نے یہ نہیں بتایا کہ اس نے نبی اکرم صلی اللہ علیہ وسلم کو چاشت کی نماز پڑھتے دیکھا۔انھوں نے بتایا کہ فتح مکہ کے دن نبی اکرم صلی اللہ علیہ وسلم ان کے گھر میں تشریف لائے اور آپ نے آٹھ رکعتیں پڑھیں،میں نے آپ کو کبھی اس سے ہلکی نمازپڑھتے نہیں دیکھا،ہاں آپ رکوع اور سجود مکمل طریقے سے کررہے تھے۔\nابن بشار نے اپنی روایات میں قط(کبھی) کا لفظ بیان نہیں کیا۔"}],[1606,"حرملہ بن یحیٰٰ اور محمد بن سلمہ مرادی دونوں نے مجھے حدیث بیان کی ، کہا : ہمیں عبداللہ بن وہب نے خبر دی ، انھوں نے کہا : مجھے یونس نے ابن شہاب سے خبر دی ، کہا : مجھے عبداللہ بن حارث کے بیٹے نے حدیث سنائی کہ ان کے والد عبداللہ بن حارث بن نوفل نے کہا : میں نے ( سب سے ) پوچھا اور میری یہ شدید خواہش تھی کہ مجھے کوئی ایک شخص مل جائے جو مجھے بتائے کہ رسول اللہ صلی اللہ علیہ وسلم نے چاشت کی نماز پڑھی ہے ۔ مجھے ام ہانی بنت ابی طالب رضی اللہ تعالیٰ عنہا کے سوا کوئی نہ ملا جو مجھے یہ بتاتا ۔ انھوں نے مجھے خبر دی کہ فتح مکہ کے دن رسول اللہ صلی اللہ علیہ وسلم دن بلند ہونے کے بعد تشریف لائے ، ایک کپڑا لا کر آپ کو پردہ مہیا کیاگیا ، آپ نے غسل فرمایا ، پھر آپ کھڑ اہوئے اور آٹھ رکعتیں پڑھیں ۔ میں نہیں جانتی کہ ان میں آپ کا قیام ( نسبتاً ) زیادہ لمبا تھا یا آپ کا رکوع یا آپ کا سجود یہ سب ( ارکان ) قریب قریب تھے اور انھوں نے ( ام ہانی رضی اللہ تعالیٰ عنہا ) نے بتایا ، میں نے ا س سے پہلے اور اس کے بعد آپ کو نہیں دیکھا کہ آپ نے یہ نماز پڑھی ہو ۔ ( محمد بن مسلمہ ) مرادی نے اپنی روایت میں \"\" یونس سے روایت ہے \"\" کہا ۔ \"\" مجھے یونس نے خبر دی \"\" نہیں کہا ۔","",{"u2":"حرملہ بن یحیٰٰ اور محمد بن سلمہ مرادی دونوں نے مجھے حدیث بیان کی،کہا:ہمیں عبداللہ بن وہب نے خبر دی،انھوں نے کہا:مجھے یونس نے ابن شہاب سے خبر دی،کہا:مجھے عبداللہ بن حارث کے بیٹے نے حدیث سنائی کہ ان کے والد عبداللہ بن حارث بن نوفل نے کہا:میں نے(سب سے) پوچھا اور میری یہ شدید خواہش تھی کہ مجھے کوئی ایک شخص مل جائے جو مجھے بتائے کہ رسول اللہ صلی اللہ علیہ وسلم نے چاشت کی نماز پڑھی ہے۔مجھے ام ہانی بنت ابی طالب رضی اللہ تعالیٰ عنہا کے سوا کوئی نہ ملا جو مجھے یہ بتاتا۔انھوں نے مجھے خبر دی کہ فتح مکہ کے دن رسول اللہ صلی اللہ علیہ وسلم دن بلند ہونے کے بعد تشریف لائے،ایک کپڑا لا کر آپ کو پردہ مہیا کیاگیا،آپ نے غسل فرمایا،پھر آپ کھڑ اہوئے اور آٹھ رکعتیں پڑھیں۔میں نہیں جانتی کہ ان میں آپ کا قیام(نسبتاً) زیادہ لمبا تھا یا آپ کا رکوع یا آپ کا سجود یہ سب (ارکان) قریب قریب تھے اور انھوں نے (ام ہانی رضی اللہ تعالیٰ عنہا) نے بتایا،میں نے ا س سے پہلے اور اس کے بعد آپ کو نہیں دیکھا کہ آپ نے یہ نماز پڑھی ہو۔\n(محمد بن مسلمہ) مرادی نے اپنی روایت میں \"یونس سے روایت ہے\" کہا۔\"مجھے یونس نے خبر دی\" نہیں کہا۔"}],[1607,"ابو نضر سے روایت ہے کہ ام ہانی بنت ابی طالب رضی اللہ تعالیٰ عنہا کو یہ کہتے ہوئے سنا کہ میں فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم کی طرف گئی تو میں نے آپ صلی اللہ علیہ وسلم کو نہاتے ہوئے پایا جبکہ آپ کی بیٹی فاطمہ رضی اللہ تعالیٰ عنہا آپ کو کپڑے سےچھپائے ہوئے تھیں ( آگے پردہ کیا ہوا تھا ) میں نے سلام عرض کیا ، آپ صلی اللہ علیہ وسلم نے پوچھا یہ کون ہے؟میں نے کہا : ام ہانی بنت ابی طالب ہوں ۔ آپ نے فرمایا : \" ام ہانی کو خوش آمدید! \" جب آپ نہانے سے فارغ ہوئے تو کھڑے ہوئے اور صرف ایک کپڑے میں لپٹے ہوئے آٹھ رکعتیں پڑھیں ، جب آپ نماز سے فارغ ہوگئے تو میں نے کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم میرا ماں جایا بھائی علی بن ابی طالب رضی اللہ تعالیٰ عنہ چاہتا ہے کہ ایک ایسے آدمی کو قتل کردے جسے میں نے پناہ دے چکی ہوں ۔ یعنی ہبیرہ کا بیٹا ، فلاں ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : امی ہانی! جس کو تم نے پناہ دی اسے ہم نے بھی پناہ دی ۔","",{"u2":"ابو نضر سے روایت ہے کہ ام ہانی بنت ابی طالب رضی اللہ تعالیٰ عنہا کو یہ کہتے ہوئے سنا کہ میں فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم کی طرف گئی تو میں نے آپ صلی اللہ علیہ وسلم کو نہاتے ہوئے پایا جبکہ آپ کی بیٹی فاطمہ رضی اللہ تعالیٰ عنہا آپ کو کپڑے سےچھپائے ہوئے تھیں (آگے پردہ کیا ہوا تھا) میں نے سلام عرض کیا،آپ صلی اللہ علیہ وسلم نے پوچھا یہ کون ہے؟میں نے کہا: ام ہانی بنت ابی طالب ہوں۔آپ نے فرمایا:\"ام ہانی کو خوش آمدید!\"جب آپ نہانے سے فارغ ہوئے تو کھڑے ہوئے اور صرف ایک کپڑے میں لپٹے ہوئے آٹھ رکعتیں پڑھیں،جب آپ نماز سے فارغ ہوگئے تو میں نے کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم میرا ماں جایا بھائی علی بن ابی طالب رضی اللہ تعالیٰ عنہ چاہتا ہے کہ ایک ایسے آدمی کو قتل کردے جسے میں نے پناہ دے چکی ہوں۔یعنی ہبیرہ کا بیٹا،فلاں،تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:امی ہانی! جس کو تم نے پناہ دی اسے ہم نے بھی پناہ دی۔\""}],[1608,"جعفر بن محمد ؒ کے والد محمد باقرؒ نے عقیل کے آزاد کردہ غلام ابو مرہ سے اور انھوں نے سیدہ ام ہانی رضی اللہ تعالیٰ عنہا سے روایت کی کہ فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم نے ان کے گھر میں ایک کپڑے میں جس کے دونوں کنارے ایک دوسرے کی مخالف جانب ڈالے گئے تھے ، آٹھ رکعتیں پڑھیں ۔","",{"u2":"جعفر بن محمد رحمہ اللہ کے والد محمد باقر رحمہ اللہ نے عقیل کے آزاد کردہ غلام ابو مرہ سے اور انھوں نے حضرت ام ہانی رضی اللہ تعالیٰ عنہا سے روایت کی کہ فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم نے ان کے گھر میں ایک کپڑے میں جس کے دونوں کنارے ایک دوسرے کی مخالف جانب ڈالے گئے تھے،آٹھ رکعتیں پڑھیں۔"}],[1609,"سیدنا ابو زر رضی اللہ تعالیٰ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" صبح کو تم میں سے ہر ایک شخص کے ہر جوڑ پر ایک صدقہ ہوتا ہے ۔ پس ہر ایک تسبیح ( ایک دفعہ \" سبحا ن اللہ \" کہنا ) صدقہ ہے ۔ ہر ایک تمحید ( الحمد لله کہنا ) ) صدقہ ہے ، ہر ایک تہلیل ( لااله الا اللہ کہنا ) صدقہ ہے ہرہر ایک تکبیر ( الله اكبرکہنا ) بھی صدقہ ہے ۔ ( کسی کو ) نیکی کی تلقین کرنا صدقہ ہے اور ( کسی کو ) برائی سے روکنا بھی صدقہ ہے ۔ اور ان تمام امور کی جگہ دو رکعتیں جو انسان چاشت کے وقت پڑھتا ہے کفایت کرتی ہیں ۔","",{"u2":"حضرت ابو زر رضی اللہ تعالیٰ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا:\" صبح کو تم میں سے ہر ایک شخص کے ہر جوڑ پر ایک صدقہ ہوتا ہے۔پس ہر ایک تسبیح (ایک دفعہ \"سبحا ن اللہ\" کہنا)صدقہ ہے۔ہر ایک تمحید (الحمد للہ کہنا)) صدقہ ہے،ہر ایک تہلیل (لاالہ الا اللہ کہنا) صدقہ ہے ہرہر ایک تکبیر (اللہ اکبرکہنا) بھی صدقہ ہے۔(کسی کو) نیکی کی تلقین کرنا صدقہ ہے اور (کسی کو) برائی سے روکنا بھی صدقہ ہے۔اور ان تمام امور کی جگہ دو رکعتیں جو انسان چاشت کے وقت پڑھتا ہے کفایت کرتی ہیں۔\""}],[1610,"ابو تیاح نے کہا : ہمیں ابو عثمان نہدی نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے حدیث سنائی ، انھوں نے کہا : مجھے میر ےخلیل صلی اللہ علیہ وسلم نے تین چیزوں کی تلقین فرمائی ، ہر ماہ تین روزے رکھنے کی ، چاشت کی دورکعتوں کی اور اس بات کی کہ سونے سے پہلے وتر پڑھ لیا کروں ۔","",{"u2":"ابو تیاح نے کہا:ہمیں ابو عثمان نہدی نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے حدیث سنائی،انھوں نے کہا:مجھے میر ےخلیل صلی اللہ علیہ وسلم نے تین چیزوں کی تلقین فرمائی،ہر ماہ تین روزے رکھنے کی،چاشت کی دورکعتوں کی اور اس بات کی کہ سونے سے پہلے وتر پڑھ لیا کروں۔"}],[1611,"عباس ، جریری ، اور ابو شمرضبعی ، دونوں نے کہا : ہم نے ابو عثمان نہدی سے سنا ، وہ سیدنا ابوہریرۃ رضی اللہ تعالیٰ عنہ سے حدیث بیان کررہے تھے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی سابقہ حدیث کی مانند حدیث بیان کی ۔","",{"u2":"عباس،جریری،اور ابو شمرضبعی،دونوں نے کہا:ہم نے ابو عثمان نہدی سے سنا،وہ حضرت ابوہریرۃ رضی اللہ تعالیٰ عنہ سے حدیث بیان کررہے تھے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی سابقہ حدیث کی مانند حدیث بیان کی۔"}],[1612,"ابو رافع الصائغ نے کہا : میں نے سیدنا ابوہریرہ رضی اللہ تعالیٰ عنہ سے سنا ، انھوں نے کہا ، مجھے میرے خلیل ابو القاسم صلی اللہ علیہ وسلم نے تین باتوں کی تلقین فرمائی ۔ ۔ ۔ آگے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے ابو عثمان نہدی کی حدیث کی طرح بیان کیا ۔","",{"u2":"ابو رافع الصائغ نے کہا:میں نے حضرت ابوہریرہ رضی اللہ تعالیٰ عنہ سے سنا،انھوں نے کہا،مجھے میرے خلیل ابو القاسم صلی اللہ علیہ وسلم نے تین باتوں کی تلقین فرمائی۔۔۔آگے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے ابو عثمان نہدی کی حدیث کی طرح بیان کیا۔"}],[1613,"سیدنا ابو درداء رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : میرے حبیب صلی اللہ علیہ وسلم نے مجھے تین باتوں کی تلقین فرمائی ہے ، جب تک میں زندہ رہوں گا ان کو کبھی ترک نہیں کروں گا ، ہر ماہ تین دنوں کے روزے ، چاشت کی نماز اور یہ کہ جب تک وتر نہ پڑھ لوں نہ سوؤں ۔","",{"u2":"حضرت ابو درداء رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے کہا:میرےحبیب صلی اللہ علیہ وسلم نے مجھے تین باتوں کی تلقین فرمائی ہے،جب تک میں زندہ رہوں گا ان کو کبھی ترک نہیں کروں گا،ہر ماہ تین دنوں کے روزے،چاشت کی نماز اور یہ کہ جب تک وتر نہ پڑھ لوں نہ سوؤں۔"}],[1614,"امام مالک ؒ نے نافع سے اور انھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ ام المومنین سیدہ حفصہ رضی اللہ تعالیٰ عنہا نے انھیں بتایاکہ جب موذن صبح کی اذان کہہ کر خاموش ہوجاتا اور صبح ظاہر ہوجاتی تو رسول اللہ صلی اللہ علیہ وسلم نماز کی اقامت سے پہلے دو مختصر رکعتیں پڑھتے ۔","",{"u2":"امام مالک رحمہ اللہ نے نافع سے اور انھوں نے حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ ام المومنین حضرت حفصہ رضی اللہ تعالیٰ عنہا نے انھیں بتایاکہ جب موذن صبح کی اذان کہہ کر خاموش ہوجاتا اور صبح ظاہر ہوجاتی تو رسول اللہ صلی اللہ علیہ وسلم نماز کی اقامت سے پہلے دو مختصر رکعتیں پڑھتے۔"}],[1615,"لیث بن سعد ، عبیداللہ اور ایوب سب نے نافع سے اسی سند کے ساتھ اسی طرح روایت بیان کی ہے جس طرح امام مالک ؒ نے کی ۔","",{"u2":"لیث بن سعد،عبیداللہ اور ایوب سب نے نافع سے اسی سند کے ساتھ اسی طرح روایت بیان کی ہے جس طرح امام مالک رحمہ اللہ نے کی۔"}],[1616,"محمد بن جعفر نے کہا : ہمیں شعبہ نے زید بن محمد سے حدیث سنائی ، انھوں نے کہا : میں نے نافع سے سنا ، وہ سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے حدیث بیان کرتے تھے اور وہ سیدہ حفصہ رضی اللہ تعالیٰ عنہا سے روایت بیان کررہے تھے سیدہ حفصہ رضی اللہ تعالیٰ عنہا نے کہا : جب فجر طلوع ہوجاتی تو رسول اللہ صلی اللہ علیہ وسلم دو مختصر رکعتوں کے سوا کوئی نماز نہ پڑھتے تھے ۔","",{"u2":"محمد بن جعفر نے کہا:ہمیں شعبہ نے زید بن محمد سے حدیث سنائی،انھوں نے کہا:میں نے نافع سے سنا،وہ حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے حدیث بیان کرتے تھے اور وہ حضرت حفصہ رضی اللہ تعالیٰ عنہا سے روایت بیان کررہے تھے حضرت حفصہ رضی اللہ تعالیٰ عنہا نے کہا:جب فجر طلوع ہوجاتی تو رسول اللہ صلی اللہ علیہ وسلم دو مختصر رکعتوں کے سوا کوئی نماز نہ پڑھتے تھے۔"}],[1617,"(محمد بن جعفر کی بجائے ) نضر نے ہمیں خبر دی ، کہا : شعبہ نے اسی سند کے ساتھ اسی سابقہ حدیث کی مانند حدیث بیان کی ہے ۔","",{"u2":"(محمد بن جعفر کی بجائے)نضر نے ہمیں خبر دی،کہا:شعبہ نے اسی سند کے ساتھ اسی سابقہ حدیث کی مانند حدیث بیان کی ہے۔"}],[1618,"سالم نے اپنے والد ( عبداللہ بن عمر رضی اللہ تعالیٰ عنہ ) سے روایت کی ، انھوں نے کہا : سیدہ حفصہ رضی اللہ تعالیٰ عنہا نے مجھے خبر دی کہ نبی اکرم صلی اللہ علیہ وسلم کے سامنے جب فجر روشن ہوجاتی تو آپ دو رکعتیں نماز پڑھتے تھے ۔","",{"u2":"سالم نے اپنے والد(عبداللہ بن عمر رضی اللہ تعالیٰ عنہ)سے روایت کی،انھوں نے کہا:حضرت حفصہ رضی اللہ تعالیٰ عنہا نے مجھے خبر دی کہ نبی اکرم صلی اللہ علیہ وسلم کے سامنے جب فجر روشن ہوجاتی تو آپ دو رکعتیں نماز پڑھتے تھے۔"}],[1619,"عبدہ بن سلیمان نے کہا : ہمیں ہشام بن عروہ نے اپنے والد کے حوالے سے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے حدیث بیان کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم اذان سنتے تو فجر کی دو رکعتیں پڑھتے اور ان میں تخفیف کرتے تھے ۔","",{"u2":"عبدہ بن سلیمان نے کہا: ہمیں ہشام بن عروہ نے اپنے والد کے حوالے سے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے حدیث بیان کی،کہا:رسول اللہ صلی اللہ علیہ وسلم اذان سنتے تو فجر کی دو رکعتیں پڑھتے اور ان میں تخفیف کرتے تھے۔"}],[1620,"علی بن مسہر ، ابو اسامہ ، عبداللہ بن نمیر ، اور وکیع سب نے ہشام سے اسی سند کے ساتھ یہی حدیث روایت کی ، البتہ ابو اسامہ کی روایت میں ( جب اذان سننے کی بجائے ) \" جب فجر طلوع ہوتی \" کے الفاظ ہیں ۔","",{"u2":"علی بن مسہر،ابو اسامہ،عبداللہ بن نمیر،اور وکیع سب نے ہشام سے اسی سند کے ساتھ یہی حدیث روایت کی،البتہ ابو اسامہ کی روایت میں(جب اذان سننے کی بجائے)\"جب فجر طلوع ہوتی\"کے الفاظ ہیں۔"}],[1621,"ابو سلمہ نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم صبح کی نماز کی اذان اور اقامت کے درمیان دو رکعتیں پڑھتے تھے ۔","",{"u2":"ابو سلمہ نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم صبح کی نماز کی اذان اور اقامت کے درمیان دو رکعتیں پڑھتے تھے۔"}],[1622,"یحییٰ بن سعید نے کہا : مجھے محمد بن عبدالرحمان نے بتایا کہ انھوں نے عمرہ کو سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے حدیث بیان کرتے ہوئے سنا وہ کہا کرتی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی ( سنت ) دورکعتیں پڑھتے اور ان کو اتنا ہلکا پڑھتے کہ میں ( دل میں ) کہتی تھی : کیا آپ نے ان میں فاتحہ بھی پڑھی ہے یا نہیں؟ ( آپ صلی اللہ علیہ وسلم عموما فاتحہ بھی بہت ٹھر ٹھر کر پڑھتے تھے ۔)","",{"u2":"یحییٰ بن سعید نے کہا:مجھے محمد بن عبدالرحمان نے بتایا کہ انھوں نے عمرہ کوحضرت عائشہ رضی اللہ تعالیٰ عنہا سے حدیث بیان کرتے ہوئے سنا وہ کہا کرتی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی(سنت) دورکعتیں پڑھتے اور ان کو اتنا ہلکا پڑھتے کہ میں(دل میں) کہتی تھی: کیا آپ نے ان میں فاتحہ بھی پڑھی ہے یا نہیں؟(آپ صلی اللہ علیہ وسلم عموما فاتحہ بھی بہت ٹھر ٹھر کر پڑھتے تھے۔)"}],[1623,"شعبہ نے محمد بن عبدالرحمان انصاری سے روایت کی ۔ انھوں نے عمرہ بنت عبدالرحمان سے سنا ، انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، کہا جب فجر طلوع ہوجاتی تو رسول اللہ صلی اللہ علیہ وسلم دو رکعتیں ادا کرتے ۔ ( دل میں ) کہتی کیا آ پ صلی اللہ علیہ وسلم ان میں فاتحہ پڑھتے ہیں؟","",{"u2":"شعبہ نے محمد بن عبدالرحمان انصاری سے روایت کی۔انھوں نے عمرہ بنت عبدالرحمان سے سنا،انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،کہا جب فجر طلوع ہوجاتی تو رسول اللہ صلی اللہ علیہ وسلم دو رکعتیں ادا کرتے۔(دل میں) کہتی کیا آ پ صلی اللہ علیہ وسلم ان میں فاتحہ پڑھتے ہیں؟"}],[1624,"یحییٰ بن سعید نے ابن جریج سے روایت کی ، انھوں نے کہا : مجھے عطاء بن عبید بن عمیر سے حدیث سنائی اور ا نھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سےروایت کی کہ نبی کریم صلی اللہ علیہ وسلم نوافل میں سے کسی اور ( نماز ) کی اتنی زیادہ پاسداری نہیں کرتے تھے جتنی آپ صبح سے پہلے کی دو رکعتوں کی کرتے تھے ۔","",{"u2":"یحییٰ بن سعید نے ابن جریج سے روایت کی،انھوں نے کہا:مجھے عطاء بن عبید بن عمیر سے حدیث سنائی اور ا نھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سےروایت کی کہ نبی کریم صلی اللہ علیہ وسلم نوافل میں سے کسی اور (نماز) کی اتنی زیادہ پاسداری نہیں کرتے تھے جتنی آپ صبح سے پہلے کی دو رکعتوں کی کرتے تھے۔"}],[1625,"حفص نے ابن جریج سے باقی ماندہ اسی سند کے ساتھ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو کسی بھی نفل ( کی ادائیگی ) کے لئے اسقدر جلدی کرتے نہیں دیکھا جتنی جلدی آپ نماز فجر سے پہلے کی دو رکعتوں کے لئے کرتے تھے ۔","",{"u2":"حفص نے ابن جریج سے باقی ماندہ اسی سند کے ساتھ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو کسی بھی نفل(کی ادائیگی) کے لئے اسقدر جلدی کرتے نہیں دیکھاجتنی جلدی آپ نماز فجر سے پہلے کی دو رکعتوں کے لئے کرتے تھے۔"}],[1626,"ابو عوانہ نے قتادہ سے ، انھوں نے زرارہ بن اوفیٰ سے ، انھوں نے سعد بن ہشام سے ، انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے اور ا نھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" فجر کی دو رکعتیں دنیا اور جو کچھ دنیا میں ہے ، اس سے بہتر ہیں ۔","",{"u2":"ابو عوانہ نے قتادہ سے،انھوں نے زرارہ بن اوفیٰ سے،انھوں نے سعد بن ہشام سے،انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے اور ا نھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا:\"فجر کی دو رکعتیں دنیا اور جو کچھ دنیا میں ہے، اس سے بہتر ہیں۔\""}],[1627,"معتمر کے والد سلیمان بن طرخان نے قتادہ سے اسی سند کے ساتھ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے طلوع فجر کے وقت کی دورکعتوں کے بارے میں فرمایا : \" وہ دو ( رکعتیں ) مجھے ساری دنیا سے زیادہ پسند ہیں ۔","",{"u2":"معتمر کے والد سلیمان بن طرخان نے قتادہ سے اسی سند کے ساتھ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے طلوع فجر کے وقت کی دورکعتوں کے بارے میں فرمایا:\"وہ دو (رکعتیں) مجھے ساری دنیا سے زیادہ پسند ہیں۔\""}],[1628,"سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فجر کی دو رکعتوں میں ( «قُلْ يَا أَيُّهَا» الْكَافِرُ‌ونَ ) اور ( «قُلْ هُوَ» اللہ أَحَدٌ ) تلاوت کیں ۔","",{"u2":"حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فجر کی دو رکعتوں میں (قُلْ یَا أَیُّہَا الْکَافِرُ‌ونَ) اور (قُلْ ہُوَ اللہ أَحَدٌ) تلاوت کیں۔"}],[1629,"مروان بن معاویہ فزاری نے عثمان بن حکیم انصاری سے حدیث بیان کی ، انھوں نے کہا : مجھے سعید بن یسار نے بتایا کہ انھیں سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے خبردی کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی دو رکعتوں میں سے پہلی میں ( قرآن مجید سے آیت ) ( «قُولُوا آمَنَّا» بِاللَّـهِ «وَمَا أُنزِلَ إِلَيْنَا» ) ( والاحصہ ) پڑھتے جو سورہ بقرہ کی آیت ہے اور دوسری میں ( آل عمران کی آیت ) ( آمَنَّا بِاللہ «وَاشْهَدْ بِأَنَّا مُسْلِمُونَ» ) ( والا حصہ ) پڑھتے ۔","",{"u2":"مروان بن معاویہ فزاری نے عثمان بن حکیم انصاری سے حدیث بیان کی،انھوں نے کہا:مجھے سعید بن یسار نے بتایا کہ انھیں حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے خبردی کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی دو رکعتوں میں سے پہلی میں (قرآن مجید سے آیت) (قُولُوا آمَنَّا بِاللَّـہِ وَمَا أُنزِلَ إِلَیْنَا) (والاحصہ) پڑھتے جو سورہ بقرہ کی آیت ہے اور دوسری میں (آل عمران کی آیت)(آمَنَّا بِاللہ وَاشْہَدْ بِأَنَّا مُسْلِمُونَ)(والا حصہ) پڑھتے۔"}],[1630,"ابو خالد احمر نے عثمان بن حکیم سے ، انھوں نے سعید بن یسار سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم فجر کی دو رکعتوں میں ( قرآن مجید میں سے ) ( «قُولُوا آمَنَّا» بِاللَّـهِ «وَمَا أُنزِلَ إِلَيْنَا» ) ( والا حصہ ) اور جو سورہ آل عمران میں ہے ( «تَعَالَوْا إِلَىٰ كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ» ) ( والاحصہ ) پڑھا کرتے تھے ۔","",{"u2":"ابو خالد احمر نے عثمان بن حکیم سے، انھوں نے سعید بن یسار سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم فجر کی دو رکعتوں میں (قرآن مجید میں سے)(قُولُوا آمَنَّا بِاللَّـہِ وَمَا أُنزِلَ إِلَیْنَا)(والا حصہ) اور جو سورہ آل عمران میں ہے(تَعَالَوْا إِلَیٰ کَلِمَۃٍ سَوَاءٍ بَیْنَنَا وَبَیْنَکُمْ) (والاحصہ) پڑھا کرتے تھے۔"}],[1631,"عیسی بن یونس نے عثمان بن حکیم سے اسی سندکے ساتھ مروان فزاری کی حدیث کی طرح حدیث بیان کی ۔","",{"u2":"عیسی بن یونس نے عثمان بن حکیم سے اسی سندکے ساتھ مروان فزاری کی حدیث کی طرح حدیث بیان کی۔"}],[1632,"ابو خالد سلیمان بن حیان نے داود بن ابی سند سے حدیث بیان کی ، انہوں نے نعمان بن سالم سے اور انھوں نے عمرہ بن اوس سے روایت کی ، انھوں نے کہا : مجھے عنبسہ بن ابی سفیان نے اپنے مرض الموت میں ایک ایسی حدیث سنائی جس سے انتہائی خوشی حاصل ہوتی ہے ، کہا : میں نے ام حبیبہ رضی اللہ تعالیٰ عنہا سے سنا وہ کہتی تھیں : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا \"\" جس نے ایک دن اور ایک رات میں بارہ رکعات ادا کیں اس کے لئے ان کے بدلے جنت میں ایک گھر بنا دیاجاتا ہے ۔ \"\" ام حبیبہ رضی اللہ تعالیٰ عنہا نے کہا : جب سے میں نے ان کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے سنا ، میں نے انھیں کبھی ترک نہیں کیا ۔ عنبسہ نے کہا : جب سے میں نے ان کے بارے میں سیدہ ام حبیبہ رضی اللہ تعالیٰ عنہا سے سنا ، میں نے انھیں کبھی ترک نہیں کیا ۔ عمرو بن اوس نے کہا : جب سے میں نے ان کے بارے میں عنبسہ سے سنا ، میں نے انھیں کبھی ترک نہیں کیا ۔ نعمان بن سالم نے کہا : جب سے میں نے عمرو بن اوس سے ان کے بارے میں سنا ، میں نے انھیں کبھی ترک نہیں کیا ۔","",{"u2":"ابو خالد سلیمان بن حیان نے داود بن ابی سند سے حدیث بیان کی،انہوں نے نعمان بن سالم سے اور انھوں نے عمرہ بن اوس سے روایت کی،انھوں نے کہا: مجھے عنبسہ بن ابی سفیان نے اپنے مرض الموت میں ایک ایسی حدیث سنائی جس سے انتہائی خوشی حاصل ہوتی ہے،کہا: میں نے ام حبیبہ رضی اللہ تعالیٰ عنہا سے سنا وہ کہتی تھیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا\"جس نے ایک دن اور ایک رات میں بارہ رکعات ادا کیں اس کے لئے ان کے بدلے جنت میں ایک گھر بنا دیاجاتا ہے۔\"\nام حبیبہ رضی اللہ تعالیٰ عنہا نے کہا: جب سے میں نے ان کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے سنا،میں نے انھیں کبھی ترک نہیں کیا۔\nعنبسہ نے کہا:جب سے میں نے ان کے بارے میں حضرت ام حبیبہ رضی اللہ تعالیٰ عنہا سے سنا،میں نے انھیں کبھی ترک نہیں کیا۔\nعمرو بن اوس نے کہا:جب سے میں نے ان کے بارے میں عنبسہ سے سنا،میں نے انھیں کبھی ترک نہیں کیا۔\nنعمان بن سالم نے کہا:جب سے میں نے عمرو بن اوس سے ان کے بارے میں سنا،میں نے انھیں کبھی ترک نہیں کیا۔"}],[1633,"بشر بن مفضل نے کہا : ہمیں داود نے نعمان بن سالم سے اسی سندکے ساتھ یہ حدیث بیان کی ، \" جس نے ایک دن میں بارہ رکعات نوافل پڑے اس کے لئے جنت میں گھر بنایا جائے گا ۔","",{"u2":"بشر بن مفضل نے کہا:ہمیں داود نے نعمان بن سالم سے اسی سندکے ساتھ یہ حدیث بیان کی،\"جس نے ایک دن میں بارہ رکعات نوافل پڑے اس کے لئے جنت میں گھر بنایا جائے گا۔\""}],[1634,"محمد بن جعفر نے کہا : ہمیں شعبہ نے نعمان بن سالم سے حدیث سنائی ، انھوں نے عمرو بن اوس سے انھوں نے عنبسہ بن ابی سفیان سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ ام حبیبہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے سنا آ پ صلی اللہ علیہ وسلم فرمارہے تھے : ”کوئی ایسا مسلمان بندہ نہیں جو ہر روز اللہ کے لئے فرائض کے علاوہ بارہ رکعات سنتیں ادا کرتا ہے مگر اللہ اس کے لئے جنت میں ایک گھر بنا دیتا ہے ۔ یا اس کے لئے جنت میں ایک گھر بنا دیاجاتا ہے ۔ ام حبیبہ رضی اللہ تعالیٰ عنہا نے کہا : میں اب تک انھیں مسلسل ادا کرتے آرہی ہوں ۔ عمرو نے کہا : میں اب تک ان کو ہمیشہ ادا کر تا آرہاہوں ۔ نعمان نے بھی اس کے مطابق کہا ۔","",{"u2":"محمد بن جعفر نے کہا:ہمیں شعبہ نے نعمان بن سالم سے حدیث سنائی،انھوں نے عمرو بن اوس سے انھوں نے عنبسہ بن ابی سفیان سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ ام حبیبہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے سنا آ پ صلی اللہ علیہ وسلم فرمارہے تھے:”کوئی ایسا مسلمان بندہ نہیں جو ہر روز اللہ کے لئے فرائض کے علاوہ بارہ رکعات سنتیں ادا کرتا ہے مگر اللہ اس کے لئے جنت میں ایک گھر بنا دیتا ہے۔یا اس کے لئے جنت میں ایک گھر بنا دیاجاتا ہے۔\nام حبیبہ رضی اللہ تعالیٰ عنہا نے کہا: میں اب تک انھیں مسلسل اداکرتے آرہی ہوں۔\nعمرو نے کہا:میں اب تک ان کو ہمیشہ ادا کر تا آرہاہوں۔نعمان نے بھی اس کے مطابق کہا۔"}],[1635,"بہز نے شعبہ سے باقی ماندہ سابقہ سندکے ساتھ سیدہ ام حبیبہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس بھی مسلمان بندے نے اہتمام کے ساتھ مکمل وضو کیا ، پھر اللہ کی رضا کی خاطر ہر روز ( نفل ) نماز پڑھی ۔ ۔ ۔ \" اور اسی کے مطابق روایت کی ۔","",{"u2":"بہز نے شعبہ سے باقی ماندہ سابقہ سندکے ساتھ حضرت ام حبیبہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جس بھی مسلمان بندے نے اہتمام کے ساتھ مکمل وضو کیا،پھر اللہ کی رضا کی خاطر ہر روز(نفل)نماز پڑھی۔۔۔\"اور اسی کے مطابق روایت کی۔"}],[1636,"سیدنا ابن عمر سے رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ظہر سے پہےلے دورکعتیں پڑھیں اور اس کے بعد دو رکعتیں اور مغرب کے بعد دورکعتیں اور عشاء کے بعد دورکعتیں اور جمعے کے بعد دو رکعتیں ادا کیں ۔ جہاں تک مغرب ، عشاء اور جمعے ( کی سنتوں ) کا تعلق ہے ، وہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ آپ کے گھر میں پڑھیں ۔"],[1637,"سیدنا ابن عمر سے رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ظہر سے پہےلے دورکعتیں پڑھیں اور اس کے بعد دو رکعتیں اور مغرب کے بعد دورکعتیں اور عشاء کے بعد دورکعتیں اور جمعے کے بعد دو رکعتیں ادا کیں ۔ جہاں تک مغرب ، عشاء اور جمعے ( کی سنتوں ) کا تعلق ہے ، وہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ آپ کے گھر میں پڑھیں ۔",""],[1638,"خالد نے عبداللہ بن شقیق سے روایت کی ، انھوں نے کہا ، میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی نفل نماز کے بارے میں سوال کیا؟تو انھوں نے جوابدیا : آپ میرے گھر میں ظہر سے پہلے چار رکعت پڑھتے ، پھر ( گھر سے ) نکلتے اور لوگوں کو نماز پڑھاتے ، پھر گھر واپس آتے اور دو رکعتیں ادا فرماتے ۔ اور آپ لوگوں کو مغرب کی نماز پڑھاتے پھر گھر آتے اور دو رکعت نماز پڑھتے ، اور لوگوں کو عشاء کی نماز پڑھاتے اور میرے گھر آتے اور دو رکعتیں پڑھتے ، ان میں وتر شامل ہوتے ، اور طویل رات کھڑے ہوکر اور طویل ر ات بیٹھ کر نماز ادا کرتے اور جب کھڑے ہوکر قراءت کرتے تو رکوع اور سجدہ بھی کھڑے ہوکر کرتے اور جب بیٹھ کر قراءت کرتے تو رکوع اور سجدہ بھی بیٹھ کر کرتے اور جب فجر طلوع ہوتی تو دو رکعتیں پڑھتے ۔",""],[1639,"شعبہ نے بدیل سے حدیث سنائی انھوں نے عبداللہ بن شقیق سے روایت کی ، انھوں نے کہا : میں فارس ( ایران ) میں بیمار تھا ، اس لئے بیٹھ کر نماز پڑھتا تھا ۔ میں نے اس کے بارے میں سیدہ عائشہ رضی اللہ تعالیٰ عنہا رضی اللہ تعالیٰ عنہ سے پوچھا تو انھوں نے جواب دیا : رسول اللہ صلی اللہ علیہ وسلم رات کو لمبا وقت کھڑے ہوکر نماز پڑھتے تھے ۔ ۔ ۔ اس کے بعد ( اسی طرح ) حدیث بیان کی ۔","",{"u2":"شعبہ نے بدیل سے حدیث سنائی انھوں نے عبداللہ بن شقیق سے روایت کی،انھوں نے کہا:میں فارس(ایران) میں بیمار تھا،اس لئے بیٹھ کر نماز پڑھتا تھا۔میں نے اس کے بارے میں حضرت عائشہ رضی اللہ تعالیٰ عنہا رضی اللہ تعالیٰ عنہ سے پوچھا تو انھوں نے جواب دیا:رسول اللہ صلی اللہ علیہ وسلم رات کو لمباوقت کھڑے ہوکر نماز پڑھتے تھے۔۔۔اس کے بعد(اسی طرح) حدیث بیان کی۔"}],[1640,"حمید نے عبداللہ بن شقیق سے روایت کی ، انھوں نے کہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز کے بارے میں سوا ل کیا تو ا نھوں نے جواب دیا : آپ رات کو لمبا وقت کھڑے ہوکر نماز پڑھتے اور رات کو لمبا وقت بیٹھ کر نماز پڑھتے اور جب آپ کھڑے ہوکر قراءت کرتے تو کھڑے کھڑے رکوع کرتے اور جب بیٹھ کر قراءت کرتے تو بیٹھے بیٹھے رکوع کرتے ۔","",{"u2":"حمید نے عبداللہ بن شقیق سے روایت کی،انھوں نے کہا: میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز کے بارے میں سوا ل کیاتو ا نھوں نے جواب دیا:آپ رات کو لمبا وقت کھڑے ہوکر نماز پڑھتے اور رات کو لمبا وقت بیٹھ کر نماز پڑھتے اور جب آپ کھڑے ہوکر قراءت کرتے تو کھڑے کھڑے رکوع کرتے اور جب بیٹھ کر قراءت کرتے تو بیٹھے بیٹھے رکوع کرتے۔"}],[1641,"محمد بن سیرین نے عبداللہ بن شقیق عقیلی سے روایت کی ، انھوں نے کہا : ہم لوگوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا س رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھا تو انھوں نے کہا آپ کثرت سے کھڑ ے ہوکراور بیٹھ کر نماز پڑھتے تھے ۔ جب آپ کھڑے ہوکر نماز کا آغازفرماتے تو کھڑے کھڑے رکوع کرتے اور جب آپ بیٹھے ہوئے نماز کا آغاز کرتے تو بیٹھے ہوئے رکوع کرتے ۔","",{"u2":"محمد بن سیرین نے عبداللہ بن شقیق عقیلی سے روایت کی،انھوں نے کہا:ہم لوگوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا س رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھا تو انھوں نے کہا آپ کثرت سے کھڑ ے ہوکراور بیٹھ کر نماز پڑھتے تھے۔جب آپ کھڑے ہوکر نماز کا آغازفرماتے تو کھڑے کھڑے رکوع کرتے اور جب آپ بیٹھے ہوئے نماز کا آغاز کرتے تو بیٹھے ہوئے رکوع کرتے۔"}],[1642,"ہشام بن عروہ سے روایت ہے ، کہا : مجھے میرے والد نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے خبر دی ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو نہیں دیکھا تھا کہ آپ نے رات کی نماز کے کسی حصے میں بیٹھ کر قراءت کی ہو یہاں تک کہ جب آپ کی عمر زیادہ ہوگئی تو آپ بیٹھ کر قراءت کرتے اور جب سورت کی تیس یا چالیس آیتیں ر ہ جاتیں تو کھڑے ہوکر انھیں پڑھتے پھر رکوع کرتے ۔","",{"u2":"ہشام بن عروہ سے روایت ہے،کہا:مجھے میرے والد نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے خبر دی،انھوں نے کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو نہیں دیکھا تھا کہ آپ نے رات کی نماز کے کسی حصے میں بیٹھ کر قراءت کی ہو یہاں تک کہ جب آپ کی عمر زیادہ ہوگئی تو آپ بیٹھ کر قراءت کرتے اور جب سورت کی تیس یا چالیس آیتیں ر ہ جاتیں تو کھڑے ہوکر انھیں پڑھتے پھر رکوع کرتے۔"}],[1643,"ابو سلمہ بن عبدالرحمان نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر ( بھی ) نماز پڑھتے تھے ، آپ بیٹھے ہوئے قراءت فرماتے جب آپ کی قراءت سے اتنا حصہ بچ جاتا جتنی تیس یا چالیس آیتیں ہوتی ہیں تو آپ کھڑ ے ہوجاتے اور کھڑے ہوئے ان کی قراءت فرماتے پھر رکوع کرتے پھر سجدہ کرتے ، پھر دوسری رکعت میں ایسا ہی کرتے ۔","",{"u2":"ابو سلمہ بن عبدالرحمان نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر(بھی) نماز پڑھتے تھے،آپ بیٹھے ہوئے قراءت فرماتے جب آپ کی قراءت سے اتنا حصہ بچ جاتا جتنی تیس یا چالیس آیتیں ہوتی ہیں تو آپ کھڑ ے ہوجاتے اور کھڑے ہوئے ان کی قراءت فرماتے پھر رکوع کرتے پھر سجدہ کرتے،پھر دوسری رکعت میں ایسا ہی کرتے۔"}],[1644,"عمرہ نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم بیٹھے ہوئے قراءت فرماتے ، پس جب رکوع کرنا چاہتے تو اتنی دیر کے لئے کھڑے ہوجاتے جتنی دیر میں ایک انسان چالیس آیتیں پڑھ لیتا ہے ۔","",{"u2":"عمرہ نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم بیٹھے ہوئے قراءت فرماتے،پس جب رکوع کرناچاہتے تو اتنی دیر کے لئے کھڑے ہوجاتے جتنی دیر میں ایک انسان چالیس آیتیں پڑھ لیتا ہے۔"}],[1645,"علقمہ بن وقاص سے روایت ہے ، انھوں نے کہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا : جب رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر دو رکعتیں پڑھتے تو کیا کرتے تھے؟انھوں نے جواب دیا : آپ ان میں قراءت کرتے رہتے ، جب رکوع کرنے کا ارادہ کرتے تو کھڑے ہوجاتے پھر ر کوع کرتے ۔","",{"u2":"علقمہ بن وقاص سے روایت ہے،انھوں نے کہا:میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا:جب رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر دو رکعتیں پڑھتے تو کیا کرتے تھے؟انھوں نے جواب دیا:آپ ان میں قراءت کرتے رہتے،جب رکوع کرنے کا ارادہ کرتے تو کھڑے ہوجاتے پھر ر کوع کرتے۔"}],[1646,"سعید بن جریری نے عبداللہ بن شقیق سے روایت کی ، انھوں نے کہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے کہا : کیا رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر نماز پڑھ لیتے تھے؟انہوں نے کہا : ہاں ، جب لوگوں ( کے معاملات کی دیکھ بھال اور فکر مندی ) نے آپ کو بوڑھا کردیا ۔","",{"u2":"سعید بن جریری نے عبداللہ بن شقیق سے روایت کی،انھوں نے کہا:میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے کہا:کیا رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر نماز پڑھ لیتے تھے؟انہوں نے کہا:ہاں، جب لوگوں(کے معاملات کی دیکھ بھال اورفکر مندی) نے آپ کو بوڑھا کردیا۔"}],[1647,"کہمس نے عبداللہ بن شقیق سے روایت کی ، انھوں نے کہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے کہا ۔ ۔ ۔ پھر نبی کریم صلی اللہ علیہ وسلم سے اسی طرح روایت بیان کی ۔","",{"u2":"کہمس نے عبداللہ بن شقیق سے روایت کی،انھوں نے کہا:میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے کہا۔۔۔پھر نبی کریم صلی اللہ علیہ وسلم سے اسی طرح روایت بیان کی۔"}],[1648,"ابو سلمہ بن عبدالرحمان نے خبر دی کہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم کا انتقال نہیں ہوا یہاں تک کہ آپ کی نماز کا بہت سا حصہ بیٹھے ہوئے ہوتا تھا ۔","",{"u2":"ابو سلمہ بن عبدالرحمان نے خبر دی کہ حضرت عائشہ رضی اللہ تعالیٰ عنہا نے انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم کا انتقال نہیں ہوا یہاں تک کہ آپ کی نماز کا بہت سا حصہ بیٹھے ہوئے ہوتا تھا۔"}],[1649,"عبداللہ بن عروہ کے والد عروہ بن زبیر نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا : جب رسول اللہ صلی اللہ علیہ وسلم کا بدن زرا بڑھ گیا اور آپ بھاری ہوگئے تو آپ کی نماز کا زیادہ تر حصہ بیٹھے ہوئے ( ادا ) ہوتا تھا ۔","",{"u2":"عبداللہ بن عروہ کے والد عروہ بن زبیر نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا:جب رسول اللہ صلی اللہ علیہ وسلم کا بدن زرا بڑھ گیا اور آپ بھاری ہوگئے تو آپ کی نماز کا زیادہ تر حصہ بیٹھے ہوئے (ادا) ہوتا تھا۔"}],[1650,"۔ امام مالک نے ابن شہاب سے ، انھوں نے سائب بن یزید سے ، انھوں نے مطلب بن ابی وداعہ سہمی سے اور انھوں نے سیدہ حفصہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو نفل نماز بیٹھ کر کبھی نہ پڑھتے دیکھاتھا حتیٰ کہ آپ صلی اللہ علیہ وسلم کی وفات سے ایک سال پہلے کا زمانہ ہوا تو آپ نفل نماز بیٹھ کر پڑھنے لگے ۔ آپ سورت کی قراءت کرتے تو اسے ٹھہر ٹھہر کر پڑھتے حتیٰ کہ وہ طویل ترین سورت سے بھی لمبی ہوجاتی ۔ ( یعنی بیٹھ کر لیکن اور بھی زیادہ لمبی نماز پڑھتے)","",{"u2":"۔ امام مالک نے ابن شہاب سے،انھوں نے سائب بن یزید سے،انھوں نے مطلب بن ابی وداعہ سہمی سے اور انھوں نے حضرت حفصہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو نفل نماز بیٹھ کر کبھی نہ پڑھتے دیکھاتھا حتیٰ کہ آپ صلی اللہ علیہ وسلم کی وفات سے ایک سال پہلے کا زمانہ ہوا تو آپ نفل نماز بیٹھ کر پڑھنےلگے۔آپ سورت کی قراءت کرتے تو اسے ٹھہر ٹھہر کر پڑھتے حتیٰ کہ وہ طویل ترین سورت سے بھی لمبی ہوجاتی۔(یعنی بیٹھ کر لیکن اور بھی زیادہ لمبی نماز پڑھتے)-"}],[1651,"یونس اور معمر دونوں نے زہری سے اسی سند کے ساتھ اس کے مانند روایت کی ، البتہ ان دونوں ( یونس اور معمر ) نے ایک یا دو سال کہا ۔","",{"u2":"یونس اور معمر دونوں نے زہری سے اسی سند کے ساتھ اس کے مانند روایت کی،البتہ ان دونوں(یونس اور معمر) نے ایک یا دو سال کہا۔"}],[1652,"سیدنا جابربن سمرہ رضی اللہ تعالیٰ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کی وفات نہ ہوئی یہاں تک کہ آپ ( رات کو ) بیٹھ کر نماز پڑھنے لگے ۔","",{"u2":"حضرت جابربن سمرہ رضی اللہ تعالیٰ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کی وفات نہ ہوئی یہاں تک کہ آپ(رات کو) بیٹھ کر نماز پڑھنے لگے۔"}],[1653,"جریر نے مجھے حدیث سنائی ، انھوں نے منصور سے ، انھوں نے ہلال بن یساف سے ، انھوں نے ابو یحییٰ سے اور انھوں نے سیدنا عبداللہ بن عمرو ( بن حوص ) رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : مجھے بتایا گیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بیٹھ کر آدمی کی نماز ( اجر میں ) آدھی نماز ہے ۔ \" انھوں نے کہا : ایک بار میں آپ کے پاس آیا اور میں نے آپ کو بیٹھ کر نماز پڑھتے ہوئے پایا تو میں نے اپنا ہاتھ آپ کے سر مبارک پر لگایا ۔ آپ نے ہو چھا : \" اے عبداللہ بن عمرو رضی اللہ تعالیٰ عنہ تمھیں کیا ہوا؟ میں نے عرض کی ، اے اللہ کے رسول صلی اللہ علیہ وسلم مجھے بتایا گیا کہ آپ نے فرمایا ہے \" بیٹھ کر آدمی کی نماز آدھی نماز کے برابر ہے ۔ \" جب کہ آپ بیٹھ کر نماز پڑھ رہے ہیں ۔ آپ نے فرمایا : \" ہاں ایسا ہی ہے لیکن میں تم میں سے کسی ایک طرح کا نہیں ہوں ۔","",{"u2":"جریر نے مجھے حدیث سنائی،انھوں نے منصور سے،انھوں نے ہلال بن یساف سے،انھوں نے ابو یحییٰ سے اور انھوں نے حضرت عبداللہ بن عمرو(بن حوص) رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:مجھے بتایا گیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"بیٹھ کر آدمی کی نماز(اجر میں) آدھی نماز ہے۔\"انھوں نے کہا:ایک بار میں آپ کے پاس آیا اور میں نے آپ کو بیٹھ کر نماز پڑھتے ہوئے پایا تو میں نے اپنا ہاتھ آپ کے سر مبارک پر لگایا۔آپ نے ہوچھا:\"اے عبداللہ بن عمرو رضی اللہ تعالیٰ عنہ تمھیں کیا ہوا؟ میں نے عرض کی،اے اللہ کے رسول صلی اللہ علیہ وسلم مجھے بتایا گیا کہ آپ نے فرمایا ہے\"بیٹھ کر آدمی کی نماز آدھی نماز کے برابر ہے۔\"جب کہ آپ بیٹھ کر نماز پڑھ رہے ہیں۔آپ نے فرمایا:\"ہاں ایسا ہی ہے لیکن میں تم میں سے کسی ایک طرح کا نہیں ہوں۔\""}],[1654,"شعبہ اور سفیان دونوں نے منصور سے اسی سابقہ سند کے ساتھ حدیث بیان کی ، البتہ شعبہ کی روایت میں ہے : \" ابو یحییٰ الاعرج سے روایت ہے \" ( انھوں نے ابو یحییٰ کے ساتھ ان کے لقب الاعرج کا بھی ذکر کیا ہے)","",{"u2":"شعبہ اور سفیان دونوں نے منصور سے اسی سابقہ سند کے ساتھ حدیث بیان کی،البتہ شعبہ کی روایت میں ہے:\"ابو یحییٰ الاعرج سے روایت ہے\"(انھوں نے ابو یحییٰ کے ساتھ ان کے لقب الاعرج کا بھی ذکر کیا ہے)-"}],[1655,"مالک نے ابن شہاب سے ، انھوں نے عروہ سے ، اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم رات کو گیارہ رکعت پڑھتے تھے ، ان میں سے ایک کے ذریعے وتر ادا فرماتے ، جب آپ اس ( ایک رکعت ) سے فارغ ہوجاتے تو آپ اپنے دائیں پہلو کے بل لیٹ جاتے یہاں تک کہ آپ کے پاس موذن آجاتا تو آپ دو ( نسبتاً ) ہلکی رکعتیں پڑھتے ۔","",{"u2":"مالک نے ابن شہاب سے،انھوں نے عروہ سے،اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم رات کوگیارہ رکعت پڑھتے تھے،ان میں سے ایک کے ذریعے وتر ادا فرماتے،جب آپ اس(ایک رکعت) سے فارغ ہوجاتے تو آپ اپنے دائیں پہلو کے بل لیٹ جاتے یہاں تک کہ آپ کے پاس موذن آجاتا تو آپ دو (نسبتاً) ہلکی رکعتیں پڑھتے۔"}],[1656,"عمرو بن حارث نے ابن شہاب سے اسی سند کے ساتھ نبی اکر م صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا رسول اللہ صلی اللہ علیہ وسلم عشاء کی نماز سے جس کو لوگ عتمہ کہتے ہیں فراغت کے بعد سے فجر تک گیارہ رکعت پڑھتے تھے ۔ ہر دو رکعت پر سلام پھیرتے اور وتر ایک رکعت پڑھتے ۔ جب موذن صبح کی نماز کی اذان کہہ کر خاموش ہوجاتا آپ کے سامنے صبح واضح ہوجاتی ۔ اور موذن آپ کے پاس آجاتا تو آپ اٹھ کر دو ہلکی رکعتیں پڑھتے پھر اپنے داہنے پہلو کے بل لیٹ جاتے حتیٰ کہ موذن آپ کے پاس اقامت ( کی اطلاع دینے ) کے لئے آجاتا ۔","",{"u2":"عمرو بن حارث نے ابن شہاب سے اسی سند کے ساتھ نبی اکر م صلی اللہ علیہ وسلم کی زوجہ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا رسول اللہ صلی اللہ علیہ وسلم عشاء کی نماز سے جس کو لوگ عتمہ کہتے ہیں فراغت کے بعد سے فجر تک گیارہ رکعت پڑھتے تھے۔ہر دو رکعت پر سلام پھیرتے اور وتر ایک رکعت پڑھتے۔جب موذن صبح کی نماز کی اذان کہہ کر خاموش ہوجاتا آپ کے سامنے صبح واضح ہوجاتی۔اور موذن آپ کے پاس آجاتا تو آپ اٹھ کر دو ہلکی رکعتیں پڑھتےپھر اپنے داہنے پہلو کے بل لیٹ جاتے حتیٰ کہ موذن آپ کے پاس اقامت(کی اطلاع دینے) کے لئے آجاتا۔"}],[1657,"عمرو بن حارث نے ابن شہاب سے اسی سند کے ساتھ نبی اکر م صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا رسول اللہ صلی اللہ علیہ وسلم عشاء کی نماز سے جس کو لوگ عتمہ کہتے ہیں فراغت کے بعد سے فجر تک گیارہ رکعت پڑھتے تھے ۔ ہر دو رکعت پر سلام پھیرتے اور وتر ایک رکعت پڑھتے ۔ جب موذن صبح کی نماز کی اذان کہہ کر خاموش ہوجاتا آپ کے سامنے صبح واضح ہوجاتی ۔ اور موذن آپ کے پاس آجاتا تو آپ اٹھ کر دو ہلکی رکعتیں پڑھتے پھر اپنے داہنے پہلو کے بل لیٹ جاتے حتیٰ کہ موذن آپ کے پاس اقامت ( کی اطلاع دینے ) کے لئے آجاتا ۔","",{"u2":"حرملہ نے مجھے یہ حدیث بیان کی(کہا)ہمیں ابن وہب نے خبر دی،انھوں نے کہا،مجھے یونس نے ابن شہاب سے اسی سند کے ساتھ خبر دی۔ اگر حرملہ نے سابقہ حدیث کی مانند حدیث بیان کی البتہ اس میں\" آپ صلی اللہ علیہ وسلم کے سامنے صبح کے روشن ہوجانے اور موذن آپ کے پاس آتا\"کے الفاظ ذکر نہیں کیے اور \"اقامت\" کا ذکر کیا۔باقی حدیث بالکل عمرو کی حدیث کی طر ح ہے۔"}],[1658,"عبداللہ بن نمیر نے ہمیں حدیث بیان کی اور کہا : ہمیں اپنے ہشام نے اپنے والد ( عروہ ) سے حدیث سنائی اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم رات کو تیرہ رکعتیں پڑھتے تھے ، ان میں سے پانچ رکعتوں کے ذریعے وتر ( ادا ) کرتے تھے ، ان میں آخری رکعت کے علاوہ کسی میں بھی تشہد کے لئے نہ بیٹھتے تھے ۔ ( بعض راتوں میں آپ صلی اللہ علیہ وسلم کا یہ معمول ہوتا)","",{"u2":"عبداللہ بن نمیر نے ہمیں حدیث بیان کی اور کہا:ہمیں اپنے ہشام نے اپنے والد(عروہ) سے حدیث سنائی اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم رات کو تیرہ رکعتیں پڑھتے تھے،ان میں سے پانچ رکعتوں کے ذریعے وتر (ادا) کرتے تھے،ان میں آخری رکعت کے علاوہ کسی میں بھی تشہد کے لئے نہ بیٹھتے تھے۔(بعض راتوں میں آپ صلی اللہ علیہ وسلم کا یہ معمول ہوتا)"}],[1659,"عبدہ بن سلیمان ، وکیع اور ابو اسامہ سب نے ہشام سے اسی سند کے ساتھ ( یہ ) روایت بیان کی ہے ۔","",{"u2":"عبدہ بن سلیمان،وکیع اور ابو اسامہ سب نے ہشام سے اسی سند کے ساتھ (یہ) روایت بیان کی ہے۔"}],[1660,"عروہ بن مالک نے عروہ سے روایت کی کہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی دو رکعتوں سمیت تیرہ ر کعتیں پڑھا کرتے تھے ۔","",{"u2":"عروہ بن مالک نے عروہ سے روایت کی کہ حضرت عائشہ رضی اللہ تعالیٰ عنہا نے انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی دو رکعتوں سمیت تیرہ ر کعتیں پڑھا کرتے تھے۔"}],[1661,"سعید بن ابی سعید مقبری نے ابو سلمہ بن عبدالرحمان سے روایت کی کہ انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا : رمضان میں رسول اللہ صلی اللہ علیہ وسلم کی نماز کیسے ہوتی تھی؟انھوں نے جواب دیا : رسول اللہ صلی اللہ علیہ وسلم رمضان اور اس کے علاوہ ( دوسرے مہینوں ) میں ( فجر سے پہلے ) گیارہ رکعتوں سے زائد نہیں پڑھتے تھے ، چار رکعتیں پڑھتے ، ان کی خوبصورتی اور ان کی طوالت کے بارے میں مت پوچھو ، پھر چار رکعتیں پڑھتے ، ان کے حسن اور طوالت کے بارے میں نہ پوچھو ، پھر تین رکعتیں پڑھتے ۔ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا میں نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم !کیا آپ وتر پڑھنے سے پہلے سوجاتے ہیں؟تو آپ نے فرمایا : اے عائشہ!میری آنکھیں سوتی ہیں اور میرا دل نہیں سوتا ۔ \" ( وہ بدستور اللہ کے ذکر میں مشغول ر ہتا ہے)","",{"u2":"سعید بن ابی سعید مقبری نے ابو سلمہ بن عبدالرحمان سے روایت کی کہ انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا:رمضان میں رسول اللہ صلی اللہ علیہ وسلم کی نماز کیسے ہوتی تھی؟انھوں نے جواب دیا:رسول اللہ صلی اللہ علیہ وسلم رمضان اور اس کے علاوہ(دوسرے مہینوں) میں (فجر سے پہلے) گیارہ رکعتوں سے زائد نہیں پڑھتے تھے،چار رکعتیں پڑھتے،ان کی خوبصورتی اور ان کی طوالت کے بارے میں مت پوچھو،پھر چار رکعتیں پڑھتے،ان کے حسن اور طوالت کے بارے میں نہ پوچھو،پھرتین رکعتیں پڑھتے۔حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا میں نے عرض کی:اے اللہ کے رسول صلی اللہ علیہ وسلم!کیا آپ وتر پڑھنے سے پہلے سوجاتے ہیں؟تو آپ نے فرمایا:اے عائشہ!میری آنکھیں سوتی ہیں اور میرا دل نہیں سوتا۔\"(وہ بدستور اللہ کے ذکر میں مشغول ر ہتا ہے)-"}],[1662,"ہشام نے یحییٰ سے اور انھوں نے ابو سلمہ سے ر وایت کی ، انھوں نے کہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے بارے میں سوا ل کیا تو انھوں نے کہا آپ تیرہ رکعتیں پڑھتے تھے ، آٹھ رکعتیں پڑھتے پھر ( ایک رکعت سے ) وتر ادا فرماتے ، پھر بیٹھے ہوئے دو رکعتیں پڑھتے ، پھر جب رکوع کرنا چاہتے تو اٹھ کھڑے ہوتے اور رکوع کرتے ، پھر صبح کی نماز کی اذان اور اقامت کے درمیان دو رکعتیں پڑھتے ۔ ( کبھی آپ صلی اللہ علیہ وسلم کی تہجد اور وتر کی ترتیب یہ بن جاتی تھی)","",{"u2":"ہشام نے یحییٰ سے اور انھوں نے ابو سلمہ سے ر وایت کی،انھوں نے کہا:میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے بارے میں سوا ل کیا تو انھوں نے کہا آپ تیرہ رکعتیں پڑھتے تھے،آٹھ رکعتیں پڑھتے پھر(ایک رکعت سے) وتر ادا فرماتے،پھر بیٹھے ہوئے دو رکعتیں پڑھتے،پھر جب رکوع کرنا چاہتے تو اٹھ کھڑے ہوتے اور رکوع کرتے،پھر صبح کی نماز کی اذان اور اقامت کے درمیا دو رکعتیں پڑھتے۔(کبھی آپ صلی اللہ علیہ وسلم کی تہجد اور وتر کی ترتیب یہ بن جاتی تھی)-"}],[1663,"شیبان اور معاویہ بن سلام نے یحییٰ بن ابی کثیر سے روایت کی ، انھوں نے کہا : مجھے ابو سلمہ نے بتایا کہ انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھا ۔ ۔ ۔ آگے سابقہ حدیث کی طرح ہے ، البتہ ان دونوں کی روایت میں ہے : \" آپ صلی اللہ علیہ وسلم کھڑے ہوکر نو رکعتیں پڑھتے تھے وتر انھی میں ادا کرتے ۔","",{"u2":"شیبان اور معاویہ بن سلام نے یحییٰ بن ابی کثیر سے روایت کی،انھوں نے کہا:مجھے ابو سلمہ نے بتایا کہ انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی نمازکے بارے میں پوچھا۔۔۔آگے سابقہ حدیث کی طرح ہے،البتہ ان دونوں کی روایت میں ہے:\"آپ صلی اللہ علیہ وسلم کھڑے ہوکر نو رکعتیں پڑھتے تھے وتر انھی میں ادا کرتے۔\""}],[1664,"عبداللہ بن ابی لبید سے روایت ہے کہ انھوں نے ابو سلمہ سے سنا ، انھوں نے کہا : میں سیدہ عائشہ رضی اللہ تعالیٰ عنہا کی خدمت میں حاضر ہوا اور کہا : اے میری ماں!مجھے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں بتایئے ۔ تو انھوں نے کہا : رمضان اور غیر رمضان میں رات کے وقت آپ کی نماز تیرہ رکعتیں تھی ، ان میں فجر کی ( سنت ) دو کعتیں بھی شامل تھیں ۔","",{"u2":"عبداللہ بن ابی لبید سے روایت ہے کہ انھوں نے ابو سلمہ سے سنا،انھوں نے کہا:میں حضرت عائشہ رضی اللہ تعالیٰ عنہا کی خدمت میں حاضر ہوا اور کہا: اے میری ماں!مجھے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں بتایئے۔تو انھوں نے کہا:رمضان اور غیر رمضان میں رات کے وقت آپ کی نماز تیرہ رکعتیں تھی،ان میں فجر کی(سنت) دو کعتیں بھی شامل تھیں۔"}],[1665,"قاسم بن محمد سے روایت ہے ، انھوں نے کہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے سنا ، فرما رہی تھی : رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز دس رکعتیں تھی اور آپ ایک رکعت وتر ادا کرتے ، پھر فجر کی ( سنتیں ) دو رکعت پڑھتے ۔ اس طرح یہ تیرہ رکعتیں ہوئیں ۔","",{"u2":"قاسم بن محمد سے روایت ہے،انھوں نے کہا:میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے سنا،فرمارہی تھی:رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز دس رکعتیں تھی اور آپ ایک رکعت وتر ادا کرتے،پھر فجر کی (سنتیں) دو رکعت پڑھتے۔اس طرح یہ تیرہ رکعتیں ہوئیں۔"}],[1666,"ابو خثیمہ ( زہیر بن معاویہ ) نے ابو اسحاق سے خبر دی ، کہا : میں نے اسود بن یزید سے اس حدیث کے بارے میں پوچھا جو ان سے سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں بیان کی تھی ۔ انھوں ( عائشہ رضی اللہ تعالیٰ عنہا ) نے کہا : رسول اللہ صلی اللہ علیہ وسلم رات کے پہلے حصے میں سوجاتے اور آخری حصے کو زندہ کرتے ( اللہ کے سامنے قیام فرماتے ہوئے جاگتے ) پھر اگر اپنے گھر والوں سے کوئی ضرورت ہوتی تو اپنی ضرورت پوری کرتے اور سوجاتے ، پھر جب پہلی اذان کا وقت ہوتا تو عائشہ رضی اللہ تعالیٰ عنہا نے کہا : آپ اچھل کر کھڑے ہوجاتے ( راوی نے کہا : ) اللہ کی قسم!عائشہ رضی اللہ تعالیٰ عنہا نے وثب کہا ، قام ( کھڑے ہوتے ) نہیں کہا ۔ پھر اپنے اوپر پانی بہاتے ، اللہ کی قسم! انھوں نے اغتسل ( نہاتے ) نہیں کہا : \" اپنے اوپر پانی بہاتے \" میں جانتا ہوں ان کی مراد کیا تھی ۔ ( یعنی زیادہ مقدار میں پانی بہاتے ) اور اگر آپ جنبی نہ ہوتے تو جس طرح آدمی نماز کے لئے وضو کرتا ہے ، اسی طرح وضو فرماتے ، پھر دو رکعتیں ( سنت فجر ) ادا فرماتے ۔","",{"u2":"ابو خثیمہ(زہیر بن معاویہ) نے ابو اسحاق سے خبر دی،کہا: میں نے اسود بن یزید سے اس حدیث کے بارے میں پوچھا جو ان سے حضرت عائشہ رضی اللہ تعالیٰ عنہا نے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں بیان کی تھی۔انھوں(عائشہ رضی اللہ تعالیٰ عنہا) نے کہا:رسول اللہ صلی اللہ علیہ وسلم رات کے پہلے حصے میں سوجاتے اور آخری حصے کو زندہ کرتے(اللہ کے سامنے قیام فرماتے ہوئے جاگتے)پھر اگر اپنے گھر والوں سےکوئی ضرورت ہوتی تو اپنی ضرورت پوری کرتے اور سوجاتے،پھر جب پہلی اذان کا وقت ہوتا تو عائشہ رضی اللہ تعالیٰ عنہا نے کہا:آپ اچھل کر کھڑے ہوجاتے(راوی نے کہا:) اللہ کی قسم!عائشہ رضی اللہ تعالیٰ عنہا نے وثب کہا،قام(کھڑے ہوتے) نہیں کہا۔پھر اپنے اوپر پانی بہاتے،اللہ کی قسم! انھوں نے اغتسل(نہاتے) نہیں کہا:\"اپنے اوپر پانی بہاتے\"میں جانتا ہوں ان کی مراد کیا تھی۔(یعنی زیادہ مقدار میں پانی بہاتے)اور اگر آپ جنبی نہ ہوتے تو جس طرح آدمی نماز کے لئے وضو کرتا ہے،اسی طرح وضو فرماتے،پھر دو رکعتیں (سنت فجر) ادا فرماتے۔"}],[1667,"عمار بن زریق نے ابو اسحاق سے ، انھوں نے اسود سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم ر ات کو نماز پڑھتے حتیٰ کہ ان کی نماز کا آخری حصہ وتر ہوتا ۔ ( اکثر آپ صلی اللہ علیہ وسلم کا معمول یہی تھا)","",{"u2":"عمار بن زریق نے ابو اسحاق سے،انھوں نے اسود سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم ر ات کو نماز پڑھتے حتیٰ کہ ان کی نماز کا آخری حصہ وتر ہوتا۔(اکثر آپ صلی اللہ علیہ وسلم کا معمول یہی تھا)-"}],[1668,"مسروق نے کہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے عمل کے بارے میں پوچھا تو انھوں نے کہا : آپ کو ہمیشہ کیا جانے والا عمل پسند تھا ۔ میں نے کہا : آپ کس و قت نماز پڑھتے تھے؟تو انہو ں نے کہا : جب آپ مرغ کی آواز سنتے تو کھڑے ہوجاتے اور نماز پڑھتے ۔","",{"u2":"مسروق نے کہا:میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے عمل کے بارے میں پوچھا تو انھوں نے کہا:آپ کو ہمیشہ کیا جانے والا عمل پسند تھا۔ میں نے کہا: آپ کس و قت نماز پڑھتے تھے؟تو انہو ں نے کہا:جب آپ مرغ کی آواز سنتے تو کھڑے ہوجاتے اور نماز پڑھتے۔"}],[1669,"ابو سلمہ نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے ر وایت کی ، انھوں نے کہا : سحر کے آخری حصے ( جب طلوع فجر سے بالکل پہلے سحر اپنی انتہا پر ہوتی ہے ) نے میرے گھر میں یا میرے پاس ، رسول اللہ صلی اللہ علیہ وسلم کو سوئے ہوئے ہی پایا ۔","",{"u2":"ابو سلمہ نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے ر وایت کی،انھوں نے کہا:سحر کے آخری حصے(جب طلوع فجر سے بالکل پہلے سحر اپنی انتہا پر ہوتی ہے) نے میرے گھر میں یا میرے پاس،رسول اللہ صلی اللہ علیہ وسلم کو سوئے ہوئے ہی پایا۔"}],[1670,"ابو نضر نے ابو سلمہ سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، کہا : نبی اکرم صلی اللہ علیہ وسلم جب فجر کی سنتیں پڑھ لیتے تو اگر میں جاگتی ہوتی میرے ساتھ گفتگو فرماتے ، ورنہ لیٹ جاتے ۔","",{"u2":"ابو نضر نے ابو سلمہ سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،کہا:نبی اکرم صلی اللہ علیہ وسلم جب فجر کی سنتیں پڑھ لیتے تو اگر میں جاگتی ہوتی میرے ساتھ گفتگو فرماتے،ورنہ لیٹ جاتے۔"}],[1671,"ابن ابی عتاب نے ابو سلمہ سے ، انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"ابن ابی عتاب نے ابو سلمہ سے،انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[1672,"عروہ بن زبیر نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم رات کو نماز پڑھتے رہتے ، جب وتر پڑھنے لگتے تو فرماتے : \" عائشہ ! اٹھو اور وتر پڑھ لو ۔","",{"u2":"عروہ بن زبیر نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم رات کو نماز پڑھتے رہتے،جب وتر پڑھنے لگتے تو فرماتے:\"عائشہ! اٹھو اور وتر پڑھ لو۔\""}],[1673,"قاسم بن محمد نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم رات کو اپنی نماز پڑھتے اور وہ ( عائشہ رضی اللہ تعالیٰ عنہا ) آپ کے سامنے لیٹی ہوتی تھیں ، جب آپ کے وتر باقی رہ جاتے تو آپ انھیں جگا دیتے اور وہ وتر پڑھ لیتیں ۔","",{"u2":"قاسم بن محمد نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم رات کو اپنی نماز پڑھتے اور وہ (عائشہ رضی اللہ تعالیٰ عنہا) آپ کے سامنے لیٹی ہوتی تھیں،جب آپ کے وتر باقی رہ جاتے تو آپ انھیں جگا دیتے اور وہ وتر پڑھ لیتیں۔"}],[1674,"مسلم ( بن صبیح ) نے مسروق سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے رات کے ہر حصے میں وتر ( یا رات ) کی نماز پڑھی ، ( لیکن عموماً ) آپ کے وتر سحری کے وقت تک پہنچتے تھے ۔","",{"u2":"مسلم(بن صبیح) نے مسروق سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے رات کے ہر حصے میں وتر(یارات) کی نماز پڑھی،(لیکن عموماً) آپ کے وتر سحری کے وقت تک پہنچتے تھے۔"}],[1675,"یحییٰ بن وثاب نے مسروق سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے رات کے ہر حصے میں وتر ( رات ) کی نماز پڑھی ، رات کے ابتدائی حصے میں بھی ، درمیان میں بھی اور آخر میں بھی ، آپ کے وتر ( کے اوقات ) سحری تک جاتے تھے ۔","",{"u2":"یحییٰ بن وثاب نے مسروق سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے رات کے ہر حصے میں وتر(رات) کی نماز پڑھی،رات کے ابتدائی حصے میں بھی،درمیان میں بھی اور آخر میں بھی،آپ کے وتر(کے اوقات) سحری تک جاتے تھے۔"}],[1676,"ابو ضحیٰ نے مسروق سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے رات کےہرحصے میں وتر پڑھے ہیں ، ( لیکن عموماً ) آپ کے وتر رات کے آخری حصے تک چلتے ۔","",{"u2":"ابو ضحیٰ نے مسروق سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے رات کےہرحصے میں وتر پڑھے ہیں،(لیکن عموماً) آپ کے وتر رات کے آخری حصے تک چلتے۔"}],[1677,"ابن ابی عدی نے سعید ( ابن ابی عروبہ ) سے ، انھوں نے قتادہ سے اور انھوں نے زرارہ سے روایت کی کہ ( سیدنا انس رضی اللہ تعالیٰ عنہ کے قریبی عزیز ) سعد بن ہشام بن عامر نے ارادہ کیا کہ اللہ تعالیٰ کی راہ میں جنگ ( جہاد ) کریں ، وہ مدینہ منورہ آگئے اور وہاں ا پنی ایک جائیداد فروخت کرنی چاہی تاکہ اس سے ہتھیار اور گھوڑے مہیا کریں اور موت آنے تک رومیوں کے خلاف جہاد کریں ، چنانچہ جب مدینہ آئے تو اہل مدینہ میں سے کچھ لوگوں سے ملے ، انھوں نے اس کو اس ارادے سے روکا اور ان کو بتایا کہ چھ افراد کے ایک گروہ نے نبی اکرم صلی اللہ علیہ وسلم کی حیات مبارکہ میں ایسا کرنے کاارادہ کیا تھا تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں روک دیا تھا ۔ آپ نے فرمایا تھا : \"\" کیا میرے طرز عمل میں تمھارے لئے نمونہ نہیں ہیں؟ \"\" چنانچہ جب ان لوگوں نے انھیں یہ بات بتائی تو انھوں نے اپنی بیوی سے رجوع کرلیا جبکہ وہ اسے طلاق دے چکے تھے ، اور اس سے رجو ع کے لئے گواہ بنائے ۔ پھر سیدنا ابن عباس رضی اللہ تعالیٰ عنہ کی خدمت میں حاضر ہوکر ان سے رسول اللہ صلی اللہ علیہ وسلم کے وتر ( بشمول قیام اللیل ) کے بارے میں سوال کیا تو سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے کہا : کیا میں تمھیں اس ہستی سے آگاہ نہ کروں ۔ جو روئے زمین کے تمام لوگوں کی نسبت رسول اللہ صلی اللہ علیہ وسلم کے وتر کو زیادہ جاننے والی ہے؟سعد نے کہا : وہ کون ہیں؟انھوں نےکہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا ان کے پاس جاؤ اور پوچھو ، پھر ( دوبارہ ) میرے پاس آنا اور ان کا جواب مجھے بھی آکر بتانا ، ( سعد نے کہا : ) میں ان کی طرف چل پڑا اور ( پہلے ) حکیم بن افلح کے پاس آیا اور انھیں اپنے ساتھ سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے پاس چلنے کو کہا تو انھوں نے کہا : میں ان کے پاس نہیں جاؤں گا کیونکہ میں نے انھیں ( آپس میں لڑنے والی ) ان دو جماعتوں کے بارے میں کچھ بھی کہنے سے روکا تھا ۔ تو وہ ان دونوں کے بارے میں اسی طریقے پر چلتے رہنے کے سوا اور کچھ نہ مانیں ۔ ( سعد نے ) کہا : تو میں نے انھیں قسم دی تو وہ آگئے ، پس ہم سیدہ عائشہ رضی اللہ تعالیٰ عنہا کی طرف چل پڑے ، اور ان سے حاضری کی اجازت طلب کی ، انھوں نے اجازت مرحمت فرمادی اور ہم ان کے گھر ( دروازے ) میں داخل ہوئے ، انھوں نے کہا : کیا حکیم ہو؟انہوں نے اسے پہچان لیا ، اس نے کہا : جی ہاں ۔ تو انھوں نے کہا : تمہارے ساتھ کون ہے؟اس نے کہا : سعد بن ہشام ۔ انھوں نے پوچھا : ہشام کون؟ اس نے کہا : عامر رضی اللہ تعالیٰ عنہ ( بن امیہ انصاری ) کے بیتے ۔ تو انہوں نے ان کے لئے رحمت کی دعا کی اور کلمات خیر کہے ۔ قتادہ نے کہا : وہ ( عامر رضی اللہ تعالیٰ عنہ ) غزوہ احد میں شہید ہوگئے تھے ۔ میں نے کہا : ام المومنین! مجھے رسول اللہ صلی اللہ علیہ وسلم کے خلق مبارک کے بارے میں بتایئے ۔ انھوں نے کہا : کیاتم قرآن نہیں پڑھتے؟میں نے عرض کی : کیوں نہیں !انھوں نے کہا : اللہ کے نبی صلی اللہ علیہ وسلم کا اخلاق قرآن ہی تھا ( آپ کی سیرت وکردار قرآن کا عملی نمونہ تھی ) کہا : اس پر میں نے یہ چاہا کہ اٹھ ( کر چلا ) جاؤں اور موت تک کسی سے کچھ نہ پوچھوں ، پھر اچانک زہن میں آیا تو میں نے کہا مجھے رسول اللہ صلی اللہ علیہ وسلم کے ( رات کے ) قیام کے بارے میں بتائیں ، تو انھوں نے کہا : کیا تم ( «يَا أَيُّهَا الْمُزَّمِّلُ» ) نہیں پڑ ھتے؟ میں نے عرض کی کیوں نہیں!انھوں نے کہا : اللہ تعالیٰ نے اس سورت کے آغاز میں رات کا قیام فرض قرار دیا تو نبی کریم صلی اللہ علیہ وسلم اور آپ کے ساتھیوں نے سال بھر قیام کیا اور اللہ تعالیٰ نے اس سورت کی آخری آیات بارہ ماہ تک آسمان پر روکے رکھیں یہاں تک کہ اللہ تعالیٰ نے اس سورت کے آخر میں تخفیف کا حکم نازل فرمایا تو رات کا قیام فرض ہونے کے بعد نفل ( میں تبدیل ) ہوگیا ۔ سعد نے کہا : میں نے عرض کی : اے ام المومنین ! مجھے رسول اللہ صلی اللہ علیہ وسلم کے وتر کے بارے میں بتایئے ۔ تو انھوں نے کہا : ہم آپ صلی اللہ علیہ وسلم کے لئے آپ کی مسواک اور آپ کے وضو کا پانی تیار کرکے رکھتے تھے اللہ تعالیٰ رات کو جب چاہتا ، آپ کو بیدار کردیتا تو آپ مسواک کرتے ، وضو کرتے اور پھر نو رکعتیں پڑھتے ، ان میں آپ آٹھویں کے علاوہ کسی رکعت میں نہ بیٹھتے ، پھر اللہ کا ذکر کرتے ، اس کی حمد بیان کرتے اور دعا فرماتے ، پھر سلام پھیرے بغیر کھڑے ہوجاتے ، پھر کھڑے ہوکرنویں رکعت پڑھتے ، پھر بیٹھتے اللہ کا ذکر اور حمد کرتے اور اس سے دعا کرتے ، پھر سلام پھیرتے جو ہمیں سناتے جو ہمیں سناتے پھر سلام ے بعد بیٹھ کر دو رکعتیں پڑھتے ، تو میرے بیٹے! یہ گیارہ رکعتیں ہوگئیں ۔ پھر جب رسول اللہ صلی اللہ علیہ وسلم کی عمر مبارک بڑھی اور ( جسم پر کسی حد تک ) گوشت چڑھ گیا ( جسم مبارک بھاری ہوگیا ) تو آپ سات وتر پڑھنے لگ گئے اور دو رکعتوں میں وہی کرتے جو پہلے کرتے تھے ( بیٹھ کر پڑھتے ) تو بیٹا!یہ نو رکعتیں ہوگئیں اور اللہ کے نبی صلی اللہ علیہ وسلم جب کوئی نماز پڑھتے تو آپ پسند کرتے کہ اس پرقائم رہیں اور جب نیند یا بیماری غالب آجاتی اور رات کا قیام نہ کرسکتے تو آپ دن کو بارہ رکعتیں پڑھ لیتے ۔ میں نہیں جانتی کہ اللہ کے نبی کریم صلی اللہ علیہ وسلم نے بھی پورا قرآن ایک رات میں پڑھا ہو اور نہ ہی آپ نے کسی رات صبح تک نماز پڑھی اور نہ رمضان کے سوا کبھی پورے مہینے کے روزے رکھے ۔ ( سعد نے ) کہا : پھر میں ابن عباس رضی اللہ تعالیٰ عنہ کی طرف گیا اور انھیں ان ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا ) کی حدیث سنائی تو انھوں نے کہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے سچ کہا ، اگر میں ان کے قریب ہوتا یا ان کے گھر جاتا ہوتا تو ان کے پاس جاتا تاکہ وہ مجھے یہ حدیث رو برو سناتیں ۔ ( سعد نے ) کہا : میں نےکہا : اگر مجھے علم ہوتا ہے کہ آپ ان کے ہاں حاضر نہیں ہوتے تو میں آپ کو ان کی حدیث نہ سناتا ( یہ سعد بالآخر سرزمین ہند میں شہید ہوئے)"],[1678,"(۔ معاذ بن ہشام نے قتادہ سے انھوں نے زراہ بن اوفیٰ سے اور انھوں نے سعد بن ہشام سے روایت کی کہ انھوں نے بیوی کو طلاق دے دی ، پھر مدینہ کی طرف روانہ ہوئے تاکہ اپنی جائیداد فروخت کریں ۔ ۔ ۔ آگے اسی سابقہ حدیث کی ) طرح بیان کیا ۔","",{"u2":"۔ معاذ بن ہشام نے قتادہ سے انھوں نے زراہ بن اوفیٰ سے اور انھوں نے سعد بن ہشام سے روایت کی کہ انھوں نے بیوی کو طلاق دے دی،پھر مدینہ کی طرف روانہ ہوئے تاکہ اپنی جائیداد فروخت کریں۔۔۔\nآگے اسی سابقہ حدیث کی) طرح بیان کیا۔"}],[1679,"محمد بن بشر نے کہا : ہمیں سعید بن ابی عروبہ نے حدیث سنائی ، کہا : ہم سے قتادہ نے حدیث بیا ن کی ، انھوں نے زراہ بن اوفیٰ سے اور انھوں نے سعد بن ہشام سے رویت کی کہ انھوں نے کہا : میں سیدنا عبداللہ ابن عباس رضی اللہ تعالیٰ عنہ کے پاس گیا اور ان سے وتر کےبارے میں سوال کیا ۔ ۔ ( اس کے بعد ) انھوں نے اپنے پورے قصے سمیت حدیث بیان کی اور اس میں کہا : انھوں ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا ) نے کہا : کون ہشام؟میں نے عرض کی : عامر رضی اللہ تعالیٰ عنہ کے بیٹے ۔ انھوں نے کہا : عامر بہت اچھے انسان تھے اُحد کے دن شہید ہوئے ۔","",{"u2":"محمد بن بشر نے کہا:ہمیں سعید بن ابی عروبہ نے حدیث سنائی،کہا: ہم سے قتادہ نے حدیث بیا ن کی،انھوں نے زراہ بن اوفیٰ سے اور انھوں نے سعد بن ہشام سے رویت کی کہ انھوں نے کہا: میں حضرت عبداللہ ابن عباس رضی اللہ تعالیٰ عنہ کےپاس گیا اور ان سے وتر کےبارے میں سوال کیا۔۔(اس کے بعد)انھوں نے اپنے پورے قصے سمیت حدیث بیان کی اور اس میں کہا: انھوں(حضرت عائشہ رضی اللہ تعالیٰ عنہا) نے کہا: کون ہشام؟میں نے عرض کی:عامر رضی اللہ تعالیٰ عنہ کے بیٹے۔انھوں نے کہا:عامر بہت اچھے انسان تھے اُحد کے دن شہید ہوئے۔"}],[1680,"معمر نے قتادہ سے اور انھوں نے زراہ بن اوفیٰ سے روایت کی کہ سعد بن ہشام ان کے پڑوسی تھے ، انھوں نے ان کو بتایا کہ انھوں نے اپنی بیوی کو طلاق دے دی ۔ ۔ آگے سعید ( بن ابی عروبہ ) کے ہم معنیٰ حدیث بیان کی ۔ اس میں ہے ، ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے ) کہا : کون ہشام؟عرض کی : عامر رضی اللہ تعالیٰ عنہ کے بیٹے ۔ انھوں نے کہا : وہ اچھے انسان تھے غزوہ احد میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ( لڑتےہوئے ) تھے شہید ہوئے ، نیز اس ( روایت ) میں ہے کہ ( سعد کے بجائے ) حکیم بن افلح نے کہا : اگر میں جانتا کہ آپ ان کے پاس حاضر نہیں ہوتے تو میں آپ کو ان کی حدیث نہ بتاتا ۔","",{"u2":"معمر نے قتادہ سے اور انھوں نے زراہ بن اوفیٰ سے روایت کی کہ سعد بن ہشام ان کے پڑوسی تھے،انھوں نے ان کو بتایا کہ انھوں نے اپنی بیوی کو طلاق دے دی۔۔آگے سعید (بن ابی عروبہ) کے ہم معنیٰ حدیث بیان کی۔اس میں ہے،(حضرت عائشہ رضی اللہ تعالیٰ عنہا نے) کہا: کون ہشام؟عرض کی:عامر رضی اللہ تعالیٰ عنہ کے بیٹے۔انھوں نے کہا: وہ اچھے انسان تھے غزوہ احد میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (لڑتےہوئے) تھے شہید ہوئے،نیز اس (روایت) میں ہے کہ(سعدکے بجائے) حکیم بن افلح نے کہا: اگر میں جانتا کہ آپ ان کے پاس حاضر نہیں ہوتے تو میں آپ کو ان کی حدیث نہ بتاتا۔"}],[1681,"ابوعوانہ نے قتادہ سے ، انھوں نے زراہ بن اوفیٰ سے ، انھوں نے سعد بن ہشام سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب آپ کی رات کی نماز بیماری یا کسی اور وجہ سے رہ جاتی تو دن کو بارہ رکعتیں پڑھ لیتے ۔","",{"u2":"ابوعوانہ نے قتادہ سے،انھوں نے زراہ بن اوفیٰ سے،انھوں نے سعد بن ہشام سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب آپ کی رات کی نماز بیماری یا کسی اور وجہ سے رہ جاتی تو دن کو بارہ رکعتیں پڑھ لیتے۔"}],[1682,"شعبہ نے قتادہ سے اسی سند کے ساتھ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب کوئی کام کرتے تو اس کو برقراررکھتے اور جب آپ رات سوتے رہ جاتے یا بیمار ہوجاتے تو آپ دن کو بارہ رکعتیں پڑھ لیتے ۔ ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے ) کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو ( کبھی ) نہیں دیکھا کہ آپ نے ساری رات صبح تک نماز پڑھی ہو اور نہ ( کبھی ) آپ نے رمضان کے سوا مسلسل مہینے بھر کے روزے رکھے ۔","",{"u2":"شعبہ نے قتادہ سے اسی سند کے ساتھ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم جب کوئی کام کرتے تو اس کو برقراررکھتے اور جب آپ رات سوتے رہ جاتے یا بیمار ہوجاتے تو آپ دن کو بارہ رکعتیں پڑھ لیتے۔\n(حضرت عائشہ رضی اللہ تعالیٰ عنہا نے) کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو (کبھی) نہیں دیکھا کہ آپ نے ساری رات صبح تک نماز پڑھی ہواور نہ(کبھی) آپ نے رمضان کے سوا مسلسل مہینے بھر کے روزے رکھے۔"}],[1683,"عبدالرحمان بن عبدالقاری سے روایت ہے ، کہا : میں نے عمر بن خطاب رضی اللہ تعالیٰ عنہ سے سنا ، کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس کسی کا حزب ( قرآن کا 1/7 ) حصہ جو عموما ایک رات میں تہجد کے دوران میں پڑھا جاتا تھا ) یا اس کا کچھ حصہ سوتے رہ جانے کی وجہ سے رہ گیا اور اس نے اسے نماز فجر اور نماز ظہر کے درمیان پڑھ لیا تو اس کے حق میں یہ لکھا جائےگا ، جیسے اس نے رات ہی کو اسے پڑھا ۔","",{"u2":"عبدالرحمان بن عبدالقاری سے روایت ہے،کہا:میں نے عمر بن خطاب رضی اللہ تعالیٰ عنہ سے سنا،کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جس کسی کا حزب(قرآن کا 1/7) حصہ جو عموما ایک رات میں تہجد کے دوران میں پڑھا جاتا تھا) یا اس کا کچھ حصہ سوتے رہ جانے کی وجہ سے رہ گیا اور اس نے اسے نماز فجر اور نمازظہر کے درمیان پڑھ لیا تو اس کے حق میں یہ لکھا جائےگا،جیسے اس نے رات ہی کو اسے پڑھا۔\""}],[1684,"ایوب نے قاسم شیبانی سے روایت کی کہ سیدنا زید بن ارقم رضی اللہ تعالیٰ عنہ نے کچھ لوگوں کو چاشت کے وقت نماز پڑھتے دیکھا تو کہا : ہاں یہ لوگ اچھی طرح جانتے ہیں کہ نماز اس وقت کی بجائے ایک اور وقت میں پڑھنا افضل ہے ۔ بے شک رسول اللہ صلی اللہ علیہ وسلم نے فرمایا \" اوابین ( اطاعت گزار ، توبہ کرنے والے اور اللہ تعالیٰ کی طرف رجوع کرنے والےلوگوں ) کی نماز اس وقت ہوتی ہے ۔ ، جب ( گرمی سے ) اونٹ کے دودھ چھڑائے جانے والے بچوں کے پاؤں جلنے لگتے ہیں ۔","",{"u2":"ایوب نے قاسم شیبانی سے روایت کی کہ حضرت زید بن ارقم رضی اللہ تعالیٰ عنہ نے کچھ لوگوں کو چاشت کے وقت نماز پڑھتے دیکھاتو کہا:ہاں یہ لوگ اچھی طرح جانتے ہیں کہ نماز اس وقت کی بجائے ایک اور وقت میں پڑھنا افضل ہے۔بے شک رسول اللہ صلی اللہ علیہ وسلم نے فرمایا\"اوابین(اطاعت گزار،توبہ کرنے والے اور اللہ تعالیٰ کی طرف رجوع کرنے والےلوگوں) کی نماز اس وقت ہوتی ہے۔،جب(گرمی سے) اونٹ کے دودھ چھڑائے جانے والے بچوں کے پاؤں جلنے لگتے ہیں۔\""}],[1685,"ہشام بن ابی عبداللہ نے کہا : ہمیں قاسم شیبانی نے سیدنا زید بن ارقم رضی اللہ تعالیٰ عنہ سے حدیث بیا ن کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم اہل قباء کے پاس تشریف لائے ، وہ لوگ ( اس وقت ) نماز پڑھ رہے تھےتوآ پ نے فرمایا : \" اوابین کی نماز اونٹ کے دودھ چھڑانے جانے والے بچوں کے پاؤ ں جلنے کے وقت ( پر ہوتی ) ہے ۔","",{"u2":"ہشام بن ابی عبداللہ نے کہا: ہمیں قاسم شیبانی نے حضرت زید بن ارقم رضی اللہ تعالیٰ عنہ سے حدیث بیا ن کی،انھوں نے کہا: ر سول اللہ صلی اللہ علیہ وسلم اہل قباء کے پاس تشریف لائے،وہ لوگ(اس وقت) نماز پڑھ رہے تھےتوآ پ نے فرمایا:\"اوابین کی نماز اونٹ کے دودھ چھڑانے جانے والے بچوں کے پاؤ ں جلنے کے وقت(پر ہوتی) ہے۔\""}],[1686,"نافع اور عبداللہ بن دینار نے سیدنا ا بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں سوال کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" رات کی نمازدو رکعتیں ہیں ، جب تم میں سے کسی کو صبح ہونے کا اندیشہ ہو تو وہ ایک رکعت پڑھ لے ، یہ اس کی پڑھی ہوئی ( تمام ) نماز کو وتر ( طاق ) بنادے گی ۔","",{"u2":"نافع اور عبداللہ بن دینار نے حضرت ا بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں سوال کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"رات کی نمازدو رکعتیں ہیں،جب تم میں سے کسی کو صبح ہونے کا اندیشہ ہو تو وہ ایک رکعت پڑھ لے،یہ اس کی پڑھی ہوئی(تمام) نماز کو وتر(طاق) بنادے گی۔\""}],[1687,"سفیان نے زہری سے ، انھوں نے سالم سے اور انھوں نے اپنے والد ( عبداللہ بن عمر رضی اللہ تعالیٰ عنہ ) سے روایت کی کہ ایک آدمی نے نبی اکرم صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" دو دو رکعتیں ۔ اور جب تمھیں صبح ہونے کا اندیشہ ہو تو ایک رکعت وترپڑھ لو ۔"],[1688,"سفیان نے زہری سے ، انھوں نے سالم سے اور انھوں نے اپنے والد ( عبداللہ بن عمر رضی اللہ تعالیٰ عنہ ) سے روایت کی کہ ایک آدمی نے نبی اکرم صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" دو دو رکعتیں ۔ اور جب تمھیں صبح ہونے کا اندیشہ ہو تو ایک رکعت وترپڑھ لو ۔"],[1689,"سفیان نے زہری سے ، انھوں نے سالم سے اور انھوں نے اپنے والد ( عبداللہ بن عمر رضی اللہ تعالیٰ عنہ ) سے روایت کی کہ ایک آدمی نے نبی اکرم صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" دو دو رکعتیں ۔ اور جب تمھیں صبح ہونے کا اندیشہ ہو تو ایک رکعت وترپڑھ لو ۔",""],[1690,"عمرو نے کہا ابن شہاب نے اس سے بیان کہ اسے سالم بن عبداللہ بن عمر اور حمید بن عبدالرحمان بن عوف دونوں نے عبداللہ بن عمر بن خطاب رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ انھوں نے کہا : ایک آدمی کھڑا ہوا اور کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم !رات کی نماز کیسے ہے؟رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" رات کی نماز دو دو رکعت ہے اور جب تمھیں صبح ہونے کا خطرہ ہوتو ایک ایک رکعت ( پڑھ کر انھیں ) وتر کرلو ۔","",{"u2":"عمرو نے کہا ابن شہاب نے اس سے بیان کہ اسے سالم بن عبداللہ بن عمر اور حمید بن عبدالرحمان بن عوف دونوں نے عبداللہ بن عمر بن خطاب رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ انھوں نے کہا:ایک آدمی کھڑا ہوا اور کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!رات کی نماز کیسے ہے؟رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"رات کی نماز دو دو رکعت ہے اور جب تمھیں صبح ہونے کا خطرہ ہوتو ایک ایک رکعت(پڑھ کر انھیں) وتر کرلو۔\""}],[1691,"ابو ربیع زہرانی نے کہا : ہمیں حماد نے حدیث سنائی کہا : ہمیں ایوب اور بدیل نے عبداللہ بن شقیق سے حدیث بیان کی ، انھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ ایک آدمی نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا ، اور میں آپ کے اور پوچھنے والے کے درمیان میں تھا ، اس نے کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم !رات کی نماز کیسے ہوتی ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" دو دو رکعتیں ، پھر جب تمھیں صبح ہونے کا اندیشہ ہو توا یک رکعت پڑھ لو اور وتر کو ا پنی نماز کا آخری حصہ بناؤ ۔ \" پھر سال کے بعد ایک آدمی نے آپ سے پوچھا ، میں رسول اللہ صلی اللہ علیہ وسلم کے قریب اسی جگہ ( درمیان میں ) تھا اور مجھے معلوم نہیں وہ پہلے والا آدمی تھا یا کوئی اور ، اسے بھی آپ نے اسی طرح جواب دیا ۔","",{"u2":"ابو ربیع زہرانی نے کہا:ہمیں حماد نے حدیث سنائی کہا: ہمیں ایوب اور بدیل نے عبداللہ بن شقیق سے حدیث بیان کی،انھوں نے حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ ایک آدمی نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا،اور میں آپ کے اور پوچھنے والے کے درمیان میں تھا،اس نے کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!رات کی نماز کیسے ہوتی ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"دو دو رکعتیں،پھر جب تمھیں صبح ہونے کا اندیشہ ہو توا یک رکعت پڑھ لو اور وتر کو ا پنی نماز کا آخری حصہ بناؤ۔\"پھر سال کے بعد ایک آدمی نے آپ سے پوچھا،میں رسول اللہ صلی اللہ علیہ وسلم کے قریب اسی جگہ (درمیان میں) تھا اور مجھے معلوم نہیں وہ پہلے والا آدمی تھا یا کوئی اور،اسے بھی آپ نے اسی طرح جواب دیا۔"}],[1692,"ابو کامل نے کہا : ہمیں حماد نے حدیث سنائی ، کہا : ہمیں ایوب ، بدیل اور عمران بن حدیر نے عبداللہ بن شقیق سے ، انھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی ، نیز ( دوسری سند سے ) محمد بن عبید غبری نے کہا : ہمیں حماد نے حدیث سنائی ، کہا : ہم سے ایوب اور زبیر بن خریت نے عبداللہ بن شقیق سے ، انھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ ایک آدمی نے نبی کریم صلی اللہ علیہ وسلم سے سوال کیا ۔ ۔ ۔ پھر دونوں ( ابو کامل اور محمد بن عبید ) نے اوپر والی ر وایت بیان کی مگر ان دونوں کی روایت میں \" ایک آدمی نے آپ سے ایک سال گزرنے کا بعد پوچھا \" اور اس کے بعد کا حصہ مروی نہیں ۔"],[1693,"ابو کامل نے کہا : ہمیں حماد نے حدیث سنائی ، کہا : ہمیں ایوب ، بدیل اور عمران بن حدیر نے عبداللہ بن شقیق سے ، انھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی ، نیز ( دوسری سند سے ) محمد بن عبید غبری نے کہا : ہمیں حماد نے حدیث سنائی ، کہا : ہم سے ایوب اور زبیر بن خریت نے عبداللہ بن شقیق سے ، انھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ ایک آدمی نے نبی کریم صلی اللہ علیہ وسلم سے سوال کیا ۔ ۔ ۔ پھر دونوں ( ابو کامل اور محمد بن عبید ) نے اوپر والی ر وایت بیان کی مگر ان دونوں کی روایت میں \" ایک آدمی نے آپ سے ایک سال گزرنے کا بعد پوچھا \" اور اس کے بعد کا حصہ مروی نہیں ۔",""],[1694,"سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا : \" وتر پڑھنے میں صبح سے سبقت کرو ۔ \" ( صبح ہونے سے پہلے پہلے وتر پڑھ لو ۔)","",{"u2":"حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا:\"وتر پڑھنے میں صبح سے سبقت کرو۔\"(صبح ہونے سے پہلے پہلے وتر پڑھ لو۔)"}],[1695,"لیث نے نافع سے روایت کی کہ سیدنا ابن عمر رضی اللہ تعالیٰ عنہا رضی اللہ تعالیٰ عنہ نے کہا : جوشخص ر ات کو نماز پڑھے ، وہ وتر کو اپنی نماز کا آخری حصہ بنائے کیونکہ رسول اللہ صلی اللہ علیہ وسلم اسی کا حکم دیتے تھے ۔","",{"u2":"لیث نے نافع سے روایت کی کہ حضرت ابن عمر رضی اللہ تعالیٰ عنہا رضی اللہ تعالیٰ عنہ نے کہا:جوشخص ر ات کو نماز پڑھے،وہ وتر کو اپنی نماز کا آخری حصہ بنائے کیونکہ رسول اللہ صلی اللہ علیہ وسلم اسی کا حکم دیتے تھے۔"}],[1696,"عبیداللہ نے نافع سے ، انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے اور ا نھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" رات کے وقت وتر کو اپنی نماز کا آخری حصہ بناؤ ۔","",{"u2":"عبیداللہ نے نافع سے،انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے اور ا نھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی،آپ نے فرمایا:\"رات کے وقت وتر کو اپنی نماز کا آخری حصہ بناؤ۔\""}],[1697,"ابن جریج نے کہا : مجھے نافع نے بتایا کہ سیدنا ابن عمر رضی اللہ تعالیٰ عنہ کہاکرتے تھے : جو شخص ر ات کو نماز پڑھے وہ صبح سے پہلے نماز کا آخری حصہ وتر کو بنائے ، رسول اللہ صلی اللہ علیہ وسلم ان ( اپنے ساتھیوں ) کو یہی حکم دیاکرتے تھے ۔","",{"u2":"ابن جریج نے کہا:مجھے نافع نے بتایا کہ حضرت ابن عمر رضی اللہ تعالیٰ عنہ کہاکرتے تھے:جو شخص ر ات کو نماز پڑھے وہ صبح سے پہلے نماز کا آخری حصہ وتر کوبنائے،رسول اللہ صلی اللہ علیہ وسلم ان(اپنے ساتھیوں) کو یہی حکم دیاکرتے تھے۔"}],[1698,"ابو تیاح نے کہا : مجھے ابو مجلز نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے حدیث سنائی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" وتر رات کے آخری حصے کی ایک رکعت ہے ۔","",{"u2":"ابو تیاح نے کہا:مجھے ابو مجلز نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے حدیث سنائی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"وتر رات کے آخری حصے کی ایک رکعت ہے۔\"\nشعبہ نے قتادہ سے،انھوں نے مجلز سے روایت کی،انھوں نے کہا:میں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے سنا، وہ نبی اکرم صلی اللہ علیہ وسلم سے حدیث بیان کرتے تھے کہ آپ نے فرمایا:\"وتر رات کے آخری حصے کی ایک رکعت ہے۔\""}],[1699,"شعبہ نے قتادہ سے ، انھوں نے مجلز سے روایت کی ، انھوں نے کہا : میں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے سنا ، وہ نبی اکرم صلی اللہ علیہ وسلم سے حدیث بیان کرتے تھے کہ آپ نے فرمایا : \" وتر رات کے آخری حصے کی ایک رکعت ہے ۔"],[1700,"ہمام نے کہا : ہمیں قتادہ نے ابو مجلز سے حدیث بیان کی ، انھوں نے کہا : میں نےسیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے وتر کے بارے میں سوال کیا تو انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے ۔ \" ( وتر ) رات کے آخری حصے کی ایک رکعت ہے ۔ \" اور میں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے پوچھا تو انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" ( وتر ) رات کے آخر کی ایک رکعت ہے ۔","",{"u2":"ہمام نے کہا:ہمیں قتادہ نے ابو مجلز سے حدیث بیان کی،انھوں نے کہا: میں نےحضرت ابن عباس رضی اللہ تعالیٰ عنہ سے وتر کے بارے میں سوال کیا تو انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا،آپ فرما رہے تھے۔\"(وتر)رات کے آخری حصے کی ایک رکعت ہے۔\"اور میں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے پوچھا تو انھوں نے کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا:\"(وتر) رات کے آخر کی ایک رکعت ہے۔\""}],[1701,"ابو کریب اور ہارون بن عبداللہ نے کہا : ہمیں ابو اسامہ نے ولید بن کثیر سے حدیث سنائی ، انھوں نے کہا : مجھے عبیداللہ بن عبداللہ بن عمر رضی اللہ تعالیٰ عنہ نے حدیث سنائی کہ سیدنا عمر رضی اللہ تعالیٰ عنہ نے انھیں بتایا کہ ایک آدمی نے جب رسول اللہ صلی اللہ علیہ وسلم مسجد میں تھے آپ کو آواز دی اور کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم !میں رات کی نماز کو وتر ( طاق ) کیسے بناؤں؟رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جو ( رات ) کی نماز پڑھے وہ دو دو رکعت پڑھے ، پھر وہ اگر محسوس کرے کہ صبح ہورہی ہےتو ایک رکعت پڑھ لے ، یہ ( ایک رکعت ) اس کی ساری نماز کو وتر ( طاق ) بنا دے گی ۔ \"\" ابو کریب نے عبیداللہ بن عبداللہ کہا ، ( آگے ) ابن عمر رضی اللہ تعالیٰ عنہ نے کہا ۔","",{"u2":"ابو کریب اور ہارون بن عبداللہ نے کہا:ہمیں ابو اسامہ نے ولید بن کثیر سے حدیث سنائی،انھوں نے کہا:مجھے عبیداللہ بن عبداللہ بن عمر رضی اللہ تعالیٰ عنہ نے حدیث سنائی کہ حضرت عمر رضی اللہ تعالیٰ عنہ نے انھیں بتایا کہ ایک آدمی نے جب رسول اللہ صلی اللہ علیہ وسلم مسجد میں تھے آپ کو آواز دی اور کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!میں رات کی نماز کو وتر(طاق) کیسے بناؤں؟رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جو(رات) کی نماز پڑھے وہ دو دو رکعت پڑھے،پھر وہ اگر محسوس کرے کہ صبح ہورہی ہےتو ایک رکعت پڑھ لے،یہ(ایک رکعت) اس کی ساری نماز کو وتر (طاق) بنا دے گی۔\"\nابو کریب نے عبیداللہ بن عبداللہ کہا،(آگے) ابن عمر رضی اللہ تعالیٰ عنہ نے کہا۔"}],[1702,"خلف بن ہشام اور ابوکامل نے کہا : ہمیں حماد بن زید نے انس بن سیرن سے حدیث سنائی ، انھوں نے کہا میں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے عرض کی : صبح کی نماز سے پہلے کی دو رکعتوں کے بارے میں آپ کی کیا رائے ہے ، کیا میں ان میں طویل قراءت کرسکتا ہوں؟انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم رات کو دو دو رکعت پڑھتے تھے اور ایک رکعت سے اس کو وتر بناتے ، میں نے کہا : میں آپ سے اس کے بارے میں نہیں پوچھ رہا ۔ انھوں نے کہا : تم ایک بوجھل آدمی ہو ( اپنی سوچ کو ترجیح دیتے ہو ) کیا مجھے موقع نہ دو گے کہ میں تمہارے لئے بات کو مکمل کروں؟رسول اللہ صلی اللہ علیہ وسلم رات کو دو دو رکعت پڑھتے تھے اور ایک وتر پڑھتے اور صبح ( کی نماز ) سے پہلے ( مختصر سی ) دو رکعتیں پڑھتے ، گویا کہ اذان ( اقامت ) آ پ کے کانوں میں ( سنائی دے رہی ) ہے ۔ خلف نے اپنی حدیث میں \"\" صبح سے پہلے کی دو رکعتوں کے بارے میں آپ کی رائے کیا ہے؟کہا اور انھوں نے \"\" صلاۃ \"\" کا لفظ بیان نہیں کیا ۔","",{"u2":"خلف بن ہشام اور ابوکامل نے کہا: ہمیں حماد بن زیدنے انس بن سیرن سے حدیث سنائی،انھوں نے کہا میں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے عرض کی:صبح کی نماز سے پہلے کی دو رکعتوں کے بارے میں آپ کی کیا رائے ہے،کیا میں ان میں طویل قراءت کرسکتا ہوں؟انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم رات کو دو دو رکعت پڑھتے تھے اور ایک رکعت سے اس کو وتر بناتے،میں نے کہا: میں آپ سے اس کے بارے میں نہیں پوچھ رہا۔انھوں نے کہا:تم ایک بوجھل آدمی ہو(اپنی سوچ کو ترجیح دیتے ہو)کیا مجھے موقع نہ دو گے کہ میں تمہارے لئے بات کو مکمل کروں؟رسول اللہ صلی اللہ علیہ وسلم رات کو دو دو رکعت پڑھتے تھے اور ایک وتر پڑھتے اور صبح(کی نماز) سے پہلے(مختصر سی) دو رکعتیں پڑھتے،گویا کہ اذان(اقامت) آ پ کے کانوں میں (سنائی دے رہی) ہے۔\nخلف نے اپنی حدیث میں\"صبح سے پہلے کی دو رکعتوں کے بارے میں آپ کی رائے کیا ہے؟کہا اور انھوں نے \"صلاۃ\" کا لفظ بیان نہیں کیا۔"}],[1703,"شعبہ نے انس بن سیرین سے روایت کی ، انھوں نے کہا : میں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے پوچھا ۔ ۔ ۔ پھر مذکورہ بالا حدیث کی طرح حدیث بیان کی اور اس میں یہ اضافہ کیا : رات کے آخری حصے میں ایک رکعت وتر پڑھتے ۔ اس میں ہے ( اور میرے دوبارہ سوا ل پر ) کہا : بس ، بس ، تم ایک بوجھل آدمی ہو ۔","",{"u2":"شعبہ نے انس بن سیرین سے روایت کی،انھوں نے کہا:میں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے پوچھا۔۔۔پھر مذکورہ بالا حدیث کی طرح حدیث بیان کی اور اس میں یہ اضافہ کیا:رات کے آخری حصے میں ایک رکعت وتر پڑھتے۔اس میں ہے(اور میرے دوبارہ سوا ل پر)کہا: بس،بس،تم ایک بوجھل آدمی ہو۔"}],[1704,"عقبہ بن حریث نے کہا : میں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے سنا ، وہ حدیث بیان کررہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" رات کی نماز دو رکعت ہے اور جب تم دیکھو کہ صبح آیا چاہتی ہے تو ایک رکعت سے ( اپنی نماز کو ) وتر کرو ۔ \" ابن عمر رضی اللہ تعالیٰ عنہ سے عرض کی گئی : مثنیٰ ، مثنیٰ ، کا کیا مفہوم ہے؟انھوں نے کہا : یہ کہ تم ہر دو رکعتوں ( کے آخر ) میں سلام پھیرو ۔","",{"u2":"عقبہ بن حریث نے کہا:میں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے سنا،وہ حدیث بیان کررہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"رات کی نماز دو رکعت ہے اور جب تم دیکھو کہ صبح آیا چاہتی ہے تو ایک رکعت سے(اپنی نماز کو) وتر کرو۔\"ابن عمر رضی اللہ تعالیٰ عنہ سے عرض کی گئی:مثنیٰ،مثنیٰ،کا کیا مفہوم ہے؟انھوں نے کہا:یہ کہ تم ہر دو رکعتوں(کے آخر) میں سلام پھیرو۔"}],[1705,"معمرنے یحییٰ بن ابی کثیر سے ، انھوں نے ابو نضرہ سے اور انھوں نے سیدنا ابو سعید رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : \" صبح سے پہلے پہلے وتر پڑھ لو ۔","",{"u2":"معمرنے یحییٰ بن ابی کثیر سے،انھوں نے ابو نضرہ سے اور انھوں نے حضرت ابو سعید رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\"صبح سے پہلے پہلے وتر پڑھ لو۔\""}],[1706,"شیبان نے یحییٰ ( بن ابی کثیر ) سے روایت کی ، انھوں نے کہا : ابو نضرۃ عوقی نے مجھے بتایا کہ سیدنا ابو سعید رضی اللہ تعالیٰ عنہ نے انھیں بتایا کہ انھوں ( صحابہ ) نے نبی اکرم صلی اللہ علیہ وسلم سے وتر کے بارے میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" صبح ہونے سے پہلے وتر پڑھ لو ۔","",{"u2":"شیبان نے یحییٰ (بن ابی کثیر) سے روایت کی،انھوں نے کہا:ابو نضرۃ عوقی نے مجھے بتایا کہ حضرت ابو سعید رضی اللہ تعالیٰ عنہ نے انھیں بتایا کہ انھوں(صحابہ) نے نبی اکرم صلی اللہ علیہ وسلم سے وتر کے بارے میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:\"صبح ہونے سے پہلے وتر پڑھ لو۔\""}],[1707,"حفص اور ابو معاویہ نے اعمش سے حدیث سنائی ، انھوں نے ابو سفیان سے اور انھوں نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جسے ڈر ہو کہ وہ رات کے آخری حصے میں نہیں اٹھ سکے گا ، وہ رات کے شروع میں وتر پڑھ لے ۔ اور جسے امید ہو کہ وہ رات کے آخر میں اٹھ جائے گا ، وہ رات کے آخر میں وتر پڑھے کیونکہ رات کے آخری حصے کی نماز کا مشاہدہ کیا جاتا ہے اور یہ افضل ہے ۔ \"\" ابومعاویہ نے ( مشهوده کی بجائے ) محضورة ( اس میں حاضری دی جاتی ہے ) کہا ۔ ( مفہوم ایک ہی ہے)","",{"u2":"حفص اور ابو معاویہ نے اعمش سے حدیث سنائی،انھوں نے ابو سفیان سے اور انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جسے ڈر ہو کہ وہ رات کے آخری حصے میں نہیں اٹھ سکے گا،وہ رات کے شروع میں وتر پڑھ لے۔اور جسے امید ہو کہ وہ رات کے آخر میں اٹھ جائے گا،وہ رات کے آخر میں وتر پڑھے کیونکہ رات کے آخری حصے کی نماز کا مشاہدہ کیا جاتا ہے اور یہ افضل ہے۔\"\nابومعاویہ نے (مشہودہ کی بجائے) محضورۃ(اس میں حاضری دی جاتی ہے) کہا۔(مفہوم ایک ہی ہے)-"}],[1708,"ابو زبیر نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا ، آپ فرمارہے تھے : \" تم میں سے جسے یہ خدشہ ہوکہ وہ رات کے آخر میں نہیں اٹھ سکے گا تو وہ وتر پڑھ لے ، پھر سوجائے اور جسے رات کو اٹھ جانے کا یقین ہو ، وہ رات کے آخرمیں وتر پڑھے کیونکہ رات کے آخری حصے میں قراءت کے وقت حاضری دی جاتی ہے اور یہ بہتر ہے ۔","",{"u2":"ابو زبیر نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا،آپ فرمارہے تھے:\"تم میں سے جسے یہ خدشہ ہوکہ وہ رات کے آخر میں نہیں اٹھ سکے گا تو وہ وتر پڑھ لے،پھر سوجائے اور جسے رات کو اٹھ جانے کا یقین ہو،وہ رات کے آخرمیں وتر پڑھے کیونکہ رات کے آخری حصے میں قراءت کے وقت حاضری دی جاتی ہے اور یہ بہتر ہے۔\""}],[1709,"ابو زبیر نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے ر وایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قیام کا لمبا ہونا بہترین نماز ہے ۔","",{"u2":"ابو زبیر نے حضرت جابر رضی اللہ تعالیٰ عنہ سے ر وایت کی، انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"قیام کا لمبا ہونا بہترین نماز ہے۔\""}],[1710,"ابو بکر بن ابی شیبہ اور ابو کریب دونوں نے کہا : ہمیں ابو معاویہ نے حدیث بیان کی ، انھوں نے کہا : ہمیں اعمش نے ابو سفیان سے حدیث سنائی اور انھوں نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم سے پوچھاگیا : کون سی نماز افضل ہے؟آپ نے فرمایا : \"\" قیام کا لمبا ہونا ۔ \"\" ابو بکر بن ابی شیبہ نے کہا : ابومعاویہ نے ہمیں اعمش سے حدیث بیان کی ۔","",{"u2":"ابو بکر بن ابی شیبہ اور ابو کریب دونوں نے کہا:ہمیں ابو معاویہ نے حدیث بیان کی،انھوں نے کہا:ہمیں اعمش نے ابو سفیان سے حدیث سنائی اور انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم سے پوچھاگیا:کون سی نمازافضل ہے؟آپ نے فرمایا:\"قیام کا لمبا ہونا۔\"\nابو بکر بن ابی شیبہ نے کہا:ابومعاویہ نے ہمیں اعمش سے حدیث بیان کی۔"}],[1711,"ابو سفیان سے روایت ہے ، انھوں نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا ، آپ فرماتے تھے : \" رات میں ایک گھڑی ایسی ہے ۔ جو مسلمان بندہ بھی اس کو پالیتا ہے ۔ اس میں وہ دنیا وآخرت کی کسی بھی خیر اور بھلائی کا سوال کرتا ہےتو اللہ اسے وہ ( بھلائی ) ضرور عطا فرمادیتا ہے ۔ اور یہ گھڑی ہر رات میں ہوتی ہے ۔","",{"u2":"ابو سفیان سے روایت ہے،انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا،آپ فرماتے تھے:\"رات میں ایک گھڑی ایسی ہے۔جو مسلمان بندہ بھی اس کو پالیتا ہے۔اس میں وہ دنیا وآخرت کی کسی بھی خیر اور بھلائی کا سوال کرتا ہےتو اللہ اسے وہ(بھلائی) ضرور عطا فرمادیتا ہے۔اور یہ گھڑی ہر رات میں ہوتی ہے۔\""}],[1712,"ابو زبیر رضی اللہ تعالیٰ عنہ نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" رات میں ایک ایسی گھڑی ہے جو مسلمان بھی اسے پالیتا ہے اور اس میں اللہ سے کسی بھی خیر کا سوال کرتا ہے تو وہ اسے وہ ( بھلائی ) عطا فرمادیتا ہے ۔","",{"u2":"ابو زبیر رضی اللہ تعالیٰ عنہ نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"رات میں ایک ایسی گھڑی ہے جو مسلمان بھی اسے پالیتا ہے اور اس میں اللہ سے کسی بھی خیر کا سوال کرتا ہے تو وہ اسے وہ (بھلائی) عطا فرمادیتا ہے۔\""}],[1713,"ابن شہاب نے ابو عبداللہ اغز اور ابو سلمہ بن عبدالرحمان سے ، انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : برکت اور رفعت کا مالک ہمارا رب ، ہر رات کو جب رات کا آخری تہائی حصہ باقی رہ جاتا ہے ، ( تو ) دنیا کے آ سمان پر نزول فرماتا ہے اور کہتا ہے : کون مجھے پکارتا ہے کہ میں اس کی پکار کو سنوں؟کون مجھ سے مانگتا ہ ے کہ میں اس کو دوں ، اور کون مجھ سے بخشش طلب کرتاہے کہ میں اسے بخش دوں؟","",{"u2":"ابن شہاب نے ابو عبداللہ اغز اور ابو سلمہ بن عبدالرحمان سے،انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ ر سول اللہ صلی اللہ علیہ وسلم نے فرمایا:برکت اور رفعت کا مالک ہمارا رب،ہر رات کو جب رات کا آخری تہائی حصہ باقی رہ جاتا ہے،(تو) دنیا کے آ سمان پر نزول فرماتا ہے اور کہتا ہے:کون مجھے پکارتا ہے کہ میں اس کی پکار کو سنوں؟کون مجھ سے مانگتا ہ ے کہ میں اس کو دوں،اور کون مجھ سے بخشش طلب کرتاہے کہ میں اسے بخش دوں؟\""}],[1714,"سہیل کے والد ابو صالح نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" اللہ تعالیٰ ہر رات کو ، جب رات کا پہلا تہائی حصہ گزر جاتا ہے ، دنیا کے آسمان پر نزول فرماتا ہے اور کہتا ہے : میں بادشاہ ہوں ، صرف میں بادشاہ ہوں ، کون ہے جو مجھے پکارتا ہے ہے کہ میں اس کی پکار کو سنوں؟کو ن ہے جو مجھ سے مانگتا ہے کہ میں اسے دوں؟کون ہے جو مجھ سے مغفرت طلب کرتا ہے کہ میں اسے معاف کروں؟وہ یہی اعلان فرماتا رہتا ہے حتیٰ کہ صبح چمک اٹھتی ہے ۔","",{"u2":"سہیل کے والد ابو صالح نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی،آپ نے فرمایا:\"اللہ تعالیٰ ہر رات کو،جب رات کا پہلا تہائی حصہ گزر جاتا ہے،دنیا کے آسمان پر نزول فرماتا ہے اور کہتا ہے:میں بادشاہ ہوں،صرف میں بادشاہ ہوں،کون ہے جو مجھے پکارتا ہے ہے کہ میں اس کی پکار کو سنوں؟کو ن ہے جو مجھ سے مانگتا ہے کہ میں اسے دوں؟کون ہے جو مجھ سے مغفرت طلب کرتا ہے کہ میں اسے معاف کروں؟وہ یہی اعلان فرماتا رہتا ہے حتیٰ کہ صبح چمک اٹھتی ہے۔\""}],[1715,"ابو بن سلمہ عبدالرحمان نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے حدیث بیا ن کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب رات کا آدھا یا دو تہائی حصہ گزر جاتا ہے توا للہ تبارک وتعا لیٰ آسمان دنیا پر نزول فرماتا ہے اور کہتا ہے : کیا کوئی مانگنے والا ہے کہ اسے دیاجائے؟کیا کوئی د عا کرنے والا ہے کہ اس کی دعا قبول کی جائے؟کیا کوئی بخشش کا طلبگار ہے کہ اسے بخشا جائے حتیٰ کہ صبح پھوٹ پڑتی ہے ۔","",{"u2":"ابو بن سلمہ عبدالرحمان نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے حدیث بیا ن کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جب رات کا آدھا یا دو تہائی حصہ گزر جاتا ہے توا للہ تبارک وتعا لیٰ آسمان دنیا پر نزول فرماتا ہے اور کہتا ہے:کیا کوئی مانگنے والا ہے کہ اسے دیاجائے؟کیا کوئی د عا کرنے والا ہے کہ اس کی دعا قبول کیجائے؟کیاکوئی بخشش کا طلبگار ہے کہ اسے بخشا جائے حتیٰ کہ صبح پھوٹ پڑتی ہے۔\""}],[1716,"محاضر ابومورع نے کہا : ہم سے سعد بن سعید ( بن قیس انصاری ) نے حدیث بیان کی ، انھوں نے کہا : مجھے ابن مرجانہ نے خبر دی ، انوں نے کہا میں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے سنا وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" آدھی رات یا رات کی آخری تہائی کے وقت اللہ تعالیٰ آسمان دنیا پر نزول فرماتا ہے اور کہتا ہے : کون مجھ سے دعا کرے گا کہ میں اس کی دعا قبول کروں ۔ یا مجھ سے سوال کرے میں اسے عطا کرو؟پھر فرماتا ہے : کون اس ( ذات ) کو قرض دےگا جو نہ محتاج ہے اور نہ حق مارنے والی ہے ( اللہ تعالیٰ کو ) ؟ \"\" امام مسلمؒ نے کہا : ابن مرجانہ سے مراد سعید بن عبداللہ ( ابو العثمان المدنی ) ہیں اور مرجانہ ان کی والدہ ہیں ۔","",{"u2":"محاضر ابومورع نے کہا:ہم سے سعد بن سعید(بن قیس انصاری) نے حدیث بیان کی،انھوں نے کہا:مجھے ابن مرجانہ نے خبر دی،انوں نے کہامیں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے سنا وہ کہہ رہے تھے:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"آدھی رات یا رات کی آخری تہائی کے وقت اللہ تعالیٰ آسمان دنیا پر نزول فرماتا ہے اور کہتا ہے:کون مجھ سے دعا کرے گا کہ میں اس کی دعا قبول کروں۔یامجھ سے سوال کرے میں اسے عطا کرو؟پھر فرماتا ہے:کون اس (ذات) کو قرض دےگا جو نہ محتاج ہے اور نہ حق مارنے والی ہے(اللہ تعالیٰ کو)؟\"\nامام مسلم رحمہ اللہ نے کہا:ابن مرجانہ سے مراد سعید بن عبداللہ(ابو العثمان المدنی) ہیں اور مرجانہ ان کی والدہ ہیں۔"}],[1717,"محاضر ابومورع نے کہا : ہم سے سعد بن سعید ( بن قیس انصاری ) نے حدیث بیان کی ، انھوں نے کہا : مجھے ابن مرجانہ نے خبر دی ، انوں نے کہا میں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے سنا وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" آدھی رات یا رات کی آخری تہائی کے وقت اللہ تعالیٰ آسمان دنیا پر نزول فرماتا ہے اور کہتا ہے : کون مجھ سے دعا کرے گا کہ میں اس کی دعا قبول کروں ۔ یا مجھ سے سوال کرے میں اسے عطا کرو؟پھر فرماتا ہے : کون اس ( ذات ) کو قرض دےگا جو نہ محتاج ہے اور نہ حق مارنے والی ہے ( اللہ تعالیٰ کو ) ؟ \"\" امام مسلمؒ نے کہا : ابن مرجانہ سے مراد سعید بن عبداللہ ( ابو العثمان المدنی ) ہیں اور مرجانہ ان کی والدہ ہیں ۔","",{"u2":"سلیمان بن بلال نے سعد بن سعید سے اسی سند کے ساتھ روایت کی اور اس میں یہ اضافہ ہے:\" پھراللہ تعالیٰ اپنے دونوں ہاتھ پھیلاتا ہے اور فرماتا ہے۔:کون اسکو قرض دے گا جو نہ محتاج ہے اور نہ ہی ظالم۔\""}],[1718,"سلیمان بن بلال نے سعد بن سعید سے اسی سند کے ساتھ روایت کی اور اس میں یہ اضافہ ہے : \" پھر اللہ تعالیٰ اپنے دونوں ہاتھ پھیلاتا ہے اور فرماتا ہے ۔ : کون اسکو قرض دے گا جو نہ محتاج ہے اور نہ ہی ظالم ۔","",{"u2":"منصور نے ابو اسحاق سے اور انھوں نے اغر ابو مسلم سے روایت کی،وہ حضرت ابو سعید اور حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کرتے ہیں۔دونوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اللہ تعالیٰ (بندوں کو آرام کی) مہلت دیتاہے حتیٰ کہ جب رات کا پہلا تہائی حصہ گزر جاتاہے تو وہ آسمان دنیا پر نزول فرماتا ہے اور کہتا ہے:کیا کوئی مغفرت کا طلب گار ہے؟کیا کوئی توبہ کرنے والا ہے؟کیاکوئی مانگنے والاہے؟کیاکوئی پکارنے والا ہے؟حتیٰ کہ فجر پھوٹ پڑتی ہے۔\""}],[1719,"منصور نے ابو اسحاق سے اور انھوں نے اغر ابو مسلم سے روایت کی ، وہ سیدنا ابو سعید اور سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کرتے ہیں ۔ دونوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالیٰ ( بندوں کو آرام کی ) مہلت دیتاہے حتیٰ کہ جب رات کا پہلا تہائی حصہ گزر جاتاہے تو وہ آسمان دنیا پر نزول فرماتا ہے اور کہتا ہے : کیا کوئی مغفرت کا طلب گار ہے؟کیا کوئی توبہ کرنے والا ہے؟کیا کوئی مانگنے والاہے؟کیا کوئی پکارنے والا ہے؟حتیٰ کہ فجر پھوٹ پڑتی ہے ۔","",{"u2":"شعبہ نے ابو اسحاق سے اسی سند کے ساتھ مذکورہ حدیث بیان کی،البتہ منصور کی روایت مکمل اور زیادہ (تفصیلات پر محیط)ہے۔"}],[1720,"حمید بن عبدالرحمان نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص کے ایمان ( کی حالت میں ) اور اجر طلب کرتے ہوئے رمضان کا قیام کیا اس کے گزشتہ تمام گناہ معاف کردیئے گئے ۔","",{"u2":"حمید بن عبدالرحمان نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ ر سول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جس شخص کے ایمان(کی حالت میں) اور اجر طلب کرتے ہوئے رمضان کا قیام کیا اس کے گزشتہ تمام گناہ معاف کردیئے گئے۔\""}],[1721,"امام زہری نے ابو سلمہ ( بن عبدالرحمان ) سے اور انھوں نے ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا رسول اللہ صلی اللہ علیہ وسلم لازم ٹھہرائے بغیر رمضان کے قیام کی ترغیب دیتے تھے ، آپ فرماتے : \" جس نے رمضان کا قیام ایمان ( کی حالت میں ) اور اجر طلب کرتے ہوئے کیا ، اس کے گزشتہ گناہ بخش دیئے جائیں گے ۔ \" رسول اللہ صلی اللہ علیہ وسلم کی وفات تک معاملہ یہی رہا ، پھر ابو بکر رضی اللہ تعالیٰ عنہ کی خلافت اور عمر رضی اللہ تعالیٰ عنہ کی خلافت کے ابتدائی دور میں بھی معاملہ اسی طرح رہا ( ترغیب دی جاتی رہی ، اجتماعی طور پر اہتمام نہیں کیاگیا)","",{"u2":"امام زہری نے ابو سلمہ(بن عبدالرحمان) سے اور انھوں نے ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا رسول اللہ صلی اللہ علیہ وسلم لازم ٹھہرائے بغیر رمضان کے قیام کی ترغیب دیتے تھے،آپ فرماتے:\"جس نے رمضان کا قیام ایمان (کی حالت میں)اوراجر طلب کرتے ہوئے کیا،اس کے گزشتہ گناہ بخش دیئے جائیں گے۔\"رسول اللہ صلی اللہ علیہ وسلم کی وفات تک معاملہ یہی رہا،پھر ابو بکر رضی اللہ تعالیٰ عنہ کی خلافت اور عمر رضی اللہ تعالیٰ عنہ کی خلافت کے ابتدائی دور میں بھی معاملہ اسی طرح رہا(ترغیب دی جاتی رہی،اجتماعی طور پر اہتمام نہیں کیاگیا)-"}],[1722,"حییٰ بن ابی کثیر نے کہا : ہمیں سلمہ بن عبدالرحمان نے حدیث بیان کی ۔ کہ سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انھیں حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس نے رمضان کے روزے ایمان ( کی حالت میں ) اور ثواب کے لئے رکھے ، اس کے گزشتہ سب گناہ معاف کردیئے جائیں گے اور جس نے لیلۃ القدر کا قیام ایمان کے ساتھ اور ثواب کے لئے کیا تو اس کے گزشتہ سارے گناہ معاف کردیئے جائیں گے ۔","",{"u2":"حییٰ بن ابی کثیر نے کہا:ہمیں سلمہ بن عبدالرحمان نے حدیث بیان کی۔کہ حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انھیں حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جس نے رمضان کے روزے ایمان(کی حالت میں) اور ثواب کے لئے رکھے،اس کے گزشتہ سب گناہ معاف کردیئے جائیں گے اور جس نے لیلۃ القدر کا قیام ایمان کے ساتھ اور ثواب کے لئے کیا تو اس کے گزشتہ سارے گناہ معاف کردیئے جائیں گے۔"}],[1723,"اعرج نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور ا نھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص لیلۃ القدر کا قیام کرے گا اور اس کو پالے گا ۔ میرا خیال ہے آپ نے فرمایا ۔ ایمان کے عالم میں اور احتساب کے لئے ، اسے بخش دیا جائے گا ۔","",{"u2":"اعرج نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور ا نھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی،آپ صلی اللہ علیہ وسلم نے فرمایا:\"جو شخص لیلۃ القدر کا قیام کرے گا اور اس کو پالے گا۔میرا خیال ہے آپ نے فرمایا۔ایمان کے عالم میں اور احتساب کے لئے،اسے بخش دیا جائے گا۔\""}],[1724,"امام مالکؒ نے ابن شہاب سے روایت کی ، انھوں نے عروہ سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک رات مسجد میں نماز پڑھی تو کچھ اور لوگوں نے ( بھی ) آپ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی ، پھر آپ نے اس سے اگلی ر ات نماز پڑھی تو لوگوں ( کی تعداد ) میں اضافہ ہوگیا ، پھر تیسری یا چوتھی رات لوگ جمع ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نکل کر ان کے پاس تشریف نہ لائے ۔ جب صبح ہوئی تو آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" جو تم نے کیا میں نے دیکھا ، مجھے تمہارے پاس آنے سے اس کے سوا کسی چیز نے نہیں روکا کہ مجھے ڈر ہوا کہ کہیں یہ ( نماز ) تم پر فرض نہ ہوجائے ۔ \"\" ( عروہ یا ان کے بعد کے کسی راوی نے ) کہا : اور یہ رمضان میں ہوا ۔","",{"u2":"امام مالک رحمہ اللہ نے ابن شہاب سے روایت کی،انھوں نے عروہ سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک رات مسجد میں نماز پڑھی تو کچھ اور لوگوں نے(بھی) آپ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی،پھر آپ نے اس سے اگلی ر ات نماز پڑھی تو لوگوں (کی تعداد)میں اضافہ ہوگیا،پھر تیسری یا چوتھی رات لوگ جمع ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نکل کر ان کے پاس تشریف نہ لائے۔جب صبح ہوئی تو آپ صلی اللہ علیہ وسلم نے فرمایا:\"جو تم نے کیا میں نے دیکھا،مجھے تمہارے پاس آنے سے اس کے سوا کسی چیز نے نہیں روکا کہ مجھے ڈر ہوا کہ کہیں یہ(نماز) تم پر فرض نہ ہوجائے۔\"\n(عروہ یا ان کے بعد کے کسی راوی نے)کہا: اور یہ رمضان میں ہوا۔"}],[1725,"یونس بن یزید نے ابن شہاب سے خبر دی ، انھوں نے کہا : مجھے عروہ بن زبیر نے بتایا کہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم رات کے وسط میں ( گھر سے ) نکلے اور مسجد میں نماز پڑھی ، کچھ لوگوں نے ( بھی ) آپ کی نماز کے ساتھ نماز ادا کی ، صبح کو لوگوں نے اس بارے میں بات چیت کی ، چنانچہ ( دوسری رات ) لوگ پہلے سے زیادہ جمع ہوگئے ، رسول اللہ صلی اللہ علیہ وسلم د وسری رات بھی باہر تشریف لائے اور لوگوں نے آپ کی نماز کے ساتھ ( اقتداء میں ) نماز پڑھی ، صبح اس کا تذکرہ کرتے رہے ، تیسری رات مسجد میں آنے والے اور زیادہ ہوگئے آپ باہر تشریف لائے اور لوگوں نے آپ کی نماز کے ساتھ نماز پڑھی ، جب چوتھی رات ہوئی تو مسجد نمازیوں کے لئے تنگ ہوگئی ، اور رسول اللہ صلی اللہ علیہ وسلم نکل کر ان کے پاس تشریف نہ لائے حتیٰ کہ آپ صبح کی نماز کے لئے تشریف لائے ۔ جب صبح کی نماز پوری کرلی تو لوگوں کی طرف متوجہ ہوئے ، پھر شہادتین پڑھ کر ( یہ خطبے کا حصہ ہیں ) فرمایا : \" اما بعد! واقعہ یہ ہے کہ آج رات تمہارا حال مجھ سے مخفی نہ تھا لیکن مجھے خدشہ ہوا کہ رات کی نماز تم پر فرض نہ کردی جائے پر تم اس ( کی ادائیگی ) سے عاجز رہو ۔","",{"u2":"یونس بن یزید نے ابن شہاب سے خبر دی،انھوں نے کہا:مجھے عروہ بن زبیر نے بتایا کہ حضرت عائشہ رضی اللہ تعالیٰ عنہا نے انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم رات کے وسط میں(گھر سے) نکلے اور مسجد میں نماز پڑھی،کچھ لوگوں نے(بھی) آپ کی نماز کے ساتھ نماز ادا کی،صبح کو لوگوں نے اس بارے میں بات چیت کی،چنانچہ(دوسری رات)لوگ پہلے سے زیادہ جمع ہوگئے،رسول اللہ صلی اللہ علیہ وسلم د وسری رات بھی باہر تشریف لائے اور لوگوں نے آپ کی نماز کے ساتھ(اقتداء میں) نماز پڑھی،صبح اس کا تذکرہ کرتے رہے،تیسری رات مسجد میں آنے والے اور زیادہ ہوگئے آپ باہر تشریف لائے اور لوگوں نے آپ کی نماز کے ساتھ نماز پڑھی،جب چوتھی رات ہوئی تو مسجد نمازیوں کے لئے تنگ ہوگئی،اور رسول اللہ صلی اللہ علیہ وسلم نکل کر ان کے پاس تشریف نہ لائے حتیٰ کہ آپ صبح کی نماز کے لئے تشریف لائے۔جب صبح کی نماز پوری کرلی تو لوگوں کی طرف متوجہ ہوئے،پھر شہادتین پڑھ کر(یہ خطبے کا حصہ ہیں)فرمایا:\"اما بعد! واقعہ یہ ہے کہ آج رات تمہارا حال مجھ سے مخفی نہ تھا لیکن مجھے خدشہ ہوا کہ رات کی نماز تم پر فرض نہ کردی جائے پر تم اس(کی ادائیگی) سے عاجز رہو۔\""}],[1726,"اوزاعی نے کہا : مجھ سے عبدہ ( بن ابی لبابہ ) نے زر ( بن جیش ) سے حدیث بیان کی ، انھوں نے کہا : میں نے ابی ابن کعب رضی اللہ تعالیٰ عنہ سے سنا ، وہ کہہ رہے تھے جب کہ ان سے کہاگیا کہ سیدنا عبداللہ بن مسعود کہتے ہیں : جس نے سال بھر قیام کیا اس نے شب قدر کو پالیا تو ابی رضی اللہ تعالیٰ عنہ نے کہا : اس اللہ کی قسم جس کے سوا کوئی معبود نہیں!وہ رات ر مضان میں ہے ۔ ۔ ۔ وہ بغیر کسی استثناء کے حلف اٹھاتے تھے ۔ ۔ ۔ اور اللہ کی قسم! میں خوب جانتا ہوں کہ وہ رات کون سی ہے ، یہ وہی رات ہے جس میں قیام کا ہمیں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا تھا ، یہ ستائیسویں صبح کی رات ہے اور ا س کی علامت یہ ہے کہ اس دن کی صبح کو سورج سفید طلوع ہوتا ہے ، اس کی کوئی شعاع نہیں ہوتی ۔","",{"u2":"اوزاعی نے کہا:مجھ سے عبدہ(بن ابی لبابہ) نے زر (بن جیش) سے حدیث بیان کی،انھوں نے کہا:میں نے ابی ابن کعب رضی اللہ تعالیٰ عنہ سے سنا،وہ کہہ رہے تھے جب کہ ان سے کہاگیا کہ حضرت عبداللہ بن مسعود کہتے ہیں:جس نے سال بھر قیام کیا اس نے شب قدر کو پالیا تو ابی رضی اللہ تعالیٰ عنہ نے کہا:اس اللہ کی قسم جس کے سوا کوئی معبود نہیں!وہ رات ر مضان میں ہے۔۔۔وہ بغیر کسی استثناء کے حلف اٹھاتے تھے۔۔۔اور اللہ کی قسم! میں خوب جانتا ہوں کہ وہ رات کون سی ہے،یہ وہی رات ہے جس میں قیام کا ہمیں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا تھا،یہ ستائیسویں صبح کی رات ہے اور ا س کی علامت یہ ہے کہ اس دن کی صبح کو سورج سفید طلوع ہوتا ہے،اس کی کوئی شعاع نہیں ہوتی۔"}],[1727,"محمد بن جعفر نے کہا : ہم سے شعبہ نے حدیث بیان کی ، انھوں نے کہا : میں نے عبدہ بن ابی لبابہ کو زرین حبیش سے حدیث بیان کرتے ہوئے سنا ، انھوں نے سیدنا ابی بن کعب رضی اللہ تعالیٰ عنہ سے روایت کی ، ( زرنے ) کہا : سیدنا ابی ابن کعب رضی اللہ تعالیٰ عنہ نے لیلۃ القدر کے بارے میں کہا : اللہ کی قسم!میں اس کے بارے میں جانتا ہوں اور میرا غالب گمان ہے کہ یہ وہی رات ہے جس کے قیام کا ہمیں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا تھا ، یہ ستائیسویں رات ہے ۔ شعبہ نے \"\" یہ وہی رات ہے جس کے قیام کا ہمیں رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا تھا \"\" فقرے کے بارے میں شک کیا ، انھوں نے کہا : مجھے یہ روایت میرے ساتھی نے ان ( عبدہ بن ابی لبابہ کے حوالے ) سے سنائی تھی ۔","",{"u2":"محمد بن جعفر نے کہا:ہم سے شعبہ نے حدیث بیان کی،انھوں نے کہا:میں نے عبدہ بن ابی لبابہ کو زرین حبیش سے حدیث بیان کرتے ہوئے سنا،انھوں نے حضرت ابی بن کعب رضی اللہ تعالیٰ عنہ سے روایت کی،(زرنے) کہا:حضرت ابی ابن کعب رضی اللہ تعالیٰ عنہ نے لیلۃ القدر کے بارے میں کہا:اللہ کی قسم!میں اس کے بارے میں جانتا ہوں اور میرا غالب گمان ہے کہ یہ وہی رات ہے جس کے قیام کا ہمیں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا تھا،یہ ستائیسویں رات ہے۔\nشعبہ نے\"یہ وہی رات ہے جس کے قیام کا ہمیں رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا تھا\"فقرے کے بارے میں شک کیا،انھوں نے کہا:مجھے یہ روایت میرے ساتھی نے ان (عبدہ بن ابی لبابہ کے حوالے) سے سنائی تھی۔"}],[1728,"۔ ( عبیداللہ کے والد ) معاذ نے کہا : ہم سے شعبہ نے اسی سند کے ساتھ سابقہ روایت کی مانند حدیث بیان کی لیکن اس میں انما شك شعبة ( شعبہ نے اس کے بارے میں شک کیا ) اور اس کے بعد کی عبارت بیان نہیں کی ۔","",{"u2":"۔(عبیداللہ کے والد) معاذ نے کہا:ہم سے شعبہ نے اسی سند کے ساتھ سابقہ روایت کی مانند حدیث بیان کی لیکن اس میں انما شک شعبۃ(شعبہ نے اس کے بارے میں شک کیا)اور اس کے بعد کی عبارت بیان نہیں کی۔"}],[1729,"سلمہ بن کہیل نے کریب سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں نے ایک رات اپنی خالہ سیدہ میمونہ رضی اللہ تعالیٰ عنہا کے ہاں گزاری ، نبی اکرم صلی اللہ علیہ وسلم رات کو اٹھے اور اپنی ضرورت ( کی جگہ ) آئے ، پھر اپنا چہرہ اور دونوں ہاتھ دھوئے ، پھر سو گئے پھر اٹھے اور مشکیزے کے پاس آئے اور اس کا بندھن کھولا ، پھر دو ( طرح کے ) وضو ( بہت ہلکا وضو اور بہت زیادہ وضو ) کے درمیان کا وضو کیا اور ( پانی ) زیادہ ( استعمال ) نہیں کیا اور ( وضو ) اچھی طرح کیا ، پھر اٹھے اور نماز شروع کی تو میں اٹھا اور میں نے انگڑائی لی ، اس ڈر سے کہ آپ یہ نہ سمجھیں کہ میں آپ ( کے حالات جاننے ) کی خاطر جاگ رہا تھا ، پھر میں نے وضو کیا ، پھر آپ صلی اللہ علیہ وسلم کھڑے ہوئے اور نماز پڑھی ۔ تو میں آپ کی دائیں جانب کھڑا ہوگیا ، آپ نے میرا ہاتھ پکڑا اور مجھے گھما کر اپنی دائیں جانب ( کھڑا ) کرلیا ۔ رسول اللہ صلی اللہ علیہ وسلم کی تیرہ رکعت رات کی نماز مکمل ہوئی ، پھر آپ لیٹ گئے اور سو گئے حتیٰ کہ آپ کی سانس لینے کی آواز آنے لگی ، آپ جب سوتے تھے تو آواز آتی تھی ۔ ، پھر آپ صلی اللہ علیہ وسلم کے پاس سیدنا بلال رضی اللہ تعالیٰ عنہ آئے ، اور آپ صلی اللہ علیہ وسلم کو نماز کی اطلاع دی ، آپ نے نماز پڑھی ( سنت فجر ادا کیں ) اور وضو نہ کیا اور آپ کی دعا میں تھا : \"\" اے للہ! میرے دل میں نور ڈال دے اور میری آنکھوں میں اور میرے کانوں میں نور بھردے اور میری دائیں طرف نور کردے اور میری بائیں طرف نور کردے اور میرے نیچے نور کردے اور میرے آگے اور میرے پیچھے نور کردے اور میرے لئے نور کو عظیم کردے ۔ \"\" ( ابن عباس رضی اللہ تعالیٰ عنہ کے شاگرد ) کریب نے بتایا کہ ( ان کے علاوہ مزید ) سات ( چیزوں کے بارے میں دعا مانگی جن ) کا تعلق جسم کے صندوق ( پسلیوں اور اردگرد کے حصے ) سے ہے ، میر ی ملاقات سیدنا عباس رضی اللہ تعالیٰ عنہ کے بیٹے سے ہوئی تو انھوں نے مجھے ان کے بارے میں بتایا ، انھوں نے بتایا کہ میرے پٹھوں ، میرے گوشت ، میرے خون ، میرے بالوں اور میری کھال ( کو نور کردے ) ، دو اور بھی چیزیں بتائیں ۔","",{"u2":"سلمہ بن کہیل نے کریب سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا: میں نے ایک رات اپنی خالہ حضرت میمونہ رضی اللہ تعالیٰ عنہا کے ہاں گزاری،نبی اکرم صلی اللہ علیہ وسلم رات کو اٹھے اور اپنی ضرورت(کی جگہ) آئے،پھر اپنا چہرہ اور دونوں ہاتھ دھوئے،پھر سو گئے پھر اٹھے اور مشکیزے کے پاس آئے اور اس کا بندھن کھولا،پھر دو(طرح کے) وضو(بہت ہلکا وضو اور بہت زیادہ وضو) کے درمیان کا وضو کیا اور (پانی) زیادہ(استعمال) نہیں کیا اور (وضو) اچھی طرح کیا،پھر اٹھے اور نماز شروع کی تو میں اٹھا اور میں نے انگڑائی لی،اس ڈر سے کہ آپ یہ نہ سمجھیں کہ میں آپ(کے حالات جاننے) کی خاطر جاگ رہا تھا،پھر میں نے وضو کیا،پھر آپ صلی اللہ علیہ وسلم کھڑے ہوئے اور نماز پڑھی۔تو میں آپ کی دائیں جانب کھڑا ہوگیا،آپ نے میرا ہاتھ پکڑا اور مجھے گھما کر اپنی دائیں جانب(کھڑا) کرلیا۔رسول اللہ صلی اللہ علیہ وسلم کی تیرہ رکعت رات کی نماز مکمل ہوئی،پھر آپ لیٹ گئے اور سو گئے حتیٰ کہ آپ کی سانس لینے کی آواز آنے لگی،آپ جب سوتے تھے تو آواز آتی تھی۔،پھر آپ صلی اللہ علیہ وسلم کے پاس حضرت بلال رضی اللہ تعالیٰ عنہ آئے،اور آپ صلی اللہ علیہ وسلم کو نماز کی اطلاع دی،آپ نے نماز پڑھی(سنت فجر ادا کیں)اور وضو نہ کیا اور آپ کی دعا میں تھا:\"اےللہ! میرے دل میں نور ڈال دے اور میری آنکھوں میں اور میرے کانوں میں نور بھردے اورمیری دائیں طرف نور کردے اور میری بائیں طرف نور کردے اور میرے نیچے نور کردے اور میرے آگے اور میرے پیچھے نور کردے اور میرے لئے نور کو عظیم کردے۔\"\n(ابن عباس رضی اللہ تعالیٰ عنہ کے شاگرد) کریب نے بتایا کہ(ان کے علاوہ مزید) سات(چیزوں کے بارے میں دعا مانگی جن) کا تعلق جسم کے صندوق(پسلیوں اور اردگرد کے حصے) سے ہے،میر ی ملاقات حضرت عباس رضی اللہ تعالیٰ عنہ کے بیٹے سے ہوئی تو انھوں نے مجھے ان کے بارے میں بتایا،انھوں نے بتایا کہ میرے پٹھوں،میرے گوشت،میرےخون،میرے بالوں اور میری کھال(کو نور کردے)،دو اور بھی چیزیں بتائیں۔"}],[1730,"امام مالک نے مخرمہ بن سلیمان سے اور انھوں نے ابن عباس رضی اللہ تعالیٰ عنہ کے مولیٰ کریب سے روایت کی کہ سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے انھیں بتایا کہ انھوں نے ایک رات ام المومنین میمونہ رضی اللہ تعالیٰ عنہا کے ہاں گزاری جو ان کی خالہ تھیں ، تو میں سرہانے ( بستر ) کے عرض میں لیٹا اور رسول اللہ صلی اللہ علیہ وسلم اور آپ کی اہلیہ اس ( بستر ) کے طول ( لمبائی ) میں لیٹے ، رسول اللہ صلی اللہ علیہ وسلم سو گئے یہاں تک کہ رات آدھی ہوئی ۔ یا اس سے تھوڑا پہلے یا تھوڑا بعد کا وقت ہوا تو رسول اللہ صلی اللہ علیہ وسلم بیدا ر ہوگئے اور اپنے ہاتھ کے ساتھ اپنے چہرے سے نیند زائل کرنے لگے ، ( چہرے پر ہاتھ پھیرا ) پھر آپ نے سورہ آل عمران کی آخری دس آیات تلاوت فرمائیں ، پھر آپ اٹھ کرایک لٹکے ہوے مشکیزے کے پاس گئے اور اس سے وضو کیا اور اچھی طرح وضو کیا ، پھر کھڑے ہوئے اور نماز پڑھنے لگے ۔ ابن عباس رضی اللہ تعالیٰ عنہ نے کہا : \"\" میں اٹھا اور میں نے بھی وہی کیا جو رسول اللہ صلی اللہ علیہ وسلم نے کیا تھا ۔ پھر جا کر آپ کے پہلو میں کھڑ ہوگیااس پر رسول اللہ صلی اللہ علیہ وسلم نے اپنا دائیاں ہاتھ میرے سر پر رکھا اور میرے دائیں کان کو پکڑ کر ( آہستہ سے ) مروڑنے لگے ۔ پھر آپ نے دو رکعت نماز پڑھی ۔ پھر دورکعتیں ، پھر دورکعتیں ، پھر دورکعتیں ، پھر دورکعتیں ، پھر دورکعتیں پڑھیں ۔ پھر وتر پڑھا ، پھر آپ لیٹ گئے حتیٰ کہ موذن آپ کے پاس آیا تو آ پ کھڑے ہوئے اور دو ہلکی رکعتیں پڑھیں ، پھر تشریف لئے گئے اور صبح کی نماز ادا کی ۔","",{"u2":"امام مالک نے مخرمہ بن سلیمان سے اور انھوں نے ابن عباس رضی اللہ تعالیٰ عنہ کے مولیٰ کریب سے روایت کی کہ حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے انھیں بتایا کہ انھوں نے ایک رات ام المومنین میمونہ رضی اللہ تعالیٰ عنہا کے ہاں گزاری جو ان کی خالہ تھیں،تو میں سرہانے(بستر) کے عرض میں لیٹا اور رسول اللہ صلی اللہ علیہ وسلم اور آپ کی اہلیہ اس(بستر) کے طول(لمبائی) میں لیٹے،رسول اللہ صلی اللہ علیہ وسلم سو گئے یہاں تک کہ رات آدھی ہوئی۔یا اس سے تھوڑا پہلے یا تھوڑا بعد کا وقت ہوا تو رسول اللہ صلی اللہ علیہ وسلم بیدا ر ہوگئے اور اپنے ہاتھ کے ساتھ اپنے چہرے سے نیند زائل کرنے لگے،(چہرے پر ہاتھ پھیرا) پھر آپ نے سورہ آل عمران کی آخری دس آیات تلاوت فرمائیں،پھر آپ اٹھ کرایک لٹکے ہوے مشکیزے کے پاس گئے اور اس سے وضو کیا اور اچھی طرح وضو کیا،پھر کھڑے ہوئے اور نماز پڑھنے لگے۔\nابن عباس رضی اللہ تعالیٰ عنہ نے کہا:\"میں اٹھا اور میں نے بھی وہی کیا جو رسول اللہ صلی اللہ علیہ وسلم نے کیاتھا۔پھر جا کر آپ کے پہلو میں کھڑ ہوگیااس پررسول اللہ صلی اللہ علیہ وسلم نے اپنا دائیاں ہاتھ میرے سر پر رکھا اور میرے دائیں کان کو پکڑ کر(آہستہ سے) مروڑنے لگے۔پھر آپ نے دو رکعت نماز پڑھی۔پھر دورکعتیں، پھر دورکعتیں، پھر دورکعتیں، پھر دورکعتیں، پھر دورکعتیں پڑھیں۔پھر وتر پڑھا،پھر آپ لیٹ گئے حتیٰ کہ موذن آپ کے پاس آیا تو آ پ کھڑے ہوئے اور دو ہلکی رکعتیں پڑھیں،پھر تشریف لئے گئے اور صبح کی نماز ادا کی۔"}],[1731,"عیاض بن عبداللہ فہری نے مخرمہ بن سلیمان سے اسی سند کے ساتھ یہی روایت بیان کی اور یہ اضافہ کیا : پھر آپ نے پانی کے ایک پرانے مشکیزے کا رخ کیا ، پھر مسواک کی اور وضو کیا اور اچھی طرح وضو کیا ، لیکن پانی بہت ہی کم بہایا ، پھر مجھے ہلایا اور میں کھڑا ہوگیا ۔ ۔ ۔ باقی ساری حدیث مالک کی حدیث کی طرح ہے ۔","",{"u2":"عیاض بن عبداللہ فہری نے مخرمہ بن سلیمان سے اسی سند کے ساتھ یہی روایت بیان کی اور یہ اضافہ کیا:پھر آپ نے پانی کے ایک پرانے مشکیزے کا رخ کیا،پھر مسواک کی اور وضو کیا اور اچھی طرح وضو کیا،لیکن پانی بہت ہی کم بہایا،پھر مجھے ہلایا اور میں کھڑا ہوگیا۔۔۔باقی ساری حدیث مالک کی حدیث کی طرح ہے۔"}],[1732,"عمرو نے عبدربہ بن سعید سے ، انھوں نے مخرمہ بن سلیمان سے ، انھوں نے ابن عباس رضی اللہ تعالیٰ عنہ کے مولیٰ کریب سے اور انھوں نےسیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے کہا : میں نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہ رضی اللہ تعالیٰ عنہا کے ہاں سویا اور اس رات رسول اللہ صلی اللہ علیہ وسلم انھیں کے پاس تھے ۔ رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا ، پھر کھڑے ہوئے اور نماز پڑھنے لگے ، میں آپ کی بائیں طرف کھڑا ہوگیا تو آپ نے مجھے پکڑ کر اپنی دائیں جانب کرلیا ۔ اس رات آپ نے تیرہ رکعتیں پڑھیں ۔ پھر رسول اللہ صلی اللہ علیہ وسلم سو گئے حتیٰ کہ آپ ( کے سانسوں ) کی آواز آنے لگی ، جب آپ سوتے تو سانس لینے کی آواز آتی تھی ۔ پھر آپ کے پاس موذن آیا تو آپ باہر تشریف لے گئے اور نماز ادا کی ، آپ نے ( ازسرنو ) وضو نہیں کیا ۔ عمرو نے کہا میں نے یہ حدیث بکیر بن اشج کو سنائی تو انھوں نے کہا : کریب نے مجھے یہی حدیث سنائی تھی ۔","",{"u2":"عمرو نے عبدربہ بن سعید سے،انھوں نے مخرمہ بن سلیمان سے،انھوں نے ابن عباس رضی اللہ تعالیٰ عنہ کے مولیٰ کریب سے اور انھوں نےحضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے کہا:میں نبی اکرم صلی اللہ علیہ وسلم کی زوجہ حضرت میمونہ رضی اللہ تعالیٰ عنہا کے ہاں سویا اور اس رات رسول اللہ صلی اللہ علیہ وسلم انھیں کے پاس تھے۔رسول اللہ صلی اللہ علیہ وسلم نے وضو کیا،پھر کھڑے ہوئے اور نماز پڑھنے لگے،میں آپ کی بائیں طرف کھڑا ہوگیا تو آپ نے مجھے پکڑ کر اپنی دائیں جانب کرلیا۔اس رات آپ نے تیرہ رکعتیں پڑھیں۔ پھر رسول اللہ صلی اللہ علیہ وسلم سو گئے حتیٰ کہ آپ(کے سانسوں) کی آواز آنے لگی،جب آپ سوتے تو سانس لینے کی آوازآتی تھی۔پھر آپ کے پاس موذن آیا تو آپ باہر تشریف لے گئے اور نماز ادا کی،آپ نے(ازسرنو) وضو نہیں کیا۔\nعمرو نے کہا میں نے یہ حدیث بکیر بن اشج کو سنائی تو انھوں نے کہا:کریب نے مجھے یہی حدیث سنائی تھی۔"}],[1733,"ضحاک نے مخرمہ بن سلیمان سے ، انھوں نے کریب مولیٰ ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں نے ایک رات اپنی خالہ میمونہ بنت حارث رضی اللہ تعالیٰ عنہا کے ہاں بسر کی ، میں نے ان سے عرض کی ۔ جب رسول اللہ صلی اللہ علیہ وسلم اٹھیں تو آ پ مجھے بھی بیدار کردیں ۔ رسول اللہ صلی اللہ علیہ وسلم نماز کے لئے کھڑے ہوئے تو میں آپ کی بائیں جانب کھڑا ہوگیا ۔ آپ نے میرا ہاتھ پکڑا اور مجھے اپنی دائیں طرف میں کردیا ، جب مجھے جھپکی آنے لگتی تو آپ میرے کان کی لو پکڑ لیتے ، آپ نے گیارہ رکعتیں پڑھیں ، پھر آپ نے کمر اور پنڈلیوں کے گرد کپڑا لپیٹ کر اسے سہارا بنا لیا ( اور سوگئے ) یہاں تک کہ میں آپ کے سونے کی حالت میں آپ کے سانس لینے کی آوازسن رہاتھا ۔ تو جب آپ کے سامنے صبح ظاہر ہوئی تو آپ نے ہلکی دو رکعتیں پڑھیں ۔","",{"u2":"ضحاک نے مخرمہ بن سلیمان سے،انھوں نے کریب مولیٰ ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:میں نے ایک رات اپنی خالہ میمونہ بنت حارث رضی اللہ تعالیٰ عنہا کے ہاں بسر کی،میں نے ان سے عرض کی۔جب رسول اللہ صلی اللہ علیہ وسلم اٹھیں تو آ پ مجھے بھی بیدار کردیں۔رسول اللہ صلی اللہ علیہ وسلم نماز کے لئے کھڑے ہوئے تو میں آپ کی بائیں جانب کھڑا ہوگیا۔آپ نے میرا ہاتھ پکڑا اور مجھے اپنی دائیں طرف میں کردیا،جب مجھے جھپکی آنے لگتی تو آپ میرے کان کی لو پکڑ لیتے،آپ نے گیارہ رکعتیں پڑھیں، پھر آپ نے کمر اور پنڈلیوں کے گرد کپڑا لپیٹ کر اسے سہارا بنا لیا(اور سوگئے) یہاں تک کہ میں آپ کے سونے کی حالت میں آپ کے سانس لینے کی آوازسن رہاتھا۔تو جب آپ کے سامنے صبح ظاہر ہوئی تو آپ نے ہلکی دو رکعتیں پڑھیں۔"}],[1734,"سفیان بن عمرو بن دینار سے ، انھوں نے کریب مولیٰ ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے اپنی خالہ میمونہ رضی اللہ تعالیٰ عنہا کے ہاں رات بسر کی ۔ رسول اللہ صلی اللہ علیہ وسلم را ت کے وقت اٹھے ، پھر آپ نے لٹکی ہوئی مشک سے ہلکا وضوکیا ( کریب نے ) کہا : انھوں ( ابن عباس رضی اللہ تعالیٰ عنہ ) نے آپ کے وضو کی کیفیت بیان کی اور وضو کو ہلکا اور کم کرتے رہے ، ابن عباس رضی اللہ تعالیٰ عنہ نے کہا : میں اٹھا اور وہی کیا جو نبی اکرم صلی اللہ علیہ وسلم نے کیا ۔ پھر آکر میں آپ صلی اللہ علیہ وسلم کی بائیں طرف کھڑا ہوگیا ، آپ نے مجھے اپنے پیچھے کیا ( اور گھما کر ) اپنی دائیں جانب کرلیا ۔ پھر آپ نے نماز پڑھی ۔ پھر لیٹ کر سوگئے حتیٰ کہ آوا ز سے سانس لینے لگے ۔ پھر بلال رضی اللہ تعالیٰ عنہ آئے اور آپ کو نماز کی اطلاع دی ، آپ باہر تشریف لے گئے اور صبح کی نماز ادا فرمائی اور ( نیا ) وضو نہ کیا ۔ سفیان نے کہا : یہ ( نیند کے باوجود وضو کی ضرورت نہ ہونا ) نبی اکرم صلی اللہ علیہ وسلم کا خاصہ تھا کیونکہ ہم تک یہ بات پہنچی ہے کہ آپ کی آنکھیں سوتی تھیں دل نہیں سوتاتھا ۔","",{"u2":"سفیان بن عمرو بن دینار سے،انھوں نے کریب مولیٰ ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے اپنی خالہ میمونہ رضی اللہ تعالیٰ عنہا کے ہاں رات بسر کی۔رسول اللہ صلی اللہ علیہ وسلم را ت کے وقت اٹھے،پھر آپ نے لٹکی ہوئی مشک سے ہلکا وضوکیا(کریب نے)کہا:انھوں(ابن عباس رضی اللہ تعالیٰ عنہ) نے آپ کے وضو کی کیفیت بیان کی اور وضو کو ہلکا اور کم کرتے رہے،ابن عباس رضی اللہ تعالیٰ عنہ نے کہا:میں اٹھا اور وہی کیا جو نبی اکرم صلی اللہ علیہ وسلم نے کیا۔پھر آکر میں آپ صلی اللہ علیہ وسلم کی بائیں طرف کھڑا ہوگیا،آپ نے مجھے اپنے پیچھے کیا(اور گھما کر)اپنی دائیں جانب کرلیا۔پھر آپ نے نماز پڑھی۔پھر لیٹ کر سوگئے حتیٰ کہ آوا ز سے سانس لینے لگے۔پھر بلال رضی اللہ تعالیٰ عنہ آئے اور آپ کو نماز کی اطلاع دی،آپ باہر تشریف لے گئے اور صبح کی نماز ادا فرمائی اور (نیا) وضو نہ کیا۔\nسفیان نے کہا:یہ (نیند کے باوجود وضو کی ضرورت نہ ہونا)نبی اکرم صلی اللہ علیہ وسلم کا خاصہ تھا کیونکہ ہم تک یہ بات پہنچی ہے کہ آپ کی آنکھیں سوتی تھیں دل نہیں سوتاتھا۔"}],[1735,"محمد بن جعفر ( غندر ) نے کہا : ہم سے شعبہ نے سلمہ سے حدیث بیان کی ، انھوں نے کریب سے اور ا نھوں نے ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں نے اپنی خالہ میمونہ کے ہاں رات گزاری ، میں نے ( وہاں رہ کر ) مشاہدہ کیا کے رسول اللہ صلی اللہ علیہ وسلم کیسے نماز پڑھتے ہیں ۔ کہا : آپ اٹھے ، پیشاب کیا ، پھر اپنا چہرہ اور ہتھیلیاں دھوئیں ۔ پھر سوگئے ۔ آپ ( کچھ دیر بعد ) پھر اٹھے ، مشکیزے کے پاس گئے اور اس کابندھن کھولا ، پھر لگن یا پیالے میں پانی انڈیلا اور اس کو اپنے ہاتھ سے جھکایا ، پھر دو وضووں کے درمیا کا خوبصورت وضو کیا ( وضو نہ بہت ہلکا کیا اور نہ اس میں مبالغہ کیا لیکن اچھی طرح کیا ) ، پھر اٹھ کر نماز پڑھنے لگے ، میں آپ کے پہلو میں کھٹرا ہوگیا ، آپ کی بائیں جانب کھٹرا ہوا ۔ کہا : تو آپ نے مجھے پکڑ کراپنی دائیں جانب کردیا ، اور رسول اللہ صلی اللہ علیہ وسلم کی تیرہ رکعت نماز مکمل ہوئی ، پھر آپ سوگئے حتیٰ کہ سانسوں کی آواز آنے لگی اور جب آپ سوجاتے تو ہم آپ کے سونے کوآپ کے سانس کی آواز سے پہچانتے ، پھر آپ نماز کے لئے باہر تشریف لائے اور نماز ادا کی ۔ اور آپ اپنی نماز یا اپنے سجدے میں یہ دعا مانگنے لگے : \" اے اللہ!میرے دل میں نور پیدا کر اور میرے کانوں میں نور پیدا کر اور میری آنکھوں میں نور پیدا کر اور میرے دائیں نور بنا اور میرے بائیں نور پیدا فرما اور میرے آگے اور میرے پیچھے نو ر کر اور میرے اوپر نور کر اور میرے لئے نور بنا ۔ ۔ ۔ یا فرمایا : \" مجھے نور بنا ۔ ۔ ۔","",{"u2":"محمد بن جعفر(غندر) نے کہا:ہم سے شعبہ نے سلمہ سے حدیث بیان کی،انھوں نے کریب سے اور ا نھوں نے ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:میں نے اپنی خالہ میمونہ کے ہاں رات گزاری،میں نے(وہاں رہ کر) مشاہدہ کیا کے رسول اللہ صلی اللہ علیہ وسلم کیسے نماز پڑھتے ہیں۔کہا:آپ اٹھے،پیشاب کیا،پھر اپنا چہرہ اور ہتھیلیاں دھوئیں۔پھر سوگئے۔آپ (کچھ دیر بعد) پھر اٹھے،مشکیزے کے پاس گئے اور اس کابندھن کھولا،پھر لگن یا پیالے میں پانی انڈیلا اور اس کو اپنے ہاتھ سے جھکایا،پھر دو وضووں کے درمیا کاخوبصورت وضو کیا(وضو نہ بہت ہلکا کیا اور نہ اس میں مبالغہ کیا لیکن اچھی طرح کیا)،پھر اٹھ کر نماز پڑھنے لگے،میں آپ کے پہلو میں کھٹرا ہوگیا،آپ کی بائیں جانب کھٹرا ہوا۔کہا:تو آپ نے مجھے پکڑ کراپنی دائیں جانب کردیا،اور رسول اللہ صلی اللہ علیہ وسلم کی تیرہ رکعت نماز مکمل ہوئی،پھر آپ سوگئے حتیٰ کہ سانسوں کی آواز آنے لگی اور جب آپ سوجاتے تو ہم آپ کے سونے کوآپ کے سانس کی آواز سے پہچانتے،پھر آپ نماز کے لئے باہر تشریف لائے اور نماز ادا کی۔اور آپ اپنی نماز یا اپنے سجدے میں یہ دعا مانگنے لگے:\"اے اللہ!میرے دل میں نور پیدا کر اور میرے کانوں میں نور پیدا کر اور میری آنکھوں میں نور پیدا کر اور میرے دائیں نور بنا اور میرے بائیں نور پیدا فرما اور میرے آگے اور میرے پیچھے نو ر کر اور میرے اوپر نور کر اور میرے لئے نور بنا۔۔۔یا فرمایا:\" مجھے نور بنا۔۔۔"}],[1736,"نضر بن شمیل نے کہا : ہمیں شعبہ نے خبر دی ، کہا : ہمیں سلمہ بن کبیل نے بکیر سے حدیث سنائی ، انھوں نے کریب سے اور انھوں نے سیدنا ابن عبا س رضی اللہ تعالیٰ عنہ سے روایت کی ۔ سلمہ نے کہا : میں کریب کو ملا تو انھوں نے کہا : سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے فرمایا : میں اپنی خالہ میمونہ کے ہاں تھا ، تو رسول اللہ صلی اللہ علیہ وسلم تشریف لائے ۔ ۔ ۔ پھر انھوں نے غندر ( محمد بن جعفر ) کی حدیث ( 1794 ) کی طرح بیان کیا اور کہا : \"\" اور مجھے سراپا نور کردے \"\" اور انھوں نے ( کسی بات میں ) شک کا اظہار نہ کیا ۔","",{"u2":"نضر بن شمیل نے کہا: ہمیں شعبہ نے خبر دی،کہا:ہمیں سلمہ بن کبیل نے بکیر سے حدیث سنائی،انھوں نے کریب سے اور انھوں نے حضرت ابن عبا س رضی اللہ تعالیٰ عنہ سے روایت کی۔\nسلمہ نے کہا: میں کریب کو ملا تو انھوں نے کہا:حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے فرمایا:میں اپنی خالہ میمونہ کے ہاں تھا،تو رسول اللہ صلی اللہ علیہ وسلم تشریف لائے۔۔۔پھر انھوں نے غندر(محمد بن جعفر) کی حدیث(1794) کی طرح بیان کیا اور کہا:\"اور مجھے سراپا نور کردے\"اور انھوں نے(کسی بات میں) شک کا اظہار نہ کیا۔"}],[1737,"۔ سعید بن مسروق نے سلمہ بن کہیل سے ، انھوں نے ابو رشدین ( کریب ) مولیٰ ابن عباس رضی اللہ تعالیٰ عنہ سے اور ا نھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں نے اپنی خالہ میمونہ رضی اللہ تعالیٰ عنہا کے ہاں رات گزاری ، پھر حدیث بیان کی لیکن اس میں چہرے اور ہتھیلیاں دھونے کاذکر نہیں ہے ، ہاں ، یہ کہا : پھر آپ مشک کے پاس آئے ، اس کا بندھن کھولا ، اور دو وضووں کے درمیان کا وضوکیا پھر بستر پر آئے اور سو گئے پھر آپ دوبارہ اٹھے اور مشک کے پاس آئے ، اس کابندھن کھولا ، پھر دوبارہ وضو کیاجو ( صحیح معنی میں ) وضو تھا اور کہا : \" میرا نور عظیم کردے \" اور یہ ہدایت نہیں کیا کہ مجھے سراپا نور کردے ۔","",{"u2":"۔ سعید بن مسروق نے سلمہ بن کہیل سے،انھوں نے ابو رشدین (کریب) مولیٰ ابن عباس رضی اللہ تعالیٰ عنہ سے اور ا نھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا: میں نے اپنی خالہ میمونہ رضی اللہ تعالیٰ عنہا کے ہاں رات گزاری،پھر حدیث بیان کی لیکن اس میں چہرے اور ہتھیلیاں دھونے کاذکر نہیں ہے،ہاں،یہ کہا:پھر آپ مشک کے پاس آئے،اس کا بندھن کھولا،اور دو وضووں کے درمیان کا وضوکیا پھر بستر پر آئے اور سو گئے پھر آپ دوبارہ اٹھے اورمشک کے پاس آئے،اس کابندھن کھولا،پھر دوبارہ وضو کیاجو(صحیح معنی میں) وضوتھا اور کہا:\"میرا نور عظیم کردے\"اور یہ ہدایت نہیں کیا کہ مجھے سراپا نور کردے۔"}],[1738,"عقیل بن خالد سے روایت ہے کہ سلمہ بن کہیل نے ان ( عقیل ) سے حدیث بیان کی کہ کریب نے ان ( سلمہ ) سے حدیث بیان کی کہ سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کے پاس گزاری ، انھوں ( ابن عباس رضی اللہ تعالیٰ عنہ ) نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم اٹھ کر مشکیزے کے پاس گئے اور اس میں سے پانی انڈیلا اور وضو کیا اور آپ نے نہ پانی زیادہ استعمال کیا نہ وضو میں کوئی کمی کی ۔ ۔ ۔ اور پوری حدیث بیا ن کی اور اس میں یہ بھی ہے کہ آپ نے اس رات انیس کلمات پر مشتمل دعا کی ۔ ( تمام الفاظ جمع کریں تو انیس بنتے ہیں ) سلمہ نے کہا : کریب نے وہ کلمات مجھے بتائے تھے اور میں ان میں سے بارہ کلمات کو یاد رکھ سکا اور باقی بھول گیا ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اے اللہ ! میرے دل میں نور پیدا فرما اور میری زبان میں نور پیدا فرما اور میرے کان میں نور پیدا فرما اور میری آنکھ میں نور پیدا فرما اور میرے اوپر نور کردے اور میرے نیچے نور کردے اور میرے دائیں نور کردے اور میرے بائیں نور کردے او ر میرے آگے نور کردے اور میرے پیچھے نور کردے اور میرے اندر نور کردے اور میرے نور کو عظیم کردے ۔","",{"u2":"عقیل بن خالد سے روایت ہے کہ سلمہ بن کہیل نے ان(عقیل) سے حدیث بیان کی کہ کریب نے ان(سلمہ) سے حدیث بیان کی کہ حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے ایک رات رسو ل اللہ صلی اللہ علیہ وسلم کے پاس گزاری،انھوں(ابن عباس رضی اللہ تعالیٰ عنہ)نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم اٹھ کر مشکیزے کے پاس گئے اور اس میں سے پانی انڈیلا اور وضو کیا اور آپ نے نہ پانی زیادہ استعمال کیا نہ وضو میں کوئی کمی کی۔۔۔اور پوری حدیث بیا ن کی اور اس میں یہ بھی ہے کہ آپ نے اس رات انیس کلمات پر مشتمل دعا کی۔(تمام الفاظ جمع کریں تو انیس بنتے ہیں)\nسلمہ نے کہا: کریب نے وہ کلمات مجھے بتائے تھے اور میں ان میں سے بارہ کلمات کو یاد رکھ سکا اور باقی بھول گیا،رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اے اللہ! میرے دل میں نور پیدا فرمااور میری زبان میں نور پیدا فرما اور میرے کان میں نور پیدا فرما اور میری آنکھ میں نور پیدا فرما اور میرے اوپر نور کردے اور میرے نیچے نور کردے اور میرے دائیں نور کردے اور میرے بائیں نور کردے او ر میرے آگے نور کردے اور میرے پیچھے نور کردے اور میرے اندر نور کردے اور میرے نور کو عظیم کردے۔\""}],[1739,"شریک بن ابی نمر نے کریب سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں ایک رات سیدہ میمونہ رضی اللہ تعالیٰ عنہا کے گھر سویا ، جبکہ نبی کریم صلی اللہ علیہ وسلم ان کے ہاں تھے تاکہ میں دیکھوں کہ رات کو رسول اللہ صلی اللہ علیہ وسلم کی نماز کی کیفیت کیا ہے ، رسول اللہ صلی اللہ علیہ وسلم نے کچھ وقت ا پنے گھر والوں کے ساتھ گفتگو فرمائی ، پھر آپ سوگئے ۔ ۔ ۔ آگے پوری حدیث بیان کی اور میں یہ بھی تھا کہ پھر آپ صلی اللہ علیہ وسلم اٹھے ، وضو کیا اور مسواک کیا ۔","",{"u2":"شریک بن ابی نمر نے کریب سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:میں ایک رات حضرت میمونہ رضی اللہ تعالیٰ عنہا کے گھر سویا،جبکہ نبی کریم صلی اللہ علیہ وسلم ان کے ہاں تھے تاکہ میں دیکھوں کہ رات کو رسول اللہ صلی اللہ علیہ وسلم کی نماز کی کیفیت کیا ہے،رسول اللہ صلی اللہ علیہ وسلم نے کچھ وقت ا پنے گھر والوں کے ساتھ گفتگو فرمائی،پھر آپ سوگئے۔۔۔آگے پوری حدیث بیان کی اور میں یہ بھی تھا کہ پھر آپ صلی اللہ علیہ وسلم اٹھے،وضو کیا اور مسواک کیا۔"}],[1740,"حبیب بن ابی ثابت نے محمد بن علی بن عبداللہ بن عباس رضی اللہ تعالیٰ عنہ سے ، انھوں نے اپنے والد سے ، انھوں نے سیدنا عبداللہ بن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ وہ ( ایک رات ) رسول اللہ صلی اللہ علیہ وسلم کے ہاں سوئے تو ( رات کو ) آپ صلی اللہ علیہ وسلم جاگے ، مسواک کی اور وضو فرمایا اور آپ ( اس وقت ) یہ آیا مبارکہ پڑھ رہے تھے : \" یقیناً آسمانوں اور زمین کی تخلیق میں اور دن رات کی آمد ورفت میں خالص عقل رکھنے والوں کے لئے نشانیاں ہیں ۔ \" یہ آیات تلاوت فرمائیں حتیٰ کہ سورت ختم کی ، پھر آپ صلی اللہ علیہ وسلم کھڑے ہوئے اور دو ر کعتیں پڑھیں ، ان میں بہت طویل قیام ، رکوع اور سجدے کیے ، پھر واپس پلٹے اور سوگئے یہاں تک کہ آپ کے سانس آواز سنائی دینے لگی ، پھر آپ نے سا طرح تین دفعہ کیا ، چھ رکعتیں پڑھیں ، ہر دفعہ آپ مسواک کرتے ، وضوفرماتےاور ان آیات کو تلاوت فرماتے ، پھر آپ نے تین وتر پڑھے ، پھر موذن نے اذان دی تو آپ نماز کے لئے باہر تشریف لے گئے اور آپ یہ دعا کررہے تھے : \" اے اللہ ! میرے دل میں نور کردے اور میری زبان میں نور کردے اور میری سماعت میں نور کردے اور میری آنکھ میں نور کردے اور میرے پیچھے نور کردے اور میرے آگے نور کردے اور میرے اوپر نور کردے اور میرے نیچے نورکردے ، اے اللہ! مجھے نور عنائیت فرما ۔","",{"u2":"حبیب بن ابی ثابت نے محمد بن علی بن عبداللہ بن عباس رضی اللہ تعالیٰ عنہ سے،انھوں نے اپنے والد سے،انھوں نے حضرت عبداللہ بن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ وہ (ایک رات) رسول اللہ صلی اللہ علیہ وسلم کے ہاں سوئے تو(رات کو)آپ صلی اللہ علیہ وسلم جاگے،مسواک کی اور وضو فرمایا اور آپ (اس وقت) یہ آیا مبارکہ پڑھ رہے تھے:\"یقیناً آسمانوں اور زمین کی تخلیق میں اور دن رات کی آمد ورفت میں خالص عقل رکھنے والوں کے لئے نشانیاں ہیں۔\"یہ آیات تلاوت فرمائیں حتیٰ کہ سورت ختم کی،پھر آپ صلی اللہ علیہ وسلم کھڑے ہوئے اور دو ر کعتیں پڑھیں،ان میں بہت طویل قیام،رکوع اور سجدے کیے،پھر واپس پلٹے اور سوگئے یہاں تک کہ آپ کے سانس آواز سنائی دینے لگی،پھر آپ نے سا طرح تین دفعہ کیا،چھ رکعتیں پڑھیں،ہر دفعہ آپ مسواک کرتے،وضوفرماتےاور ان آیات کو تلاوت فرماتے،پھر آپ نے تین وتر پڑھے،پھر موذن نے اذان دی تو آپ نماز کے لئے باہر تشریف لے گئے اور آپ یہ دعا کررہے تھے:\"اے اللہ! میرے دل میں نور کردے اور میری زبان میں نور کردے اور میری سماعت میں نور کردے اور میری آنکھ میں نور کردے اور میرے پیچھے نور کردے اور میرے آگے نور کردے اور میرے اوپر نور کردے اور میرے نیچے نورکردے،اے اللہ! مجھے نور عنائیت فرما۔\""}],[1741,"ابن جریج نے کہا ، مجھے عطاء نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے خبر دی ، انھوں نے کہا : میں نے ایک رات اپنی خالہ میمونہ رضی اللہ تعالیٰ عنہا کے پاس بسر کی تو رسول اللہ صلی اللہ علیہ وسلم رات کی نفل نماز پڑھنے کے لئے جاگے ۔ نبی کریم صلی اللہ علیہ وسلم اٹھ کرمشک کی طرف گئے اور وضو فرمایا ، پھر کھڑے ہوکر نماز پڑھی ، جب میں یہ آپ کو یہ کرتے دیکھا تو میں بھی اٹھا اور میں نے بھی مشک سے وضوکیا ، ( جب رسول اللہ صلی اللہ علیہ وسلم وضو کرتے رہے ، ابن عباس رضی اللہ تعالیٰ عنہ جاگنے کے بعد غور سے انھیں دیکھتے رہے تاکہ آپ کی اتباع کرسکیں ) پھر میں آپ کے بائیں پہلو میں کھڑا ہوگیا تو آپ نے اپنی پشت کے پیچھے سے میرا ہاتھ پکڑا ، ااسی طرح پیچھے سے مجھے دائیں جانب ٹھیک کرکے کھڑا کیا ۔ ( عطا ء نے کہا : ) میں نے پوچھا : کیا یہ نفل نماز میں ہوا تھا؟انھوں نے کہا : ہاں ۔","",{"u2":"ابن جریج نے کہا،مجھے عطاء نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے خبر دی،انھوں نے کہا:میں نے ایک رات اپنی خالہ میمونہ رضی اللہ تعالیٰ عنہا کے پاس بسر کی تو رسول اللہ صلی اللہ علیہ وسلم رات کی نفل نماز پڑھنے کے لئے جاگے۔نبی کریم صلی اللہ علیہ وسلم اٹھ کرمشک کی طرف گئے اور وضو فرمایا،پھر کھڑے ہوکر نماز پڑھی، جب میں یہ آپ کو یہ کرتے دیکھا تو میں بھی اٹھا اور میں نے بھی مشک سے وضوکیا،(جب رسول اللہ صلی اللہ علیہ وسلم وضو کرتے رہے،ابن عباس رضی اللہ تعالیٰ عنہ جاگنے کے بعد غور سے انھیں دیکھتے رہے تاکہ آپ کی اتباع کرسکیں) پھر میں آپ کے بائیں پہلو میں کھڑا ہوگیا تو آپ نے اپنی پشت کے پیچھے سے میراہاتھ پکڑا،ااسی طرح پیچھے سے مجھے دائیں جانب ٹھیک کرکے کھڑا کیا۔\n(عطا ء نے کہا:) میں نے پوچھا:کیا یہ نفل نماز میں ہوا تھا؟انھوں نے کہا:ہاں۔"}],[1742,"قیس بن سعد ، عطاء سے حدیث بیان کرتے ہیں ، انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : سیدنا عباس رضی اللہ تعالیٰ عنہ نے مجھے نبی کریم صلی اللہ علیہ وسلم کے پاس بھیجا آپ صلی اللہ علیہ وسلم میری خالہ میمونہ رضی اللہ تعالیٰ عنہا کے گھر میں تھے تو وہ رات میں نے آپ کے ساتھ گزاری ، آپ رات کو اٹھ کر نماز پڑھنے لگے اور میں آپ کے بائیں طرف کھڑا ہوگیا تو آپ نے مجھے اپنی پشت کے پیچھے سے پکڑا اور اپنی دائیں جانب کرلیا ( اس حدیث میں مذید یہ تفصیل سامنے آئی کہ ابن عباس رضی اللہ تعالیٰ عنہ کو ان کے والد نے بھیجاتھا)","",{"u2":"قیس بن سعد،عطاء سے حدیث بیان کرتے ہیں،انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:حضرت عباس رضی اللہ تعالیٰ عنہ نے مجھے نبی کریم صلی اللہ علیہ وسلم کے پاس بھیجا آپ صلی اللہ علیہ وسلم میری خالہ میمونہ رضی اللہ تعالیٰ عنہا کے گھر میں تھے تو وہ رات میں نے آپ کے ساتھ گزاری،آپ رات کو اٹھ کر نماز پڑھنے لگےاور میں آپ کے بائیں طرف کھڑا ہوگیا تو آپ نے مجھے اپنی پشت کے پیچھے سے پکڑا اور اپنی دائیں جانب کرلیا(اس حدیث میں مذید یہ تفصیل سامنے آئی کہ ابن عباس رضی اللہ تعالیٰ عنہ کو ان کے والد نے بھیجاتھا)-"}],[1743,"عبدالملک نے عطاء سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : میں نے اپنی خالہ میمونہ رضی اللہ تعالیٰ عنہا کے ہاں رات گزاری ۔ ۔ ۔ آگے ابن جریج اور قیس بن سعد کی روایت کی طرح ہے ۔","",{"u2":"عبدالملک نے عطاء سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا:میں نے اپنی خالہ میمونہ رضی اللہ تعالیٰ عنہا کے ہاں رات گزاری۔۔۔آگے ابن جریج اور قیس بن سعد کی روایت کی طرح ہے۔"}],[1744,"ابو بکر بن ابی شیبہ ابن مثنیٰ ، اور ابن بشار نے غندر ، شعبہ اور ابوجمرہ کی سند سے حدیث بیان کی کہ سیدنا ابن عباس رضی اللہ تعالیٰ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کو تیرہ رکعتیں پڑھا کرتے تھے ( یہی رات کی رکعتوں کی زیادہ سے زیادہ تعداد ہے جس میں دو خفیف رکعتیں شامل ہیں ۔ آپ صلی اللہ علیہ وسلم کا معمول گیارہ کا تھا جس طرح سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے فرمایا ۔)","",{"u2":"ابو بکر بن ابی شیبہ ابن مثنیٰ،اور ابن بشار نے غندر،شعبہ اور ابوجمرہ کی سند سے حدیث بیان کی کہ حضرت ابن عباس رضی اللہ تعالیٰ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کوتیرہ رکعتیں پڑھاکرتے تھے(یہی رات کی رکعتوں کی زیادہ سے زیادہ تعداد ہے جس میں دو خفیف رکعتیں شامل ہیں۔آپ صلی اللہ علیہ وسلم کا معمول گیارہ کاتھا جس طرح حضرت عائشہ رضی اللہ تعالیٰ عنہا نے فرمایا۔)"}],[1745,"سیدنا زید بن خالد جہنی رضی اللہ تعالیٰ عنہ سے روایت ہے ۔ کہ انھوں نے ( دل میں ) کہا : میں آج رات رسول اللہ صلی اللہ علیہ وسلم کی نماز کا ( گہری نظر سے ) مشاہدہ کروں گا ، تو ( میں نے دیکھا کہ ) آپ نے دو ہلکی رکعتیں پڑھیں ، پھر دو انتہائی لمبی رکعتیں بہت ہی زیادہ لمبی رکعتیں اداکیں ، پھر دو رکعتیں پڑھیں ۔ جو ( ان طویل ترین ) رکعتوں سے ہلکی تھیں ، پھر دو رکعتیں پڑھیں جو اپنے سے پہلے کی دو رکعتوں سے ہلکی تھیں ، پھر دو رکعتیں پڑھیں جو ا پنے سے پہلے کی دو رکعتوں سے کم تر تھیں ، پھر دو رکعتیں پڑھیں جو اپنے سے پہلی والی رکعتوں سے کم تھیں ، پھر وتر پڑھا تو یہ تیرہ رکعتیں ہوئیں ۔","",{"u2":"حضرت زید بن خالد جہنی رضی اللہ تعالیٰ عنہ سے روایت ہے۔کہ انھوں نے(دل میں) کہا:میں آج رات رسول اللہ صلی اللہ علیہ وسلم کی نماز کا(گہری نظر سے)مشاہدہ کروں گا،تو(میں نے دیکھا کہ)آپ نے دو ہلکی رکعتیں پڑھیں،پھر دو انتہائی لمبی رکعتیں بہت ہی زیادہ لمبی رکعتیں اداکیں،پھر دو رکعتیں پڑھیں۔جو (ان طویل ترین)رکعتوں سے ہلکی تھیں،پھر دو رکعتیں پڑھیں جو اپنے سے پہلے کی دو رکعتوں سے ہلکی تھیں،پھر دو رکعتیں پڑھیں جو ا پنے سے پہلے کی دو رکعتوں سے کم تر تھیں،پھر دو رکعتیں پڑھیں جو اپنے سے پہلی والی رکعتوں سے کم تھیں،پھر وتر پڑھا تو یہ تیرہ رکعتیں ہوئیں۔"}],[1746,"سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : میں ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا ، ہم پانی کے ایک گھاٹ پر پہنچے تو آپ نے فرمایا : \" جابر!کیا تم سواری کو پلانے کے لئے گھاٹ پر نہیں اتروں گے؟ \" میں نے کہا : کیوں نہیں!رسول اللہ صلی اللہ علیہ وسلم ( بھی ) گھاٹ پر اترے اور میں بھی اترا ، پھر آپ ضرورت کے لئے تشریف لے گئے اور میں نے آپ کے لئے وضو کا پانی رکھ دیا ، آپ واپس آئے اور وضو فرمایا ، پھر آپ کھڑ ے ہوئے اور ایک کپڑے میں نماز پڑھی جس کے دونوں کنارے آپ نے مخالف سمتوں میں ڈال رکھے تھے ( دائیں کنارے کو بائیں کندھے پر اور بائیں کنارے کو دائیں کندھے پر ڈالا ) میں آپ کے پیچھے کھڑا ہوگیا تو آپ نے میرے کان سے پکڑ کر مجھے اپنی دائیں طرف کرلیا ۔","",{"u2":"حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے کہا:میں ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا،ہم پانی کے ایک گھاٹ پر پہنچے تو آپ نے فرمایا:\"جابر!کیا تم سواری کو پلانے کے لئے گھاٹ پر نہیں اتروں گے؟\"میں نے کہا:کیوں نہیں!رسول اللہ صلی اللہ علیہ وسلم (بھی) گھاٹ پر اترے اور میں بھی اترا،پھر آپ ضرورت کے لئے تشریف لے گئے اور میں نے آپ کے لئے وضو کا پانی رکھ دیا،آپ واپس آئے اور وضو فرمایا،پھر آپ کھڑ ے ہوئے اور ایک کپڑے میں نماز پڑھی جس کے دونوں کنارے آپ نے مخالف سمتوں میں ڈال رکھے تھے(دائیں کنارے کو بائیں کندھے پر اور بائیں کنارے کو دائیں کندھے پر ڈالا) میں آپ کے پیچھے کھڑا ہوگیا تو آپ نے میرے کان سے پکڑ کر مجھے اپنی دائیں طرف کرلیا۔"}],[1747,"سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت ہے ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب رات کو نماز پڑھنے کےلئے اٹھتے ، اپنی نماز کا آغاز دو ہلکی رکعتوں سے فرماتے ۔","",{"u2":"حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت ہے،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم جب رات کو نماز پڑھنے کےلئے اٹھتے،اپنی نماز کا آغاز دو ہلکی رکعتوں سے فرماتے۔"}],[1748,"سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جب تم میں سے کوئی رات کو ( نماز کے لئے ) اٹھے تو وہ اپنی نماز کا آغاز دو ہلکی رکعتوں سے کرے ۔","",{"u2":"حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا:\"جب تم میں سے کوئی رات کو(نماز کے لئے)اٹھے تو وہ اپنی نماز کا آغاز دو ہلکی رکعتوں سے کرے۔\""}],[1749,"امام مالک ؒ نے ابو زہیر سے ، انھوں نے طاؤس سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب رات کی آ خری تہائی میں نماز کے لئے اٹھتے تو فرماتے : \" اے اللہ ! تمام تعریف تیرے ہی لئے ہے ، تو آسمانوں اور زمین کا نور ہے اور تیرے ہی لئے حمد ہے تو آسمانوں اور زمین کو قائم رکھنے والا ہے اور تیرے ہی لئے حمد ہےتو آسمانوں اور زمین کا اور جو کچھ ان میں ہے تو پالنے والا ہے ۔ اور تو برحق ہے اور تیرا وعدہ سچا ہے اور تیرا قول اٹل ہے اور تیرے ساتھ ملاقات قطعی ہے اور جنت حق ہے اور جہنم حق ہے اور قیامت حق ہے ۔ اے اللہ میں نے اپنے آپ کو تیرے سپرد کردیا اور میں تجھ پر ایمان لایا اور میں نے تجھ پر توکل اور بھروسہ کیا اور تیری طرف رجوع کیا اور تیر ی توفیق سے ( تیرے منکروں سے ) جھگڑا کیا اور تیرے ہی حضور فیصلہ لایا ( تجھے ہی حاکم تسلیم کیا ) تو بخش دے وہ گناہ جو میں نے پہلے کیے اور جو بعد میں کئے اور جو چھپ کرکئے اور جو ظاہرا کیے تو ہی میرا معبود ہے تیرے سوا کوئی معبود نہیں ۔","",{"u2":"امام مالک رحمہ اللہ نے ابو زہیر سے،انھوں نے طاؤس سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب رات کی آ خری تہائی میں نماز کے لئے اٹھتے تو فرماتے:\"اے اللہ! تمام تعریف تیرے ہی لئے ہے،تو آسمانوں اور زمین کا نور ہے اور تیرے ہی لئے حمد ہے تو آسمانوں اور زمین کو قائم رکھنے والا ہے اور تیرے ہی لئے حمد ہےتو آسمانوں اور زمین کا اور جو کچھ ان میں ہے تو پالنے والا ہے۔اور توبرحق ہے اور تیرا وعدہ سچا ہے اور تیرا قول اٹل ہے اور تیرے ساتھ ملاقات قطعی ہے اور جنت حق ہے اور جہنم حق ہے اور قیامت حق ہے۔اے اللہ میں نے اپنے آپ کو تیرے سپرد کردیا اور میں تجھ پر ایمان لایا اور میں نے تجھ پر توکل اور بھروسہ کیا اور تیری طرف رجوع کیا اور تیر ی توفیق سے(تیرے منکروں سے)جھگڑا کیا اور تیرے ہی حضور فیصلہ لایا(تجھے ہی حاکم تسلیم کیا) تو بخش دے وہ گناہ جو میں نے پہلے کیے اور جو بعد میں کئے اور جو چھپ کرکئے اور جو ظاہرا کیے تو ہی میرا معبود ہے تیرے سوا کوئی معبود نہیں۔\""}],[1750,"سفیان اور ابن جریج دونوں نے سلیمان ا حول سے ، انھوں نے طاؤس سے ، انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ۔ ابن جریج اور امام مالک ؒ کی ( گزشتہ ) حدیث کے الفاظ ایک جیسے ہیں ، دو جملوں کے سوا کوئی اختلاف نہیں ، ابن جریج نے قيام کے بجائے قيم کہا ( معنی ایک ہیں ) اور واسررت کی جگہ وما اسررت کہا ۔ ( سفیان ) ابن عینیہ کی حدیث میں کچھ اضافہ ہے ، وہ متعدد جملوں میں امام مالکؒ اور ابن جریج سے اختلاف کرتے ہیں ۔","",{"u2":"سفیان اور ابن جریج دونوں نے سلیمان ا حول سے،انھوں نے طاؤس سے،انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی۔ابن جریج اور امام مالک رحمہ اللہ کی(گزشتہ)حدیث کے الفاظ ایک جیسے ہیں،دو جملوں کے سوا کوئی اختلاف نہیں،ابن جریج نے قیام کے بجائے قیم کہا(معنی ایک ہیں) اور واسررت کی جگہ وما اسررت کہا۔(سفیان) ابن عینیہ کی حدیث میں کچھ اضافہ ہے،وہ متعدد جملوں میں امام مالک رحمہ اللہ اور ابن جریج سے اختلاف کرتے ہیں۔"}],[1751,"قیس بن سعد نے طاؤس سے ، انھوں نے ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے یہی حدیث روایت کی ۔ ( اس حدیث کے راوی عمران القصیر کے ) الفاظ ان ( امام مالک ، سفیان ، ابن جریج ) کے الفاظ سے ملتے جلتے ہیں ۔","",{"u2":"قیس بن سعد نے طاؤس سے،انھوں نے ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے یہی حدیث روایت کی۔(اس حدیث کے راوی عمران القصیر کے) الفاظ ان (امام مالک،سفیان،ابن جریج) کے الفاظ سے ملتے جلتے ہیں۔"}],[1752,"ابو سلمہ بن عبدالرحمان نے کہا : میں نے ام المومنین سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا : نبی اکرم صلی اللہ علیہ وسلم جب رات کو نماز کے لئے اٹھتے تھے تو کس چیز کے ساتھ نماز کا آغاز کرتے تھے؟انھوں نے جواب دیا : جب آپ رات کو اٹھتے تو نماز کا آ غاز ( اس دعا سے ) کرتے : \" اے اللہ! جبرائیل ، میکائیل اور اسرافیل کے رب!آسمانوں اور زمین کو پیدا فرمانے والے!پوشیدہ اور ظاہر کو جاننے والے!تیرے بندے جن باتوں میں اختلاف کرتے تھے تو ہی ان کے درمیان فیصلہ فرمائےگا ۔ ، جن باتوں میں اختلاف کیا گیا ہے تو ہی ا پنے حکم سے مجھے ان میں سے جو حق ہے اس پر چلا ، بے شک تو ہی جسے چاہے سیدھی راہ پر چلاتا ہے ۔","",{"u2":"ابو سلمہ بن عبدالرحمان نے کہا:میں نے ام المومنین حضرت عائشہ رضی اللہ تعالیٰ عنہا سے پوچھا:نبی اکرم صلی اللہ علیہ وسلم جب رات کو نماز کے لئے اٹھتے تھے تو کس چیز کے ساتھ نماز کا آغاز کرتے تھے؟انھوں نے جواب دیا:جب آپ رات کو اٹھتے تو نماز کا آ غاز(اس دعا سے) کرتے:\"اے اللہ! جبرائیل،میکائیل اور اسرافیل کے رب!آسمانوں اور زمین کو پیدا فرمانے والے!پوشیدہ اور ظاہر کو جاننے والے!تیرے بندے جن باتوں میں اختلاف کرتے تھے تو ہی ان کے درمیان فیصلہ فرمائےگا۔،جن باتوں میں اختلاف کیا گیا ہے تو ہی ا پنے حکم سے مجھے ان میں سے جو حق ہے اس پر چلا،بے شک تو ہی جسے چاہے سیدھی راہ پر چلاتا ہے۔\""}],[1753,"یوسف ماجثون نے کہا : مجھ سے میرے والد ( یعقوب بن ابی سلمہ ماجثون ) نے عبدالرحمان اعرج سے حدیث بیان کی ، انھوں نے عبیداللہ بن ابی رافع سے ، انھوں نے سیدنا علی بن ابی طالب رضی اللہ تعالیٰ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے ر وایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم نماز کے لئے کھڑ ے ہوتے تھے تو فرماتے : \"\" میں نے اپنا رخ اس ذات کی طرف کردیا ہے ۔ جس نے آسمانوں اور زمین کو پیدا فرمایا ، ہر طرف سے یکسو ہوکر ، اور میں اس کے ساتھ شریک ٹھہرانے والوں میں سے نہیں ، میری نماز اور میری ہر ( بدنی ومالی ) عبادت اور میرا جینا اور میرا مرنا اللہ کے لئے ہے جو کائنات کا رب ہے ، اس کا کوئی شریک نہیں اور اسی کا مجھے حکم ملا ہے اور میں فرمانبرداری کرو نے والوں میں سے ہوں ۔ اے اللہ ! تو ہی بادشاہ ہے تیرے سوا کوئی بندگی کے لائق نہیں ، تو میرا رب ہے میں تیرا بندہ ہوں اور میں نے اپنے اوپر ظلم کیا ہے اور اپنے گناہ کا اعتراف کیا ہے ، اس لئے میرے سارے گناہ بخش دے کیونکہ گناہوں کو بخشنے والا تیرے سوا کوئی نہیں ، اور میری بہترین اخلاق کی طرف راہنمائی فرما ، تیرے سوا بہترین اخلاق کی راہ پر چلانے والا کوئی نہیں ، اور برے اخلاق مجھ سے ہٹا دے ، تیرے سوا برے اخلاق کو مجھ سے دور کرنے والا کوئی نہیں ، میں تیرے حضور حاضر ہوں اور دونوں جہانوں کی سعادتیں تجھ سے ہیں ہر طرح کی بھلائی تیر ے ہاتھ میں ہے اور برائی کا تیر ی طرف کوئی گزر نہیں ہے میں تیرے ہی سہارے ہوں ، اور تیری ہی طرف میرا رخ ہے ، تو برکت والا رفعت والا اور بلندی والا ہے میں تجھ سے بخشش مانگتا ہوں اور تیرے حضور توبہ کر تا ہوں ۔ \"\" اور جب آپ رکوع کرتے تو فرماتے : \"\" اے اللہ ! میں تیرے سامنے جھکا ہوا ہوں اور میں تجھ ہی پر ایمان لایا ہوں ، اپنے آپ کو تیرے ہی سپرد کر دیا ہے ، میرے کان اور میری آنکھیں اور میرا مغز اور میری ہڈیاں اور میری رگیں اور میرے پٹھے تیرے ہی حضور جھکے ہوئے ہیں ۔ \"\" اور جب رکوع سے اٹھتے تو کہتے : \"\" اے اللہ! ہمارے رب ، تیرے ہی لئے حمد ہے جس سے آ سمانوں اور زمین کی وسعتیں بھر جائیں اور اس کے بعد جو تو چاہے اس کی وسعتیں بھر جائیں ۔ \"\" اور جب آپ سجدہ کرتے تو کہتے : \"\" اے اللہ!میں نے تیرے ہی حضور سجدہ کیا اور تجھ ہی پر ایمان لایا اور ا پنے آپ کو تیرے ہی حوالے کیا ، میرا چہرہ اس ذات کے سامنے سجدہ ریز ہے جس نے اسے پیدا کیا ، اس کی صورت گری کی اور اس کے کان اور اس کی آنکھیں تراشیں ، برکت والاہے اللہ جو بہترین خالق ہے ۔ \"\" پھر تشہد اور سلام کے درمیان میں یہ دعا پڑھتے ۔ \"\" اے اللہ ! بخش دے جو خطائیں میں نے پہلے کیں یا بعد میں کیں اور چھپا کر کہیں یا علانیہ کیں اور جو بھی زیادتی میں نے کی اور جس کا مجھ سے زیادہ تمھیں علم ہے ( اطاعت اور خیر میں ) تو ہی آگے کرنے والا ہے اور تو ہی پیچھے کرنے والا ہے اور تیرے سوا کوئی عبادت کا حقدار نہیں ۔","",{"u2":"یوسف ماجثون نے کہا:مجھ سے میرے والد(یعقوب بن ابی سلمہ ماجثون) نے عبدالرحمان اعرج سے حدیث بیان کی،انھوں نے عبیداللہ بن ابی رافع سے،انھوں نے حضرت علی بن ابی طالب رضی اللہ تعالیٰ عنہ سے اور انھوں نےرسول اللہ صلی اللہ علیہ وسلم سے ر وایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم نماز کے لئے کھڑ ے ہوتے تھے تو فرماتے:\"میں نے اپنا رخ اس ذات کی طرف کردیا ہے۔جس نے آسمانوں اور زمین کو پیدا فرمایا،ہر طرف سے یکسو ہوکر، اور میں اس کے ساتھ شریک ٹھہرانے والوں میں سے نہیں،میری نماز اور میری ہر(بدنی ومالی) عبادت اور میرا جینا اور میرا مرنا اللہ کے لئے ہے جو کائنات کا رب ہے،اس کا کوئی شریک نہیں اور اسی کا مجھے حکم ملا ہے اور میں فرمانبرداری کرونے والوں میں سے ہوں۔اے اللہ! تو ہی بادشاہ ہے تیرے سوا کوئی بندگی کے لائق نہیں،تو میرا رب ہے میں تیرا بندہ ہوں اور میں نے اپنے اوپر ظلم کیا ہے اور اپنے گناہ کا اعتراف کیا ہے،اس لئے میرے سارے گناہ بخش دے کیونکہ گناہوں کو بخشنے والا تیرے سوا کوئی نہیں،اور میری بہترین اخلاق کی طرف راہنمائی فرما،تیرے سوا بہترین اخلاق کی راہ پر چلانے والا کوئی نہیں،اور برے اخلاق مجھ سے ہٹا دے،تیرے سوا برے اخلاق کو مجھ سے دور کرنے والا کوئی نہیں،میں تیرے حضور حاضر ہوں اور دونوں جہانوں کی سعادتیں تجھ سے ہیں ہر طرح کی بھلائی تیر ے ہاتھ میں ہے اور برائی کا تیر ی طرف کوئی گزر نہیں ہے میں تیرے ہی سہارے ہوں،اور تیری ہی طرف میرا رخ ہے،تو برکت والا رفعت والا اور بلندی والا ہے میں تجھ سے بخشش مانگتا ہوں اور تیرے حضور توبہ کر تا ہوں۔\"\nاور جب آپ رکوع کرتے تو فرماتے:\"اے اللہ! میں تیرے سامنے جھکا ہوا ہوں اور میں تجھ ہی پر ایمان لایاہوں،اپنے آپ کو تیرے ہی سپرد کر دیا ہے،میرے کان اور میری آنکھیں اور میرا مغز اور میری ہڈیاں اور میری رگیں اور میرے پٹھے تیرے ہی حضور جھکے ہوئے ہیں۔\"\nاور جب رکوع سے اٹھتے تو کہتے:\"اے اللہ! ہمارے رب،تیرے ہی لئے حمد ہے جس سے آ سمانوں اور زمین کی وسعتیں بھر جائیں اور اس کے بعد جو تو چاہے اس کی وسعتیں بھر جائیں۔\"\nاور جب آپ سجدہ کرتے تو کہتے:\"اے اللہ!میں نے تیرے ہی حضور سجدہ کیااور تجھ ہی پر ایمان لایا اور ا پنے آپ کو تیرے ہی حوالے کیا،میرا چہرہ اس ذات کے سامنے سجدہ ریز ہے جس نےاسے پیدا کیا،اس کی صورت گری کی اور اس کے کان اور اس کی آنکھیں تراشیں،برکت والاہے اللہ جو بہترین خالق ہے۔\"پھر تشہد اور سلام کے درمیان میں یہ دعا پڑھتے۔\"اے اللہ! بخش دے جو خطائیں میں نے پہلے کیں یا بعد میں کیں اور چھپا کر کہیں یا علانیہ کیں اور جو بھی زیادتی میں نے کی اور جس کا مجھ سے زیادہ تمھیں علم ہے(اطاعت اور خیر میں) تو ہی آگے کرنے والا ہے اور تو ہی پیچھے کرنے والا ہے اور تیرے سوا کوئی عبادت کا حقدار نہیں۔\""}],[1754,"عبدالعزیز بن عبداللہ بن ابی سلمہ نے اپنے چچا الماجثون ( یعقوب ) بن ابی سلمہ سے اور انھوں نے ( عبدالرحمان ) اعرج سے اسی سند کے ساتھ یہی حدیث بیان کی اور کہا : رسول اللہ صلی اللہ علیہ وسلم جب نماز کا آغاز فرماتے تو اللہ اکبر کہتے ، پھر د عا پڑھتے : وجهت وجهيي اس میں ( کے بجائے ) \" انا من المسلمين \" اور میں اطاعت وفرمانبرداری میں اولین ( مقام پر فائز ) ہوں \" کے الفاظ ہیں اور کہا : جب آپ رکوع سے اپنا سر اٹھاتے تو \" سمع اللہ لمن حمده ربنا ولك الحمد \" کہتے اورصوره ( اس کی صورت گری کی ) کے بعد \" فاحسن صوره \" ( اس کو بہترین شکل وصورت عنایت فرمائی ) کے الفاظ کہے اور کہا جب سلام پھیرتے تو کہتے : \" اللهم اغفرلي ما قدمت \" اے اللہ! بخش دے جو میں نے پہلے کیا ۔ \" حدیث کے آخر تک اور انھوں نے \" تشہد اور سلام پھیرنے کے درمیان \" کے الفاظ نہیں کہے ۔","",{"u2":"عبدالعزیز بن عبداللہ بن ابی سلمہ نے اپنے چچا الماجثون(یعقوب) بن ابی سلمہ سے اور انھوں نے (عبدالرحمان) اعرج سے اسی سند کے ساتھ یہی حدیث بیان کی اور کہا:رسول اللہ صلی اللہ علیہ وسلم جب نماز کا آغاز فرماتے تو اللہ اکبر کہتے،پھر د عا پڑھتے:وجہت وجہیی اس میں (کے بجائے)\"انا من المسلمین\" اور میں اطاعت وفرمانبرداری میں اولین (مقام پر فائز) ہوں\"کے الفاظ ہیں اور کہا:جب آپ رکوع سے اپنا سر اٹھاتے تو\"سمع اللہ لمن حمدہ ربنا ولک الحمد\" کہتے اورصورہ(اس کی صورت گری کی)کے بعد \"فاحسن صورہ\"(اس کو بہترین شکل وصورت عنایت فرمائی) کے الفاظ کہے اور کہا جب سلام پھیرتے تو کہتے:\" اللہم اغفرلی ما قدمت \"اے اللہ! بخش دے جو میں نے پہلے کیا۔\"حدیث کے آخر تک اور انھوں نے \"تشہد اور سلام پھیرنے کے درمیان\" کے الفاظ نہیں کہے۔"}],[1755,"عبداللہ بن نمیر ، ابو معاویہ اور جریر سب نے اعمش سے ، انھوں نے سعد بن عبیدہ سے ، انھوں نے مستورد بن احنف سے ، انھوں نے صلہ بن زفر سے اور انھوں نے سیدنا حذیفہ رضی اللہ تعالیٰ عنہ سے روایت کی ، ۔ انھوں نے کہا : ایک رات میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی ، آپ نے سورہ بقرہ کا آغاز فرمایا ، میں نے ( دل میں ) کہا : آپ سو آیات پڑھ کر رکوع فرمائیں گے مگر آپ آگے بڑھ گئے میں نے کہا : آپ اسے ( پوری ) رکعت میں پڑھیں گے ، آپ آگے پڑھتے گئے ، میں نے سوچا ، اسے پڑھ کر رکوع کریں گے مگر آپ نے سورہ نساءشروع کردی ، آپ نے وہ پوری پڑھی ، پھر آپ نے آل عمران شروع کردی ، اس کو پورا پڑھا ، آپ ٹھر ٹھر کر قرائت فرماتے رہے جب ایسی آیت سے گزرتے جس میں تسبیح ہے تو سبحان اللہ کہتے اور جب سوال ( کرنے والی آیت ) سے گزرتے ( پڑھتے ) تو سوا ل کرتے اور جب پناہ مانگنے والی آیت سے گزرتے تو ۔ ( اللہ سے ) پناہ مانگتے ، پھر آپ نے ر کوع فرمایا اور سبحان ربي العظيم کہنے لگے ، آپ کا رکوع ( تقریباً ) آپ کے قیام جتنا تھا ۔ پھر آپ نے \"\" سمع اللہ لمن حمده \"\" کہا : پھر آپ لمبی دیر کھڑے رہے ، تقریباً اتنی دیر جتنی دیر رکوع کیا تھا ، پھر سجدہ کیا اور \"\" سبحان ربي الاعلي \"\" کہنے لگے اور آپ کا سجدہ ( بھی ) آپ کے قیام کے قریب تھا ۔ جریر کی روایت میں یہ اضافہ ہےکہ آپ نے کہا : ( سمع اللہ لمن حمده ربنا لك الحمد \"\" ) یعنی ربنا لك الحمد کا اضافہ ہے ۔","",{"u2":"عبداللہ بن نمیر،ابو معاویہ اور جریر سب نے اعمش سے،انھوں نے سعد بن عبیدہ سے،انھوں نے مستورد بن احنف سے،انھوں نے صلہ بن زفر سے اور انھوں نے حضرت حذیفہ رضی اللہ تعالیٰ عنہ سے روایت کی،۔انھوں نے کہا:ایک رات میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی،آپ نے سورہ بقرہ کا آغاز فرمایا،میں نے(دل میں) کہا:آپ سو آیات پڑھ کر رکوع فرمائیں گے مگر آپ آگے بڑھ گئے میں نے کہا:آپ اسے(پوری) رکعت میں پڑھیں گے،آپ آگے پڑھتے گئے،میں نے سوچا،اسے پڑھ کر رکوع کریں گے مگر آپ نے سورہ نساءشروع کردی،آپ نے وہ پوری پڑھی،پھر آپ نے آل عمران شروع کردی،اس کو پورا پڑھا،آپ ٹھر ٹھر کر قرائت فرماتے رہے جب ایسی آیت سے گزرتے جس میں تسبیح ہے توسبحان اللہ کہتے اور جب سوال (کرنے والی آیت) سے گزرتے(پڑھتے) تو سوا ل کرتے اور جب پناہ مانگنے والی آیت سے گزرتے تو۔(اللہ سے) پناہ مانگتے،پھر آپ نے ر کوع فرمایا اور سبحان ربی العظیم کہنے لگے،آپ کا رکوع(تقریباً) آپ کے قیام جتنا تھا۔پھر آپ نے \"سمع اللہ لمن حمدہ\"کہا:پھر آپ لمبی دیر کھڑے رہے،تقریباً اتنی دیر جتنی دیر رکوع کیا تھا،پھر سجدہ کیا اور \"سبحان ربی الاعلی\" کہنے لگے اور آپ کا سجدہ (بھی) آپ کے قیام کے قریب تھا۔\nجریر کی روایت میں یہ اضافہ ہےکہ آپ نے کہا:(سمع اللہ لمن حمدہ ربنا لک الحمد\")یعنی ربنا لک الحمدکا اضافہ ہے۔)"}],[1756,"جریر نے اعمش سے اور انھوں نے ابووائل سے روایت کی ۔ انھوں نے کہا : سیدنا عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نمازپڑھی آپ نے اتنی لمبی نماز پڑھی کہ میں نے ایک ناپسندیدہ کام کا ارادہ کر لیا ۔ کہا : تو ان سے پوچھا گیا آپ نے کس بات کا ارادہ کیا تھا؟ انھوں نے کہا : میں نے ارادہ کیا کہ بیٹھ جاؤں اور آپ کو ( اکیلے ہی قیام کی حالت میں ) چھوڑدوں ۔","",{"u2":"جریر نے اعمش سے اور انھوں نے ابووائل سے روایت کی۔انھوں نے کہا: حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نمازپڑھی آپ نے اتنی لمبی نماز پڑھی کہ میں نے ایک ناپسندیدہ کام کا ارادہ کر لیا۔کہا: تو ان سے پوچھا گیا آپ نے کس بات کا ارادہ کیا تھا؟\nانھوں نے کہا: میں نے ارادہ کیا کہ بیٹھ جاؤں اور آپ کو (اکیلے ہی قیام کی حالت میں) چھوڑدوں۔\""}],[1757,"علی بن مسہر نے اعمش سے اسی سند کے ساتھ اسی کے مانند روایت کی ۔","",{"u2":"علی بن مسہر نے اعمش سے اسی سند کے ساتھ اسی کے مانند روایت کی۔"}],[1758,"سیدنا عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت ہے انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے سامنے ایک ایسے آدمی کا ذکر کیا گیا جو رات نھر سویا رہا یہاں تک کہ صبح ہو گئی آپ نے فر ما یا : وہ ( ایسا ) شخص ہے کہ شیطان نے اس کے کان میں ۔ \" یا فر ما یا : \" اس کے دونوں کا نوں میں پیشاب کر دیا ہے ۔","",{"u2":"حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت ہے انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے سامنے ایک ایسے آدمی کا ذکر کیا گیا جو رات نھر سویا رہا یہاں تک کہ صبح ہو گئی آپ نے فر ما یا:وہ (ایسا)شخص ہے کہ شیطان نے اس کے کان میں۔\"یا فر ما یا:\"اس کے دونوں کا نوں میں پیشاب کر دیا ہے۔\""}],[1759,"سیدنا علی بن ابی طالب رضی اللہ تعالیٰ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے رات کے وقت انھیں اور فاطمہ رضی اللہ تعالیٰ عنہا کو جگایا اور فر ما یا : \" کیا تم لوگ نماز نہیں پڑھو گے؟ میں نےکہا : اے اللہ کے رسول !ہماری جانیں اللہ کے ہاتھ میں ہیں جب وہ ہمیں اٹھانا چاہتا ہے اٹھا دیتا ہے جب میں نے آپ سے یہ کہا تو آپ واپس چلے گئے پھر میں نے آپ کو سنا کہ آپ واپس پلٹتے ہو ئے اپنی ران پر ہاتھ مارتے تھے اور کہتے ( آیت کا ایک ٹکڑا پڑھتے ) تھے : \" انسان سب سے بڑھ کر جھگڑا کرنے والا ہے ( جدل ( جھگڑا ) یہ تھی کہ جگا ئے جا نے پر ممنون ہو نے اور نماز پڑھنے کی بجا ئے عذر پیش کیا گیا ۔","",{"u2":"حضرت علی بن ابی طالب رضی اللہ تعالیٰ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے رات کے وقت انھیں اور فاطمہ رضی اللہ تعالیٰ عنہا کو جگایا اور فر ما یا:\"کیا تم لوگ نماز نہیں پڑھو گے؟ میں نےکہا:اے اللہ کے رسول!ہماری جانیں اللہ کے ہاتھ میں ہیں جب وہ ہمیں اٹھانا چاہتا ہے اٹھا دیتا ہے جب میں نے آپ سے یہ کہا تو آپ واپس چلے گئے پھر میں نے آپ کو سنا کہ آپ واپس پلٹتے ہو ئے اپنی ران پر ہاتھ مارتے تھے اور کہتے (آیتکا ایک ٹکڑاپڑھتے) تھے:\"انسان سب سے بڑھ کر جھگڑا کرنے والا ہے (جدل(جھگڑا) یہ تھی کہ جگا ئے جا نے پر ممنون ہو نے اور نماز پڑھنے کی بجا ئے عذر پیش کیا گیا۔)"}],[1760,"سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت ہے انھوں نے یہ فرمان نبی صلی اللہ علیہ وسلم کی طرف منسوب کیا آپ نے فر ما یا : \" جب تم میں سے کو ئی سوجا تا ہے تو شیطان اس کے سر کے پچھلے حصے پر تین گرہیں لگاتا ہے ہر گرہ پر تھپکی دیتا ہے کہ تم پر ایک بہت لمبی رات ( کا سونا لا زم ) ہے جب انسان بیدار ہو کر اللہ تعا لیٰ کا ذکر کرتا ہے تو ایک گرہ کھل جا تی ہے اور جب وہ وضو کرتا ہے اس سے دو گرہ کھل جا تی ہے پھر جب نماز پڑھتا ہے ساری گرہیں کھل جاتی ہیں اور وہ چاق چوبند ہشاش بشاش پاک طبیعت ( کےساتھ ) صبح کرتا ہے ورنہ ( جاگ کر عبادت نہیں کرتا تو ) صبح کو گندے دل کے ساتھ اور سست اٹھتا ہے ۔","",{"u2":"حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت ہے انھوں نے یہ فرمان نبی صلی اللہ علیہ وسلم کی طرف منسوب کیا آپ نے فر ما یا:\"جب تم میں سے کو ئی سوجا تا ہے تو شیطان اس کے سر کے پچھلے حصے پر تین گرہیں لگاتا ہے ہر گرہ پر تھپکی دیتا ہے کہ تم پر ایک بہت لمبی رات (کا سونا لا زم) ہے جب انسان بیدار ہو کر اللہ تعا لیٰ کا ذکر کرتا ہے تو ایک گرہ کھل جا تی ہے اور جب وہ وضو کرتا ہے اس سے دو گرہ کھل جا تی ہے پھر جب نماز پڑھتا ہے ساری گرہیں کھل جاتی ہیں اور وہ چاق چوبند ہشاش بشاش پاک طبیعت (کےساتھ) صبح کرتا ہے ورنہ (جاگ کر عبادت نہیں کرتا تو) صبح کو گندے دل کے ساتھ اور سست اٹھتا ہے۔\""}],[1761,"عبیداللہ نے کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے بیان کیا انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فر ما یا : \" کچھ نمازیں گھر میں پڑھا کرو اور ان ( گھروں ) کو قبریں نہ بناؤ ۔","",{"u2":"عبیداللہ نے کہا: مجھے نافع نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے بیان کیا انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی،آپ نے فر ما یا:\"کچھ نمازیں گھر میں پڑھا کرو اور ان (گھروں) کو قبریں نہ بناؤ۔\""}],[1762,"ایوب نے نافع سے انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فر ما یا : گھروں میں ( نفل ) نمازیں پڑھوں اور انھیں قبریں نہ بناؤ ۔","",{"u2":"ایوب نے نافع سے انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی، آپ نے فر ما یا:گھروں میں (نفل)نمازیں پڑھوں اور انھیں قبریں نہ بناؤ۔\""}],[1763,"سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت ہے انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" جب تم میں سے کو ئی اپنی مسجد میں نماز ( باجماعت ) ادا کر لے تو اپنی نماز میں سے اپنے گھر کے لیے بھی کچھ حصہ رکھے کیونکہ اللہ اس کے گھر میں اس کے نماز پڑھنے کی وجہ سے خیروبھلا ئی رکھے گا ۔","",{"u2":"حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت ہے انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"جب تم میں سے کو ئی اپنی مسجد میں نماز (باجماعت)ادا کر لے تو اپنی نماز میں سے اپنے گھر کے لیے بھی کچھ حصہ رکھے کیونکہ اللہ اس کے گھر میں اس کے نماز پڑھنے کی وجہ سے خیروبھلا ئی رکھے گا۔"}],[1764,"سیدنا ابو موسیٰ رضی اللہ تعالیٰ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فر ما یا : \" اس گھر کی مثال جس میں اللہ کا ذکر کیا جا تا ہے اور اس گھر کی مثال جس میں اللہ کو یاد نہیں کیا جا تا زندہ اور مردہ جیسی ہے ۔","",{"u2":"حضرت ابو موسیٰ رضی اللہ تعالیٰ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فر ما یا:\"اس گھر کی مثال جس میں اللہ کا ذکر کیا جا تا ہے اور اس گھر کی مثال جس میں اللہ کو یاد نہیں کیا جا تا زندہ اور مردہ جیسی ہے۔\""}],[1765,"سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" اپنے گھروں کو قبرستان نہ بنا ؤ شیطان اس گھر سے بھا گتا ہے جس میں سورہ بقرہ پڑھی جاتی ہے ۔","",{"u2":"حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"اپنے گھروں کو قبرستان نہ بنا ؤ شیطان اس گھر سے بھا گتا ہے جس میں سورہ بقرہ پڑھی جاتی ہے۔\""}],[1766,"عبد اللہ سعید نے کہا : عمر بن عبید اللہ رضی اللہ تعالیٰ عنہ کے آزاد کردہ غلام سالم ابو نضر نے ہمیں بسربن سعید سے حدیث بیان کی اور انھوں نے سیدنا زید بن ثابت رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے چٹائی کا ایک چھوٹا سا حجرہ بنوایا اور رسول اللہ صلی اللہ علیہ وسلم ( گھر سے ) باہر آکر اس میں نماز پڑھنے لگے لو گ اس ( حجرے ) تک آپ کے پیچھے پیچھے آئے اور آکر آپ کی اقتدامیں نماز پڑھنے لگے ، پھر ایک اور رات لو گ آئے اور ( حجرے کے ) پاس آگئے جبکہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے پاس آنے میں تا خیر کر دی ۔ کہا : آپ ان کے پاس تشریف نہ لا ئےصحابہ کرام رضوان اللہ عنھم اجمعین نے اپنی آوازیں بلند کیں ( تاکہ آپ آوازیں سن کر تشریف لے آئیں ) اور دروازے پر چھوٹی چھوٹی کنکریاں ماریں تو رسول اللہ صلی اللہ علیہ وسلم غصے کی حالت میں ان کی طرف تشریف لا ئے اور ان سے فر ما یا : تم مسلسل یہ عمل کرتے رہے حتیٰ کہ مجھے خیال ہوا کہ یہ نماز تم پر لازم قراردے دی جا ئے گی ، اس لیے تم اپنے گھروں میں نماز پڑھا کرو کیونکہ انسان کی فرض نماز کے سوا وہی بہتر ہےجو گھر میں پڑھے ۔","",{"u2":"عبد اللہ سعید نے کہا: عمر بن عبید اللہ رضی اللہ تعالیٰ عنہ کے آزاد کردہ غلام سالم ابو نضرنے ہمیں بسربن سعید سے حدیث بیان کی اور انھوں نے حضرت زید بن ثابت رضی اللہ تعالیٰ عنہ سے روایت کی، انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے چٹائی کا ایک چھوٹا سا حجرہ بنوایا اور رسول اللہ صلی اللہ علیہ وسلم (گھر سے) باہر آکر اس میں نماز پڑھنے لگے لو گ اس (حجرے) تک آپ کے پیچھے پیچھے آئے اور آکر آپ کی اقتدامیں نماز پڑھنے لگے،پھر ایک اور رات لو گ آئے اور (حجرےکے) پاس آگئے جبکہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے پاس آنے میں تا خیر کر دی۔کہا:آپ ان کے پاس تشریف نہ لا ئےصحابہ کرام رضوان اللہ عنھم اجمعین نے اپنی آوازیں بلند کیں (تاکہ آپ آوازیں سن کر تشریف لے آئیں)اور دروازے پر چھوٹی چھوٹی کنکریاں ماریں تو رسول اللہ صلی اللہ علیہ وسلم غصے کی حالت میں ان کی طرف تشریف لا ئے اور ان سے فر ما یا:تم مسلسل یہ عمل کرتے رہے حتیٰ کہ مجھے خیال ہوا کہ یہ نماز تم پر لازم قراردے دی جا ئے گی،اس لیے تم اپنے گھروں میں نماز پڑھا کرو کیونکہ انسان کی فرض نماز کے سوا وہی بہتر ہےجو گھر میں پڑھے۔\""}],[1767,"موسیٰ بن عقبہ نے ہمیں حدیث بیان کی ، کہا : میں نے ابو نضرسے سنا انھوں نے بسر بن سعید سے اور انھوں نے سیدنا زید بن ثابت رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے مسجد میں چٹائی سے ایک حجرہ بنوایا اور آپ نے اس میں چند راتیں نماز پڑھی حتیٰ کہ آپ کے پاس لو گ جمع ہو گئے ۔ ۔ ۔ پھر مذکورہ بالا روایت بیان کی اور اس میں یہ اضافہ کیا کہ ( آپ صلی اللہ علیہ وسلم نے فر ما یا : ) \" اگر تم پر نماز فرض کر دی گئی تو تم ( سب ) اس کی پابندی نہیں کر سکو گے ۔ \" ( یہ حجرہ اعتکاف کے لیے تھا ۔)","",{"u2":"موسیٰ بن عقبہ نے ہمیں حدیث بیان کی،کہا: میں نے ابو نضرسے سنا انھوں نے بسر بن سعید سے اور انھوں نے حضرت زید بن ثابت رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے مسجد میں چٹائی سے ایک حجرہ بنوایا اور آپ نے اس میں چند راتیں نماز پڑھی حتیٰ کہ آپ کے پاس لو گ جمع ہو گئے۔۔۔پھر مذکورہ بالا روایت بیان کی اور اس میں یہ اضافہ کیا کہ (آپ صلی اللہ علیہ وسلم نے فر ما یا:)\"اگر تم پر نماز فرض کر دی گئی تو تم (سب) اس کی پابندی نہیں کر سکو گے۔\"(یہ حجرہ اعتکاف کے لیے تھا۔)"}],[1768,"سعید بن ابی نے ابو سلمہ ( نم عبد الرحمان بن عوف ) سے انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کی ایک چٹائی تھی آپ رات کو اس سے حجرہ بنا لیتے اور اس میں نماز پڑھتے تو لوگوں نے بھی آپ کی اقتدا میں نماز پڑھنی شروع کر دی آپ دن کے وقت اسے بچھا لیتے تھے ایک رات لو گ کثرت کے ساتھ جمع ہو گئے تو آپ نے فر ما یا : \" لوگو !اتنے اعمال کی پابندی کرو جتنے اعمال کی تم میں طاقت ہے کیونکہ ( اس وقت تک ) اللہ تعا لیٰ ( اجرو ثواب دینے سے رضی اللہ تعالیٰ عنہ نہیں اکتاتا حتیٰ کہ تم خود اکتا جاؤ اور یقیناًاللہ کے نزدیک زیادہ محبوب عمل وہی ہے جس پر ہمیشگی اختیار کی جا ئے چاہے وہ کمہو ۔ اور رسول اللہ صلی اللہ علیہ وسلم کے گھر والے جب کو ئی عمل کرتے تو اسے ہمیشہ بر قرار رکھتے ۔)","",{"u2":"سعید بن ابی نے ابو سلمہ (نم عبد الرحمان بن عوف)سے انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کی ایک چٹائی تھی آپ رات کو اس سے حجرہ بنا لیتے اور اس میں نماز پڑھتے تو لوگوں نے بھی آپ کی اقتدا میں نماز پڑھنی شروع کر دی آپ دن کے وقت اسے بچھا لیتے تھے ایک رات لو گ کثرت کے ساتھ جمع ہو گئے تو آپ نے فر ما یا:\"لوگو!اتنے اعمال کی پابندی کرو جتنے اعمال کی تم میں طاقت ہے کیونکہ (اس وقت تک) اللہ تعا لیٰ (اجرو ثواب دینے سے رضی اللہ تعالیٰ عنہ نہیں اکتاتا حتیٰ کہ تم خود اکتا جاؤ اور یقیناًاللہ کے نزدیک زیادہ محبوب عمل وہی ہے جس پر ہمیشگی اختیار کی جا ئے چاہے وہ کمہو۔ اور رسول اللہ صلی اللہ علیہ وسلم کے گھر والے جب کو ئی عمل کرتے تو اسے ہمیشہ بر قرار رکھتے۔"}],[1769,"سعد بن ابرا ہیم سے روایت ہے کہ انھوں نے ابو سلمہ سے سنا ، وہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے حدیث بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا : اللہ تعا لیٰ کو کو ن سا عمل زیادہ پسند ہے؟ آپ نے فر ما یا : \" جسے ہمیشہ کیا جا ئے اگر چہ کم ہو ۔","",{"u2":"سعد بن ابرا ہیم سے روایت ہے کہ انھوں نے ابو سلمہ سے سنا،وہ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے حدیث بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا: اللہ تعا لیٰ کو کو ن سا عمل زیادہ پسند ہے؟ آپ نے فر ما یا:\"جسے ہمیشہ کیا جا ئے اگر چہ کم ہو۔"}],[1770,"علقمہ سے روایت ہے کہا میں نے ام المومنین !عائشہ رضی اللہ تعالیٰ عنہا سے سوال کیا اور کہا ام المومنین !رسول اللہ صلی اللہ علیہ وسلم کے عمل کی کیفیت کیا تھی؟کیا آپ ( کسی خاص عمل کے لیے ) کچھ ایام مخصوص فر ما لیتے تھے؟انھوں نے فر ما یا : نہیں آپ کا عمل دائمی ہو تا تھا اور تم میں سے کو ن اس قدر استطاعت رکھتا ہے جتنی استطاعت رسول اللہ صلی اللہ علیہ وسلم میں تھی ؟","",{"u2":"علقمہ سے روایت ہے کہا میں نے ام المومنین!عائشہ رضی اللہ تعالیٰ عنہا سے سوال کیا اور کہا ام المومنین!رسول اللہ صلی اللہ علیہ وسلم کے عمل کی کیفیت کیا تھی؟کیا آپ(کسی خاص عمل کے لیے)کچھ ایام مخصوص فر ما لیتے تھے؟انھوں نے فر ما یا:نہیں آپ کا عمل دائمی ہو تا تھا اور تم میں سے کو ن اس قدر استطاعت رکھتا ہے جتنی استطاعت رسول اللہ صلی اللہ علیہ وسلم میں تھی؟"}],[1771,"قاسم بن محمد نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روا یت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \"\" اللہ تعا لیٰ کے ہاں محبوب ترین کا م وہ ہے جس پر ہمیشہ عمل کیا جا ئے اگرچہ وہ قلیل ہو ۔ ( قاسم بن محمد نے ) کہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا جب کو ئی عمل کرتیں تو اس کو لازم کر لیتی ۔","",{"u2":"قاسم بن محمد نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روا یت کی، انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"اللہ تعا لیٰ کے ہاں محبوب ترین کا م وہ ہے جس پر ہمیشہ عمل کیا جا ئے اگرچہ وہ قلیل ہو۔\n(قاسم بن محمد نے) کہا: حضرت عائشہ رضی اللہ تعالیٰ عنہا جب کو ئی عمل کرتیں تو اس کو لازم کر لیتی۔"}],[1772,"ابوبکر بن ابی شیبہ نے کہا : ہمیں ابن علیہ نے حدیث سنائی ، نیز زہیر بن حرب نے کہا : ہمیں اسماعیل نے حدیث سنائی ، ان دونوں ( ابن علیہ اور اسماعیل ) نے عبدالعزیز بن صہیب سے اور انھوں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے اور ( دیکھا کہ ) دو ستونوں کے درمیان ایک رسی لٹکی ہوئی ہے ۔ آپ صلی اللہ علیہ وسلم نے پوچھا : \" یہ کیا ہے؟صحابہ رضوان اللہ عنھم اجمعین کرام نے عرض کی : سیدہ زینب رضی اللہ تعالیٰ عنہا کی رسی ہے ، وہ نماز پڑھتی رہتی ہیں ، جب سست پڑتی ہیں یا تھک جاتی ہیں تو اس کو پکڑ لیتی ہیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اسے کھول دو ، ہرشخص نماز پڑھے جب تک ہشاش بشاش رہے ، جب سست پڑ جائے یا تھک جائے تو بیٹھ جائے ۔ \" زہیر کی روایت میں ( قعد کی بجائے ) \" فليقعد \" ہے ۔ یعنی ماضی کی بجائے امر کا صیغہ استعمال کیا ، مفہوم ایک ہی ہے ۔","",{"u2":"ابوبکر بن ابی شیبہ نے کہا:ہمیں ابن علیہ نے حدیث سنائی،نیز زہیر بن حرب نے کہا:ہمیں اسماعیل نے حدیث سنائی،ان دونوں(ابن علیہ اوراسماعیل) نے عبدالعزیز بن صہیب سے اور انھوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے اور(دیکھا کہ) دو ستونوں کے درمیان ایک رسی لٹکی ہوئی ہے۔آپ صلی اللہ علیہ وسلم نے پوچھا:\"یہ کیا ہے؟صحابہ رضوان اللہ عنھم اجمعین کرام نے عرض کی:حضرت زینب رضی اللہ تعالیٰ عنہا کی رسی ہے،وہ نماز پڑھتی رہتی ہیں،جب سست پڑتی ہیں یا تھک جاتی ہیں تو اس کو پکڑ لیتی ہیں۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"اسے کھول دو،ہرشخص نماز پڑھے جب تک ہشاش بشاش رہے،جب سست پڑ جائے یا تھک جائے تو بیٹھ جائے۔\"زہیر کی روایت میں(قعد کی بجائے) \"فلیقعد\" ہے۔یعنی ماضی کی بجائے امر کا صیغہ استعمال کیا،مفہوم ایک ہی ہے۔"}],[1773,"عبدالوارث نے عبدالعزیز ( بن صہیب ) سے ، انھوں نے سیدنا انس رضی اللہ تعالیٰ عنہا سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"عبدالوارث نے عبدالعزیز (بن صہیب) سے،انھوں نے حضرت انس رضی اللہ تعالیٰ عنہا سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[1774,"ابن شہاب نے کہا : مجھے عروہ بن زبیر نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے ا نھیں بتایا کہ حولا بنت تویت بن حبیب بن اسد بن عبدالعزیٰ اس عالم میں ان کے قریب سے گزری جب رسول اللہ صلی اللہ علیہ وسلم ان کے پاس تھے ، کہا : میں نے عرض کی : یہ حولا بنت تویت ہیں اور لوگوں کا خیال ہے کہ یہ رات بھر نہیں سوتیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ( کیا رات بھر نہیں سوتی!اتنا عمل اپنا ؤ جتنے کی تم طاقت رکھتے ہو ۔ اللہ کی قسم!اللہ نہیں اکتائے گا یہاں تک کہ تم اکتا جاؤ ۔)","",{"u2":"ابن شہاب نے کہا:مجھے عروہ بن زبیر نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کی زوجہ حضرت عائشہ رضی اللہ تعالیٰ عنہا نے ا نھیں بتایا کہ حولا بنت تویت بن حبیب بن اسد بن عبدالعزیٰ اس عالم میں ان کے قریب سے گزری جب رسول اللہ صلی اللہ علیہ وسلم ان کے پاس تھے،کہا:میں نے عرض کی:یہ حولا بنت تویت ہیں اور لوگوں کا خیال ہے کہ یہ رات بھر نہیں سوتیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:(کیا رات بھر نہیں سوتی!اتنا عمل اپنا ؤ جتنے کی تم طاقت رکھتے ہو۔اللہ کی قسم!اللہ نہیں اکتائے گا یہاں تک کہ تم اکتا جاؤ۔\""}],[1775,"ابو اسامہ اور یحییٰٰ بن سعید نے ہشام بن عروہ سے روایت کی ، انھوں نے کہا : مجھے میرے والد نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کرتے ہوئے خبر دی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور میرے پاس ایک خاتون موجود تھیں ، آپ نے پوچھا : \"\" یہ کون ہے؟ \"\" میں نے کہا : یہ ایسی عورت ہے جو رات بھر نہیں سوتی ، نماز پڑھتی رہتی ہے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اتنا عمل کرو جتنا تمہارے بس میں ہو ، اللہ کی قسم !اللہ نہیں اکتائے گا یہاں تک کہ تم ہی عمل سے اکتا جاؤ ۔ \"\" اللہ کے ہاں دین کا وہی عمل پسند ہے جس پر عمل کرنے والا ہمیشگی کرے ۔ ابو اسامہ کی روایت میں ہے ، یہ بنو اسد کی عورت تھی ۔","",{"u2":"ابو اسامہ اور یحییٰٰ بن سعید نے ہشام بن عروہ سے روایت کی،انھوں نے کہا: مجھے میرے والد نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کرتے ہوئے خبر دی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور میرے پاس ایک خاتون موجود تھیں،آپ نے پوچھا:\"یہ کون ہے؟\"میں نے کہا:یہ ایسی عورت ہے جو رات بھر نہیں سوتی،نماز پڑھتی رہتی ہے۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"اتنا عمل کرو جتنا تمہارے بس میں ہو،اللہ کی قسم!اللہ نہیں اکتائے گا یہاں تک کہ تم ہی عمل سے اکتا جاؤ۔\"اللہ کے ہاں دین کا وہی عمل پسند ہے جس پر عمل کرنے والا ہمیشگی کرے۔\nابو اسامہ کی روایت میں ہے،یہ بنو اسد کی عورت تھی۔"}],[1776,"سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے رویت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نےفرمایا : \" جب تم میں سے کوئی شخص نماز میں اونگھنے لگے تو وہ سوجائے حتیٰ کہ نیند جاتی رہے کیونکہ جب تم میں سے کوئی شخص اونگھ کی حالت میں نماز پڑھتاہے تو وہ ممکن ہے وہ استغفار کرنے چلے لیکن ( اس کی بجائے ) اپنے آپ کو برا بھلا کہنے لگے ،","",{"u2":"حضرت عائشہ رضی اللہ تعالیٰ عنہا سے رویت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نےفرمایا:\"جب تم میں سے کوئی شخص نماز میں اونگھنے لگے تو وہ سوجائے حتیٰ کہ نیند جاتی رہے کیونکہ جب تم میں سے کوئی شخص اونگھ کی حالت میں نماز پڑھتاہے تو وہ ممکن ہے وہ استغفار کرنے چلے لیکن (اس کی بجائے) اپنے آپ کو برا بھلا کہنے لگے،\""}],[1777,"ہمام بن منبہ نے کہا : یہ احادیث ہیں جو ابوہریرۃ رضی اللہ تعالیٰ عنہ نے ہمیں محمد رسول اللہ صلی اللہ علیہ وسلم کے واسطے بیان کی ہیں ، پھر ان میں سے کچھ احادیث ذکر کیں ، ان میں سے یہ بھی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص رات کو قیام کرے اور اس کی زبان پر قراءت مشکل ہوجائے اور اسے پتہ نہ چلے کہ وہ کیا کہہ رہا ہے تو اسے لیٹ جانا چاہیے ۔","",{"u2":"ہمام بن منبہ نے کہا:یہ احادیث ہیں جو ابوہریرۃ رضی اللہ تعالیٰ عنہ نے ہمیں محمد رسول اللہ صلی اللہ علیہ وسلم کے واسطے بیان کی ہیں،پھر ان میں سے کچھ احادیث ذکر کیں،ان میں سے یہ بھی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جب تم میں سے کوئی شخص رات کو قیام کرے اور اس کی زبان پر قراءت مشکل ہوجائے اور اسے پتہ نہ چلے کہ وہ کیا کہہ رہا ہے تو اسے لیٹ جانا چاہیے۔\""}],[1778,"ابواسامہ نے ہشام سے انھوں نے اپنے والد ( عروہ ) سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ایک آدمی کی قراءت سنی جو وہ رات کو کر رہا تھا تو فر ما یا : \" اللہ اس پر رحم فر ما ئے !اس نے مجھے فلاں آیت یاد دلا دی جس کی تلاوت فلاں سورت میں چھوڑ چکا تھا","",{"u2":"ابواسامہ نے ہشام سے انھوں نے اپنے والد (عروہ) سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ایک آدمی کی قراءت سنی جو وہ رات کو کر رہا تھا تو فر ما یا:\"اللہ اس پر رحم فر ما ئے!اس نے مجھے فلاں آیت یاد دلا دی جس کی تلاوت فلاں سورت میں چھوڑ چکا تھا"}],[1779,"عبد ہ اور ابو معاویہ نے ہشام سے انھوں نے اپنے والد ( عروہ ) سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا نبی صلی اللہ علیہ وسلم مسجد میں ایک آدمی کی قراءت سن رہے تھے تو آپ نے فر ما یا : \" اللہ اس پر رحم فر ما ئے ! اس نے مجھے ایک آیت یاد دلا دی ہے جو مجھے بھلا دی گئی تھی ۔","",{"u2":"1838عبد ہ اور ابو معاویہ نے ہشام سے انھوں نے اپنے والد (عروہ)سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا نبی صلی اللہ علیہ وسلم مسجد میں ایک آدمی کی قراءت سن رہے تھے تو آپ نے فر ما یا:\"اللہ اس پر رحم فر مائے اس نے مجھے ایک آیت یاد دلا دی ہے جو مجھے بھلا دی گئی تھی۔"}],[1780,"امام مالک نے نافع کے واسطے سے سیدنا عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا \" صاحب قرآن ( قرآن حفظ کرنے والے ) کی مثال پاؤں بندھے اونٹوں ( کے چرواہے ) کی مانند ہے اگر اس نے ان کی نگہداشت کی تو وہ انھیں قابو میں رکھے گا اور اگر انھیں چھوڑ دے گا تو وہ چلے جا ئیں گے ۔","",{"u2":"امام مالک نے نافع کے واسطے سے حضرت عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا \"صاحب قرآن (قرآن حفظ کرنے والے)کی مثال پاؤں بندھے اونٹوں (کے چرواہے) کی مانند ہے اگر اس نے ان کی نگہداشت کی تو وہ انھیں قابو میں رکھے گا اور اگر انھیں چھوڑ دے گا تو وہ چلے جا ئیں گے۔\""}],[1781,"عبید اللہ ایوب اور موسیٰ بن عقبہ سب نے ( جن تک سندوں کے مختلف سلسلے پہنچے ) نافع سے انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے مالک کی حدیث کے ہم معنی روایت بیان کی اور موسیٰ بن عقبہ کی روایت میں یہ اضافہ ہے : \" جب صاحب قرآن قیام کرے گا اور رات دن اس کی قراءت کرے گا تو وہ اسے یاد رکھے گا اور جب اس ( کی قراءت ) کے ساتھ قیام نہیں کرے گا تو وہ اسے بھول جا ئے گا ۔","",{"u2":"1840عبید اللہ ایوب اور موسیٰ بن عقبہ سب نے (جن تک سندوں کے مختلف سلسلے پہنچے) نافع سے انھوں نے حضڑت ابن عمر رضی اللہ تعالیٰ عنہ سے مالک کی حدیث کے ہم معنی روایت بیان کی اور موسیٰ بن عقبہ کی روایت میں یہ اضافہ ہے:\"جب صاحب قرآن قیام کرے گا اور رات دن اس کی قراءت کرے گا تو وہ اسے یاد رکھے گا اور جب اس (کی قراءت) کے ساتھ قیام نہیں کرے گا تو وہ اسے بھول جا ئے گا۔"}],[1782,"منصور نے ابو وائل ( شفیق بن سلمہ ) سے اور انھوں نے سیدنا عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" کسی بھی انسان کے لیے انتہائی ناز یبا بات ہے کہ وہ کہے ۔ میں فلاں فلاں آیت بھول گیا ہوں بلکہ وہ بھوادیا گیا ہے قرآن کو یاد کرتے رہو کیونکہ وہ لو گوں کے سینوں سے دور بھاگنے میں رسیوں سمیت بھا گ جا نے والے اونٹوں سے بھی بڑھ کر ہے ۔","",{"u2":"منصور نے ابو وائل (شفیق بن سلمہ) سے اور انھوں نے حضڑت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"کسی بھی انسان کے لیے انتہائی ناز یبا بات ہے کہ وہ کہے۔ میں فلاں فلاں آیت بھول گیا ہوں بلکہ وہ بھوادیا گیا ہے قرآن کو یاد کرتے رہو کیونکہ وہ لو گوں کے سینوں سے دور بھاگنے میں رسیوں سمیت بھا گ جا نے والے اونٹوں سے بھی بڑھ کر ہے۔"}],[1783,"اعمش نے شفیق بن سلمہ سے روا یت کی انھوں نے کہا ۔ سیدنا عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ کہا ان مصاحف ۔ ۔ اور کبھی کہا : قرآن ۔ ۔ کے ساتھ تجدید عہد کرتے رہا کرو کیونکہ وہ انسانوں کے سینوں سے بھا گ جا نے میں اپنے پاؤں کی رسیوں سے نکل بھاگنے والے اونٹوں سے بھی بڑھ کر ہے کہا : اور رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا ہے ۔ \" تم میں سے کسی کو یہ نہیں کہنا چا ہیے کہ میں فلا ں فلا ں آیت بھول گیا ہوں بلکہ اسے بھلوا دیا گیا ہے ۔","",{"u2":"اعمش نے شفیق بن سلمہ سے روا یت کی انھوں نے کہا۔حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ کہا ان مصاحف۔۔اور کبھی کہا:قرآن۔۔کے ساتھ تجدید عہد کرتے رہا کرو کیونکہ وہ انسانوں کے سینوں سے بھا گ جا نے میں اپنے پاؤں کی رسیوں سے نکل بھاگنے والے اونٹوں سے بھی بڑھ کر ہے کہا:اور رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا ہے۔\"تم میں سے کسی کو یہ نہیں کہنا چا ہیے کہ میں فلا ں فلا ں آیت بھول گیا ہوں بلکہ اسے بھلوا دیا گیا ہے۔"}],[1784,"عبدہ بن ابی لبابہ نے شفیق بن سلمہ سے روایت کی انھوں نے کہا : میں نے سیدنا عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کو کہتے ہو ئے سنا انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے ہو ئے سنا : \" کسی آدمی کے لیے یہ بہت بری بات ہے کہ وہ کہے میں فلا ں فلاں سورت بھول گیا یا فلا ں فلاں آیت بھول گیا بلکہ اسے بھلوا دیا گیا ہے ۔","",{"u2":"عبدہ بن ابی لبابہ نے شفیق بن سلمہ سے روایت کی انھوں نے کہا: میں نے حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کو کہتے ہو ئے سنا انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے ہو ئے سنا:\"کسی آدمی کے لیے یہ بہت بری بات ہے کہ وہ کہے میں فلا ں فلاں سورت بھول گیا یا فلا ں فلاں آیت بھول گیا بلکہ اسے بھلوا دیا گیا ہے۔"}],[1785,"عبد اللہ بن براد اشعری اور ابو کریب نے کہا ہمیں ابو اسامہ نے برید سے انھوں نے ابو بردہ سے انھوں نے سیدنا ابو موسیٰ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے حدیث بیان کی آپ صلی اللہ علیہ وسلم نے فر ما یا : \" قرآن کی نگہداشت کرو اس ذات کی قسم جس کے ہاتھ میں محمد ( صلی اللہ علیہ وسلم ) کی جا ن ہے ! یہ بھا گنے میں پاؤں بندھے اونٹؤں سے بڑھ کر ہے ۔ اس حدیث کے الفاظ ابن براد ( کی روایت ) کے ہیں ۔","",{"u2":"عبد اللہ بن براد اشعری اور ابو کریب نے کہا ہمیں ابو اسامہ نے برید سے انھوں نے ابو بردہ سے انھوں نے حضرت ابو موسیٰ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے حدیث بیان کی آپ صلی اللہ علیہ وسلم نے فر ما یا:\"قرآن کی نگہداشت کرو اس ذات کی قسم جس کے ہاتھ میں محمد (صلی اللہ علیہ وسلم) کی جا ن ہے! یہ بھا گنے میں پاؤں بندھے اونٹؤں سے بڑھ کر ہے۔اس حدیث کے الفاظ ابن براد(کی روایت) کے ہیں۔"}],[1786,"سفیان بن عیینہ نے زہری سے انھوں نے ابو سلمہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی وہ اس ( فر ما ن ) کو نبی صلی اللہ علیہ وسلم تک پہنچا تے تھے آپ صلی اللہ علیہ وسلم نے فر ما یا : \" اللہ تعا لیٰ نے ( کبھی ) کسی چیز پر اس قدر کان نہیں دھرا ( توجہ سے نہیں سنا ) جتنا کسی خوش آواز نبی ( کی آواز ) پر کان دھرا جس نے خوش الحانی سے قراءت کی ۔","",{"u2":"سفیان بن عیینہ نے زہری سے انھوں نے ابو سلمہ سے اور انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی وہ اس (فر ما ن) کو نبی صلی اللہ علیہ وسلم تک پہنچا تے تھے آپ صلی اللہ علیہ وسلم نے فر ما یا:\"اللہ تعا لیٰ نے (کبھی)کسی چیز پر اس قدر کان نہیں دھرا (توجہ سے نہیں سنا) جتنا کسی خوش آواز نبی (کی آواز) پر کان دھرا جس نے خوش الحانی سے قراءت کی۔"}],[1787,"یونس اور عمر ( بن حارث ) دونوں نے ابن شہاب سے اسی سند کے ساتھ یہ روایت کی اس میں ) ما اذن لنبي کے بجا ئے ) كما ياذن لنبي ( جس طرح ایک نبی کے لیے کان دھرتا ہے جو خوش الحانی سے قراءت کررہا ہو ۔ ) کے الفاظ ہیں","",{"u2":"یونس اور عمر (بن حارث) دونوں نے ابن شہاب سے اسی سند کے ساتھ یہ روایت کی اس میں) ما اذن لنبی کے بجا ئے)کما یاذن لنبی(جس طرح ایک نبی کے لیے کان دھرتا ہے جو خوش الحانی سے قراءت کررہا ہو۔) کے الفاظ ہیں"}],[1788,"عبد العزیز بن محمد نے کہا : یزید بن ہاد نے ہمیں محمد بن ابرا ہیم سے حدیث بیان کی انھوں نے ابو سلمہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے ہوئے سنا : اللہ تعا لیٰ نے ( کبھی ) کسی چیز پر اس طرح کان نہیں دھرا جس طرح کسی خوش آواز نبی ( کی قراءت ) پر جب وہ بلند آواز کے ساتھ خوش الحانی سے قراءت کرے ۔","",{"u2":"عبد العزیز بن محمد نے کہا: یزید بن ہاد نے ہمیں محمد بن ابرا ہیم سے حدیث بیان کی انھوں نے ابو سلمہ سے اور انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے ہوئے سنا: اللہ تعا لیٰ نے (کبھی) کسی چیز پر اس طرح کان نہیں دھرا جس طرح کسی خوش آواز نبی (کی قراءت) پر جب وہ بلند آواز کے ساتھ خوش الحانی سے قراءت کرے۔"}],[1789,"عمر بن مالک اور حیوہ بن شریح نے ابن ہاد سے اسی سند کے ساتھ بالکل اس جیسی روا یت بیان کی اور انھوں نے ( ان رسول اللہ ) ( بے شک رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا ) کہا اور سَمِعَ ( اس نے سنا ) کا لفظ نہیں بولا ۔","",{"u2":"عمر بن مالک اور حیوہ بن شریح نے ابن ہاد سے اسی سند کے ساتھ بالکل اس جیسی روا یت بیان کی اور انھوں نے (ان رسول اللہ)(بے شک رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا) کہا اور سَمِعَ (اس نے سنا)کا لفظ نہیں بولا۔"}],[1790,"حییٰ بن ابی کثیرؒ نے ابو سلمہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر مایا : اللہ تعا لیٰ نے ( کبھی ) کسی چیز پر اس طرح کا ن نہیں دھرا جیسے وہ نبی صلی اللہ علیہ وسلم ( کی آواز ) پر کا ن دھرتا ہے جو بلند آواز کے ساتھ خوش الحانی سے قراءت کرتا ہے ۔","",{"u2":"حییٰ بن ابی کثیر رحمہ اللہ نے ابو سلمہ سے اور انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فر مایا: اللہ تعا لیٰ نے (کبھی) کسی چیز پر اس طرح کا ن نہیں دھرا جیسے وہ نبی صلی اللہ علیہ وسلم (کی آواز) پر کا ن دھرتا ہے جو بلند آواز کے ساتھ خوش الحانی سے قراءت کرتا ہے۔\""}],[1791,"یحییٰ بن ایوب قتیبہ بن سعید اور ابن حجر نے کہا : ہمیں اسماعیل بن جعفر نے محمد بن عمرو سے حدیث بیان کی انھوں نے ابو سلمہ سے انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے یحییٰ بن ابی کثیر کی حدیث کی طرح روا یت بیان کی مگر ابن ایوب نے اپنی روا یت میں ( كاذنه کے بجا ئے ) كاذنه ( جس طرح وہ اجازت دیتا ہے ) کہا ۔ اس ( طرح ما اذن اللہ کا معنی ہو گا اللہ تعا لیٰ نے ( بار یابی کی اجازت نہیں دی ۔)","",{"u2":"یحییٰ بن ایوب قتیبہ بن سعید اور ابن حجر نے کہا: ہمیں اسماعیل بن جعفر نے محمد بن عمرو سے حدیث بیان کی انھوں نے ابو سلمہ سے انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے یحییٰ بن ابی کثیر کی حدیث کی طرح روا یت بیان کی مگر ابن ایوب نے اپنی روا یت میں(کاذنہ کے بجا ئے) کاذنہ (جس طرح وہ اجازت دیتا ہے) کہا۔اس(طرح ما اذن اللہ کا معنی ہو گا اللہ تعا لیٰ نے (بار یابی کی اجازت نہیں دی۔"}],[1792,"سیدنا برید رضی اللہ تعالیٰ عنہ سے روا یت ہے انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" عبد اللہ بن قیس ۔ ۔ یا اشعری ۔ ۔ ۔ کو آل داود کی بنسریوں ( خوبصورت آوازوں ) میں سے ایک بنسری ( خوبصورت آواز ) عطاکی گئی ہے","",{"u2":"حضرت برید رضی اللہ تعالیٰ عنہ سے روا یت ہے انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"عبد اللہ بن قیس۔۔یا اشعری۔۔۔کو آل داودکی بنسریوں (خوبصورت آوازوں) میں سے ایک بنسری (خوبصورت آواز) عطاکی گئی ہے"}],[1793,"(سیدنا ابو موسیٰ اشعری رضی اللہ تعالیٰ عنہ سے روا یت ہے انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فر ما یا ) : کیا ہی خوب ہو تا ) کاش! تم مجھے دیکھتے جب گزشتہ رات میں بڑے انہماک سے تمھاری قراءت سن رہا تھا تمھیں آل داؤد کی خوبصورت آوازوں میں سے ایک خوبصورت آوازدی گئی ہے ۔","",{"u2":"حضرت ابو موسیٰ اشعری رضی اللہ تعالیٰ عنہ سے روا یت ہے انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فر ما یا):کیا ہی خوب ہو تا)کاش! تم مجھے دیکھتے جب گزشتہ رات میں بڑے انہماک سے تمھاری قراءت سن رہا تھا تمھیں آل داؤدکی خوبصورت آوازوں میں سے ایک خوبصورت آوازدی گئی ہے۔"}],[1794,"عبداللہ بن ادریس اور وکیع نے شعبہ سے اور انھوں نے معاویہ بن قرہ سے روایت کی ، انھوں نے کہا : میں نے عبداللہ بن مغفل مزنی رضی اللہ تعالیٰ عنہ سے سنا ، وہ کہہ رہے تھے : نبی اکرم صلی اللہ علیہ وسلم نے فتح مکہ والے سال اپنے سفر میں اپنی سواری پر سورہ فتح کی تلاوت فرمائی اور اپنی قراءت میں آواز کو دہرایا ۔ معاویہ نے کہا : اگر مجھے یہ اندیشہ نہ ہوتا کہ لوگ میرے گرد جمع ہوجائیں گے تو میں تمھیں آپ صلی اللہ علیہ وسلم جیسی قراء ت سناتا ۔","",{"u2":"عبداللہ بن ادریس اور وکیع نے شعبہ سے اور انھوں نے معاویہ بن قرہ سے روایت کی،انھوں نے کہا:میں نے عبداللہ بن مغفل مزنی رضی اللہ تعالیٰ عنہ سے سنا،وہ کہہ رہے تھے:نبی اکرم صلی اللہ علیہ وسلم نے فتح مکہ والے سال اپنے سفر میں اپنی سواری پر سورہ فتح کی تلاوت فرمائی اور اپنی قراءت میں آواز کو دہرایا۔\nمعاویہ نے کہا:اگر مجھے یہ اندیشہ نہ ہوتا کہ لوگ میرے گرد جمع ہوجائیں گے تو میں تمھیں آپ صلی اللہ علیہ وسلم جیسی قراء ت سناتا۔"}],[1795,"محمد بن جعفر نے کہا : شعبہ نے ہمیں معاویہ بن قرہ سے حدیث بیان کی ، انھوں نے کہا : میں نے سیدنا عبداللہ بن مغفل سے سنا ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فتح مکہ کے دن اپنی اونٹنی پر ( سوار ) سورہ فتح پڑھتے ہوئے دیکھا ۔ ( معاویہ بن قرہ نے ) کہا : سیدنا ابن مغفل رضی اللہ تعالیٰ عنہ نے قراءت کی اور اس میں ترجیع کی ، معاویہ نے کہا : اگر مجھے لوگوں ( کے اکھٹے ہوجانے ) کا اندیشہ نہ ہوتا تو میں تمھارے لئے ( قراءت کا ) وہی ( طریقہ اختیار ) کرتا جو سیدنا ابن مغفل رضی اللہ تعالیٰ عنہ نے نبی اکرم صلی اللہ علیہ وسلم کے حوالے سے بیان کیا تھا ۔","",{"u2":"محمد بن جعفر نے کہا:شعبہ نے ہمیں معاویہ بن قرہ سے حدیث بیان کی،انھوں نے کہا:میں نے حضرت عبداللہ بن مغفل سے سنا،انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فتح مکہ کے دن اپنی اونٹنی پر(سوار) سورہ فتح پڑھتے ہوئے دیکھا۔(معاویہ بن قرہ نے)کہا:حضرت ابن مغفل رضی اللہ تعالیٰ عنہ نےقراءت کی اور اس میں ترجیع کی،معاویہ نے کہا:اگر مجھے لوگوں(کے اکھٹے ہوجانے) کا اندیشہ نہ ہوتا تو میں تمھارے لئے(قراءت کا) وہی (طریقہ اختیار) کرتا جو حضرت ابن مغفل رضی اللہ تعالیٰ عنہ نے نبی اکرم صلی اللہ علیہ وسلم کے حوالے سے بیان کیا تھا۔"}],[1796,"خالد بن حارث اور معاذ نے کہا : شعبہ نے ہمیں اسی سند کے ساتھ اسی طرح کی حدیث بیان کی ، خالد بن حارث کی روایت میں ہے کہ آپ صلی اللہ علیہ وسلم ( سورہ فتح تلاوت کرتے ہوئے اپنی ) سواری پر سفر کررہے تھے ۔","",{"u2":"خالد بن حارث اور معاذ نے کہا:شعبہ نے ہمیں اسی سند کے ساتھ اسی طرح کی حدیث بیان کی،خالد بن حارث کی روایت میں ہے کہ آپ صلی اللہ علیہ وسلم (سورہ فتح تلاوت کرتے ہوئے اپنی)سواری پر سفر کررہے تھے۔"}],[1797,"ابو خثیمہ نے ابو اسحاق سے اور انھوں نے سیدنا بر اء رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ایک آدمی سورہ کہف کی تلاوت کررہاتھا اور اس کے پاس ہی دو رسیوں میں بندھا ہوا گھوڑا ( موجود ) تھا ۔ تو اسے ایک بدلی نے ڈھانپ لیا ۔","",{"u2":"ابو خثیمہ نے ابو اسحاق سے اور انھوں نے حضرت بر اء رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:ایک آدمی سورہ کہف کی تلاوت کررہاتھا اور اس کے پاس ہی دو رسیوں میں بندھا ہواگھوڑا(موجود)تھا۔تو اسے ایک بدلی نے ڈھانپ لیا۔"}],[1798,"محمد بن جعفر نے کہا : ہم سے شعبہ نے ابو اسحاق سے حدیث بیان کی ۔ انھوں نے کہا : میں نے سیدنا براء رضی اللہ تعالیٰ عنہ سے سنا وہ کہہ رہے تھے : ایک آدمی نے سورہ کہف کی قراءت کی ۔ گھر میں ( اس وقت ) ایک چوپا یہ بھی تھا ۔ وہ بدکنے لگا اس شخص نے دیکھا کہ جا نور کے اوپر دھندیا بدلی تھی جو اس پر چھائی ہو ئی ہے تو اس نے یہ واقعہ نبی اکرم صلی اللہ علیہ وسلم کو بتایا آپ نے فر ما یا : اے شخص ! پڑھا کرو یہ تو سکینت تھی جو قراءت کے وقت اتری ( یا قرآن کی خاطر نازل ہو ئی ۔)","",{"u2":"محمد بن جعفر نے کہا:ہم سے شعبہ نے ابو اسحاق سے حدیث بیان کی۔انھوں نے کہا: میں نے حضرت براء رضی اللہ تعالیٰ عنہ سے سنا وہ کہہ رہے تھے:ایک آدمی نے سورہ کہف کی قراءت کی۔ گھرمیں(اس وقت) ایک چوپا یہ بھی تھا۔وہ بدکنے لگا اس شخص نے دیکھا کہ جا نور کے اوپر دھندیا بدلی تھی جو اس پر چھائی ہو ئی ہے تو اس نے یہ واقعہ نبی اکرم صلی اللہ علیہ وسلم کو بتایا آپ نے فر ما یا: اے شخص! پڑھا کرو یہ تو سکینت تھی جو قراءت کے وقت اتری (یا قرآن کی خاطر نازل ہو ئی۔)"}],[1799,"عبد الرحمٰن بن مہدی اور داؤد نے کہا : ہمیں شعبہ نے ابو اسحاق سے حدیث بیان کی انھوں نے کہا : میں نے سیدنا براء رضی اللہ تعالیٰ عنہ کو کہتے ہو ئے سنا ۔ ۔ ۔ آگے دونوں ( عبد الرحمٰن بن مہدی اور ابوداؤد ) نے سابقہ حدیث کے مانند ذکر کیا ۔ البتہ اتنا فرق ہے کہ انھوں نے ( تنفر \" وہ بدکنے لگا \" کے بجا ئے ) تنقز ( وہ اچھلنے لگا ) کہا","",{"u2":"عبد الرحمٰن بن مہدی اور داؤد نے کہا: ہمیں شعبہ نے ابو اسحاق سے حدیث بیان کی انھوں نے کہا: میں نے حضرت براء رضی اللہ تعالیٰ عنہ کو کہتے ہو ئے سنا۔۔۔آگے دونوں (عبد الرحمٰن بن مہدی اور ابوداؤد) نے سابقہ حدیث کے مانند ذکر کیا۔ البتہ اتنا فرق ہے کہ انھوں نے (تنفر\"وہ بدکنے لگا \" کے بجا ئے) تنقز(وہ اچھلنے لگا) کہا"}],[1800,"سیدنا ابو سعید خدری رضی اللہ تعالیٰ عنہ نے حدیث بیان کی کہ حجرت اسید بن حضیر رضی اللہ تعالیٰ عنہ ایک رات اپنے باڑے میں قراءت کر رہے تھے کہ اچانک ان کا گھوڑا بدکنے لگا انھوں نے پھر پڑھا وہ دوبارہ بدکا پھر پڑھا وہ پھر بدکا ۔ اسید رضی اللہ تعالیٰ عنہ نے کہا : مجھے خوف پیدا ہوا کہ وہ ( میرے بیٹے ) یحییٰ کو روند ڈالے گا میں اٹھ کر اس کے پاس گیا تو اچانک چھتری جیسی کو ئی چیز میرے سر پر تھی اس میں کچھ چراغوں جیسا تھا وہ فضا میں بلند ہو گئی حتیٰ کہ مجھے نظر آنا بند ہو گئی کہا : میں صبح کو رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا اور عرض کی : اے اللہ کے رسول !اس اثنا میں کہ کل میں آدھی رات کے وقت اپنے باڑے میں قراءت کر رہا تھا کہ اچانک میرا گھوڑا بدکنے لگا ۔ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : ابن حضیر!پڑھتے رہتے ۔ \" میں نے عرض کی : میں پڑھتا رہا پھر اس نے دوبارہ اچھل کود کی ۔ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : ابن حضیر! پڑھتے رہتے ۔ میں نے کہا : میں نے قراءت جاری رکھی اس نے کچھ بدک کر چکر لگانے شروع کر دیے ۔ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" ابن حضیر! پڑھتے رہتے ۔ میں نے کہا : پھر میں نے چھوڑ دیا ۔ ( میرا بیٹا ) یحییٰ اس کے قریب تھا میں ڈر گیا کہ وہ اسے روند دے گا ۔ تو میں چھتری جیسی چیز دیکھی اس میں چراغوں کی طرح کی چیزیں تھیں وہ فضا میں بلند ہو ئی حتیٰ کہ مجھے نظر آنی بند ہو گئی اس پر رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" وہ فرشتے تھے جو تمھاری قراءت سن رہے تھے اور اگر تم پڑھتے رہتے تو لوگ صبح کو دیکھ لیتے وہ ان سے اوجھل نہ ہوتے ۔","",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالیٰ عنہ نے حدیث بیان کی کہ حجرت اسید بن حضیر رضی اللہ تعالیٰ عنہ ایک رات اپنے باڑے میں قراءت کر رہے تھے کہ اچانک ان کا گھوڑا بدکنے لگا انھوں نے پھر پڑھا وہ دوبارہ بدکا پھر پڑھا وہ پھر بدکا۔اسید رضی اللہ تعالیٰ عنہ نے کہا: مجھے خوف پیدا ہوا کہ وہ (میرے بیٹے) یحییٰ کو روند ڈالے گا میں اٹھ کر اس کے پاس گیا تو اچانک چھتری جیسی کو ئی چیز میرے سر پر تھی اس میں کچھ چراغوں جیسا تھا وہ فضا میں بلند ہو گئی حتیٰ کہ مجھے نظر آنا بند ہو گئی کہا: میں صبح کو رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا اور عرض کی:اے اللہ کے رسول!اس اثنا میں کہ کل میں آدھی رات کے وقت اپنے باڑے میں قراءت کر رہا تھا کہ اچانک میرا گھوڑا بدکنے لگا۔رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا: ابن حضیر!پڑھتے رہتے۔\"میں نے عرض کی: میں پڑھتا رہا پھر اس نے دوبارہ اچھل کود کی۔رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا: ابن حضیر! پڑھتے رہتے۔میں نے کہا: میں نے قراءت جاری رکھی اس نے کچھ بدک کر چکر لگانے شروع کر دیے۔ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"ابن حضیر! پڑھتے رہتے۔میں نے کہا: پھر میں نے چھوڑ دیا۔(میرا بیٹا) یحییٰ اس کے قریب تھا میں ڈر گیا کہ وہ اسے روند دے گا۔تو میں چھتری جیسی چیز دیکھی اس میں چراغوں کی طرح کی چیزیں تھیں وہ فضا میں بلند ہو ئی حتیٰ کہ مجھے نظر آنی بند ہو گئی اس پر رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"وہ فرشتے تھے جو تمھاری قراءت سن رہے تھے اور اگر تم پڑھتے رہتے تو لوگ صبح کو دیکھ لیتے وہ ان سے اوجھل نہ ہوتے۔"}],[1801,"(ابو عوانہ نے قتادہ سے انھوں نے سیدنا انس ) سے انھوں نے سیدنا ابو موسیٰ اشعری رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : اس مومن کی مثال جو قرآن مجید کی تلاوت کرتا ہے نارنگی کی سی ہے اس کی خوشبو بھی عمدہ ہے اور اس کا ذائقہ ( بھی خوشگوار ہے اور اس مومن کی مثال جو قرآن مجید کی تلاوت نہیں کرتا کھجور کی سی ہے اس کی خوشبو نہیں ہو تی جبکہ اس کا ذائقہ شیریں ہے اور اس منافق کی مثال جو قرآن کی تلاوت کرتا نیاز بو جیسی ہے اس کی خوشبو عمدہ ہے اور ذائقہ کڑوا ہے اور اس منافق کی مثال جو قرآن نہیں پڑھتا اندر ائن ( تمے ) کی طرح ہے جس کی خوشبو بھی نہیں ہو تی اور اس کا ذائقہ ( بھی سخت ) کڑوا ہے ۔","",{"u2":"ابو عوانہ نے قتادہ سے انھوں نے حضرت انس) سے انھوں نے حضرت ابو موسیٰ اشعری رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:اس مومن کی مثال جو قرآن مجید کی تلاوت کرتا ہے نارنگی کی سی ہے اس کی خوشبوبھی عمدہ ہے اور اس کا ذائقہ (بھی خوشگوار ہے اور اس مومن کی مثال جو قرآن مجید کی تلاوت نہیں کرتا کھجور کی سی ہے اس کی خوشبو نہیں ہو تی جبکہ اس کا ذائقہ شیریں ہے اور اس منافق کی مثال جو قرآن کی تلاوت کرتا نیاز بو جیسی ہے اس کی خوشبوعمدہ ہے اور ذائقہ کڑوا ہے اور اس منافق کی مثال جو قرآن نہیں پڑھتا اندر ائن (تمے) کی طرح ہے جس کی خوشبو بھی نہیں ہو تی اور اس کا ذائقہ (بھی سخت) کڑوا ہے۔"}],[1802,"ہمام اور شعبہ نے قتادہ سے اسی سند کے ساتھ اسی کی طرح حدیث روایت کی ۔ اس میں یہ فرق ہے کہ ہمام کی روایت میں منا فق کی جگہ فاجر ( بدکردار ) کا لفظ ہے ۔","",{"u2":"ہمام اور شعبہ نے قتادہ سے اسی سند کے ساتھ اسی کی طرح حدیث روایت کی۔اس میں یہ فرق ہے کہ ہمام کی روایت میں منا فق کی جگہ فاجر (بدکردار) کا لفظ ہے۔"}],[1803,"ابو عوانہ نے قتادہؒ سے روایت کی ، انھوں نے زراہ بن اوفیٰ ( عامری ) سے ، انھوں نے سعد بن ہشام سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قرآن مجید کا مہر قرآن لکھنے والے انتہائی معزز اور اللہ تعالیٰ کے فرمانبردار فرشتوں کے ساتھ ہوگا اور جو انسان قرآن مجیدپڑھتاہے اور ہکلاتا ہے ۔ اور وہ ( پڑھنا ) اس کے لئے مشقت کا باعث ہے ، اس کے لئے دو اجر ہیں ۔","",{"u2":"ابو عوانہ نے قتادہ رحمہ اللہ سے روایت کی،انھوں نے زراہ بن اوفیٰ (عامری) سے،انھوں نےسعد بن ہشام سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"قرآن مجید کا مہر قرآن لکھنے والے انتہائی معزز اور اللہ تعالیٰ کے فرمانبردار فرشتوں کے ساتھ ہوگا اور جو انسان قرآن مجیدپڑھتاہے اور ہکلاتا ہے۔اور وہ(پڑھنا)اس کے لئے مشقت کا باعث ہے،اس کے لئے دو اجر ہیں۔\""}],[1804,"ابن ابی عدی نے سعید سے روایت کی ، وکیع نے ہشام دستوائی سے روایت کی ، ان دونوں نے قتادہ سے اسی سند کے ساتھ حدیث بیان کی البتہ وکیع کی حدیث میں یہ الفاظ ہیں : \" جو اسے پڑھتا ہے اور وہ اس پر گراں ہوتا ہے ، اس کے لئے دو اجر ہیں ۔","",{"u2":"ابن ابی عدی نے سعید سے روایت کی،وکیع نے ہشام دستوائی سے روایت کی،ان دونوں نے قتادہ سے اسی سند کے ساتھ حدیث بیان کی البتہ وکیع کی حدیث میں یہ الفاظ ہیں:\"جو اسے پڑھتا ہے اور وہ اس پر گراں ہوتا ہے،اس کے لئے دو اجر ہیں۔\""}],[1805,"ہمام نےکہا : ہم سے قتادہ نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا ابی رضی اللہ تعالیٰ عنہ سے فرمایا : \" اللہ تعالیٰ نے مجھے حکم دیا ہے کہ میں تمھارے سامنے قراءت کروں ۔ \" انھوں نےکہا : کیا اللہ تعالیٰ نے آپ کے سامنے میرا نام لیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالیٰ نے میرے سامنے تمہارا نام لیا ۔ \" تو سیدنا ابی رضی اللہ تعالیٰ عنہ رونے لگے ۔","",{"u2":"ہمام نےکہا:ہم سے قتادہ نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت ابی رضی اللہ تعالیٰ عنہ سے فرمایا:\"اللہ تعالیٰ نے مجھے حکم دیا ہے کہ میں تمھارے سامنے قراءت کروں۔\"انھوں نےکہا:کیا اللہ تعالیٰ نے آپ کے سامنے میرا نام لیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"اللہ تعالیٰ نے میرے سامنے تمہارا نام لیا۔\" تو حضرت ابی رضی اللہ تعالیٰ عنہ رونے لگے۔"}],[1806,"محمد بن جعفر نے کہا : ہم سے شعبہ نے حدیث بیان کی ، انھوں نے کہا : میں نے قتادہ کو سیدنا انس رضی اللہ تعالیٰ عنہ سے حدیث بیان کرتے سنا ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ابی بن کعب رضی اللہ تعالیٰ عنہ سے فرمایا : \" اللہ تعالیٰ نے حکم دیا ہے کہ میں تمہارے سامنےلَمْ «يَكُنِ الَّذِينَ» كَفَرُ‌وا کی قراءت کروں ۔ \" انھوں نے کہا : اور ( اللہ تعالیٰ نے ) آپ کے سامنے میرا نام لیا ہے؟آپ نے فرمایا : \" ہاں ۔ \" ( انس رضی اللہ تعالیٰ عنہ نے ) کہا : تو وہ رودیئے ۔","",{"u2":"محمد بن جعفر نے کہا:ہم سے شعبہ نے حدیث بیان کی،انھوں نے کہا:میں نے قتادہ کو حضرت انس رضی اللہ تعالیٰ عنہ سے حدیث بیان کرتے سنا،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے ابی بن کعب رضی اللہ تعالیٰ عنہ سے فرمایا:\"اللہ تعالیٰ نے حکم دیا ہے کہ میں تمہارے سامنےلَمْ یَکُنِ الَّذِینَ کَفَرُ‌وا کی قراءت کروں۔\"انھوں نے کہا:اور (اللہ تعالیٰ نے) آپ کے سامنے میرا نام لیا ہے؟آپ نے فرمایا:\"ہاں۔\"(انس رضی اللہ تعالیٰ عنہ نے) کہا:تو وہ رودیئے۔"}],[1807,"خالد بن حارث نے کہا : شعبہ نے ہمیں قتادہ کے حوالے سے حدیث بیان کی ، انھوں نے کہا : میں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے سنا ، وہ کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے ابی رضی اللہ تعالیٰ عنہ سے کہا ۔ ۔ ۔ ( آگے سابقہ حدیث ) کے مانند ہے ۔"],[1808,"حفص بن غیاث نے اعمش سے روایت کی ، انھوں نے ابراہیم سے ، انھوں عبیدہ ( سلمانی ) سے اور انھوں نے عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \" میرے سامنے قرآن مجید کی قراءت کرو ۔ \" انھوں نے کہا : میں نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم ! کیا میں آپ کو سناؤں ، جبکہ آپ پر ہی تو ( قرآن مجید ) نازل ہوا ہے؟آپ نے فرمایا : \" میری خواہش ہے کہ میں اسے کسی دوسرے سے سنوں ۔ \" تو میں نے سورہ نساء کی قراءت شروع کی ، جب میں اس آیت پر پہنچا : «فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَىٰ» هَـٰؤُلَاءِ شَهِيدًا \" اس وقت کیا حال ہوگا ، جب ہم ہر امت میں سے ایک گواہ لائیں گے اور آپ کو ان پر گواہ بنا کرلائیں گے ۔ \" تو میں نے اپنا سر اٹھایا ، یا میرے پہلو میں موجود آدمی نے مجھے ٹھوکا دیا تو میں نے اپنا سر اٹھایا ، میں نے دیکھا کہ آپ صلی اللہ علیہ وسلم کے آنسو بہہ رہے تھے ۔","",{"u2":"حفص بن غیاث نے اعمش سے روایت کی،انھوں نے ابراہیم سے،انھوں عبیدہ (سلمانی) سےاور انھوں نے عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا:\"میرے سامنے قرآن مجید کی قراءت کرو۔\"انھوں نے کہا:میں نے عرض کی:اے اللہ کے رسول صلی اللہ علیہ وسلم! کیا میں آپ کو سناؤں،جبکہ آپ پر ہی تو (قرآن مجید) نازل ہوا ہے؟آپ نے فرمایا:\" میری خواہش ہے کہ میں اسےکسی دوسرے سے سنوں۔\"تو میں نے سورہ نساء کی قراءت شروع کی،جب میں اس آیت پر پہنچا: فَکَیْفَ إِذَا جِئْنَا مِن کُلِّ أُمَّۃٍ بِشَہِیدٍ وَجِئْنَا بِکَ عَلَیٰ ہَـٰؤُلَاءِ شَہِیدًا \"اس وقت کیا حال ہوگا،جب ہم ہر امت میں سے ایک گواہ لائیں گے اور آپ کو ان پر گواہ بنا کرلائیں گے۔\"تو میں نے اپنا سر اٹھایا،یا میرے پہلو میں موجود آدمی نے مجھے ٹھوکا دیا تو میں نے اپنا سر اٹھایا،میں نے دیکھا کہ آپ صلی اللہ علیہ وسلم کے آنسو بہہ رہے تھے۔"}],[1809,"ہناد بن سری اور منجانب بن حارث تمیمی نے علی بن مسہر سے روایت کی ، انھوں نے اعمش سے اسی سندکے ساتھ روایت کی ، ہناد نے اپنی روایت میں یہ اضافہ کیا : رسول اللہ صلی اللہ علیہ وسلم نے ، جب آپ منبر پر تشریف فرماتھے ، مجھ سے کہا : \" مجھے قرآن سناؤ","",{"u2":"ہناد بن سری اور منجانب بن حارث تمیمی نے علی بن مسہر سے روایت کی،انھوں نے اعمش سے اسی سندکے ساتھ روایت کی،ہناد نے اپنی روایت میں یہ اضافہ کیا:رسول اللہ صلی اللہ علیہ وسلم نے،جب آپ منبر پر تشریف فرماتھے،مجھ سے کہا:\"مجھے قرآن سناؤ\""}],[1810,"مسعر نے عمرو بن مرہ سے اور انھوں نے ابراہیم سے روایت کی ، انھوں نے کہا : نبی اکرم صلی اللہ علیہ وسلم نے عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے کہا : \"\" مجھے قرآن مجید سناؤ ۔ \"\" انھوں نے کہا : کیا میں آپ کو سناؤں جبکہ ( قرآن ) اترا ہی آپ پر ہے؟آپ نے فرمایا : \"\" مجھے اچھا لگتاہے کہ میں اسے کسی دوسرے سے سنوں ۔ \"\" ( ابراہیم ) نے کہا : انھوں نے آپ کے سامنے سورہ نساء ابتداء سے اس آیت تک سنائی : «فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَىٰ» هَـٰؤُلَاءِ شَهِيدًا \"\" اس وقت کیا حال ہوگا ، جب ہم ہر امت میں سے ایک گواہ لائیں گے اور آپ کو ان پر گواہ بنا کرلائیں گے ۔ \"\" تو آپ صلی اللہ علیہ وسلم ( اس آیت پر ) رو پڑے ۔ مسعر نے ایک دوسری سند سے عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کا یہ قول نقل کیا کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : \"\" میں ان پر اس وقت تک گواہ تھا جب تک میں ان میں رہا ۔ \"\" مسعر کو شک ہے ۔ ما دمت فيهم کہایا ما كنت فيهم ( جب تک میں ان میں تھا ) کہا ۔","",{"u2":"مسعر نے عمرو بن مرہ سے اور انھوں نے ابراہیم سے روایت کی،انھوں نے کہا:نبی اکرم صلی اللہ علیہ وسلم نے عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے کہا:\"مجھے قرآن مجید سناؤ۔\"انھوں نے کہا:کیا میں آپ کو سناؤں جبکہ(قرآن) اترا ہی آپ پر ہے؟آپ نے فرمایا:\" مجھے اچھا لگتاہے کہ میں اسے کسی دوسرے سے سنوں۔\"(ابراہیم) نے کہا:انھوں نے آپ کے سامنے سورہ نساء ابتداء سے اس آیت تک سنائی: فَکَیْفَ إِذَا جِئْنَا مِن کُلِّ أُمَّۃٍ بِشَہِیدٍ وَجِئْنَا بِکَ عَلَیٰ ہَـٰؤُلَاءِ شَہِیدًا \"اس وقت کیا حال ہوگا،جب ہم ہر امت میں سے ایک گواہ لائیں گے اور آپ کو ان پر گواہ بنا کرلائیں گے۔\"تو آپ صلی اللہ علیہ وسلم (اس آیت پر) رو پڑے۔\nمسعر نے ایک دوسری سند سے عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کا یہ قول نقل کیا کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\"میں ان پر اس وقت تک گواہ تھا جب تک میں ان میں رہا۔\"مسعر کو شک ہے۔ما دمت فیہم کہایا ما کنت فیہم (جب تک میں ان میں تھا)کہا۔"}],[1811,"جریر نے اعمش سے ، انھوں نے ابراہیم سے ، انھوں نے علقمہ سے اور انھوں نے سیدنا عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : \"\" میں حمص میں تھا تو کچھ لوگوں نے مجھے کہا : ہمیں قرآن مجید سنائیں تو میں نے انھیں سورہ یوسف سنائی ۔ لوگوں میں سے ایک آدمی نے کہا : اللہ کی قسم! یہ اس طرح نہیں اتری تھی ۔ میں نے کہا : تجھ پر افسوس ، اللہ کی قسم!میں نے یہ سورت رسول اللہ صلی اللہ علیہ وسلم کو سنائی تھی تو آ پ نے مجھ سے فرمایا : \"\" تو نے خوب قراءت کی ۔ \"\" اسی اثنا میں کہ میں اس سے گفتگو کررہا تھا تو میں نے اس ( کے منہ ) سے شراب کی بو محسوس کی ، میں نے کہا : تو شراب بھی پیتا ہے اور کتاب اللہ کی تکذیب بھی کرتا ہے؟تو یہاں سے نہیں جاسکتا حتیٰ کہ میں تجھے کوڑے لگاؤں ، پھر میں نے اسے حد کے طور پر کوڑے لگائے ۔","",{"u2":"جریر نے اعمش سے،انھوں نے ابراہیم سے،انھوں نے علقمہ سے اور انھوں نے حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:\" میں حمص میں تھا تو کچھ لوگوں نے مجھے کہا:ہمیں قرآن مجید سنائیں تو میں نے انھیں سورہ یوسف سنائی۔لوگوں میں سے ایک آدمی نے کہا:اللہ کی قسم! یہ اس طرح نہیں اتری تھی۔میں نے کہا:تجھ پر افسوس،اللہ کی قسم!میں نے یہ سورت رسول اللہ صلی اللہ علیہ وسلم کو سنائی تھی تو آ پ نے مجھ سے فرمایا:\" تو نے خوب قراءت کی۔\"\nاسی اثنا میں کہ میں اس سے گفتگو کررہا تھا تو میں نے اس (کے منہ) سے شراب کی بو محسوس کی،میں نے کہا:تو شراب بھی پیتا ہے اور کتاب اللہ کی تکذیب بھی کرتا ہے؟تو یہاں سے نہیں جاسکتا حتیٰ کہ میں تجھے کوڑے لگاؤں،پھر میں نے اسے حد کے طور پر کوڑے لگائے۔"}],[1812,"عیسیٰ بن یونس اور ابو معاویہ نے اعمش سے اسی سند کے ساتھ ر وایت کی لیکن ابومعاویہ کی روایت میں فقال لي احسنت ( آپ نے مجھے فرمایا : \" تو نے بہت اچھا پڑھا \" ) کے الفاظ نہیں ہیں ۔","",{"u2":"عیسیٰ بن یونس اور ابو معاویہ نے اعمش سے اسی سند کے ساتھ ر وایت کی لیکن ابومعاویہ کی روایت میں فقال لی احسنت(آپ نے مجھے فرمایا:\"تو نے بہت اچھا پڑھا\") کے الفاظ نہیں ہیں۔"}],[1813,"سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نےفرمایا : \" کیا تم میں سے کوئی شخص یہ پسند کرتا ہے کہ جب وہ ( باہر سے ) اپنے گھر واپس آئے تو اس میں تین بڑی فربہ حاملہ اونٹنیاں موجود پائے؟ \" ہم نے عرض کی : جی ہاں!آپ نے فرمایا : \" تین آیات جنھیں تم میں سے کوئی شخص اپنی نماز میں پڑھتا ہے ۔ وہ اس کے لئے تین بھاری بھرکم اور موٹی تازی حاملہ اونٹنیوں سے بہتر ہیں ۔","",{"u2":"حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نےفرمایا:\"کیا تم میں سے کوئی شخص یہ پسند کرتا ہے کہ جب وہ(باہر سے) اپنے گھر واپس آئے تو اس میں تین بڑی فربہ حاملہ اونٹنیاں موجود پائے؟\" ہم نے عرض کی:جی ہاں!آپ نے فرمایا:\"تین آیات جنھیں تم میں سے کوئی شخص اپنی نماز میں پڑھتا ہے۔وہ اس کے لئے تین بھاری بھرکم اور موٹی تازی حاملہ اونٹنیوں سے بہتر ہیں۔\""}],[1814,"سیدنا عقبہ بن عامر رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم گھر سے نکل کر تشریف لائے ۔ ہم صفہ ( چبوترے ) پر مووجودتھے ، آپ نے فرمایا : \" تم میں سے کون پسند کرتا ہے کہ روزانہ صبح بطحان یا عقیق ( کی وادی ) میں جائے اور وہاں سے بغیر کسی گناہ اور قطع رحمی کے دو بڑے بڑے کوہانوں والی اونٹنیاں لائے؟ \" ہم نے عرض کی ، اے اللہ کے رسول صلی اللہ علیہ وسلم ! ہم سب کو یہ بات پسند ہے آپ نے فرمایا : \" پھر تم میں سے صبح کوئی شخص مسجد میں کیوں نہیں جاتا کہ وہ اللہ کی کتاب کی دو آیتیں سیکھے یا ان کی قراءت کرے تو یہ اس کے لئے دو اونٹنیوں ( کے حصول ) سے بہتر ہے اور یہ تین آیات تین اونٹنیوں سے بہتر اور چار آیتیں اس کے لئے چار سے بہتر ہیں اور ( آیتوں کی تعداد جو بھی ہو ) اونٹوں کی اتنی تعداد سے بہتر ہے ۔","",{"u2":"حضرت عقبہ بن عامر رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم گھر سےنکل کر تشریف لائے۔ہم صفہ(چبوترے) پر مووجودتھے،آپ نے فرمایا:\" تم میں سے کون پسند کرتا ہے کہ روزانہ صبح بطحان یا عقیق(کی وادی) میں جائے اور وہاں سے بغیر کسی گناہ اور قطع رحمی کے دو بڑے بڑے کوہانوں والی اونٹنیاں لائے؟\"ہم نے عرض کی،اے اللہ کے رسول صلی اللہ علیہ وسلم! ہم سب کو یہ بات پسندہے آپ نے فرمایا:\"پھر تم میں سے صبح کوئی شخص مسجد میں کیوں نہیں جاتا کہ وہ اللہ کی کتاب کی دو آیتیں سیکھے یا ان کی قراءت کرے تو یہ اس کے لئے دو اونٹنیوں (کے حصول) سے بہتر ہے اور یہ تین آیات تین اونٹنیوں سے بہتر اور چار آیتیں اس کے لئے چار سے بہتر ہیں اور(آیتوں کی تعداد جو بھی ہو) اونٹوں کی اتنی تعداد سے بہتر ہے۔\""}],[1815,"ابو توبہ ربیع بن نافع نے بیان کیا کہ ہم سے معاویہ ، یعنی ابن اسلام نے حدیث بیان کی ، انھوں نے زید سے روایت کی کہ انھوں نے ابو سلام سے سنا ، وہ کہتے تھے : مجھ سے سیدنا ابو امامہ باہلی رضی اللہ تعالیٰ عنہ نے حدیث بیان کی ، انھوں کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کویہ فرماتے ہوئے سنا : \"\" قرآن پڑھا کرو کیونکہ وہ قیامت کے دن اصحاب قرآن ( حفظ وقراءت اور عمل کرنے والوں ) کا سفارشی بن کر آئےگا ۔ دو روشن چمکتی ہوئی سورتیں : البقرہ اور آل عمران پڑھا کرو کیونکہ وہ قیامت کے دن اس طرح آئیں گی جیسے وہ دو بادل یا دو سائبان ہوں یا جیسے وہ ایک سیدھ میں اڑتے پرندوں کی وہ ڈاریں ہوں ، وہ اپنی صحبت میں ( پڑھنے اور عمل کرنے ) والوں کی طرف سے دفاع کریں گی ۔ سورہ بقرہ پڑھا کرو کیونکہ اسے حاصل کرنا باعث برکت اور اسے ترک کرنا باعث حسرت ہے اور باطل پرست اس کی طاقت نہیں رکھتے ۔ \"\" معاویہ نے کہا : مجھے یہ خبر پہنچی ہے کہ باطل پرستوں سے ساحر ( جادوگر ) مراد ہیں ۔","",{"u2":"ابو توبہ ربیع بن نافع نے بیان کیا کہ ہم سے معاویہ،یعنی ابن اسلام نے حدیث بیان کی،انھوں نے زید سے روایت کی کہ انھوں نے ابو سلام سے سنا، وہ کہتے تھے:مجھ سے حضرت ابو امامہ باہلی رضی اللہ تعالیٰ عنہ نے حدیث بیان کی،انھوں کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کویہ فرماتے ہوئے سنا:\"قرآن پڑھا کرو کیونکہ وہ قیامت کے دن اصحاب قرآن(حفظ وقراءت اور عمل کرنے والوں) کا سفارشی بن کر آئےگا۔دو روشن چمکتی ہوئی سورتیں:البقرہ اور آل عمران پڑھا کرو کیونکہ وہ قیامت کے دن اس طرح آئیں گی جیسے وہ دو بادل یا دو سائبان ہوں یا جیسے وہ ایک سیدھ میں اڑتے پرندوں کی وہ ڈاریں ہوں،وہ اپنی صحبت میں(پڑھنے اور عمل کرنے)والوں کی طرف سے دفاع کریں گی۔سورہ بقرہ پڑھا کرو کیونکہ اسے حاصل کرنا باعث برکت اور اسے ترک کرناباعث حسرت ہے اور باطل پرست اس کی طاقت نہیں رکھتے۔\"\nمعاویہ نے کہا: مجھے یہ خبر پہنچی ہے کہ باطل پرستوں سے ساحر(جادوگر) مراد ہیں۔"}],[1816,"یحییٰ بن حسان نے کہا : معاویہ بن سلام نے ہمیں اسی سند کے ساتھ اسی طرح حدیث بیان کی لیکن انہوں نے دونوں جگہوں پراوكانهما ( یا جیسے وہ ) کی جگہ \" وكانهما \" ( اور جیسے وہ ) کہا اور معاویہ کا قول ہے کہ \" مجھے یہ خبر پہنچی \" ذکر نہیں کیا ۔","",{"u2":"یحییٰ بن حسان نے کہا:معاویہ بن سلام نے ہمیں اسی سند کے ساتھ اسی طرح حدیث بیان کی لیکن انہوں نے دونوں جگہوں پراوکانہما(یا جیسے وہ) کی جگہ \"وکانہما\"(اور جیسے وہ) کہا اور معاویہ کا قول ہے کہ\"مجھے یہ خبرپہنچی\"ذکر نہیں کیا۔"}],[1817,"سیدنا نواس بن سمعان کلابی رضی اللہ تعالیٰ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" قیامت کے دن قرآن اور قرآن والے ایسے لوگوں کو لایا جائے گا جو اس پر عمل کرتے تھے ، سورہ بقرہ اور سورہ آل عمران اس کے آگے آگے ہوں گی ۔ \" رسول اللہ صلی اللہ علیہ وسلم نے ان سورتوں کے لئے تین مثالیں دیں جن کو ( سننے کے بعد ) میں ( آج تک ) نہیں بھولا ، آپ نے فرمایا : \" جیسے وہ دو بادل ہیں یا دو کالے سائبان ہیں جن کے درمیان روشنی ہے جیسے وہ ایک سیدھ میں اڑنے والے پرندوں کی دو ٹولیاں ہیں ، وہ ا پنے صاحب ( صحبت میں رہنے والے ) کی طرف سے مدافعت کریں گی ۔","",{"u2":"حضرت نواس بن سمعان کلابی رضی اللہ تعالیٰ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:\"قیامت کے دن قرآن اور قرآن والے ایسے لوگوں کو لایا جائے گا جو اس پر عمل کرتے تھے،سورہ بقرہ اورسورہ آل عمران اس کے آگے آگے ہوں گی۔\"رسول اللہ صلی اللہ علیہ وسلم نے ان سورتوں کے لئے تین مثالیں دیں جن کو(سننے کے بعد)میں (آج تک) نہیں بھولا،آپ نے فرمایا:\"جیسے وہ دو بادل ہیں یا دو کالے سائبان ہیں جن کے درمیان روشنی ہے جیسے وہ ایک سیدھ میں اڑنے والے پرندوں کی دو ٹولیاں ہیں،وہ ا پنے صاحب(صحبت میں رہنے والے)کی طرف سے مدافعت کریں گی۔"}],[1818,"سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سےروایت ہے کہ جبرئیل علیہ السلام نبی اکرم صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے کہ اچانک انھوں نے اوپر سے ایسی آواز سنی جیسی دروازہ کھلنے کی ہوتی ہے تو انھوں نے اپنا سر اوپر اٹھایا اور کہا : آسمان کا یہ دروازہ آج ہی کھولا گیا ہے ، آج سے پہلے کبھی نہیں کھولا گیا ، اس سے ایک فرشتہ اترا تو انھوں نے کہا : یہ ایک فرشتہ آسمان سے اترا ہے یہ آج سے پہلے کبھی نہیں اترا ، اس فرشتے نے سلام کیا اور ( آپ صلی اللہ علیہ وسلم سے ) کہا : آپ کو دو نور ملنے کی خوشخبری ہو جو آپ سے پہلے کسی نبی کو نہیں دیئے گئے : ( ایک ) فاتحہ الکتاب ( سورہ فاتحہ ) اور ( دوسری ) سورہ بقرہ کی آخری آیات ۔ آپ ان دونوں میں سے کوئی جملہ بھی نہیں پڑھیں گے مگر وہ آپ کو عطا کردیا جائے گا ۔","",{"u2":"حضرت ابن عباس رضی اللہ تعالیٰ عنہ سےروایت ہے کہ جبرئیل علیہ السلام نبی اکرم صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے کہ اچانک انھوں نے اوپر سے ایسی آواز سنی جیسی دروازہ کھلنے کی ہوتی ہے تو انھوں نے اپنا سر اوپر اٹھایا اور کہا:آسمان کا یہ دروازہ آج ہی کھولا گیا ہے،آج سے پہلے کبھی نہیں کھولا گیا،اس سے ایک فرشتہ اترا تو انھوں نے کہا:یہ ایک فرشتہ آسمان سے اترا ہے یہ آج سے پہلے کبھی نہیں اترا،اس فرشتے نے سلام کیا اور(آپ صلی اللہ علیہ وسلم سے) کہا:آپ کو دو نور ملنے کی خوشخبری ہو جو آپ سے پہلے کسی نبی کو نہیں دیئے گئے: (ایک) فاتحہ الکتاب (سورہ فاتحہ) اور (دوسری) سورہ بقرہ کی آخری آیات۔آپ ان دونوں میں سے کوئی جملہ بھی نہیں پڑھیں گے مگر وہ آپ کو عطا کردیا جائے گا۔"}],[1819,"زہیر نے کہا : ہم سے منصور نے حدیث بیان کی ، انھوں نے ابراہیم سے اور انھوں نے عبدالرحما بن یزید سے ر وایت کی ، انھوں نے کہا : میں بیت اللہ کے پاس سیدنا ابو مسعود رضی اللہ تعالیٰ عنہ سے ملا تو میں نے کہا : مجھے آپ کے حوالے سے سورہ بقرہ کی دو آیتوں کے بارے میں حدیث پہنچی ہے ۔ تو انھوں نے کہا : ہاں ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا : \" سورہ بقرہ کی آخری دو آیتیں ، جو شخص رات میں انھیں پڑھے گا وہ اس کے لئے کافی ہوں گی ۔","",{"u2":"زہیر نے کہا:ہم سے منصور نے حدیث بیان کی،انھوں نے ابراہیم سے اور انھوں نے عبدالرحما بن یزید سے ر وایت کی،انھوں نے کہا:میں بیت اللہ کے پاس حضرت ابو مسعود رضی اللہ تعالیٰ عنہ سے ملا تو میں نے کہا:مجھے آپ کے حوالے سے سورہ بقرہ کی دو آیتوں کے بارے میں حدیث پہنچی ہے۔تو انھوں نے کہا:ہاں،رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا:\"سورہ بقرہ کی آخری دو آیتیں،جو شخص رات میں انھیں پڑھے گا وہ اس کے لئے کافی ہوں گی۔\""}],[1820,"جریر اور شعبہ دونوں نے منصور سے اسی سند کے ساتھ یہی ر وایت بیان کی ہے ۔","",{"u2":"جریر اور شعبہ دونوں نے منصور سے اسی سند کے ساتھ یہی ر وایت بیان کی ہے۔"}],[1821,"علی بن مسہر نے اعمش سے روایت کی ، انھوں نے ابراہیم سے ، انھوں نے عبدالرحمان بن یزید سے ، انھوں نے علقمہ بن قیس سے اور انھوں نے سیدنا ابو مسعود انصاری رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جس نے رات کے وقت سورہ بقرہ کی یہ آخری دو آیات پڑھیں ، وہ اس کے لئے کافی ہوں گی ۔ \"\" عبدالرحمان نے کہا : میں خود ابومسعود رضی اللہ تعالیٰ عنہ کو ملا ، وہ بیت اللہ کا طواف کررہے تھے ، میں نے ان سے پوچھا تو انھوں نے مجھے یہ روایت ( براہ راست ) نبی اکرم صلی اللہ علیہ وسلم سے سنائی ۔","",{"u2":"علی بن مسہر نے اعمش سے روایت کی،انھوں نے ابراہیم سے،انھوں نے عبدالرحمان بن یزید سے،انھوں نے علقمہ بن قیس سے اور انھوں نے حضرت ابو مسعود انصاری رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جس نے رات کے وقت سورہ بقرہ کی یہ آخری دو آیات پڑھیں،وہ اس کے لئے کافی ہوں گی۔\"\nعبدالرحمان نے کہا:میں خود ابومسعود رضی اللہ تعالیٰ عنہ کو ملا،وہ بیت اللہ کا طواف کررہے تھے،میں نے ان سے پوچھا تو انھوں نے مجھے یہ روایت(براہ راست) نبی اکرم صلی اللہ علیہ وسلم سے سنائی۔"}],[1822,"عیسیٰ بن یونس اور عبداللہ بن نمیر نے اعمش سے باقی ماندہ اسی سند کےساتھ اسی کے مانند روایت بیان کی ۔","",{"u2":"عیسیٰ بن یونس اور عبداللہ بن نمیر نے اعمش سے باقی ماندہ اسی سند کےساتھ اسی کے مانند روایت بیان کی۔"}],[1823,"حفص اور ابو معاویہ نے بھی اعمش سے باقی ماندہ سابقہ سند کے ساتھ اسی کے مانند ر وایت بیان کی ہے ۔","",{"u2":"حفص اور ابو معاویہ نے بھی اعمش سے باقی ماندہ سابقہ سند کے ساتھ اسی کے مانند ر وایت بیان کی ہے۔"}],[1824,"معاذ بن ہشام نے اپنے والد سے حدیث بیان کی ، انھوں نے قتادہ سے ، انھوں نے سالم بن ابی جعد غطفانی سے ، انھوں نے معدان بن ابی طلحہ یعمری سے اور انھوں نے سیدنا ابو درداء رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : \" جس ( مسلمان ) نے سورہ کہف کی پہلی دس آیات حفظ کرلیں ، اسے دجال کے فتنے سے محفوظ کرلیا گیا ۔","",{"u2":"معاذ بن ہشام نے اپنے والد سے حدیث بیان کی،انھوں نے قتادہ سے،انھوں نے سالم بن ابی جعد غطفانی سے،انھوں نے معدان بن ابی طلحہ یعمری سے اور انھوں نے حضرت ابو درداء رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\"جس(مسلمان) نے سورہ کہف کی پہلی دس آیات حفظ کرلیں، اسے دجال کے فتنے سے محفوظ کرلیا گیا۔\""}],[1825,"شعبہ اور ہمام نے قتادہ سے اسی سند کے ساتھ روایت کی ۔ اس میں شعبہ نے سورہ کہف کی آخری ( دس ) آیات کہا ہے جبکہ ہمام نے ابتدائی ( دس ) آیات کہا ہے جس طرح ہشام کی روایت ہے ۔","",{"u2":"شعبہ اور ہمام نے قتادہ سے اسی سند کے ساتھ روایت کی۔اس میں شعبہ نے سورہ کہف کی آخری (دس)آیات کہا ہے جبکہ ہمام نے ابتدائی(دس) آیات کہا ہے جس طرح ہشام کی روایت ہے۔"}],[1826,"سیدنا ابی بن کعب رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اے ابو منذر!کیا تم جانتے ہو کتاب اللہ کی کونسی آیت ، جو تمھارے پاس ہے ، سب سے عظیم ہے؟ \" کہا : میں نے عرض کی : اللہ اوراس کے رسول صلی اللہ علیہ وسلم زیادہ جانتے ہیں ۔ آپ نے ( دوبارہ ) فرمایا : \" اے ابو منذر! کیا تم جانتے ہو اللہ کی کتاب کی کونسی آیت جو تمہارے پاس ہے ، سب سے عظمت والی ہے؟ \" کہا : میں نے عرض کی اللَّهُ لَا إِلہ «إِلَّا هُوَ الْحَيُّ الْقَيُّومُ» کہا : تو آپ نے میرے سینے پر ہاتھ مارا اور فرمایا : اللہ کی قسم !ابو منذر! تمھیں یہ علم مبارک ہو ۔","",{"u2":"حضرت ابی بن کعب رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اے ابو منذر!کیا تم جانتے ہو کتاب اللہ کی کونسی آیت،جو تمھارے پاس ہے،سب سے عظیم ہے؟\"کہا: میں نے عرض کی:اللہ اوراس کے رسول صلی اللہ علیہ وسلم زیادہ جانتے ہیں۔آپ نے (دوبارہ) فرمایا: \"اے ابو منذر! کیا تم جانتے ہو اللہ کی کتاب کی کونسی آیت جو تمہارے پاس ہے،سب سے عظمت والی ہے؟\"کہا: میں نے عرض کیاللَّہُ لَا إِلہ إِلَّا ہُوَ الْحَیُّ الْقَیُّومُ کہا:تو آپ نے میرے سینے پر ہاتھ مارا اور فرمایا:اللہ کی قسم!ابو منذر! تمھیں یہ علم مبارک ہو۔\""}],[1827,"شعبہ نے قتادہ سے ، انہوں نے سالم بن ابی جعد سے ، انہوں نے معدان بن ابی طلحہ سے ، انھوں نے سیدنا ابو درداء رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تم میں سے کوئی شخص اتنا بھی نہیں کرسکتا کہ ایک رات میں تہائی قرآن کی تلاوت کرلے؟ \" انھوں ( صحابہ کرام رضوان اللہ عنھم اجمعین ) نے عرض کی : ( کوئی شخص ) تہائی قرآن کی تلاوت کیسے کرسکتاہے؟آپ صلی اللہ علیہ وسلم نے فرمایا : «قُلْ هُوَ اللَّهُ أَحَدٌ» ایک تہائی قرآن کے برابر ہے ۔","",{"u2":"شعبہ نے قتادہ سے،انہوں نے سالم بن ابی جعد سے،انہوں نے معدان بن ابی طلحہ سے،انھوں نے حضرت ابو درداء رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"کیا تم میں سے کوئی شخص اتنا بھی نہیں کرسکتا کہ ایک رات میں تہائی قرآن کی تلاوت کرلے؟\"انھوں(صحابہ کرام رضوان اللہ عنھم اجمعین) نے عرض کی: (کوئی شخص) تہائی قرآن کی تلاوت کیسے کرسکتاہے؟آپ صلی اللہ علیہ وسلم نے فرمایا: قُلْ ہُوَ اللَّہُ أَحَدٌ ایک تہائی قرآن کے برابر ہے۔\""}],[1828,"سعید بن ابی عروبہ اور ابان عطار نے قتادہ سے اسی سابقہ سند کے ساتھ روایت کی ، ان دونوں ( سعید اور ابان ) کی حدیث میں رسول اللہ صلی اللہ علیہ وسلم کا یہ فرمان ہے ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالیٰ نے قرآن مجید کے تین اجزاء ( حصے ) کئے ہیں اور «قُلْ هُوَ اللَّهُ أَحَدٌ» کو قرآن کے اجزاء میں سے ایک جز قرار دیا ہے ۔","",{"u2":"سعید بن ابی عروبہ اور ابان عطار نے قتادہ سے اسی سابقہ سند کے ساتھ روایت کی،ان دونوں (سعید اور ابان) کی حدیث میں رسول اللہ صلی اللہ علیہ وسلم کا یہ فرمان ہے،آپ صلی اللہ علیہ وسلم نے فرمایا:\"اللہ تعالیٰ نے قرآن مجید کے تین اجزاء(حصے) کئے ہیں اور قُلْ ہُوَ اللَّہُ أَحَدٌ کو قرآن کے اجزاء میں سے ایک جز قرار دیاہے۔\""}],[1829,"یزید بن کیسان نے کہا : ہمیں ابو حازم نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے حدیث سنائی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اکھٹے ہوجاؤ!میں تمھارے سامنے ایک تہائی قرآن مجید پڑھوں گا ۔ \" جنھوں نے جمع ہونا تھا وہ جمع ہوگئے پھر نبی اکرم صلی اللہ علیہ وسلم باہر تشریف لائے اور آپ صلی اللہ علیہ وسلم نے سورہ «قُلْ هُوَ اللَّهُ أَحَدٌ» کی قراءت فرمائی ، پھر گھر میں چلے گئے تو ہم میں سے ایک سے دوسرے نے کہا : مجھے لگتاہے آپ کے پاس شاید آسمان سے کوئی اہم خبر آئی ہے ۔ جو آپ کو اندر لے گئی ہے ۔ پھر نبی اکرم صلی اللہ علیہ وسلم ( دوبارہ ) باہر تشریف لائے اور فرمایا : \" میں نے تم سے کہا تھا نا کہ میں تمھیں تہائی قرآن سناؤں گا ، جان لو یہ کہ ( سورت ) قرآن کے تیسرے حصے کے برابر ہے ۔","",{"u2":"یزید بن کیسان نے کہا:ہمیں ابو حازم نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے حدیث سنائی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اکھٹے ہوجاؤ!میں تمھارے سامنے ایک تہائی قرآن مجید پڑھوں گا۔\"جنھوں نے جمع ہونا تھا وہ جمع ہوگئے پھر نبی اکرم صلی اللہ علیہ وسلم باہر تشریف لائے اور آپ صلی اللہ علیہ وسلم نے سورہ قُلْ ہُوَ اللَّہُ أَحَدٌ کی قراءت فرمائی،پھر گھر میں چلے گئے تو ہم میں سے ایک سے دوسرے نے کہا:مجھے لگتاہے آپ کے پاس شاید آسمان سے کوئی اہم خبرآئی ہے۔جو آپ کو اندر لے گئی ہے۔پھر نبی اکرم صلی اللہ علیہ وسلم (دوبارہ) باہر تشریف لائے اور فرمایا:\" میں نے تم سے کہا تھا نا کہ میں تمھیں تہائی قرآن سناؤں گا،جان لو یہ کہ(سورت) قرآن کے تیسرے حصے کے برابر ہے۔\""}],[1830,"ابواسماعیل بشیر نے ابو حازم سے اور انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم باہر نکل کر ہمارے پاس تشریف لائے اور فرمایا : \" میں تمھارے سامنے تہائی قرآن کی قراءت کرتا ہوں ۔ \" پھر آپ صلی اللہ علیہ وسلم نے «قُلْ هُوَ اللَّهُ أَحَدٌ» ﴿ «اللَّهُ الصَّمَدُ» پڑھا یہاں تک کہ اسے ( سورت ) کو ختم کردیا ۔","",{"u2":"ابواسماعیل بشیر نے ابو حازم سے اور انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم باہر نکل کر ہمارے پاس تشریف لائے اور فرمایا:\" میں تمھارے سامنے تہائی قرآن کی قراءت کرتا ہوں۔\"پھر آپ صلی اللہ علیہ وسلم نے قُلْ ہُوَ اللَّہُ أَحَدٌ ﴿ اللَّہُ الصَّمَدُ پڑھا یہاں تک کہ اسے (سورت) کو ختم کردیا۔"}],[1831,"عمرہ بنت عبدالرحمان نے ، اور وہ رسول اللہ صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ تعالی عنہا کی پرورش میں تھیں ، سیدہ عائشہ رضی اللہ تعالی عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو ایک مہم کا امیر بنا کر روانہ فرمایا ، وہ اپنے ساتھیوں کی نماز میں قراءت کرتا اور ( اس کا ) اختتام «قُلْ هُوَ اللَّهُ أَحَدٌ» سے کرتا تھا ۔ جب وہ لوگ واپس آئے تو انھوں نے اس بات کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے کیا ۔ آپ نے فرمایا : \" اسے پوچھو ، وہ ایسا کس لئے کرتا تھا؟ \" صحابہ کرام نے پوچھا تو اس نے جواب دیا : اس لئے کہ یہ رحمٰن ( جل وعلا ) کی صفت ہے ، اس لئے مجھے اس بات سے محبت ہے کہ میں اس کی قراءت کروں ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اسے بتادو! اللہ بھی اس سے محبت کرتا ہے ۔","",{"u2":"عمرہ بنت عبدالرحمان نے،اور وہ رسول اللہ صلی اللہ علیہ وسلم کی زوجہ حضرت عائشہ رضی اللہ تعالیٰ عنہا کی پرورش میں تھیں،حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو ایک مہم کا امیر بنا کر روانہ فرمایا،وہ اپنے ساتھیوں کی نماز میں قراءت کرتا اور (اس کا) اختتام قُلْ ہُوَ اللَّہُ أَحَدٌ سے کرتا تھا۔جب وہ لوگ واپس آئے تو انھوں نے اس بات کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے کیا۔آپ نے فرمایا:\"اسے پوچھو،وہ ایسا کس لئے کرتا تھا؟\" صحابہ کرام نے پوچھا تو اس نے جواب دیا:اس لئے کہ یہ رحمٰن (جل وعلا) کی صفت ہے،اس لئے مجھے اس بات سے محبت ہے کہ میں اس کی قراءت کروں۔رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" اسے بتادو! اللہ بھی اس سے محبت کرتا ہے۔\""}],[1832,"بیان ( بن بشر ) نے قیس بن ابی حازم سے اور انھوں نے سیدنا عقبہ بن عامر رضی اللہ تعالی عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تمھیں معلوم نہیں کہ جو آیتیں آج مجھ پر نازل کی گئی ہیں ان جیسی ( آیتیں ) کبھی دیکھی تک نہیں گئیں؟ \" «قُلْ أَعُوذُ» بِرَ‌بِّ «الْفَلَقِ اور قُلْ أَعُوذُ» بِرَ‌بِّ النَّاسِ ۔","",{"u2":"بیان(بن بشر)نے قیس بن ابی حازم سے اور انھوں نے حضرت عقبہ بن عامر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" کیا تمھیں معلوم نہیں کہ جو آیتیں آج مجھ پر نازل کی گئی ہیں ان جیسی(آیتیں)کبھی دیکھی تک نہیں گئیں؟\"قُلْ أَعُوذُ بِرَ‌بِّ الْفَلَقِ اور قُلْ أَعُوذُ بِرَ‌بِّ النَّاسِ۔\""}],[1833,"محمد بن عبداللہ بن نمیر نے بیان کیا ، کہا : میرے والد نے ہمیں حدیث بیان کی ، کہا : مجھ سے اسماعیل نے حدیث بیان کی ، انھوں نے قیس سے اور انھوں نے عقبہ بن عامر رضی اللہ تعالی عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \" مجھ پر ایسی آیتیں اتاری گئی ہیں کہ ان جیسی ( آیتیں ) کبھی دیکھی تک نہیں گئیں ۔ ( یعنی ) معوذ تین ۔","",{"u2":"محمد بن عبداللہ بن نمیر نے بیان کیا،کہا:میرے والد نے ہمیں حدیث بیان کی،کہا: مجھ سے اسماعیل نے حدیث بیان کی،انھوں نے قیس سے اور انھوں نے عقبہ بن عامر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا:\" مجھ پر ایسی آیتیں اتاری گئی ہیں کہ ان جیسی (آیتیں) کبھی دیکھی تک نہیں گئیں۔(یعنی) معوذ تین۔\""}],[1834,"۔ وکیع اور ابو اسامہ نے اسماعیل سے اسی سند کے سات اسی طرح روایت بیان کی ، البتہ ابو اسامہ نے عقبہ بن عامر جہنی رضی اللہ تعالی عنہ سے جو روایت کی ، اس میں ہے ، عقبہ بن عامر جہنی رضی اللہ تعالی عنہ سے روایت ہے اور وہ محمد صلی اللہ علیہ وسلم کے بلند مرتبہ ساتھیوں میں سے تھے ۔",""],[1835,"سفیان بن عینیہ نے حدیث بیان کی ، کہا : ہمیں ( ابن شہاب ) زہری نے سالم سے حدیث بیان کی ، انھوں نے اپنے والد ( عبداللہ بن عمر رضی اللہ تعالی عنہ ) سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" دو چیزوں ( خوبیوں ) کے سوا کسی اور چیز میں حسد ( رشک ) کی گنجائش نہیں : ایک وہ آدمی جسے اللہ تعالی نے قرآن کی نعمت عنایت فرمائی ، پھر وہ دن اور رات کی گھڑیوں میں اس کے ساتھ قیام کرتا ہے ۔ اور دوسرا وہ شخص جسے اللہ نے مال ودولت سے نوازا اور وہ دن اور رات کے اوقات میں اسے ( اللہ کی راہ میں ) خرچ کرتا ہے ۔","",{"u2":"سفیان بن عینیہ نے حدیث بیان کی،کہا:ہمیں (ابن شہاب) زہری نے سالم سے حدیث بیان کی،انھوں نے اپنے والد (عبداللہ بن عمر رضی اللہ تعالیٰ عنہ) سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا:\"دو چیزوں(خوبیوں) کے سوا کسی اور چیز میں حسد(رشک) کی گنجائش نہیں:ایک وہ آدمی جسے اللہ تعالیٰ نے قرآن کی نعمت عنایت فرمائی،پھر وہ دن اور رات کی گھڑیوں میں اس کے ساتھ قیام کرتا ہے۔ اور دوسرا وہ شخص جسے اللہ نے مال ودولت سے نوازا اور وہ دن اور رات کے اوقات میں اسے(اللہ کی راہ میں) خرچ کرتا ہے۔\""}],[1836,"یونس نے ابن شہاب ( زہری ) سے روایت کی ، انھوں نے کہا : مجھے سالم بن عبداللہ بن عمر رضی اللہ تعالی عنہ نے اپنے والد سے حدیث سنائی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" دو چیزوں کے علاوہ کسی چیز میں حسد ( رشک ) نہیں : ایک اس شخص سے متعلق جسے اللہ تعالی نے یہ کتاب عنایت فرمائی اور اس نے دن رات کی گھڑیوں میں اس کے ساتھ قیام کیا اور دوسرا وہ شخص جسے اللہ تعالی نے مال سے نوازا اور اس نے دن رات کے اوقات میں اسے صدقہ کیا ۔","",{"u2":"یونس نے ابن شہاب (زہری) سے روایت کی،انھوں نے کہا: مجھے سالم بن عبداللہ بن عمر رضی اللہ تعالیٰ عنہ نے اپنے والد سے حدیث سنائی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"دو چیزوں کے علاوہ کسی چیز میں حسد (رشک) نہیں: ایک اس شخص سے متعلق جسے اللہ تعالیٰ نے یہ کتاب عنایت فرمائی اور اس نے دن رات کی گھڑیوں میں اس کے ساتھ قیام کیا اور دوسرا وہ شخص جسے اللہ تعالیٰ نے مال سے نوازا اور اس نے دن رات کے اوقات میں اسے صدقہ کیا۔\""}],[1837,"سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" دو باتوں کے سوا کسی چیز میں حسد ( رشک ) نہیں کیا جاسکتا : ایک وہ آدمی جسے اللہ تعالی نے مال دیا پھر اسے اس پر مسلط کردیا کہ وہ اس مال کو حق کی راہ میں بے دریغ لٹائے ۔ دوسرا وہ انسان جسے اللہ تعالی نے حکمت ( دانائی ) عطا کی اور وہ اس کے مطابق ( اپنے اور دوسروں کے ) معاملات طے کر تا ہے اور اس کی تعلیم دیتاہے ۔"],[1838,"سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" دو باتوں کے سوا کسی چیز میں حسد ( رشک ) نہیں کیا جاسکتا : ایک وہ آدمی جسے اللہ تعالی نے مال دیا پھر اسے اس پر مسلط کردیا کہ وہ اس مال کو حق کی راہ میں بے دریغ لٹائے ۔ دوسرا وہ انسان جسے اللہ تعالی نے حکمت ( دانائی ) عطا کی اور وہ اس کے مطابق ( اپنے اور دوسروں کے ) معاملات طے کر تا ہے اور اس کی تعلیم دیتاہے ۔",""],[1839,"ابراہیم بن سعد نے ابن شہاب ( زہری ) سے اور انھوں نے عامر بن واثلہ سے روایت کی کہ نافع بن عبدالحارث ( مدینہ اور مکہ کے راستے پر ایک منزل ) عسفان آکر سیدنا عمر رضی اللہ تعالی عنہ سے ملے ، ( وہ استقبال کے لئے آئے ) اور سیدنا عمر رضی اللہ تعالی عنہ انھیں مکہ کا عامل بنایا کرتے تھے ، انھوں ( سیدنا عمر رضی اللہ تعالی عنہ ) نے ان سے پوچھا کہ آپ نے اہل وادی ، یعنی مکہ کے لوگوں پر ( بطور نائب ) کسے مقرر کیا؟نافع نے جواب دیا : ابن ابزی کو ۔ انھوں نے پوچھا ابن ابزی کون ہے؟کہنے لگے : ہمارے آزاد کردہ غلاموں میں سے ایک ہے ۔ سیدنا عمر رضی اللہ تعالی عنہ نےکہا : تم نے ان پر ایک آزاد کردہ غلام کو اپنا جانشن بنا ڈالا؟تو ( نافع نے ) جواب دیا : و ہ اللہ عزوجل کی کتاب کو پڑھنے والا ہے اور فرائض کا عالم ہے ۔ عمر رضی اللہ تعالی عنہ نے کہا : ( ہاں واقعی ) تمہارے نبی صلی اللہ علیہ وسلم نے فرمایا تھا ۔ اللہ تعالی اس کتاب ( قرآن ) کے ذریعے بہت سے لوگوں کو اونچا کردیتا ہے اور بہتوں کو اس کے ذریعے سے نیچا گراتا ہے ۔","",{"u2":"ابراہیم بن سعد نے ابن شہاب (زہری) سے اور انھوں نے عامر بن واثلہ سے روایت کی کہ نافع بن عبدالحارث (مدینہ اور مکہ کے راستے پر ایک منزل) عسفان آکر حضرت عمر رضی اللہ تعالیٰ عنہ سے ملے،(وہ استقبال کے لئے آئے) اور حضرت عمر رضی اللہ تعالیٰ عنہ انھیں مکہ کا عامل بنایا کرتے تھے،انھوں (حضرت عمر رضی اللہ تعالیٰ عنہ) نے ان سے پوچھا کہ آپ نے اہل وادی،یعنی مکہ کے لوگوں پر(بطور نائب) کسے مقرر کیا؟نافع نے جواب دیا:ابن ابزیٰ کو۔انھوں نے پوچھا ابن ابزیٰ کون ہے؟کہنے لگے:ہمارے آزاد کردہ غلاموں میں سے ایک ہے۔حضرت عمر رضی اللہ تعالیٰ عنہ نےکہا:تم نے ان پر ایک آزاد کردہ غلام کو اپنا جانشن بنا ڈالا؟تو (نافع نے) جواب دیا:و ہ اللہ عزوجل کی کتاب کو پڑھنے والا ہے اور فرائض کا عالم ہے۔عمر رضی اللہ تعالیٰ عنہ نے کہا: (ہاں واقعی) تمہارے نبی صلی اللہ علیہ وسلم نے فرمایا تھا۔اللہ تعالیٰ اس کتاب (قرآن) کے ذریعے بہت سے لوگوں کو اونچا کردیتا ہے اور بہتوں کو اس کے ذریعے سے نیچا گراتا ہے۔\""}],[1840,"شعیب نے زہری سے خبر دی ، انھوں نے کہا : مجھے عامر بن واثلہ لیثی نے حدیث بیان کی کہ نافع بن عبدالحارث خزاعی نے عسفان ( کے مقام ) پر سیدنا عمر رضی اللہ تعالی عنہ سے ملاقات کی ۔ ۔ ۔ ( آگے ) زہری سے ابراہیم بن سعد کی روایت کی طرح بیان کیا ۔","",{"u2":"شعیب نے زہری سے خبر دی،انھوں نے کہا:مجھے عامر بن واثلہ لیثی نے حدیث بیان کی کہ نافع بن عبدالحارث خزاعی نے عسفان(کے مقام) پر حضرت عمر رضی اللہ تعالیٰ عنہ سے ملاقات کی۔۔۔(آگے) زہری سے ابراہیم بن سعد کی روایت کی طرح بیان کیا۔"}],[1841,"مالک نے ابن شہاب سے ، انھوں نے عروہ بن زبیر سے انھوں نے عبدالرحمان بن عبدالقاری سے روایت کی ، انھوں نے کہا : میں نے سیدنا عمر بن خطاب رضی اللہ تعالی عنہ سے سنا ، وہ کہہ رہے تھے : میں نے ہشام بن حکیم بن حزام کو سورہ فرقان اس سے مختلف ( صورت میں ) پڑھتے سنا جس طرح میں پڑھتا تھا ۔ ، حالانکہ مجھے ( خود ) رسول اللہ صلی اللہ علیہ وسلم نے یہ سورت پڑھائی تھی ، قریب تھا کہ میں اس سے جھگڑا کرنے میں جلد بازی سے کام لیتا لیکن میں نے اس کو مہلت دی حتی کہ وہ نماز سے فارغ ہوگیا ، پھر میں نے اسے گلے کی چادر سے اسے باندھا اور کھینچ کر رسول اللہ صلی اللہ علیہ وسلم کے پا س لے آیا اور آپ صلی اللہ علیہ وسلم سے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم !میں نے اس کو اس طرح سورہ فرقان پڑھتے ہوئےسنا ہے جو اس سے مختلف ہے جس طرح آپ صلی اللہ علیہ وسلم نے مجھے وہ سورت پڑھائی تھی ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \" اسے چھوڑ دو ( اور اسے مخاطت ہوکر فرمایا : ) پڑھو ۔ \" تو اس نے اسی طرح پڑھا جس طرح میں نے اسے پڑھتے ہوئے سنا تھا ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" یہ سورت اسی طرح نازل ہوئی ہے ۔ \" پھر مجھ سے کہا : \" تم پڑھو ۔ \" میں نے پڑھا تو ( اس پر بھی ) آپ صلی اللہ علیہ وسلم نے فرمایا : \" یہ سورت اسی طرح اتری تھی ۔ بلاشبہ یہ قرآن سات حروف پر نازل کیا گیا ہے ۔ پس ان میں سے جو تمھارے لئے آسان ہو اسی کے مطابق پڑھو ۔","",{"u2":"مالک نے ابن شہاب سے،انھوں نے عروہ بن زبیر سے انھوں نے عبدالرحمان بن عبدالقاری سے روایت کی،انھوں نے کہا:میں نے حضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ سے سنا،وہ کہہ رہے تھے:میں نے ہشام بن حکیم بن حزام کو سورہ فرقان اس سے مختلف(صورت میں) پڑھتے سنا جس طرح میں پڑھتا تھا۔،حالانکہ مجھے(خود) رسول اللہ صلی اللہ علیہ وسلم نے یہ سورت پڑھائی تھی،قریب تھا کہ میں اس سے جھگڑا کرنے میں جلد بازی سے کام لیتا لیکن میں نے اس کو مہلت دی حتیٰ کہ وہ نماز سے فارغ ہوگیا،پھر میں نے اسے گلے کی چادر سے اسے باندھا اور کھینچ کر رسول اللہ صلی اللہ علیہ وسلم کے پا س لے آیا اور آپ صلی اللہ علیہ وسلم سے عرض کی:اے اللہ کے رسول صلی اللہ علیہ وسلم!میں نے اس کو اس طرح سورہ فرقان پڑھتے ہوئےسنا ہے جو اس سے مختلف ہے جس طرح آپ صلی اللہ علیہ وسلم نے مجھے وہ سورت پڑھائی تھی۔رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\" اسے چھوڑ دو(اور اسے مخاطت ہوکر فرمایا:)پڑھو۔\" تو اس نے اسی طرح پڑھا جس طرح میں نے اسے پڑھتے ہوئے سنا تھا۔اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"یہ سورت اسی طرح نازل ہوئی ہے۔\"پھر مجھ سے کہا:\"تم پڑھو۔\"میں نے پڑھا تو(اس پر بھی) آپ صلی اللہ علیہ وسلم نے فرمایا:\"یہ سورت اسی طرح اتری تھی۔بلاشبہ یہ قرآن سات حروف پر نازل کیا گیا ہے۔پس ان میں سے جو تمھارے لئے آسان ہواسی کے مطابق پڑھو۔\""}],[1842,"یونس نے ابن شہاب سے روایت کی ، انھوں نے کہا : مجھے عروہ بن زبیر نے بتایا کہ مسود بن مخرمہ اور عبدالرحمان بن عبدالقاری نے بتایا کہ ان دونوں سیدنا عمر بن خطاب رضی اللہ تعالی عنہ کو یہ کہتے ہوئے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کی حیات مبارکہ میں ہشام بن حکیم کو سورہ فرقان پڑھتے سنا ۔ ۔ ۔ آگے اسی کے مانند حدیث سنائی اور یہ اضافہ کیا کہ قریب تھا کہ میں اس پر نماز پر ہی پل پڑوں ، میں نے بڑی مشکل سے صبر کیا یہاں تک کہ اس نے سلام پھیرا ۔","",{"u2":"یونس نے ابن شہاب سے روایت کی،انھوں نے کہا:مجھے عروہ بن زبیر نے بتایا کہ مسود بن مخرمہ اور عبدالرحمان بن عبدالقاری نے بتایا کہ ان دونوں حضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ کو یہ کہتے ہوئے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کی حیات مبارکہ میں ہشام بن حکیم کو سورہ فرقان پڑھتے سنا۔۔۔آگے اسی کے مانند حدیث سنائی اور یہ اضافہ کیا کہ قریب تھا کہ میں اس پر نماز پر ہی پل پڑوں،میں نے بڑی مشکل سے صبر کیا یہاں تک کہ اس نے سلام پھیرا۔"}],[1843,"معمر نے زہری سے یونس کی روایت کی طرح اسی کی سند کے ساتھ روایت کی ۔","",{"u2":"معمر نے زہری سے یونس کی روایت کی طرح اسی کی سند کے ساتھ روایت کی۔"}],[1844,"یونس نے ابن شہاب سے روایت کی ، انھوں نے کہا : مجھ سے عبیداللہ بن عبداللہ بن عتبہ نے حدیث بیان کی کہ سیدنا ابن عباس رضی اللہ تعالی عنہ نے ان سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جبرئیل علیہ السلام نے مجھے ایک حرف پر ( قرآن ) پڑھایا ، میں نے ان سے مراجعت کی ، پھر میں زیادہ کا تقاضا کرتا رہا اور وہ میرے لئے حروف میں اضافہ کرتے گئے یہاں تک کہ سات حرفوں تک پہنچ گئے ۔ \"\" ابن شہاب نے کہا : مجھے خبر پہنچی کہ پڑھنے کی یہ سات صورتیں ( سات حروف ) ایسے معاملے میں ہوتیں جو ( حقیقتاً اور معناً ) ایک ہی رہتا ، ( ان کی وجہ سے ) حلال وحرام کے اعتبار سے کوئی اختلاف نہ ہوتا ۔","",{"u2":"یونس نے ابن شہاب سے روایت کی،انھوں نے کہا:مجھ سے عبیداللہ بن عبداللہ بن عتبہ نے حدیث بیان کی کہ حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے ان سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جبرئیل علیہ السلام نے مجھے ایک حرف پر (قرآن) پڑھایا،میں نے ان سے مراجعت کی،پھر میں زیادہ کا تقاضا کرتا رہا اور وہ میرے لئے حروف میں اضافہ کرتے گئے یہاں تک کہ سات حرفوں تک پہنچ گئے۔\"\nابن شہاب نے کہا:مجھے خبر پہنچی کہ پڑھنے کی یہ سات صورتیں(سات حروف) ایسے معاملے میں ہوتیں جو(حقیقتاً اور معناً)ایک ہی رہتا،(ان کی وجہ سے) حلال وحرام کے اعتبار سے کوئی اختلاف نہ ہوتا۔"}],[1845,"ہمیں معمر نے زہری سے اسی سند کے ساتھ خبر دی ۔","",{"u2":"ہمیں معمر نے زہری سے اسی سند کے ساتھ خبر دی۔"}],[1846,"عبداللہ بن نمیر نے کہا : اسماعیل بن ابی خالد نے ہمیں حدیث بیان کی ، انھوں نے عبداللہ بن عیسی بن عبدالرحمان بن ابی یعلی سے ، انھوں نے اپنے دادا ( عبدالرحمان ) سے اور انھوں نے سیدنا ابی ابن کعب رضی اللہ تعالی عنہ سے روایت کی ، انھوں نے کہا : میں مسجد میں تھا کہ ایک آدمی داخل ہوا ، نماز پڑھنے لگا اور اس نے جس طرح قراءت کی اس کو میں نے اس کے سامنے ناقابل مقبول قرار دے دیا ۔ پھر ایک اور آدمی آیا ، پھر ایک اور آدمی آیا ، اس نے ایسی قراءت کی جو اس کے ساتھی ( پہلے آدمی ) کی قراءت سے مختلف تھی ، جب ہم نماز سے فارغ ہوئے تو ہم سب رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ، میں نے عرض کی کہ اس شخص نے ایسی قراءت کی جو میں نے اس کے سامنے رد کردی اور دوسرا آیا تو اس نے اپنے ساتھی سے بھی الگ قراءت کی ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے انھیں حکم دیا ، ان دونوں نے قراءت کی ۔ نبی اکرم صلی اللہ علیہ وسلم نے ان دونوں کے انداز کی تحسین فرمائی تو میرے دل میں آپ کی تکذیب ( جھٹلانے ) کا داعیہ اس زور سے ڈالا گیا جتنا اس وقت بھی نہ تھا جب میں جاہلیت میں تھا ۔ جب رسول اللہ صلی اللہ علیہ وسلم نے مجھ پر طاری ہونے والی اس کیفیت کو دیکھا تو میرے سینے میں مارا جس سے میں پسینہ پسینہ ہوگیا ، جیسے میں ڈر کے عالم میں اللہ کو دیکھ رہا ہوں ، آ پ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \" میرے پاس حکم بھیجا گیا کہ میں قرآن ایک حرف ( قراءت کی ایک صورت ) پر پڑھوں ۔ تو میں نے جواباً درخواست کی کہ میری امت پر آسانی فرمائیں ۔ تو میرے پاس دوبارہ جواب بھیجا کہ میں اسے دو حرفوں پر پڑھوں ۔ میں نے پھر عرض کی کہ میری امت کے لئے آسانی فرمائیں ۔ تو میرئے پاس تیسری بار جواب بھیجا کہ اسے سات حروف پر پڑھیے ، نیز آپ کے لئے ہر جواب کے بدلے جو میں نے دیا ایک دعا ہے جو آپ مجھ سے مانگیں ۔ میں نے عرض کی : اے میرے اللہ!میری امت کو بخش دے ۔ اور تیسری دعا میں نے اس دن کے لئے موخر کرلی ہے جس دن تمام مخلوق حتی کہ ابراہیم علیہ السلام بھی میری طرف راغب ہوں گے ۔","",{"u2":"عبداللہ بن نمیر نے کہا:اسماعیل بن ابی خالد نے ہمیں حدیث بیان کی،انھوں نے عبداللہ بن عیسیٰ بن عبدالرحمان بن ابی یعلیٰ سے،انھوں نے اپنے دادا(عبدالرحمان) سے اور انھوں نے حضرت ابی ابن کعب رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:میں مسجد میں تھا کہ ایک آدمی داخل ہوا،نماز پڑھنے لگا اور اس نے جس طرح قراءت کی اس کو میں نے اس کے سامنے ناقابل مقبول قرار دے دیا۔پھر ایک اور آدمی آیا،پھر ایک اور آدمی آیا،اس نے ایسی قراءت کی جو اس کے ساتھی(پہلے آدمی) کی قراءت سے مختلف تھی،جب ہم نماز سے فارغ ہوئے تو ہم سب رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے،میں نے عرض کی کہ اس شخص نے ایسی قراءت کی جو میں نے اس کے سامنے رد کردی اور دوسرا آیا تو اس نے اپنے ساتھی سے بھی الگ قراءت کی۔تو رسول اللہ صلی اللہ علیہ وسلم نے انھیں حکم دیا،ان دونوں نے قراءت کی۔نبی اکرم صلی اللہ علیہ وسلم نے ان دونوں کے انداز کی تحسین فرمائی تو میرے دل میں آپ کی تکذیب(جھٹلانے) کا داعیہ اس زور سے ڈالا گیا جتنا اس وقت بھی نہ تھا جب میں جاہلیت میں تھا۔جب رسول اللہ صلی اللہ علیہ وسلم نے مجھ پر طاری ہونے والی اس کیفیت کو دیکھا تو میرے سینے میں مارا جس سے میں پسینہ پسینہ ہوگیا،جیسے میں ڈر کے عالم میں اللہ کو دیکھ رہا ہوں،آ پ صلی اللہ علیہ وسلم نے مجھ سے فرمایا:\"میرے پاس حکم بھیجا گیا کہ میں قرآن ایک حرف(قراءت کی ایک صورت)پر پڑھوں۔تو میں نے جواباً درخواست کی کہ میری امت پر آسانی فرمائیں۔تو میرے پاس دوبارہ جواب بھیجا کہ میں اسے دو حرفوں پر پڑھوں۔میں نے پھر عرض کی کہ میری امت کے لئے آسانی فرمائیں۔تو میرئے پاس تیسری بار جواب بھیجا کہ اسے سات حروف پر پڑھیے،نیز آپ کے لئے ہر جواب کے بدلے جو میں نے دیا ایک دعا ہے جو آپ مجھ سے مانگیں۔میں نے عرض کی:اے میرے اللہ!میری امت کو بخش دے۔اور تیسری دعا میں نے اس دن کے لئے موخر کرلی ہے جس دن تمام مخلوق حتیٰ کہ ابراہیم علیہ السلام بھی میری طرف راغب ہوں گے۔\""}],[1847,"محمد بن بشر نے اسماعیل بن ابی خالد سے اسی سند کے ساتھ روایت کی کہ سیدنا ابی ابن کعب رضی اللہ تعالی عنہ نے بتایا کہ میں اس مسجد میں بیٹھا ہوا تھا کہ ایک آدمی داخل ہوا اور نماز پڑھی ، اس نے اس طرح قراءت کی ۔ ۔ ۔ ( آگے ) عبداللہ بن نمیر کی طرح حدیث بیان کی ۔","",{"u2":"محمد بن بشر نے اسماعیل بن ابی خالد سے اسی سند کے ساتھ روایت کی کہ حضرت ابی ابن کعب رضی اللہ تعالیٰ عنہ نے بتایا کہ میں اس مسجد میں بیٹھا ہوا تھا کہ ایک آدمی داخل ہوا اور نماز پڑھی،اس نے اس طرح قراءت کی۔۔۔(آگے) عبداللہ بن نمیر کی طرح حدیث بیان کی۔"}],[1848,"محمد بن جعفر غندر نے شعبہ سے روایت کی ، انھوں نے حکم سے ، انھوں نے مجاہد سے ، انھوں نے ابن ابی لیلی سے اور انھوں نے سیدنا ابی بن کعب رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم بنو غفار کے اضاۃ ( بارانی تالاب ) کے پاس تشریف فرما تھے ۔ کہا : آپ کے پاس جبرئیل ؑ آئے اور کہا : اللہ تعالی نے آپ کو حکم دیا ہے کہ آپ کی امت ایک حرف ( قراءت کی صورت ) پر قرآن پڑھے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" میں اللہ تعالی سے اس کا عفو ( درگزر ) اور اس کی مغفرت چاہتاہوں میری امت اس کی طاقت نہیں رکھتی ۔ \" پھر وہ جبرئیل علیہ السلام دوبارہ آپ کے پاس آئے ۔ اور کہا کہ اللہ تعالی حکم دیتا ہے کہ آپ کی امت دو حرفوں پر قرآن پڑھے ۔ آپ صلی اللہ علیہ وسلم نے کہا : \" میں اللہ تعالی سے اس کا عفو اور بخشش مانگتا ہوں ، میری امت اس کی طاقت نہیں رکھتی ۔ پھر وہ جبرئیل علیہ السلام تیسری بار آپ کے پاس آئے ۔ اور کہا کہ اللہ تعالی حکم دیتا ہے کہ آپ کی امت تین حرفوں پر قرآن پڑھے ۔ آپ صلی اللہ علیہ وسلم نے کہا : \" میں اللہ تعالی سے اس کا عفو اور بخشش مانگتا ہوں ، میری امت اس کی طاقت نہیں رکھتی ۔ پھر وہ جبرئیل علیہ السلام چوتھی مرتبہ آپ کے پاس آئے ۔ اور کہا کہ اللہ تعالی حکم دیتا ہے کہ آپ کی امت سات حرفوں پر قرآن پڑھے ۔ وہ جس حرف پر بھی پڑھیں گے ٹھیک پڑھیں گے ۔","",{"u2":"محمد بن جعفر غندر نے شعبہ سے روایت کی،انھوں نے حکم سے،انھوں نے مجاہد سے،انھوں نے ابن ابی لیلیٰ سے اور انھوں نے حضرت ابی بن کعب رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم بنو غفار کے اضاۃ(بارانی تالاب) کے پاس تشریف فرما تھے۔کہا:آپ کے پاس جبرئیل علیہ السلام آئے اور کہا:اللہ تعالیٰ نے آپ کو حکم دیا ہے کہ آپ کی امت ایک حرف(قراءت کی صورت) پر قرآن پڑھے۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"میں اللہ تعالیٰ سے اس کا عفو(درگزر) اور اس کی مغفرت چاہتاہوں میری امت اس کی طاقت نہیں رکھتی۔\"پھر وہ جبرئیل علیہ السلام دوبارہ آپ کے پاس آئے۔اور کہا کہ اللہ تعالیٰ حکم دیتا ہے کہ آپ کی امت دو حرفوں پرقرآن پڑھے۔آپ صلی اللہ علیہ وسلم نے کہا:\"میں اللہ تعالیٰ سے اس کا عفو اور بخشش مانگتا ہوں،میری امت اس کی طاقت نہیں رکھتی۔ پھر وہ جبرئیل علیہ السلام تیسری بار آپ کے پاس آئے۔اور کہا کہ اللہ تعالیٰ حکم دیتا ہے کہ آپ کی امت تین حرفوں پرقرآن پڑھے۔آپ صلی اللہ علیہ وسلم نے کہا:\"میں اللہ تعالیٰ سے اس کا عفو اور بخشش مانگتا ہوں،میری امت اس کی طاقت نہیں رکھتی۔ پھر وہ جبرئیل علیہ السلام چوتھی مرتبہ آپ کے پاس آئے۔اور کہا کہ اللہ تعالیٰ حکم دیتا ہے کہ آپ کی امت سات حرفوں پرقرآن پڑھے۔وہ جس حرف پر بھی پڑھیں گے ٹھیک پڑھیں گے۔"}],[1849,"معاذ عنبری نے شعبہ سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔",""],[1850,"ابو بکر بن ابی شیبہ اور ابن نمیر نے وکیع سے ، انھوں نے اعمش سے اور انھوں نے ابو وائل سے روایت کی ، انھوں نے کہا : ا یک آدمی جو نہیک بن سنان کہلاتا تھا ۔ سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ کے پاس آیا اور کہا : ابو عبدالرحمان! آپ اس کلمے کو کیسے پڑھتے ہیں؟آپ اسے الف کے ساتھ «مِّن مَّاءٍ» غَيْرِ‌آسِنٍ سمجھتے ہیں ۔ یا پھر یاء کے ساتھ ص «مِّن مَّاءٍ» غَيْرِ‌ياسِنٍ ؟تو عبداللہ رضی اللہ تعالی عنہ نے اس سے پوچھا : تم نے اس لفظ کے سوا تمام قرآن مجید یادکرلیاہے؟اس نے کہا : میں ( تمام ) مفصل سورتیں ایک رکعت میں پڑھتا ہوں ۔ اس پر سیدنا عبداللہ رضی اللہ تعالی عنہ نے فرمایا : شعر کی سی تیز رفتاری کےساتھ پڑھتے ہو؟کچھ لوگ قرآن مجید پڑھتے ہیں وہ ان کے گلوں سے نیچے نہیں اترتا ، لیکن جب وہ دل میں پہنچتا اور اس میں راسخ ہوتاہے تو نفع دیتا ہے ۔ نماز میں افضل رکوع اور سجدے ہیں اور میں ان ایک جیسی سورتوں کو جانتا ہوں جن کو رسول اللہ صلی اللہ علیہ وسلم ملایا کر تے تھے ، دو دو ( ملا کر ) ایک رکعت میں پڑھتے تھے ، پھر عبداللہ اٹھ کرچلے گئے ، اس پر علقمہ بھی ان کے پیچھے اندر چلے گئے ، پھر واپس آئے اور کہا : مجھے انھوں نے وہ سورتیں بتادی ہیں ۔ ابن نمیر نے اپنی روایت میں کہا : بنو بجیلہ کا ایک شخص سیدنا عبداللہ رضی اللہ تعالی عنہ ( بن مسعود ) کے پاس آیا ، انھوں نے \"\" نہیک بن سنان \"\" نہیں کہا ۔","",{"u2":"ابو بکر بن ابی شیبہ اور ابن نمیر نے وکیع سے،انھوں نے اعمش سے اور انھوں نے ابو وائل سے روایت کی،انھوں نے کہا: ا یک آدمی جو نہیک بن سنان کہلاتا تھا۔حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کے پاس آیا اور کہا:ابو عبدالرحمان! آپ اس کلمے کو کیسےپڑھتے ہیں؟آپ اسے الف کے ساتھ مِّن مَّاءٍ غَیْرِ‌آسِنٍ سمجھتے ہیں۔ یا پھر یاء کے ساتھ ص مِّن مَّاءٍ غَیْرِ‌یاسِنٍ؟تو عبداللہ رضی اللہ تعالیٰ عنہ نے اس سے پوچھا:تم نے اس لفظ کے سواتمام قرآن مجید یادکرلیاہے؟اس نے کہا:میں (تمام) مفصل سورتیں ایک رکعت میں پڑھتاہوں۔اس پر حضرت عبداللہ رضی اللہ تعالیٰ عنہ نے فرمایا:شعر کی سی تیز رفتاری کےساتھ پڑھتے ہو؟کچھ لوگ قرآن مجید پڑھتے ہیں وہ ان کے گلوں سے نیچے نہیں اترتا،لیکن جب وہ دل میں پہنچتا اور اس میں راسخ ہوتاہے تو نفع دیتا ہے۔نماز میں افضل رکوع اور سجدے ہیں اور میں ان ایک جیسی سورتوں کو جانتا ہوں جن کو رسول اللہ صلی اللہ علیہ وسلم ملایا کر تے تھے،دو دو(ملا کر) ایک رکعت میں پڑھتے تھے،پھر عبداللہ اٹھ کرچلے گئے،اس پر علقمہ بھی ان کے پیچھے اندر چلے گئے،پھر واپس آئے اور کہا:مجھے انھوں نے وہ سورتیں بتادی ہیں۔\nابن نمیر نے اپنی روایت میں کہا:بنو بجیلہ کا ایک شخص حضرت عبداللہ رضی اللہ تعالیٰ عنہ (بن مسعود) کے پاس آیا،انھوں نے \"نہیک بن سنان\" نہیں کہا۔"}],[1851,"ابو معاویہ نے اعمش سے ، انھوں نے ابو وائل سے روایت کی ، انھوں نے کہا : سیدنا عبداللہ کے پاس ایک آدمی آیا جسے نہیک بن سنان کہا جاتا تھا ۔ ۔ ۔ ( آگے ) وکیع کی روایت کے مانند ہے ، مگر انھوں نے کہا : علقمہ سیدنا عبداللہ رضی اللہ تعالی عنہ کے پاس ( گھر کے اندر ) حاضری دینے آئے تو ہم نے ان سے کہا : سیدنا عبداللہ رضی اللہ تعالی عنہ سے ان باہم ملتی جلتی سورتوں کے بارے میں پوچھیں جو رسول اللہ صلی اللہ علیہ وسلم ایک رکعت میں پڑھتے تھے ۔ وہ ان کے پاس اندر چلے گئے اور ان سورتوں کے بارے میں ان سے پوچھا ، پھر ہمارے پاس تشریف لائے اور بتایا ، وہ سیدنا عبداللہ رضی اللہ تعالی عنہ ( کے مصحف ) کی ترتیب کے مطابق مفصل بیس سورتیں ہیں ( جنھیں آپ صلی اللہ علیہ وسلم ) دس رکعتوں میں ( پڑھتے تھے ۔)","",{"u2":"ابو معاویہ نے اعمش سے،انھوں نے ابو وائل سے روایت کی،انھوں نے کہا:حضرت عبداللہ کے پاس ایک آدمی آیا جسے نہیک بن سنان کہا جاتا تھا۔۔۔(آگے) وکیع کی روایت کے مانند ہے،مگر انھوں نے کہا:علقمہ حضرت عبداللہ رضی اللہ تعالیٰ عنہ کے پاس(گھر کے اندر) حاضری دینے آئے تو ہم نے ان سے کہا:حضرت عبداللہ رضی اللہ تعالیٰ عنہ سے ان باہم ملتی جلتی سورتوں کے بارے میں پوچھیں جو ر سول اللہ صلی اللہ علیہ وسلم ایک رکعت میں پڑھتے تھے۔وہ ان کے پاس اندر چلے گئے اور ان سورتوں کے بارے میں ان سے پوچھا،پھر ہمارے پاس تشریف لائے اوربتایا،وہ حضرت عبداللہ رضی اللہ تعالیٰ عنہ (کے مصحف) کی ترتیب کے مطابق مفصل بیس سورتیں ہیں(جنھیں آپ صلی اللہ علیہ وسلم) دس رکعتوں میں (پڑھتے تھے۔)"}],[1852,"عیسی بن یونس نے کہا : اعمش نے ہم سے اپنی اسی سند کے ساتھ ان دونوں ( وکیع اور ابو معاویہ ) کی حدیث کی طرح بیان کی ۔ اس میں ہے انھوں ( عبداللہ رضی اللہ تعالی عنہ ) نے کہا : میں ان ایک جیسی سورتوں کو جانتا ہوں جو رسول اللہ صلی اللہ علیہ وسلم دو دو ملا کر ایک رکعت میں پڑھتے تھے ، بیس سورتیں دس رکعتوں میں ۔","",{"u2":"عیسیٰ بن یونس نے کہا:اعمش نے ہم سے اپنی اسی سند کے ساتھ ان دونوں (وکیع اور ابو معاویہ) کی حدیث کی طرح بیان کی۔اس میں ہے انھوں(عبداللہ رضی اللہ تعالیٰ عنہ) نے کہا:میں ان ایک جیسی سورتوں کو جانتا ہوں جو رسول اللہ صلی اللہ علیہ وسلم دو دو ملا کر ایک رکعت میں پڑھتے تھے،بیس سورتیں دس رکعتوں میں۔"}],[1853,"مہدی بن میمون نے کہا : واصل حدب نے ہمیں ابو وائل سے حدیث بیان کی ، انھوں نے کہا : ایک دن ہم صبح کی نماز پڑھنے کے بعد سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ کی خدمت میں حاضر ہوئے ، ہم نے دروازے سے ( انھیں ) سلام عرض کیا ، انھوں نے ہمیں اندر آنے کی اجازت دی ، ہم کچھ دیر دروازے پر رکے رہے ، اتنے میں ایک بچی نکلی اور کہنے لگی : کیا آپ لوگ اندر نہیں آئیں گے؟ ہم اندر چلے گئے اور وہ بیٹھے تسبیحات پڑھ رہے تھے ، انھوں نے پوچھا : جب آپ لوگوں کو اجازت دے دی گئی تو پھر آنے میں کیا رکاوٹ تھی؟ہم نے عرض کی : نہیں ( رکاوٹ نہیں تھی ) ، البتہ ہم نے سوچا ( کہ شاید ) گھر کے بعض افراد سوئے ہوئے ہوں ۔ انھوں نے فرمایا : تم نے ابن ام عبد کے گھر والوں کے متعلق غفلت کا گمان کیا؟ پھر دوبارہ تسبحات میں مشغول ہوگئے حتی کہ انھوں نے محسوس کیا کہ سورج نکل آیا ہوگا تو فرمایا : اے بچی!دیکھو تو! کیا سورج نکل آیا ہے؟اس نے دیکھا ، ابھی سورج نہیں نکلا تھا ، وہ پھر تسبیح کی طرف متوجہ ہوگئے حتی کہ پھر جب انھوں نے محسوس کیا کہ سورج طلوع ہوگیا ہے تو کہا اے لڑکی!دیکھو کیا سورج طلوع ہوگیا ہے اس نے د یکھا تو سورج طلوع ہوچکا تھا ، انھوں نے فرمایا : اللہ کی حمد جس نے ہمیں یہ دن لوٹا دیا ۔ مہدی نے کہا : میرے خیال میں انھوں نے یہ بھی کہا ۔ ۔ ۔ اور ہمارے گناہوں کی پاداش میں ہمیں ہلاک نہیں کیا ۔ لوگوں میں سے ایک آدمی نے کہا : میں نے کل رات تمام مفصل سورتوں کی تلاوت کی ، اس پر عبداللہ رضی اللہ تعالی عنہ نے کہا : تیزی سے ، جس طرح شعر تیز پڑھے جاتے ہیں؟ہم نے باہم ملا کر پڑھی جانے والی سورتوں کی سماعت کی ہے ۔ اور مجھے وہ دو دو سورتیں یاد ہیں جنھیں رسول اللہ صلی اللہ علیہ وسلم پڑھا کرتے تھے مفصل میں سے اٹھارہ سورتیں اور دوسورتیں حمٰ والی ۔","",{"u2":"مہدی بن میمون نے کہا: واصل حدب نے ہمیں ابو وائل سے حدیث بیان کی،انھوں نے کہا: ایک دن ہم صبح کی نماز پڑھنے کے بعدحضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کی خدمت میں حاضر ہوئے،ہم نے دروازے سے(انھیں) سلام عرض کیا،انھوں نے ہمیں اندر آنے کی اجازت دی،ہم کچھ دیر دروازے پر رکے رہے،اتنے میں ایک بچی نکلی اور کہنے لگی:کیا آپ لوگ اندر نہیں آئیں گے؟ ہم اندر چلے گئے اور وہ بیٹھے تسبیحات پڑھ رہے تھے،انھوں نے پوچھا:جب آپ لوگوں کو اجازت دے دی گئی تو پھر آنے میں کیارکاوٹ تھی؟ہم نے عرض کی:نہیں(رکاوٹ نہیں تھی)،البتہ ہم نے سوچا(کہ شاید) گھر کے بعض افراد سوئے ہوئے ہوں۔انھوں نے فرمایا:تم نے ابن ام عبد کے گھر والوں کے متعلق غفلت کا گمان کیا؟ پھر دوبارہ تسبحات میں مشغول ہوگئے حتیٰ کہ انھوں نے محسوس کیا کہ سورج نکل آیا ہوگا تو فرمایا:اے بچی!دیکھو تو! کیا سورج نکل آیا ہے؟اس نے دیکھا،ابھی سورج نہیں نکلا تھا،وہ پھر تسبیح کی طرف متوجہ ہوگئے حتیٰ کہ پھر جب انھوں نے محسوس کیا کہ سورج طلوع ہوگیا ہے تو کہا اے لڑکی!دیکھو کیاسورج طلوع ہوگیا ہے اس نے د یکھا تو سورج طلوع ہوچکا تھا،انھوں نے فرمایا:اللہ کی حمد جس نے ہمیں یہ دن لوٹا دیا۔مہدی نے کہا:میرے خیال میں انھوں نے یہ بھی کہا۔۔۔اور ہمارے گناہوں کی پاداش میں ہمیں ہلاک نہیں کیا۔لوگوں میں سے ایک آدمی نے کہا:میں نے کل رات تمام مفصل سورتوں کی تلاوت کی،اس پر عبداللہ رضی اللہ تعالیٰ عنہ نے کہا:تیزی سے،جس طرح شعر تیز پڑھے جاتے ہیں؟ہم نے باہم ملا کر پڑھی جانے والی سورتوں کی سماعت کی ہے۔اور مجھے وہ دو دو سورتیں یاد ہیں جنھیں رسول اللہ صلی اللہ علیہ وسلم پڑھا کرتے تھےمفصل میں سے اٹھارہ سورتیں اور دوسورتیں حمٰ والی۔"}],[1854,"منصور نے ( ابووائل ) شقیق سے روایت کی ، انھوں نے کہا : بنو بجیلہ میں سے ایک آدمی جسے نہیک بن سنان کہا جاتاتھا ۔ سیدنا عبداللہ رضی اللہ تعالی عنہ کے پاس آیا اور کہنے لگا : میں ( تمام ) مفصل سورتیں ایک رکعت میں پڑھتا ہوں ۔ سیدنا عبداللہ رضی اللہ تعالی عنہ نے فرمایا : تیزی سے جیسے شعر تیزی سے پڑھے جاتے ہیں؟مجھے وہ باہم ملتی جلتی سورتیں معلوم ہیں جنھیں رسول اللہ صلی اللہ علیہ وسلم ایک ایک رکعت میں دو دو کرکے پڑھتے تھے ۔","",{"u2":"منصور نے(ابووائل) شقیق سے روایت کی،انھوں نے کہا:بنو بجیلہ میں سے ایک آدمی جسے نہیک بن سنان کہا جاتاتھا۔حضرت عبداللہ رضی اللہ تعالیٰ عنہ کے پاس آیا اور کہنے لگا:میں (تمام)مفصل سورتیں ایک رکعت میں پڑھتا ہوں۔حضرت عبداللہ رضی اللہ تعالیٰ عنہ نے فرمایا:تیزی سے جیسے شعر تیزی سے پڑھے جاتے ہیں؟مجھے وہ باہم ملتی جلتی سورتیں معلوم ہیں جنھیں رسول اللہ صلی اللہ علیہ وسلم ایک ایک رکعت میں دو دو کرکے پڑھتے تھے۔"}],[1855,"عمرو بن مرہ سے روایت ہے ۔ انھوں نے ابو وائل سے سنا وہ حدیث بیان کر رہے تھے کہ ایک آدمی سیدنا عبد اللہ بن مسعود رضی اللہ تعالی عنہ کے پاس آیا اور کہا : میں نے آج رات ( تمام ) مفصل سورتیں ایک رکعت میں پڑھی ہیں تو عبد اللہ رضی اللہ تعالی عنہ نے فر ما یا : اس تیز رفتاری سے جس طرح شعر پڑھے جاتے ہیں؟ ( پھر ) عبد اللہ رضی اللہ تعالی عنہ نے فر ما یا : میں وہ نظائر ( ایک جیسی سورتیں ) پہچا نتا ہوں جن کو رسول اللہ صلی اللہ علیہ وسلم ملا کر پڑھا کرتے تھے انھوں نے مفصل سورتوں میں سے بیس سورتیں بتا ئیں جنھیں رسول اللہ صلی اللہ علیہ وسلم دو دوملا کر ایک رکعت میں پڑھتے تھے ۔ ( ان سورتوں کی تفصیل کے لیے دیکھیے سنن ابی داؤد شھر رمضان باب تخریب القرآن)","",{"u2":"عمرو بن مرہ سے روایت ہے۔انھوں نے ابو وائل سے سنا وہ حدیث بیان کر رہے تھے کہ ایک آدمی حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ کے پاس آیا اور کہا: میں نے آج رات (تمام) مفصل سورتیں ایک رکعت میں پڑھی ہیں تو عبد اللہ رضی اللہ تعالیٰ عنہ نے فر ما یا: اس تیز رفتاری سے جس طرح شعر پڑھے جاتے ہیں؟(پھر)عبد اللہ رضی اللہ تعالیٰ عنہ نے فر ما یا:میں وہ نظائر (ایک جیسی سورتیں) پہچا نتا ہوں جن کو رسول اللہ صلی اللہ علیہ وسلم ملا کر پڑھا کرتے تھے انھوں نے مفصل سورتوں میں سے بیس سورتیں بتا ئیں جنھیں رسول اللہ صلی اللہ علیہ وسلم دو دوملا کر ایک رکعت میں پڑھتے تھے۔(ان سورتوں کی تفصیل کے لیے دیکھیے سنن ابی داؤد شھر رمضان باب تخریب القرآن 1396)"}],[1856,"زہیر نے کہا : ہم سے ابو اسحاق نے حدیث بیان کی ، انھوں نے کہا : میں نے ایک آدمی کو دیکھا اس نے اسود بن یزید ( سبیعی کوفی ) سے جبکہ وہ مسجد میں قرآن کی تعلیم دے رہے تھے ۔ سوال کیا : تم اس ( آیت ) کو کیسے پڑھتے ہو ؟دال پڑھتے یا ذال ؟ انھوں نے جواب دیا : دال پڑھتا ہوں ۔ میں نے عبد اللہ بن مسعود رضی اللہ تعالی عنہ سے سنا وہ بتا رہے تھے ۔ کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فَهَلْ مِن مُّدَّكِرٍ دال کے ساتھ پڑھتے سنا ۔","",{"u2":"زہیر نے کہا:ہم سے ابو اسحاق نے حدیث بیان کی،انھوں نے کہا: میں نے ایک آدمی کو دیکھا اس نے اسود بن یزید (سبیعی کوفی) سے جبکہ وہ مسجد میں قرآن کی تعلیم دے رہے تھے۔سوال کیا:تم اس (آیت)کو کیسے پڑھتے ہو؟دال پڑھتے یا ذال؟ انھوں نے جواب دیا:دال پڑھتا ہوں۔میں نے عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے سنا وہ بتا رہے تھے۔کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فَہَلْ مِن مُّدَّکِرٍ‌ دال کے ساتھ پڑھتے سنا۔"}],[1857,"شعبہ نے ابو اسحاق سے انھوں نے اسود سے انھوں نے سیدنا عبد اللہ بن مسعود رضی اللہ تعالی عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روا یت کی کہ آ پ صلی اللہ علیہ وسلم اس کلمے مُّدَّكِرٍ پڑھتے تھے ( یعنی دال کے ساتھ)","",{"u2":"شعبہ نے ابو اسحاق سے انھوں نے اسود سے انھوں نے حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روا یت کی کہ آ پ صلی اللہ علیہ وسلم اس کلمے مُّدَّکِرٍ‌ پڑھتے تھے (یعنی دال کے ساتھ)"}],[1858,"اعمش نے ابرا ہیم سے اور انھوں نے علقمہ ( بن قیس کوفی ) سے روایت کی انھوں نے کہا : ہم شام آئے تو ہمارے پاس سیدنا ابو دارداء رضی اللہ تعالی عنہ تشریف لا ئے اور انھوں نے پو چھا : کیا تم میں سے کو ئی ایسا ہے جو عبداللہ بن مسعود رضی اللہ تعالی عنہ کی قراءت کے مطابق پڑھتا ہو ؟میں نے عرض کی : جی ہاں میں ( پڑھتا ہوں ) انھوں نے پو چھا : تم نے عبد اللہ بن مسعود رضی اللہ تعالی عنہ کو یہ آیت «وَاللَّيْلِ إِذَا يَغْشَىٰ» کسی طرح پڑھتے سنا ہے ۔ ( میں نے ) کہا : میں نے انھیںوَاللَّيْلِ «إِذَا يَغْشَىٰ» و الذَّكَرَ‌وَالْأُنثَىٰ پڑھتے سنا ۔ انھوں نے کہا : اور میں نے بھی اللہ کی قسم !رسول اللہ صلی اللہ علیہ وسلم کو ایسے ہی پڑھتے سنا لیکن یہ لو گ چا ہتے ہیں کہ میں «وَمَا خَلَقَ» الذَّكَرَ‌وَالْأُنثَىٰ پڑھوں میں ان کے پیچھے نہیں چلوں گا ۔ ( ابن مسعود اور ابودرداء رضی اللہ تعالی عنہ غالباًقراءت کی اس دوسری صورت سے آگاہ نہ ہو سکے جو رسول اللہ صلی اللہ علیہ وسلم ہی نے سکھا ئی تھی ۔)","",{"u2":"اعمش نے ابرا ہیم سے اور انھوں نے علقمہ (بن قیس کوفی)سے روایت کی انھوں نے کہا: ہم شام آئے تو ہمارے پاس حضرت ابو دارداء رضی اللہ تعالیٰ عنہ تشریف لا ئے اور انھوں نے پو چھا:کیا تم میں سے کو ئی ایسا ہے جو عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کی قراءت کے مطابق پڑھتا ہو؟میں نے عرض کی:جی ہاں میں (پڑھتا ہوں) انھوں نے پو چھا:تم نے عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ کو یہ آیت وَاللَّیْلِ إِذَا یَغْشَیٰ کسی طرح پڑھتے سناہے۔(میں نے)کہا: میں نے انھیںوَاللَّیْلِ إِذَا یَغْشَیٰ و الذَّکَرَ‌وَالْأُنثَیٰ پڑھتے سنا۔انھوں نے کہا: اور میں نے بھی اللہ کی قسم!رسول اللہ صلی اللہ علیہ وسلم کو ایسے ہی پڑھتے سنا لیکن یہ لو گ چا ہتے ہیں کہ میں وَمَا خَلَقَ الذَّکَرَ‌وَالْأُنثَیٰ پڑھوں میں ان کے پیچھے نہیں چلوں گا۔(ابن مسعود اور ابودرداء رضی اللہ تعالیٰ عنہ غالباًقراءت کی اس دوسری صورت سے آگاہ نہ ہو سکے جو رسول اللہ صلی اللہ علیہ وسلم ہی نے سکھا ئی تھی۔)"}],[1859,"مغیرہ نے ابرا ہیم سے روا یت کی ، انھوں نے کہا : علقم ہشام آئے اور ایک مسجد میں داخل ہو ئے اس میں نماز پڑھی ، پھر لو گو ں کے ایک حلقے میں جا کر بیٹھ گئے اتنے میں ایک صاحب آئے تو مجھے ان کے ( ارد گرد ) لو گوں کے اکٹھا ہو نے اور ( انکی وجہ سے ) ایک خاص ہیئت اختیار کر لینے کا پتہ چل گیا ( اس سے معلوم ہو تا تھا کہ وہ خاص شخصیت ہیں ) ( علقمہ نے کہا : وہ میرے پہلو میں بیٹھ گئے ۔ پھر فر ما یا : عبد اللہ رضی اللہ تعالی عنہ ( بن مسعود رضی اللہ تعالی عنہ ) جس طرح پڑھا کرتے تھے کیا تمھیں وہ یاد ہے؟ اس کے بعد اسی ( پہلی حدیث کی ) طرح بیان کیا ۔","",{"u2":"مغیرہ نے ابرا ہیم سے روا یت کی،انھوں نے کہا:علقم ہشام آئے اور ایک مسجد میں داخل ہو ئے اس میں نماز پڑھی،پھر لو گو ں کے ایک حلقے میں جا کر بیٹھ گئے اتنے میں ایک صاحب آئے تو مجھے ان کے (ارد گرد)لو گوں کے اکٹھا ہو نے اور (انکی وجہ سے)ایک خاص ہیئت اختیار کر لینے کا پتہ چل گیا (اس سے معلوم ہو تا تھا کہ وہ خاص شخصیت ہیں)(علقمہ نے کہا: وہ میرے پہلو میں بیٹھ گئے۔پھر فر ما یا:عبد اللہ رضی اللہ تعالیٰ عنہ (بن مسعود رضی اللہ تعالیٰ عنہ)جس طرح پڑھا کرتے تھے کیا تمھیں وہ یاد ہے؟ اس کے بعد اسی (پہلی حدیث کی)طرح بیان کیا۔"}],[1860,"اسماعیل بن ابرا ہیم ( ابن علیہ ) نے داودبن ابی ہند سے انھوں نے شعبی سے اور انھوں نے علقمہ سے روا یت کی ، انھوں نے کہا : میں نے سیدنا ابو درداء رضی اللہ تعالی عنہ سے ملا انھوں نے مجھ سے پو چھا : تم کہاں سے ہو؟ میں نے کہا : اہل عراق سے انھوں نے پو چھا : ان کے کو ن سے لو گو ں میں سے؟ میں نے کہا : اہل کو فہ سے انھوں نے پوچھا : کیاتم ( قرآن مجید ) عبد اللہ بن مسعود رضی اللہ تعالی عنہ کی قراءت کے مطا بق پڑھتے ہو؟میں نے کہا : جی ہاں انھوں نے کہا : «وَاللَّيْلِ إِذَا يَغْشَىٰ» پڑھو ۔ میں نے پڑھا «وَاللَّيْلِ إِذَا يَغْشَىٰ» ﴿<http : //tanzil.net/>﴾ وَالنَّهَارِ‌إِذَا «تَجَلَّىٰ» ﴿<http : //tanzil.net/>﴾ وَ الذَّكَرَ‌وَالْأُنثَىٰ کہا : وہ ہنس پڑے پھر فر ما یا : میں نے اسی طرح رسول اللہ صلی اللہ علیہ وسلم کو پڑھتے سنا ۔","",{"u2":"اسماعیل بن ابرا ہیم (ابن علیہ) نے داودبن ابی ہند سے انھوں نے شعبی سے اور انھوں نے علقمہ سے روا یت کی، انھوں نے کہا: میں نے حضرت ابو درداء رضی اللہ تعالیٰ عنہ سے ملا انھوں نے مجھ سے پو چھا:تم کہاں سے ہو؟ میں نے کہا: اہل عراق سے انھوں نے پو چھا: ان کے کو ن سے لو گو ں میں سے؟ میں نے کہا: اہل کو فہ سے انھوں نے پوچھا: کیاتم(قرآن مجید) عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ کی قراءت کے مطا بق پڑھتے ہو؟میں نے کہا: جی ہاں انھوں نے کہا: وَاللَّیْلِ إِذَا یَغْشَیٰ پڑھو۔ میں نے پڑھا وَاللَّیْلِ إِذَا یَغْشَیٰ ﴿<http://tanzil.net/>﴾ وَالنَّہَارِ‌إِذَا تَجَلَّیٰ ﴿<http://tanzil.net/>﴾ وَ الذَّکَرَ‌وَالْأُنثَیٰ کہا: وہ ہنس پڑے پھر فر ما یا:میں نے اسی طرح رسول اللہ صلی اللہ علیہ وسلم کو پڑھتے سنا۔"}],[1861,"عبد الاعلیٰ نے کہا : ہم سے داود نے عامر ( شعبی ) سے اور انھوں نے علقمہ سے روا یت کی ، انھوں نے کہا : میں شام آیا اور سیدنا ابو درداء رضی اللہ تعالیٰ عنہ سے ملا ۔ ۔ ۔ ۔ آگے ابن علیہ ( اسماعیل بن ابرا ہیم ) کی ( مذکورہ با لا ) حدیث کی طرح بیا ن کیا ۔","",{"u2":"عبد الاعلیٰ نے کہا: ہم سے داودنے عامر (شعبی)سے اور انھوں نے علقمہ سے روا یت کی، انھوں نے کہا: میں شام آیا اور حضرت ابو درداء رضی اللہ تعالیٰ عنہ سے ملا۔۔۔۔آگے ابن علیہ (اسماعیل بن ابرا ہیم) کی (مذکورہ با لا) حدیث کی طرح بیا ن کیا۔"}],[1862,"سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز عصر کے بعد سورج غروب ہو نے تک نماز پڑھنے سے منع فر ما یا ۔ اور صبح کے بعد سورج طلوع ہو نے تک نماز سے منع فر ما یا ۔","",{"u2":"حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز عصر کے بعد سورج غروب ہو نے تک نماز پڑھنے سے منع فر ما یا۔اور صبح کے بعد سورج طلوع ہو نے تک نماز سے منع فر ما یا۔"}],[1863,"منصور نے قتادہ سے روا یت کی انھوں نے کہا : ہمیں ابو عالیہ نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے خبر دی انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ایک سے زیادہ ساتھیوں سے سنا ہے ان میں عمر بن خطاب رضی اللہ تعالیٰ عنہ بھی شامل ہیں اور وہ مجھے ان میں سب سے زیادہ محبوب تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز فجر کے بعد سورج طلوع ہو نے تک اور عصر کے بعد سورج غروب ہو نے تک نماز پڑھنے سے منع فر ما یا ہے ۔","",{"u2":"منصور نے قتادہ سے روا یت کی انھوں نے کہا: ہمیں ابو عالیہ نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے خبر دی انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ایک سے زیادہ ساتھیوں سے سنا ہے ان میں عمر بن خطاب رضی اللہ تعالیٰ عنہ بھی شامل ہیں اور وہ مجھے ان میں سب سے زیادہ محبوب تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز فجر کے بعد سورج طلوع ہو نے تک اور عصر کے بعد سورج غروب ہو نے تک نماز پڑھنے سے منع فر ما یا ہے۔"}],[1864,"شعبہ سعید اور معاذ بن ہشام نے اپنے والد کے واسطے سے قتادہ سے اسی سند کے ساتھ یہ روا یت بیان کی ، البتہ سعید اور ہشام کی حدیث میں ( نماز فجر کے بعد سورج طلوع ہو نے تک کے بجا ئے ) \" صبح کے بعد سورج چمکنے تک \" کے الفاظ ہیں ۔","",{"u2":"شعبہ سعید اور معاذ بن ہشام نے اپنے والد کے واسطے سے قتادہ سے اسی سند کے ساتھ یہ روا یت بیان کی، البتہ سعید اور ہشام کی حدیث میں (نماز فجر کے بعد سورج طلوع ہو نے تک کے بجا ئے)\"صبح کے بعد سورج چمکنے تک \"کے الفاظ ہیں۔"}],[1865,"عطاء بن یزید لیثی نے خبر دی کہ انھوں نے ابو سعید خدری رضی اللہ تعالیٰ عنہ کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" نماز عصر کے بعد کوئی نماز نہیں یہاں تک کہ سورج غروب ہوجائے اور نماز فجر کے بعد کوئی نماز نہیں یہاں تک کہ سورج طلوع ہوجائے ۔","",{"u2":"عطاء بن یزید لیثی نے خبر دی کہ انھوں نے ابو سعید خدری رضی اللہ تعالیٰ عنہ کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"نماز عصر کے بعد کوئی نماز نہیں یہاں تک کہ سورج غروب ہوجائے اور نماز فجر کے بعد کوئی نماز نہیں یہاں تک کہ سورج طلوع ہوجائے۔\""}],[1866,"نافع نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کوئی شخص ( جان بوجھ کر ) طلوع شمس اور غروب شمس کے وقت کا قصد کرکے ان اوقات میں نماز نہ پڑھے ۔","",{"u2":"نافع نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تم میں سے کوئی شخص(جان بوجھ کر) طلوع شمس اور غروب شمس کے وقت کا قصد کرکے ان اوقات میں نماز نہ پڑھے۔\""}],[1867,"ہشام کے والد عروہ نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اپنی نماز کے لئے جان بوجھ کر نہ سورج کے طلوع ہونے کا قصد کرو اور نہ اس کے غروب ہونے کا کیونکہ سورج شیطان کے دو سینگوں کے ساتھ طلوع ہوتا ہے ۔","",{"u2":"ہشام کے والد عروہ نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اپنی نماز کے لئے جان بوجھ کر نہ سورج کے طلوع ہونے کا قصد کرو اور نہ اس کے غروب ہونے کا کیونکہ سورج شیطان کے دو سینگوں کے ساتھ طلوع ہوتا ہے۔\""}],[1868,"سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب سورج کا کنارہ نمودار ہوجائے تو نماز موخر کردو حتیٰ کہ وہ ( سورج ) نکل آئے ( بلند ہوجائے ) اور جب سورج کا کنارہ غروب ہوجائے تو نماز موخر کردو حتیٰ کہ وہ ( سورج ) پوری طرح غائب ہوجائے ۔","",{"u2":"حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جب سورج کا کنارہ نمودار ہوجائے تو نماز موخر کردو حتیٰ کہ وہ(سورج) نکل آئے(بلند ہوجائے) اور جب سورج کا کنارہ غروب ہوجائے تو نماز موخر کردو حتیٰ کہ وہ(سورج) پوری طرح غائب ہوجائے۔\""}],[1869,"لیث نے خیر بن نعیم حضرمی سے روایت کی ، انھوں نے عبداللہ بن ہبیرہ سے ، انھوں نے ابو تمیم جیشانی سے اور انھوں نے ابو بصرہ رضی اللہ تعالیٰ عنہ غفاری سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں مخمص نامی جگہ میں عصر کی نماز پڑھائی اور فرمایا \" یہ نماز تم سے پہلے لوگوں کو دی گئی ( ان پر فرض کی گئی ) تو انھوں نے اسے ضائع کردیا ، اس لئے جو بھی اس کی حفاظت کرے گا اسے اس کا دوگنا اجر ملے گا اور ا س کے بعد کوئی نماز نہیں یہاں تک کہ ( اس کا ) شاہد طلوع ہوجائے ۔ \" شاہد ( سے مراد ) ستارہ ہے ۔","",{"u2":"لیث نے خیر بن نعیم حضرمی سے روایت کی،انھوں نے عبداللہ بن ہبیرہ سے،انھوں نے ابو تمیم جیشانی سے اور انھوں نے ابو بصرہ رضی اللہ تعالیٰ عنہ غفاری سے روایت کی،انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں مخمص نامی جگہ میں عصر کی نماز پڑھائی اور فرمایا\"یہ نماز تم سے پہلے لوگوں کو دی گئی(ان پر فرض کی گئی) تو انھوں نے اسے ضائع کردیا،اس لئے جو بھی اس کی حفاظت کرے گا اسے اس کا دوگنا اجر ملے گا اور ا س کے بعد کوئی نماز نہیں یہاں تک کہ (اس کا)شاہد طلوع ہوجائے۔\"شاہد(سے مراد) ستارہ ہے۔"}],[1870,"یزید بن ابی حبیب نے خیر بن نعیم حضرمی سے ، انھوں نے عبداللہ بن ہبیرہ سبائی سے ۔ ۔ ۔ اور وہ ثقہ تھے ۔ انھوں نے ابو تمیم جیشانی سے اور انھوں نے ابو بصرہ غفار ی سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں عصر کی نماز پڑھائی ۔ ۔ ۔ آگے سابقہ حدیث کے مانند ہے ۔","",{"u2":"یزید بن ابی حبیب نے خیر بن نعیم حضرمی سے،انھوں نے عبداللہ بن ہبیرہ سبائی سے۔۔۔اور وہ ثقہ تھے۔انھوں نے ابو تمیم جیشانی سے اور انھوں نے ابو بصرہ غفار ی سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے ہمیں عصر کی نماز پڑھائی۔۔۔آگے سابقہ حدیث کے مانند ہے۔"}],[1871,"سیدنا عقبہ بن عامر جہنی رضی اللہ تعالیٰ عنہ کہتے تھے کہ تین ا وقات ہیں ، رسول اللہ صلی اللہ علیہ وسلم ہمیں روکتے تھے کہ ہم ان میں نماز پڑھیں یا ان میں اپنے مردوں کو قبروں میں اتاریں : جب سورج چمکتا ہوا طلوع ہورہا ہو یہاں تک کہ وہ بلند ہوجائے اور جب دوپہر کو ٹھہرنے والا ( سایہ ) ٹھہر جاتا ہے حتیٰ کہ سورج ( آگے کو ) جھک جائے اور جب سورج غروب ہونے کے لئے جھکتا ہے یہاں تک کہ وہ ( پوری طرح ) غروب ہوجائے ۔","",{"u2":"حضرت عقبہ بن عامر جہنی رضی اللہ تعالیٰ عنہ کہتے تھے کہ تین ا وقات ہیں،رسول اللہ صلی اللہ علیہ وسلم ہمیں روکتے تھے کہ ہم ان میں نماز پڑھیں یا ان میں اپنے مردوں کو قبروں میں اتاریں:جب سورج چمکتا ہوا طلوع ہورہا ہو یہاں تک کہ وہ بلند ہوجائے اور جب دوپہر کو ٹھہرنے والا(سایہ)ٹھہر جاتا ہے حتیٰ کہ سورج(آگے کو)جھک جائے اور جب سورج غروب ہونے کے لئے جھکتا ہے یہاں تک کہ وہ (پوری طرح) غروب ہوجائے۔"}],[1872,"ابو عمار شداد بن عبداللہ اور یحییٰ بن ابی کثیر نے ابو امامہ سے روایت کی ۔ ۔ ۔ عکرمہ نے کہا : شداد ابو امامہ اور واثلہ رضی اللہ تعالیٰ عنہ سے مل چکا ہے ، وہ شام کے سفر میں سیدنا انس رضی اللہ تعالیٰ عنہ کے ساتھ رہا اور ان کی فضیلت اور خوبی کی تعریف کی ۔ سیدنا ابو امامہ رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : عمرو بن عبسہ سلمی رضی اللہ تعالیٰ عنہ نےکہا : میں جب اپنے جاہلیت کے دور میں تھا تو ( یہ بات ) سمجھتا تھا کہ لوگ گمراہ ہیں اور جب وہ بتوں کی عبادت کرتے ہیں تو کسی ( سچی ) چیز ( دین ) پر نہیں ، پھر میں نے مکہ کے ایک آدمی کے بارے میں سنا کہ وہ بہت سی باتوں کی خبر دیتا ہے ، میں اپنی سواری پر بیٹھا اور ان کے پاس آگیا ، اس زمانے میں رسول اللہ صلی اللہ علیہ وسلم چھپے ہوئے تھے ، آپ کی قوم ( کے لوگ ) آپ کے خلاف دلیر ، اور جری تھے ۔ میں ایک لطیف تدبیر اختیار کرکے مکہ میں آپ کی خدمت میں حاضر ہوا اور آپ سے پوچھا آپ کیا ہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" میں نبی ہوں ۔ \" پھر میں نے پوچھا : \" نبی کیا ہوتا ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" مجھے اللہ نے بھیجا ہے ۔ \" میں نے کہا : آپ کو کیا ( پیغام ) دے کر بھیجا ہے؟آپ نے فرمایا : \" اللہ تعالیٰ مجھے صلہ رحمی ، بتوں کو توڑنے ، اللہ تعالیٰ کو ایک قرار دینے ، اور اس کے ساتھ کسی چیز کو شریک نہ ٹھہرانے ( کاپیغام ) دے کر بھیجا ہے ۔ \" میں نے آپ سے پوچھا : آپ کے ساتھ اس ( دین ) پر اور کون ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" ایک آزاد اور ایک غلام ۔ \" ۔ ۔ ۔ کہا : آپ صلی اللہ علیہ وسلم کے ساتھ اس وقت ایمان لانے والوں میں سے ابو بکر اور بلال رضوان اللہ عنھم اجمعین تھے ۔ میں نے کہا : میں بھی آپ کا متبع ہوں ۔ فرمایا : \" تم اپنے آج کل کے حالات میں ایسا کرنے کی استطاعت نہیں رکھتے ۔ کیا تم میرا اور لوگوں کا حال نہیں دیکھتے؟لیکن ( ان حالات میں ) تم اپنے گھر کی طرف لوٹ جاؤ اور جب میرے بارے میں سنو کہ میں غالب آگیا ہوں تو میرے پاس آجانا ۔ \" کہا : تو میں اپنے گھر والوں کے پاس لوٹ گیا ۔ او ( بعد ازاں ) رسول اللہ صلی اللہ علیہ وسلم مدینہ تشریف لے گئے میں اپنے گھر ہی میں تھا ، جب آپ صلی اللہ علیہ وسلم مدینہ تشریف لائے ۔ تو میں بھی خبریں لینے اور لوگوں سے آپ کے حالات پوچھنے میں لگ گیا ۔ حتیٰ کہ میرے پاس اہل یثرب ( مدینہ والوں ) میں سے کچھ لوگ آئے تو میں نے پوچھا : یہ شخص جو مدینہ میں آیا ہے اس نے کیا کچھ کیا ہے؟انھوں نے کہا : لوگ تیزی سے ان ( کے دین ) کی طرف بڑھ رہے ہیں ، آپ کی قوم نے آپ کو قتل کرنا چاہا تھا لیکن وہ ایسا نہ کرسکے ۔ اس پر میں مدینہ آیا اور آپ کی خدمت میں حاضر ہوا اور عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم ! کیا آپ مجھے پہچانتے ہیں؟آپ نے فرمایا : \" ہاں تم وہی ہو ناں جو مجھ سے مکہ میں ملے تھے؟ \" کہا : تو میں نے عرض کی : جی ہاں ، اور پھر پوچھا : اے اللہ کے نبی! مجھے وہ ( سب ) بتایئے جو اللہ نے آپ کو سکھایا ہے اور میں اس سے ناواقف ہوں ، مجھے نماز کے بارے میں بتایئے ۔ آپ نے فرمایا : \" صبح کی نماز پڑھو اور پھر نماز سے رک جاؤ حتیٰ کہ سورج نکل کر بلند ہوجائے کیونکہ وہ جب طلوع ہوتا ہے تو شیطان ( اپنے سینگوں کو آگے کرکے یوں دیکھاتا ہے جیسے وہ اُس ) کے دو سینگوں کےدرمیان طلوع ہوتا ہے اور اس وقت کافر اس ( سورج ) کو سجدہ کرتے ہیں ، اس کے بعد نماز پڑھو کیونکہ نماز کا مشاہدہ ہوتاہے اور اس میں ( فرشتے ) حاضر ہوتے ہیں یہاں تک کہ جب نیزے کا سایہ اس کے ساتھ لگ جائے ( سورج بالکل سر پر آجائے ) تو پھر نماز سے رک جاؤ کیونکہ اس وقت جہنم کو ایندھن سے بھر کو بھڑکایاجاتا ہے ، پھر جب سایہ آئے جائے ( سورج ڈھل جائے ) تو نماز پڑھو کیونکہ نماز کا مشاہدہ کیا جاتا ہے اور اس میں حاضری دی جاتی ہے حتیٰ کہ تم عصر سے فارغ ہوجاؤ ، پھر نماز سے رک جاؤ یہاں تک کہ سورج ( پوری طرح ) غروب ہوجائے کیونکہ وہ شیطان کے دو سینگوں میں غروب ہوتا ہے اور اس وقت کافر اس کے سامنے سجدہ کرتے ہیں ۔ \" کہا : پھر میں نے پوچھا : اے اللہ کے نبی صلی اللہ علیہ وسلم ! تو وضو؟مجھے اس کے بارے میں بھی بتایئے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے جوشخص بھی وضو کے لئے پانی اپنے قریب کرتاہے ۔ پھر کلی کرتاہے اور ناک میں پانی کھینچ کر اسے جھاڑتاہے تو اس سے اس کے چہرے ، منہ ، اور ناک کے نتھنوں کے گناہ جھڑ جاتے ہیں ، پھر جب وہ اللہ کے حکم کےمطابق اپنے چہرے کو دھوتا ہے تو لازماً اس کے چہرے کے گناہ بھی پانی کے ساتھ اس کی داڑھی کے کناروں سے گر جاتے ہیں ، پھر وہ اپنے دونوں ہاتھوں کو کہنیوں ( کے اوپر ) تک دھوتا ہے ۔ تو لازماً اس کے ہاتھوں کے گناہ پانی کے ساتھ اس کے پوروں سے گرجاتے ہیں ، پھر وہ سر کا مسح کرتاہے تو اس کے سر کے گناہ پانی کے ساتھ اس کے بالوں کے اطراف سے زائل ہوجاتے ہیں ، پھر وہ ٹخنوں ( کے اوپر ) تک اپنے دونوں قدم دھوتا ہے ۔ تو اس کے دونوں پاؤں کے گناہ پانی کے ساتھ اس کے پوروں سے گر جاتے ہیں ، پھر اگر وہ کھڑا ہوا نماز پڑھی اور اللہ کے شایان شان اس کی حمد وثنا اور بزرگی بیان کی اور اپنا دل اللہ کے لئے ( ہر قسم کے دوسرے خیالات وتصورات سے ) خالی کرلیا تو وہ اپنے گناہوں سے اس طرح نکلتا ہے جس طرح اس وقت تھا جس دن اس کی ماں نے اسے ( ہر قسم کے گناہوں سے پاک ) جنا تھا ۔ \" سیدنا عمرو بن عبسہ رضی اللہ تعالیٰ عنہ نے یہ حدیث رسول اللہ صلی اللہ علیہ وسلم کے ( ایک اور ) صحابی سیدنا ابو امامہ رضی اللہ تعالیٰ عنہ کو سنائی تو ابو امامہ رضی اللہ تعالیٰ عنہ نے ان سے کہا : اے عمرو بن عبسہ رضی اللہ تعالیٰ عنہ !دیکھ لوتم کیا کہہ رہے ہو ۔ ایک ہی جگہ اس آدمی کو اتنا کچھ عطا کردیا جاتا ہے! اس پر عمرو رضی اللہ تعالیٰ عنہ نے کہا : اے ابو امامہ رضی اللہ تعالیٰ عنہ !میری عمر بڑھ گئی ہے میری ہڈیاں نرم ہوگئیں ہیں اور میری موت کا وقت بھی قریب آچکا ہے اور مجھے کوئی ضرورت نہیں کہ اللہ پر جھوٹ بولوں ۔ اور اس کے رسول صلی اللہ علیہ وسلم پر جھوٹ بولوں ۔ اگر میں نے اس حدیث کو رسول اللہ صلی اللہ علیہ وسلم سے ایک ، دو ، تین ۔ ۔ ۔ حتیٰ کہ انھوں نے سات بار شمار کیا ۔ ۔ ۔ بار نہ سنا ہوتا تو میں اس حدیث کو کبھی بیان نہ کرتا بلکہ میں نے تو اسے آپ صلی اللہ علیہ وسلم سے اس سے بھی زیادہ بار سنا ہے ۔","",{"u2":"ابو عمار شداد بن عبداللہ اور یحییٰ بن ابی کثیر نے ابو امامہ سے روایت کی۔۔۔عکرمہ نے کہا:شداد ابو امامہ اور واثلہ رضی اللہ تعالیٰ عنہ سے مل چکا ہے،وہ شام کے سفر میں حضرت انس رضی اللہ تعالیٰ عنہ کے ساتھ رہااور ان کی فضیلت اور خوبی کی تعریف کی۔حضرت ابو امامہ رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے کہا:عمرو بن عبسہ سلمی رضی اللہ تعالیٰ عنہ نےکہا:میں جب اپنے جاہلیت کے دور میں تھا تو(یہ بات) سمجھتا تھا کہ لوگ گمراہ ہیں اور جب وہ بتوں کی عبادت کرتے ہیں تو کسی(سچی) چیز(دین) پر نہیں،پھر میں نے مکہ کے ایک آدمی کے بارے میں سنا کہ وہ بہت سی باتوں کی خبر دیتا ہے،میں اپنی سواری پر بیٹھا اور ان کے پاس آگیا،اس زمانے میں رسول اللہ صلی اللہ علیہ وسلم چھپے ہوئے تھے،آپ کی قوم (کے لوگ) آپ کے خلاف دلیر،اور جری تھے۔میں ایک لطیف تدبیر اختیار کرکے مکہ میں آپ کی خدمت میں حاضر ہوااور آپ سے پوچھا آپ کیا ہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"میں نبی ہوں۔\"پھر میں نے پوچھا:\"نبی کیا ہوتا ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"مجھے اللہ نے بھیجا ہے۔\"میں نے کہا:آپ کو کیا (پیغام) دے کر بھیجا ہے؟آپ نے فرمایا:\" اللہ تعالیٰ مجھے صلہ رحمی،بتوں کو توڑنے،اللہ تعالیٰ کو ایک قرار دینے،اور اس کے ساتھ کسی چیز کو شریک نہ ٹھہرانے(کاپیغام) دے کر بھیجا ہے۔\"میں نے آپ سے پوچھا: آپ کے ساتھ اس (دین) پر اور کون ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا:\" ایک آزاد اور ایک غلام۔\"۔۔۔کہا:آپ صلی اللہ علیہ وسلم کے ساتھ اس وقت ایمان لانے والوں میں سے ابو بکر اور بلال رضوان اللہ عنھم اجمعین تھے۔میں نے کہا:میں بھی آپ کا متبع ہوں۔فرمایا:\" تم اپنے آج کل کے حالات میں ایسا کرنے کی استطاعت نہیں رکھتے۔کیا تم میرا اور لوگوں کا حال نہیں دیکھتے؟لیکن(ان حالات میں) تم اپنے گھر کی طرف لوٹ جاؤ اور جب میرے بارے میں سنو کہ میں غالب آگیا ہوں تو میرے پاس آجانا۔\"کہا:تو میں اپنے گھر والوں کے پاس لوٹ گیا۔او(بعد ازاں) رسول اللہ صلی اللہ علیہ وسلم مدینہ تشریف لے گئے میں اپنے گھر ہی میں تھا،جب آپ صلی اللہ علیہ وسلم مدینہ تشریف لائے۔ تو میں بھی خبریں لینے اور لوگوں سے آپ کے حالات پوچھنے میں لگ گیا۔حتیٰ کہ میرے پاس اہل یثرب(مدینہ والوں) میں سے کچھ لوگ آئے تو میں نے پوچھا:یہ شخص جو مدینہ میں آیا ہے اس نے کیا کچھ کیا ہے؟انھوں نے کہا:لوگ تیزی سے ان(کے دین) کی طرف بڑھ رہے ہیں،آپ کی قوم نے آپ کو قتل کرنا چاہا تھا لیکن وہ ایسا نہ کرسکے۔اس پر میں مدینہ آیا اور آپ کی خدمت میں حاضر ہوا اور عرض کی:اے اللہ کے رسول صلی اللہ علیہ وسلم! کیا آپ مجھے پہچانتے ہیں؟آپ نے فرمایا:\" ہاں تم وہی ہو ناں جو مجھ سے مکہ میں ملے تھے؟\" کہا:تو میں نے عرض کی:جی ہاں،اور پھر پوچھا:اے اللہ کے نبی! مجھے وہ(سب) بتایئے جو اللہ نے آپ کوسکھایا ہے اور میں اس سے ناواقف ہوں،مجھے نماز کے بارے میں بتایئے۔آپ نے فرمایا:\"صبح کی نماز پڑھو اور پھر نمازسے رک جاؤ حتیٰ کہ سورج نکل کر بلند ہوجائے کیونکہ وہ جب طلوع ہوتا ہے تو شیطان (اپنے سینگوں کو آگے کرکے یوں دیکھاتا ہے جیسے وہ اُس) کے دو سینگوں کےدرمیان طلوع ہوتا ہے اور اس وقت کافر اس (سورج) کو سجدہ کرتے ہیں،اس کے بعد نماز پڑھو کیونکہ نماز کا مشاہدہ ہوتاہے اور اس میں (فرشتے) حاضر ہوتے ہیں یہاں تک کہ جب نیزے کا سایہ اس کے ساتھ لگ جائے(سورج بالکل سر پر آجائے) تو پھر نماز سے رک جاؤ کیونکہ اس وقت جہنم کو ایندھن سے بھر کو بھڑکایاجاتا ہے،پھر جب سایہ آئے جائے(سورج ڈھل جائے) تو نمازپڑھو کیونکہ نماز کا مشاہدہ کیاجاتا ہے اور اس میں حاضری دی جاتی ہے حتیٰ کہ تم عصر سے فارغ ہوجاؤ،پھر نماز سے رک جاؤ یہاں تک کہ سورج(پوری طرح) غروب ہوجائے کیونکہ وہ شیطان کے دو سینگوں میں غروب ہوتا ہے اور اس وقت کافر اس کے سامنے سجدہ کرتے ہیں۔\"کہا:پھر میں نے پوچھا:اے اللہ کے نبی صلی اللہ علیہ وسلم! تو وضو؟مجھے اس کے بارے میں بھی بتایئے۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"تم میں سے جوشخص بھی وضو کے لئے پانی اپنے قریب کرتاہے۔پھر کلی کرتاہے اور ناک میں پانی کھینچ کر اسے جھاڑتاہے تو اس سے اس کے چہرے،منہ،اور ناک کے نتھنوں کے گناہ جھڑ جاتے ہیں،پھر جب وہ اللہ کے حکم کےمطابق اپنے چہرے کو دھوتا ہے تو لازماً اس کے چہرے کےگناہ بھی پانی کے ساتھ اس کی داڑھی کے کناروں سے گر جاتے ہیں،پھر وہ اپنے دونوں ہاتھوں کو کہنیوں(کے اوپر) تک دھوتا ہے۔تو لازماً اس کے ہاتھوں کےگناہ پانی کے ساتھ اس کے پوروں سے گرجاتے ہیں،پھر وہ سر کا مسح کرتاہے تو اس کے سر کے گناہ پانی کے ساتھ اس کے بالوں کے اطراف سے زائل ہوجاتے ہیں،پھر وہ ٹخنوں(کے اوپر)تک اپنے دونوں قدم دھوتا ہے۔تو اس کے دونوں پاؤں کے گناہ پانی کے ساتھ اس کے پوروں سے گر جاتے ہیں،پھر اگر وہ کھڑا ہوانماز پڑھی اور اللہ کے شایان شان اس کی حمد وثنا اور بزرگی بیان کی اور اپنا دل اللہ کے لئے(ہر قسم کے دوسرے خیالات وتصورات سے)خالی کرلیا تو وہ اپنے گناہوں سے اس طرح نکلتا ہے جس طرح اس وقت تھا جس دن اس کی ماں نے اسے(ہر قسم کے گناہوں سے پاک) جنا تھا۔\"حضرت عمرو بن عبسہ رضی اللہ تعالیٰ عنہ نے یہ حدیث رسول اللہ صلی اللہ علیہ وسلم کے(ایک اور) صحابی حضرت ابو امامہ رضی اللہ تعالیٰ عنہ کو سنائی تو ابو امامہ رضی اللہ تعالیٰ عنہ نے ان سے کہا:اے عمرو بن عبسہ رضی اللہ تعالیٰ عنہ!دیکھ لوتم کیا کہہ رہے ہو۔ ایک ہی جگہ اس آدمی کو اتناکچھ عطا کردیا جاتا ہے! اس پر عمرو رضی اللہ تعالیٰ عنہ نے کہا:اے ابو امامہ رضی اللہ تعالیٰ عنہ!میری عمر بڑھ گئی ہے میری ہڈیاں نرم ہوگئیں ہیں اور میری موت کا وقت بھی قریب آچکا ہے اور مجھے کوئی ضرورت نہیں کہ اللہ پر جھوٹ بولوں۔اور اس کے رسول صلی اللہ علیہ وسلم پر جھوٹ بولوں۔ اگر میں نے اس حدیث کو رسول اللہ صلی اللہ علیہ وسلم سے ایک،دو،تین۔۔۔حتیٰ کہ انھوں نے سات بار شمار کیا۔۔۔بار نہ سنا ہوتا تو میں اس حدیث کو کبھی بیان نہ کرتا بلکہ میں نے تو اسے آپ صلی اللہ علیہ وسلم سے اس سے بھی زیادہ بارسنا ہے۔"}],[1873,"وہیب نے کہا : ہم سے عبداللہ بن طاوس نے حدیث بیان کی ، انھوں نے اپنے والد ( طاوس ) سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : سیدنا عمر رضی اللہ تعالیٰ عنہ کو وہم لاحق ہوا ہے ( کہ وہ ہر صورت عصر کے بعد نماز پڑھنے کو قابل سزا سمجھتے ہیں ) رسول اللہ صلی اللہ علیہ وسلم نے تو اس بات سے منع فرمایا ہے کہ سورج کے طلوع یا اس کے غروب کے وقت نماز پڑھنے کا قصد کیا جائے ۔","",{"u2":"وہیب نے کہا:ہم سے عبداللہ بن طاوس نے حدیث بیان کی،انھوں نے اپنے والد (طاوس) سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:حضرت عمر رضی اللہ تعالیٰ عنہ کو وہم لاحق ہوا ہے(کہ وہ ہر صورت عصر کے بعد نماز پڑھنے کو قابل سزا سمجھتے ہیں) رسول اللہ صلی اللہ علیہ وسلم نے تو اس بات سے منع فرمایا ہے کہ سورج کے طلوع یا اس کے غروب کے وقت نماز پڑھنے کا قصد کیا جائے۔"}],[1874,"معمر نے باقی ماندہ سابقہ سند کے ساتھ طاوس کے بیٹے سے ، انھوں نے اپنے والد سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے عصر کے بعد دو رکعت پڑھنی کبھی نہیں چھوڑ ی تھی کہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا نےکہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" نماز کے لئے تم جان بوجھ کر سورج کے طلوع اور اس کے غروب ہونے کا قصد نہ کرو کہ اس وقت نماز پڑھو ۔","",{"u2":"معمر نے باقی ماندہ سابقہ سند کے ساتھ طاوس کے بیٹے سے،انھوں نے اپنے والد سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے عصر کے بعد دو رکعت پڑھنی کبھی نہیں چھوڑ ی تھی کہا:حضرت عائشہ رضی اللہ تعالیٰ عنہا نےکہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"نماز کے لئے تم جان بوجھ کر سورج کے طلوع اور اس کے غروب ہونے کا قصد نہ کرو کہ اس وقت نماز پڑھو۔\""}],[1875,"سیدنا ابن عباس رضی اللہ تعالیٰ عنہ کے آزاد کردہ غلام کریب سے روایت ہے کہ عبداللہ بن عباس رضی اللہ تعالیٰ عنہ ، عبدالرحمان بن ازہر ، مسور بن مخرمہ رضی اللہ تعالیٰ عنہ انھیں نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے پاس بھیجا اور کہا کہ ہم سب کی طرف سے انھیں سلام عرض کرنا اور ان سے عصر کے بعد کی دو رکعت کے بارے میں پوچھنا اور کہنا کہ ہمیں خبر ملی ہے کہ آ پ یہ ( دو رکعتیں ) پڑھتی ہیں ۔ جبکہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے ہم تک یہ خبر پہنچی ہے کہ آپ صلی اللہ علیہ وسلم نے ان سے روکا ہے ۔ ابن عباس رضی اللہ تعالیٰ عنہ نے کہا کہ میں تو سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ کے ساتھ مل کر لوگوں کو ان سے روکا کرتا تھا ۔ کریب نے کہا : میں سیدہ عائشہ رضی اللہ تعالیٰ عنہا کی خدمت میں حاضر ہوا اور ان حضرات نے جو پیغام د ے کر مجھے بھیجا تھا میں نے ان تک پہنچایا ۔ انھوں نے جواب دیا ام سلمہ رضی اللہ تعالیٰ عنہا سے پوچھو ۔ میں نکل کر ان حضرات کے پاس لوٹا اور انھیں ان کے جواب سے آگاہ کیا ۔ ان حضرات نے مجھے وہی پیغام دے کر سیدنا اسلمہ رضی اللہ تعالیٰ عنہا کی طرف بھیج دیا جس طرح سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے پاس بھیجاتھا ، اس پر ام سلمہ رضی اللہ تعالیٰ عنہا نے جواب دیا ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا کہ آپ ان دو رکعتوں سے روکتے تھے ، پھر میں نے آپ صلی اللہ علیہ وسلم کو یہ دو رکعتیں پڑھتے ہوئے دیکھا ، ہاں ، آپ نے جب یہ دو رکعتیں پڑھیں تھیں اس وقت آپ عصر کی نماز پڑھ چکے تھے ، پھر ( عصر پڑھ کر ) آپ ( میرے گھر میں ) داخل ہوئے جبکہ میرے پاس انصار کے قبیلے بنو حرام کے قبیلے کی کچھ عورتیں موجود تھیں ، آ پ نے یہ دو رکعتیں ادا ( کرنی شروع ) کیں تو میں نے آپ کے پاس خادمہ بھیجی اور ( اس سے ) کہا : آپ صلی اللہ علیہ وسلم کی ایک جانب جا کر کھڑی ہوجاؤ اور آپ صلی اللہ علیہ وسلم سے عرض کرو کہ اے اللہ کے رسول صلی اللہ علیہ وسلم !ام سلمہ رضی اللہ تعالیٰ عنہا کہتی ہیں : میں آپ سے سنتی رہی ہوں کہ آپ ( عصر کے بعد ) ان دو رکعتوں سے منع فرماتے تھے اور اب میں آپ کو پڑھتے ہوئے دیکھ رہی ہوں؟اگر آپ صلی اللہ علیہ وسلم ہاتھ سے اشارہ فرمائیں تو پیچھے ہٹ ( کرکھڑی ہو ) جانا ۔ اس لڑکی نے ایسے ہی کیا ، آپ نے ہاتھ سے اشارہ فرمایا ، وہ آپ سے پیچھے ہٹ ( کر کھڑی ہو ) گئی ، جب آپ صلی اللہ علیہ وسلم نے سلام پھیراتو فرمایا : \" اے ابو امیہ ( حذیفہ بن مغیرہ مخزومی ) کی بیٹی!تم نے عصر کے بعد کی دورکعتوں کے بارے میں پوچھا ہے ، تو ( معاملہ یہ ہے کہ ) بنو عبدالقیس کے کچھ افراد اپنی قوم کے اسلام ( لانے کی اطلاع ) کے ساتھ میرے پاس آئے ، اور انھوں نے مجھے ظہر کی بعد کی دورکعتوں سے مشغول کردیا ، یہ وہی دو رکعتیں ہیں ۔","",{"u2":"حضرت ابن عباس رضی اللہ تعالیٰ عنہ کے آزاد کردہ غلام کریب سے روایت ہے کہ عبداللہ بن عباس رضی اللہ تعالیٰ عنہ،عبدالرحمان بن ازہر،مسور بن مخرمہ رضی اللہ تعالیٰ عنہ انھیں نبی اکرم صلی اللہ علیہ وسلم کی زوجہ حضرت عائشہ رضی اللہ تعالیٰ عنہا کے پاس بھیجا اور کہا کہ ہم سب کی طرف سے انھیں سلام عرض کرنا اور ان سے عصر کے بعد کی دو رکعت کے بارے میں پوچھنا اور کہنا کہ ہمیں خبر ملی ہے کہ آ پ یہ(دو رکعتیں) پڑھتی ہیں۔ جبکہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے ہم تک یہ خبر پہنچی ہے کہ آپ صلی اللہ علیہ وسلم نے ان سے روکا ہے۔ابن عباس رضی اللہ تعالیٰ عنہ نے کہا کہ میں تو حضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ کے ساتھ مل کر لوگوں کو ان سے روکا کرتا تھا۔کریب نے کہا:میں حضرت عائشہ رضی اللہ تعالیٰ عنہا کی خدمت میں حاضر ہوا اور ان حضرات نے جو پیغام د ے کر مجھے بھیجا تھا میں نے ان تک پہنچایا۔انھوں نے جواب دیا ام سلمہ رضی اللہ تعالیٰ عنہا سے پوچھو۔میں نکل کر ان حضرات کے پاس لوٹا اور انھیں ان کے جواب سے آگاہ کیا۔ان حضرات نے مجھے وہی پیغام دے کر حضرت اسلمہ رضی اللہ تعالیٰ عنہا کی طرف بھیج دیا جس طرح حضرت عائشہ رضی اللہ تعالیٰ عنہا کے پاس بھیجاتھا،اس پر ام سلمہ رضی اللہ تعالیٰ عنہا نے جواب دیا۔میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا کہ آپ ان دو رکعتوں سے روکتے تھے،پھر میں نے آپ صلی اللہ علیہ وسلم کو یہ دو رکعتیں پڑھتے ہوئے دیکھا،ہاں،آپ نے جب یہ دو رکعتیں پڑھیں تھیں اس وقت آپ عصر کی نماز پڑھ چکے تھے،پھر(عصر پڑھ کر) آپ(میرے گھر میں) داخل ہوئے جبکہ میرے پاس انصار کے قبیلے بنو حرام کے قبیلے کی کچھ عورتیں موجودتھیں،آ پ نے یہ دو رکعتیں ادا (کرنی شروع) کیں تو میں نے آپ کے پاس خادمہ بھیجی اور (اس سے) کہا:آپ صلی اللہ علیہ وسلم کی ایک جانب جا کر کھڑی ہوجاؤ اور آپ صلی اللہ علیہ وسلم سے عرض کرو کہ اے اللہ کے رسول صلی اللہ علیہ وسلم!ام سلمہ رضی اللہ تعالیٰ عنہا کہتی ہیں:میں آپ سے سنتی رہی ہوں کہ آپ(عصر کے بعد) ان دو رکعتوں سے منع فرماتے تھے اور اب میں آپ کو پڑھتے ہوئےدیکھ رہی ہوں؟اگر آپ صلی اللہ علیہ وسلم ہاتھ سے اشارہ فرمائیں تو پیچھے ہٹ(کرکھڑی ہو) جانا۔اس لڑکی نے ایسے ہی کیا،آپ نے ہاتھ سے اشارہ فرمایا،وہ آپ سے پیچھے ہٹ(کر کھڑی ہو)گئی،جب آپ صلی اللہ علیہ وسلم نے سلام پھیراتو فرمایا:\"اے ابو امیہ(حذیفہ بن مغیرہ مخزومی) کی بیٹی!تم نے عصر کے بعد کی دورکعتوں کے بارے میں پوچھا ہے،تو (معاملہ یہ ہے کہ)بنو عبدالقیس کے کچھ افراد اپنی قوم کے اسلام(لانے کی اطلاع) کے ساتھ میرے پاس آئے، اور انھوں نے مجھے ظہر کی بعد کی دورکعتوں سے مشغول کردیا،یہ وہی دو رکعتیں ہیں۔\""}],[1876,"یحییٰ بن ایوب ، قتیبہ ، اور علی بن حجر نے اسماعیل بن جعفر سے حدیث بیان کی ، ابن ایوب نے کہا : ہمیں اسماعیل نے حدیث سنائی ، کہا مجھے محمد بن ابی حرملہ نے خبر دی ، انھوں نےکہا ، مجھے ابو سلمہ نے خبر دی کہ انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے ان دو ر کعتوں کے بارے میں پوچھا جو رسول اللہ صلی اللہ علیہ وسلم عصر کے بعد پڑھتے تھے ۔ انھوں نےکہا : آپ صلی اللہ علیہ وسلم یہ دو رکعتیں ( ظہر کے بعد ) عصر سے پہلے پڑھتے تھے ، پھر ایک دن ان کے پڑھنے سے مشغول ہوگئے یا انھیں بھول گئے تو آپ صلی اللہ علیہ وسلم نے وہ عصر کے بعد پڑھیں ، پھر آپ صلی اللہ علیہ وسلم نے انھیں قائم رکھا کیونکہ جب آپ صلی اللہ علیہ وسلم کوئی نماز ( ایک دفعہ ) پڑھ لیتے تو اسے قائم رکھتے تھے ۔ یحییٰ بن ایوب نے کہا : اسماعیل نے کہا ( اثبتها اسے قائم رکھتے تھے ) سے مراد ہے : آپ اس پر ہمیشہ عمل فرماتے تھے ۔","",{"u2":"یحییٰ بن ایوب،قتیبہ،اور علی بن حجر نے اسماعیل بن جعفر سے حدیث بیان کی،ابن ایوب نے کہا:ہمیں اسماعیل نے حدیث سنائی،کہا مجھے محمد بن ابی حرملہ نے خبر دی،انھوں نےکہا،مجھے ابو سلمہ نے خبر دی کہ انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے ان دو ر کعتوں کے بارے میں پوچھا جو رسول اللہ صلی اللہ علیہ وسلم عصر کے بعد پڑھتے تھے۔انھوں نےکہا:آپ صلی اللہ علیہ وسلم یہ دو رکعتیں (ظہر کے بعد) عصر سے پہلے پڑھتے تھے،پھر ایک دن ان کے پڑھنے سے مشغول ہوگئے یا انھیں بھول گئے تو آپ صلی اللہ علیہ وسلم نے وہ عصر کے بعد پڑھیں،پھر آپ صلی اللہ علیہ وسلم نے انھیں قائم رکھا کیونکہ جب آپ صلی اللہ علیہ وسلم کوئی نماز(ایک دفعہ) پڑھ لیتے تو اسے قائم رکھتے تھے۔\nیحییٰ بن ایوب نے کہا:اسماعیل نے کہا(اثبتہا اسے قائم رکھتے تھے) سے مراد ہے:آپ اس پر ہمیشہ عمل فرماتے تھے۔"}],[1877,"عروہ نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے فرمایا : رسول اللہ صلی اللہ علیہ وسلم نے میرے ہاں عصر کے بعد دو رکعتیں کبھی نہیں چھوڑیں ۔","",{"u2":"عروہ نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم نے میرے ہاں عصر کے بعد دو رکعتیں کبھی نہیں چھوڑیں۔"}],[1878,"عبدالرحمان بن اسود نے اپنے والد اسود سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : دو نمازیں ہیں ، رسول اللہ صلی اللہ علیہ وسلم نے میرے گھر میں انھیں رازداری سے اور اعلانیہ کبھی ترک نہیں کیا : دو رکعتیں فجر سے پہلے اور دو رکعتیں عصر کے بعد ۔","",{"u2":"عبدالرحمان بن اسود نے اپنے والد اسود سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:دو نمازیں ہیں،رسول اللہ صلی اللہ علیہ وسلم نے میرے گھر میں انھیں رازداری سے اور اعلانیہ کبھی ترک نہیں کیا:دو رکعتیں فجر سے پہلے اور دو رکعتیں عصر کے بعد۔"}],[1879,"ابو اسحاق نے اسود اور مسروق سے روایت کی ، ان دونوں نے کہا : ہم سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے بارے میں گواہی دیتے ہیں کہ انھوں نے کہا : کوئی دن جس میں رسول اللہ صلی اللہ علیہ وسلم میرے پاس ہوتے تھے ایسا نہ تھا کہ آپ صلی اللہ علیہ وسلم نے یہ دو رکعتیں نہ پڑھی ہوں ۔ ان کی مراد عصر کے بعد کی دو رکعتوں سے تھی ۔","",{"u2":"ابو اسحاق نے اسود اور مسروق سے روایت کی،ان دونوں نے کہا:ہم حضرت عائشہ رضی اللہ تعالیٰ عنہا کے بارے میں گواہی دیتے ہیں کہ انھوں نے کہا:کوئی دن جس میں رسول اللہ صلی اللہ علیہ وسلم میرے پاس ہوتے تھے ایسا نہ تھا کہ آپ صلی اللہ علیہ وسلم نے یہ دو رکعتیں نہ پڑھی ہوں۔ان کی مراد عصر کے بعد کی دو رکعتوں سے تھی۔"}],[1880,"مختار بن فلفل سے روایت ہے ، انھوں نے کہا : میں نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے عصر کے بعد نفل نماز پڑھنے کے بارے میں پوچھا تو انھوں نے کہا : سیدنا عمر رضی اللہ تعالیٰ عنہ عصر کے بعد نماز پڑھنے پر ہاتھوں پر مارتے تھے اور نبی اکرم صلی اللہ علیہ وسلم کے دور میں ہم سورج کے غروب ہوجانے کے بعد نماز مغرب سے پہلے دو رکعتیں پڑھتے تھے ۔ تو میں نے ان سے پوچھا : کیا رسول اللہ صلی اللہ علیہ وسلم نے یہ دو رکعتیں پڑھیں؟انھوں نے کہا : آپ ہمیں پڑھتا دیکھتے تھے آپ نے نہ ہمیں حکم دیا اور نہ روکا ۔","",{"u2":"مختار بن فلفل سے روایت ہے،انھوں نے کہا: میں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے عصر کے بعد نفل نماز پڑھنے کے بارے میں پوچھا تو انھوں نے کہا:حضرت عمر رضی اللہ تعالیٰ عنہ عصر کے بعد نماز پڑھنے پر ہاتھوں پر مارتے تھے اور نبی اکرم صلی اللہ علیہ وسلم کےدور میں ہم سورج کے غروب ہوجانے کے بعد نماز مغرب سے پہلے دو رکعتیں پڑھتے تھے۔تو میں نے ان سے پوچھا:کیا رسول اللہ صلی اللہ علیہ وسلم نے یہ دو رکعتیں پڑھیں؟انھوں نے کہا:آپ ہمیں پڑھتا دیکھتے تھے آپ نے نہ ہمیں حکم دیا اور نہ روکا۔"}],[1881,"عبدالعزیز بن صہیب نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : ہم مدینے میں ہوتے تھے ، جب موذن مغرب کی اذان دیتا و لوگ ستونوں کی طرح لپکتے تھے اور وہ دو رکعتیں پڑھتے تھے حتیٰ کہ ایک مسافر مسجد میں آتا تو ان رکعتوں کو پڑھنے والوں کی کثرت دیکھ کر یہ سمجھتا کہ مغرب کی نماز ہوچکی ہے ۔","",{"u2":"عبدالعزیز بن صہیب نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:ہم مدینے میں ہوتے تھے،جب موذن مغرب کی اذان دیتا و لوگ ستونوں کی طرح لپکتے تھے اور وہ دو رکعتیں پڑھتے تھے حتیٰ کہ ایک مسافر مسجد میں آتا تو ان رکعتوں کو پڑھنے والوں کی کثرت دیکھ کر یہ سمجھتا کہ مغرب کی نماز ہوچکی ہے۔"}],[1882,"کہمس نےکہا : ہم سے عبداللہ بن بریدہ نے سیدنا عبداللہ بن مغفل مزنی رضی اللہ تعالیٰ عنہ سے حدیث بیان کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \" ہر دو اذانوں ( اذان اور تکبیر ) کے درمیان نماز ہے ۔ \" آپ صلی اللہ علیہ وسلم نے تین دفعہ فرمایا ( اور ) تیسری دفعہ فرمایا : \" اس کے لئے جو چاہے ۔","",{"u2":"کہمس نےکہا:ہم سے عبداللہ بن بریدہ نے حضرت عبداللہ بن مغفل مزنی رضی اللہ تعالیٰ عنہ سے حدیث بیان کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\"ہر دو اذانوں (اذان اور تکبیر) کے درمیان نماز ہے۔\"آپ صلی اللہ علیہ وسلم نے تین دفعہ فرمایا(اور) تیسری دفعہ فرمایا:\"اس کے لئے جو چاہے۔\""}],[1883,"جریری نے عبداللہ بن بریرہ سے ، انھوں نے سیدنا عبداللہ بن مغفل رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی کی مثل روایت کی ، مگرانھوں نے کہا کہ آپ صلی اللہ علیہ وسلم نے چوتھی مرتبہ فرمایا؛ \" اس کے لئے جو چاہے ۔","",{"u2":"جریری نے عبداللہ بن بریرہ سے،انھوں نے حضرت عبداللہ بن مغفل رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی کی مثل روایت کی،مگرانھوں نے کہا کہ آپ صلی اللہ علیہ وسلم نے چوتھی مرتبہ فرمایا؛\"اس کے لئے جو چاہے۔\""}],[1884,"معمر نے زہری سے ، انھوں نے سالم سے اور انھوں نےسیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے نماز خوف پڑھائی ، دو گروہوں میں سے ایک کو ایک رکعت پڑھائی اور دوسرا گروہ دشمن کے سامنے کھڑا ہواتھا ، پھر یہ ( آپ کے ساتھ نماز پڑھنے والے ) پلٹ گئے اور اپنے ساتھیوں کی جگہ دشمن کی طرف رخ کرکے جاکھڑے ہوئے اور وہ لوگ آگئے ۔ پھر نبی اکرم صلی اللہ علیہ وسلم نے انھیں بھی ایک رکعت پڑھائی اور اس کے بعد نبی اکرم صلی اللہ علیہ وسلم نے سلام پھیر دیا پھر ( آپ کے بعد ) انہوں نے بھی اپنی رکعت مکمل کرلی اور انھوں نے بھی دوسری رکعت مکمل کرلی ۔","",{"u2":"معمر نے زہری سے،انھوں نے سالم سے اور انھوں نےحضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے نماز خوف پڑھائی،دو گروہوں میں سے ایک کو ایک رکعت پڑھائی اور دوسرا گروہ دشمن کے سامنے کھڑا ہواتھا،پھر یہ (آپ کے ساتھ نماز پڑھنے والے) پلٹ گئے اور اپنے ساتھیوں کی جگہ دشمن کی طرف رخ کرکے جاکھڑے ہوئے اور وہ لوگ آگئے۔پھر نبی اکرم صلی اللہ علیہ وسلم نے انھیں بھی ایک رکعت پڑھائی اور اس کے بعد نبی اکرم صلی اللہ علیہ وسلم نے سلام پھیر دیا پھر (آپ کے بعد) انہوں نے بھی اپنی رکعت مکمل کرلی اور انھوں نے بھی دوسری رکعت مکمل کرلی۔"}],[1885,"فلیح نے زہری سے ، انھوں نے سالم بن عبداللہ بن عمر سے اور انھوں نے ا پنے والد سے روایت کی کہ وہ رسول اللہ صلی اللہ علیہ وسلم سے صلاۃ الخوف ( کا طریقہ ) بیان کرتے اور فرماتے : میں نے آپ صلی اللہ علیہ وسلم کے ساتھ یہ نماز پڑھی ۔ ۔ ۔ ( آگے ) اسی کے ہم معنی حدیث ہے ۔","",{"u2":"فلیح نے زہری سے،انھوں نے سالم بن عبداللہ بن عمر سے اور انھوں نے ا پنے والد سے روایت کی کہ وہ رسول اللہ صلی اللہ علیہ وسلم سے صلاۃ الخوف(کاطریقہ) بیان کرتے اور فرماتے:میں نے آپ صلی اللہ علیہ وسلم کے ساتھ یہ نماز پڑھی۔۔۔(آگے) اسی کے ہم معنی حدیث ہے۔"}],[1886,"نافع نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ا پنے جنگ کے ایام میں سے ایک دن نماز خوف پڑھائی ، ایک گروہ آپ صلی اللہ علیہ وسلم کے ساتھ نماز کے لئے کھڑہوگیا ۔ اور دوسرا دشمن کے بالمقابل ۔ آپ صلی اللہ علیہ وسلم نے ساتھ کھڑے ہونے والوں کو ایک رکعت پڑھا دی ، پھر یہ لوگ ( دشمن کے مقابلے میں ) چلے گئے اور دوسرے آگئے ، آپ صلی اللہ علیہ وسلم نے انھیں بھی ایک رکعت پڑھا دی ، پھر ان دونوں گروہوں نے ( یکے بعد دیگرے ) ایک ایک رکعت اداکرلی ۔ ( نافع ) نے کہا : ابن عمر رضی اللہ تعالیٰ عنہ نے کہا : اگر خوف اس سے زیادہ ہو ( اور صف بندی ممکن نہ ہو ) تو سواری پر یا کھڑے کھڑے اشاارہ کرو اور نماز پڑھ لو ۔","",{"u2":"نافع نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے ا پنے جنگ کے ایام میں سے ایک دن نماز خوف پڑھائی،ایک گروہ آپ صلی اللہ علیہ وسلم کے ساتھ نماز کے لئے کھڑہوگیا۔اور دوسرا دشمن کے بالمقابل۔آپ صلی اللہ علیہ وسلم نے ساتھ کھڑے ہونے والوں کو ایک رکعت پڑھا دی،پھر یہ لوگ(دشمن کے مقابلےمیں) چلے گئے اور دوسرے آگئے،آپ صلی اللہ علیہ وسلم نے انھیں بھی ایک رکعت پڑھا دی،پھر ان دونوں گروہوں نے(یکے بعد دیگرے) ایک ایک رکعت اداکرلی۔(نافع) نے کہا:ابن عمر رضی اللہ تعالیٰ عنہ نے کہا:اگر خوف اس سے زیادہ ہو(اور صف بندی ممکن نہ ہو) تو سواری پر یا کھڑے کھڑے اشاارہ کرو اور نماز پڑھ لو۔"}],[1887,"عطاء نے سیدنا جابر بن عبداللہ انصاری رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز خوف میں شریک ہوا ، آپ صلی اللہ علیہ وسلم نے ہماری دو صفیں بنائیں ، ایک صف رسول اللہ صلی اللہ علیہ وسلم کے پیچھے تھی ( اور دوسری ان کے پیچھے ) اور دشمن ہمارے اور قبلے کے درمیان تھا ، نبی اکرم صلی اللہ علیہ وسلم نے تکبیر ( تحریمہ ) کہی اور ہم سب نے بھی تکبیر کہی ، پھر آپ صلی اللہ علیہ وسلم نے رکوع کیا اور ہم سب نے رکوع کیا ، پھر آپ صلی اللہ علیہ وسلم نے رکوع سے اپنا سر اٹھایا اور ہم سب نے سراٹھایا ، پھر آپ صلی اللہ علیہ وسلم سجدے کے لئے جھک گئے اور آپ صلی اللہ علیہ وسلم سے متصل صف نے بھی سجدہ کیا اور پچھلی صف دشمن کے مد مقابل کھڑی رہی ، جب آپ صلی اللہ علیہ وسلم نے دو سجدے کے کرلیے ۔ اور آپ صلی اللہ علیہ وسلم سے متصل صف ( سجدے کرکے آپ صلی اللہ علیہ وسلم کے ساتھ ) کھڑی ہوگئی تو پچھلی صف سجدے کے لئے نیچے ہوئی اور پھر کھڑی ہوگئی ، اس کے بعد پچھلی صف آگے آگئی اور اگلی صف پیچھے چلی گئی ، پھر جب آپ صلی اللہ علیہ وسلم نے رکوع کیا تو ہم سب نے رکوع کیا ۔ پھر آپ نے رکوع سے اپنا سر اٹھایا اور ہم سب نے بھی سراٹھایا ، پھر آپ صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم سے متصل صف جو پہلی رکعت میں پیچھے تھی ، سجدے کے لئے نیچے چلی گئی اور پچھلی صف دشمن کے مقابلے میں کھڑی رہی ، جب نبی اکرم صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم سے متصل صف نے سجدہ کرلیا تو پچھلی صف سجدے کے لئے جھکی ۔ انھوں نے سجدے کیے ۔ پھر نبی اکرم صلی اللہ علیہ وسلم نے سلام پھیرا اور ہم سب نے بھی سلام پھیردیا ۔ سیدنا جابر رضی اللہ تعالیٰ عنہ نے بتایا : جس طرح تمہارےمحافظ ( آجکل ) اپنے امیروں کی حفاظت کے لئے کرتے ہیں ۔","",{"u2":"عطاء نے حضرت جابر بن عبداللہ انصاری رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز خوف میں شریک ہوا،آپ صلی اللہ علیہ وسلم نے ہماری دو صفیں بنائیں،ایک صف رسول اللہ صلی اللہ علیہ وسلم کے پیچھے تھی(اوردوسری ان کے پیچھے)اور دشمن ہمارے اور قبلے کے درمیان تھا،نبی اکرم صلی اللہ علیہ وسلم نے تکبیر(تحریمہ) کہی اور ہم سب نے بھی تکبیر کہی،پھر آپ صلی اللہ علیہ وسلم نے رکوع کیا اور ہم سب نے رکوع کیا،پھر آپ صلی اللہ علیہ وسلم نے رکوع سے اپنا سر اٹھایا اور ہم سب نے سراٹھایا،پھر آپ صلی اللہ علیہ وسلم سجدے کے لئے جھک گئے اور آپ صلی اللہ علیہ وسلم سے متصل صف نے بھی سجدہ کیا اور پچھلی صف دشمن کے مد مقابل کھڑی رہی،جب آپ صلی اللہ علیہ وسلم نے دو سجدے کے کرلیے۔اور آپ صلی اللہ علیہ وسلم سے متصل صف(سجدے کرکے آپ صلی اللہ علیہ وسلم کے ساتھ) کھڑی ہوگئی تو پچھلی صف سجدے کے لئے نیچے ہوئی اور پھر کھڑی ہوگئی،اس کے بعد پچھلی صف آگے آگئی اور اگلی صف پیچھے چلی گئی،پھر جب آپ صلی اللہ علیہ وسلم نے رکوع کیا تو ہم سب نے رکوع کیا۔پھر آپ نے رکوع سے اپنا سر اٹھایا اور ہم سب نے بھی سراٹھایا،پھر آپ صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم سے متصل صف جو پہلی رکعت میں پیچھے تھی،سجدے کے لئے نیچے چلی گئی اور پچھلی صف دشمن کے مقابلے میں کھڑی رہی،جب نبی اکرم صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم سے متصل صف نے سجدہ کرلیا تو پچھلی صف سجدے کے لئے جھکی۔انھوں نے سجدے کیے۔پھر نبی اکرم صلی اللہ علیہ وسلم نے سلام پھیرا اور ہم سب نے بھی سلام پھیردیا۔حضرت جابر رضی اللہ تعالیٰ عنہ نے بتایا:جس طرح تمہارےمحافظ (آجکل) اپنے امیروں کی حفاظت کے لئے کرتے ہیں۔"}],[1888,"ابو زبیر نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا؛ہم نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں جہینہ قبیلے کے لوگوں سے جنگ لڑی ، انھوں نے ہمارے ساتھ بڑی شدیدجنگ کی جب ہم نے ظہر کی نماز پڑھی تو مشرکوں نے کہا : اگر ہم ان پر یکبارگی حملہ کریں تو ان کو کاٹ کررکھ دیں ۔ جبرئیل علیہ السلام نے رسول اللہ صلی اللہ علیہ وسلم کو اس بات سے آگاہ کردیا اور رسول اللہ صلی اللہ علیہ وسلم نے ہمیں بتایا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : ان لوگوں نے کہا ہے کہ ابھی ان کی ایک ایسی نماز کا وقت آنےوالاہے جو ان کو ان کی اولاد سے بھی زیادہ پیاری ہے ۔ جب عصر کا وقت آیا ، آپ صلی اللہ علیہ وسلم نے ہماری دو صفیں بنائیں جبکہ مشرک ہمارے اور ہمارے قبیلے کے درمیان تھے ۔ کہا : تو رسول اللہ صلی اللہ علیہ وسلم نے تکبیر تحریمہ کہی اور ہم نے بھی تکبیر کہی ، آپ صلی اللہ علیہ وسلم نے رکوع کیا اور ہم نے بھی رکوع کیا ، پھرآپ صلی اللہ علیہ وسلم نے سجدہ کیا اورآپ صلی اللہ علیہ وسلم کے ساتھ پہلی صف نے بھی سجدہ کیا ۔ جب یہ حضرات کھڑے ہوگئے تو دوسر ی صف والوں نے سجدے کیے ، پھر پہلی صف پیچھے چلی گئی اور دوسری آگے بڑھ گئی اور پہلی صف کی جگہ کھڑی ہوگئی ۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے تکبیر کہی اور ہم نے بھی تکبیر کہی اور آپ صلی اللہ علیہ وسلم نے رکوع کیا اور ہم نے بھی رکوع کیا ۔ پھر آپ صلی اللہ علیہ وسلم نے سجدہ کیا اور آپ صلی اللہ علیہ وسلم کے ساتھ ( موجودہ ) پہلی صف نے سجدہ کیا اور دوسری کھڑی رہی ۔ پھر جب دوسری صف نے سجدے کرلیے اور اس کے بعد سب بیٹھ گئے تو آپ صلی اللہ علیہ وسلم نے سب کے ساتھ سلام پھیرا ۔ ابو زبیر نے کہا : پھر سیدنا جابر رضی اللہ تعالیٰ عنہ نے خصوصی طور پر فرمایا : جس طرح تمہارے یہ امیر نماز پڑھتے ہیں ۔","",{"u2":"ابو زبیر نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا؛ہم نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں جہینہ قبیلے کے لوگوں سے جنگ لڑی،انھوں نے ہمارے ساتھ بڑی شدیدجنگ کی جب ہم نے ظہر کی نماز پڑھی تو مشرکوں نے کہا:اگر ہم ان پر یکبارگی حملہ کریں تو ان کو کاٹ کررکھ دیں۔جبرئیل علیہ السلام نے رسول اللہ صلی اللہ علیہ وسلم کو اس بات سے آگاہ کردیا اوررسول اللہ صلی اللہ علیہ وسلم نے ہمیں بتایا۔آپ صلی اللہ علیہ وسلم نے فرمایا:ان لوگوں نے کہا ہے کہ ابھی ان کی ایک ایسی نماز کا وقت آنےوالاہے جو ان کو ان کی اولاد سے بھی زیادہ پیاری ہے۔جب عصرکا وقت آیا،آپ صلی اللہ علیہ وسلم نے ہماری دو صفیں بنائیں جبکہ مشرک ہمارے اور ہمارے قبیلے کے درمیان تھے۔کہا:تو رسول اللہ صلی اللہ علیہ وسلم نے تکبیر تحریمہ کہی اور ہم نے بھی تکبیر کہی،آپ صلی اللہ علیہ وسلم نے رکوع کیا اور ہم نے بھی رکوع کیا،پھرآپ صلی اللہ علیہ وسلم نے سجدہ کیا اورآپ صلی اللہ علیہ وسلم کے ساتھ پہلی صف نے بھی سجدہ کیا۔جب یہ حضرات کھڑے ہوگئے تو دوسر ی صف والوں نے سجدے کیے،پھر پہلی صف پیچھے چلی گئی اور دوسری آگے بڑھ گئی اور پہلی صف کی جگہ کھڑی ہوگئی۔پھر رسول اللہ صلی اللہ علیہ وسلم نے تکبیر کہی اور ہم نے بھی تکبیرکہی اور آپ صلی اللہ علیہ وسلم نے رکوع کیا اور ہم نے بھی رکوع کیا۔پھر آپ صلی اللہ علیہ وسلم نے سجدہ کیا اور آپ صلی اللہ علیہ وسلم کے ساتھ(موجودہ) پہلی صف نے سجدہ کیا اور دوسری کھڑی رہی۔پھر جب دوسری صف نے سجدے کرلیے اور اس کے بعد سب بیٹھ گئے تو آپ صلی اللہ علیہ وسلم نے سب کے ساتھ سلام پھیرا۔\nابو زبیر نے کہا:پھر حضرت جابر رضی اللہ تعالیٰ عنہ نے خصوصی طور پر فرمایا: جس طرح تمہارے یہ امیر نماز پڑھتے ہیں۔"}],[1889,"عبدالرحمان بن قاسم نے اپنے والد سے ، انھوں نے صالح بن خوات بن جبیر سے اور انھوں نے سیدنا سہل بن ابی حثمہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے ساتھیوں کو نماز خوف پڑھائی اور انھیں اپنے پیچھے دو صفوں میں کھڑا کیا اور اپنے ساتھ ( کی صف ) والوں کو ایک رکعت پڑھائی ۔ پھر آپ کھڑے ہوگئے اور کھڑے ہی رہے یہاں تک کہ ان سے پیچھے والوں نے ایک رکعت پڑھ لی ، پھر یہ آگے آگے اور جو ان سے آگے تھے پیچھے چلے گئے ۔ پھر آپ صلی اللہ علیہ وسلم نے انھیں ایک رکعت پڑھائی ۔ پھر آپ بیٹھ گئے حتیٰ کہ جو پیچھے چلے گئے تھے انھوں نے ( بھی ایک اور ) رکعت پڑھ لی ، پھر آپ صلی اللہ علیہ وسلم نے سلام پھیرا ۔","",{"u2":"عبدالرحمان بن قاسم نے اپنے والد سے،انھوں نے صالح بن خوات بن جبیرسے اور انھوں نے حضرت سہل بن ابی حثمہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے ساتھیوں کو نماز خوف پڑھائی اور انھیں اپنے پیچھے دو صفوں میں کھڑا کیا اور اپنے ساتھ(کی صف) والوں کوایک رکعت پڑھائی۔پھر آپ کھڑے ہوگئے اور کھڑے ہی رہے یہاں تک کہ ان سے پیچھے والوں نے ایک رکعت پڑھ لی،پھر یہ آگے آگے اور جو ان سے آگے تھے پیچھے چلے گئے۔ پھر آپ صلی اللہ علیہ وسلم نے انھیں ایک رکعت پڑھائی۔پھر آپ بیٹھ گئے حتیٰ کہ جو پیچھے چلے گئے تھے انھوں نے(بھی ایک اور)رکعت پڑھ لی،پھر آپ صلی اللہ علیہ وسلم نے سلام پھیرا۔"}],[1890,"یزید بن رومان نے صالح بن خوات سے اور انھوں نے اس شخص سے نقل کیا جس نے غزوہ ذات الرقاع میں رسول اللہ صلی اللہ علیہ وسلم کی معیت میں نماز خوف پڑھی تھی ۔ کہ ایک گروہ نے آپ صلی اللہ علیہ وسلم کے ساتھ صف بنائی اور دوسرا گروہ دشمن کے رو برو تھا ، آپ صلی اللہ علیہ وسلم نے اپنے ساتھ والوں کو ایک رکعت پڑھائی ، پھر آپ صلی اللہ علیہ وسلم کھڑے رہے اور انھوں نے اپنے طور پر ( دوسری رکعت پڑھ کر ) نماز مکمل کرلی اور ( سلام پھیر کر ) چلے گئے اور دشمن کے سامنے صف بند ہوگئے اور دوسرا گروہ آگیا ، آپ صلی اللہ علیہ وسلم نے جو رکعت رہتی تھی ۔ ان کو پڑھا دی پھر بیٹھے رہے اور ان لوگوں نے اپنے طور پر ( رکعت پڑھ کر ) نماز مکمل کرلی تو آپ صلی اللہ علیہ وسلم نے ان کے ساتھ سلام پھیرا ۔","",{"u2":"یزید بن رومان نے صالح بن خوات سےاور انھوں نے اس شخص سے نقل کیا جس نے غزوہ ذات الرقاع میں رسول اللہ صلی اللہ علیہ وسلم کی معیت میں نمازخوف پڑھی تھی۔ کہ ایک گروہ نے آپ صلی اللہ علیہ وسلم کے ساتھ صف بنائی اور دوسرا گروہ دشمن کے رو برو تھا،آپ صلی اللہ علیہ وسلم نے اپنے ساتھ والوں کو ایک رکعت پڑھائی،پھر آپ صلی اللہ علیہ وسلم کھڑے رہے اور انھوں نے اپنے طور پر(دوسری رکعت پڑھ کر) نماز مکمل کرلی اور(سلام پھیر کر) چلے گئے اور دشمن کے سامنے صف بند ہوگئے اور دوسرا گروہ آگیا،آپ صلی اللہ علیہ وسلم نے جو رکعت رہتی تھی۔ ان کو پڑھا دی پھر بیٹھے رہے اور ان لوگوں نے اپنے طور پر(رکعت پڑھ کر) نماز مکمل کرلی تو آپ صلی اللہ علیہ وسلم نے ان کے ساتھ سلام پھیرا۔"}],[1891,"۔ ابان بن یزید نے کہا : ہم سے یحییٰ ابن کثیر نے ابو سلمہ ( بن عبدالرحمان ) سے حدیث بیان کی اور انھوں نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ( جہاد پر ) آئے ۔ حتیٰ کہ جب ہم ذات الرقاع ( نامی پہاڑ ) تک پہنچے ۔ کہا : ہماری عادت تھی کہ جب ہم کسی گھنے سائے والے درخت تک پہنچے تو اسے رسول اللہ صلی اللہ علیہ وسلم کے لئے چھوڑ دیتے ، کہا : ایک مشرک آیا جبکہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار درخت پر لٹکی ہوئی تھی ، اس نے رسول اللہ صلی اللہ علیہ وسلم کی تلوار پکڑ لی ، اسے میان سے نکالا اور رسول اللہ صلی اللہ علیہ وسلم سے کہنے لگا : کیا آپ مجھ سے ڈ رتے ہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" نہیں ۔ \" اس نے کہا : تو پھر آپ کو مجھ سے کون بچائے گا؟آپ صلی اللہ علیہ وسلم نےفرمایا : \" اللہ تعالیٰ مجھے تم سے محفوظ فرمائے گا ۔ \" رسول اللہ صلی اللہ علیہ وسلم کے ساتھیوں نے اسے دھمکایا تو اس نے تلوار میان میں ڈال لی اور اسے لٹکایا ۔ اس کے بعد نماز کے لئے اذان کہی گئی ، آپ صلی اللہ علیہ وسلم نے ایک گروہ کو دو رکعت نماز پڑھائی ، پھر وہ گروہ پیچھے چلا گیااس کے بعد آپ صلی اللہ علیہ وسلم نے دوسرے گروہ کو دو رکعتیں پڑھائیں ۔ کہا اس طرح رسول اللہ صلی اللہ علیہ وسلم کی چار رکعتیں ہوئیں اور لوگوں کی دو دو رکعتیں ۔","",{"u2":"۔ ابان بن یزید نے کہا:ہم سے یحییٰ ابن کثیر نے ابو سلمہ(بن عبدالرحمان) سے حدیث بیان کی اور انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ(جہاد پر) آئے۔حتیٰ کہ جب ہم ذات الرقاع(نامی پہاڑ) تک پہنچے۔کہا:ہماری عادت تھی کہ جب ہم کسی گھنے سائے والے درخت تک پہنچے تو اسے رسول اللہ صلی اللہ علیہ وسلم کے لئے چھوڑ دیتے،کہا:ایک مشرک آیا جبکہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار درخت پر لٹکی ہوئی تھی،اس نے رسول اللہ صلی اللہ علیہ وسلم کی تلوارپکڑ لی،اسے میان سے نکالا اور رسول اللہ صلی اللہ علیہ وسلم سے کہنے لگا:کیا آپ مجھ سے ڈ رتے ہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"نہیں۔\"اس نے کہا: تو پھر آپ کومجھ سے کون بچائے گا؟آپ صلی اللہ علیہ وسلم نےفرمایا:\" اللہ تعالیٰ مجھے تم سےمحفوظ فرمائے گا۔\"رسول اللہ صلی اللہ علیہ وسلم کے ساتھیوں نے اسے دھمکایا تو اس نے تلوار میان میں ڈال لی اور اسے لٹکایا۔اس کے بعد نماز کے لئے اذان کہی گئی،آپ صلی اللہ علیہ وسلم نے ایک گروہ کو دو رکعت نماز پڑھائی،پھر وہ گروہ پیچھے چلا گیااس کے بعد آپ صلی اللہ علیہ وسلم نے دوسرے گروہ کو دو رکعتیں پڑھائیں۔کہا اس طرح رسول اللہ صلی اللہ علیہ وسلم کی چار رکعتیں ہوئیں اور لوگوں کی دو دو رکعتیں۔"}],[1892,"معاویہ بن سلام نے کہا : مجھے یحییٰ ( بن ا بی کثیر ) نے خبردی ، انھوں نے کہا : مجھے ابو سلمہ بن عبدالرحمان نے خبر دی کہ انھیں جابر رضی اللہ تعالیٰ عنہ نے بتایا کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز خوف پڑھی ، رسول اللہ صلی اللہ علیہ وسلم نے ایک گروہ کودو رکعتیں پڑھائیں ، پھر دوسرے گروہ کو دو ر کعتیں پڑھائیں ، اس طرح رسول اللہ صلی اللہ علیہ وسلم نے چار ر کعتیں پڑھیں اور ہر گروہ کو دو دو رکعتیں پڑھائیں ۔","",{"u2":"معاویہ بن سلام نے کہا:مجھے یحییٰ(بن ا بی کثیر) نے خبردی،انھوں نے کہا:مجھے ابو سلمہ بن عبدالرحمان نے خبر دی کہ انھیں جابر رضی اللہ تعالیٰ عنہ نے بتایا کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز خوف پڑھی،رسول اللہ صلی اللہ علیہ وسلم نے ایک گروہ کودو رکعتیں پڑھائیں،پھر دوسرے گروہ کو دو ر کعتیں پڑھائیں،اس طرح رسول اللہ صلی اللہ علیہ وسلم نے چار ر کعتیں پڑھیں اور ہر گروہ کو دو دو رکعتیں پڑھائیں۔"}],[1893,"نافع نے سیدنا عبداللہ ( بن عمر رضی اللہ تعالیٰ عنہ ) سے روایت کی ، انھوں نےکہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئےسنا : \" جب تم میں سے کوئی شخص جمعے کےلئے آنے کاارادہ کرے تو وہ غسل کرے ۔","",{"u2":"نافع نے حضرت عبداللہ (بن عمر رضی اللہ تعالیٰ عنہ) سے روایت کی،انھوں نےکہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئےسنا:\" جب تم میں سے کوئی شخص جمعے کےلئے آنے کاارادہ کرے تو وہ غسل کرے۔\""}],[1894,"لیث نے ابن شہاب سے ، انھوں نے عبداللہ بن عبداللہ بن عمیر سے ، انھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے منبر پر کھڑے ہوئے فرمایا : \" تم میں سے جو جمعے کے لئے آئے غسل کرے ۔","",{"u2":"لیث نے ابن شہاب سے،انھوں نے عبداللہ بن عبداللہ بن عمیر سے،انھوں نے حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے منبر پر کھڑے ہوئے فرمایا:\"تم میں سے جو جمعے کے لئے آئے غسل کرے۔\""}],[1895,"ابن جریج نے کہا : ابن شہاب نے عبداللہ بن عمر رضی اللہ تعالیٰ عنہ کے دونوں بیٹوں سالم اور عبداللہ سے خبر دی ، انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اس ( سابقہ حدیث ) کے مانندروایت کی ۔","",{"u2":"ابن جریج نے کہا:ابن شہاب نے عبداللہ بن عمر رضی اللہ تعالیٰ عنہ کے دونوں بیٹوں سالم اورعبداللہ سے خبر دی، انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اس(سابقہ حدیث) کے مانندروایت کی۔"}],[1896,"یونس نے ابن شہاب سے ، انھوں نے سالم بن عبداللہ سے اورانھوں نے اپنے والد سے روایت کی ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئےسنا ۔ ۔ ۔ ( آگے ) اسی ( سابقہ حدیث ) کے مانند ہے ۔","",{"u2":"یونس نے ابن شہاب سے،انھوں نے سالم بن عبداللہ سے اورانھوں نے اپنے والد سے روایت کی،انھوں نے کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئےسنا۔۔۔(آگے)اسی(سابقہ حدیث) کے مانند ہے۔"}],[1897,"سیدنا عبداللہ رضی اللہ تعالیٰ عنہ سے روایت ہے کہ سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ جمعے کے دن لوگوں کو خطاب فرمارہےتھے ( کہ اسی اثناء میں ) رسول اللہ صلی اللہ علیہ وسلم کے صحابہ رضوان اللہ عنھم اجمعین میں سے ایک شخص داخل ہوا ، سیدنا عمر رضی اللہ تعالیٰ عنہ نے انھیں آوازدی : ( آنے کی ) یہ کون سی گھڑی ہے؟انھوں نے کہا : میں آج مصروف ہوگیا ، گھر لوٹتے ہیں میں نے اذان سنی اور صرف وضو کیا ( اور حاضر ہوگیا ہوں ) سیدنا عمر رضی اللہ تعالیٰ عنہ نے کہا : اور وہ بھی ( صرف ) وضو؟حالانکہ آپ کو معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم غسل کرنے کاحکم دیتے تھے ۔","",{"u2":"حضرت عبداللہ رضی اللہ تعالیٰ عنہ سے روایت ہے کہ حضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ جمعے کے دن لوگوں کوخطاب فرمارہےتھے(کہ اسی اثناء میں) رسول اللہ صلی اللہ علیہ وسلم کے صحابہ رضوان اللہ عنھم اجمعین میں سے ایک شخص داخل ہوا،حضرت عمر رضی اللہ تعالیٰ عنہ نے انھیں آوازدی: (آنےکی) یہ کون سی گھڑی ہے؟انھوں نے کہا: میں آج مصروف ہوگیا،گھر لوٹتے ہیں میں نے اذان سنی اور صرف وضو کیا(اورحاضر ہوگیاہوں) حضرت عمر رضی اللہ تعالیٰ عنہ نے کہا: اور وہ بھی (صرف) وضو؟حالانکہ آپ کو معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم غسل کرنے کاحکم دیتے تھے۔"}],[1898,"سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ نے کہا : ( ایک بار ) سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ جمعے کے دن لوگوں کو خطبہ ارشادفرمارہے تھے کہ اسی دوران میں سیدنا عثمان بن عفان رضی اللہ تعالیٰ عنہ مسجد میں داخل ہوئے ۔ سیدنا عمر رضی اللہ تعالیٰ عنہ نے ان پر تعریف کی ( اعتراض کیا ) اور کہا : لوگوں کو کیا ہوا کہ اذان کےبعد دیر لگاتے ہیں؟سیدنا عثمان رضی اللہ تعالیٰ عنہ نے کہا : اے امیر المومنین رضی اللہ تعالیٰ عنہ !میں نے اذان سننے پر اس سے زیادہ کچھ نہیں کیا کہ وضو کیا ہے اور حاضر ہوگیا ہوں ، اس پر عمر رضی اللہ تعالیٰ عنہ نے کہا اور وہ بھی ( صرف ) وضو؟ کیا تم لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے نہیں سنا : \" جب تم میں سے کوئی جمعے کے لئے آئے تو وہ غسل کرے؟","",{"u2":"حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ نے کہا: (ایک بار) حضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ جمعے کے دن لوگوں کو خطبہ ارشادفرمارہے تھے کہ اسی دوران میں حضرت عثمان بن عفان رضی اللہ تعالیٰ عنہ مسجد میں داخل ہوئے۔حضرت عمر رضی اللہ تعالیٰ عنہ نے ان پر تعریف کی(اعتراض کیا) اور کہا:لوگوں کو کیا ہوا کہ اذان کےبعد دیر لگاتے ہیں؟حضرت عثمان رضی اللہ تعالیٰ عنہ نے کہا:اے امیر المومنین رضی اللہ تعالیٰ عنہ!میں نے اذان سننے پر اس سے زیادہ کچھ نہیں کیا کہ وضو کیا ہے اورحاضر ہوگیاہوں،اس پر عمر رضی اللہ تعالیٰ عنہ نے کہا اور وہ بھی(صرف) وضو؟ کیا تم لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے نہیں سنا:\" جب تم میں سے کوئی جمعے کے لئے آئے تو وہ غسل کرے؟\""}],[1899,"سیدنا ابو سعید خدری رضی اللہ تعالیٰ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" جمعے کے دن ہر بالغ شخص پر غسل کرنا واجب ہے ۔","",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالیٰ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا: \"جمعے کے دن ہر بالغ شخص پر غسل کرنا واجب ہے۔\""}],[1900,"عروہ بن زبیر نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : جمعے کے لیے لو گ اپنے گھروں سے اور عوالی سے باری باری آتے تھے وہ اونی عبائیں پہنے ہو تے تھے اور ( راستے میں ) ان پر گردو غبار بھی پڑتا تھا جس کی وجہ سے ان سے بو پھوٹتی تھی ان میں سے ایک انسان رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس وقت آپ صلی اللہ علیہ وسلم میرے ہاں تشریف فر ما تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" کیا ہی اچھا ہو کہ تم لو گ اس دن کے لیے صاف ستھرے ہو جا یا کرو ۔","",{"u2":"عروہ بن زبیر نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی، انھوں نے کہا: جمعے کے لیے لو گ اپنے گھروں سے اور عوالی سے باری باری آتے تھے وہ اونی عبائیں پہنے ہو تے تھے اور (راستے میں) ان پر گردو غبار بھی پڑتا تھا جس کی وجہ سے ان سے بو پھوٹتی تھی ان میں سے ایک انسان رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس وقت آپ صلی اللہ علیہ وسلم میرے ہاں تشریف فر ما تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"کیا ہی اچھا ہو کہ تم لو گ اس دن کے لیے صاف ستھرے ہو جا یا کرو۔"}],[1901,"عمرہ نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : لو گ کا م کا ج والے تھے ان کے نوکر چاکر نہ ہو تے تھے وہ ایسے تھے کہ ان سے بو آتی تھی تو ان سے کہا گیا : کیا ہی اچھا ہو کہ تم جمعے کے دن نہا لیا کرو ۔","",{"u2":"عمرہ نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا: لو گ کا م کا ج والے تھے ان کے نوکر چاکر نہ ہو تے تھے وہ ایسے تھے کہ ان سے بو آتی تھی تو ان سے کہا گیا: کیا ہی اچھا ہو کہ تم جمعے کے دن نہا لیا کرو۔"}],[1902,"سعید بن ابی بلال اور بکیر بن اشج نے ابو بکر بن منکد ر سے حدیث بیان کی ، انھوں نے عمرو بن سلیم سے انھوں نے عبد الرحمٰن بن ابی سعید خدری رضی اللہ تعالیٰ عنہ سے اور انھوں نے اپنے والد ( سیدنا ابو سعید رضی اللہ تعالیٰ عنہ ) سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \"\" جمعے کے دن غسل کرنا ہر بالگ شخص پر واجب ہے اور مسواک کرنا بھی اور ( ہر شخص ) اپنی استطاعت کے مطا بق خوشبو استعمال کرے ۔ \"\" البتہ بکیر نے ( سند میں ) عبد الرحمان کا ذکر نہیں کیا اورخوشبوکے بارے میں کہا : \"\" چاہے وہ عورت کی خوشبو کیوں نہ ہو ۔","",{"u2":"سعید بن ابی بلال اور بکیر بن اشج نے ابو بکر بن منکد ر سے حدیث بیان کی، انھوں نے عمرو بن سلیم سے انھوں نے عبد الرحمٰن بن ابی سعید خدری رضی اللہ تعالیٰ عنہ سے اور انھوں نے اپنے والد (حضڑت ابو سعید رضی اللہ تعالیٰ عنہ) سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"جمعے کے دن غسل کرنا ہر بالگ شخص پر واجب ہے اور مسواک کرنا بھی اور (ہر شخص) اپنی استطاعت کے مطا بق خوشبو استعمال کرے۔\"\nالبتہ بکیر نے (سند میں) عبد الرحمان کا ذکر نہیں کیا اورخوشبوکے بارے میں کہا: \"چاہے وہ عورت کی خوشبو کیوں نہ ہو۔"}],[1903,"روح بن عباوہ اور عبد الرزاق نے ابن جریج سے حدیث بیان کی انھوں نے کہا مجھے ابراہیم بن میسر ہ نے طاوس سے خبر دی اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے جمعے کے دن غسل کرنے کے بارے میں نبی صلی اللہ علیہ وسلم کا فر ما ن بیان کیا ۔ طاوس نے کہا : میں نے ابن عباس رضی اللہ تعالیٰ عنہ سے پو چھا : اگر اس کے گھر والوں کے پاس موجود ہو تو وہ خوشبو تیل بھی استعمال کر سکتا ہے ؟انھوں نے ( جواب میں ) کہا : میں یہ بات نہیں جا نتا ۔","",{"u2":"روح بن عباوہ اور عبد الرزاق نے ابن جریج سے حدیث بیان کی انھوں نے کہا مجھے ابراہیم بن میسر ہ نے طاوس سے خبر دی اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے جمعے کے دن غسل کرنے کے بارے میں نبی صلی اللہ علیہ وسلم کا فر ما ن بیان کیا۔طاوس نے کہا: میں نے ابن عباس رضی اللہ تعالیٰ عنہ سے پو چھا: اگر اس کے گھر والوں کے پاس موجود ہو تو وہ خوشبو تیل بھی استعمال کر سکتا ہے؟انھوں نے (جواب میں) کہا: میں یہ بات نہیں جا نتا۔"}],[1904,"محمد بن بکر اور ضحاک بن مخلددونوں نے بن جریج سے اسی سند کے ساتھ ( سابقہ ) حدیث بیان کی ۔","",{"u2":"محمد بن بکر اور ضحاک بن مخلددونوں نے بن جریج سے اسی سند کے ساتھ (سابقہ) حدیث بیان کی۔"}],[1905,"طاوس نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی آپ نے فر ما یا : ہر مسلمان پر اللہ تعا لیٰ کا حق ہے کہ وہ ہر سات دنوں میں ( کم سے کم ) ایک بار نہائے اپنا سر اور اپنا جسم دھوئے ۔","",{"u2":"طاوس نے حضڑت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی آپ نے فر ما یا: ہر مسلمان پر اللہ تعا لیٰ کا حق ہے کہ وہ ہر سات دنوں میں(کم سے کم) ایک بار نہائے اپنا سر اور اپنا جسم دھوئے۔\""}],[1906,"ابو صالح سمنان نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" جس نے جمعے کے دن غسل جنابت ( جیسا غسل ) کیا پھر مسجد ) چلا گیا تو اس نے گو یا ایک اونٹ قربان کیا اور جو دوسری گھڑی میں گیا تو گو یا اس نے گا ئے قربان کی اور جو تیسری گھڑی میں گیا گو یا اس نے سینگوں والا ایک مینڈھا قربان کیا اور جو چوتھی گھڑی میں گیا اس نے گو یا ایک مرغ اللہ کے تقرب کے لیے پیش کیا اور جو پانچویں گھڑی میں گیا اس نے گو یا ایک انڈا تقرب کے لیے پیش کیا اس کے بعد جب امام آجا تا ہے تو فرشتے ذکر ( عبادتاور امور خیر کی یاد دہانی ) سنتے ہیں ۔","",{"u2":"ابو صالح سمنان نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"جس نے جمعے کے دن غسل جنابت (جیسا غسل) کیا پھر مسجد) چلا گیا تو اس نے گو یا ایک اونٹ قربان کیا اور جودوسری گھڑی میں گیا تو گو یا اس نے گا ئے قربان کی اور جو تیسری گھڑی میں گیا گو یا اس نے سینگوں والا ایک مینڈھا قربان کیا اور جو چوتھی گھڑی میں گیا اس نے گو یا ایک مرغ اللہ کے تقرب کے لیے پیش کیا اور جو پانچویں گھڑی میں گیا اس نے گو یا ایک انڈا تقرب کے لیے پیش کیا اس کے بعد جب امام آجا تا ہے تو فرشتے ذکر (عبادتاور امور خیر کی یاد دہانی) سنتے ہیں۔"}],[1907,"قتیبہ بن سعید اور محمد بن رمح بن مہاجر نے حدیث بیان کی ، ابن رمح نے کہا : ہمیں لیث نے عقیل بن خالد سے خبر دی انھوں نے بن شہاب سے روایت کی انھوں نے کہا مجھے سعید بن مسیب نے خبر دی کہ سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" جمعے کے دن جب امام خطبہ دے رہا ہو ( اس وقت ) اگر تم نے اپنے ساتھی سے کہا : خاموش رہو تو تم نے فضول گو ئی کی ۔","",{"u2":"قتیبہ بن سعید اور محمد بن رمح بن مہاجر نے حدیث بیان کی،ابن رمح نے کہا: ہمیں لیث نے عقیل بن خالد سے خبر دی انھوں نے بن شہاب سے روایت کی انھوں نے کہا مجھے سعید بن مسیب نے خبر دی کہ حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"جمعے کے دن جب امام خطبہ دے رہا ہو (اس وقت)اگر تم نے اپنے ساتھی سے کہا: خاموش رہو تو تم نے فضول گو ئی کی۔"}],[1908,"عبد الملک بن شعیب بن لیث نے کہا : مجھ سے میرے والد شعیب نے میرے دادا لیث سے حدیث بیان کی انھوں نے کہا : مجھ سے عقیل بن خالد نے ابن شہاب سے انھوں نے عمربن عبد العزیز سے انھوں نے عبد اللہ بن ابرا ہیم بن قارظ سے روایت کی نیز انھوں نے ( ابن شہاب زہری ) نے ابن مسیب سے بھی روا یت کی ان دو نوں ( عمربن عبد العزیز اور سعید بن مسیب ) نے ان ( بن شہاب سے حدیث بیان کی کہ سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے سنا ۔ ۔ ۔ ( آگے اسی سند حدیث ) کے مانند ہے ۔","",{"u2":"عبد الملک بن شعیب بن لیث نے کہا: مجھ سے میرے والد شعیب نے میرے دادالیث سے حدیث بیان کی انھوں نے کہا: مجھ سے عقیل بن خالد نے ابن شہاب سے انھوں نے عمربن عبد العزیز سے انھوں نے عبد اللہ بن ابرا ہیم بن قارظ سے روایت کی نیز انھوں نے (ابن شہاب زہری) نے ابن مسیب سے بھی روا یت کی ان دو نوں (عمربن عبد العزیز اور سعید بن مسیب) نے ان (بن شہاب سے حدیث بیان کی کہ حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے سنا۔۔۔(آگے اسی سند حدیث) کے مانند ہے۔"}],[1909,"ابن جریج نے کہا : ابن شہاب نے مجھے اس حدیث کی دونوں سندوں کے ساتھ اس حدیث میں اسی کے مانند خبردی البتہ ابن جریج نے ( عبد اللہ بن ابرا ہیم بن قارظ کے بجا ئے ) ابرا ہیم بن عبد اللہ بن قارظ کہا ہے ۔ ( امام مسلم نے نا م کی درستی کے لیے یہ سند بیان کی)","",{"u2":"ابن جریج نے کہا: ابن شہاب نے مجھے اس حدیث کی دونوں سندوں کے ساتھ اس حدیث میں اسی کے مانند خبردی البتہ ابن جریج نے(عبد اللہ بن ابرا ہیم بن قارظ کے بجا ئے) ابرا ہیم بن عبد اللہ بن قارظ کہا ہے۔(امام مسلم نے نا م کی درستی کے لیے یہ سند بیان کی)"}],[1910,"ابو زناد نے عرج سے انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی آپ صلی اللہ علیہ وسلم نے فر ما یا : \"\" جمعے کے دن جب امام خطبہ دے رہا ہو ( اس وقت ) اگر تم نے اپنے ساتھی سے کہا : خا مو ش رہو تو تم نے ( خود ) شور مچا یا ۔ \"\" ابو زناد نے کہا : یہ ( فقد لغيت ) ابو ہریرہ رضی اللہ تعالیٰ عنہ ( کے قبیلے ) کی لغت ہے جبکہ ( عام مروج لغت ) ( فقد لغوت ) ہے ۔","",{"u2":"ابو زناد نے عرج سے انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی آپ صلی اللہ علیہ وسلم نے فر ما یا:\"جمعے کے دن جب امام خطبہ دے رہا ہو (اس وقت) اگر تم نے اپنے ساتھی سے کہا:خا مو ش رہو تو تم نے (خود) شور مچا یا۔\"\nابو زناد نے کہا:یہ (فقد لغیت)ابو ہریرہ رضی اللہ تعالیٰ عنہ (کے قبیلے) کی لغت ہے جبکہ (عام مروج لغت) (فقد لغوت)ہے۔"}],[1911,"یحییٰ بن یحییٰ اور قتیبہ بن سعید نے مالک بن انس انھوں نے ابو زناد سے انھوں نے اعرج سے اور انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جمعے کا ذکر کرتے ہو ئے فر ما یا : \"\" اس میں ایک گھڑی ہے اس ( گھڑی ) کی موافقت کرتے ہو ئے کو ئی مسلمان بندہ نماز پڑھتے ہو ئے اللہ تعا لیٰ سے جو کچھ بھی مانگتا ہے اللہ تعا لیٰ اسے عطا کر دیتا ہے ۔ قتیبہ نے اپنی روایت میں اضافہ کیا : آپ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے اشارا فر ما کر اس گھڑی کے قلیل ہو نے کو واضح کیا ۔","",{"u2":"یحییٰ بن یحییٰ اور قتیبہ بن سعید نے مالک بن انس انھوں نے ابو زناد سے انھوں نے اعرج سے اور انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جمعے کا ذکر کرتے ہو ئے فر ما یا:\"اس میں ایک گھڑی ہے اس (گھڑی)کی موافقت کرتے ہو ئے کو ئی مسلمان بندہ نماز پڑھتے ہو ئے اللہ تعا لیٰ سے جو کچھ بھی مانگتا ہے اللہ تعا لیٰ اسے عطا کر دیتا ہے۔\nقتیبہ نے اپنی روایت میں اضافہ کیا: آپ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے اشارا فر ما کر اس گھڑی کے قلیل ہو نے کو واضح کیا۔"}],[1912,"ایوب نے محمد سے انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : ابو القاسم صلی اللہ علیہ وسلم نے فر ما یا : \" بیشک جمعے کے دن میں ایک گھڑی ہے کوئی مسلمان بھی کھڑا نماز پڑھتے ہو ئے اس کی موافقت کر لیتا ( اسے پالیتا ) ہے ( اور ) اللہ تعا لیٰ سے کسی خیر کا سوال کرتا ہے تو اللہ تعا لیٰ اسے وہی ( خیر ) عطا کر دیتا ہے ۔ اور آپ صلی اللہ علیہ وسلم نے ہا تھ سے اس کے قلیل اور کم ہو نے کو بیان کیا ۔","",{"u2":"ایوب نے محمد سے انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا: ابو القاسم صلی اللہ علیہ وسلم نے فر ما یا:\"بیشک جمعے کے دن میں ایک گھڑی ہے کوئی مسلمان بھی کھڑا نماز پڑھتے ہو ئے اس کی موافقت کر لیتا (اسے پالیتا)ہے (اور)اللہ تعا لیٰ سے کسی خیر کا سوال کرتا ہے تو اللہ تعا لیٰ اسے وہی (خیر) عطا کر دیتا ہے۔اور آپ صلی اللہ علیہ وسلم نے ہا تھ سے اس کے قلیل اور کم ہو نے کو بیان کیا۔"}],[1913,"ابن عون نے محمد سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا ابو القاسم صلی اللہ علیہ وسلم نے فر ما یا ۔ ۔ ۔ ( آگے ) اسی ( سابقہ حدیث ) کے ما نند ہے ۔","",{"u2":"ابن عون نے محمد سے اور انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا ابو القاسم صلی اللہ علیہ وسلم نے فر ما یا۔۔۔(آگے)اسی (سابقہ حدیث) کے ما نند ہے۔"}],[1914,"سلمہ بن علقمہ نے محمد سے اورانھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا : ابو القاسم صلی اللہ علیہ وسلم نے فر ما یا ۔ ۔ ۔ ( آگے ) اسی ( سابقہ حدیث ) کے مانند ہے","",{"u2":"سلمہ بن علقمہ نے محمد سے اورانھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا: ابو القاسم صلی اللہ علیہ وسلم نے فر ما یا۔۔۔(آگے) اسی (سابقہ حدیث) کے مانند ہے"}],[1915,"محمد بن زیاد نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ۔ آپ نے فر ما یا \" جمعے کے دن میں ایک گھڑی ایسی ہے کہ کو ئی مسلمان اللہ تعا لیٰ سے کسی خیر کا سوال کرتے ہو ئے اس کی موافقت نہیں کرتا مگر اللہ تعا لیٰ اسے وہی خیر عطا کر دیتا ہے \" فر ما یا یہ ایک چھوٹی سی گھڑی ہے ۔","",{"u2":"محمد بن زیاد نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی۔آپ نے فر ما یا \"جمعے کے دن میں ایک گھڑی ایسی ہے کہ کو ئی مسلمان اللہ تعا لیٰ سے کسی خیر کا سوال کرتے ہو ئے اس کی موافقت نہیں کرتا مگر اللہ تعا لیٰ اسے وہی خیر عطا کر دیتا ہے\"فر ما یا یہ ایک چھوٹی سی گھڑی ہے۔"}],[1916,"ہمام بن منبہ نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی لیکن انھوں نے ( وهي ساعة خفيفة ) ( وہ ایک چھوٹی سی گھڑی ہے ) نہیں کہا ۔","",{"u2":"ہمام بن منبہ نے حضڑت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی لیکن انھوں نے (وہی ساعۃ خفیفۃ)(وہ ایک چھوٹی سی گھڑی ہے)نہیں کہا۔"}],[1917,"ابو بردہ بن ابی مو سیٰ اشعری رضی اللہ تعالیٰ عنہ سے روا یت ہے کہا : مجھ سے سیدنا عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ نے کہا : کیا تم نے اپنے والد کو جمعے کی گھڑی کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کرتے ہو ئے سنا ہے ؟کہ کہا : میں نے کہا : جی ہاں میں نے انھیں یہ کہتے سنا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فر ما رہے تھے : \" یہ امام کے بیٹھنے سے لے کر نماز مکمل ہو نے تک ہے ۔","",{"u2":"ابو بردہ بن ابی مو سیٰ اشعری رضی اللہ تعالیٰ عنہ سے روا یت ہے کہا: مجھ سے حضرت عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ نے کہا: کیا تم نے اپنے والد کو جمعے کی گھڑی کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کرتے ہو ئے سنا ہے؟کہ کہا: میں نے کہا: جی ہاں میں نے انھیں یہ کہتے سنا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فر ما رہے تھے:\"یہ امام کے بیٹھنے سے لے کر نماز مکمل ہو نے تک ہے۔"}],[1918,"ابن شہاب نے کہا : مجھے عبد الرحمٰن اعرج نے خبر دی انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ کو کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" بہترین دن جس پر سورج طلوع ہو تا ہے جمعے کا دن ہے اسی دن آدم ؑپیدا کیے گئے اور اسی دن جنت میں داخل کیے گئے اور اسی دن اس سے نکا لے گئے ۔","",{"u2":"ابن شہاب نے کہا: مجھے عبد الرحمٰن اعرج نے خبر دی انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ کو کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"بہترین دن جس پر سورج طلوع ہو تا ہے جمعے کا دن ہے اسی دن آدم علیہ السلام پیدا کیے گئے اور اسی دن جنت میں داخل کیے گئے اور اسی دن اس سے نکا لے گئے۔"}],[1919,"ابو زناد نے اعرج سے اور انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے رو یت کی کہ نبی کریم صلی اللہ علیہ وسلم نے فر ما یا : بہترین دن جس میں سورج نکلتا ہے جمعے کا ہے اسی دن آدم ؑکو پیدا کیا گیا تھا اور اسی دن انھیں جنت میں داخل کیا گیا اور اسی میں انھیں اس سے نکا لا گیا ( خلا فت ارضی سونپی گئی ) اور قیامت بھی جمعے کے دن ہی بر پاہو گی ۔ \" صالح مومنوں کے لیے یہ انعام عظیم حا صل کرنے کا دن ہو گا ۔","",{"u2":"ابو زناد نے اعرج سے اور انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے رو یت کی کہ نبی کریم صلی اللہ علیہ وسلم نے فر ما یا:بہترین دن جس میں سورج نکلتا ہے جمعے کا ہے اسی دن آدم علیہ السلام کو پیدا کیا گیا تھا اور اسی دن انھیں جنت میں داخل کیا گیا اور اسی میں انھیں اس سے نکا لا گیا (خلا فت ارضی سونپی گئی) اور قیامت بھی جمعے کے دن ہی بر پاہو گی۔\"صالح مومنوں کے لیے یہ انعام عظیم حا صل کرنے کا دن ہو گا۔"}],[1920,"عمر و ناقد نے کہا : ہمیں سفیان بن عیینہ نے ابو زناد سے حدیث سنا ئی انھوں نے اعرج سے اور انھوں نے حجرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" ہم سب سے آخری ہیں اور قیامت کے دن سب سے پہلے ہو ں گے یہ اس کے باوجود ہے کہ ہر امت کو کتاب ہم سے پہلے دی گئی اور ہمیں ( ہماری کتاب ) ان کے بعد دی گئی پھر یہ دن جسے اللہ تعالیٰ نے ہمارے لئے لکھ دیا تھا اللہ تعا لیٰ نے اس کے لیے ہماری رہنما ئی فر ما ئی لو گ اس معاملے میں ہمارے بعد ہیں یہود کل ( جمعے سے اگلا دن یعنی ہفتہ منا ئیں گے ) اور نصاریٰ پرسوں ( ہفتےسے اگلا دن اتوار کا منا ئیں گے ۔)","",{"u2":"عمر و ناقد نے کہا:ہمیں سفیان بن عیینہ نے ابو زناد سے حدیث سنا ئی انھوں نے اعرج سے اور انھوں نے حجرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"ہم سب سے آخری ہیں اور قیامت کے دن سب سے پہلے ہو ں گے یہ اس کے باوجود ہے کہ ہر امت کو کتاب ہم سے پہلے دی گئی اور ہمیں (ہماری کتاب)ان کے بعد دی گئی پھر یہ دن جسے اللہ تعالیٰ نے ہمارے لئے لکھ دیا تھا اللہ تعا لیٰ نے اس کے لیے ہماری رہنما ئی فر ما ئی لو گ اس معاملے میں ہمارے بعد ہیں یہود کل (جمعے سے اگلا دن یعنی ہفتہ منا ئیں گے) اور نصاریٰ پرسوں (ہفتےسے اگلا دن اتوار کا منا ئیں گے۔)"}],[1921,"ابن ابی عمر نے کہا : ہمیں سفیان نے ابو زناد سے حدیث سنا ئی انھوں نے اعرج سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت کی نیز ( سفیان نے عبد اللہ ) بن طاوس سے انھوں نے اپنے والد ( طاوس بن کیسان ) سے انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" ہم سب کے بعد آنے والے ہیں اور قیامت کے دن ہم سب سے پہلے ہو ں گے ۔ ۔ ۔ \" اسی ( مذکورہ با لا حدیث ) کے مانند ہے","",{"u2":"ابن ابی عمر نے کہا: ہمیں سفیان نے ابو زناد سے حدیث سنا ئی انھوں نے اعرج سے اور انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت کی نیز(سفیان نے عبد اللہ) بن طاوس سے انھوں نے اپنے والد (طاوس بن کیسان) سے انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\" ہم سب کے بعد آنے والے ہیں اور قیامت کے دن ہم سب سے پہلے ہو ں گے۔۔۔\"اسی (مذکورہ با لا حدیث) کے مانند ہے"}],[1922,"ابو صالح نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" ہم آخری ہیں ( پھر بھی ) قیامت کے دن پہلے ہو ں گے اور ہم ہی پہلے جنت میں داخل ہوں گے البتہ انھیں ( انکی ) کتاب ہم سب سے پہلے دی گئی اور ہمیں ( ہماری کتاب ) ان کے بعد دی گئی انھوں نے ( آپس میں ) اختلا ف کیا اور اللہ تعا لیٰ نے ہماری اس حق کی طرف رہنما ئی فر ما ئی جس میں انھوں نے اختلا ف کیا تھا یہ ( جمعہ ) ان کا وہی دن تھا جس کے بارے میں انھوں نے اختلا ف کیا اللہ تعا لیٰ نے ہمیں اس کی طرف رہنما ئی کردی ۔ ۔ ۔ راوی نے کہا : جمعے کا دن مراد ہے ۔ ۔ آج کا دن ہمارا ہے اور کل کا دن یہودیوں کا ہے اس سے اگلا دن عیسائیوں کا ۔","",{"u2":"ابو صالح نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"ہم آخری ہیں (پھر بھی) قیامت کے دن پہلے ہو ں گے اور ہم ہی پہلے جنت میں داخل ہوں گے البتہ انھیں (انکی) کتاب ہم سب سے پہلے دی گئی اور ہمیں (ہماری کتاب) ان کے بعد دی گئی انھوں نے (آپس میں) اختلا ف کیا اور اللہ تعا لیٰ نے ہماری اس حق کی طرف رہنما ئی فر ما ئی جس میں انھوں نے اختلا ف کیا تھا یہ (جمعہ) ان کا وہی دن تھا جس کے بارے میں انھوں نے اختلا ف کیا اللہ تعا لیٰ نے ہمیں اس کی طرف رہنما ئی کردی۔۔۔راوی نے کہا: جمعے کا دن مرادہے۔۔آج کا دن ہمارا ہے اور کل کا دن یہودیوں کا ہے اس سے اگلا دن عیسائیوں کا۔\""}],[1923,"وہب بن منبہ کے بھا ئی ہمام بن منبہ نے کہا : یہ حدیث ہے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے ہمیں محمد رسول اللہ صلی اللہ علیہ وسلم سے بیان کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : ہم آخری ہیں ( مگر ) قیامت کے دن سبقت لے جا نے والے ہو ں گے اس کے باوجود کہ ان کے بعد دی گئی اور یہ ( جمعہ ) ان کا وہی دن ہے جو ان پر فرض کیا گیا تھا اور وہ اس کے بارے میں اختلاف میں پڑگئے پھر اللہ تعا لیٰ نے اس کے بارے میں ہماری رہنمائی فر ما ئی اس لیے وہ لو گ اس ( عبادت کے دن کے ) معاملے میں ہم سے پیچھے ہیں یہود ( اپنا دن ) کل منا ئیں گے اور عیسا ئی پر سوں ۔","",{"u2":"وہب بن منبہ کے بھا ئی ہمام بن منبہ نے کہا: یہ حدیث ہے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے ہمیں محمد رسول اللہ صلی اللہ علیہ وسلم سے بیان کی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا: ہم آخری ہیں (مگر) قیامت کے دن سبقت لے جا نے والے ہو ں گے اس کے باوجود کہ ان کے بعد دی گئی اور یہ (جمعہ) ان کا وہی دن ہے جو ان پر فرض کیا گیا تھا اور وہ اس کے بارے میں اختلاف میں پڑگئے پھر اللہ تعا لیٰ نے اس کے بارے میں ہماری رہنمائی فر ما ئی اس لیے وہ لو گ اس (عبادت کے دن کے) معاملے میں ہم سے پیچھے ہیں یہود (اپنا دن) کل منا ئیں گے اور عیسا ئی پر سوں۔"}],[1924,"ابو کریب اور واصل بن عبدالاعلیٰ نے کہا : ہم سے ابن فضیل نے ابومالک اشجعی ( سعد بن طارق ) سے حدیث بیان کی ، انھوں نے ابو حازم سے اورانھوں نے ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی ، نیز انھوں ( ابو مالک ) نے ربعی بن حراش سے اور انھوں نے سیدنا حذیفہ رضی اللہ تعالیٰ عنہ سے روایت کی ، ان دونوں ( صحابیوں ) نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جو لوگ ہم سے پہلے تھے اللہ تعالیٰ نے انھیں جمعہ کی راہ سے ہٹادیا ، اس لئے یہود کے لئے ہفتے کا دن ہوگیا اور نصاریٰ کے لئے اتوار کا دن ۔ پھر اللہ تعالیٰ نے ہمیں ( اس دنیا میں لایا ) اور جمعے کے دن کی طرف ہماری راہنمائی فرمادی ۔ اس نے جمعہ پھر ہفتہ پھر اتوار رکھا ( جس طرح وہ عبادت کے دنوں میں ہم سے پیچھے ہیں ) اسی طرح قیامت کے دن بھی ہم سے پیچھے ہوں گے ۔ اہل دنیا میں سے ہم سب کے بعد ہیں اور قیامت کےدن سب سے پہلے ہوں گے ۔ جن کا فیصلہ ( باقی ) مخلوقات سے پہلے کردیا جائے گا ۔ \"\" واصل کی روایت میں ( المقضي لهم کی جگہ ) المقضي بينهم ( جن کے درمیان فیصلہ ) ہے ۔","",{"u2":"ابو کریب اور واصل بن عبدالاعلیٰ نے کہا:ہم سے ابن فضیل نے ابومالک اشجعی(سعد بن طارق) سے حدیث بیان کی،انھوں نے ابو حازم سے اورانھوں نے ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی،نیز انھوں(ابو مالک) نے ربعی بن حراش سے اور انھوں نے حضرت حذیفہ رضی اللہ تعالیٰ عنہ سے روایت کی،ان دونوں(صحابیوں) نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" جو لوگ ہم سے پہلے تھے اللہ تعالیٰ نے انھیں جمعہ کی راہ سے ہٹادیا،اس لئے یہود کے لئے ہفتے کا دن ہوگیا اور نصاریٰ کے لئے اتوار کا دن۔پھراللہ تعالیٰ نے ہمیں(اس دنیا میں لایا) اور جمعے کے دن کی طرف ہماری راہنمائی فرمادی۔اس نے جمعہ پھر ہفتہ پھر اتوار رکھا(جس طرح وہ عبادت کے دنوں میں ہم سے پیچھے ہیں)اسی طرح قیامت کے دن بھی ہم سے پیچھے ہوں گے۔اہل دنیا میں سے ہم سب کے بعد ہیں اور قیامت کےدن سب سے پہلے ہوں گے۔جن کا فیصلہ(باقی) مخلوقات سے پہلے کردیا جائے گا۔\"\nواصل کی روایت میں(المقضی لہم کی جگہ) المقضی بینہم(جن کے درمیان فیصلہ) ہے۔"}],[1925,"ابن ابی زائدہ نے ( ابومالک ) سعد بن طارق سے خبر دی ، انھوں نے کہا : ربعی بن حراش نے مجھے سیدنا حذیفہ رضی اللہ تعالیٰ عنہ سے حدیث بیان کی ، انھوں نےکہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ہماری راہنمائی جمعے کی طرف کی گئی اور جو لوگ ہم سے پہلے تھے ان کو اللہ تعالیٰ نے ا س سے دوسری راہ پر لگادیا ۔ ۔ ۔ \" آگے ابن فضیل کے ہم معنی حدیث بیان کی ۔","",{"u2":"ابن ابی زائدہ نے(ابومالک) سعد بن طارق سے خبر دی،انھوں نے کہا:ربعی بن حراش نے مجھے حضرت حذیفہ رضی اللہ تعالیٰ عنہ سے حدیث بیان کی،انھوں نےکہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"ہماری راہنمائی جمعے کی طرف کی گئی اور جو لوگ ہم سے پہلے تھے ان کو اللہ تعالیٰ نے ا س سےدوسری راہ پر لگادیا۔۔۔\"آگے ابن فضیل کے ہم معنی حدیث بیان کی۔"}],[1926,"ابوعبداللہ اغر نے خبر دی کہ انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایاجب جمعے کا دن ہوتا ہے تو مسجد کے دروازوں میں سے ہر دروازے پر فرشتے ہوتے ہیں جو ( آنے والوں کی ترتیب کے مطابق ( پہلے پھر پہلے کا نام لکھتے ہیں ، اور جب امام ( منبر پر ) بیٹھ جاتا ہے تو وہ ( ناموں والے ) صحیفے لپیٹ دیتے ہیں اورآکرذکر ( خطبہ ) سنتے ہیں ۔ اور گرمی میں ( پہلے ) آنے والے کی مثال اس انسان جیسی ہے جو اونٹ قربان کرتا ہے پھر ( جو آیا ) گویا وہ گائے قربان کردیتا ہے ۔ پھر ( جو آیا ) گویا وہ مینڈھا قربان کردیتاہے ، پھر ( جو آیا ) گویا وہ تقرب کے لئے مرغی پیش کرتاہے پھر ( جو آیا ) گویا وہ تقریب کے لئے انڈا پیش کرتا ہے ۔","",{"u2":"ابوعبداللہ اغر نے خبر دی کہ انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے سنا،وہ کہہ رہے تھے:رسول اللہ صلی اللہ علیہ وسلم نے فرمایاجب جمعے کا دن ہوتا ہے تو مسجد کے دروازوں میں سے ہر دروازے پر فرشتے ہوتے ہیں جو(آنے والوں کی ترتیب کے مطابق(پہلے پھر پہلے کا نام لکھتے ہیں،اور جب امام(منبر پر) بیٹھ جاتا ہے تو وہ(ناموں والے) صحیفے لپیٹ دیتے ہیں اورآکرذکر(خطبہ) سنتے ہیں۔اور گرمی میں(پہلے) آنے والے کی مثال اس انسان جیسی ہے جو اونٹ قربان کرتا ہےپھر(جو آیا) گویا وہ گائے قربان کردیتا ہے۔پھر(جو آیا) گویا وہ مینڈھا قربان کردیتاہے،پھر(جو آیا) گویا وہ تقرب کے لئے مرغی پیش کرتاہے پھر (جو آیا) گویا وہ تقریب کے لئے انڈا پیش کرتا ہے۔\""}],[1927,"سعید ( بن مسیب ) نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی ( سابقہ حدیث ) کے مانند روایت کی ۔","",{"u2":"سعید(بن مسیب) نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی(سابقہ حدیث) کے مانند روایت کی۔"}],[1928,"سہیل کے والد ابو صالح سمان نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مسجد کے دروازوں میں سے ہر ایک دروازے پر ایک فرشتہ ہوتاہے جو پہلے پھر پہلے آنے والے کا نام لکھتا ہے ۔ آپ نے اونٹ کی قربانی کی مثال دی ، پھر بتدریج کم کرتے گئے یہاں تک کہ ( آخر میں ) انڈے جیسے چھوٹے ( صدقے ) کی مثال دی ۔ پھر جب امام منبر پر بیٹھ جاتا ہے تو ( اندراج کے ) صحیفے لپیٹ دیئے جاتے ہیں اور ( فرشتے ) ذکر ونصیحت ( سننے ) کے لئے حاضر ہوجاتے ہیں ۔","",{"u2":"سہیل کے والد ابو صالح سمان نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"مسجد کے دروازوں میں سے ہر ایک دروازے پر ایک فرشتہ ہوتاہے جو پہلے پھر پہلے آنے والے کا نام لکھتا ہے۔آپ نے اونٹ کی قربانی کی مثال دی،پھر بتدریج کم کرتے گئے یہاں تک کہ (آخر میں) انڈے جیسے چھوٹے(صدقے) کی مثال دی۔پھر جب امام منبر پر بیٹھ جاتا ہے تو(اندراج کے) صحیفے لپیٹ دیئے جاتے ہیں اور(فرشتے) ذکر ونصیحت(سننے) کے لئے حاضر ہوجاتے ہیں۔\""}],[1929,"سہیل نے اپنے والد ( ابو صالح ) سے ، انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کہ آپ نے فرمایا : \" جس نے غسل کیا ، پھر جمعے کے لئے حاضر ہوا ، پھر اس کے مقدر میں جتنی ( نفل ) نماز تھی پڑھی ، پھر خاموشی سے ( خطبہ ) سنتا رہا حتیٰ کہ خطیب اپنے خطبے سے فارغ ہوگیا ، پھر اس کے ساتھ نماز پڑھی ، اس کے اس جمعے سے لے کر ایک اور ( پچھلے یا اگلے ) جمعے تک کے گناہ بخش دیے جاتے ہیں اور مزید تین دنوں کے بھی ۔","",{"u2":"سہیل نے اپنے والد(ابو صالح) سے،انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کہ آپ نے فرمایا:\"جس نے غسل کیا،پھر جمعے کے لئے حاضر ہوا،پھر اس کے مقدر میں جتنی (نفل) نماز تھی پڑھی،پھر خاموشی سے(خطبہ) سنتا رہا حتیٰ کہ خطیب اپنے خطبے سے فارغ ہوگیا،پھر اس کے ساتھ نماز پڑھی،اس کے اس جمعے سے لے کر ایک اور(پچھلے یا اگلے) جمعے تک کے گناہ بخش دیے جاتے ہیں اور مزید تین دنوں کے بھی۔\""}],[1930,"اعمش نے ابو صالح سے اور انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص نے وضو کیا اور اچھی طرح وضو کیا ، پھر جمعے کے لئے آیا ، غور کے ساتھ خاموشی سے خطبہ سنا ، اس کے جمعے سے لے کر جمعے تک گناہ معاف کردئیے جاتے ہیں ۔ اور تین دن زائد کے بھی ۔ اور جو ( بلاوجہ ) کنکریوں کو ہاتھ لگاتا رہا ( ان سے کھیلتا رہا ) ، اس نے لغو اورفضول کام کیا ۔","",{"u2":"اعمش نے ابو صالح سے اور انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" جس شخص نے وضو کیا اوراچھی طرح وضو کیا،پھر جمعے کے لئے آیا،غور کے ساتھ خاموشی سے خطبہ سنا،اس کے جمعے سے لے کر جمعے تک گناہ معاف کردئیے جاتے ہیں۔اورتین دن زائد کے بھی۔اور جو(بلاوجہ) کنکریوں کو ہاتھ لگاتا رہا(ان سے کھیلتا رہا)،اس نے لغو اورفضول کام کیا۔\""}],[1931,"حسن بن عیاش نے جعفر بن محمد سے ، انھوں نے اپنے والد ( محمد ) سے اور انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تھے ، پھر واپس آتے ، پھر اپنے پانی لانے والے اونٹوں کو آرام کا وقت دیتے ، حسن نےکہا : میں نے جعفر سے کہا : یہ ( نماز ) کس وقت ہوتی؟انھوں نے کہا : سورج کے ڈھلنے کے وقت ۔","",{"u2":"حسن بن عیاش نے جعفر بن محمد سے،انھوں نے اپنے والد (محمد) سے اور انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تھے،پھر واپس آتے،پھر اپنے پانی لانے والے اونٹوں کو آرام کا وقت دیتے،حسن نےکہا:میں نے جعفر سے کہا:یہ (نماز) کس وقت ہوتی؟انھوں نے کہا:سورج کے ڈھلنے کے وقت۔"}],[1932,"قاسم بن زکریا نے کہا : ہمیں خالد بن مخلد نے حدیث بیان کی ، نیز عبداللہ بن عبدالرحمان دارمی نے کہا : ہمیں یحییٰ بن حسان نے حدیث بیان کی ، ان دونوں ( خالد اور یحییٰ ) نے کہا : ہمیں سلیمان بن بلال نے جعفر سے حدیث بیا ن کی ، انھوں نے اپنے والد ( محمد ) سے روایت کی کہ انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے پوچھا : رسول اللہ صلی اللہ علیہ وسلم کس وقت جمعہ پڑھتے تھے؟انھوں نے کہا : آپ جمعہ پڑھاتے ، پھر ہم اونٹوں کے پاس جاتے ، پھر انہیں آرام کا وقت دیتے ۔ عبداللہ نے اپنی روایت میں یہ اضافہ کیا : جس وقت سورج ڈھل جاتا ۔ ( جمال سے مراد ) تواضح ، یعنی پانی لانے والے اونٹ ہیں ۔","",{"u2":"قاسم بن زکریا نے کہا:ہمیں خالد بن مخلد نے حدیث بیان کی،نیز عبداللہ بن عبدالرحمان دارمی نے کہا:ہمیں یحییٰ بن حسان نے حدیث بیان کی،ان دونوں(خالد اوریحییٰ) نے کہا:ہمیں سلیمان بن بلال نے جعفر سےحدیث بیا ن کی،انھوں نےاپنے والد (محمد) سے روایت کی کہ انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے پوچھا:رسول اللہ صلی اللہ علیہ وسلم کس وقت جمعہ پڑھتے تھے؟انھوں نے کہا:آپ جمعہ پڑھاتے،پھر ہم اونٹوں کے پاس جاتے،پھر انہیں آرام کا وقت دیتے۔\nعبداللہ نے اپنی روایت میں یہ اضافہ کیا: جس وقت سورج ڈھل جاتا۔(جمال سے مراد)تواضح،یعنی پانی لانے والے اونٹ ہیں۔"}],[1933,"عبداللہ بن مسلمہ بن قعنب ، یحییٰ بن یحییٰ اور علی بن حجر میں سے یحییٰ نے کہا : ہمیں خبر دی اور دوسرے دونوں نے کہا : ہم سے حدیث بیا ن کی عبدالعزیز بن ابی حازم نے اپنے والد ابوحازم سے ، انھوں نے سیدنا سہیل رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ہم جمعہ کے بعد ہی قیلولہ کرتے اور کھانا کھاتے تھے ۔ ( علی ) ابن حجر نے اضافہ کیا : رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں ۔","",{"u2":"عبداللہ بن مسلمہ بن قعنب،یحییٰ بن یحییٰ اور علی بن حجر میں سے یحییٰ نے کہا:ہمیں خبر دی اور دوسرے دونوں نے کہا:ہم سے حدیث بیا ن کی عبدالعزیز بن ابی حازم نے اپنے والد ابوحازم سے،انھوں نے حضرت سہیل رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:ہم جمعہ کے بعد ہی قیلولہ کرتے اور کھانا کھاتے تھے۔(علی) ابن حجر نے اضافہ کیا:رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں۔"}],[1934,"وکیع نے یعلیٰ بن حارث محاربی سے روایت کی ، انھوں نے ایاس بن سلمہ بن اکوع سے اور انھوں نے اپنے والد ( سیدنا سلمہ بن اکوع رضی اللہ تعالیٰ عنہ ) سے روایت کی ، انھوں نے کہا : جب سورج ڈھلتا ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ پڑھتے ، پھر ہم سایہ تلاش کرتے ہوئے لوٹتے ۔","",{"u2":"وکیع نے یعلیٰ بن حارث محاربی سے روایت کی،انھوں نے ایاس بن سلمہ بن اکوع سے اور انھوں نے اپنے والد(حضرت سلمہ بن اکوع رضی اللہ تعالیٰ عنہ) سے روایت کی،انھوں نے کہا:جب سورج ڈھلتا ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ پڑھتے،پھر ہم سایہ تلاش کرتے ہوئے لوٹتے۔"}],[1935,"ہشام بن عبدالملک نے یعلیٰ بن حارث سے باقی ماندہ اسی سند کے ساتھ روایت کی ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ پڑھتے پھر لوٹتے تو ہمیں دیواروں کا اتنا بھی سایہ نہ ملتا کہ ہم ( سورج سے ) اس کی اوٹ لے سکیں ۔","",{"u2":"ہشام بن عبدالملک نے یعلیٰ بن حارث سے باقی ماندہ اسی سند کے ساتھ روایت کی ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ پڑھتے پھر لوٹتے تو ہمیں دیواروں کا اتنا بھی سایہ نہ ملتا کہ ہم(سورج سے) اس کی اوٹ لے سکیں۔"}],[1936,"سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن کھڑے ہوکر خطبہ ارشاد فرماتے ، پھر ( تھوڑی دیر ) بیٹھ جاتے ، پھر کھڑے ہوجاتے ۔ کہا : جس طرح آجکل ( خطبہ دینے والے ) کرتے ہیں ۔","",{"u2":"حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن کھڑے ہوکر خطبہ ارشاد فرماتے،پھر(تھوڑی دیر) بیٹھ جاتے،پھر کھڑے ہوجاتے۔کہا:جس طرح آجکل (خطبہ دینے والے) کرتے ہیں۔"}],[1937,"ابو احوص نے سماک سے اور انھوں نے سیدنا جابر بن سمرۃ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : نبی کریم صلی اللہ علیہ وسلم کے دو خطبے ہوتے تھے جن کے درمیان آپ بیٹھتے تھے ۔ آپ قرآن پڑھتے اور لوگوں کو نصیحت اور تذکیر فرماتے ۔","",{"u2":"ابو احوص نے سماک سے اور انھوں نے حضرت جابر بن سمرۃ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:نبی کریم صلی اللہ علیہ وسلم کے دو خطبے ہوتے تھے جن کے درمیان آپ بیٹھتے تھے۔آپ قرآن پڑھتے اور لوگوں کو نصیحت اور تذکیر فرماتے۔"}],[1938,"ابو خثیمہ نے سماک سے روایت کی ، انھوں نے کہا : سیدنا جابر بن سمرۃ رضی اللہ تعالیٰ عنہ نے مجھے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوکر خطبہ دیتے تھے ، پھر بیٹھ جاتے ، پھر کھڑے ہوتے اور کھڑے ہوکر خطبہ دیتے ، اس لئے جس نے تمھیں یہ بتایا کہ آپ بیٹھ کر خطبہ دیتے تھے ، اس نے جھوٹ بولا ۔ اللہ کی قسم! میں نے آپ کے ساتھ دو ہزار سے زائد نمازیں پڑھی ہیں ۔ ( جن میں بہت سے جمعے بھی آئے اور آپ صلی اللہ علیہ وسلم نے تمام خطبے کھڑے ہوکر دیے ۔)","",{"u2":"ابو خثیمہ نے سماک سے روایت کی،انھوں نے کہا:حضرت جابر بن سمرۃ رضی اللہ تعالیٰ عنہ نے مجھے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوکر خطبہ دیتے تھے،پھر بیٹھ جاتے،پھر کھڑے ہوتے اور کھڑے ہوکر خطبہ دیتے،اس لئے جس نے تمھیں یہ بتایا کہ آپ بیٹھ کر خطبہ دیتے تھے،اس نے جھوٹ بولا۔اللہ کی قسم! میں نے آپ کے ساتھ دو ہزار سے زائد نمازیں پڑھی ہیں۔(جن میں بہت سے جمعے بھی آئے اور آپ صلی اللہ علیہ وسلم نے تمام خطبے کھڑے ہوکر دیے۔)"}],[1939,"جریر نے حصین بن عبدالرحمان سے روایت کی ، انھوں نے سالم بن ابی جعد سے اور انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم جمعے کےی دن کھڑے ہوکر خطبہ دے رہے تھے کہ شام سے ایک تجارتی قافلہ آگیا ، لوگوں نے اس کا رخ کرلیا حتیٰ کہ پیچھے بارہ آدمیوں کے سوا کوئی نہ بچا تویہ آیت نازل کی گئی جو سورہ جمعہ میں ہے : \" اور جب وہ تجارت یا کوئی مشغلہ دیکھتے ہیں تو اس کی طرف ٹوٹ پڑتے ہیں اور آپ کو کھڑا چھوڑ جاتے ہیں ۔","",{"u2":"جریر نے حصین بن عبدالرحمان سے روایت کی،انھوں نے سالم بن ابی جعد سے اور انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم جمعے کےی دن کھڑے ہوکر خطبہ دے رہے تھے کہ شام سے ایک تجارتی قافلہ آگیا،لوگوں نے اس کا رخ کرلیا حتیٰ کہ پیچھے بارہ آدمیوں کے سوا کوئی نہ بچا تویہ آیت نازل کی گئی جو سورہ جمعہ میں ہے:\"اور جب وہ تجارت یا کوئی مشغلہ دیکھتے ہیں تو اس کی طرف ٹوٹ پڑتے ہیں اور آپ کو کھڑا چھوڑ جاتے ہیں۔\""}],[1940,"عبداللہ بن ادریس نے حصین سے اسی سند کے ساتھ روایت کی ، کہا : ( جب تجارتی قافلہ آیا تو ) رسول اللہ صلی اللہ علیہ وسلم خطبہ دے رہے تھے ۔ یہ نہیں کہا : کھڑے ہوئے ۔","",{"u2":"عبداللہ بن ادریس نے حصین سے اسی سند کے ساتھ روایت کی،کہا: (جب تجارتی قافلہ آیاتو) رسول اللہ صلی اللہ علیہ وسلم خطبہ دے رہے تھے۔یہ نہیں کہا:کھڑے ہوئے۔"}],[1941,"خالد طحان نے حصین سے روایت کی ، انھوں نے سالم اور ابو سفیان سے اور انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ہم جمعے کے دن رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ ایک چھوٹا سا بازار ( سامان بیچنے والوں کا قافلہ ) آگیا تو لوگ اس کی طرف نکل گئے اور ( صرف ) بارہ آدمیوں کے سوا کوئی نہ بچا ، میں بھی ان میں تھا ، کہا : اس پر اللہ تعالیٰ نے یہ آیت اتاری : \" اور جب وہ تجارت یا کوئی مشغلہ دیکھتے ہیں تو اس کی طرف ٹوٹ پڑتے ہیں اور آ پ کو کھڑا چھوڑ دیتے ہیں \" آیت کے آخر تک ۔","",{"u2":"خالد طحان نے حصین سے روایت کی،انھوں نے سالم اور ابو سفیان سے اور انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:ہم جمعے کے دن رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ ایک چھوٹا سا بازار(سامان بیچنے والوں کا قافلہ) آگیا تو لوگ اس کی طرف نکل گئے اور (صرف) بارہ آدمیوں کے سوا کوئی نہ بچا،میں بھی ان میں تھا،کہا:اس پر اللہ تعالیٰ نے یہ آیت اتاری:\"اور جب وہ تجارت یاکوئی مشغلہ دیکھتے ہیں تو اس کی طرف ٹوٹ پڑتے ہیں اور آ پ کو کھڑا چھوڑ دیتے ہیں\"آیت کے آخر تک۔"}],[1942,"ہشیم نے کہا : ہمیں حصین نے ابو سفیان اور سالم بن ابی جعد سے خبر دی ، انھوں نے سیدنا جابربن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے بیان کیا ، ایک بار جب نبی اکرم صلی اللہ علیہ وسلم جمعے کے دن کھڑے ہوئے ( خطبہ دے رہے ) تھے کہ ایک تجارتی قافلہ مدینہ آگیا ، رسول اللہ صلی اللہ علیہ وسلم کے ساتھی اس کی طرف لپک پڑے حتیٰ کہ آپ کے ساتھ بارہ آدمیوں کے سوا کوئی نہ بچا ۔ ان میں ابو بکر اور عمر رضی اللہ تعالیٰ عنہ بھی موجود تھے ۔ کہا : تو ( اس پر ) یہ آیت اتری : \" اور جب وہ تجارت یا کوئی مشغلہ دیکھتے ہیں تو اس کی طرف ٹوٹ پڑتے ہیں ۔","",{"u2":"ہشیم نے کہا:ہمیں حصین نے ابو سفیان اور سالم بن ابی جعد سے خبر دی،انھوں نے حضرت جابربن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے بیان کیا،ایک بار جب نبی اکرم صلی اللہ علیہ وسلم جمعے کے دن کھڑے ہوئے(خطبہ دے رہے) تھے کہ ایک تجارتی قافلہ مدینہ آگیا،رسول اللہ صلی اللہ علیہ وسلم کے ساتھی اس کی طرف لپک پڑے حتیٰ کہ آپ کے ساتھ بارہ آدمیوں کے سوا کوئی نہ بچا۔ان میں ابو بکر اور عمر رضی اللہ تعالیٰ عنہ بھی موجود تھے۔کہا:تو(اس پر) یہ آیت اتری:\" اور جب وہ تجارت یا کوئی مشغلہ دیکھتے ہیں تو اس کی طرف ٹوٹ پڑتے ہیں۔\""}],[1943,"سیدنا کعب بن عجرہ رضی اللہ تعالیٰ عنہ سے روایت ہے کہ وہ مسجد میں آئے ، دیکھاکہ ( اموی والی ) عبدالرحمان بن ام حکیم بیٹھ کر خطبہ دے رہا ہے ، انھوں نے فرمایا : اس خبیث کودیکھو ، بیٹھ کر خطبہ دے رہا ہے ، جبکہ اللہ تعالیٰ کا فرمان ہے : \" اور جب وہ تجارت یا کوئی مشغلہ دیکھتے ہیں تو ادھر ٹوٹ پڑتے ہیں اور آپ کو کھڑا چھوڑ جاتے ہیں ۔","",{"u2":"حضرت کعب بن عجرہ رضی اللہ تعالیٰ عنہ سے روایت ہے کہ وہ مسجد میں آئے،دیکھاکہ(اموی والی) عبدالرحمان بن ام حکیم بیٹھ کر خطبہ دے رہا ہے،انھوں نے فرمایا:اس خبیث کودیکھو،بیٹھ کر خطبہ دے رہا ہے،جبکہ اللہ تعالیٰ کا فرمان ہے:\"اور جب وہ تجارت یا کوئی مشغلہ دیکھتے ہیں تو ادھر ٹوٹ پڑتے ہیں اور آپ کوکھڑا چھوڑ جاتے ہیں۔\""}],[1944,"حکم بن مینا ء نے حدیث بیان کی کہا : سیدنا عبد اللہ بن عمر اور سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انھیں حدیث بیان کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ اپنے منبر کی لکڑیوں پر ( کھڑے ہو ئے ) فر ما رہے تھے \" لو گوں کے گروہ ہر صورت جمعہ چھوڑ دینے سے باز آجا ئیں یا اللہ تعا لیٰ ان کے دلوں پر مہر لگا دے گا پھر وہ غا فلوں میں سے ہو جا ئیں گے ۔","",{"u2":"حکم بن مینا ء نے حدیث بیان کی کہا: حضرت عبد اللہ بن عمر اور حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ نے انھیں حدیث بیان کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ اپنے منبر کی لکڑیوں پر (کھڑے ہو ئے) فر ما رہے تھے \"لو گوں کے گروہ ہر صورت جمعہ چھوڑ دینے سے باز آجا ئیں یا اللہ تعا لیٰ ان کے دلوں پر مہر لگا دے گا پھر وہ غا فلوں میں سے ہو جا ئیں گے۔"}],[1945,"ابوا حوص نے سما ک بن حرب سے اور انھوں نے سیدنا جا بربن سمرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتا تھا آپ کی نماز ( طوالت میں ) متوسط ہو تی تھی اور آپ کا خطبہ بھی متوسط ہو تا تھا ۔","",{"u2":"ابوا حوص نے سما ک بن حرب سے اور انھوں نے حضرت جا بربن سمرہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا:میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتا تھا آپ کی نماز (طوالت میں)متوسط ہو تی تھی اور آپ کا خطبہ بھی متوسط ہو تا تھا۔"}],[1946,"ابو بکر بن ابی شیبہ اور ابن نمیر نے کہا : ہمیں محمد بن بشر نے حدیث بیان کی ، ہمیں زکریا نے حدیث بیان کی کہا : مجھ سے سماک بن حرب نے سیدنا جا بر بن سمرہ رضی اللہ تعالیٰ عنہ سے حدیث بیان کی ، انھوں نے کہا : میں نماز یں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ پڑھتا تھا تو آپ کی نماز در میانی ہو تی تھی اور آپ کا خطبہ بھی درمیانہ ہو تا تھا ابو بکر بن ابی شیبہ کی روا یت میں ( زکریا نے کہا : ( حدثني سماك بن حرب ) \" مجھے سماک بن حرب نے حدیث بیان کی \" کے بجائے ) زكريا نے مجھے سماک سے روایت کی \" کے الفا ظ ہیں ۔","",{"u2":"ابو بکر بن ابی شیبہ اور ابن نمیر نے کہا: ہمیں محمد بن بشر نے حدیث بیان کی، ہمیں زکریا نے حدیث بیان کی کہا: مجھ سے سماک بن حرب نے حضرت جا بر بن سمرہ رضی اللہ تعالیٰ عنہ سے حدیث بیان کی، انھوں نے کہا:میں نماز یں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ پڑھتا تھا تو آپ کی نماز در میانی ہو تی تھی اور آپ کا خطبہ بھی درمیانہ ہو تا تھا ابو بکر بن ابی شیبہ کی روا یت میں (زکریا نے کہا: (حدثنی سماک بن حرب)\" مجھے سماک بن حرب نے حدیث بیان کی\"کے بجائے)زکریا نےمجھے سماک سے روایت کی\" کے الفا ظ ہیں۔"}],[1947,"عبد الوہاب بن عبد المجید ( ثقفی ) نے جعفر ( صادق ) بن محمد ( باقر ) سے روایت کی انھوں نے اپنے والد سے اور انھوں نے سیدنا جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب خطبہ دیتے تو آپ کی آنکھیں سرخ ہو جا تیں ، آواز بلند ہو جا تی اور جلال کی کیفیت طاری ہو جا تی تھی حتیٰ کہ ایسا لگتا جیسے آپ کسی لشکر سے ڈرا رہے ہیں فر ما رہے ہیں کہ وہ ( لشکر ) صبح یا شام ( تک ) تمھیں آلے گا اور فر ما تے \" میں اور قیامت اس طرح بھیجے گئے ہیں \" اور آپ اپنی انگشت شہادت اور درمیانی انگلی کو ملا کر دکھا تے اور فر ما تے ۔ \" ( حمدو صلاۃ ) کے بعد بلا شبہ بہترین حدیث ( کلام ) اللہ کی کتاب ہے اور زندگی کا بہترین طریقہ محمد صلی اللہ علیہ وسلم کا طریقہ زندگی ہے اور ( دین میں ) بد ترین کا وہ ہیں جو خود نکا لے گئے ہوں اور ہر نیا نکا لا ہوا کا م گمراہی ہے پھر فر ما تے : \" میں ہر مو من کے ساتھ خود اس کی نسبت زیادہ محبت اور شفقت رکھنے والا ہوں جو کو ئی ( مومن اپنے بعد ) مال چھوڑ گیا تو وہ اس کے اہل و عیال ( وارثوں ) کا ہے اور جو مومن قرض یا بے سہارا اہل و عیال چھوڑ گیا تو ( اس قرض کو ) میری طرف لو ٹا یا جا ئے ( اور اس کے کنبے کی پرورش ) میرے ذمے ہے ۔","",{"u2":"عبد الوہاب بن عبد المجید (ثقفی) نے جعفر (صادق) بن محمد (باقر)سے روایت کی انھوں نے اپنے والد سے اور انھوں نے حضرت جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب خطبہ دیتے تو آپ کی آنکھیں سرخ ہو جا تیں،آواز بلند ہو جا تی اور جلال کی کیفیت طاری ہو جا تی تھی حتیٰ کہ ایسا لگتا جیسے آپ کسی لشکر سے ڈرا رہے ہیں فر ما رہے ہیں کہ وہ (لشکر) صبح یا شام (تک) تمھیں آلے گا اور فر ما تے \"میں اور قیامت اس طرح بھیجے گئے ہیں \"اور آپ اپنی انگشت شہادت اور درمیانی انگلی کو ملا کر دکھا تے اور فر ما تے۔\"(حمدو صلاۃ) کے بعد بلا شبہ بہترین حدیث (کلام)اللہ کی کتاب ہے اور زندگی کا بہترین طریقہ محمد صلی اللہ علیہ وسلم کا طریقہ زندگی ہے اور (دین میں) بد ترین کا وہ ہیں جو خود نکا لے گئے ہوں اور ہر نیا نکا لا ہوا کا م گمراہی ہے پھر فر ما تے:\"میں ہر مو من کے ساتھ خود اس کی نسبت زیادہ محبت اور شفقت رکھنے والا ہوں جو کو ئی (مومن اپنے بعد)مال چھوڑ گیا تو وہ اس کے اہل و عیال (وارثوں) کا ہے اور جو مومن قرض یا بے سہارا اہل و عیال چھوڑ گیا تو(اس قرض کو) میری طرف لو ٹا یا جا ئے (اور اس کے کنبے کی پرورش) میرے ذمے ہے۔"}],[1948,"سلیمان بن بلال نے کہا : مجھ سے جعفر بن محمد نے اپنے نے اپنے والد سے روایت کی انھوں نے کہا : میں نے سیدنا جا بر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے سنا وہ کہتے تھے جمعے کے دن نبی اکرم صلی اللہ علیہ وسلم کا خطبہ اس طرح ہوتا تھاکہ آپ اللہ تعا لیٰ کی حمد و ثناء بیان کرتے پھر اس کے بعد آپ ( اپنی بات ارشاد فر ما تے اور آپ کی اواز بہت بلند ہو تی ۔ ۔ ۔ پھر اس ( سابقہ حدیث ) کے مانند حدیث بیان کی ۔","",{"u2":"سلیمان بن بلال نے کہا: مجھ سے جعفر بن محمد نے اپنے نے اپنے والد سے روایت کی انھوں نے کہا: میں نے حضرت جا بر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے سنا وہ کہتے تھے جمعے کے دن نبی اکرم صلی اللہ علیہ وسلم کا خطبہ اس طرح ہوتا تھاکہ آپ اللہ تعا لیٰ کی حمد و ثناء بیان کرتے پھر اس کے بعد آپ (اپنی بات ارشاد فر ما تے اور آپ کی اواز بہت بلند ہو تی۔۔۔پھر اس (سابقہ حدیث) کے مانند حدیث بیان کی۔"}],[1949,"سفیان نے جعفر سے انھوں نے اپنے والد ( محمد باقر ) سے اور انھوں نے سیدنا جا بر رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم لو گوں کو ( اس طرح ) خطبہ دیتے پہلے اللہ کی شان کے مطابق اس کی حمد و ثنا ء بیان کرتے پھر فر ما تے ۔ \" جسے اللہ سیدھی راہ پر چلا ئے اسے کو ئی گمراہ نہیں کر سکتا اور جسے وہ سیدھی راہ سے ہٹا دے اسے کو ئی ہدایت نہیں دے سکتا اور بہترین بات ( حدیث ) اللہ کی کتاب ہے ۔ ۔ ۔ \" آگے ( عبد الوہاب بن عبد المجید ) ثقفی کی حدیث ( 2005 ) کے ما نند ہے ۔","",{"u2":"سفیان نے جعفر سے انھوں نے اپنے والد (محمد باقر)سے اور انھوں نے حضرت جا بر رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم لو گوں کو (اس طرح) خطبہ دیتے پہلے اللہ کی شان کے مطابق اس کی حمد و ثنا ء بیان کرتے پھر فر ما تے۔\"جسے اللہ سیدھی راہ پر چلا ئے اسے کو ئی گمراہ نہیں کر سکتا اور جسے وہ سیدھی راہ سے ہٹا دے اسے کو ئی ہدایت نہیں دے سکتا اور بہترین بات (حدیث) اللہ کی کتاب ہے۔۔۔\"آگے (عبد الوہاب بن عبد المجید) ثقفی کی حدیث (2005)کے ما نند ہے۔"}],[1950,"سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت ہے کہ ضمادمکہ آیا ، وہ ( قبیلہ ) از دشنوء سے تھا اور آسیب کا دم کیا کرتا تھا ( جسے لوگ ریح کہتے تھے ، یعنی ایسی ہوا جو نظرنہیں آتی ، اثر کرتی ہے ) اس نے مکہ کے بے وقوفوں کو یہ کہتے سنا کہ محمد ( صلی اللہ علیہ وسلم ) کو جنون ہوگیا ہے ( نعوذ باللہ ) اس نے کہا : اگر میں اس آدمی کو دیکھ لوں تو شاید اللہ تعالیٰ اسے میرے ہاتھوں شفا بخش دے ۔ کہا : وہ آپ سے ملا اور کہنے لگا : اے محمد صلی اللہ علیہ وسلم !میں اس نظر نہ آنے والی بیماری ( ریح ) کو زائل کرنے کے لئے دم کرتا ہوں اور اللہ تعالیٰ جسے چاہتا ہے میرے ہاتھوں شفا بخشتا ہے تو آپ کیا چاہتے ہیں ( کہ میں دم کروں؟ ) رسول اللہ صلی اللہ علیہ وسلم نے ( جواب میں ) کہا : \" ان الحمد لله نحمده ونستعينه من يهده الله فلا مضل له ومن يضلل فلا هادي له واشهد ان لا اله الا اللہ وحده لا شريك له وان محمدا عبده ورسوله اما بعد \" یقیناً تمام حمد اللہ کے لیے ہے ، ہم اسی کی حمد کرتے ہیں اور اسی سے مدد مانگتے ہیں ، جس کو اللہ سیدھی راہ پرچلائے ، اسے کوئی گمراہ نہیں کرسکتا اور جسے وہ گمراہ چھوڑ دے ، اسے کوئی راہ راست پر نہیں لاسکتا اور میں گواہی دیتا ہوں کہ اللہ کے سواکوئی سچا معبود نہیں ، وہی اکیلا ( معبود ) ہے ، ا س کا کوئی شریک نہیں اور بلاشبہ محمد ( صلی اللہ علیہ وسلم ) اس کا بندہ اور اس کا رسول ہے ، اس کے بعد! \" کہا : وہ بول اٹھا : اپنے یہ کلمات مجھے دوبارہ سنائیں ۔ رسول اللہ صلی اللہ علیہ وسلم نے تین مرتبہ یہ کلمات اس کے سامنے دہرائے ۔ اس پر اس نے کہا : میں نے کاہنوں ، جادوگروں اور شاعروں ( سب ) کے قول سنے ہیں ، میں نے آپ کے ان کلمات جیسا کوئی کلمہ ( کبھی ) نہیں سنا ، یہ تو بحر ( بلاغت ) کہ تہ تک پہنچ گئے ہیں اور کہنے لگا : ہاتھ بڑھایئے!میں آپ کے ساتھ اسلام پر بیعت کرتا ہوں ۔ کہا : تو اس نے آپ کی بیعت کرلی ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اور تیری ( طرف سے تیری ) قوم ( کے اسلام ) پر بھی ( تیری بیعت لیتا ہوں ) \" اس نے کہا : اپنی قوم ( کے اسلام ) پر بھی ( بیعت کرتاہوں ) اس کے بعد آپ نے ایک سریہ ( چھوٹا لشکر ) بھیجا ، وہ ان کی قوم کے پاس سے گزرے تو امیر لشکر نے لشکر سے پوچھا : کیا تم نے ان لوگوں سے کوئی چیز لی ہے؟تو لوگوں میں سے ایک شخص نے کہا : میں نے ان سے ایک لوٹا لیا ہے اس نے کہا : اسے واپس کردو کیونکہ یہ ( کوئی اور نہیں بلکہ ) ضماد رضی اللہ تعالیٰ عنہ کی قوم ہے ۔","",{"u2":"حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت ہے کہ ضمادمکہ آیا،وہ (قبیلہ) از دشنوء سے تھا اور آسیب کا دم کیا کرتا تھا(جسے لوگ ریح کہتے تھے،یعنی ایسی ہوا جو نظرنہیں آتی،اثر کرتی ہے) اس نے مکہ کے بے وقوفوں کو یہ کہتے سنا کہ محمد (صلی اللہ علیہ وسلم) کو جنون ہوگیا ہے(نعوذ باللہ) اس نے کہا: اگر میں اس آدمی کو دیکھ لوں تو شاید اللہ تعالیٰ اسے میرے ہاتھوں شفا بخش دے۔کہا:وہ آپ سے ملا اور کہنے لگا:اے محمد صلی اللہ علیہ وسلم!میں اس نظر نہ آنے والی بیماری(ریح) کو زائل کرنے کے لئے دم کرتا ہوں اور اللہ تعالیٰ جسے چاہتا ہے میرے ہاتھوں شفا بخشتا ہے تو آپ کیا چاہتے ہیں(کہ میں دم کروں؟)رسول اللہ صلی اللہ علیہ وسلم نے (جواب میں) کہا:\"ان الحمد للہ نحمدہ ونستعینہ من یہدہ اللہ فلا مضل لہ ومن یضلل فلا ہادی لہ واشہد ان لا الہ الا اللہ وحدہ لا شریک لہ وان محمدا عبدہ ورسولہ اما بعد\"یقیناً تمام حمد اللہ کے لیے ہے،ہم اسی کی حمد کرتے ہیں اور اسی سے مدد مانگتے ہیں،جس کو اللہ سیدھی راہ پرچلائے،اسے کوئی گمراہ نہیں کرسکتا اور جسے وہ گمراہ چھوڑ دے،اسے کوئی راہ راست پر نہیں لاسکتا اور میں گواہی دیتا ہوں کہ اللہ کے سواکوئی سچا معبود نہیں،وہی اکیلا(معبود) ہے،ا س کا کوئی شریک نہیں اور بلاشبہ محمد(صلی اللہ علیہ وسلم) اس کا بندہ اور اس کا رسول ہے،اس کے بعد!\"کہا: وہ بول اٹھا:اپنے یہ کلمات مجھے دوبارہ سنائیں۔رسول اللہ صلی اللہ علیہ وسلم نے تین مرتبہ یہ کلمات اس کے سامنے دہرائے۔اس پر اس نے کہا: میں نے کاہنوں،جادوگروں اور شاعروں(سب) کے قول سنے ہیں،میں نے آپ کے ان کلمات جیسا کوئی کلمہ(کبھی) نہیں سنا،یہ تو بحر(بلاغت) کہ تہ تک پہنچ گئے ہیں اور کہنے لگا:ہاتھ بڑھایئے!میں آپ کے ساتھ اسلام پر بیعت کرتا ہوں۔کہا:تو اس نے آپ کی بیعت کرلی۔رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اور تیری (طرف سے تیری) قوم(کے اسلام) پر بھی (تیری بیعت لیتاہوں)\"اس نے کہا: اپنی قوم(کے اسلام) پر بھی(بیعت کرتاہوں) اس کے بعد آپ نے ایک سریہ(چھوٹا لشکر) بھیجا،وہ ان کی قوم کے پاس سے گزرے تو امیر لشکر نے لشکر سے پوچھا:کیا تم نے ان لوگوں سے کوئی چیز لی ہے؟تو لوگوں میں سے ایک شخص نے کہا:میں نے ان سے ایک لوٹا لیا ہے اس نے کہا:اسے واپس کردو کیونکہ یہ(کوئی اور نہیں بلکہ)ضماد رضی اللہ تعالیٰ عنہ کی قوم ہے۔"}],[1951,"ابو وائل نے کہا : ہمارے سامنے سیدنا عمار رضی اللہ تعالیٰ عنہ نے خطبہ دیا ۔ انتہائی مختصر اور انتہائی بلیغ ( بات کی ) جب وہ منبر سے اترے تو ہم نے کہا : ابویقظان! آپ نے انتہائی پر تاثیر اور انتہائی مختصر خطبہ دیا ہے ، کاش! آپ سانس کچھ لمبی کرلیتے ( زیادہ دیر بات کرلیتے ) انھوں نے فرمایا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے : \" انسان کی نماز کا طویل ہونا اوراس کے خطبے کا چھوٹا ہونا اس کی سمجھداری کی علامت ہے ، اس لئے نماز لمبی کرو اور خطبہ چھوٹا دو ، اوراس میں کوئی شبہ نہیں کہ کوئی بیان جادو ( کی طرح ) ہوتا ہے ۔","",{"u2":"ابو وائل نے کہا:ہمارے سامنے حضرت عمار رضی اللہ تعالیٰ عنہ نے خطبہ دیا۔انتہائی مختصر اورانتہائی بلیغ(بات کی) جب وہ منبر سے اترے تو ہم نے کہا:ابویقظان! آپ نے انتہائی پر تاثیر اور انتہائی مختصر خطبہ دیاہے،کاش! آپ سانس کچھ لمبی کرلیتے(زیادہ دیر بات کرلیتے) انھوں نے فرمایا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے:\"انسان کی نماز کا طویل ہونا اوراس کے خطبے کاچھوٹا ہونا اس کی سمجھداری کی علامت ہے،اس لئے نماز لمبی کرو اور خطبہ چھوٹا دو،اوراس میں کوئی شبہ نہیں کہ کوئی بیان جادو(کی طرح) ہوتا ہے۔\""}],[1952,"ابو بکر بن ابی شیبہ اور محمد بن عبداللہ بن نمیر نے کہا : ہمیں وکیع نے سفیان سے حدیث بیان کی ، انھوں نے عبدالعزیز بن رفیع سے ، انھوں نے تمیم بن طرفہ سے اور انھوں نے سیدنا عدی بن حاتم رضی اللہ تعالیٰ عنہ سے روایت کی کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے خطبہ دیا اور ( اس میں ) کہا : جو اللہ اور اس کے رسول کی اطاعت کرتاہے اس نے رشدوہدایت پالی اور جو ان دونوں کی نافرمانی کرتاہے وہ بھٹک گیا ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" تو بُرا خطیب ہے ، ( فقرے کے پہلے حصے کی طرح ) یوں کہو ، جس نے اللہ کی اور اس کے رسول کی نافرمانی کی ( وہ گمراہ ہوا ۔ ) \"\" ابن نمیر کی ر وایت میں غوي ( واہ کے نیچے زیر ) ہے ۔","",{"u2":"ابو بکر بن ابی شیبہ اور محمد بن عبداللہ بن نمیر نے کہا:ہمیں وکیع نے سفیان سے حدیث بیان کی،انھوں نے عبدالعزیز بن رفیع سے،انھوں نے تمیم بن طرفہ سے اور انھوں نے حضرت عدی بن حاتم رضی اللہ تعالیٰ عنہ سے روایت کی کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے خطبہ دیا اور(اس میں) کہا:جو اللہ اور اس کے رسو ل کی اطاعت کرتاہے اس نے رشدوہدایت پالی اور جو ان دونوں کی نافرمانی کرتاہے وہ بھٹک گیا۔اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تو بُرا خطیب ہے،(فقرے کے پہلے حصے کی طرح) یوں کہو،جس نے اللہ کی اور اس کے ر سول کی نافرمانی کی(وہ گمراہ ہوا۔)\"\nابن نمیر کی ر وایت میں غوی(واہ کے نیچے زیر) ہے۔"}],[1953,"صفوان کے والد سیدنا یعلیٰ بن امیہ رضی اللہ تعالیٰ عنہ سے روایت ہے کہ انھوں نے نبی کریم صلی اللہ علیہ وسلم سے سنا ، آپ منبر پر پڑھ رہے تھے : «وَنَادَوْا يَا مَالِكُ» \" اور وہ پکاریں گے : اے مالک! \" ( الزخرف 77 :)","",{"u2":"صفوان کے والد حضرت یعلیٰ بن امیہ رضی اللہ تعالیٰ عنہ سے روایت ہے کہ انھوں نے نبی کریم صلی اللہ علیہ وسلم سے سنا،آپ منبر پر پڑھ رہے تھے:وَنَادَوْا یَا مَالِکُ\"اور وہ پکاریں گے:اے مالک!\"(الزخرف 77:43)"}],[1954,"سلیمان بن بلال نے یحییٰ بن سعید سے روایت کی ، انھوں نے عمرہ بنت عبدالرحمان ( بن سعد بن زرارہ انصاریہ ) سے ، انھوں نے کہا : ( ماں کی طرف سے ) اپنی بہن کی طرف سے روایت کی ، انھوں نے کہا : میں نے سورہ ق ۚ وَالْقُرْ‌آنِ الْمَجِيدِ جمعے کے دن رسول اللہ صلی اللہ علیہ وسلم کی زبان مبارک سے سن کریاد کی ۔ آپ اسے ہر جمعے منبر پر پڑھ کر سنایا ( اور سمجھایا ) کرتے تھے ۔","",{"u2":"سلیمان بن بلال نے یحییٰ بن سعید سے روایت کی،انھوں نے عمرہ بنت عبدالرحمان(بن سعد بن زرارہ انصاریہ) سے،انھوں نے کہا: (ماں کی طرف سے) اپنی بہن کی طرف سے روایت کی،انھوں نے کہا:میں نے سورہ ق ۚ وَالْقُرْ‌آنِ الْمَجِیدِ جمعے کے دن رسول اللہ صلی اللہ علیہ وسلم کی زبان مبارک سے سن کریاد کی۔آپ اسے ہر جمعے منبر پر پڑھ کر سنایا(اور سمجھایا) کرتے تھے۔"}],[1955,"یحییٰ بن ایوب نے یحییٰ بن سعید سے ، انھوں نے عمرہ سے اور انھوں نے اپنی بہن سے جو عمر میں ان سے بڑی تھیں ، روایت کی ۔ ۔ ۔ سلیمان بن بلال کی حدیث کے مانند ۔","",{"u2":"یحییٰ بن ایوب نے یحییٰ بن سعید سے،انھوں نے عمرہ سے اور انھوں نے اپنی بہن سے جو عمر میں ان سے بڑی تھیں،روایت کی۔۔۔سلیمان بن بلال کی حدیث کے مانند۔"}],[1956,"عبداللہ بن محمد بن معن نے حارثہ بن نعمان کی بیٹی ( ام ہشام ) سے روایت کی ، انھوں نے کہا : میں نے سورہ ق ( کسی اور سے نہیں براہ راست ) رسول اللہ صلی اللہ علیہ وسلم کی زبان سے سن کر یاد کی ، آپ ہر جمعے میں اسے پڑھ کر خطاب فرماتے تھے ۔ انھوں نے کہا : ہمارا اور رسول اللہ صلی اللہ علیہ وسلم کا تندور ایک ہی تھا ۔","",{"u2":"عبداللہ بن محمد بن معن نے حارثہ بن نعمان کی بیٹی(ام ہشام) سے روایت کی،انھوں نے کہا:میں نے سورہ ق(کسی اور سے نہیں براہ راست) رسول اللہ صلی اللہ علیہ وسلم کی زبان سے سن کر یاد کی،آپ ہر جمعے میں اسےپڑھ کر خطاب فرماتے تھے۔انھوں نے کہا:ہمارا اور رسول اللہ صلی اللہ علیہ وسلم کا تندور ایک ہی تھا۔"}],[1957,"یحییٰ بن عبداللہ بن عبدالرحمان بن سعد نے زرارہ نے ام ہشام بنت حارثہ بن نعمان رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ہمارا اور رسول اللہ صلی اللہ علیہ وسلم کا تندور دو یا ایک سال سے کچھ زیادہ عرصہ ایک ہی رہا اور میں نے سورہ ق ۚ وَالْقُرْ‌آنِ الْمَجِيدِ ( کسی اور سے نہیں بلکہ ) رسول اللہ صلی اللہ علیہ وسلم کی زبان سے سن کر یاد کی ، آپ ہر جمعے کے دن جب لوگوں کو خطبہ دیتے تو اسے منبر پر پڑھتے تھے ۔","",{"u2":"یحییٰ بن عبداللہ بن عبدالرحمان بن سعد نے زرارہ نے ام ہشام بنت حارثہ بن نعمان رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:ہمارا اور رسول اللہ صلی اللہ علیہ وسلم کا تندور دو یا ایک سال سے کچھ زیادہ عرصہ ایک ہی رہا اور میں نے سورہ ق ۚ وَالْقُرْ‌آنِ الْمَجِیدِ (کسی اور سے نہیں بلکہ) رسول اللہ صلی اللہ علیہ وسلم کی زبان سے سن کر یاد کی،آپ ہر جمعے کے دن جب لوگوں کو خطبہ دیتے تو اسے منبر پر پڑھتے تھے۔"}],[1958,"عبداللہ بن ادریس نے حصین سے اور انھوں نے سیدنا عمارہ بن رویبہ ( ثقفی ) رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : انھوں نے بشر بن مروان ( بن حکم ، عامل مدینہ ) کو منبر پر ( تقریر کے دوران ) دونوں ہاتھ بلند کرتے دیکھا تو کہا : اللہ تعالیٰ ان دونوں ہاتھوں کو بگاڑے ، میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ اپنے ہاتھ سے اس سےزیادہ اشارہ نہیں کرتے تھے اور اپنی انگشت شہادت سے اشارہ کیا ۔","",{"u2":"عبداللہ بن ادریس نے حصین سے اور انھوں نے حضرت عمارہ بن رویبہ(ثقفی) رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:انھوں نے بشر بن مروان(بن حکم،عامل مدینہ) کو منبر پر(تقریر کے دوران) دونوں ہاتھ بلند کرتے دیکھا تو کہا:اللہ تعالیٰ ان دونوں ہاتھوں کو بگاڑے،میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ اپنے ہاتھ سے اس سےزیادہ اشارہ نہیں کرتے تھے اور اپنی انگشت شہادت سے اشارہ کیا۔"}],[1959,"ابو عوانہ نے حصین بن عبدالرحمان سے روایت کی ، انھوں نے کہا : میں نے جمعے کے دن بشر بن مروان کو دونوں ہاتھ اٹھاتے ہوئے دیکھا تو اس پر عمارہ بن رویبہ رضی اللہ تعالیٰ عنہ نے کہا ۔ ۔ ۔ اس کے بعد اس ( مذکورہ بالا روایت ) کے ہم معنی روایت بیان کی ۔","",{"u2":"ابو عوانہ نے حصین بن عبدالرحمان سے روایت کی،انھوں نے کہا:میں نے جمعے کے دن بشر بن مروان کو دونوں ہاتھ اٹھاتے ہوئے دیکھا تو اس پر عمارہ بن رویبہ رضی اللہ تعالیٰ عنہ نے کہا۔۔۔اس کے بعد اس (مذکورہ بالا روایت) کے ہم معنی روایت بیان کی۔"}],[1960,"حماد بن زید نے عمرو بن دینار سے اور انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : اسی اثناء میں جب جمعے کے دن رسول اللہ صلی اللہ علیہ وسلم خطبہ دے رہے تھے ایک آدمی ( مسجد میں ) آیا تو نبی کریم صلی اللہ علیہ وسلم نے اس سے پوچھا : \" اے فلاں ( نام لیا ) !کیا تو نے نماز پڑھ لی ہے؟ \" اس نے کہا : نہیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اور اٹھو اور نماز پڑھو ۔","",{"u2":"حماد بن زید نے عمرو بن دینار سے اور انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:اسی اثناء میں جب جمعے کے دن رسول اللہ صلی اللہ علیہ وسلم خطبہ دے رہے تھے ایک آدمی (مسجد میں) آیا تو نبی کریم صلی اللہ علیہ وسلم نے اس سے پوچھا:\"اے فلاں(نام لیا)!کیا تو نے نماز پڑھ لی ہے؟\"اس نے کہا: نہیں۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"اور اٹھو اور نماز پڑھو۔\""}],[1961,"ایوب نے عمرو ( بن دینار ) سے ، انھوں نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے حماد کی طرح روایت کی ، اور انھوں ( ایوب ) نے بھی اس میں دو رکعت کا ذکر نہیں کیا ( البتہ اگلی روایت میں سفیان نے کیا ہے ۔)","",{"u2":"ایوب نے عمرو(بن دینار) سے،انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے حماد کی طرح روایت کی،اور انھوں(ایوب) نے بھی اس میں دو رکعت کا ذکر نہیں کیا (البتہ اگلی روایت میں سفیان نے کیا ہے۔)"}],[1962,"قتیبہ بن سعید اور اسحاق بن ابراہیم میں سے قتیبہ نے کہا : ہمیں حدیث سنائی اور اسحاق نے کہا : ہمیں خبر دی سفیان نے عمرو سے ، انھوں نے جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سےسنا ، وہ کہہ رہے تھے : ایک آدمی مسجد میں داخل ہوا جب رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن خطبہ دےرہے تھے ۔ تو آپ نے پوچھا : \" کیا تم نے نماز پڑھ لی؟ \" اس نے کہا : نہیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اٹھو اور دو رکعتیں پڑھ لو ۔ \" قتیبہ کی حدیث میں ( فصل ركعتين کے بجائے ) صل ركعتين ( دو رکعتیں پڑھو ) ہے ۔","",{"u2":"قتیبہ بن سعید اور اسحاق بن ابراہیم میں سے قتیبہ نے کہا:ہمیں حدیث سنائی اور اسحاق نے کہا:ہمیں خبر دی سفیان نے عمرو سے،انھوں نے جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سےسنا،وہ کہہ رہے تھے:ایک آدمی مسجد میں داخل ہوا جب رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن خطبہ دےرہے تھے۔ تو آپ نے پوچھا:\"کیا تم نے نماز پڑھ لی؟\"اس نے کہا:نہیں۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"اٹھو اور دو رکعتیں پڑھ لو۔\"قتیبہ کی حدیث میں (فصل رکعتین کے بجائے) صل رکعتین (دو رکعتیں پڑھو)ہے۔"}],[1963,"ابن جریج نے کہا : ہمیں عمرو بن دینار نے خبر دی کہ انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے سنا ، وہ کہہ رہے تھے : ایک آدمی آیا جب کہ نبی اکرم صلی اللہ علیہ وسلم منبر پر تھے ، جمعے کے دن خطبہ ارشاد فرمارہے تھے تو آپ نے اس سے پوچھا : \" کیا تم نے دو رکعتیں پڑھ لی ہیں؟ \" اس نے کہا : نہیں ۔ آپ نے فرمایا : \" پڑھ لو ۔","",{"u2":"ابن جریج نے کہا:ہمیں عمرو بن دینار نے خبر دی کہ انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے سنا،وہ کہہ رہے تھے:ایک آدمی آیا جب کہ نبی اکرم صلی اللہ علیہ وسلم منبر پر تھے،جمعے کے دن خطبہ ارشاد فرمارہے تھے تو آپ نے اس سے پوچھا:\"کیا تم نے دو رکعتیں پڑھ لی ہیں؟\" اس نے کہا:نہیں۔آپ نے فرمایا:\"پڑھ لو۔\""}],[1964,"شعبہ نے عمرو ( بن دینار ) سے روایت کی ، انھوں نے کہا : میں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے سنا کہ نبی اکرم صلی اللہ علیہ وسلم نے خطبے میں فرمایا : \" جب تم میں سے کوئی شخص جمعے کے دن آئے جبکہ امام ( گھر سے ) نکل ( کر ) آچکا ہے تو وہ دو رکعت پڑھ لے ۔","",{"u2":"شعبہ نے عمرو(بن دینار) سے روایت کی،انھوں نے کہا:میں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے سنا کہ نبی اکرم صلی اللہ علیہ وسلم نے خطبے میں فرمایا:\"جب تم میں سے کوئی شخص جمعے کے دن آئے جبکہ امام(گھر سے) نکل (کر) آچکا ہے تو وہ دو رکعت پڑھ لے۔\""}],[1965,"ابو زبیر نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی کہ سلیک غطفانی رضی اللہ تعالیٰ عنہ جمعے کے دن آئے جبکہ رسول اللہ صلی اللہ علیہ وسلم منبر پر بیٹھے ہوئے تھے تو سلیک نماز پڑھنے سے پہلے ہی بیٹھ گئے ۔ رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا : \" کیا تم نے دو رکعتیں پڑھ لی ہیں؟ \" انھوں نے کہا : نہیں ۔ آپ نے فرمایا : \" اٹھو اور دو ر کعتیں پڑھو ۔","",{"u2":"ابو زبیر نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی کہ سلیک غطفانی رضی اللہ تعالیٰ عنہ جمعے کے دن آئے جبکہ رسول اللہ صلی اللہ علیہ وسلم منبر پر بیٹھے ہوئے تھے تو سلیک نماز پڑھنے سے پہلے ہی بیٹھ گئے۔رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا:\"کیا تم نے دو رکعتیں پڑھ لی ہیں؟\" انھوں نے کہا: نہیں۔آپ نے فرمایا:\"اٹھو اور دو ر کعتیں پڑھو۔\""}],[1966,"ابو سفیان ( طلحہ بن نافع واسطی ) نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نےکہا : سلیک غطفانی رضی اللہ تعالیٰ عنہ جمعے کے دن ( اس وقت ) آئے جب رسول اللہ صلی اللہ علیہ وسلم خطبہ دے رہے تھے تو وہ بیٹھ گئے ۔ آپ نے ان سے کہا : \" اے سلیک!ا ٹھ کر دو رکعتیں پڑھو اور ان میں سے اختصار برتو ۔ \" اس کے بعد آپ صلی اللہ علیہ وسلم نے فرمایا! \" جب تم میں سے کوئی جمعے کےدن آئے جبکہ امام خطبہ دے رہا ہو تو وہ دو رکعتیں پڑھے اور ان میں اختصار کرے ۔","",{"u2":"ابو سفیان(طلحہ بن نافع واسطی) نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نےکہا:سلیک غطفانی رضی اللہ تعالیٰ عنہ جمعے کے دن(اس وقت) آئے جب رسول اللہ صلی اللہ علیہ وسلم خطبہ دے رہے تھے تو وہ بیٹھ گئے۔آپ نے ان سے کہا:\"اے سلیک!ا ٹھ کر دو رکعتیں پڑھو اور ان میں سے اختصار برتو۔\"اس کے بعد آپ صلی اللہ علیہ وسلم نے فرمایا!\"جب تم میں سے کوئی جمعے کےدن آئے جبکہ امام خطبہ دے رہا ہو تو وہ دو رکعتیں پڑھے اور ان میں اختصار کرے۔\""}],[1967,"سیدنا ابو رفاعہ ( تمیم بن اُسید عدوی رضی اللہ تعالیٰ عنہ ) نے کہا کہ میں نبی صلی اللہ علیہ وسلم کے پاس ( اس وقت ) پہنچا جبکہ آپ خطبہ دے رہے تھے ، میں نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم !ایک پردیسی آدمی ہے اپنے دین کے بارے میں پوچھنے آیا ہے اسے معلوم نہیں کہ ا س کادین کیا ہے کہا : تو رسول اللہ صلی اللہ علیہ وسلم میری طرف متوجہ ہوئے اور اپنا خطبہ چھوڑا ، یہاں تک کہ میرے پاس پہنچ گئے ۔ ایک کرسی لائی گئی میرے خیال میں اس کے پائے لوہے کے تھے ، کہا : تو رسول اللہ صلی اللہ علیہ وسلم اس پر بیٹھ گئے اور اللہ تعالیٰ نے جو کچھ آپ کو سکھایا تھا اس میں سے مجھے سکھانے لگے پھر اپنے خطبے کے لئے بڑھے اور اس کا آخری حصہ مکمل فرمایا ۔","",{"u2":"حضرت ابو رفاعہ(تمیم بن اُسید عدوی رضی اللہ تعالیٰ عنہ) نے کہا کہ میں نبی صلی اللہ علیہ وسلم کے پاس(اس وقت) پہنچا جبکہ آپ خطبہ دے رہے تھے،میں نے عرض کی:اے اللہ کے رسول صلی اللہ علیہ وسلم!ایک پردیسی آدمی ہے اپنے دین کے بارے میں پوچھنے آیا ہے اسے معلوم نہیں کہ ا س کادین کیا ہے کہا:تو رسول اللہ صلی اللہ علیہ وسلم میری طرف متوجہ ہوئے اور اپنا خطبہ چھوڑا،یہاں تک کہ میرے پاس پہنچ گئے۔ایک کرسی لائی گئی میرے خیال میں اس کے پائے لوہے کے تھے،کہا:تو رسول اللہ صلی اللہ علیہ وسلم اس پر بیٹھ گئے اور اللہ تعالیٰ نے جو کچھ آپ کو سکھایا تھا اس میں سے مجھے سکھانے لگے پھر اپنے خطبے کے لئے بڑھے اور اس کا آخری حصہ مکمل فرمایا۔"}],[1968,"سلیمان جو ہلال ( تمیمی ) کے بیٹے ہیں ، انھوں نے جعفر ( صادق ) سے ، انھوں نے اپنے والد سے اور انھوں نے ابو رافع ( مولیٰ رسول اللہ صلی اللہ علیہ وسلم کے بیٹے عبیداللہ ) سے ر وایت کی ، انھوں نے کہا : مروان نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ کو مدینہ میں اپنا جانشین مقرر کیا اور خود مکہ چلا گیا ۔ سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے ہمیں جمعے کی نماز پڑھائی اور ( پہلی رکعت میں ) سورہ جمعہ پڑھنے کے بعد دوسری رکعت میں «إِذَا جَاءَكَ الْمُنَافِقُونَ» پڑھی اور کہا : جب ابو ہریرۃ رضی اللہ تعالیٰ عنہ جمعے کی نماز سے فارغ ہوئے تو میں ان کے پاس جاپہنچا اور ان سے کہا : آپ نے وہ دو سورتیں پڑھی ہیں جو علی ابن طالب رضی اللہ تعالیٰ عنہ کوفہ میں پڑھا کرتے تھے ۔ ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو جمعے کے دن یہ سورتیں پڑھتے ہوئے سنا ہے ۔","",{"u2":"سلیمان جو ہلال(تمیمی) کے بیٹے ہیں،انھوں نے جعفر (صادق) سے،انھوں نے اپنے والد سے اور انھوں نے ابو رافع (مولیٰ رسول اللہ صلی اللہ علیہ وسلم کے بیٹے عبیداللہ) سے ر وایت کی،انھوں نے کہا:مروان نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ کو مدینہ میں اپنا جانشین مقرر کیا اور خود مکہ چلا گیا۔حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے ہمیں جمعے کی نماز پڑھائی اور (پہلی رکعت میں) سورہ جمعہ پڑھنے کے بعد دوسری رکعت میں إِذَا جَاءَکَ الْمُنَافِقُونَ پڑھی اور کہا:جب ابو ہریرۃ رضی اللہ تعالیٰ عنہ جمعے کی نماز سے فارغ ہوئے تو میں ان کے پاس جاپہنچا اور ان سے کہا:آپ نے وہ دو سورتیں پڑھی ہیں جو علی ابن طالب رضی اللہ تعالیٰ عنہ کوفہ میں پڑھا کرتے تھے۔ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو جمعے کے دن یہ سورتیں پڑھتے ہوئے سنا ہے۔"}],[1969,"حاتم بن اسماعیل اور عبدالعزیز دراوردی دونوں نے ( اپنی اپنی سندکے ساتھ ) جعفر سے روایت کی ، انھوں نے اپنے والد سے اور انھوں نے عبیداللہ بن ابی رافع سے روایت کی ، انھوں نے کہا : مروان رضی اللہ تعالیٰ عنہ نے سیدنا ابوہریرہ رضی اللہ تعالیٰ عنہ کو قائم مقام گورنر بنایا ۔ ۔ ۔ آگے اسی کے مانند ہے ، سوائے اس کے کہ حاتم کی روایت ( ان الفاظ ) میں ہے : انھوں نے پہلی رکعت میں سورہ جمعہ پڑھی اور دوسری رکعت میں «إِذَا جَاءَكَ الْمُنَافِقُونَ» ۔ عبدالعزیز کی روایت سلیمان بن بلال کی ( سابقہ ) ر وایت کی طرح ہے ۔","",{"u2":"حاتم بن اسماعیل اور عبدالعزیز دراوردی دونوں نے(اپنی اپنی سندکے ساتھ) جعفر سے روایت کی،انھوں نے اپنے والد سے اور انھوں نے عبیداللہ بن ابی رافع سے روایت کی،انھوں نے کہا:مروان رضی اللہ تعالیٰ عنہ نے حضرت ابوہریرہ رضی اللہ تعالیٰ عنہ کو قائم مقام گورنر بنایا۔۔۔آگے اسی کے مانندہے،سوائے اس کے کہ حاتم کی روایت(ان الفاظ) میں ہے:انھوں نے پہلی رکعت میں سورہ جمعہ پڑھی اور دوسری رکعت میں إِذَا جَاءَکَ الْمُنَافِقُونَ۔\nعبدالعزیز کی روایت سلیمان بن بلال کی (سابقہ) ر وایت کی طرح ہے۔"}],[1970,"(جریر نے ابراہیم بن محمد بن منتشر سے ، انھوں نے اپنے والد سے ، انھوں نے سیدنا نعمان بن بشیر کے آزاد کردہ غلام حبیب بن سالم سے اور انھوں نے سیدنا نعمان بن بشیر رضی اللہ تعالیٰ عنہ سےروایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم عیدین اور جمعے میں «سَبِّحِ اسْمَ» رَ‌بِّكَ «الْأَعْلَى» اور ) «هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ» پڑھتے ۔ کہا : اور اگر عید اور جمعہ ایک ہی دن اکھٹے ہوجاتے تو آپ یہی دو سورتیں دونوں نمازوں میں پڑھتے تھے ۔","",{"u2":"جریر نے ابراہیم بن محمد بن منتشر سے،انھوں نے اپنے والد سے،انھوں نے حضرت نعمان بن بشیر کے آزاد کردہ غلام حبیب بن سالم سے اور انھوں نے حضرت نعمان بن بشیر رضی اللہ تعالیٰ عنہ سےروایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم عیدین اور جمعے میں سَبِّحِ اسْمَ رَ‌بِّکَ الْأَعْلَی اور) ہَلْ أَتَاکَ حَدِیثُ الْغَاشِیَۃِ پڑھتے۔\nکہا:اور اگر عید اور جمعہ ایک ہی دن اکھٹے ہوجاتے تو آپ یہی دو سورتیں دونوں نمازوں میں پڑھتے تھے۔"}],[1971,"ابو عوانہ نے ابراہیم بن محمد بن منتشر سے اسی سند کے ساتھ ( اسی کے مانند ) ر وایت کی ۔","",{"u2":"ابو عوانہ نے ابراہیم بن محمد بن منتشر سے اسی سند کے ساتھ(اسی کے مانند) ر وایت کی۔"}],[1972,"عبیداللہ بن عبداللہ نے کہا : ضحاک بن قیس نے سیدنا نعمان بن بشیر رضی اللہ تعالیٰ عنہ کوخط لکھ کر پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم نے جمعے کے دن سورہ جمعہ کے علاوہ ( اور ) کون سی سورت پڑھی؟انھوں نے جواب دیا : آپ صلی اللہ علیہ وسلم «هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ» پڑھا کرتے تھے ۔","",{"u2":"عبیداللہ بن عبداللہ نے کہا:ضحاک بن قیس نے حضرت نعمان بن بشیر رضی اللہ تعالیٰ عنہ کوخط لکھ کر پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم نے جمعے کے دن سورہ جمعہ کے علاوہ(اور) کون سی سورت پڑھی؟انھوں نے جواب دیا:آپ صلی اللہ علیہ وسلم ہَلْ أَتَاکَ حَدِیثُ الْغَاشِیَۃِ پڑھا کرتے تھے۔"}],[1973,"عبدہ بن سلیمان نے سفیان سے روایت کی ، انھوں نے مخول بن راشد سے ، انھوں نے مسلم البطین سے ، انہوں نے سعید بن جبیر سے اورانھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم جمعے کے دن فجر کی نماز میں الم ﴿﴾ «تَنزِيلُ الْكِتَابِ» السجدہ اور «هَلْ أَتَىٰ عَلَى الْإِنسَانِ حِينٌ مِّنَ» الدَّهْرِ پڑھتے تھے ۔ آپ صلی اللہ علیہ وسلم جمعے کی نماز میں سورہ جمعہ اور سورہ منافقون پڑھتے تھے ۔","",{"u2":"عبدہ بن سلیمان نے سفیان سے روایت کی،انھوں نے مخول بن راشد سے،انھوں نے مسلم البطین سے،انہوں نے سعید بن جبیر سے اورانھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم جمعے کے دن فجر کی نماز میں الم ﴿﴾ تَنزِیلُ الْکِتَابِ السجدہ اور ہَلْ أَتَیٰ عَلَی الْإِنسَانِ حِینٌ مِّنَ الدَّہْرِ‌ پڑھتے تھے۔آپ صلی اللہ علیہ وسلم جمعے کی نماز میں سورہ جمعہ اورسورہ منافقون پڑھتے تھے۔"}],[1974,"عبداللہ بن نمیر اور وکیع دونوں نے سفیان سے اسی سند کے ساتھ اسی ( سابقہ حدیث ) کے مانند روایت کی ۔","",{"u2":"عبداللہ بن نمیر اور وکیع دونوں نے سفیان سے اسی سند کے ساتھ اسی(سابقہ حدیث) کے مانند روایت کی۔"}],[1975,"شعبہ نے مخول سے اسی سندکے ساتھ دونوں نمازوں کے بارے میں اسی ( سابقہ حدیث ) کے مانند روایت کی جس طرح سفیان نے ( اپنی روایت میں ) کہا ۔","",{"u2":"شعبہ نے مخول سے اسی سندکے ساتھ دونوں نمازوں کے بارے میں اسی(سابقہ حدیث) کے مانند روایت کی جس طرح سفیان نے (اپنی روایت میں) کہا۔"}],[1976,"سفیان نے سعد بن ابراہیم سے ، انہوں نے عبدالرحمان اعرج سے ، انھوں نے ابوہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ جمعے کے دن فجر کی نماز میں الم ﴿﴾ «تَنزِيلُ الْكِتَابِ اور هَلْ أَتَىٰ عَلَى الْإِنسَانِ» پڑھتے تھے ۔","",{"u2":"سفیان نے سعد بن ابراہیم سے،انہوں نے عبدالرحمان اعرج سے،انھوں نے ابوہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ جمعے کے دن فجر کی نماز میں الم ﴿﴾ تَنزِیلُ الْکِتَابِ اور ہَلْ أَتَیٰ عَلَی الْإِنسَانِ پڑھتے تھے۔"}],[1977,"۔ ابراہیم بن سعد نے اپنے والد ( سعد بن ابراہیم ) سے ، انھوں نے عبدالرحمان اعرج سے اور انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم جمعے کے دن صبح کی نماز کی پہلی رکعت میں الم ﴿﴾ «تَنزِيلُ الْكِتَابِ» اور دوسری رکعت میں «هَلْ أَتَىٰ عَلَى الْإِنسَانِ حِينٌ مِّنَ» الدَّهْرِ‌لَمْ «يَكُن شَيْئًا» مَّذْكُورً‌ا پڑھتے تھے ۔ ۔","",{"u2":"۔ ابراہیم بن سعد نے اپنے والد(سعد بن ابراہیم)سے،انھوں نے عبدالرحمان اعرج سے اور انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم جمعے کے دن صبح کی نماز کی پہلی رکعت میں الم ﴿﴾ تَنزِیلُ الْکِتَابِ اور دوسری رکعت میں ہَلْ أَتَیٰ عَلَی الْإِنسَانِ حِینٌ مِّنَ الدَّہْرِ‌لَمْ یَکُن شَیْئًا مَّذْکُورً‌ا پڑھتے تھے۔۔"}],[1978,"۔ خالد بن عبداللہ نے سہیل سے ، انھوں نے اپنے والد ( ابوصالح ) سے اور انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی جمعہ پڑھ چکے تو اس کے بعد چار رکعتیں پڑھے ۔","",{"u2":"۔ خالد بن عبداللہ نے سہیل سے،انھوں نے اپنے والد (ابوصالح) سے اور انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جب تم میں سے کوئی جمعہ پڑھ چکے تو اس کے بعد چار رکعتیں پڑھے۔\""}],[1979,"ابوبکر بن ابی شیبہ اور عمرو الناقد نے کہا : ہمیں عبداللہ بن ادریس نے سہیل سے حدیث سنائی ، انھوں نے اپنے والد سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم جمعے کے بعد نماز پڑھو تو چار رکعتیں پڑھو \" عمرو نے اپنی روایت میں اضافہ کیا ، ابن ادریس نے کہا سہیل نے کہا : اگر تمھیں کسی چیز کی وجہ سے جلدی ہو تو دو رکعتیں مسجد میں پڑھ لو اور دو رکعتیں و اپس جا کر ( گھر میں ) پڑ ھ لو ۔","",{"u2":"ابوبکر بن ابی شیبہ اور عمرو الناقد نے کہا:ہمیں عبداللہ بن ادریس نے سہیل سے حدیث سنائی،انھوں نے اپنے والد سے اور انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی، انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جب تم جمعے کے بعد نماز پڑھو تو چار رکعتیں پڑھو\"عمرو نے اپنی روایت میں اضافہ کیا،ابن ادریس نے کہا سہیل نے کہا:اگر تمھیں کسی چیز کی وجہ سے جلدی ہو تو دو رکعتیں مسجد میں پڑھ لو اور دو رکعتیں و اپس جا کر(گھر میں) پڑ ھ لو۔"}],[1980,"جریر اور سفیان نے سہیل سے ، انھوں نے اپنے والد سے اور انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نےفرمایا : \"\" تم میں سے جو شخص جمعے کے بعد نماز پڑھے تو چار رکعتیں پڑھے ۔ \"\" جریر کی حدیث میں \"\" منكم \"\" ( تم میں سے ) کے الفاظ نہیں ہیں ۔","",{"u2":"جریر اور سفیان نے سہیل سے،انھوں نے اپنے والد سے اور انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نےفرمایا:\"تم میں سے جو شخص جمعے کے بعد نماز پڑھے توچار رکعتیں پڑھے۔\"\nجریر کی حدیث میں \"منکم\"(تم میں سے) کے الفاظ نہیں ہیں۔"}],[1981,"لیث نے نافع سے اورانھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ جب وہ جمعہ پڑھ لیتے تو واپس جاتے اور اپنے گھر میں دو ر رکعتیں پڑھتے ۔ پھر انھوں ( ابن عمر رضی اللہ تعالیٰ عنہ ) نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کرتے تھے ۔","",{"u2":"لیث نے نافع سے اورانھوں نے حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ جب وہ جمعہ پڑھ لیتے تو واپس جاتے اور اپنے گھر میں دو ر رکعتیں پڑھتے۔پھر انھوں (ابن عمر رضی اللہ تعالیٰ عنہ) نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کرتے تھے۔"}],[1982,"یحییٰ بن یحییٰ نے کہا : میں نے امام مالکؒ پر ( حدیث کی ) قراءت کی ، انھوں نے نافع سے اورانھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کی نفل نماز کو بیان کیا اور کہا کہ آپ جمعے کے بعد کوئی ( نفل ) نماز نہ پڑھے حتیٰ کہ واپس تشریف لے جاتے پھر ا پنے گھر میں د و رکعتیں پڑھتے تھے ۔ یحییٰ بن یحییٰ نے کہا : میرا خیال ہے کہ میں نے ( امام مالکؒ کے سامنے ) \" فيصلي \" پڑھا تھا یا یقین ہے ( کہ یہی پڑھا تھا)","",{"u2":"یحییٰ بن یحییٰ نے کہا:میں نے امام مالک رحمہ اللہ پر(حدیث کی) قراءت کی،انھوں نے نافع سے اورانھوں نے حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کی نفل نماز کو بیان کیا اورکہا کہ آپ جمعے کے بعد کوئی (نفل) نماز نہ پڑھے حتیٰ کہ واپس تشریف لے جاتے پھر ا پنے گھر میں د و رکعتیں پڑھتے تھے۔یحییٰ بن یحییٰ نے کہا:میرا خیال ہے کہ میں نے(امام مالک رحمہ اللہ کے سامنے)\"فیصلی\"پڑھا تھا یا یقین ہے(کہ یہی پڑھاتھا)"}],[1983,"سالم نے اپنے والد ( سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ ) سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم جمعے کےبعددو ر کعتیں پڑھتے تھے ۔","",{"u2":"سالم نے اپنے والد(حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ) سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم جمعے کےبعددو ر کعتیں پڑھتے تھے۔"}],[1984,"غندر نے ابن جریج سے روایت کی ، انھوں نے کہا : مجھے عمر بن عطاء بن ابی خوار نے بتایا کہ نافع بن جبیر نے انھیں نمر کے بھانجے سائب کے پاس بھیجے ان سے اس چیز کے بارے میں پوچھنے کے لئے جو سیدنا معاویہ رضی اللہ تعالیٰ عنہ نے ان کی نماز میں دیکھی تھی ۔ سائب نے کہا : ہاں ، میں نے مقصورہ ( مسجد کے حجرے ) میں ان کے ساتھ جمعہ پڑھا تھا ۔ اور جب امام نے سلام پھیرا تو میں اپنی جگہ پر کھڑا ہوگیا اور نماز پڑھی ۔ جب معاویہ رضی اللہ تعالیٰ عنہ اندر داخل ہوئے تو مجھے بلوایا اور کہا : جو کام تم نے کیا ہے آئندہ نہ کرنا ۔ جب تم جمعہ پڑھ لو تو اسے کسی دوسری نماز سے نہ ملانا یہاں تک کہ گفتگو کرلو یا اس جگہ سے نکل جاؤ کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اس بات کا حکم دیاتھا کہ ہم کسی نماز کو دوسری نماز سے نہ ملائیں حتیٰ کہ ہم گفتگو کرلیں یا ( اس جگہ سے ) نکل جائیں ۔","",{"u2":"غندر نے ابن جریج سے روایت کی،انھوں نے کہا:مجھے عمر بن عطاء بن ابی خوار نے بتایا کہ نافع بن جبیر نے انھیں نمر کے بھانجے سائب کے پاس بھیجے ان سے اس چیز کے بارے میں پوچھنے کے لئے جو حضرت معاویہ رضی اللہ تعالیٰ عنہ نے ان کی نماز میں دیکھی تھی۔سائب نے کہا:ہاں،میں نے مقصورہ(مسجد کے حجرے) میں ان کے ساتھ جمعہ پڑھا تھا۔اور جب امام نے سلام پھیرا تو میں اپنی جگہ پر کھڑا ہوگیا اور نماز پڑھی۔جب معاویہ رضی اللہ تعالیٰ عنہ اندرداخل ہوئے تو مجھے بلوایا اور کہا:جو کام تم نے کیا ہے آئندہ نہ کرنا۔جب تم جمعہ پڑھ لو تو اسے کسی دوسری نماز سے نہ ملانا یہاں تک کہ گفتگو کرلو یا اس جگہ سے نکل جاؤ کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اس بات کا حکم دیاتھا کہ ہم کسی نماز کو دوسری نماز سے نہ ملائیں حتیٰ کہ ہم گفتگو کرلیں یا(اس جگہ سے) نکل جائیں۔"}],[1985,"حجاج بن محمد نے کہا : ابن جریج نے کہا : مجھے عمر بن عطاء نے بتایا کہ نافع بن جبیر نے انھیں نمر کے بھانجے سائب بن یزید کے پاس بھیجا ۔ ۔ ۔ آگے سابقہ حدیث کے کی مانند بیان کیا ۔ مگر ( اس روایت میں ) یہ ہے کہ سائب نے کہا : جب انھوں نے سلام پھیرا تو میں اپنی جگہ کھڑا ہوگیا ۔ انھوں نے ( سلام پھیرا کہا ) امام کا ذکر نہیں کیا ۔","",{"u2":"حجاج بن محمد نے کہا:ابن جریج نے کہا: مجھے عمر بن عطاء نے بتایا کہ نافع بن جبیر نے انھیں نمر کے بھانجے سائب بن یزید کے پاس بھیجا۔۔۔آگے سابقہ حدیث کے کی مانند بیان کیا۔مگر(اس روایت میں) یہ ہے کہ سائب نے کہا:جب انھوں نے سلام پھیرا تو میں اپنی جگہ کھڑا ہوگیا۔انھوں نے(سلام پھیرا کہا) امام کا ذکر نہیں کیا۔"}],[1986,"حسن بن مسلم نے طاوس سے خبر دی انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا : میں عید الفطر کی نماز میں رسول اللہ صلی اللہ علیہ وسلم ابو بکر رضی اللہ تعالیٰ عنہ عمر اور عثمان رضی اللہ تعالیٰ عنہ کے ساتھ حاضر ہوا ہوں یہ سب خطبے سے پہلے نماز پڑھتے تھے پھر خطبہ دیتے تھے ایک دفعہ اللہ کے نبی صلی اللہ علیہ وسلم ( بلند جگہ سے ) نیچے آئے ایسا محسوس ہو تا ہے کہ میں ( اب بھی ) آپ کو دیکھ رہا ہوں جب آپ اپنے ہاتھ سے مردوں کو بٹھا رہے تھے پھر ان کے در میان میں سے راستہ بنا تے ہو ئے آگے بڑھے حتیٰ کہ عورتوں کے قریب تشریف لے آئے اور بلال رضی اللہ تعالیٰ عنہ آپ کے ساتھ تھے آپ نے ( قرآن کا یہ حصہ تلاوت ) فر ما یا ۔ \" اے نبی صلی اللہ علیہ وسلم !جب آپ کے پاس مومن عورتیں اس بات پر بیعت کرنے کے لیے آئیں کہ وہ اللہ تعا لیٰ کے ساتھ کسی چیز کو شریک نہیں بنا ئیں گی ۔ آپ نے یہ آیت تلاوت فر ما ئی حتیٰ کہ اس سے فارغ ہو ئے پھر فر ما یا ۔ \" تم اس پر قائم ہو؟ \" تو ایک عورت نے ( جبکہ ) آپ کو اس کے علاوہ ان میں سے اور کسی نے جواب نہیں دیا کہا : ہاں اے اللہ کے نبی صلی اللہ علیہ وسلم ! ۔ ۔ اس وقت پتہ نہیں چل رہا تھا کہ وہ کو ن ہے ۔ ۔ ۔ آپ نے فر ما یا ۔ \" تم صدقہ کرو ۔ ۔ ۔ اس پر بلال رضی اللہ تعالیٰ عنہ نے اپنا کپڑا پھیلا دیا پھر کہنے لگے لاؤ تم سب پر میرے ماں باپ قربان ہوں !تو وہ اپنے بڑے بڑے چھلے اور انگوٹھیا ں بلال رضی اللہ تعالیٰ عنہ کے کپڑے میں ڈالنے لگیں ۔","",{"u2":"حسن بن مسلم نے طاوس سے خبر دی انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا: میں عید الفطر کی نماز میں رسول اللہ صلی اللہ علیہ وسلم ابو بکر رضی اللہ تعالیٰ عنہ عمر اور عثمان رضی اللہ تعالیٰ عنہ کے ساتھ حاضر ہوا ہوں یہ سب خطبے سے پہلے نماز پڑھتے تھے پھر خطبہ دیتے تھے ایک دفعہ اللہ کے نبی صلی اللہ علیہ وسلم (بلند جگہ سے) نیچے آئے ایسا محسوس ہو تا ہے کہ میں (اب بھی) آپ کو دیکھ رہا ہوں جب آپ اپنے ہاتھ سے مردوں کو بٹھا رہے تھے پھر ان کے در میان میں سے راستہ بنا تے ہو ئے آگے بڑھے حتیٰ کہ عورتوں کے قریب تشریف لے آئے اور بلال رضی اللہ تعالیٰ عنہ آپ کے ساتھ تھے آپ نے (قرآن کا یہ حصہ تلاوت) فر ما یا۔\"اے نبی صلی اللہ علیہ وسلم!جب آپ کے پاس مومن عورتیں اس بات پر بیعت کرنے کے لیے آئیں کہ وہ اللہ تعا لیٰ کے ساتھ کسی چیز کو شریک نہیں بنا ئیں گی۔آپ نے یہ آیت تلاوت فر ما ئی حتیٰ کہ اس سے فارغ ہو ئے پھر فر ما یا۔\"تم اس پر قائم ہو؟ \"تو ایک عورت نے (جبکہ) آپ کو اس کے علاوہ ان میں سے اور کسی نے جواب نہیں دیا کہا:ہاں اے اللہ کے نبی صلی اللہ علیہ وسلم!۔۔اس وقت پتہ نہیں چل رہا تھا کہ وہ کو ن ہے۔۔۔آپ نے فر ما یا۔\"تم صدقہ کرو۔۔۔اس پر بلال رضی اللہ تعالیٰ عنہ نے اپنا کپڑا پھیلا دیا پھر کہنے لگے لاؤ تم سب پر میرے ماں باپ قربان ہوں!تو وہ اپنے بڑے بڑے چھلے اور انگوٹھیا ں بلال رضی اللہ تعالیٰ عنہ کے کپڑے میں ڈالنے لگیں۔"}],[1987,"سفیان بن عیینہ نے کہا : ہم سے ایوب نے حدیث بیان کی انھوں نے کہا میں نے عطاء سے سنا انھوں نے کہا میں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ کو یہ کہتے ہوئے سنا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے بارے میں شہادت دیتا ہوں آپ نماز عید خطبہ سے پہلے پڑھی پھر آپ نے خطبہ دیا پھر آپ نے دیکھا کہ آپ نے عورتوں کو ( اپنی بات ) نہیں سنائی تو آپ ان کے پاس آئے اور ان کو یاد دہانی ( تلقین ) فر ما ئی اور انھیں نصیحت کی اور صدقہ کرنے کا حکم دیا اور بلال رضی اللہ تعالیٰ عنہ اپنا کپڑا پھیلا ئے ہو ئے تھے کو ئی عورت ( اس کپڑے میں ) انگوٹھی پھینکتی تھی ( کو ئی حلقے دارزیور ( چھلے بالیاں کڑے کنگن ) اور کوئی دوسری چیزیں ڈالتی تھی ۔","",{"u2":"سفیان بن عیینہ نے کہا: ہم سے ایوب نے حدیث بیان کی انھوں نے کہا میں نے عطاء سے سنا انھوں نے کہا میں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ کو یہ کہتے ہوئے سنا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے بارے میں شہادت دیتا ہوں آپ نماز عید خطبہ سے پہلے پڑھی پھر آپ نے خطبہ دیا پھر آپ نے دیکھا کہ آپ نے عورتوں کو (اپنی بات) نہیں سنائی تو آپ ان کے پاس آئے اور ان کو یاد دہانی (تلقین) فر ما ئی اور انھیں نصیحت کی اور صدقہ کرنے کا حکم دیا اور بلال رضی اللہ تعالیٰ عنہ اپنا کپڑا پھیلا ئے ہو ئے تھے کو ئی عورت (اس کپڑے میں) انگوٹھی پھینکتی تھی (کو ئی حلقے دارزیور (چھلے بالیاں کڑے کنگن)اور کوئی دوسری چیزیں ڈالتی تھی۔"}],[1988,"سفیان بن عیینہ نے کہا : ہم سے ایوب نے حدیث بیان کی انھوں نے کہا میں نے عطاء سے سنا انھوں نے کہا میں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ کو یہ کہتے ہوئے سنا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے بارے میں شہادت دیتا ہوں آپ نماز عید خطبہ سے پہلے پڑھی پھر آپ نے خطبہ دیا پھر آپ نے دیکھا کہ آپ نے عورتوں کو ( اپنی بات ) نہیں سنائی تو آپ ان کے پاس آئے اور ان کو یاد دہانی ( تلقین ) فر ما ئی اور انھیں نصیحت کی اور صدقہ کرنے کا حکم دیا اور بلال رضی اللہ تعالیٰ عنہ اپنا کپڑا پھیلا ئے ہو ئے تھے کو ئی عورت ( اس کپڑے میں ) انگوٹھی پھینکتی تھی ( کو ئی حلقے دارزیور ( چھلے بالیاں کڑے کنگن ) اور کوئی دوسری چیزیں ڈالتی تھی ۔","",{"u2":"حماد اور اسماعیل بن ابرا ہیم نے ایوب سے اسی سند کے ساتھ اسی طرح حدیث بیان کی۔"}],[1989,"ابن جریج نے کہا : ہمیں عطاء نے حجرت جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے خبر دی کہا : میں نے ان ( جابر رضی اللہ تعالیٰ عنہ ) کو یہ کہتے ہوئے سنا کہ نبی صلی اللہ علیہ وسلم عید الفطر کے دن ( نماز کے لیے ) کھڑے ہو ئے پھر نماز پڑھا ئی چنانچہ آپ نے خطبے سے پہلے نماز سے ابتدا کی پھر لو گوں کو خطاب فر ما یا ۔ جب نبی صلی اللہ علیہ وسلم ( خطبہ سے ) فارغ ہو ئے تو ( چبوترے سے ) اتر کر عورتوں کے پاس آئے انھیں تذکیر و نصیحت کی جبکہ آپ بلال رضی اللہ تعالیٰ عنہ کے بازو کا سہارا لیے ہو ئے تھے اور بلال رضی اللہ تعالیٰ عنہ اپنا کپڑا پھیلا ئے ہو ئے تھے عورتیں اس میں صدقہ ڈال رہی تھیں ( ابن جریج نے کہا : ) میں نے عطاء سے پوچھا فطر کے دن کا صدقہ ( ڈال رہی تھیں ؟ ) انھوں نے کہا : نہیں اس وقت ( اپنا ) صدقہ کر رہی تھیں ( کو ئی عورت چھلا ڈالتی تھی ( اسی طرح یکے بعد دیگر ے ( ڈال رہی تھیں اور ڈال رہی تھیں ۔ میں نے عطاء سے ( پھر ) پوچھا : کیا اب بھی امام کے لیے لا زم ہے کہ جب ( مردوں کے خطبے سے ) فارغ ہو تو عورتوں کو تلقین اور نصیحت کرے ؟ انھوں نے کہا : ہاں مجھے اپنی زندگی کی قسم ! یہ ان پر عائد شدہ ) حق ہے انھیں کیا ہو گیا ہے کہ وہ ایسا نہیں کرتے ۔","",{"u2":"ابن جریج نے کہا: ہمیں عطاء نے حجرت جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے خبر دی کہا: میں نے ان (جابر رضی اللہ تعالیٰ عنہ) کو یہ کہتے ہوئے سنا کہ نبی صلی اللہ علیہ وسلم عید الفطر کے دن (نماز کے لیے) کھڑے ہو ئے پھر نماز پڑھا ئی چنانچہ آپ نے خطبے سے پہلے نماز سے ابتدا کی پھر لو گوں کو خطاب فر ما یا۔جب نبی صلی اللہ علیہ وسلم (خطبہ سے) فارغ ہو ئے تو(چبوترے سے) اتر کر عورتوں کے پاس آئے انھیں تذکیر و نصیحت کی جبکہ آپ بلال رضی اللہ تعالیٰ عنہ کے بازوکا سہارا لیے ہو ئے تھے اور بلال رضی اللہ تعالیٰ عنہ اپنا کپڑا پھیلا ئے ہو ئے تھے عورتیں اس میں صدقہ ڈال رہی تھیں (ابن جریج نے کہا:) میں نے عطاء سے پوچھا فطر کے دن کا صدقہ(ڈال رہی تھیں؟)انھوں نے کہا: نہیں اس وقت (اپنا) صدقہ کر رہی تھیں (کو ئی عورت چھلا ڈالتی تھی (اسی طرح یکے بعد دیگر ے (ڈال رہی تھیں اور ڈال رہی تھیں۔\nمیں نے عطاء سے (پھر) پوچھا: کیا اب بھی امام کے لیے لا زم ہے کہ جب(مردوں کے خطبے سے) فارغ ہو تو عورتوں کو تلقین اور نصیحت کرے؟ انھوں نے کہا: ہاں مجھے اپنی زندگی کی قسم! یہ ان پر عائد شدہ) حق ہے انھیں کیا ہو گیا ہے کہ وہ ایسا نہیں کرتے۔"}],[1990,"عبد الملک بن ابی سلیمان نے عطاء سے اور انھوں نے سیدنا جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا : میں عید کے دن رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز میں حاضر ہوا آپ نے خطبے سے پہلے اذان اور تکبیر کے بغیر نماز سے ابتدا کی پھر بلال رضی اللہ تعالیٰ عنہ کا سہارا لے کر کھڑے ہو ئے اللہ کے تقوے کا حکم دیا اس کی اطاعت پر ابھا را لو گو ں کو نصیحت کی اور انھیں ( دین کی بنیادی باتوں کی ) یاد دہانی کرا ئی پھر چل پڑے حتیٰ کہ عورتوں کے پاس آگئے ( تو ) انھیں وعظ و تلقین ( تذکیر ) کی اور فر ما یا ۔ \" صدقہ کرو کیونکہ تم میں اسے اکثر جہنم کا ایندھن ہیں ۔ \" عورتوں کے در میان سے ایک بھلی سیاہی مائل رخساروں والی عورت نے کھڑے ہو کر پوچھا : اللہ کے رسول صلی اللہ علیہ وسلم !کیوں ؟آپ نے فر ما یا : اس لیے کہ تم شکا یت بہت کرتی ہو اور اپنے رفیق زندگی کی ناشکری کرتی ہو ۔ ( جا بر رضی اللہ تعالیٰ عنہ نے ) کہا اس پردہ عورتیں اپنے زیورات سے صدقہ کرنے لگیں وہ بلال رضی اللہ تعالیٰ عنہ کے کپڑے میں اپنی بالیاں اور انگھوٹھیاں ڈالنے لگیں ۔","",{"u2":"عبد الملک بن ابی سلیمان نے عطاء سے اور انھوں نے حضرت جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا: میں عید کے دن رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز میں حاضر ہوا آپ نے خطبے سے پہلے اذان اور تکبیر کے بغیر نماز سے ابتدا کی پھر بلال رضی اللہ تعالیٰ عنہ کا سہارا لے کر کھڑے ہو ئے اللہ کے تقوے کا حکم دیا اس کی اطاعت پر ابھا را لو گو ں کو نصیحت کی اور انھیں (دین کی بنیادی باتوں کی) یاد دہانی کرا ئی پھر چل پڑے حتیٰ کہ عورتوں کے پاس آگئے (تو) انھیں وعظ و تلقین (تذکیر) کی اور فر ما یا۔\"صدقہ کرو کیونکہ تم میں اسے اکثر جہنم کا ایندھن ہیں۔\"عورتوں کے در میان سے ایک بھلی سیاہی مائل رخساروں والی عورت نے کھڑے ہو کر پوچھا:اللہ کے رسول صلی اللہ علیہ وسلم!کیوں؟آپ نے فر ما یا:اس لیے کہ تم شکا یت بہت کرتی ہو اور اپنے رفیق زندگی کی ناشکری کرتی ہو۔(جا بر رضی اللہ تعالیٰ عنہ نے) کہا اس پردہ عورتیں اپنے زیورات سے صدقہ کرنے لگیں وہ بلال رضی اللہ تعالیٰ عنہ کے کپڑے میں اپنی بالیاں اور انگھوٹھیاں ڈالنے لگیں۔"}],[1991,"سیدنا ابن عباس اور سیدنا جابر ؓ نے کہا کہ اذان نہ عیدالفطر میں ہوتی تھی اور نہ عید الاضحیٰ میں ۔ پھر میں نے ان سے پوچھا تھوڑی دیر کے بعد اسی بات کو ، (یہ قول ہے ابن جریج راوی کا) تو انہوں نے کہا (یعنی ان کے شیخ عطاء نے) کہ خبر دی مجھے سیدنا جابر بن عبداللہ انصاری ؓ نے کہ نہ اذان ہوتی تھی عیدالفطر میں جب نکلتا تھا اور نہ بعد اس کے نکلنے کے اور نہ تکبیر ہوتی ، نہ اذان اور نہ اور کچھ وہ دن ایسا ہے کہ اس دن نہ اذان ہے نہ تکبیر ۔","",{"u2":"محمد بن رافع نے کہا: ہم سے عبد الرزاق نے حدیث بیان کی انھوں نے کہا: ہمیں ابن جریج نے خبر دی انھوں نے کہا: مجھے عطاء نے حضرت ابن عباس اور جابر بن عبد اللہ انصاری رضی اللہ تعالیٰ عنہ سے خبر دی ان دونوں نے کہا: عید الفطر اور عید الاضحیٰ کے دن اذان نہیں دی جا تی تھی (ابن جریج نے کہا: کہ) میں نے کچھ عرصے بعد اس کے بارے میں عطاء سے پھر پو چھا تو انھوں نے مجھے جا بر رضی اللہ تعالیٰ عنہ بن عبد اللہ انصاری رضی اللہ تعالیٰ عنہ سے خبر دی کہ عید الفطر کے دن اذان نہیں ہے نہ اس وقت جب امام نکلے اور نہ نکلنے کے بعدنہ اقامت ہے نہ اعلا ن اور نہ کو ئی اور چیز اس د ن نہ اذان ہے اور نہ اقامت۔"}],[1992,"۔ محمد بن رافع نے کہا : ہمیں عبد الرزاق نے حدیث سنا ئی کہا : ہمیں ابن جریج نے خبر دی کہا : مجھے عطاء نے خبر دی کہ ابن زبیر رضی اللہ تعالیٰ عنہ کی بیعت کے آغاز ہی میں ابن عباس رضی اللہ تعالیٰ عنہ نے ان کی طرف پیغام بھیجا کہ عید الفطر کے دن نماز ( عید کے لیے اذان نہیں دی جا تی تھی لہٰذا آپ اس کے لیے اذان نہ کہلوائیں ابن زبیر رضی اللہ تعالیٰ عنہ نے اس اذان نہ کہلوائی اور اس کے ساتھ یہ پیغام بھی بھیجا کہ خطبہ نماز کے بعد ہے اور ( عہد نبوی اور خلا فت راشدہ میں ) ایسے ہی کیا جا تا تھا ( عطاء نے ) کہا : تو ابن زبیر رضی اللہ تعالیٰ عنہ نے نماز خطبے سے پہلے پڑھا ئی ۔","",{"u2":"۔ محمد بن رافع نے کہا: ہمیں عبد الرزاق نے حدیث سنا ئی کہا: ہمیں ابن جریج نے خبر دی کہا: مجھے عطاء نے خبر دی کہ ابن زبیر رضی اللہ تعالیٰ عنہ کی بیعت کے آغاز ہی میں ابن عباس رضی اللہ تعالیٰ عنہ نے ان کی طرف پیغام بھیجا کہ عید الفطرکے دن نماز (عید کے لیے اذان نہیں دی جا تی تھی لہذا آپ اس کے لیے اذان نہ کہلوائیں ابن زبیر رضی اللہ تعالیٰ عنہ نے اس اذان نہ کہلوائی اور اس کے ساتھ یہ پیغام بھی بھیجا کہ خطبہ نماز کے بعد ہے اور (عہد نبوی اور خلا فت راشدہ میں) ایسے ہی کیا جا تا تھا (عطاء نے) کہا: تو ابن زبیر رضی اللہ تعالیٰ عنہ نے نماز خطبے سے پہلے پڑھا ئی۔"}],[1993,"سیدنا جا بر بن سمرہ رضی اللہ تعالیٰ عنہ سے روا یت ہے انھوں نے کہا میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عید ین کی نماز ایک یا دو دفعہ پڑھی ہے ۔","",{"u2":"حضرت جا بر بن سمرہ رضی اللہ تعالیٰ عنہ سے روا یت ہے انھوں نے کہا میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عید ین کی نماز ایک یا دو دفعہ پڑھی ہے۔"}],[1994,"سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم ابو بکر اور عمر رضی اللہ تعالیٰ عنہ عید ین کی نماز خطبے سے پہلے پڑھتے تھے ۔","",{"u2":"حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم ابو بکر اور عمر رضی اللہ تعالیٰ عنہ عید ین کی نماز خطبے سے پہلے پڑھتے تھے۔"}],[1995,"سیدنا ابو سعید خدری رضی اللہ تعالیٰ عنہ سے روا یت کہ رسول اللہ صلی اللہ علیہ وسلم عید الاضحیٰ اور عید الفطر کے دن تشریف لا تے تو نماز سے آغاز فرماتے اور جب اپنی نماز پڑھ لیتے اور سلام پھیر تے تو کھڑے ہو جا تے لوگوں کی طرف رخ فر ما تے جبکہ لو گ اپنی نماز پڑھنے کی جگہ میں بیٹھے ہو تے اگر آپ کو کو ئی لشکر بھیجنے کی ضرورت ہو تی تو اس کا لو گو ں کے سامنے ذکر فر ما تے اور اگر آپ کو اس کے سوا کو ئی اور ضرورت ہوتی تو انھیں اس کا حکم دیتے اور فر ما یا کرتے \" صدقہ کرو صدقہ کرو صدقہ کرو زیادہ صدقہ عورتیں دیا کرتی تھیں پھر آپ واپس ہو جا تے اور یہی معمول چلتا رہا حتیٰ کہ مردان بن حکم کا دور آگیا میں اس کے ساتھ ہاتھ میں ہاتھ ڈال کر نکلا حتیٰ کہ ہم عید گا ہ میں پہنچ گئے تو دیکھا کہ کثیر بن صلت نے وہاں مٹی ( کے گا رے ) اور اینٹوں سے منبر بنا یا ہو اتھا تو اچانک مردان کا ہا تھ مجھ سے کھنچا تا نی کرنے لگا جیسے وہ مجھے منبر کی طرف کھنچ رہا ہو اور میں اسے نماز کی طرف کھنچ رہا ہوں جب میں نے اس کی طرف سے یہ بات دیکھی تو میں نے کہا : نماز سے آغاز ( کا مسنون کا طریقہ ) کہاں ہے؟ اس نے کہا : اے ابو سعید !نہیں جو آپ جا نتے ہیں اسے ترک کر دیا گیا ہے میں نے کہا : ہر گز نہیں ، اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! جو میں جانتا ہوں تم اس سے بہتر طریقہ نہیں لاسکتے ۔ ۔ ۔ ابو سعید رضی اللہ تعالیٰ عنہ نے تین دفہ کہا ، پھر چل دئیے ۔","",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالیٰ عنہ سے روا یت کہ رسول اللہ صلی اللہ علیہ وسلم عید الاضحیٰ اور عید الفطر کے دن تشریف لا تے تو نماز سے آغاز فرماتے اور جب اپنی نماز پڑھ لیتے اور سلام پھیر تے تو کھڑے ہو جا تے لوگوں کی طرف رخ فر ما تے جبکہ لو گ اپنی نماز پڑھنے کی جگہ میں بیٹھے ہو تے اگر آپ کو کو ئی لشکر بھیجنے کی ضرورت ہو تی تو اس کا لو گو ں کے سامنے ذکر فر ما تے اور اگر آپ کو اس کے سوا کو ئی اور ضرورت ہوتی تو انھیں اس کا حکم دیتے اور فر ما یا کرتے \"صدقہ کرو صدقہ کرو صدقہ کرو زیادہ صدقہ عورتیں دیا کرتی تھیں پھر آپ واپس ہو جا تے اور یہی معمول چلتا رہا حتیٰ کہ مردان بن حکم کا دور آگیا میں اس کے ساتھ ہاتھ میں ہاتھ ڈال کر نکلا حتیٰ کہ ہم عید گا ہ میں پہنچ گئے تو دیکھا کہ کثیر بن صلت نے وہاں مٹی (کے گا رے) اور اینٹوں سے منبر بنا یا ہو اتھا تو اچانک مردان کا ہا تھ مجھ سے کھنچا تا نی کرنے لگا جیسے وہ مجھے منبر کی طرف کھنچ رہا ہو اور میں اسے نماز کی طرف کھنچ رہا ہوں جب میں نے اس کی طرف سے یہ بات دیکھی تو میں نے کہا: نماز سے آغاز (کا مسنون کا طریقہ)کہاں ہے؟ اس نے کہا: اے ابو سعید!نہیں جو آپ جا نتے ہیں اسے ترک کر دیا گیا ہے میں نے کہا: ہر گز نہیں،اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! جو میں جانتا ہوں تم اس سے بہتر طریقہ نہیں لاسکتے۔۔۔ابو سعید رضی اللہ تعالیٰ عنہ نے تین دفہ کہا،پھر چل دئیے۔"}],[1996,"محمد ( بن سیرین ) نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : آپ نے ہمیں حکم دیا ۔ ۔ ۔ ان کی مراد نبی کریم صلی اللہ علیہ وسلم سے تھی ۔ ۔ ۔ کہ ہم عیدین میں بالغہ اور پردہ نشین عورتوں کو لے جایا کریں اور آپ نے حیض والی عورتوں کو حکم دیا کہ وہ مسلمانوں کی نماز کی جگہ سے ہٹ کر بیٹھیں ۔","",{"u2":"محمد (بن سیرین) نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:آپ نے ہمیں حکم دیا۔۔۔ان کی مراد نبی کریم صلی اللہ علیہ وسلم سے تھی۔۔۔کہ ہم عیدین میں بالغہ اور پردہ نشین عورتوں کو لے جایا کریں اور آپ نے حیض والی عورتوں کو حکم دیا کہ وہ مسلمانوں کی نماز کی جگہ سے ہٹ کر بیٹھیں۔"}],[1997,"عاصم احول نے حفصہ بنت سیرین سے اور انھوں نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : \" ہمیں عیدین میں نکلنے کا حکم دیاجاتاتھا ، پردہ نشین اوردوشیزہ کو بھی ۔ \" انھوں نے کہا : حیض والی عورتیں بھی نکلیں گی اور لوگوں کے پیچھے رہیں گی اور لوگوں کے ساتھ تکبیر کہیں گی ۔","",{"u2":"عاصم احول نے حفصہ بنت سیرین سے اور انھوں نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:\"ہمیں عیدین میں نکلنے کا حکم دیاجاتاتھا،پردہ نشین اوردوشیزہ کو بھی۔\"انھوں نے کہا:حیض والی عورتیں بھی نکلیں گی اور لوگوں کے پیچھے رہیں گی اور لوگوں کے ساتھ تکبیر کہیں گی۔"}],[1998,"۔ ہشام نے حفصہ بن سیرین سے اور انھوں نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم عید الفطر اور عید الاضحیٰ میں عورتوں کو باہر نکالیں ، دوشیزہ ، حائضہ اور پردہ نشیں عورتوں کو باہر نکالیں ، دوشیزہ اور حائضہ اور پردہ نشین عورتوں کو ، لیکن حائضہ نمازسےدور رہیں ۔ وہ خیروبرکت اور مسلمانوں کی دعا میں شریک ہوں ۔ میں نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم ! ہم میں سے کسی عورت کے پاس چادر نہیں ہوتی ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اس کی ( کوئی مسلمانک ) بہن اس کو اپنی چادر کا ایک حصہ پہنا دے ۔","",{"u2":"۔ ہشام نے حفصہ بن سیرین سے اور انھوں نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم عید الفطر اورعید الاضحیٰ میں عورتوں کو باہر نکالیں،دوشیزہ،حائضہ اور پردہ نشیں عورتوں کو باہر نکالیں،دوشیزہ اور حائضہ اور پردہ نشین عورتوں کو،لیکن حائضہ نمازسےدور رہیں۔وہ خیروبرکت اور مسلمانوں کی دعا میں شریک ہوں۔میں نے عرض کی:اے اللہ کے رسول صلی اللہ علیہ وسلم! ہم میں سے کسی عورت کے پاس چادر نہیں ہوتی۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"اس کی(کوئی مسلمانک) بہن اس کو اپنی چادر کا ایک حصہ پہنا دے۔\""}],[1999,"معاذ عنبری نے کہا : ہم سے شعبہ نے حدیث بیان کی ، انھوں نے عدی سے روایت کی ، انھوں نے سعید بن جبیر سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم عید الاضحیٰ یا عید الفطر کے دن باہر نکلے اوردو رکعتیں پڑھائیں ، اس سے پہلے یا بعد میں کوئی نماز نہیں پڑھی ۔ پھر عورتوں کے پاس آئے جبکہ بلال رضی اللہ تعالیٰ عنہ آپ کے ساتھ تھے ، آپ صلی اللہ علیہ وسلم نے عورتوں کو صدقے کا حکم دیا تو کوئی عورت اپنی بالیاں ( بلال رضی اللہ تعالیٰ عنہ کے کپڑے میں ) ڈالتی تھیں اور کوئی اپنا ( لونگ وغیرہ کا خوشبودار ) ہار ڈالتی تھی ۔","",{"u2":"معاذ عنبری نے کہا:ہم سے شعبہ نے حدیث بیان کی،انھوں نے عدی سے روایت کی،انھوں نے سعید بن جبیر سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم عید الاضحیٰ یا عید الفطر کے دن باہر نکلے اوردو رکعتیں پڑھائیں،اس سے پہلے یا بعد میں کوئی نماز نہیں پڑھی۔پھر عورتوں کے پاس آئے جبکہ بلال رضی اللہ تعالیٰ عنہ آپ کے ساتھ تھے،آپ صلی اللہ علیہ وسلم نے عورتوں کو صدقے کا حکم دیا تو کوئی عورت اپنی بالیاں(بلال رضی اللہ تعالیٰ عنہ کے کپڑے میں)ڈالتی تھیں اور کوئی اپنا(لونگ وغیرہ کا خوشبودار)ہار ڈالتی تھی۔"}],[2000,"معاذ عنبری نے کہا : ہم سے شعبہ نے حدیث بیان کی ، انھوں نے عدی سے روایت کی ، انھوں نے سعید بن جبیر سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم عید الاضحیٰ یا عید الفطر کے دن باہر نکلے اوردو رکعتیں پڑھائیں ، اس سے پہلے یا بعد میں کوئی نماز نہیں پڑھی ۔ پھر عورتوں کے پاس آئے جبکہ بلال رضی اللہ تعالیٰ عنہ آپ کے ساتھ تھے ، آپ صلی اللہ علیہ وسلم نے عورتوں کو صدقے کا حکم دیا تو کوئی عورت اپنی بالیاں ( بلال رضی اللہ تعالیٰ عنہ کے کپڑے میں ) ڈالتی تھیں اور کوئی اپنا ( لونگ وغیرہ کا خوشبودار ) ہار ڈالتی تھی ۔","",{"u2":"محمد بن ادریس اورغندر دونوں نے شعبہ سے اسی سند کے ساتھ اس(مذکورہ بالا حدیث)کے ہم معنی حدیث بیان کی۔"}],[2001,"مالک نے ضمرہ بن سعید مازنی سے اور انھوں نے عبیداللہ بن عبداللہ سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ نے ابو واقدلیثی سے پوچھا : رسول اللہ صلی اللہ علیہ وسلم عید الاضحیٰ اور عید الفطر میں کون سی سورت قراءت فرماتے تھے؟توانھوں نے کہا : آپ صلی اللہ علیہ وسلم ان دونوں میں سورہ ق وَالْقُرْ‌آنِ الْمَجِيدِ اور سورہ اقْتَرَ‌بَتِ «السَّاعَةُ وَانشَقَّ» الْقَمَرُ پڑھا کرتے تھے ۔","",{"u2":"مالک نے ضمرہ بن سعید مازنی سے اور انھوں نے عبیداللہ بن عبداللہ سے روایت کی کہ حضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ نے ابو واقدلیثی سے پوچھا:رسول اللہ صلی اللہ علیہ وسلم عید الاضحیٰ اور عید الفطر میں کون سی سورت قراءت فرماتے تھے؟توانھوں نے کہا:آپ صلی اللہ علیہ وسلم ان دونوں میں سورہ ق وَالْقُرْ‌آنِ الْمَجِیدِ اور سورہ اقْتَرَ‌بَتِ السَّاعَۃُ وَانشَقَّ الْقَمَرُ‌ پڑھا کرتے تھے۔"}],[2002,"فلیح نے ضمر ہ بن سعید سے ، انھوں نے عبیداللہ بن عبداللہ بن عتبہ سے اور انھوں نے سیدنا ابو واقد لیثی رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے فرمایا ، سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ نے مجھ سے اس بارے میں پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم نے عید کی نماز میں کیا پڑھا؟تو میں نے کہا : اقْتَرَ‌بَتِ «السَّاعَةُ» اور ق وَالْقُرْ‌آنِ الْمَجِيدِ","",{"u2":"فلیح نے ضمر ہ بن سعید سے،انھوں نے عبیداللہ بن عبداللہ بن عتبہ سے اور انھوں نے حضرت ابو واقد لیثی رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے فرمایا،حضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ نے مجھ سے اس بارے میں پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم نے عید کی نماز میں کیا پڑھا؟تو میں نے کہا: اقْتَرَ‌بَتِ السَّاعَۃُ اور ق وَالْقُرْ‌آنِ الْمَجِیدِ"}],[2003,"ابو اسامہ نے ہشام سے ، انھوں نے اپنے والد ( عروہ ) سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : سیدنا ابو بکر میرے ہاں تشریف لائے جبکہ میرے پاس انصار کی دو بچیاں تھیں ۔ اور انصار نے جنگ بعاث میں جو اشعار ایک دوسرے کے مقابلے میں کہے تھے ، انھیں گارہی تھیں ۔ کہا : وہ کوئی گانے والیاں نہ تھیں ۔ سیدنا ابو بکر رضی اللہ تعالیٰ عنہ نے ( انھیں دیکھ کر ) کہا : کیا رسول اللہ صلی اللہ علیہ وسلم کے گھر میں شیطان کی آواز ( بلند ہورہی ) ہے؟اور یہ عید کے دن ہوا تھا ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ابو بکر!ہر قوم کے لئے ایک عید ہے اور یہ ہماری عید ہے ۔","",{"u2":"ابو اسامہ نے ہشام سے،انھوں نے اپنے والد(عروہ) سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:حضرت ابو بکر میرے ہاں تشریف لائے جبکہ میرے پاس انصار کی دو بچیاں تھیں۔اور انصار نے جنگ بعاث میں جو اشعار ایک دوسرے کے مقابلے میں کہےتھے،انھیں گارہی تھیں۔کہا:وہ کوئی گانے والیاں نہ تھیں۔حضرت ابو بکر رضی اللہ تعالیٰ عنہ نے(انھیں دیکھ کر) کہا:کیا رسول اللہ صلی اللہ علیہ وسلم کے گھر میں شیطان کی آواز(بلند ہورہی) ہے؟اور یہ عید کے دن ہوا تھا۔اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"ابو بکر!ہر قوم کے لئے ایک عید ہے اور یہ ہماری عید ہے۔\""}],[2004,"ابو معاویہ نے ہشام بن عروہ سے اسی سند کے ساتھ ( سابقہ حدیث کے مانند ) روایت کی اور اس میں ہے دو بچیاں دف سے کھیل ہی تھیں ( دف بجارہیں تھیں)","",{"u2":"ابو معاویہ نے ہشام بن عروہ سے اسی سند کے ساتھ (سابقہ حدیث کے مانند) روایت کی اور اس میں ہے دو بچیاں دف سے کھیل ہی تھیں(دف بجارہیں تھیں)"}],[2005,"عمرو نے کہا کہ ابن شہاب نے انھیں عروہ سے حدیث سنائی اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ( انھوں نے کہا ) کہ سیدنا ابو بکر رضی اللہ تعالیٰ عنہ میرے ہاں تشریف لائے جبکہ منیٰ کے ایام میں میرے پاس دو بچیاں گارہی تھیں ۔ اور دف بجا رہی تھیں ۔ اور رسول اللہ صلی اللہ علیہ وسلم کپڑا اوڑھے لیٹے ہوئے تھے ، ابو بکر رضی اللہ تعالیٰ عنہ ان دونوں کو ڈانٹا ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے اپنے آپ سے کپڑا ہٹایا اور فرمایا : \" ابو بکر!انھیں چھوڑیئے کہ یہ عید کے دن ہیں ۔ \" اور ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے ) کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ مجھے اپنی چادر سے چھپائے ہوئے تھے اور میں حبشیوں کو دیکھ رہی تھی کہ وہ کھیل رہے تھے اور میں کم سن لڑکی تھی ، ذرا اندازہ لگاؤ اس لڑکی کو شوق کس قدر ہوگا جو کھیل کی شوقین ، نو عمر تھی ( وہ کتنی دیر کھیل دیکھے گی؟)","",{"u2":"عمرو نے کہا کہ ابن شہاب نے انھیں عروہ سے حدیث سنائی اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی(انھوں نے کہا)کہ حضرت ابو بکر رضی اللہ تعالیٰ عنہ میرے ہاں تشریف لائے جبکہ منیٰ کے ایام میں میرے پاس دو بچیاں گارہی تھیں۔اور دف بجا رہی تھیں۔اور رسول اللہ صلی اللہ علیہ وسلم کپڑا اوڑھے لیٹے ہوئے تھے،ابو بکر رضی اللہ تعالیٰ عنہ ان دونوں کو ڈانٹا۔اس پر رسول اللہ صلی اللہ علیہ وسلم نے اپنے آپ سے کپڑا ہٹایا اور فرمایا:\"ابو بکر!انھیں چھوڑیئے کہ یہ عید کے دن ہیں۔\"اور(حضرت عائشہ رضی اللہ تعالیٰ عنہا نے)کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ مجھےاپنی چادر سے چھپائے ہوئے تھے اور میں حبشیوں کو دیکھ رہی تھی کہ وہ کھیل رہے تھے اور میں کم سن لڑکی تھی،ذرا اندازہ لگاؤ اس لڑکی کو شوق کس قدر ہوگا جو کھیل کی شوقین،نو عمر تھی(وہ کتنی دیر کھیل دیکھے گی؟)"}],[2006,"یونس نے ابن شہاب سے او انھوں نے عروہ بن زبیر سے روایت کی ، انھوں نے کہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : اللہ کی قسم !میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھاکہ آپ صلی اللہ علیہ وسلم میرے حجرے کے دروازے پر کھڑے ہیں اور حبشی اپنے چھوٹے نیزوں کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کی مسجد میں کھیل ( مشقین کر رہے ) رہے تھے ۔ اور آپ مجھے اپنی چادر سے چھپائے ہوئے ہیں تاکہ میں ان کے کرتب دیکھ سکوں ، پھر آپ میری خاطر کھڑے رہے حتیٰ کہ میں ہی ہوں جو واپس پلٹی ، اندازہ کرو ایک نو عمر لڑکی کا شوق کس قدر ہوگا جو کھیل کی شوقین ہو ( کتنی دیر تک کھڑی رہی ہوگی ۔)","",{"u2":"یونس نے ابن شہاب سے او انھوں نے عروہ بن زبیر سے روایت کی،انھوں نے کہا:حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا:اللہ کی قسم!میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھاکہ آپ صلی اللہ علیہ وسلم میرے حجرے کے دروازے پر کھڑے ہیں اور حبشی اپنے چھوٹے نیزوں کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کی مسجد میں کھیل (مشقین کر رہے)رہے تھے۔اور آپ مجھے اپنی چادر سے چھپائے ہوئے ہیں تاکہ میں ان کے کرتب دیکھ سکوں،پھر آپ میری خاطر کھڑے رہے حتیٰ کہ میں ہی ہوں جو واپس پلٹی،اندازہ کرو ایک نو عمر لڑکی کا شوق کس قدر ہوگا جو کھیل کی شوقین ہو(کتنی دیر تک کھڑی رہی ہوگی۔)"}],[2007,"محمد بن عبد الرحمان نے عروہ سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سےروایت کی ، انھوں نےکہا : رسول اللہ صلی اللہ علیہ وسلم ( گھر میں ) داخل ہوئے جبکہ میرے پاس دو بچیاں جنگ بعاث کے اشعار بلند آواز سے سنا رہی تھیں ۔ آپ بستر پر لیٹ گئے اور اپنا چہرہ ( دوسری سمیت ) پھیر لیا ۔ اس کے بعد سیدنا ابو بکر رضی اللہ تعالیٰ عنہ تشریف لائے ۔ تو انھوں نے مجھے سرزنش کی اور کہا : رسول اللہ صلی اللہ علیہ وسلم کی موجودگی میں شیطان کی آواز؟اس پر رسول اللہ صلی اللہ علیہ وسلم ان کی طرف متوجہ ہوئے اور فرمایا : \" انھیں چھوڑیئے \" جب ان ( ابو بکر رضی اللہ تعالیٰ عنہ ) کی توجہ ہٹی تو میں ان کو اشارہ کیا اور وہ چلی گئیں ۔ اور عید کا ایک دن تھا ، کالے لوگ ڈھالوں اور بھالوں کےکرتب دکھا رہے تھے تو میں نے رسول اللہ صلی اللہ علیہ وسلم سے د رخواست کی یا آپ نے خود ہی فرمایا : \" دیکھنے کی خواہش رکھتی ہو؟ \" میں نے کہا : جی ہاں ۔ آ پ نے مجھے اپنے پیچھے کھڑاکرلیا ، میرا رخسار آپ کے رخسار پر ( لگ رہا ) تھا اور آ پ فرمارہے تھے : \" اے ارفدہ کے بیٹو! ( اپنا مظاہرہ ) جاری رکھو ۔ \" حتیٰ کہ جب میں اکتا گئی ( تو ) آپ صلی اللہ علیہ وسلم نے فرمایا : \" تمھارے لئے کافی ہے؟ \" میں نے کہا : جی ہاں ۔ فرمایا : \" تو چلی جاؤ ۔","",{"u2":"محمد بن عبد الرحمان نے عروہ سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سےروایت کی،انھوں نےکہا:رسول اللہ صلی اللہ علیہ وسلم (گھر میں) داخل ہوئے جبکہ میرے پاس دو بچیاں جنگ بعاث کے اشعار بلندآواز سے سنارہی تھیں۔آپ بستر پرلیٹ گئے اور اپنا چہرہ (دوسری سمیت) پھیر لیا۔اس کے بعدحضرت ابو بکر رضی اللہ تعالیٰ عنہ تشریف لائے۔تو انھوں نے مجھے سرزنش کی اور کہا:رسول اللہ صلی اللہ علیہ وسلم کی موجودگی میں شیطان کی آواز؟اس پر رسول اللہ صلی اللہ علیہ وسلم ان کی طرف متوجہ ہوئے اورفرمایا:\"انھیں چھوڑیئے\"جب ان(ابو بکر رضی اللہ تعالیٰ عنہ) کی توجہ ہٹی تو میں ان کو اشارہ کیا اور وہ چلی گئیں۔اورعید کا ایک دن تھا،کالے لوگ ڈھالوں اور بھالوں کےکرتب دکھا رہے تھے تو میں نے رسول اللہ صلی اللہ علیہ وسلم سے د رخواست کی یا آپ نے خود ہی فرمایا:\"دیکھنے کی خواہش رکھتی ہو؟\"میں نے کہا:جی ہاں۔آ پ نے مجھے اپنے پیچھے کھڑاکرلیا،میرا رخسار آپ کے رخسار پر(لگ رہا) تھا اور آ پ فرمارہے تھے:\"اے ارفدہ کے بیٹو!(اپنا مظاہرہ) جاری رکھو۔\"حتیٰ کہ جب میں اکتا گئی(تو) آپ صلی اللہ علیہ وسلم نے فرمایا:\"تمھارےلئے کافی ہے؟\"میں نے کہا:جی ہاں۔فرمایا:\"توچلی جاؤ۔\""}],[2008,"جریر نے ہشام سے ، انھوں نے اپنے والد ( عروہ ) سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : حبشی آکر عید کے دن مسجد میں ہتھیاروں کے ساتھ اچھل کود رہے تھے ، ( ہتھیاروں کا مظاہرہ کررہے تھے ) تو رسول اللہ صلی اللہ علیہ وسلم نے مجھے بلایا ، میں نے اپنا سر آپ کے کندھے پر رکھا اور ان کا کھیل ( کرتب ) دیکھنے لگی ( آپ صلی اللہ علیہ وسلم کھڑے رہے ) یہاں تک کہ میں نے خود ہی ان کے کھیل کے نظارے سے واپسی اختیار کی ۔","",{"u2":"جریر نے ہشام سے،انھوں نے اپنے والد(عروہ) سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:حبشی آکر عید کے دن مسجد میں ہتھیاروں کے ساتھ اچھل کود رہے تھے،(ہتھیاروں کا مظاہرہ کررہے تھے)تو رسول اللہ صلی اللہ علیہ وسلم نے مجھے بلایا،میں نے اپنا سر آپ کے کندھے پر رکھا اور ان کا کھیل (کرتب) دیکھنے لگی (آپ صلی اللہ علیہ وسلم کھڑے رہے) یہاں تک کہ میں نے خود ہی ان کے کھیل کے نظارے سے واپسی اختیار کی۔"}],[2009,"یحییٰ بن زکریا بن ابی زائدہ اور محمد بن بشر دونوں نے ہشام سے اسی سندکے ساتھ ( سابقہ حدیث کی طرح ) روایت کی اور انھوں نےفي المسجد ( مسجد میں ) کے الفاظ ذکر نہیں کیے ۔","",{"u2":"یحییٰ بن زکریا بن ابی زائدہ اور محمد بن بشر دونوں نے ہشام سے اسی سندکے ساتھ(سابقہ حدیث کی طرح) روایت کی اور انھوں نےفی المسجد(مسجد میں) کے الفاظ ذکر نہیں کیے۔"}],[2010,"عطاء نے بتایا کہ مجھے عبید بن عمیر نے خبر دی ، انھوں نے کہا : مجھے سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے خبر دی کہ انھوں نے کھیلنے والوں کے بارے میں کہا : میں ان کا کھیل دیکھناچاہتی ہوں ۔ کہا : اس پر رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوگئے اور میں دروازے پر کھڑی ہوکر آپ کے کانوں اور کندھوں کےدرمیان سے دیکھنے لگی اور وہ لوگ مسجد میں کھیل رہے تھے ۔ عطاء نے کہا : وہ ایرانی تھے یا حبشی ۔ اور کہا : مجھے ابن عتیق یعنی عبید بن عمیر نے بتایا کہ وہ حبشی تھے ۔","",{"u2":"عطاء نے بتایا کہ مجھے عبید بن عمیر نے خبر دی،انھوں نے کہا:مجھے حضرت عائشہ رضی اللہ تعالیٰ عنہا نے خبر دی کہ انھوں نے کھیلنے والوں کے بارے میں کہا:میں ان کاکھیل دیکھناچاہتی ہوں۔کہا:اس پر رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوگئے اور میں دروازے پر کھڑی ہوکر آپ کے کانوں اور کندھوں کےدرمیان سے دیکھنے لگی اور وہ لوگ مسجد میں کھیل رہے تھے۔\nعطاء نے کہا:وہ ایرانی تھے یا حبشی۔اور کہا:مجھے ابن عتیق یعنی عبید بن عمیر نے بتایا کہ وہ حبشی تھے۔"}],[2011,"سیدنا ابوہریرۃ رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : جبکہ حبشی رسول اللہ صلی اللہ علیہ وسلم کے سامنے اپنے بھالوں سے کھیل رہے تھے تو سیدنا عمر بن خطاب رضی اللہ تعالیٰ عنہ پہنچ گئے اور کنکریاں اٹھانے کے لئے جھکے تاکہ وہ انھیں کنکریاں ماریں تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا : \" عمر!انھیں چھوڑ دو ۔","",{"u2":"حضرت ابوہریرۃ رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے کہا:جبکہ حبشی رسول اللہ صلی اللہ علیہ وسلم کے سامنے اپنے بھالوں سے کھیل رہے تھے توحضرت عمر بن خطاب رضی اللہ تعالیٰ عنہ پہنچ گئے اور کنکریاں اٹھانے کے لئے جھکے تاکہ وہ انھیں کنکریاں ماریں تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا:\"عمر!انھیں چھوڑ دو۔\""}],[2012,"امام مالکؒ نے عبداللہ بن ابی بکر سے روایت کی ، انھوں نے عباد بن تمیم سے سنا ، وہ کہہ رہے تھے : میں نے سیدنا عبداللہ بن زید مازنی رضی اللہ تعالیٰ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم ( مدینہ سے ) باہر نکل کرعیدگاہ گئے ، بارش مانگی اور جب آپ قبلہ رخ ہوئے تو اپنی چادر کو پلٹا ۔","",{"u2":"امام مالک رحمہ اللہ نے عبداللہ بن ابی بکر سے روایت کی،انھوں نے عباد بن تمیم سے سنا،وہ کہہ رہے تھے:میں نے حضرت عبداللہ بن زید مازنی رضی اللہ تعالیٰ عنہ سے سنا،وہ کہہ رہے تھے:رسول اللہ صلی اللہ علیہ وسلم (مدینہ سے) باہر نکل کرعیدگاہ گئے،بارش مانگی اور جب آپ قبلہ رخ ہوئے تواپنی چادر کو پلٹا۔"}],[2013,"سفیان بن عینیہ نے عبداللہ بن ابی بکر سے ، انھوں نے عباد بن تمیم سے اور انھوں نے اپنے چچا ( عبداللہ بن زید رضی اللہ تعالیٰ عنہ ) سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ( مدینہ سے ) نکل کر عیدگاہ تشریف لے گئے اور بارش کی دعاکی ، آپ نے قبلے کی طرف رخ کیا ، اپنی چادرپلٹی اوردو رکعت نماز پڑھی ۔","",{"u2":"سفیان بن عینیہ نے عبداللہ بن ابی بکر سے،انھوں نے عباد بن تمیم سے اور انھوں نے اپنے چچا(عبداللہ بن زید رضی اللہ تعالیٰ عنہ) سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم (مدینہ سے) نکل کر عیدگاہ تشریف لے گئے اور بارش کی دعاکی،آپ نے قبلے کی طرف رخ کیا،اپنی چادرپلٹی اوردو رکعت نماز پڑھی۔"}],[2014,"ابو بکربن محمد بن عمرو نے بتایا کہ ان کو عبادبن تمیم نے خبر دی ، ان کو سیدنا عبداللہ بن زید انصاری رضی اللہ تعالیٰ عنہ نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم بارش کی دعا کرنے کےلئے عید گاہ گئے اور جب آپ نے دعا کرنے کا ارادہ فرمایا تو قبلہ کی طرف رخ کرلیا اور اپنی چادر کو پلٹ دیا ۔","",{"u2":"ابو بکربن محمد بن عمرو نے بتایا کہ ان کو عبادبن تمیم نے خبر دی،ان کوحضرت عبداللہ بن زیدانصاری رضی اللہ تعالیٰ عنہ نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم بارش کی دعاکرنے کےلئے عید گاہ گئے اور جب آپ نے دعا کرنے کا ارادہ فرمایا تو قبلہ کی طرف رخ کرلیا اور اپنی چادر کو پلٹ دیا۔"}],[2015,"ابن شہاب نے کہا : مجھے عباد بن تمیم مازنی نے خبر دی ، انھوں نے اپنے چچا سے سنا اور وہ نبی کریم صلی اللہ علیہ وسلم کے ساتھیوں میں سے تھے وہ کہہ رہے تھے : ایک دن رسول اللہ صلی اللہ علیہ وسلم بارش کی دعا مانگنے کے لئے نکلے ، اللہ سے دعا کرتے ہوئے اپنی پشت لوگوں کی طرف کی ، منہ قبلہ کی طرف کیا اور اپنی چادر پلٹی ، پھر دو رکعت نماز ادا کی ۔","",{"u2":"ابن شہاب نے کہا:مجھےعباد بن تمیم مازنی نے خبر دی،انھوں نے اپنے چچاسے سنا اور وہ نبی کریم صلی اللہ علیہ وسلم کے ساتھیوں میں سے تھے وہ کہہ رہے تھے:ایک دن رسول اللہ صلی اللہ علیہ وسلم بارش کی دعا مانگنےکے لئے نکلے،اللہ سے دعاکرتے ہوئے اپنی پشت لوگوں کی طرف کی،منہ قبلہ کی طرف کیا اوراپنی چادر پلٹی،پھر دو رکعت نمازادا کی۔"}],[2016,"شعبہ نے ثابت سے اورانھوں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے روایت کی کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ، آپ دعا کے لئے دونوں ہاتھ اٹھاتے حتیٰ کہ آپ کی بغلوں کی سفیدی نظر آتی تھی ۔","",{"u2":"شعبہ نے ثابت سے اورانھوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے روایت کی کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا،آپ دعا کے لئے دونوں ہاتھ اٹھاتے حتیٰ کہ آپ کی بغلوں کی سفیدی نظر آتی تھی۔"}],[2017,"حمادبن سلمہ نے ثابت سے اور انھوں نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے ر وایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے بارش مانگنے کے لیے دعا فرمائی تو اپنے ہاتھوں کی پشت کے ساتھ آسمان کی طرف اشارہ کیا ۔","",{"u2":"حمادبن سلمہ نے ثابت سے اور انھوں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے ر وایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے بارش مانگنے کے لیے دعا فرمائی تو اپنے ہاتھوں کی پشت کے ساتھ آسمان کی طرف اشارہ کیا۔"}],[2018,"ابن ابی عدی اور عبدالاعلیٰ نے سعید ( بن ابی عروبہ ) سے ، انھوں نے قتادہ سے اور انھوں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم استسقاء کے سوا کسی اور دعا کے لئے اپنے ہاتھ ( اتنے زیادہ ) بلند نہیں کرتےتھے ۔ یہاں تک کہ اس سے آپ کی بغلوں کی سفیدی دیکھائی دینے لگتی ، البتہ عبدالاعلیٰ نے ( شک کے ساتھ ) کہا \" يري بياض ابطه اوبياض ابطيه \" ( آپ کی بغل کی سفیدی یا دونوں بغلوں کی سفیدی دیکھائی دینے لگتی ۔)","",{"u2":"ابن ابی عدی اور عبدالاعلیٰ نے سعید(بن ابی عروبہ) سے،انھوں نے قتادہ سے اور انھوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم استسقاء کے سوا کسی اور دعا کے لئے اپنے ہاتھ(اتنے زیادہ) بلند نہیں کرتےتھے۔یہاں تک کہ اس سے آپ کی بغلوں کی سفیدی دیکھائی دینے لگتی،البتہ عبدالاعلیٰ نے(شک کے ساتھ) کہا\" یری بیاض ابطہ اوبیاض ابطیہ \"(آپ کی بغل کی سفیدی یا دونوں بغلوں کی سفیدی دیکھائی دینے لگتی۔)"}],[2019,"یحییٰ بن سعید نے ( سعید ) بن ابی عروبہ سے اور انھوں نے قتادہ سے روایت کی کہ ان کو سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے اسی ( سابقہ حدیث ) کے ہم معنی حدیث بیان کی ۔","",{"u2":"یحییٰ بن سعید نے(سعید) بن ابی عروبہ سے اور انھوں نے قتادہ سے روایت کی کہ ان کو حضرت انس بن مالک رضی اللہ تعالیٰ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے اسی(سابقہ حدیث) کے ہم معنی حدیث بیان کی۔"}],[2020,"شریک بن ابی نمر نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی کہ جمعے کے روز ایک آدمی اس دروازے سے مسجد میں داخل ہوا جو دارالقضاء کی طرف تھا اور رسول اللہ صلی اللہ علیہ وسلم کھڑے خطبہ ارشاد فرمارہے تھے ، اس نے کھڑے کھڑے رسول اللہ صلی اللہ علیہ وسلم کی طرف رخ کیا ، پھر کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم !مال مویشی ہلاک ہوگئے اور راستے منقطع ہوچکے ، اللہ تعالیٰ سے دعا فرمائیں کہ وہ ہمیں بارش عطا کرے ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھ اٹھا دیئے ، پھر کہا : \"\" اے اللہ!ہمیں بارش عنایت فرما ، اے اللہ!ہمیں بارش عنایت فرما ، اے اللہ!ہمیں بارش سے نوازدے ۔ \"\" سیدنا انس رضی اللہ تعالیٰ عنہ نے کہا : اللہ کی قسم!ہم آسمان میں نہ کوئی گھٹا دیکھ رہے تھے اور نہ بادل کا کوئی ٹکڑا ۔ ہمارے اور سلع پہاڑ کے درمیان کوئی گھر تھا نہ محلہ ۔ پھر اس کے پیچھے سے ڈھال جیسی چھوٹی سی بدلی اٹھی ، جب وہ آسمان کے وسط میں پہنچی تو پھیل گئی ، پھر وہ برسی ، اللہ کی قسم!ہم نے ہفتہ بھر سورج نہ دیکھا ۔ پھر اگلے جمعے اسی دروازے سے ایک آدمی داخل ہوا ، رسول اللہ صلی اللہ علیہ وسلم کھڑے خطبہ ارشاد فرمارہے تھے ، اس نے کھڑے کھڑے آپ صلی اللہ علیہ وسلم کی طرف رخ کرکے کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم ! ( بارش کی کثرت سے ) مال مویشی ہلاک ہوگئے اور راستے بند ہوگئے ، اس لئے اللہ تعالیٰ سے دعا فرمائیں کہ وہ ہم سے بارش روک لے ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے دونوں ہاتھ اٹھا دیے ، پھر فرمایا : \"\" اے اللہ!ہمارے ارد گرد ( بارش برسا ) ہم پر نہیں ، اے اللہ!پہاڑیوں پر ، ٹیلوں پر ، وادیوں کے اندر ( ندیوں میں ) اور درخت اگنے کے مقامات پر ( برسا ۔ ) \"\" کہا : \"\" ( فوراً ) بادل چھٹ گئے اور ہم ( مسجد سے ) نکلے تو دھوپ میں چل رہے تھے ۔ شریک نے کہا : میں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے پوچھا : کیا وہ پہلے آدمی تھا؟انھوں نے جواب دیا : میں نہیں جانتا ۔","",{"u2":"شریک بن ابی نمر نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی کہ جمعے کے روز ایک آدمی اس دروازے سے مسجد میں داخل ہوا جو دارالقضاء کی طرف تھا اور رسول اللہ صلی اللہ علیہ وسلم کھڑے خطبہ ارشاد فرمارہے تھے،اس نے کھڑے کھڑے رسول اللہ صلی اللہ علیہ وسلم کی طرف رخ کیا،پھر کہا:اےاللہ کے رسول صلی اللہ علیہ وسلم!مال مویشی ہلاک ہوگئے اور راستے منقطع ہوچکے،اللہ تعالیٰ سے دعا فرمائیں کہ وہ ہمیں بارش عطا کرے۔اس پر رسول اللہ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھ اٹھا دیئے،پھر کہا:\"اے اللہ!ہمیں بارش عنایت فرما،اے اللہ!ہمیں بارش عنایت فرما،اے اللہ!ہمیں بارش سے نوازدے۔\"حضرت انس رضی اللہ تعالیٰ عنہ نے کہا:اللہ کی قسم!ہم آسمان میں نہ کوئی گھٹا دیکھ رہے تھے اور نہ بادل کا کوئی ٹکڑا۔ہمارے اور سلع پہاڑ کے درمیان کوئی گھر تھا نہ محلہ۔پھر اس کے پیچھے سے ڈھال جیسی چھوٹی سی بدلی اٹھی،جب وہ آسمان کے وسط میں پہنچی تو پھیل گئی،پھر وہ برسی،اللہ کی قسم!ہم نے ہفتہ بھر سورج نہ دیکھا۔پھر اگلے جمعے اسی دروازے سے ایک آدمی داخل ہوا،رسول اللہ صلی اللہ علیہ وسلم کھڑے خطبہ ارشاد فرمارہے تھے،اس نے کھڑے کھڑے آپ صلی اللہ علیہ وسلم کی طرف رخ کرکے کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!(بارش کی کثرت سے)مال مویشی ہلاک ہوگئے اور راستے بند ہوگئے،اس لئے اللہ تعالیٰ سے دعا فرمائیں کہ وہ ہم سے بارش روک لے۔اس پر رسول اللہ صلی اللہ علیہ وسلم نے دونوں ہاتھ اٹھادیے،پھر فرمایا:\"اے اللہ!ہمارے ارد گرد(بارش برسا) ہم پر نہیں،اے اللہ!پہاڑیوں پر،ٹیلوں پر،وادیوں کے اندر(ندیوں میں)اور درخت اگنے کے مقامات پر(برسا۔)\"کہا:\"(فوراً)بادل چھٹ گئے اور ہم(مسجد سے) نکلے تو دھوپ میں چل رہے تھے۔\nشریک نے کہا:میں نے حضرت انس رضی اللہ تعالیٰ عنہ سے پوچھا:کیا وہ پہلے آدمی تھا؟انھوں نے جواب دیا:میں نہیں جانتا۔"}],[2021,"اسحاق بن عبداللہ بن ابی طلحہ نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نےکہا : رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگوں کوخشک سالی نے آلیا ۔ اسی اثنا میں کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن منبر پر لوگوں کے سامنے خطبہ دے رہے تھے کہ اچانک ایک بدوی کھڑا ہوا اور کہا : اے اللہ کے رسول : مال مویشی ہلاک ہوگئے ، بال بچے بھوکے مرنے لگے ۔ ۔ ۔ ( آگے ) اسی ( سابقہ حدیث ) کے ہم معنی حدیث بیان کی ۔ اور اس میں ہے ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" ا ے اللہ!ہمارے ارد گرد ( برسا ) ہمارے اوپر نہیں ۔ \" کہا : اور آپ اپنے ہاتھ سے جس طرف بھی اشارہ کرتے تھے اسی طرف سے بادل چھٹ جاتے تھے حتیٰ کہ میں نے مدینہ منورہ کو ( زمین کے ) خالی ٹکڑے کے مانند دیکھا اور وادی قناۃ ایک ماہ تک بہتی رہی اور کسی طرف سے بھی کوئی شخص نہیں آیا مگر اس نے موسلادھار بارش کی خبر دی ۔","",{"u2":"اسحاق بن عبداللہ بن ابی طلحہ نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نےکہا:رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگوں کوخشک سالی نے آلیا۔اسی اثنا میں کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن منبر پر لوگوں کے سامنے خطبہ دے رہے تھے کہ اچانک ایک بدوی کھڑا ہوا اور کہا:اے اللہ کے رسول:مال مویشی ہلاک ہوگئے،بال بچے بھوکے مرنے لگے۔۔۔(آگے) اسی(سابقہ حدیث) کے ہم معنی حدیث بیان کی۔اور اس میں ہے،آپ صلی اللہ علیہ وسلم نے فرمایا:\"ا ے اللہ!ہمارے ارد گرد(برسا)ہمارے اوپر نہیں۔\"کہا:اور آپ اپنے ہاتھ سے جس طرف بھی اشارہ کرتے تھے اسی طرف سے بادل چھٹ جاتے تھےحتیٰ کہ میں نے مدینہ منورہ کو(زمین کے)خالی ٹکڑے کے مانند دیکھا اور وادی قناۃ ایک ماہ تک بہتی رہی اور کسی طرف سے بھی کوئی شخص نہیں آیا مگر اس نے موسلادھار بارش کی خبر دی۔"}],[2022,"عبدالاعلیٰ بن حماد اور محمد بن ابی بکر مقدمی نے کہا : ہمیں معتمر نے حدیث بیا ن کی ، انھوں نے کہا : ہمیں عبیداللہ نے ثابت بنانی سے اور انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن خطبہ دے رہے تھے کہ لوگ آپ کے سامنے کھڑے ہوگئے ، ( بات شروع کرنے والے بدو کے ساتھ دوسرے بھی شامل ہوگئے ) وہ فریاد کرنے لگے اور کہنے لگے : اے اللہ کے نبی !بارش بندہوگئی ، درختوں ( کے پتے سوکھ کر ) سرخ ہوگئے اور مویشی ہلاک ہوگئے ۔ ۔ ۔ اور ( آگے مذکورہ بالا حدیث کے مانند ) حدیث بیان کی ۔ اس میں عبدالاعلیٰ کی روایت سے یہ ( الفاظ ) ہیں : مدینہ سے بادل چھٹ گئے اور اس کے ارد گرد بارش برسانے لگے جبکہ مدینہ میں ایک قطرہ بھی نہیں برس رہاتھا میں نے مدینہ کو دیکھا وہ ایک طرح کے تاج کے اندر ( بارش سے محفوظ ) تھا ۔","",{"u2":"عبدالاعلیٰ بن حماد اور محمد بن ابی بکر مقدمی نے کہا:ہمیں معتمر نے حدیث بیا ن کی،انھوں نے کہا:ہمیں عبیداللہ نے ثابت بنانی سے اور انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن خطبہ دے رہے تھے کہ لوگ آپ کے سامنے کھڑے ہوگئے،(بات شروع کرنے والے بدو کے ساتھ دوسرے بھی شامل ہوگئے)وہ فریاد کرنے لگے اور کہنے لگے:اےاللہ کے نبی!بارش بندہوگئی،درختوں(کے پتے سوکھ کر) سرخ ہوگئے اور مویشی ہلاک ہوگئے۔۔۔اور(آگے مذکورہ بالا حدیث کے مانند) حدیث بیان کی۔اس میں عبدالاعلیٰ کی روایت سے یہ (الفاظ) ہیں:مدینہ سے بادل چھٹ گئے اور اس کے ارد گرد بارش برسانے لگے جبکہ مدینہ میں ایک قطرہ بھی نہیں برس رہاتھا میں نے مدینہ کو دیکھا وہ ایک طرح کے تاج کے اندر(بارش سے محفوظ) تھا۔"}],[2023,"سلمان بن مغیرۃ نے ثابت اور انھوں نے سیدنا انس رضی اللہ تعالیٰ عنہ سے اسی کے ہم معنی روایت کی اور یہ اضافہ کیا : اللہ تعالیٰ نے بادلوں کو جوڑ دیا اور ہم اسی ( حالت ) میں رہے حتیٰ کہ میں نے دیکھا ایک قوی اور مضبوط آدمی کو بھی اس کا دل ( بارش کی کثرت کی بناء پر ) اس فکر میں مبتلا کردیتاتھا کہ وہ ا پنے اہل وعیال کے پاس پہنچے ۔","",{"u2":"سلمان بن مغیرۃ نے ثابت اور انھوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے اسی کے ہم معنی روایت کی اور یہ اضافہ کیا:اللہ تعالیٰ نے بادلوں کو جوڑ دیا اور ہم اسی(حالت) میں رہے حتیٰ کہ میں نے دیکھا ایک قوی اور مضبوط آدمی کو بھی اس کا دل(بارش کی کثرت کی بناء پر) اس فکر میں مبتلا کردیتاتھا کہ وہ ا پنے اہل وعیال کے پاس پہنچے۔"}],[2024,"حفص بن عبیداللہ بن انس بن مالک نے بیان کیاکہ انھوں نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے سنا ، وہ کہہ رہے تھے : جمعے کے دن ایک اعرابی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا جبکہ آپ منبر پر تھے ۔ ۔ ۔ ( آگے مذکورہ بالاحدیث کے مانند ) حدیث بیان کی اور اس میں یہ اضافہ کیا : میں نے بادل کو دیکھاوہ اس طرح چھٹ رہا تھا جیسے وہ ایک بڑی چادر ہوجب اسے لپیٹا جارہا ہو ۔","",{"u2":"حفص بن عبیداللہ بن انس بن مالک نے بیان کیاکہ انھوں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے سنا،وہ کہہ رہے تھے:جمعے کے دن ایک اعرابی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا جبکہ آپ منبر پر تھے۔۔۔(آگے مذکورہ بالاحدیث کے مانند) حدیث بیان کی اور اس میں یہ اضافہ کیا:میں نے بادل کو دیکھاوہ اس طرح چھٹ رہا تھا جیسے وہ ایک بڑی چادر ہوجب اسے لپیٹا جارہا ہو۔"}],[2025,"سیدنا انس رضی اللہ تعالیٰ عنہ نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ ہم پر بارش برسنے لگی تو رسول اللہ صلی اللہ علیہ وسلم اپنا ( سر اور کندھے کا کپڑا ) کھول دیا حتیٰ کہ بارش آپ پر آنے لگی ۔ ہم نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم !آپ نے ایسا کیوں کیا؟آپ نے فرمایا : \" کیونکہ وہ نئی نئی ( سیدھی ) اپنے رب عزوجل کی طرف سے آرہی ہے ۔","",{"u2":"حضرت انس رضی اللہ تعالیٰ عنہ نے کہا:ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ ہم پر بارش برسنے لگی تو رسول اللہ صلی اللہ علیہ وسلم اپنا(سر اور کندھے کا کپڑا) کھول دیا حتیٰ کہ بارش آپ پر آنے لگی۔ہم نے عرض کی:اے اللہ کے رسول صلی اللہ علیہ وسلم!آپ نے ایسا کیوں کیا؟آپ نے فرمایا:\"کیونکہ وہ نئی نئی (سیدھی) اپنے رب عزوجل کی طرف سے آرہی ہے۔\""}],[2026,"جعفر بن محمد نے عطاء بن ابی ر باح سے روایت کی انھوں نے نبی کریم صلی اللہ علیہ وسلم کی ذوجہ محترمہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا کو کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم کی عادت مبارکہ تھیں کہ جب آندھی یا بادل کا دن ہوتا تو آپ کے چہرہ مبارک پر اس کا اثر پہچانا جاسکتا تھا ، آپ صلی اللہ علیہ وسلم ( اضطراب کے عالم میں ) کبھی آگے جاتے اور کبھی پیچھے ہٹتے ، پھر جب بارش برسناشروع ہوجاتی تو آپ اس سے خوش ہوجاتے اور وہ ( پہلی کیفیت ) آ پ سے دور ہوجاتی ، سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : میں نے ( ایک بار ) آپ سے ( اس کا سبب ) پوچھا تو آپ نے فرمایا : \" میں ڈر گیا کہ یہ عذاب نہ ہو جو میری امت پر مسلط کردیا گیا ہو \" اور بارش کو دیکھ لیتے تو فرماتے \" رحمت ہے ۔","",{"u2":"جعفر بن محمد نے عطاء بن ابی ر باح سے روایت کی انھوں نے نبی کریم صلی اللہ علیہ وسلم کی ذوجہ محترمہ حضرت عائشہ رضی اللہ تعالیٰ عنہا کو کہتے ہوئے سنا:رسول اللہ صلی اللہ علیہ وسلم کی عادت مبارکہ تھیں کہ جب آندھی یا بادل کا دن ہوتا تو آپ کے چہرہ مبارک پر اس کا اثر پہچانا جاسکتا تھا،آپ صلی اللہ علیہ وسلم (اضطراب کے عالم میں)کبھی آگے جاتے اور کبھی پیچھے ہٹتے،پھر جب بارش برسناشروع ہوجاتی تو آپ اس سے خوش ہوجاتے اور وہ(پہلی کیفیت) آ پ سے دور ہوجاتی،حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا:میں نے(ایک بار) آپ سے(اس کا سبب) پوچھا تو آپ نے فرمایا:\"میں ڈر گیا کہ یہ عذاب نہ ہو جو میری امت پر مسلط کردیا گیا ہو\"اور بارش کو دیکھ لیتے تو فرماتے\"رحمت ہے۔\""}],[2027,"ابن جریج عطاء بن ابی رباح سے حدیث بیان کرتے ہیں ، انھوں نے نبی اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روای کی کہ انھوں نے کہا : جب تیز ہوا چلتی تو نبی اکرم صلی اللہ علیہ وسلم فرمایا کرتے : \" اے اللہ!میں تجھ سے اس کی خیر اور بھلائی کا سوا ل کرتا ہوں ۔ اور جو اس میں ہے اس کی اور جو کچھ اس کے زریعے بھیجا گیا ہے اس کی خیر ( کا طلبگار ہوں ) اور اس کے شر سے اور جو کچھ اس میں ہے اور جو اس میں بھیجا گیا ہے ا س کے شر سے تیری پناہ چاہتاہوں \" ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے ) کہا : جب آسمان پر بادل گھر آتے تو آپ صلی اللہ علیہ وسلم کا رنگ بدل جاتا اور آ پ ( اضطراب کے عالم میں ) کبھی باہر نکلتے اور کبھی اندر آتے ، کبھی آگے بڑھتے اور کبھی پیچھے ہٹتے ، اس کے بعد جب بارش برسنے لگتی تو آپ صلی اللہ علیہ وسلم سے ( یہ کیفیت ) دورہوجاتی ، مجھے اس کیفیت کا پتہ چل گیا ، سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : تو میں نے آپ صلی اللہ علیہ وسلم سے پوچھا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" عائشہ!ہوسکتاہے ( یہ اسی طرح ہو ) جیسے قوم عاد نے ( بادلوں کو دیکھ کر ) کہا تھا : \" جب انھوں نے اس ( عذاب ) کو بادل کی طرح اپنی بستیوں کی طرف آتے دیکھا تو انھوں نے کہا : یہ بادل ہے جو ہم پربرسے گا ۔","",{"u2":"ابن جریج عطاء بن ابی رباح سے حدیث بیان کرتے ہیں،انھوں نے نبی اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روای کی کہ انھوں نے کہا:جب تیز ہوا چلتی تو نبی اکرم صلی اللہ علیہ وسلم فرمایا کرتے:\"اے اللہ!میں تجھ سے اس کی خیر اور بھلائی کا سوا ل کرتا ہوں۔اور جو اس میں ہے اس کی اور جو کچھ اس کے زریعے بھیجا گیا ہے اس کی خیر(کا طلبگار ہوں) اور اس کے شر سے اور جو کچھ اس میں ہے اور جو اس میں بھیجا گیا ہے ا س کے شر سے تیری پناہ چاہتاہوں\"(حضرت عائشہ رضی اللہ تعالیٰ عنہا نے)کہا:جب آسمان پر بادل گھر آتے تو آپ صلی اللہ علیہ وسلم کا رنگ بدل جاتا اور آ پ(اضطراب کے عالم میں) کبھی باہر نکلتے اور کبھی اندر آتے،کبھی آگے بڑھتے اور کبھی پیچھے ہٹتے،اس کے بعد جب بارش برسنے لگتی تو آپ صلی اللہ علیہ وسلم سے(یہ کیفیت) دورہوجاتی،مجھے اس کیفیت کا پتہ چل گیا،حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا:تومیں نے آپ صلی اللہ علیہ وسلم سے پوچھا۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"عائشہ!ہوسکتاہے(یہ اسی طرح ہو) جیسے قوم عاد نے(بادلوں کو دیکھ کر)کہا تھا:\"جب انھوں نے اس (عذاب) کو بادل کی طرح اپنی بستیوں کی طرف آتے دیکھا تو انھوں نے کہا:یہ بادل ہے جو ہم پربرسے گا۔\""}],[2028,"سلمان بن یسار نے نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ محترمہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ انھوں نے کہا : میں نے اللہ کے رسول صلی اللہ علیہ وسلم کو کبھی پوری طرح ایسا ایسےہنستا ہو انہیں دیکھاکہ میں آپ کے حلق مبارک کے اندر کا ابھرا ہوا حصہ دیکھ لوں ، آپ صلی اللہ علیہ وسلم صرف مسکرایا کرتے تھے ، اور جب آپ صلی اللہ علیہ وسلم بادل یا آندھی دیکھتے تو اس کا اثرآپ کے چہرہ انور پرعیاں ہوجاتا تو ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے ) کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم !میں لوگوں کو دیکھتی ہوں کہ جب بادل دیکھتے ہیں تو اس اُمید پر خوش ہوجاتے ہیں کہ اس میں بارش ہوگی اور میں آپ صلی اللہ علیہ وسلم کو دیکھتی ہوں کہ جب آپ اس ( بادل ) دیکھتے ہیں تو میں آپ کے چہرے پر ناپسندیدگی محسوس کرتی ہوں؟سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : آپ صلی اللہ علیہ وسلم نے فرمایا : \" عائشہ!مجھے اس بات سے کیا چیز امن دلا سکتی ہے کہ کہیں ان میں عذاب ( نہ ) ہو ، ایک قوم آندھی کے عذاب کا شکار ہوئی تھی اور ایک قوم نے عذاب کو ( دور ) سے دیکھا تو کہا : \" یہ بادل ہے جو ہم پر بارش برسائے گا ۔","",{"u2":"سلمان بن یسار نے نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ محترمہ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ انھوں نے کہا:میں نے اللہ کے رسول صلی اللہ علیہ وسلم کو کبھی پوری طرح ایسا ایسےہنستا ہوانہیں دیکھاکہ میں آپ کے حلق مبارک کے اندر کا ابھرا ہواحصہ دیکھ لوں،آپ صلی اللہ علیہ وسلم صرف مسکرایا کرتے تھے،اور جب آپ صلی اللہ علیہ وسلم بادل یا آندھی دیکھتے تو اس کا اثرآپ کے چہرہ انور پرعیاں ہوجاتا تو(حضرت عائشہ رضی اللہ تعالیٰ عنہا نے)کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!میں لوگوں کو دیکھتی ہوں کہ جب بادل دیکھتے ہیں تو اس اُمید پر خوش ہوجاتے ہیں کہ اس میں بارش ہوگی اور میں آپ صلی اللہ علیہ وسلم کو دیکھتی ہوں کہ جب آپ اس(بادل)دیکھتے ہیں تو میں آپ کے چہرے پر ناپسندیدگی محسوس کرتی ہوں؟حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا:آپ صلی اللہ علیہ وسلم نے فرمایا:\"عائشہ!مجھے اس بات سے کیا چیز امن دلا سکتی ہے کہ کہیں ان میں عذاب(نہ)ہو،ایک قوم آندھی کے عذاب کا شکار ہوئی تھی اور ایک قوم نے عذاب کو(دور) سے دیکھا تو کہا:\"یہ بادل ہے جو ہم پر بارش برسائے گا۔\""}],[2029,"مجاہد نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے ، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" بادصبا ( مشرقی سمت سے چلنے والی ہوا ) سے میری مدد کی گئی ہے اور باددبور ( مغربی سمت سے چلنے والی ہوا ) سے قوم عاد کو ہلاک کیا گیا ۔","",{"u2":"مجاہد نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے،انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\"بادصبا(مشرقی سمت سے چلنے والی ہوا)سے میری مدد کی گئی ہے اور باددبور(مغربی سمت سے چلنے والی ہوا) سے قوم عاد کو ہلاک کیا گیا۔\""}],[2030,"سعید بن جبیر نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اس کی مانند روایت کی ۔","",{"u2":"سعید بن جبیر نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اس کی مانند روایت کی۔"}],[2031,"امام مالک بن انس اور عبد اللہ بن نمیر نے کہا : ہمیں ہشام نے اپنے والد عروہ سے حدیث سنا ئی انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روا یت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے زما نے میں سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھنے کے لیے قیام فر ما یا اور بہت ہی لمبا قیام کیا ، پھر آپ نے رکو ع کیا تو انتہا ئی طویل رکوع کیا پھر آپ نے سر اٹھا یا تو انتہائی طویل قیام کیا اور وہ پہلے قیام سے ( کچھ ) کم تھا پھر آپ نے ( دوبارہ ) رکو ع کیا تو بہت لمبا رکو ع کیا اور وہ پہلے رکوع سے کم تھا پھر آپ نے سجدے کیے پھر آپ کھڑے ہو گئے اور قیام کو لمبا کیا وہ پہلے قیام سے کم تھا پھر آپ نے رکوع کیا اور رکوع کو لمبا کیا اور وہ پہلے رکوع سے کم تھا پھر آپ نے اپنا سر اٹھا یا اور قیا م کیا تو بہت لمبا قیام کیا جبکہ وہ پہلے قیام سے کم تھا پھر آپ نے رکوع کیا تو انتہائی طویل رکوع کیا لیکن وہ پہلے رکوع سے کم تھا پھر سجدے کیے پھر رسول اللہ صلی اللہ علیہ وسلم ( نماز سے فارغ ہو کر ) پلٹے تو سورج روشن ہو چکا تھا اور آپ نے لو گو ں سے خطا ب فر ما یا اللہ تعالیٰ کی حمدو ثناء بیان کی ، پھر فر ما یا : \"\" بے شک سورج اور چاند اللہ تعا لیٰ کی نشانیوں میں سے ہیں ان کو کسی کی مو ت یا زند گی کی وجہ سے گرہن نہیں لگتا جب تم انھیں ( اس حالت میں ) دیکھو تو اللہ کی بڑائی بیان کرو اللہ تعا لیٰ سے دعا مانگو نماز پڑھو اور صدقہ کرو اے اُمت محمد ( صلی اللہ علیہ وسلم ) کو ئی نہیں جو ( اس بات پر ) اللہ تعالیٰ سے زیادہ غیرت رکھنے والا ہو کہ اس کا بندہ یا اس کی باندی زنا کرے !اے اُمت محمد!اللہ کی قسم !اگر تم ان باتوں کو جان لو جن کو میں جا نتا ہوں ۔ تو تم بہت زیادہ روؤاور بہت کم ہنسو ۔ دیکھو !کیا میں نے ( پیغام ) اچھی طرح پہنچا دیا ؟ \"\" اور امام مالک کی روایت میں ہے : \"\" یقیناً سورج اور چاند اللہ تعا لیٰ کی نشانیوں میں سے دو نشانیاں ہیں ۔"],[2032,"امام مالک بن انس اور عبد اللہ بن نمیر نے کہا : ہمیں ہشام نے اپنے والد عروہ سے حدیث سنا ئی انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روا یت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے زما نے میں سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھنے کے لیے قیام فر ما یا اور بہت ہی لمبا قیام کیا ، پھر آپ نے رکو ع کیا تو انتہا ئی طویل رکوع کیا پھر آپ نے سر اٹھا یا تو انتہائی طویل قیام کیا اور وہ پہلے قیام سے ( کچھ ) کم تھا پھر آپ نے ( دوبارہ ) رکو ع کیا تو بہت لمبا رکو ع کیا اور وہ پہلے رکوع سے کم تھا پھر آپ نے سجدے کیے پھر آپ کھڑے ہو گئے اور قیام کو لمبا کیا وہ پہلے قیام سے کم تھا پھر آپ نے رکوع کیا اور رکوع کو لمبا کیا اور وہ پہلے رکوع سے کم تھا پھر آپ نے اپنا سر اٹھا یا اور قیا م کیا تو بہت لمبا قیام کیا جبکہ وہ پہلے قیام سے کم تھا پھر آپ نے رکوع کیا تو انتہائی طویل رکوع کیا لیکن وہ پہلے رکوع سے کم تھا پھر سجدے کیے پھر رسول اللہ صلی اللہ علیہ وسلم ( نماز سے فارغ ہو کر ) پلٹے تو سورج روشن ہو چکا تھا اور آپ نے لو گو ں سے خطا ب فر ما یا اللہ تعالیٰ کی حمدو ثناء بیان کی ، پھر فر ما یا : \"\" بے شک سورج اور چاند اللہ تعا لیٰ کی نشانیوں میں سے ہیں ان کو کسی کی مو ت یا زند گی کی وجہ سے گرہن نہیں لگتا جب تم انھیں ( اس حالت میں ) دیکھو تو اللہ کی بڑائی بیان کرو اللہ تعا لیٰ سے دعا مانگو نماز پڑھو اور صدقہ کرو اے اُمت محمد ( صلی اللہ علیہ وسلم ) کو ئی نہیں جو ( اس بات پر ) اللہ تعالیٰ سے زیادہ غیرت رکھنے والا ہو کہ اس کا بندہ یا اس کی باندی زنا کرے !اے اُمت محمد!اللہ کی قسم !اگر تم ان باتوں کو جان لو جن کو میں جا نتا ہوں ۔ تو تم بہت زیادہ روؤاور بہت کم ہنسو ۔ دیکھو !کیا میں نے ( پیغام ) اچھی طرح پہنچا دیا ؟ \"\" اور امام مالک کی روایت میں ہے : \"\" یقیناً سورج اور چاند اللہ تعا لیٰ کی نشانیوں میں سے دو نشانیاں ہیں ۔","",{"u2":"امام مالک بن انس اور عبد اللہ بن نمیر نے کہا: ہمیں ہشام نے اپنے والد عروہ سے حدیث سنا ئی انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روا یت کی، انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم کے زما نے میں سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھنے کے لیے قیام فر ما یا اور بہت ہی لمبا قیام کیا، پھر آپ نے رکو ع کیا تو انتہا ئی طویل رکوع کیا پھر آپ نے سر اٹھا یا تو انتہائی طویل قیام کیا اور وہ پہلے قیام سے (کچھ)کم تھا پھر آپ نے (دوبارہ)رکو ع کیا تو بہت لمبا رکو ع کیا اور وہ پہلے رکوع سے کم تھا پھر آپ نے سجدے کیے پھر آپ کھڑے ہو گئے اور قیام کو لمبا کیا وہ پہلے قیام سے کم تھا پھر آپ نے رکوع کیا اور رکوع کو لمبا کیا اور وہ پہلے رکوع سے کم تھا پھر آپ نے اپنا سر اٹھا یا اور قیا م کیا تو بہت لمبا قیام کیا جبکہ وہ پہلے قیام سے کم تھا پھر آپ نے رکوع کیا تو انتہائی طویل رکوع کیا لیکن وہ پہلے رکوع سے کم تھا پھر سجدے کیے پھر رسول اللہ صلی اللہ علیہ وسلم (نماز سے فارغ ہو کر) پلٹے تو سورج روشن ہو چکا تھا اور آپ نے لو گو ں سے خطا ب فر ما یا اللہ تعالیٰ کی حمدو ثناء بیان کی، پھر فر ما یا:\"بے شک سورج اور چاند اللہ تعا لیٰ کی نشانیوں میں سے ہیں ان کو کسی کی مو ت یا زند گی کی وجہ سے گرہن نہیں لگتا جب تم انھیں (اس حالت میں) دیکھو تو اللہ کی بڑائی بیان کرو اللہ تعا لیٰ سے دعا مانگو نماز پڑھو اور صدقہ کرو اے اُمت محمد(صلی اللہ علیہ وسلم)کو ئی نہیں جو (اس بات پر) اللہ تعالیٰ سے زیادہ غیرت رکھنے والا ہو کہ اس کا بندہ یا اس کی باندی زنا کرے!اے اُمت محمد!اللہ کی قسم!اگر تم ان باتوں کو جان لو جن کو میں جا نتا ہوں۔\nتو تم بہت زیادہ روؤاور بہت کم ہنسو۔دیکھو!کیا میں نے (پیغام) اچھی طرح پہنچا دیا؟\"اور امام مالک کی روایت میں ہے:\"یقیناً سورج اور چاند اللہ تعا لیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔"}],[2033,"ابو معاویہ نے ہشام بن عروہ سے اسی سند کے ساتھ ( سابقہ حدیث کے مانند ) روایت کی اور اس میں یہ اضافہ کیا پھر آپ صلی اللہ علیہ وسلم نے فر ما یا : \" امابعد ( حمد و صلاۃ کے بعد ) !بلا شبہ سورج اور چاند اللہ کی نشانیوں میں سے دونشانیاں ہیں ۔ \" اور یہ بھی اضافہ کیا : پھر آپ نے اپنے دونوں ہاتھا اٹھا ئے اور فر ما یا : \" اے اللہ !کیا میں نے ( پیغام ) اچھی طرح پہنچا دیا ؟","",{"u2":"ابو معاویہ نے ہشام بن عروہ سے اسی سند کے ساتھ (سابقہ حدیث کے مانند) روایت کی اور اس میں یہ اضافہ کیا پھر آپ صلی اللہ علیہ وسلم نے فر ما یا:\"امابعد (حمد و صلاۃ کے بعد)!بلا شبہ سورج اور چاند اللہ کی نشانیوں میں سے دونشانیاں ہیں۔\"اور یہ بھی اضافہ کیا:پھر آپ نے اپنے دونوں ہاتھا اٹھا ئے اور فر ما یا:\"اے اللہ!کیا میں نے (پیغام) اچھی طرح پہنچا دیا؟\""}],[2034,"حرملہ بن یحییٰ نے مجھے حدیث بیان کی ، ( کہا ) مجھے ابن وہب نے یونس سے خبر دی نیز ابو طاہر اور محمد بن سلمہ مرادی نے کہا : ابن وہب نے یو نس سے حدیث بیان کی انھوں نے ابن شہاب سے روا یت کی انھوں نے کہا مجھے عروہ بن زبیر نے نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے خبر دی انھوں نے کہا رسول اللہ صلی اللہ علیہ وسلم کی حیات مبارکہ میں سورج کو گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم باہر مسجد میں تشریف لے گئے آپ نماز کے لیے کھڑے ہو گئے اور تکبیر کہی اور لو گ آپ کے پیچھے صف بستہ ہو گئے پھر رسول اللہ صلی اللہ علیہ وسلم نے طویل قراءت فر ما ئی پھر آپ نے الله اكبرکہا اور ایک لمبا رکو ع کیا پھر آپ نے اپنا سر اٹھا یا اور سمع اللہ لمن حمده ربنا ولك الحمد کہا پھر آپ نے قیام کیا اور ایک طویل قراءت کی یہ پہلی ( قراءت ) سے کچھ کم تھی پھر الله اكبرکہا اور کہہ کر طویل رکوع کیا یہ پہلے رکوع سے کچھ کم تھا پھر سمع اللہ لمن حمده ربنا ولك الحمد کہا پھر سجدہ کیا اور ابو طاہر نے ( ثم سجده ) ( پھر آپنے سجدہ کیا ) کے الفا ظ نہیں کہے ۔ پھر دوسری رکعت میں بھی اسی طرح کیا حتیٰ کہ چار رکوع اور چار سجدے مکمل کیے اور آپ کے سلام پھیرنے سے پہلے سورج روشن ہو گیا پھر آپ کھڑے ہو ئے اور لو گوں کو خطاب فر ما یا اور اللہ تعا لیٰ کی ( ایسی ) ثنا بیان کی جو اس کے شایان شان تھی پھر فر ما یا \"\" سورج اور چاند اللہ تعا لیٰ کی نشانیوں میں سے دو نشانیاں ہیں انھیں کسی کی مو ت کی وجہ سے گرہن لگتا ہے نہ کسی کی زندگی کی وجہ سے جب تم انھیں ( گرہن میں ) دیکھو تو فوراًنماز کی طرف لپکو ۔ \"\" آپ نے یہ بھی فر ما یا : \"\" اور نماز پڑھتے رہو یہاں تک کہ اللہ تمھارے لیے کشادگی کر دے اور رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \"\" میں نے اپنی اس جگہ ( پر ہو تے ہو ئے ) ہر وہ چیز دیکھ لی جس کا تمھارے ساتھ وعدہ کیا گیا ہے حتیٰ کہ میں نے اپنے آپ کو دیکھا کہ میں جنت کا ایک گچھا لینا چاہتا ہوں اس وقت جب تم نے مجھے دیکھا تھا کہ میں قدم آگے بڑھا رہا ہوں ۔ اور ( محمد بن سلمہ ) مرادی نے \"\" آگے بڑھ رہا ہوں \"\" کہا ۔ ۔ ۔ اور میں نے جہنم بھی دیکھی اس کا ایک حصہ دوسرے حصے کو ریزہ ریزہ کر رہا تھا یہ اس وقت جب تم نے مجھے دیکھا کہ میں پیچھے ہٹا ۔ اور میں نے جہنم میں عمرو بن لحی کو دیکھا جس نے سب سے پہلے بتوں کی نذر کی اونٹنیاں چھوڑیں ۔ \"\" ابو طا ہر کی روایت \"\" نماز کی طرف لپکو پر ختم ہو گئی انھوں نے بعد والا حصہ بیان نہیں کیا ۔","",{"u2":"حرملہ بن یحییٰ نے مجھے حدیث بیان کی،(کہا) مجھے ابن وہب نے یونس سے خبر دی نیز ابو طاہر اور محمد بن سلمہ مرادی نے کہا: ابن وہب نے یو نس سے حدیث بیان کی انھوں نے ابن شہاب سے روا یت کی انھوں نے کہا مجھے عروہ بن زبیر نے نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے خبر دی انھوں نے کہا رسول اللہ صلی اللہ علیہ وسلم کی حیات مبارکہ میں سورج کو گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم باہر مسجد میں تشریف لے گئے آپ نماز کے لیے کھڑے ہو گئے اور تکبیر کہی اور لو گ آپ کے پیچھے صف بستہ ہو گئے پھر رسول اللہ صلی اللہ علیہ وسلم نے طویل قراءت فر ما ئی پھر آپ نےاللہ اکبرکہا اور ایک لمبا رکو ع کیا پھر آپ نے اپنا سر اٹھا یا اور سمع اللہ لمن حمدہ ربنا ولک الحمد کہا پھر آپ نے قیام کیا اور ایک طویل قراءت کی یہ پہلی (قراءت) سے کچھ کم تھی پھر اللہ اکبرکہا اور کہہ کر طویل رکوع کیا یہ پہلے رکوع سے کچھ کم تھا پھر سمع اللہ لمن حمدہ ربنا ولک الحمد کہا پھر سجدہ کیا اور ابو طاہر نے (ثم سجدہ)(پھر آپنے سجدہ کیا) کے الفا ظ نہیں کہے۔پھر دوسری رکعت میں بھی اسی طرح کیا حتیٰ کہ چار رکوع اور چار سجدے مکمل کیے اور آپ کے سلام پھیرنے سے پہلے سورج روشن ہو گیا پھر آپ کھڑے ہو ئے اور لو گوں کو خطاب فر ما یا اور اللہ تعا لیٰ کی (ایسی) ثنا بیان کی جو اس کے شایان شان تھی پھر فر ما یا \"سورج اور چاند اللہ تعا لیٰ کی نشانیوں میں سے دو نشانیاں ہیں انھیں کسی کی مو ت کی وجہ سے گرہن لگتا ہے نہ کسی کی زندگی کی وجہ سے جب تم انھیں (گرہن میں) دیکھو تو فوراًنماز کی طرف لپکو۔\"آپ نے یہ بھی فر ما یا:\"اور نماز پڑھتے رہو یہاں تک کہ اللہ تمھارے لیے کشادگی کر دے اور رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"میں نے اپنی اس جگہ (پر ہو تے ہو ئے) ہر وہ چیز دیکھ لی جس کا تمھارے ساتھ وعدہ کیا گیا ہے حتیٰ کہ میں نے اپنے آپ کو دیکھا کہ میں جنت کا ایک گچھا لینا چاہتا ہوں اس وقت جب تم نے مجھے دیکھا تھا کہ میں قدم آگے بڑھا رہا ہوں۔اور (محمد بن سلمہ) مرادی نے \"آگے بڑھ رہا ہوں \"کہا۔۔۔اور میں نے جہنم بھی دیکھی اس کا ایک حصہ دوسرے حصے کو ریزہ ریزہ کر رہا تھا یہ اس وقت جب تم نے مجھے دیکھا کہ میں پیچھے ہٹا۔اور میں نے جہنم میں عمرو بن لحی کو دیکھا جس نے سب سے پہلے بتوں کی نذر کی اونٹنیاں چھوڑیں۔\"\nابو طا ہر کی روایت \"نماز کی طرف لپکو پر ختم ہو گئی انھوں نے بعد والا حصہ بیان نہیں کیا۔"}],[2035,"ابو عمرو اوزاعی اور ان کے علاوہ د وسرے ( راوی ، دونوں میں سے ہرایک ) نے کہا : میں نے ابن شہاب زہری سے سنا ، وہ عروہ سے اور وہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے خبر دے رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں سورج کوگرہن لگ گیا تو آپ نے یہ اعلان کرنے والا ( ایک شخص ) بھیجاکہ \" کہ نماز جمع کرنے والی ہے ۔ اس پر لوگ جمع ہوگئے ، آپ آگے بڑھے ، تکبیر تحریمہ کہی اور چار رکوعوں اور چار سجدوں کےساتھ دو رکعتیں پڑھیں ۔","",{"u2":"ابو عمرو اوزاعی اور ان کے علاوہ د وسرے(راوی،دونوں میں سے ہرایک)نے کہا:میں نے ابن شہاب زہری سے سنا،وہ عروہ سے اور وہ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے خبر دے رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں سورج کوگرہن لگ گیا تو آپ نے یہ اعلان کرنے والا(ایک شخص)بھیجاکہ\"کہ نماز جمع کرنے والی ہے۔اس پر لوگ جمع ہوگئے،آپ آگے بڑھے،تکبیر تحریمہ کہی اور چار رکوعوں اور چار سجدوں کےساتھ دو رکعتیں پڑھیں۔"}],[2036,"عبدالرحمان بن نمر نے خبر دی کہ انھوں نے ابن شہاب سے سنا ، وہ عروہ اور سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے خبر دے رہے تھے کہ نبی اکرم صلی اللہ علیہ وسلم نے صلاۃ الخسوف ( چاند یا سورج گرہن کی نماز ) میں بلند آواز سے قراءت کی اور دو رکعتوں میں چار رکوع اور چار سجدے کرکے نماز ادا کی ۔","",{"u2":"عبدالرحمان بن نمر نے خبر دی کہ انھوں نے ابن شہاب سے سنا،وہ عروہ اور حضرت عائشہ رضی اللہ تعالیٰ عنہا سے خبر دے رہے تھے کہ نبی اکرم صلی اللہ علیہ وسلم نے صلاۃ الخسوف(چاند یاسورج گرہن کی نماز) میں بلند آوازسے قراءت کی اور دو رکعتوں میں چار رکوع اور چار سجدے کرکے نماز ادا کی۔"}],[2037,"عبدالرحمان بن نمر نے خبر دی کہ انھوں نے ابن شہاب سے سنا ، وہ عروہ اور سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے خبر دے رہے تھے کہ نبی اکرم صلی اللہ علیہ وسلم نے صلاۃ الخسوف ( چاند یا سورج گرہن کی نماز ) میں بلند آواز سے قراءت کی اور دو رکعتوں میں چار رکوع اور چار سجدے کرکے نماز ادا کی ۔","",{"u2":"۔(عبدالرحمان بن نمر نے ہی کہا:)زہری نے کہا:کثیر بن عباس رضی اللہ تعالیٰ عنہ نے(اپنے بھائی حضرت عبداللہ) ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے دو رکعتوں میں چار رکوع اور چار سجدے کئے۔"}],[2038,"محمد بن ولید زبیدی نے زہری سے روایت کی ، انھوں نے کہا : کثیر بن عباس رضی اللہ تعالیٰ عنہ حدیث بیان کرتے تھےکہ سیدنا ابن عباس رضی اللہ تعالیٰ عنہ رسول اکرم صلی اللہ علیہ وسلم کی سورج گرہن والے دن کی نماز ( اسی طرح ) بیان کرتےتھے جس طرح عروہ نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے بیان کی ۔","",{"u2":"محمد بن ولید زبیدی نے زہری سے روایت کی،انھوں نے کہا:کثیر بن عباس رضی اللہ تعالیٰ عنہ حدیث بیان کرتے تھےکہ حضرت ابن عباس رضی اللہ تعالیٰ عنہ رسول اکرم صلی اللہ علیہ وسلم کی سورج گرہن والے دن کی نماز(اسی طرح) بیان کرتےتھے جس طرح عروہ نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے بیان کی۔"}],[2039,"ابن جریج نے کہا : میں نے عطاء ( بن ابی رباح ) کو کہتے ہوئے سنا : میں نے عبید بن عمیر سے سنا ، کہہ رہے تھے : مجھ سے اس شخص نے حدیث بیان کی جنھیں میں سچا سمجھتاہوں ۔ ( عطاء نے کہا : ) میرا خیال ہے ان کی مراد سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے تھی ۔ کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں سورج کوگرہن لگ گیا تو آپ نے بڑا پُر مشقت قیام کیا ۔ سیدھے کھڑے ہوتے ، پھر رکوع میں چلے جاتے ، پھر کھڑے ہوتے ۔ پھر رکوع کرتے ، پھر کھڑے ہوتے پھر رکوع کرتے ، دو رکعتیں ( تین ) تین رکوع اور چار سجدوں کے ساتھ پڑھیں ، پھر آپ نے سلام پھیر ا تو سورج روشن ہوچکا تھا ۔ جب آپ صلی اللہ علیہ وسلم رکوع کرتے تو الله اكبرکہا کہتے اس کے بعد جب رکوع کرتے اور جب سر اٹھاتے تو \" سمع اللہ لمن حمده \" کہتے ۔ اسکے بعد آپ ( خطبہ کے لئے ) کھڑے ہوئے ۔ اللہ تعالیٰ کی حمد وثنا بیان کی ، پھر فرمایا : \" سورج اور چاند نہ کسی کی موت پر بےنور ہوتے ہیں اور نہ ہی کسی کی زندگی پر بلکہ وہ اللہ کی نشانیاں ہیں ، ان کے ذریعے سے وہ اپنے بندوں کو خوف دلاتا ہے ، جب تم گرہن دیکھو تو اللہ کو یاد کرو حتیٰ کہ وہ روشن ہوجائیں ۔","",{"u2":"ابن جریج نے کہا:میں نے عطاء(بن ابی رباح) کو کہتے ہوئے سنا:میں نے عبید بن عمیر سے سنا،کہہ رہے تھے:مجھ سے اس شخص نے حدیث بیان کی جنھیں میں سچا سمجھتاہوں۔(عطاء نے کہا:) میرا خیال ہے ان کی مراد حضرت عائشہ رضی اللہ تعالیٰ عنہا سے تھی۔کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں سورج کوگرہن لگ گیا تو آپ نے بڑا پُر مشقت قیام کیا۔سیدھے کھڑے ہوتے،پھر رکوع میں چلے جاتے،پھرکھڑے ہوتے۔پھر رکوع کرتے،پھر کھڑے ہوتے پھر رکوع کرتے،دو رکعتیں(تین) تین رکوع اور چار سجدوں کے ساتھ پڑھیں،پھر آپ نے سلام پھیر ا تو سورج روشن ہوچکا تھا۔جب آپ صلی اللہ علیہ وسلم رکوع کرتے تو اللہ اکبرکہا کہتے اس کے بعد جب رکوع کرتے اور جب سر اٹھاتے تو\" سمع اللہ لمن حمدہ \" کہتے۔اسکے بعد آپ(خطبہ کے لئے) کھڑے ہوئے۔اللہ تعالیٰ کی حمد وثنا بیان کی،پھر فرمایا:\"سورج اور چاند نہ کسی کی موت پر بےنور ہوتے ہیں اور نہ ہی کسی کی زندگی پر بلکہ وہ اللہ کی نشانیاں ہیں،ان کے ذریعے سے وہ اپنے بندوں کو خوف دلاتا ہے،جب تم گرہن دیکھو تو اللہ کو یاد کرو حتیٰ کہ وہ روشن ہوجائیں۔\""}],[2040,"قتادہ نے عطاء بن ابی رباح سے ، انھوں نے عبید بن عمیر سے اور انھوں نے حضر ت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے ( کسوف میں ) چھ رکوعوں اور چار سجدوں پر مشتمل نماز پڑھی ۔","",{"u2":"قتادہ نے عطاء بن ابی رباح سے،انھوں نے عبید بن عمیر سے اور انھوں نے حضر ت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے (کسوف میں) چھ رکوعوں اور چار سجدوں پر مشتمل نماز پڑھی۔"}],[2041,"سلیمان بن بلال نے یحییٰ ( بن سعید ) سے اور انھوں نے عمرہ سے روایت کی کہ ایک یہودی عورت سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے پاس مانگنے کے لئے آئی ۔ اس نے آکر ( کہا : اللہ آپ کو عذاب قبر سے پناہ دے ۔ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : میں نے کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم !لوگوں کو قبر میں عذاب ہوگا؟عمرہ نے کہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے بتایاکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" میں اللہ کی پناہ چاہتا ہوں \"\" پھر رسول اللہ صلی اللہ علیہ وسلم ایک صبح کسی سواری پر سوار ہوکر نکلے تو سورج کوگرہن لگ گیا ، سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : میں بھی عورتوں کے سات حجروں کے درمیان سے نکل کر مسجد میں آئی اور رسول اللہ صلی اللہ علیہ وسلم اپنی سواری سے ( اتر کر ) نماز پڑھنے کی اس جگہ پر آئے جہاں آپ نماز پڑھایا کرتے تھے ، آپ کھڑے ہوگئے اور لوگ بھی آپ کے پیچھے کھڑے ہوگئے ، سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : پھر آپ نے لمبا قیام کیا ، پھر رکوع کیا اور لمبا رکوع کیا ، پھر ( رکوع سے ) سر اٹھایا اور طویل قیام کیا جو پہلے قیام سے چھوٹا تھا ۔ اور پھر ( رکوع سے ) سر اٹھایا تو سورج روشن ہوچکا تھا ، پھر ( نماز سے فراغت کے بعد ) آپ نے فرمایا : \"\" میں نے تمھیں دیکھا ہے کہ تم قبروں میں دجال کی آزمائش کی طرح آزمائش میں ڈالے جاؤگے ۔ \"\" عمرہ نے کہا : میں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا کو یہ کہتے ہوئے سنا کہ میں اس کے بعد رسول اللہ صلی اللہ علیہ وسلم سے سنا کرتی تھی کہ آپ صلی اللہ علیہ وسلم آگ کے عذاب سے اور قبر کے عذاب سے پناہ مانگتے تھے ۔","",{"u2":"سلیمان بن بلال نے یحییٰ(بن سعید) سے اور انھوں نے عمرہ سے روایت کی کہ ایک یہودی عورت حضرت عائشہ رضی اللہ تعالیٰ عنہا کے پاس مانگنے کے لئے آئی۔اس نے آکر(کہا:اللہ آپ کو عذاب قبر سے پناہ دے۔حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا:میں نے کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!لوگوں کو قبرمیں عذاب ہوگا؟عمرہ نے کہا:حضرت عائشہ رضی اللہ تعالیٰ عنہا نے بتایاکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"میں اللہ کی پناہ چاہتا ہوں\"پھر رسول اللہ صلی اللہ علیہ وسلم ایک صبح کسی سواری پر سوار ہوکر نکلے تو سورج کوگرہن لگ گیا،حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا:میں بھی عورتوں کے سات حجروں کے درمیان سے نکل کر مسجد میں آئی اور رسول اللہ صلی اللہ علیہ وسلم اپنی سواری سے(اتر کر)نماز پڑھنے کی اس جگہ پرآئے جہاں آپ نماز پڑھایا کرتے تھے،آپ کھڑے ہوگئے اور لوگ بھی آپ کے پیچھے کھڑے ہوگئے،حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا:پھر آپ نے لمبا قیام کیا،پھر رکوع کیا اور لمبا رکوع کیا،پھر(رکوع سے) سر اٹھایا اور طویل قیام کیا جو پہلے قیام سے چھوٹا تھا۔اور پھر (رکوع سے)سر اٹھایا تو سورج روشن ہوچکا تھا،پھر(نماز سے فراغت کے بعد)آپ نے فرمایا:\"میں نے تمھیں دیکھا ہے کہ تم قبروں میں دجال کی آزمائش کی طرح آزمائش میں ڈالے جاؤگے۔\"\nعمرہ نے کہا:میں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا کو یہ کہتے ہوئے سنا کہ میں اس کے بعد رسول اللہ صلی اللہ علیہ وسلم سے سنا کرتی تھی کہ آپ صلی اللہ علیہ وسلم آگ کے عذاب سے اور قبر کے عذاب سے پناہ مانگتے تھے۔"}],[2042,"عبدالوہاب اور سفیان نے یحییٰ بن سعید سے اسی سند کے ساتھ سلیمان بن بلال کی حدیث کے ہم معنی روایت بیان کی ۔","",{"u2":"عبدالوہاب اور سفیان نے یحییٰ بن سعید سے اسی سند کے ساتھ سلیمان بن بلال کی حدیث کے ہم معنی روایت بیان کی۔"}],[2043,"اسماعیل ابن علیہ نے ہشام دستوائی سے روایت کی ، انھوں نے کہا : ہمیں ابو زبیر نے جابر بن عبداللہ سے حدیث سنائی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک انتہائی گرم دن سورج کوگرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے ساتھیوں ( صحابہ رضوان اللہ عنھم اجمعین ) کے ساتھ نمازپڑھی ، آپ نے ( اتنا ) لمبا قیام کیا کہ کچھ لوگ گرنے لگے ، پھر آپ نے رکوع کیا اوراے لمبا کیا ، پھر ( رکوع سے ) سر اٹھایا اور لمبا ( قیام ) کیا ، آپ صلی اللہ علیہ وسلم نے پھر رکوع کیا اور لمبا کیا ۔ پھرآپ صلی اللہ علیہ وسلم نے ( رکوع سے ) سر اٹھایا اور ( اس قیام کو لمبا ) کیا ، پھر دو سجدے کیے ، پھر آپ ( دوسری رکعت کے لئے ) اٹھے اور اسی طرح کیا ، اس طرح چار رکوع اور چار سجدے ہوگئے ، پھر آپ نے فرمایا : بلاشبہ مجھ پر ہر وہ چیز ( حشر نشر ، پل صراط ، جنت اور دوزخ ) جس میں سے تم گزروگے ، پیش کی گئی ، میرے سامنے جنت پیش کی گئی حتیٰ کہ اگر میں اس میں سے ایک گچھے کو لینا چاہتا تو اسے پکڑ لیتا ۔ یا آپ نے ( یوں ) فرمایا : میں نے ایک گچھہ لینا چاہا تو میرا ہاتھ اس تک نہ پہنچا ، اور میرے سامنے جہنم پیش کی گئی تو میں نے اس میں بنی اسرائیل کی ایک عورت دیکھی جسے اپنی بلی ( کے معاملے ) میں عذاب دیا جارہا تھا ۔ اس نے اسے باندھ دیا نہ اسے کچھ کھلایا ( پلایا ) نہ اسے چھوڑا ہی کہ وہ زمین کے چھوٹے موٹے جاندار پرندے وغیرہ کھالیتی ۔ اور میں نے ابو ثمامہ عمرو ( بن عامر ) بن مالک ( جس کالقب لحی تھا اور خزاعہ اس کی اولاد میں سے تھا ) کو دیکھا کہ وہ آگ میں اپنی انتڑیاں گھسیٹ رہاتھا ، لوگ کہا کرتے تھےکہ سورج اور چاند کسی عظیم شخصیت کی موت پر ہی بے نور ہوتے ہیں ، حالانکہ وہ اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں ۔ جو وہ تمھیں دیکھاتا ہے ، جب انھیں گرہن لگے تو اس وقت تک نماز پڑھتے رہو کہ وہ ( گرہن ) چھٹ جائے ۔","",{"u2":"اسماعیل ابن علیہ نے ہشام دستوائی سے روایت کی،انھوں نے کہا:ہمیں ابو زبیر نے جابر بن عبداللہ سے حدیث سنائی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک انتہائی گرم دن سورج کوگرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے ساتھیوں(صحابہ رضوان اللہ عنھم اجمعین) کے ساتھ نمازپڑھی،آپ نے(اتنا) لمبا قیام کیا کہ کچھ لوگ گرنے لگے،پھر آپ نے رکوع کیا اوراے لمبا کیا،پھر(رکوع سے) سر اٹھایا اور لمبا(قیام) کیا،آپ صلی اللہ علیہ وسلم نے پھر رکوع کیا اور لمبا کیا۔پھرآپ صلی اللہ علیہ وسلم نے(رکوع سے) سر اٹھایا اور (اس قیام کو لمبا) کیا،پھر دو سجدے کیے،پھر آپ(دوسری رکعت کے لئے) اٹھے اور اسی طرح کیا،اس طرح چار رکوع اورچار سجدے ہوگئے،پھر آپ نے فرمایا:بلاشبہ مجھ پر ہر وہ چیز(حشر نشر،پل صراط،جنت اور دوزخ)جس میں سے تم گزروگے،پیش کی گئی،میرے سامنے جنت پیش کی گئی حتیٰ کہ اگر میں اس میں سے ایک گچھے کو لینا چاہتا تو اسے پکڑ لیتا۔یا آپ نے(یوں) فرمایا:میں نے ایک گچھہ لیناچاہا تو میرا ہاتھ اس تک نہ پہنچا،اور میرے سامنے جہنم پیش کی گئی تو میں نے اس میں بنی اسرائیل کی ایک عورت دیکھی جسے اپنی بلی(کے معاملے) میں عذاب دیا جارہا تھا۔اس نے اسے باندھ دیا نہ اسے کچھ کھلایا(پلایا) نہ اسے چھوڑا ہی کہ وہ زمین کے چھوٹے موٹے جاندار پرندے وغیرہ کھالیتی۔اور میں نے ابو ثمامہ عمرو(بن عامر) بن مالک(جس کالقب لحی تھا اور خزاعہ اس کی اولاد میں سے تھا)کو دیکھا کہ وہ آگ میں اپنی انتڑیاں گھسیٹ رہاتھا،لوگ کہا کرتے تھےکہ سورج اور چاند کسی عظیم شخصیت کی موت پر ہی بے نور ہوتے ہیں،حالانکہ وہ اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔جو وہ تمھیں دیکھاتا ہے،جب انھیں گرہن لگے تو اس وقت تک نماز پڑھتے رہو کہ وہ(گرہن) چھٹ جائے۔\""}],[2044,"اسماعیل ابن علیہ نے ہشام دستوائی سے روایت کی ، انھوں نے کہا : ہمیں ابو زبیر نے جابر بن عبداللہ سے حدیث سنائی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک انتہائی گرم دن سورج کوگرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے ساتھیوں ( صحابہ رضوان اللہ عنھم اجمعین ) کے ساتھ نمازپڑھی ، آپ نے ( اتنا ) لمبا قیام کیا کہ کچھ لوگ گرنے لگے ، پھر آپ نے رکوع کیا اوراے لمبا کیا ، پھر ( رکوع سے ) سر اٹھایا اور لمبا ( قیام ) کیا ، آپ صلی اللہ علیہ وسلم نے پھر رکوع کیا اور لمبا کیا ۔ پھرآپ صلی اللہ علیہ وسلم نے ( رکوع سے ) سر اٹھایا اور ( اس قیام کو لمبا ) کیا ، پھر دو سجدے کیے ، پھر آپ ( دوسری رکعت کے لئے ) اٹھے اور اسی طرح کیا ، اس طرح چار رکوع اور چار سجدے ہوگئے ، پھر آپ نے فرمایا : بلاشبہ مجھ پر ہر وہ چیز ( حشر نشر ، پل صراط ، جنت اور دوزخ ) جس میں سے تم گزروگے ، پیش کی گئی ، میرے سامنے جنت پیش کی گئی حتیٰ کہ اگر میں اس میں سے ایک گچھے کو لینا چاہتا تو اسے پکڑ لیتا ۔ یا آپ نے ( یوں ) فرمایا : میں نے ایک گچھہ لینا چاہا تو میرا ہاتھ اس تک نہ پہنچا ، اور میرے سامنے جہنم پیش کی گئی تو میں نے اس میں بنی اسرائیل کی ایک عورت دیکھی جسے اپنی بلی ( کے معاملے ) میں عذاب دیا جارہا تھا ۔ اس نے اسے باندھ دیا نہ اسے کچھ کھلایا ( پلایا ) نہ اسے چھوڑا ہی کہ وہ زمین کے چھوٹے موٹے جاندار پرندے وغیرہ کھالیتی ۔ اور میں نے ابو ثمامہ عمرو ( بن عامر ) بن مالک ( جس کالقب لحی تھا اور خزاعہ اس کی اولاد میں سے تھا ) کو دیکھا کہ وہ آگ میں اپنی انتڑیاں گھسیٹ رہاتھا ، لوگ کہا کرتے تھےکہ سورج اور چاند کسی عظیم شخصیت کی موت پر ہی بے نور ہوتے ہیں ، حالانکہ وہ اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں ۔ جو وہ تمھیں دیکھاتا ہے ، جب انھیں گرہن لگے تو اس وقت تک نماز پڑھتے رہو کہ وہ ( گرہن ) چھٹ جائے ۔","",{"u2":"عبدالملک بن صباح نے ہشام دستوائی سے اسی سند کےھ ساتھ اسی(سابقہ حدیث) کے مانند حدیث بیان کی،مگر انھوں نے کہا:(آپ نے فرمایا:)\"میں نے آگ میں بلاد حمیر کی(رہنے والی) ایک سیاہ لمبی عورت دیکھی۔\"اور انھوں نےمن بنی اسرائیل (بنی اسرائیل کی) کے الفاظ نہیں کہے۔"}],[2045,"ابو بکر بن ابی شیبہ نے کہا : ہم سے عبداللہ بن نمیر نے حدیث بیان کی ، نیز محمد بن عبداللہ نمیر نے حدیث بیان کی ۔ ۔ ۔ دونوں کے لفظ ملتے جلتے ہیں ۔ کہا : ہمیں میرے والد ( عبداللہ بن نمیر ) نے حدیث سنائی ، کہا : ہمیں عبدالملک نے عطاء سے حدیث بیان کی ، انھوں نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں ، جس دن رسول اللہ صلی اللہ علیہ وسلم کے بیتے ابراہیم رضی اللہ تعالیٰ عنہ فوت ہوئے ، سورج گرہن ہوگیا ، ( بعض ) لوگوں نے کہا : سورج کو گرہن سیدنا ابراہیم رضی اللہ تعالیٰ عنہ کی موت کی بنا پر لگا ہے ۔ ( پھر ) نبی اکرم صلی اللہ علیہ وسلم کھڑے ہوئے اور لوگوں کو چھ رکوعوں ، چار سجدوں کے ساتھ ( دو رکعت ) نماز پڑھائی ۔ آغاز کیا تو اللہ اکبر کہا ، پھر قراءت کی اور طویل قراءت کی ، پھر جتنا قیام کیا تھا تقریباً رکوع کیا ، پھر رکوع سے ا پنا سر اٹھایا اور پہلی قراءت سے کچھ کم قراءت کی ، پھر ( اس ) قیام جتنا رکوع کیا ، پھر رکوع سے اپنا سر اٹھایا اور دوسری قراءت سے کچھ کم قراءت کی ، پھر ( اس ) قیام جتنا رکوع کیا ، پھر رکوع سے اپنا سر اٹھایا ، پھر سجدے کے لئے جھکے اور دو سجدے فرمائے ، پھر کھڑے ہوئے اور ( اس دوسری ر کعت میں بھی ) تین رکوع کیے ، ان میں سے ہر پہلا رکوع بعد والے رکوع سے زیادہ لمبا تھا اور آپ کا رکوع تقریباً سجدے کے برابر تھا ، پھرآپ پیچھے ہٹے تو آپ کے پیچھے والی صفیں بھی پیچھے ہٹ گئیں حتیٰ کہ ہم لوگ آخر ( آخری کنارے ) تک پہنچ گئے ۔ ابو بکر ( ابن ابی شیبہ ) نے کہا : حتیٰ کہ آپ عور توں کی صفوں کے قر یب پہنچ گئے ۔ پھر آپ آگے بڑھے اور آپ کے ساتھ لوگ بھی ( صفوں میں ) آگے بڑھ آئے حتیٰ کہ آپ ( واپس ) اپنی جگہ پر کھڑے ہوگئے پھر جب آپ نے نماز سے سلام پھیرا ، اس وقت سورج اپنی اصلی حالت پر آچکا تھا ، پھر آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا : \" لوگو!سورج اور چاند اللہ کی نشانیوں میں سے دو نشانیاں ہی ہیں اور بلا شبہ ان دونوں کو ، لوگوں میں سے کسی کی موت پر گرہن نہیں لگتا ۔ ابو بکر ( بن ابی شیبہ ) نے \" کسی بشر کی موت پر \" کہا ۔ پس جب تم کوئی ایسی چیز دیکھو تو اس وقت تک نماز پڑھو جب تک کہ یہ زائل ہوجائے ، کوئی چیز نہیں جس کا تم سے وعدہ کیاگیا ہے مگر میں نے اسے اپنی اس نماز میں دیکھ لیا ہے ۔ آگ ( میرے سامنے ) لائی گئی اور یہ اس وقت ہوا جب تم نے مجھے دیکھا کہ میں اس ڈر سے پیچھے ہٹا ہوں کہ اس کی لپٹیں مجھ تک نہ پہنچیں ۔ یہاں تک کہ میں نے اس آگ میں مڑے ہوئے سرے والی چھڑی کے مالک کو دیکھ لیا ، وہ آگ میں اپنی انتڑیاں کھینچ رہا ہے ۔ وہ اپنی اس مڑے ہوئے سرے والی چھڑی کے زریعے سے حاجیوں کی ( چیزیں ) چوری کرتا تھا ۔ اگر اس ( کی چوری ) کا پتہ چل جاتا تو کہہ دیتا : یہ چیز میری لاٹھی کے ساتھ اٹک گئی تھی ، اور اگر پتہ نہ چلتا تووہ اسے لے جاتا ۔ یہاں تک کہ میں نے اس ( آگ ) میں بلی والی اس عورت کو بھی دیکھا جس نے اس ( بلی ) کو باندھ رکھا ، نہ خود اسے کچھ کھلایااور نہ اسے چھوڑا کہ وہ زمین کے اس چھوٹے موٹے جاندار اور پرندے کھا لیتی ، حتیٰ کہ وہ ( بلی ) بھوک سے مر گئی ، پھر جنت کو ( میرے سامنے ) لایاگیا اور یہ اس وقت ہوا جب تم نے مجھے دیکھا کہ میں آگے بڑھا حتیٰ کہ میں واپس اپنی جگہ پر آکھڑا ہوا ، میں نے اپنا ہاتھ بڑھایا اور میں چاہتا تھا کہ میں اس کے پھل میں سے کچھ لے لوں تاکہ تم اسے دیکھ سکو ، پھر مجھ پر بات کھلی کہ میں ایسا نہ کروں ، کوئی ایسی چیز نہیں جس کا تم سے وعدہ کیا جاتا ہے مگر میں نے وہ اپنی اس نماز میں دیکھ لی ہے ۔","",{"u2":"ابو بکر بن ابی شیبہ نے کہا:ہم سے عبداللہ بن نمیر نے حدیث بیان کی،نیز محمد بن عبداللہ نمیر نے حدیث بیان کی۔۔۔دونوں کے لفظ ملتے جلتے ہیں۔کہا:ہمیں میرے والد(عبداللہ بن نمیر)نے حدیث سنائی،کہا:ہمیں عبدالملک نے عطاء سے حدیث بیان کی،انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں،جس دن رسول اللہ صلی اللہ علیہ وسلم کے بیتے ابراہیم رضی اللہ تعالیٰ عنہ فوت ہوئے،سورج گرہن ہوگیا،(بعض)لوگوں نے کہا:سورج کو گرہن حضرت ابراہیم رضی اللہ تعالیٰ عنہ کی موت کی بنا پر لگا ہے۔(پھر) نبی اکرم صلی اللہ علیہ وسلم کھڑے ہوئے اور لوگوں کو چھ رکوعوں،چار سجدوں کے ساتھ(دو رکعت) نماز پڑھائی۔آغاز کیاتو اللہ اکبر کہا،پھرقراءت کی اور طویل قراءت کی، پھر جتنا قیام کیا تھا تقریباً رکوع کیا،پھر رکوع سے ا پنا سر اٹھایا اور پہلی قراءت سےکچھ کم قراءت کی،پھر(اس)قیام جتنا رکوع کیا،پھر رکوع سے اپنا سر اٹھایا اور دوسری قراءت سے کچھ کم قراءت کی،پھر(اس)قیام جتنا رکوع کیا،پھر رکوع سے اپنا سر اٹھایا،پھر سجدے کے لئے جھکے اور دو سجدے فرمائے،پھر کھڑے ہوئے اور(اس دوسری ر کعت میں بھی)تین رکوع کیے،ان میں سے ہر پہلا رکوع بعد والے رکوع سے زیادہ لمباتھا اور آپ کا رکوع تقریباً سجدے کے برابر تھا،پھرآپ پیچھے ہٹے تو آپ کے پیچھے والی صفیں بھی پیچھے ہٹ گئیں حتیٰ کہ ہم لوگ آخر(آخری کنارے)تک پہنچ گئے۔ابو بکر(ابن ابی شیبہ)نے کہا:حتیٰ کہ آپ عور توں کی صفوں کے قر یب پہنچ گئے۔پھر آپ آگے بڑھے اور آپ کے ساتھ لوگ بھی (صفوں میں)آگے بڑھ آئے حتیٰ کہ آپ(واپس) اپنی جگہ پر کھڑے ہوگئے پھر جب آپ نے نماز سے سلام پھیرا،اس وقت سورج اپنی اصلی حالت پر آچکا تھا،پھر آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا:\"لوگو!سورج اور چاند اللہ کی نشانیوں میں سے دو نشانیاں ہی ہیں اور بلا شبہ ان دونوں کو،لوگوں میں سے کسی کی موت پر گرہن نہیں لگتا۔ابو بکر(بن ابی شیبہ)نے\"کسی بشر کی موت پر\"کہا۔پس جب تم کوئی ایسی چیز دیکھو تو اس وقت تک نماز پڑھو جب تک کہ یہ زائل ہوجائے،کوئی چیز نہیں جس کا تم سے وعدہ کیاگیا ہے مگر میں نے اسے اپنی اس نماز میں دیکھ لیاہے۔آگ (میرے سامنے) لائی گئی اور یہ اس وقت ہوا جب تم نے مجھے دیکھا کہ میں اس ڈر سے پیچھے ہٹا ہوں کہ اس کی لپٹیں مجھ تک نہ پہنچیں۔یہاں تک کہ میں نے اس آگ میں مڑے ہوئے سرے والی چھڑی کے مالک کو دیکھ لیا،وہ آگ میں اپنی انتڑیاں کھینچ رہا ہے۔وہ اپنی اس مڑے ہوئے سرے والی چھڑی کے زریعے سے حاجیوں کی (چیزیں)چوری کرتا تھا۔اگر اس (کی چوری) کا پتہ چل جاتا تو کہہ دیتا:یہ چیز میری لاٹھی کے ساتھ اٹک گئی تھی،اور اگر پتہ نہ چلتا تووہ اسے لے جاتا۔یہاں تک کہ میں نے اس(آگ) میں بلی والی اس عورت کو بھی دیکھا جس نے اس (بلی) کو باندھ رکھا،نہ خود اسے کچھ کھلایااور نہ اسے چھوڑا کہ وہ زمین کے اس چھوٹے موٹے جاندار اور پرندے کھا لیتی،حتیٰ کہ وہ (بلی) بھوک سے مر گئی،پھر جنت کو(میرے سامنے) لایاگیا اور یہ اس وقت ہوا جب تم نے مجھے دیکھا کہ میں آگے بڑھا حتیٰ کہ میں واپس اپنی جگہ پر آکھڑا ہوا،میں نے اپنا ہاتھ بڑھایا اور میں چاہتا تھا کہ میں اس کے پھل میں سے کچھ لے لوں تاکہ تم اسے دیکھ سکو،پھر مجھ پر بات کھلی کہ میں ایسا نہ کروں،کوئی ایسی چیز نہیں جس کا تم سے وعدہ کیا جاتا ہے مگر میں نے وہ اپنی اس نماز میں دیکھ لی ہے۔\""}],[2046,"ہمیں ( عبداللہ ) ابن نمیر نے حدیث بیان کی ، کہا : ہم سے ہشام نے ، انھوں نے ( اپنی بیوی ) فاطمہ ( بنت منذر بن زبیر بن عوام ) سے اور انھوں نے ( اپنی دادی ) سیدہ اسماء بنت ابی بکر رضی اللہ تعالیٰ عنہا سے حدیث بیان کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے دور میں سورج کوگرہن لگ گیا ، چنانچہ میں عائشہ رضی اللہ تعالیٰ عنہا کے ہاں آئی اور وہ ( ساتھ مسجد میں ) نماز پڑھ رہی تھیں ، میں نے پوچھا : لوگوں کو کیا ہوا وہ ( اس وقت ) نماز پڑھ رہے ہیں؟انھوں نے اپنے سر سے آسمان کی طرف اشارہ کیا ۔ تو میں نے پوچھا : کوئی نشانی ( ظاہر ہوئی ) ہے؟انھوں نے ( اشارے سے ) بتایا : ہاں ، تو رسول اللہ صلی اللہ علیہ وسلم نے قیام کو بہت زیادہ لمبا کی حتیٰ کہ مجھ پر غشی طاری ہونے لگی ، میں نے اپنے پہلو میں پڑی مشک اٹھائی اور اپنے سریا اپنے چہرے پر پانی ڈالنےلگی ۔ کہا : رسول اللہ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو سورج روشن ہوچکا تھا ۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے لوگوں سے خطاب فرمایا ، اللہ تعالیٰ کی حمد کی اور اس کی ثنا بیان کی ، پھر فرمایا : \" اما بعد ( حمد وثنا کے بعد ) ! کوئی چیز ایسی نہیں جس کا میں نے مشاہدہ نہیں کیا تھا مگر اب میں نے اپنی اس جگہ سے اس کا مشاہدہ کر لیا ہے حتی ٰ کہ جنت اور دوزخ بھی دیکھ لی ہیں ۔ اور یہ بھی حقیقت ہے کہ مجھ پر یہ وحی کی گئی ہے کہ عنقریب ہے کہ عنقریب قبروں میں تمھاری مسیح دجال کی آزمائش کے قریب یا س جیسی آزمائش ہوگی ۔ ۔ ( فاطمہ نے کہا ) مجھے پتہ نہیں ، حضر ت اسما رضی اللہ عنہا نے ان میں سے کون سا لفظ کہا ۔ اور تم میں سے ہر ایک کے پاس ( فرشتوں کی ) آمد ہو گی اور پوچھا جائے گا : تم اس آدمی کے بارے میں کیا جانتے ہو ؟ تو مومن یا یقین رکھنے والا ۔ مجھے معلوم نہیں سیدنا اسما رضی اللہ عنہا نے کون سا لفظ کہا ۔ ۔ کہنے گا : وہ محمد ہیں ، وہ اللہ کے رسول ہیں ، ہمارے پاس کھلی نشانیاں اور ہدایت لے کر آئے ، ہم نے ان ( کی بات ) کو قبول کیا اور اطاعت کی ، تین دفعہ ( سوال وجواب ) ہوگا ۔ پھراُس سے کہاجائے گا : سوجاؤ ، ہمیں معلوم تھا کہ تم ان پر ایمان رکھتےہو ۔ ایک نیک بخت کی طرح سوجاؤ ۔ اور رہا منافق یا وہ جوشک وشبہ میں مبتلا تھا ۔ معلوم نہیں سیدنا اسما رضی اللہ عنہا نے ان میں سے کو ن سا لفظ کہا ۔ تو وہ کہے گا : میں نہیں جانتا ، میں نے لوگوں کو کچھ کہتے ہوئے سناتھا تو وہی کہہ دیا تھا ۔","",{"u2":"ہمیں (عبداللہ) ابن نمیر نے حدیث بیان کی،کہا:ہم سے ہشام نے،انھوں نے (اپنی بیوی)فاطمہ(بنت منذر بن زبیر بن عوام)سے اور انھوں نے(اپنی دادی)حضرت اسماء بنت ابی بکر رضی اللہ تعالیٰ عنہا سے حدیث بیان کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم کے دور میں سورج کوگرہن لگ گیا،چنانچہ میں عائشہ رضی اللہ تعالیٰ عنہا کے ہاں آئی اور وہ(ساتھ مسجد میں)نماز پڑھ رہی تھیں،میں نے پوچھا:لوگوں کو کیا ہوا وہ(اس وقت) نماز پڑھ رہے ہیں؟انھوں نے اپنے سر سے آسمان کی طرف اشارہ کیا۔تو میں نے پوچھا:کوئی نشانی(ظاہر ہوئی) ہے؟انھوں نے (اشارے سے) بتایا:ہاں،تو رسول اللہ صلی اللہ علیہ وسلم نے قیام کو بہت زیادہ لمبا کی حتیٰ کہ مجھ پر غشی طاری ہونے لگی، میں نے اپنے پہلو میں پڑی مشک اٹھائی اور اپنے سریا اپنے چہرے پر پانی ڈالنےلگی۔ کہا: رسول اللہ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے توسورج روشن ہوچکا تھا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے لوگوں سے خطاب فرمایا، اللہ تعالیٰ کی حمد کی اور اس کی ثنا بیان کی، پھر فرمایا: \" اما بعد (حمد وثنا کے بعد)! کوئی چیز ایسی نہیں جس کا میں نے مشاہدہ نہیں کیا تھا مگر اب میں نے اپنی اس جگہ سے اس کا مشاہدہ کر لیا ہے حتی ٰ کہ جنت اور دوزخ بھی دیکھ لی ہیں۔ اور یہ بھی حقیقت ہے کہ مجھ پر یہ وحی کی گئی ہے کہ عنقریب ہے کہ عنقریب قبروں میں تمھاری مسیح دجال کی آزمائش کے قریب یا س جیسی آزمائش ہوگی۔۔ (فاطمہ نے کہا) مجھے پتہ نہیں، حضر ت اسما رضی اللہ عنہا نے ان میں سے کون سا لفظ کہا۔ اور تم میں سے ہر ایک کے پاس (فرشتوں کی) آمد ہو گی اور پوچھا جائے گا: تم اس آدمی کے بارے میں کیاجانتے ہو؟ تومومن یا یقین رکھنے والا۔ مجھے معلوم نہیں حضرت اسما رضی اللہ عنہا نے کون سا لفظ کہا۔۔کہنے گا: وہ محمد ہیں، وہ اللہ کے رسول ہیں، ہمارےپاس کھلی نشانیاں اور ہدایت لے کر آئے، ہم نے ان (کی بات) کوقبول کیا اور اطاعت کی، تین دفعہ (سوال وجواب) ہوگا۔ پھراُس سے کہاجائے گا: سوجاؤ، ہمیں معلوم تھا کہ تم ان پر ایمان رکھتےہو۔ ایک نیک بخت کی طرح سوجاؤ۔ اور رہامنافق یا وہ جوشک وشبہ میں مبتلا تھا۔معلوم نہیں حضرت اسما رضی اللہ عنہا نے ان میں سے کو ن سا لفظ کہا۔ تو وہ کہے گا: میں نہیں جانتا، میں نے لوگوں کو کچھ کہتےہوئے سناتھا تو وہی کہہ دیا تھا۔\""}],[2047,"ابو اسامہ نے ہشام سے ، انھوں نے فاطمہ سے اور انھوں نے سیدنا اسما رضی اللہ عنہا سے روایت کی ، انھوں نے کہا : میں سیدہ عائشہ رضی اللہ عنہا کے پاس آئی تو اس وقت لوگ ( نماز میں ) کھڑے تھے اور وہ بھی نما ز پڑھ رہی تھیں ۔ میں نے پوچھا : لوگو ں کو کیا ہوا؟ اور ( آگے ) ہشام سے ابن نمیر کی ( سابقہ ) حدیث کی طرح حدیث بیان کی ۔","",{"u2":"ابو اسامہ نے ہشام سے، انھوں نے فاطمہ سے اور انھوں نے حضرت اسما رضی اللہ عنہا سے روایت کی، انھوں نے کہا: میں حضرت عائشہ رضی اللہ عنہا کے پاس آئی تو اس وقت لوگ (نماز میں) کھڑے تھے اور وہ بھی نما ز پڑھ رہی تھیں۔ میں نے پوچھا: لوگو ں کو کیا ہوا؟ اور (آگے) ہشام سے ابن نمیر کی (سابقہ) حدیث کی طرح حدیث بیان کی۔"}],[2048,"ابو اسامہ نے ہشام سے ، انھوں نے فاطمہ سے اور انھوں نے سیدنا اسما رضی اللہ عنہا سے روایت کی ، انھوں نے کہا : میں سیدہ عائشہ رضی اللہ عنہا کے پاس آئی تو اس وقت لوگ ( نماز میں ) کھڑے تھے اور وہ بھی نما ز پڑھ رہی تھیں ۔ میں نے پوچھا : لوگو ں کو کیا ہوا؟ اور ( آگے ) ہشام سے ابن نمیر کی ( سابقہ ) حدیث کی طرح حدیث بیان کی ۔","",{"u2":"عروہ سے روایت ہے، انھوں نے کہا: سورج کے لیے کسف نہ کہو، بلکہ خسف کا لفظ استعمال کرو۔(اردو میں دونوں کا معنی \"گرہن \" ہی ہے۔)"}],[2049,"خالد بن حارث نے کہا : ہم سے ابن جریج نے حدیث بیان کی ، ( انھوں نے کہا : ) مجھ سے منصور بن عبدالرحٰمن نے اپنی والدہ صفیہ بنت شیبہ سے اور انھوں نے سیدہ اسماء بنت ابی بکر رضی اللہ عنہا سے روایت کی ، انھوں نے کہا : ایک دن نبی اکرم صلی اللہ علیہ وسلم تیزی سے ( لپک کر ) گئے ۔ کہا : ان کی مراد اس دن سے تھی جس دن سورج کو گرہن لگا تھا ۔ ۔ تو ( جلدی میں ) آپ نے ایک زنانہ قمیض اٹھالی حتیٰ کہ پیچھے سے آپ کو آپ کی چادر لا کر دی گئی ۔ آپ نے لوگوں کی امامت کرتے ہوئے انتہائی طویل قیام کیا ۔ اگرکوئی ایسا انسان آتا جس کو یہ پتہ نہ ہوتا کہ آ پ ( قیام کے بعد ) رکوع کرچکے ہیں تو اس قیام کی لمبائی کی بنا پر وہ کبھی نہ کہہ سکتا کہ آپ ( ایک دفعہ ) رکوع کرچکے ہیں ۔","",{"u2":"خالد بن حارث نے کہا: ہم سے ابن جریج نے حدیث بیان کی،(انھوں نے کہا:) مجھ سے منصور بن عبدالرحٰمن نے اپنی والدہ صفیہ بنت شیبہ سے اور انھوں نے حضرت اسماء بنت ابی بکر رضی اللہ عنہا سے روایت کی، انھوں نے کہا: ایک دن نبی اکرم صلی اللہ علیہ وسلم تیزی سے (لپک کر) گئے۔ کہا: ان کی مراد اس دن سے تھی جس دن سورج کو گرہن لگا تھا۔۔ تو(جلدی میں) آپ نے ایک زنانہ قمیض اٹھالی حتیٰ کہ پیچھے سے آپ کو آپ کی چادر لا کر دی گئی۔ آپ نے لوگوں کی امامت کرتے ہوئے انتہائی طویل قیام کیا۔ اگرکوئی ایسا انسان آتا جس کو یہ پتہ نہ ہوتا کہ آ پ (قیام کے بعد) رکوع کرچکے ہیں تو اس قیام کی لمبائی کی بنا پر وہ کبھی نہ کہہ سکتا کہ آپ (ایک دفعہ) رکوع کرچکے ہیں۔"}],[2050,"یحیٰ اموی نے کہا : ہم سے ا بن جریج نے اسی سند کے ساتھ اسی ( سابقہ حدیث ) کے مانند حدیث بیان کی ۔ ( اس میں ) انھوں نے کہا : ( آپ نے ) طویل قیام کیا ، آپ قیام کرتے ، پھر رکو ع میں چلے جاتے ۔ اور اس میں یہ اضافہ کیا : میں ( بیٹھنے کا ارادہ کرتی تو ) ایسی عورت کو دیکھنے لگتی جو مجھ سے بڑھ کر عمر رسیدہ ہوتی اور کسی دوسری کو دیکھتی جو مجھ سے زیادہ بیمار ہوتی ( اور ان سے حوصلہ پا کر کھڑی رہتی ۔)","",{"u2":"یحیٰ اموی نے کہا: ہم سے ا بن جریج نے اسی سند کے ساتھ اسی (سابقہ حدیث) کے مانند حدیث بیان کی۔(اس میں) انھوں نے کہا: (آپ نے) طویل قیام کیا، آپ قیام کرتے، پھر رکو ع میں چلے جاتے۔ اور اس میں یہ اضافہ کیا:میں (بیٹھنے کا ارادہ کرتی تو) ایسی عورت کو دیکھنے لگتی جو مجھ سے بڑھ کر عمر رسیدہ ہوتی اور کسی دوسری کو دیکھتی جو مجھ سے زیادہ بیمار ہوتی(اور ان سے حوصلہ پا کر کھڑی رہتی۔)"}],[2051,"وہیب نے کہا : ہمیں منصور نے اپنی والدہ ( صفیہ ) سے حدیث بیان کی ، انھوں نے اسماء بنت ابی بکر رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے دور میں سورج کوگرہن لگ گیا تو آپ جلدی سے لپکے ( اور ) غلطی سے زنانہ قمیص اٹھا لی حتیٰ کہ اسکے بعد ( پیچھے سے ) آپ کی چادر آپ کو لاکر دی گئی ۔ کہا : میں اپنی ضرورت سے فارغ ہوئی اور ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے گھر سے ) مسجد میں داخل ہوئی تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو قیام کی حالت میں دیکھا ۔ میں بھی آپ کی اقتداء میں کھڑی ہوگئی ۔ آپ نے بہت لمبا قیام کیا حتیٰ کہ میں نے اپنے آپ کو اس حالت میں دیکھا کہ میں بیٹھنا چاہتی تھی ، پھر میں کسی کمزور عورت کی طرف متوجہ ہوتی اور ( دل میں ) کہتی : یہ تو مجھ سے بھی زیادہ کمزور ہے ۔ ( اور کھڑی رہتی ہے ) پھر آپ نے رکوع کیا تو رکوع کو انتہائی لمبا کردیا ، پھر آپ نے ( رکوع سے ) اپناسر اٹھایا تو قیام کو بہت طول دیا ۔ یہاں تک کہ اگر کوئی آدمی ( اس حالت میں ) آتا تو اسے خیال ہوتا کہ ابھی تک آپ نے رکوع نہیں کیا ۔","",{"u2":"وہیب نے کہا:ہمیں منصور نے اپنی والدہ(صفیہ) سے حدیث بیان کی،انھوں نے اسماء بنت ابی بکر رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم کے دور میں سورج کوگرہن لگ گیا تو آپ جلدی سے لپکے(اور) غلطی سے زنانہ قمیص اٹھا لی حتیٰ کہ اسکے بعد(پیچھےسے)آپ کی چادر آپ کو لاکر دی گئی۔کہا:میں اپنی ضرورت سے فارغ ہوئی اور(حضرت عائشہ رضی اللہ تعالیٰ عنہا کے گھر سے)مسجد میں داخل ہوئی تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو قیام کی حالت میں دیکھا۔میں بھی آپ کی اقتداء میں کھڑی ہوگئی۔آپ نے بہت لمبا قیام کیا حتیٰ کہ میں نے اپنے آپ کو اس حالت میں دیکھا کہ میں بیٹھنا چاہتی تھی،پھر میں کسی کمزور عورت کی طرف متوجہ ہوتی اور(دل میں) کہتی:یہ تو مجھ سے بھی زیادہ کمزور ہے۔(اور کھڑی رہتی ہے)پھر آپ نے رکوع کیا تو رکوع کو انتہائی لمبا کردیا،پھر آپ نے(رکوع سے) اپناسر اٹھایا تو قیام کو بہت طول دیا۔یہاں تک کہ اگر کوئی آدمی(اس حالت میں)آتا تو اسے خیال ہوتا کہ ابھی تک آپ نے رکوع نہیں کیا۔"}],[2052,"حفص بن میسرہ نے کہا : زید بن اسلم نے مجھے عطاء بن یسار سے حدیث بیان کی ، انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے ر وایت کی ، انھوں نے کہا ، رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے اور آپ کی معیت میں لوگوں نے نماز پڑھی ۔ آپ نے بہت طویل قیام کیا ، سورہ بقرہ کے بقدر ، پھر آپ نے بہت طویل رکوع کیا ، پھر آپ نے سر اٹھایا اور طویل قیام کیا اور وہ پہلے قیام سے کم تھا ، پھر آپ نے طویل رکوع کیا اور وہ پہلے رکوع سے کم تھا ، پھر آپ نے سجدے کیے ، پھر آپ نے طویل قیام کیا اور وہ پہلے قیام سے کچھ کم تھا ، پھر آپ نے طویل ر کوع کیا اور وہ پہلے رکوع سے کم تھا ، پھر آپ نے سر اٹھایا اور طویل قیام کیا اور وہ اپنے سے پہلے والے قیام سے کم تھا ، پھر آپ نے لمبا رکوع کیا اور وہ پہلے کے رکوع سے کم تھا ، پھر آپ نے سجدے کیے ، پھر آپ نے سلام پھیرا تو سورج روشن ہوچکا تھا ۔ پھر آپ نے ارشاد فرمایا : \" سورج اور چاند اللہ تعالیٰ کی دو نشانیوں میں سے نشانیاں ہیں ، وہ کسی کی موت پر گرہن زدہ نہیں ہوتے اور نہ کسی کی زندگی کے سبب سے ( انھیں گرہن لگتاہے ) جب تم ( ان کو ) اس طرح دیکھ تو اللہ کا زکر کرو ( نماز پڑھو ۔ ) \" لوگوں نے کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم !ہم نے آپ صلی اللہ علیہ وسلم کو دیکھا ، آپ نے اپنے کھڑے ہونے کی اس جگہ پر کوئی چیز لینے کی کوشش کی ، پھرہم نے دیکھاکہ آپ رک گئے ۔ آپ نے فرمایا : \" میں نے جنت دیکھی اور میں نے اس میں سے ایک گچھہ لینا چاہا اور اگر میں اس کو پکڑ لیتا تو تم ر ہتی دنیا تک اس میں سے کھاتے رہتے ( اور ) میں نے جہنم دیکھی ، میں نے آج جیسا منظر کبھی نہیں دیکھا اور میں نے اہل جہنم کی اکثریت عورتوں کی دیکھی ۔ \" لوگوں نے پوچھا : اللہ کے رسول صلی اللہ علیہ وسلم ! ( یہ ) کس وجہ سے؟آپ نے فرمایا : \" ان کے کفر کی وجہ سے ۔ \" کہا گیا : کیا وہ اللہ کے ساتھ کفر کرتی ہیں؟آپ نے فرمایا : \" رفیق زندگی کا کفران ( ناشکری ) کرتی ہیں ۔ اور احسان کا کفران کر تی ہیں ۔ اگر تم ان میں سے کسی کے ساتھ ہمیشہ حسن سلوک کرتے رہو پھر وہ تم سے کسی دن کوئی ( ناگوار ) بات دیکھے تو کہہ دے گی : تم سے میں نے کبھی کوئی خیر نہیں دیکھی ۔","",{"u2":"حفص بن میسرہ نے کہا:زید بن اسلم نے مجھے عطاء بن یسار سے حدیث بیان کی،انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے ر وایت کی،انھوں نے کہا،رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں سورج کو گرہن لگ گیا تورسول اللہ صلی اللہ علیہ وسلم نے اور آپ کی معیت میں لوگوں نے نماز پڑھی۔آپ نے بہت طویل قیام کیا،سورہ بقرہ کے بقدر،پھر آپ نے بہت طویل رکوع کیا،پھر آپ نے سر اٹھایا اور طویل قیام کیا اور وہ پہلے قیام سے کم تھا،پھر آپ نے طویل رکوع کیا اور وہ پہلے رکوع سے کم تھا،پھر آپ نے سجدے کیے،پھر آپ نے طویل قیام کیا اور وہ پہلے قیام سے کچھ کم تھا،پھر آپ نے طویل ر کوع کیا اور وہ پہلے رکوع سے کم تھا،پھر آپ نے سر اٹھایا اور طویل قیام کیا اور وہ اپنے سے پہلے والے قیام سے کم تھا،پھر آپ نے لمبا رکوع کیا اور وہ پہلے کے رکوع سے کم تھا،پھر آپ نے سجدے کیے،پھر آپ نے سلام پھیرا تو سورج روشن ہوچکا تھا۔پھر آپ نے ارشاد فرمایا:\"سورج اور چاند اللہ تعالیٰ کی دو نشانیوں میں سےنشانیاں ہیں،وہ کسی کی موت پر گرہن زدہ نہیں ہوتے اور نہ کسی کی زندگی کے سبب سے(انھیں گرہن لگتاہے)جب تم(ان کو) اس طرح دیکھ تو اللہ کا زکر کرو(نماز پڑھو۔)\"لوگوں نے کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!ہم نے آپ صلی اللہ علیہ وسلم کو دیکھا،آپ نے اپنے کھڑےہونے کی اس جگہ پر کوئی چیز لینے کی کوشش کی،پھرہم نے دیکھاکہ آپ رک گئے۔آپ نے فرمایا:\"میں نے جنت دیکھی اور میں نے اس میں سے ایک گچھہ لینا چاہا اور اگر میں اس کو پکڑ لیتا تو تم ر ہتی دنیا تک اس میں سے کھاتے رہتے(اور) میں نے جہنم دیکھی،میں نے آج جیسا منظر کبھی نہیں دیکھا اور میں نے اہل جہنم کی اکثریت عورتوں کی دیکھی۔\"لوگوں نے پوچھا:اللہ کے رسول صلی اللہ علیہ وسلم!(یہ) کس وجہ سے؟آپ نے فرمایا:\"ان کے کفر کی وجہ سے۔\"کہا گیا:کیا وہ اللہ کے ساتھ کفر کرتی ہیں؟آپ نے فرمایا:\"رفیق زندگی کا کفران(ناشکری) کرتی ہیں۔اوراحسان کا کفران کر تی ہیں۔اگر تم ان میں سے کسی کے ساتھ ہمیشہ حسن سلوک کرتے رہو پھر وہ تم سے کسی دن کوئی(ناگوار) بات دیکھے تو کہہ دے گی:تم سے میں نے کبھی کوئی خیر نہیں دیکھی۔\""}],[2053,"امام مالک نے زید بن اسلم سے اسی سند کے ساتھ اس ( مذکورہ حدیث ) کے مانند روایت کی ، البتہ انھوں نے \" ثم رايناك كففت کے بجائے ) ثم رايناك تكعكعت \" ( پھر ہم نے آپ کو دیکھا کہ آپ آگے بڑھنے سے باز رہے)","",{"u2":"امام مالک نے زید بن اسلم سے اسی سند کے ساتھ اس (مذکورہ حدیث) کے مانند روایت کی،البتہ انھوں نے \"ثم رایناک کففت کے بجائے) ثم رایناک تکعکعت \"(پھر ہم نے آپ کو دیکھا کہ آپ آگے بڑھنے سے باز رہے)"}],[2054,"اسماعیل ابن علیہ نے سفیان سے ، انھوں نے حبیب بن ابی ثابت سے ، انھوں نے طاوس سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : جب سورج کو گرہن لگا تو آپ صلی اللہ علیہ وسلم نے چار سجدوں کے ساتھ آٹھ رکوع کیے ۔ اور سیدنا علی رضی اللہ تعالیٰ عنہ سے بھی اسی کے مانند روایت کی گئی ہے ۔","",{"u2":"اسماعیل ابن علیہ نے سفیان سے،انھوں نے حبیب بن ابی ثابت سے،انھوں نے طاوس سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:جب سورج کو گرہن لگا تو آپ صلی اللہ علیہ وسلم نے چار سجدوں کے ساتھ آٹھ رکوع کیے۔اور حضرت علی رضی اللہ تعالیٰ عنہ سے بھی اسی کے مانند روایت کی گئی ہے۔"}],[2055,"یحییٰ نے سفیان سے حدیث بیان کی ، انھوں نے کہا : ہمیں حبیب نے طاوس سے حدیث سنائی ، انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے کسوف ( کے دوران ) میں نماز پڑھائی ، قراءت کی پھر رکوع کیا ، پھر قرءات کی ، پھر رکوع کیا ، پھر قراءت کی ۔ پھر رکوع کیا ۔ پھر قراءت کی ۔ پھر رکوع کیا ۔ پھر سجدے کئے ۔ کہا : دوسری ( رکعت ) بھی اسی طرح تھی ۔","",{"u2":"یحییٰ نے سفیان سے حدیث بیان کی،انھوں نے کہا:ہمیں حبیب نے طاوس سے حدیث سنائی،انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے کسوف(کے دوران) میں نماز پڑھائی،قراءت کی پھر رکوع کیا،پھر قرءات کی،پھر رکوع کیا،پھر قراءت کی۔پھر رکوع کیا۔پھر قراءت کی۔پھر رکوع کیا۔پھر سجدے کئے۔کہا:دوسری(رکعت)بھی اسی طرح تھی۔"}],[2056,"سیدنا عبداللہ بن عمرو بن عاص رضی اللہ تعالیٰ عنہ نے کہا : کہ جب رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں گرہن ہوا تو \" الصلواة جامعة \" ( کے الفاظ کے ساتھ ) اعلان کیاگیا ۔ رسول اللہ صلی اللہ علیہ وسلم نے ایک رکعت میں دو رکوع کیے ، پھر دوسری رکعت کے لئے کھڑے ہوگئے اور ایک رکعت میں دو رکوع کیے ، پھر سورج سے گرہن زائل کردیا گیا تو سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : میں نے نہ کبھی ایسا رکوع کیا اور نہ کبھی ایسا سجدہ کیا جو اس سے زیادہ لمبا ہو ۔","",{"u2":"حضرت عبداللہ بن عمرو بن عاص رضی اللہ تعالیٰ عنہ نے کہا:کہ جب رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں گرہن ہواتو\" الصلواۃ جامعۃ \"(کے الفاظ کے ساتھ) اعلان کیاگیا۔رسول اللہ صلی اللہ علیہ وسلم نے ایک رکعت میں دو رکوع کیے،پھر دوسری رکعت کے لئے کھڑے ہوگئے اور ایک رکعت میں دو رکوع کیے،پھر سورج سے گرہن زائل کردیا گیا تو حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا:میں نے نہ کبھی ایسا رکوع کیا اور نہ کبھی ایسا سجدہ کیا جو اس سے زیادہ لمبا ہو۔"}],[2057,"ہشیم نے اسماعیل سے ، انھوں نے قیس بن ابی حازم سے ، اور انھوں نے ابو مسعود انصاری رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سورج اور چاند اللہ تعالیٰ کی دو نشانیوں میں سے نشانیاں ہیں ۔ اللہ تعالیٰ ان کے ذریعے سے اپنے بندوں کو خوف دلاتاہے ۔ اور ان دونوں کو انسانوں میں سے کسی کی موت کی بناء پر گرہن نہیں لگتا ، لہٰذا جب تم ان میں سے کوئی نشانی دیکھو تو نماز پڑھو اور اللہ تعالیٰ کو پکارو یہاں تک کہ جو کچھ تمہارے ( ساتھ ہوا ) ہے وہ کھل جائے ۔","",{"u2":"ہشیم نے اسماعیل سے،انھوں نے قیس بن ابی حازم سے،اور انھوں نے ابو مسعود انصاری رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"سورج اور چاند اللہ تعالیٰ کی دو نشانیوں میں سے نشانیاں ہیں۔اللہ تعالیٰ ان کے ذریعے سے اپنے بندوں کو خوف دلاتاہے۔اور ان دونوں کو انسانوں میں سے کسی کی موت کی بناء پر گرہن نہیں لگتا،لہذا جب تم ان میں سے کوئی نشانی دیکھو تو نماز پڑھو اور اللہ تعالیٰ کو پکارو یہاں تک کہ جو کچھ تمہارے(ساتھ ہوا) ہے وہ کھل جائے۔\""}],[2058,"معتمر نے اسماعیل سے ، انھوں نے قیس سے اور انھوں نے سیدنا ابو مسعود رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سورج اور چاند کو لوگوں میں سے کسی کے مرنے پر گرہن نہیں لگتا بلکہ وہ اللہ تعالیٰ کی نشانیوں میں سےدو نشانیاں ہیں ۔ لہٰذا جب تم اس ( گرہن ) کو دیکھو تو قیام کرو اور نماز پڑھو ۔","",{"u2":"معتمر نے اسماعیل سے،انھوں نے قیس سے اور انھوں نے حضرت ابو مسعود رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"سورج اور چاند کو لوگوں میں سے کسی کے مرنے پر گرہن نہیں لگتا بلکہ وہ اللہ تعالیٰ کی نشانیوں میں سےدو نشانیاں ہیں۔لہذا جب تم اس (گرہن) کو دیکھو تو قیام کرو اور نماز پڑھو۔\""}],[2059,"وکیع ، ابواسامہ ، ابن نمیر ، جریر ، سفیان ، اور مروان سب نے اسماعیل سے اسی سند کے ساتھ روایت کی ، سفیان اور وکیع ، کی روایت میں ہے کہ ابراہیم رضی اللہ تعالیٰ عنہ کی وفات کے دن سورج کو گرہن لگا تو لوگوں نے کہا : سورج کو ابراہیم رضی اللہ تعالیٰ عنہ کی وفات کی بناء پر گرہن لگا ہے ۔","",{"u2":"وکیع،ابواسامہ،ابن نمیر،جریر،سفیان،اورمروان سب نے اسماعیل سے اسی سند کے ساتھ روایت کی،سفیان اوروکیع،کی روایت میں ہے کہ ابراہیم رضی اللہ تعالیٰ عنہ کی وفات کے دن سورج کو گرہن لگا تو لوگوں نے کہا:سورج کو ابراہیم رضی اللہ تعالیٰ عنہ کی وفات کی بناء پر گرہن لگا ہے۔"}],[2060,"ابو عامر اشعری عبداللہ بن براد اور محمد بن علاء نے کہا : ہمیں ابو اسامہ نے برید سے حدیث سنائی ، انھوں نے ابو بردہ سے اور انھوں نے ابو موسیٰ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج کو گرہن لگ گیا تو آپ تیزی سے اٹھے ، آپ کو خوف لاحق ہوا کہ مبادا قیامت ( آگئی ) ہو ، یہاں تک کہ آپ مسجد میں تشریف لے آئے اور آپ کھڑے ہوئے بہت طویل قیام ، رکوع اور سجدے کے ساتھ نماز پڑھتے رہے ، میں نے کبھی آپ کو نہیں دیکھا تھا کہ کسی نماز میں ( آپ نے ) ایسا کیا ہو ، پھر آپ نے فرمایا : \" یہی نشانیاں ہیں جو اللہ تعالیٰ بھیجتا ہے ۔ یہ کسی کی موت یا زندگی کی بناء پر نہیں ہوتیں ، بلکہ اللہ ان کو بھیجتا ہے تاکہ ان کے زریعے سے اپنے بندوں کو ( قیامت سے ) خوف دلائے ، اس لئے جب تم ان میں سے کوئی نشانی دیکھو تو جلد از جلد اس کے ذکر ، دعا اور استغفار کی طرف لپکو ، \" ابن علاء کی ر وایت میں \" خسفت الشمس \" کے بجائے ) كسفت الشمس ( سورج کو گرہن لگا ) کے الفاظ ہیں ( معنی ایک ہی ہے ) اور انھوں نے ( يخوف بها عباده ان کے ذریعے سے اپنے بندوں کو خوف دلاتا ہے کے بجائے ) يخوف عباده ( اپنے بندوں کو خوف دلاتا ہے ) کہا ۔","",{"u2":"ابو عامر اشعری عبداللہ بن براد اور محمد بن علاء نے کہا:ہمیں ابو اسامہ نے برید سے حدیث سنائی،انھوں نے ابو بردہ سے اور انھوں نے ابو موسیٰ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج کو گرہن لگ گیا تو آپ تیزی سے اٹھے،آپ کو خوف لاحق ہوا کہ مبادا قیامت (آگئی)ہو،یہاں تک کہ آپ مسجد میں تشریف لے آئے اور آپ کھڑے ہوئے بہت طویل قیام،رکوع اورسجدے کے ساتھ نماز پڑھتے رہے،میں نے کبھی آپ کو نہیں دیکھا تھا کہ کسی نماز میں(آپ نے) ایسا کیا ہو،پھر آپ نے فرمایا:\"یہی نشانیاں ہیں جو اللہ تعالیٰ بھیجتا ہے۔یہ کسی کی موت یا زندگی کی بناء پر نہیں ہوتیں،بلکہ اللہ ان کو بھیجتا ہے تاکہ ان کے زریعے سے اپنے بندوں کو(قیامت سے) خوف دلائے،اس لئے جب تم ان میں سے کوئی نشانی دیکھو تو جلد از جلد اس کے ذکر،دعا اور استغفار کی طرف لپکو،\"ابن علاء کی ر وایت میں\"خسفت الشمس\" کے بجائے) کسفت الشمس (سورج کو گرہن لگا) کے الفاظ ہیں(معنی ایک ہی ہے) اور انھوں نے(یخوف بہا عبادہ ان کے ذریعے سے اپنے بندوں کو خوف دلاتا ہے کے بجائے) یخوف عبادہ (اپنے بندوں کو خوف دلاتا ہے) کہا۔"}],[2061,"بشر بن مفضل نے کہا : جریری نے ہمیں ابو علاء حیان بن عمیر سے حدیث بیان کی ، انھوں نے سیدنا عبدالرحمان بن سمرہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : میں ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں اپنے تیروں کے زریعے سے تیر انداز کررہا تھا کے سورج کو گرہن لگ گیا ، تو نے ان کو پھینکا اور ( دل میں ) کہا کہ میں آج ہرصورت دیکھوں گا کہ سورج گرہن میں رسول اللہ صلی اللہ علیہ وسلم پر کیا نئی کیفیت طاری ہوتی ہے ۔ میں آپ کے پاس پہنچا تو ( دیکھا کہ ) آپ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھ اٹھائے ہوئے تھے ، ( اللہ کو ) پکار رہے تھے ، اس کی بڑائی بیان کررہے تھے ، اس کی حمد و ثنا بیان کررہے تھے اور لاالٰہ الا اللہ کا ورد فرما رہے تھے ، یہاں تک کہ سورج سے گرہن ہٹا دیاگیا ، پھر آپ صلی اللہ علیہ وسلم نے ( ہررکعت میں ) دو سورتیں پڑھیں اور دو رکعتیں ادا کیں ۔","",{"u2":"بشر بن مفضل نے کہا:جریری نے ہمیں ابو علاء حیان بن عمیر سے حدیث بیان کی،انھوں نے حضرت عبدالرحمان بن سمرہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:میں ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں اپنے تیروں کے زریعے سے تیر انداز کررہا تھا کے سورج کو گرہن لگ گیا،تو نے ان کو پھینکا اور(دل میں) کہا کہ میں آج ہرصورت دیکھوں گا کہ سورج گرہن میں رسول اللہ صلی اللہ علیہ وسلم پر کیا نئی کیفیت طاری ہوتی ہے۔میں آپ کے پاس پہنچا تو(دیکھا کہ) آپ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھ اٹھائے ہوئے تھے،(اللہ کو) پکار رہے تھے،اس کی بڑائی بیان کررہے تھے،اس کی حمد و ثنا بیان کررہے تھے اور لاالٰہ الا اللہ کا ورد فرما رہے تھے،یہاں تک کہ سورج سے گرہن ہٹا دیاگیا، پھر آپ صلی اللہ علیہ وسلم نے(ہررکعت میں) دو سورتیں پڑھیں اور دو رکعتیں ادا کیں۔"}],[2062,"عبدالاعلیٰ بن عبدالاعلیٰ نے جریری سے ، انھوں نے حیان بن نمیر سے اور انھوں نے سیدنا عبدالرحمان بن سمرہ رضی اللہ تعالیٰ عنہ سے روایت کی اور وہ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ رضوان اللہ عنھم اجمعین میں سے تھے ، انھوں نے کہا : میں رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں ایک د ن مدینہ میں ا پنے تیروں سے نشانے لگا رہا تھا کہ اچانک سورج کو گرہن لگ گیا ، اس پر میں نے انھیں ( تیروں کو ) پھینکا اور ( دل میں ) کہا : اللہ کی قسم!میں ضرور د یکھوں گا کہ سورج کے گرہن کے اس و قت میں رسول اللہ صلی اللہ علیہ وسلم پر کیا نئی کیفیت طاری ہوئی ہے ۔ کہا : میں آپ کے پاس آیا ، آپ نماز میں کھرے تھے ، دونوں ہاتھ اٹھائے ہوئے تھے ، پھر آپ نے تسبیح ، حمد و ثنا لاالٰہ الا اللہ اور اللہ کی بڑائی کا ورد اور د عا مانگنی شروع کردی یہاں تک کہ سورج کا گرہن چھٹ گیا ، کہا : اور جب سورج کا گرہن چھٹ گیا تو آپ صلی اللہ علیہ وسلم نے دو سورتیں پڑھیں اور دو رکعت نماز ادا کی ۔","",{"u2":"عبدالاعلیٰ بن عبدالاعلیٰ نے جریری سے،انھوں نے حیان بن نمیر سے اور انھوں نے حضرت عبدالرحمان بن سمرہ رضی اللہ تعالیٰ عنہ سے روایت کی اور وہ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ رضوان اللہ عنھم اجمعین میں سے تھے،انھوں نے کہا:میں رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں ایک د ن مدینہ میں ا پنے تیروں سے نشانے لگا رہا تھا کہ اچانک سورج کو گرہن لگ گیا،اس پر میں نے انھیں(تیروں کو) پھینکا اور(دل میں) کہا:اللہ کی قسم!میں ضرور د یکھوں گا کہ سورج کے گرہن کے اس و قت میں ر سول اللہ صلی اللہ علیہ وسلم پر کیا نئی کیفیت طاری ہوئی ہے۔کہا:میں آپ کے پاس آیا،آپ نماز میں کھرے تھے،دونوں ہاتھ اٹھائے ہوئے تھے،پھر آپ نے تسبیح،حمد و ثنا لاالٰہ الا اللہ اور اللہ کی بڑائی کا ورد اور د عا مانگنی شروع کردی یہاں تک کہ سورج کا گرہن چھٹ گیا،کہا:اور جب سورج کا گرہن چھٹ گیا تو آپ صلی اللہ علیہ وسلم نے دو سورتیں پڑھیں اور دو رکعت نماز ادا کی۔"}],[2063,"سالم بن نوح نے کہا : ہمیں جریری نے حیان بن عمیر سے خبر دی اور انھوں نے عبدالرحمان بن سمرہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ایک دفعہ میں رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں باہر نکل کر اپنے تیروں سے نشانہ بازی کی مشق کررہا تھا کہ سورج گرہن ہوگیا ، پھر ( سالم بن نوح نے ) ان دونوں ( بشر اور عبدالاعلیٰ ) کی حدیث کی طرح بیان کیا ۔","",{"u2":"سالم بن نوح نے کہا:ہمیں جریری نے حیان بن عمیر سے خبر دی اور انھوں نے عبدالرحمان بن سمرہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:ایک دفعہ میں رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں باہر نکل کر اپنے تیروں سے نشانہ بازی کی مشق کررہا تھا کہ سورج گرہن ہوگیا،پھر(سالم بن نوح نے) ان دونوں(بشر اور عبدالاعلیٰ) کی حدیث کی طرح بیان کیا۔"}],[2064,"سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے ، وہ رسول اللہ صلی اللہ علیہ وسلم سے یہ خبر سنایا کرتے تھے ۔ کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" یقیناً سورج اور چاند کو کسی شخص کی موت یا زندگی کی وجہ سے گرہن نہیں لگتا بلکہ یہ اللہ کی نشانیوں میں سے نشانی ہیں ، جب تم انھیں ( اس طرح ) دیکھو تو نماز پڑھو ۔","",{"u2":"حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے،وہ رسول اللہ صلی اللہ علیہ وسلم سے یہ خبر سنایا کرتے تھے۔ کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\"یقیناً سورج اور چاند کو کسی شخص کی موت یا زندگی کی وجہ سے گرہن نہیں لگتا بلکہ یہ اللہ کی نشانیوں میں سے نشانی ہیں،جب تم انھیں(اس طرح) دیکھو تو نماز پڑھو۔\""}],[2065,"سیدنا مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں سورج کو گرہن لگا ، اسی دن جب ابراہیم رضی اللہ تعالیٰ عنہ فوت ہوئے ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سورج اور چاند اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں ، ان کو نہ کسی کی موت سے گرہن لگتاہے اور نہ کسی کی زندگی سے اس لئے جب تم ان کو ( گرہن لگا ) دیکھو تو اللہ کو پکارو اور نماز پڑھو یہاں تک کہ گرہن زائل ہوجائے ۔","",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں سورج کو گرہن لگا،اسی دن جب ابراہیم رضی اللہ تعالیٰ عنہ فوت ہوئے،تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"سورج اور چاند اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں،ان کو نہ کسی کی موت سے گرہن لگتاہے اور نہ کسی کی زندگی سے اس لئے جب تم ان کو(گرہن لگا) دیکھو تو اللہ کو پکارو اور نماز پڑھو یہاں تک کہ گرہن زائل ہوجائے۔\""}],[2066,"بشر بن مفضل نے کہا : ہمیں عمارہ بن غزیہ نے یحییٰ بن عمارہ سے حدیث بیان کی ، انھوں نے کہا : میں نے سیدنا ابو سعید خدری رضی اللہ تعالیٰ عنہ سے سنا ، کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اپنے مرنے والے لوگوں کو لاالٰہ الا اللہ کی تلقین کرو ۔","",{"u2":"بشر بن مفضل نے کہا:ہمیں عمارہ بن غزیہ نے یحییٰ بن عمارہ سے حدیث بیان کی،انھوں نے کہا:میں نے حضرت ابو سعید خدری رضی اللہ تعالیٰ عنہ سے سنا،کہہ رہے تھے:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اپنے مرنے والے لوگوں کو لاالٰہ الا اللہ کی تلقین کرو۔\""}],[2067,"عبدالعزیز دراوردی اور سلیمان بن بلال نے اسی ( مذکورہ بالا ) سند سے ( یہی ) حدیث بیان کی ۔","",{"u2":"عبدالعزیز دراوردی اور سلیمان بن بلال نے اسی(مذکورہ بالا) سند سے(یہی) حدیث بیان کی۔"}],[2068,"سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نےفرمایا : \" اپنے مرنے والے لوگوں کو لاالٰہ الا اللہ کی تلقین کرو ۔","",{"u2":"حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نےفرمایا:\"اپنے مرنے والے لوگوں کو لاالٰہ الا اللہ کی تلقین کرو۔\""}],[2069,"اسماعیل بن جعفر نےکہا : مجھے سعد بن سعید نے عمر بن کثیر بن افلح سے خبر دی ، انھوں نے ( عمر ) ابن سفینہ سے اور انھوں نے سیدہ ام سلمہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \"\" کوئی مسلمان نہیں جسے مصیبت پہنچے اور وہ ( وہی کچھ ) کہے جس کا اللہ نے اسے حکم دیا ہے : \"\" یقینا ہم اللہ کے ہیں اور اسی کی طرف لوٹنے والے ہیں ، اے اللہ!مجھے میری مصیبت پر اجر دے اور مجھے ( اس کا ) اس سے بہتر بدل عطا فرما \"\" مگر اللہ تعالیٰ اسے اس ( ضائع شدہ چیز ) کا بہتر بدل عطا فرمادیتا ہے ۔ \"\" ( ام سلمہ رضی اللہ تعالیٰ عنہا نے ) کہا : جب ( میرے خاوند ) ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوگئے تو میں نے ( دل میں ) کہا : کون سا مسلمان ابو سلمہ رضی اللہ تعالیٰ عنہ سے بہتر ( ہوسکتا ) ہے!وہ پہلا گھرانہ ہے جس نے رسول اللہ صلی اللہ علیہ وسلم کی طرف ہجرت کی ۔ پھر میں نے وہ ( کلمات ) کہے تو اللہ تعالیٰ نے مجھے رسول اللہ صلی اللہ علیہ وسلم کی صورت میں اس کا بدل عطا فرمادیا ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے اپنے لئے نکاح کا پیغام دیتے ہوئے حاطب بن ابی بلتعہ رضی اللہ تعالیٰ عنہ کو میرے پا س بھیجا تو میں نے کہا : میری ایک بیٹی ہے اور میں بہت غیرت کرنے والی ہوں ۔ اس پر آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اس کی بیٹی کے بارے میں ہم اللہ سے دعا کرتے ہیں کہ وہ اس کو اس ( ام سلمہ رضی اللہ تعالیٰ عنہا ) سے بے نیاز کردے اور میں اللہ سے دعا کرتا ہوں کہ وہ ( بے جا ) غیرت کو ( اس سے ) ہٹا دے ۔","",{"u2":"اسماعیل بن جعفر نےکہا:مجھے سعد بن سعید نے عمر بن کثیر بن افلح سے خبر دی،انھوں نے(عمر) ابن سفینہ سے اور انھوں نے حضرت ام سلمہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:\"کوئی مسلمان نہیں جسے مصیبت پہنچے اور وہ(وہی کچھ) کہے جس کا اللہ نے اسے حکم دیا ہے:\"یقینا ہم اللہ کے ہیں اور اسی کی طرف لوٹنے والے ہیں،اے اللہ!مجھے میری مصیبت پر اجر دے اور مجھے(اس کا) اس سے بہتر بدل عطا فرما\"مگر اللہ تعالیٰ اسے اس(ضائع شدہ چیز) کا بہتر بدل عطا فرمادیتا ہے۔\"\n(ام سلمہ رضی اللہ تعالیٰ عنہا نے) کہا:جب (میرے خاوند) ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوگئے تو میں نے(دل میں) کہا:کون سا مسلمان ابو سلمہ رضی اللہ تعالیٰ عنہ سے بہتر (ہوسکتا) ہے!وہ پہلا گھرانہ ہے جس نے رسول اللہ صلی اللہ علیہ وسلم کی طرف ہجرت کی۔پھر میں نے وہ(کلمات) کہےتو اللہ تعالیٰ نے مجھے رسول اللہ صلی اللہ علیہ وسلم کی صورت میں اس کا بدل عطا فرمادیا،کہا:رسول اللہ صلی اللہ علیہ وسلم نے اپنے لئے نکاح کا پیغام دیتے ہوئے حاطب بن ابی بلتعہ رضی اللہ تعالیٰ عنہ کو میرے پا س بھیجا تو میں نے کہا:میری ایک بیٹی ہے اور میں بہت غیرت کرنے والی ہوں۔اس پر آپ صلی اللہ علیہ وسلم نے فرمایا:\"اس کی بیٹی کے بارے میں ہم اللہ سے دعا کرتے ہیں کہ وہ اس کو اس(ام سلمہ رضی اللہ تعالیٰ عنہا) سے بے نیاز کردے اور میں اللہ سے دعا کرتا ہوں کہ وہ(بے جا)غیرت کو(اس سے) ہٹا دے۔\""}],[2070,"ابو اسامہ نے سعد بن سعید سے روایت کی ، انھوں نے کہا : مجھے عمر بن کثیر بن افلح نے خبر دی ، انھوں نے کہا : میں نے ابن سفینہ سے سنا ، وہ بیان کررہے تھے کہ انھوں نے نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ کو یہ کہتے ہوئے سناکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \"\" کوئی بندہ نہیں جسے مصیبت پہنچے اور وہ کہے : بےشک ہم اللہ کے ہیں اور اسی کی طرف لوٹنے والے ہیں ۔ اے اللہ!مجھے میری مصیبت کا اجردے اور مجھے اس کا بہتر بدل عطا فرما ، مگر اللہ تعالیٰ اسے اس کی مصیبت کا اجر دیتاہے اور اسے اس کا بہتر بدل عطا فرماتاہے ۔ \"\" ( سیدہ ام سلمہ رضی اللہ تعالیٰ عنہا نے ) کہا : تو جب ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوگئے ، میں نے اس طرح کہا جس طرح نبی اکرم صلی اللہ علیہ وسلم نے مجھے حکم دیا تھا تو اللہ تعالیٰ نے مجھے رسول اللہ صلی اللہ علیہ وسلم کی صورت میں ان سے بہتر بدل عطا فرمادیا ۔","",{"u2":"ابو اسامہ نے سعد بن سعید سے روایت کی،انھوں نے کہا:مجھے عمر بن کثیر بن افلح نے خبر دی،انھوں نے کہا:میں نے ابن سفینہ سے سنا،وہ بیان کررہے تھے کہ انھوں نے نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ کو یہ کہتے ہوئے سناکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:\"کوئی بندہ نہیں جسے مصیبت پہنچے اور وہ کہے:بےشک ہم اللہ کے ہیں اور اسی کی طرف لوٹنے والے ہیں۔اے اللہ!مجھے میری مصیبت کا اجردے اور مجھے اس کا بہتر بدل عطا فرما،مگر اللہ تعالیٰ اسے اس کی مصیبت کا اجر دیتاہے اور اسے اس کا بہتر بدل عطا فرماتاہے۔\"\n(حضرت ام سلمہ رضی اللہ تعالیٰ عنہا نے)کہا:تو جب ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوگئے،میں نے اس طرح کہا جس طرح نبی اکرم صلی اللہ علیہ وسلم نے مجھے حکم دیا تھا تو اللہ تعالیٰ نے مجھے رسول اللہ صلی اللہ علیہ وسلم کی صورت میں ان سے بہتر بدل عطا فرمادیا۔"}],[2071,"عبداللہ بن نمیر نے کہا : ہمیں سعد بن سعید نے حدیث سنائی ، انھوں نے کہا : مجھے عمر بن کثیر نے سیدہ ام سلمہ رضی اللہ تعالیٰ عنہا کے آزاد کردہ غلام ابن سفینہ سے خبر دی اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ سیدہ ام سلمہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ۔ ۔ ۔ ( آگے ) ابو اسامہ کی حدیث کے مانند ( حدیث بیان کی ) اور یہ اضافہ کیا : سیدہ ام سلمہ رضی اللہ تعالیٰ عنہا نےکہا : جب ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوگئے تو میں نے ( دل میں ) کہا : رسول اللہ صلی اللہ علیہ وسلم کے صحابی ابو سلمہ رضی اللہ تعالیٰ عنہ سے بہتر کون ہوسکتاہے؟پھر اللہ تعالیٰ نے میرے ارادے کو پختہ کردیا تو میں نے وہی ( کلمات ) کہے ۔ اس کے بعد میری رسول اللہ صلی اللہ علیہ وسلم سے شادی ہوگئی ۔","",{"u2":"عبداللہ بن نمیر نے کہا:ہمیں سعد بن سعید نے حدیث سنائی،انھوں نے کہا:مجھے عمر بن کثیر نے حضرت ام سلمہ رضی اللہ تعالیٰ عنہا کے آزاد کردہ غلام ابن سفینہ سے خبر دی اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ حضرت ام سلمہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا۔۔۔(آگے) ابو اسامہ کی حدیث کے مانند(حدیث بیان کی)اور یہ اضافہ کیا:حضرت ام سلمہ رضی اللہ تعالیٰ عنہا نےکہا:جب ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوگئے تو میں نے(دل میں) کہا:رسول اللہ صلی اللہ علیہ وسلم کے صحابی ابو سلمہ رضی اللہ تعالیٰ عنہ سے بہتر کون ہوسکتاہے؟پھر اللہ تعالیٰ نے میرے ارادے کو پختہ کردیا تو میں نےوہی(کلمات) کہے۔اس کے بعد میری رسول اللہ صلی اللہ علیہ وسلم سے شادی ہوگئی۔"}],[2072,"سیدہ ام سلمہ رضی اللہ تعالیٰ عنہا سے روایت ہے ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم مریض یا مرنے والے کے پاس جاؤ تو بھلائی کی بات کہو کیونکہ جو تم کہتے ہو فرشتے اس پر آمین کہتے ہیں ۔ \" کہا : جب ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوگئے تو میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم !ابو سلمہ وفات پاگئے ہیں ۔ آپ نے فرمایا : \" تم ( یہ کلمات ) کہو : اے اللہ! مجھے اور اس کو معاف فرما اور اس کے بعد مجھے اس کا بہترین بدل عطا فرما ۔ \" کہا : میں نے ( یہ کلمات ) کہے تو اللہ تعالیٰ نے مجھے ان کےبعد وہ دے دیے جو میرے لئے ان سے بہتر ہیں ، یعنی محمد صلی اللہ علیہ وسلم ۔","",{"u2":"حضرت ام سلمہ رضی اللہ تعالیٰ عنہا سے روایت ہے،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جب تم مریض یا مرنے والے کے پاس جاؤ تو بھلائی کی بات کہو کیونکہ جو تم کہتے ہو فرشتے اس پر آمین کہتے ہیں۔\"کہا:جب ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوگئے تو میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور عرض کی:اے اللہ کے رسول صلی اللہ علیہ وسلم!ابو سلمہ وفات پاگئے ہیں۔آپ نے فرمایا:\"تم(یہ کلمات) کہو:اےاللہ! مجھے اور اس کو معاف فرما اور اس کے بعد مجھے اس کا بہترین بدل عطا فرما۔\"کہا:میں نے(یہ کلمات) کہے تو اللہ تعالیٰ نے مجھے ان کےبعد وہ دے دیے جو میرے لئے ان سے بہتر ہیں،یعنی محمد صلی اللہ علیہ وسلم۔"}],[2073,"ابو اسحاق فزاری نے خالد حذا سے ، انھوں نے ابو قلابہ سے ، انھوں نے قبیصہ بن ذویب سے اور انھوں نے سیدہ ام سلمہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ابو سلمہ رضی اللہ تعالیٰ عنہ کے پاس تشریف لائے ، اس وقت ان کی آنکھیں کھلی ہوئیں تھیں تو آپ نے انھیں بند کردیا ، پھر فرمایا : \" جب روح قبض کی جاتی ہے تو نظر اس کا پیچھاکرتی ہے ۔ \" اس پر انکے گھر کے کچھ لوگ چلا کر ر ونے لگے تو آ پ صلی اللہ علیہ وسلم نے فرمایا؛ \" تم اپنے لئے بھلائی کے علاوہ اور کوئی دعا نہ کرو کیونکہ تم جو کہتے ہو فرشتے اس پر آمین کہتے ہیں ۔ \" پھر آپ صلی اللہ علیہ وسلم نے فرمایا : \" اے اللہ!ابو سلمہ رضی اللہ تعالیٰ عنہ کی مغفرت فرما ، ہدایت یافتہ لوگوں میں اس کے درجات بلند فرما اور اس کے پیچھے رہ جانے والوں میں تو اس کا جانشین بن اور اے جہانوں کے پالنے والے!ہمیں اور اس کو بخش دے ، اس کے لئے اس کی قبر میں کشادگی عطا فرما اور اس کے لئے اس ( قبر ) میں روشنی کردے ۔","",{"u2":"ابو اسحاق فزاری نے خالد حذا سے،انھوں نے ابو قلابہ سے،انھوں نے قبیصہ بن ذویب سے اور انھوں نے حضرت ام سلمہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم ابو سلمہ رضی اللہ تعالیٰ عنہ کے پاس تشریف لائے،اس وقت ان کی آنکھیں کھلی ہوئیں تھیں تو آپ نے انھیں بند کردیا،پھر فرمایا:\"جب روح قبض کی جاتی ہے تو نظر اس کا پیچھاکرتی ہے۔\"اس پر انکے گھر کے کچھ لوگ چلا کر ر ونے لگے تو آ پ صلی اللہ علیہ وسلم نے فرمایا؛\"تم اپنے لئے بھلائی کے علاوہ اور کوئی دعا نہ کرو کیونکہ تم جو کہتے ہو فرشتے اس پر آمین کہتے ہیں۔\"پھر آپ صلی اللہ علیہ وسلم نے فرمایا:\"اے اللہ!ابو سلمہ رضی اللہ تعالیٰ عنہ کی مغفرت فرما،ہدایت یافتہ لوگوں میں اس کے درجات بلند فرما اور اس کے پیچھے رہ جانے والوں میں تو اس کا جانشین بن اور اے جہانوں کے پالنے والے!ہمیں اور اس کو بخش دے،اس کے لئے اس کی قبر میں کشادگی عطا فرما اور اس کے لئے اس(قبر) میں روشنی کردے۔\""}],[2074,"عبیداللہ بن حسن نے کہا : ہمیں خالد حذاء نے اسی ( مذکورہ بالا ) سند کے ساتھ اس ( سابقہ حدیث ) کے ہم معنی حدیث بیان کی ، اس کے سوا کہ انھوں نے ( واخلفه في عقبه کے بجائے ) واخلفه في تركته ( جو کچھ اس نے چھوڑا ہے ، یعنی اہل ومال ، اس میں اس کا جانشین بن ) کہا ، اور انھوں نے اللهم!اوسع له في قبره ( اے اللہ!اس کے لئے اس کی قبر میں وسعت پیدا فرما ) کہا اورافسح له ( اوراس کے لئے کشادگی پیدا فرما ) نہیں کہا اور ( عبیداللہ نے ) یہ زائد بیان کیا کہ خالد حذاء نے کہا : ایک اور ساتویں دعا کی جسے میں بھول گیا ۔","",{"u2":"عبیداللہ بن حسن نے کہا:ہمیں خالد حذاء نے اسی (مذکورہ بالا)سند کے ساتھ اس(سابقہ حدیث) کے ہم معنی حدیث بیان کی،اس کے سوا کہ انھوں نے(واخلفہ فی عقبہ کے بجائے) واخلفہ فی ترکتہ(جو کچھ اس نے چھوڑا ہے،یعنی اہل ومال،اس میں اس کا جانشین بن)کہا،اور انھوں نےاللہم!اوسع لہ فی قبرہ(اے اللہ!اس کے لئے اس کی قبر میں وسعت پیدا فرما)کہا اورافسح لہ(اوراس کے لئے کشادگی پیدا فرما)نہیں کہا اور(عبیداللہ نے) یہ زائد بیان کیا کہ خالد حذاء نے کہا:ایک اور ساتویں دعا کی جسے میں بھول گیا۔"}],[2075,"ابن جریج نے علاء بن یعقوب سے روایت کی ، انھوں نے کہا : مجھے میرے والد نے خبر دی کہ انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ کو کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیاتم انسان کو دیکھتے نہیں کہ جب وہ فوت ہوجاتاہے تو اس کی نظر اٹھ جاتی ہے؟ \" لوگوں نے کہا : کیوں نہیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" یہ اس وقت ہوتا ہے جب اس کی نظر اس کی روح کا پیچھا کرتی ہے ۔","",{"u2":"ابن جریج نے علاء بن یعقوب سے روایت کی،انھوں نے کہا:مجھے میرے والد نے خبر دی کہ انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ کو کہتے ہوئے سنا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"کیاتم انسان کو دیکھتے نہیں کہ جب وہ فوت ہوجاتاہے تو اس کی نظر اٹھ جاتی ہے؟\"لوگوں نے کہا:کیوں نہیں۔آپ صلی اللہ علیہ وسلم نے فرمایا:\"یہ اس وقت ہوتا ہے جب اس کی نظر اس کی روح کا پیچھا کرتی ہے۔\""}],[2076,"عبدالعزیز دراوردی نے ( بھی ) علاء سے اسی سند کے ساتھ ( سابقہ حدیث کے مانند ) روایت بیان کی ۔","",{"u2":"عبدالعزیز دراوردی نے (بھی) علاء سے اسی سند کے ساتھ(سابقہ حدیث کے مانند) روایت بیان کی۔"}],[2077,"سیدہ ام سلمہ رضی اللہ تعالیٰ عنہا نے فرمایا : جب ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوئے ، میں نے ( دل میں ) کہا : پردیسی ، پردیس میں ( فوت ہوگیا ) میں اس پر ایسا روؤں گی کہ اس کا خوب چرچا ہوگا ، چنانچہ میں نے اس پر رونے کی تیاری کرلی کہ اچانک بالائی علاقے سے ایک عورت آئی ، وہ ( رونے میں ) میرا ساتھ دینا چاہتی تھی کہ اسے سامنے سے رسول اللہ صلی اللہ علیہ وسلم مل گئے تو آپ صلی اللہ علیہ وسلم نے فرمایا؛ \" کیا تم شیطان کو اس گھر میں ( دوبارہ ) داخل کرنا چاہتی ہو ۔ جہاں سے اللہ نے اس کو نکال دیا ہے؟ \" دوبار ( آپ صلی اللہ علیہ وسلم نے یہ کلمات کہے ) تو میں ر ونے سے رک گئی اور نہ روئی ۔","",{"u2":"حضرت ام سلمہ رضی اللہ تعالیٰ عنہا نے فرمایا:جب ابو سلمہ رضی اللہ تعالیٰ عنہ فوت ہوئے،میں نے (دل میں) کہا:پردیسی،پردیس میں (فوت ہوگیا) میں اس پر ایسا روؤں گی کہ اس کا خوب چرچا ہوگا،چنانچہ میں نے اس پر رونے کی تیاری کرلی کہ اچانک بالائی علاقے سے ایک عورت آئی،وہ(رونے میں) میرا ساتھ دینا چاہتی تھی کہ اسے سامنے سے رسول اللہ صلی اللہ علیہ وسلم مل گئےتو آپ صلی اللہ علیہ وسلم نے فرمایا؛\"کیا تم شیطان کو اس گھر میں (دوبارہ)داخل کرنا چاہتی ہو۔جہاں سے اللہ نے اس کو نکال دیا ہے؟\" دوبار(آپ صلی اللہ علیہ وسلم نے یہ کلمات کہے)تو میں ر ونے سے رک گئی اور نہ روئی۔"}],[2078,"حماد بن زید نے عاصم احول سے ، انھوں نے ابو عثمان نہدی سے اور انہوں نے اسامہ بن زید رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ہم نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر تھے کہ آپ کی بیٹیوں میں سے ایک نے آپ کو بلاتے ہوئے اور اطلاع دیتے ہوئے آپ کی طرف پیغام بھیجا کہ اس کا بچہ ۔ ۔ ۔ یااس کا بیٹا ۔ ۔ ۔ موت ( کے عالم ) میں ہے ۔ اس پر آپ صلی اللہ علیہ وسلم نے پیام لانے والے سے فرمایا : \" ان کے پاس واپس جا کر ان کو بتاؤ کہ اللہ ہی کا ہے جو اس نے لے لیا اور اسی کا ہے ۔ جو اس نے دیا تھا اور اس کے ہاں ہر چیز کا وقت مقرر ہے ، اور ان کو بتادو کہ وہ صبر کریں اور اجر وثواب کی طلب گار ہوں ۔ \" پیام رساں دوبارہ آیا اور کہا : انھوں نے ( آپ کو ) قسم دی ہے کہ آپ ان کے پاس ضرور تشریف لائیں ۔ کہا : اس پر نبی اکرم صلی اللہ علیہ وسلم اٹھے اور آپ کے ساتھ سیدنا سعد بن عبادہ رضی اللہ تعالیٰ عنہ اور معاذ بن جبل رضی اللہ تعالیٰ عنہ بھی اٹھ کھڑے ہوئے اور میں بھی ان کے ساتھ چل پڑا ، آپ کے سامنے بچے کو پیش کیا گیا جبکہ اس کا سانس اکھڑا ہواتھا ، ( جسم اس طرح مضطرب تھا ) جیسے اس کی جان پرانے مشکیزے میں ہوتو آپ کی آنکھیں بہہ پڑیں ، اس پر سیدنا سعد رضی اللہ تعالیٰ عنہ نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم !یہ کیا ہے؟آپ نے فرمایا؛ \" یہ رحمت ہے جو اللہ نے اپنے بندوں کے دلوں میں رکھی ہے اور اللہ اپنے بندوں میں سے رحم دل بندوں ہی پر رحم فرماتا ہے ۔","",{"u2":"حماد بن زید نے عاصم احول سے،انھوں نے ابو عثمان نہدی سے اور انہوں نے اسامہ بن زید رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:ہم نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر تھے کہ آپ کی بیٹیوں میں سے ایک نے آپ کو بلاتے ہوئے اور اطلاع دیتے ہوئے آپ کی طرف پیغام بھیجا کہ اس کابچہ۔۔۔یااس کا بیٹا۔۔۔موت(کے عالم) میں ہے۔اس پر آپ صلی اللہ علیہ وسلم نے پیام لانے والےسے فرمایا:\"ان کے پاس واپس جا کر ان کو بتاؤ کہ اللہ ہی کا ہے جو اس نے لے لیا اوراسی کا ہے۔جو اس نے دیا تھا اور اس کے ہاں ہر چیز کا وقت مقرر ہے،اور ان کو بتادو کہ وہ صبر کریں اور اجر وثواب کی طلب گار ہوں۔\"پیام رساں دوبارہ آیا اور کہا:انھوں نے (آپ کو) قسم دی ہے کہ آپ ان کے پاس ضرور تشریف لائیں۔کہا:اس پر نبی اکرم صلی اللہ علیہ وسلم اٹھے اور آپ کے ساتھ حضرت سعد بن عبادہ رضی اللہ تعالیٰ عنہ اور معاذ بن جبل رضی اللہ تعالیٰ عنہ بھی اٹھ کھڑے ہوئے اور میں بھی ان کے ساتھ چل پڑا،آپ کے سامنے بچے کو پیش کیا گیا جبکہ اس کا سانس اکھڑا ہواتھا،(جسم اس طرح مضطرب تھا)جیسے اس کی جان پرانے مشکیزے میں ہوتو آپ کی آنکھیں بہہ پڑیں،اس پر حضرت سعد رضی اللہ تعالیٰ عنہ نے عرض کی:اےاللہ کے رسول صلی اللہ علیہ وسلم!یہ کیا ہے؟آپ نے فرمایا؛\"یہ رحمت ہے جو اللہ نے اپنے بندوں کے دلوں میں رکھی ہے اور اللہ اپنے بندوں میں سے رحم دل بندوں ہی پر رحم فرماتا ہے۔\""}],[2079,"ابن فضیل اور ابو معاویہ ہر ایک نے عاصم احول سے اسی سند کے ساتھ ( سابقہ حدیث کی مانند ) حدیث بیان کی ، البتہ حماد کی حدیث زیادہ مکمل اور زیادہ لمبی ہے ۔","",{"u2":"ابن فضیل اور ابو معاویہ ہر ایک نے عاصم احول سے اسی سند کے ساتھ(سابقہ حدیث کی مانند) حدیث بیان کی،البتہ حماد کی حدیث زیادہ مکمل اور زیادہ لمبی ہے۔"}],[2080,"سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : سیدنا سعد بن عبادہ رضی اللہ تعالیٰ عنہ اپنی بیماری میں مبتلا ہوئے تو رسول اللہ صلی اللہ علیہ وسلم عبدالرحمان بن عوف رضی اللہ تعالیٰ عنہ ، سعد بن ابی وقاص رضی اللہ تعالیٰ عنہ ، اور عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کےساتھ ان کی عیادت کے لئے ان کے پاس تشریف لے گئے ۔ جب آپ ان کے ہاں داخل ہوئے تو انھیں غشی کی حالت میں پایا ، آپ نے پوچھا : \" کیا انھوں نے اپنی مدت پوری کرلی ( وفات پاگئے ہیں ) ؟ \" لوگوں نے کہا : اے اللہ کے رسول صلی اللہ علیہ وسلم !نہیں ۔ رسول اللہ صلی اللہ علیہ وسلم روپڑے ، جب لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو روتے ہوئے دیکھا تو انہوں نے بھی روناشروع کردیا ۔ اس پر آپ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تم سنو گے نہیں کہ اللہ تعالیٰ آنکھ کے آنسو اور دل کے غم پر سزا نہیں دیتا بلکہ اس ۔ ۔ ۔ آپ نے اپنی زبان مبارک کی طرف اشارہ کیا ۔ ۔ ۔ کی وجہ سے عذاب دیتا ہے یا رحم کرتا ہے ۔","",{"u2":"حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے کہا:حضرت سعد بن عبادہ رضی اللہ تعالیٰ عنہ اپنی بیماری میں مبتلا ہوئے تو رسول اللہ صلی اللہ علیہ وسلم عبدالرحمان بن عوف رضی اللہ تعالیٰ عنہ،سعد بن ابی وقاص رضی اللہ تعالیٰ عنہ،اور عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ کےساتھ ان کی عیادت کے لئے ان کے پاس تشریف لے گئے۔جب آپ ان کے ہاں داخل ہوئے تو انھیں غشی کی حالت میں پایا،آپ نے پوچھا:\"کیا انھوں نے اپنی مدت پوری کرلی(وفات پاگئے ہیں)؟\"لوگوں نے کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!نہیں۔رسول اللہ صلی اللہ علیہ وسلم روپڑے،جب لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو روتے ہوئے دیکھاتو انہوں نے بھی روناشروع کردیا۔اس پر آپ صلی اللہ علیہ وسلم نے فرمایا:\"کیا تم سنو گے نہیں کہ اللہ تعالیٰ آنکھ کے آنسو اور دل کے غم پر سزا نہیں دیتا بلکہ اس۔۔۔آپ نے اپنی زبان مبارک کی طرف اشارہ کیا۔۔۔کی وجہ سے عذاب دیتا ہے یا رحم کرتا ہے۔\""}],[2081,"سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے کہ انھوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے کہ انصار میں سے ایک آدمی آیا ، اس نے آپ کو سلام کہا اور پھر وہ انصاری پشت پھیر کر چل دیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اے انصار کے بھائی ( انصاری ) !میرے بھائی سعد بن عبادہ رضی اللہ تعالیٰ عنہ کا کیا حال ہے ؟ \" اس نے عرض کی : وہ اچھا ہے ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کون اسکی عیادت کرے گا؟ \" پھر آپ اٹھے اور آپ کےساتھ ہم بھی اٹھ کھڑے ہوئے ، ہم دس سے زائد لوگ تھے ، ہمارے پاس جوتے نہ تھے نہ موزے ، نہ ٹوپیاں اور نہ قمیص ہی ۔ ہم اس شوریلی زمین پر چلتے ہوئے ان کے پاس پہنچ گئے ، ان کی قوم کے لوگ ان کے ارد گرد سے پیچھے ہٹ گئے حتیٰ کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ کرام رضوان اللہ عنھم اجمعین جو آپ کےساتھ تھے ، ( ان کے ) قریب ہوگئے ۔","",{"u2":"حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت ہے کہ انھوں نے کہا:ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے کہ انصار میں سے ایک آدمی آیا،اس نے آپ کو سلام کہا اور پھر وہ انصاری پشت پھیر کر چل دیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اے انصار کے بھائی(انصاری)!میرے بھائی سعد بن عبادہ رضی اللہ تعالیٰ عنہ کا کیا حال ہے؟\"اس نے عرض کی: وہ اچھا ہے۔اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تم میں سے کون اسکی عیادت کرے گا؟\"پھر آپ اٹھے اور آپ کےساتھ ہم بھی اٹھ کھڑے ہوئے،ہم دس سے زائد لوگ تھے،ہمارے پاس جوتے نہ تھے نہ موزے،نہ ٹوپیاں اور نہ قمیص ہی۔ہم اس شوریلی زمین پر چلتے ہوئے ان کے پاس پہنچ گئے،ان کی قوم کے لوگ ان کے ارد گرد سے پیچھے ہٹ گئے حتیٰ کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ کرام رضوان اللہ عنھم اجمعین جو آپ کےساتھ تھے،(ان کے) قریب ہوگئے۔"}],[2082,"محمد یعنی جعفر ( الصادق ) کے فرزند نے حدیث بیان کی ، کہا : ہمیں شعبہ نے ثابت سے حدیث سنائی ، انھوں نے کہا : میں نے سیدنا انس رضی اللہ تعالیٰ عنہ کو یہ فرماتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" صبر پہلے صدمے کے وقت ہے ( اس کے بعد تو انسان غم کو آہستہ آہستہ برداشت کرنے لگتاہے ۔)","",{"u2":"محمد یعنی جعفر(الصادق) کے فرزند نے حدیث بیان کی،کہا:ہمیں شعبہ نے ثابت سے حدیث سنائی،انھوں نے کہا:میں نے حضرت انس رضی اللہ تعالیٰ عنہ کو یہ فرماتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"صبر پہلے صدمے کے وقت ہے(اس کے بعد تو انسان غم کو آہستہ آہستہ برداشت کرنے لگتاہے۔)\""}],[2083,"عثمان بن عمر نے کہا : ہمیں شعبہ نے ثابت بنانی کے حوالےسے سیدنا انس رضی اللہ تعالیٰ عنہ سے روایت بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک عورت کے پاس آئے جو اپنے بچے ( کی موت ) پر رورہی تھی تو آپ نے ان سے فرمایا : \" اللہ کاتقویٰ اختیار کرواورصبر کرو \" اس نے کہا : آپ کو میری مصیبت کی کیاپروا؟جب آپ چلے گئے تو اس کو بتایا گیا کہ وہ ( تمھیں صبر کی تلقین کرنے والے ) اللہ کے رسول صلی اللہ علیہ وسلم تھے ۔ تو اس عورت پر موت جیسی کیفیت طاری ہوگئی ، وہ آپ کے دروازے پر آئی تو اس نے آپ صلی اللہ علیہ وسلم کے دروازے پر دربان نہ پائے ۔ اس نےکہا : اے اللہ کے رسول صلی اللہ علیہ وسلم !میں نے ( اس وقت ) آپ کو نہیں پہچانا تھا تو آپ صلی اللہ علیہ وسلم نے فرمایا؛ \" ( حقیقی ) صبر پہلے صدمے یا صدمے کے آغاز ہی میں ہوتا ہے ۔","",{"u2":"عثمان بن عمر نے کہا:ہمیں شعبہ نے ثابت بنانی کے حوالےسے حضرت انس رضی اللہ تعالیٰ عنہ سے روایت بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک عورت کے پاس آئے جو اپنے بچے(کی موت) پر رورہی تھی تو آپ نے ان سے فرمایا:\"اللہ کاتقویٰ اختیار کرواورصبر کرو\"اس نے کہا:آپ کو میری مصیبت کی کیاپروا؟جب آپ چلے گئے تو اس کو بتایا گیا کہ وہ(تمھیں صبر کی تلقین کرنے والے) اللہ کے رسول صلی اللہ علیہ وسلم تھے۔تو اس عورت پر موت جیسی کیفیت طاری ہوگئی،وہ آپ کے دروازے پر آئی تو اس نے آپ صلی اللہ علیہ وسلم کے دروازے پر دربان نہ پائے۔اس نےکہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!میں نے(اس وقت)آپ کو نہیں پہچانا تھا تو آپ صلی اللہ علیہ وسلم نے فرمایا؛\"(حقیقی) صبر پہلے صدمے یا صدمے کے آغاز ہی میں ہوتا ہے۔"}],[2084,"خالد بن حارث ، عبدالملک بن عمرو ، اور عبدالصمد سب نے کہا : ہمیں شعبہ نے اسی سند کے ساتھ عثمان بن عمر کے سنائے گئے واقعے کے مطابق اس کی حدیث کی طرح حدیث سنائی ۔ اورعبدالصمد کی حدیث میں ( یہ جملہ ) ہے : نبی اکرم صلی اللہ علیہ وسلم قبرکے پاس ( بیٹھی ہوئی ) ایک عورت کے پاس سے گزرے ۔","",{"u2":"خالد بن حارث،عبدالملک بن عمرو،اور عبدالصمد سب نے کہا:ہمیں شعبہ نے اسی سند کے ساتھ عثمان بن عمر کے سنائے گئے واقعے کے مطابق اس کی حدیث کی طرح حدیث سنائی۔اورعبدالصمد کی حدیث میں(یہ جملہ)ہے:نبی اکرم صلی اللہ علیہ وسلم قبرکے پاس (بیٹھی ہوئی) ایک عورت کے پاس سے گزرے۔"}],[2085,"نافع نے سیدنا عبد اللہ ( بن عمر ) رضی اللہ تعالیٰ عنہ سے روایت کی ، کہ سیدہ حفصہ رضی اللہ تعالیٰ عنہا سیدنا نا عمر رضی اللہ تعالیٰ عنہ ( کی حالت ) پر رونے لگیں تو انھوں نے کہا : اے میری بیٹی !رک جا ؤ کیا تمھیں معلوم نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا تھا : \" میت کو اس پر اس کے گھروالوں کی آہ و بکا سے عذاب دیا جا تا ہے","",{"u2":"نافع نے حضرت عبد اللہ (بن عمر) رضی اللہ تعالیٰ عنہ سے روایت کی،کہ حضرت حفصہ رضی اللہ تعالیٰ عنہا سید نا عمر رضی اللہ تعالیٰ عنہ (کی حالت) پر رونے لگیں تو انھوں نے کہا: اے میری بیٹی!رک جا ؤ کیا تمھیں معلوم نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا تھا:\"میت کو اس پر اس کے گھروالوں کی آہ و بکا سے عذاب دیا جا تا ہے-"}],[2086,"شعبہ نے کہا : میں نے قتادہ کو سعید بن مسیب سے حدیث بیان کرتے ہو ئے سنا ، انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ کے واسطے سے سیدنا عمر رضی اللہ تعالیٰ عنہ سے انھوں نے نبی صلی اللہ علیہ وسلم سے روا یت کی ، آپ نے فر ما یا : \" میت کو اس کی قبر میں اس پر کیے جا نے والے نو حے سے عذاب دیا جا تاہے ۔","",{"u2":"شعبہ نے کہا: میں نے قتادہ کو سعید بن مسیب سے حدیث بیان کرتے ہو ئے سنا، انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ کے واسطے سے حضرت عمر رضی اللہ تعالیٰ عنہ سے انھوں نے نبی صلی اللہ علیہ وسلم سے روا یت کی،آپ نے فر ما یا:\"میت کو اس کی قبر میں اس پر کیے جا نے والے نو حے سے عذاب دیا جا تاہے۔"}],[2087,"سعید ( بن ابی عروبہ ) نے قتادہ سے انھوں نے سعید بن مسیب سے انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے انھوں نے سیدنا عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فر ما یا : \" میت کو اس کی قبر میں اس پر کیے جا نے والے نو حے سے عذاب دیا جا تا ہے ۔","",{"u2":"سعید (بن ابی عروبہ)نے قتادہ سے انھوں نے سعید بن مسیب سے انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے انھوں نے حضرت عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی،آپ نے فر ما یا:\"میت کو اس کی قبر میں اس پر کیے جا نے والے نو حے سے عذاب دیا جا تا ہے۔\""}],[2088,"ابو صالح نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے روا یت کی ، انھوں نے کہا : جب سیدنا عمر رضی اللہ تعالیٰ عنہ کو زخمی کیا گیاوہ بے ہو ش ہو گئے تب ان پر بلند آواز سے چیخ و پکار کی گئی جب ان کو افاقہ ہوا تو انھوں نے کہا : کیا تم لوگ جانتے نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فر مایا : \" میت کو زندہ کے رونے سے عذاب دیا جا تا ہے ؟","",{"u2":"ابو صالح نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روا یت کی،انھوں نے کہا: جب حضرت عمر رضی اللہ تعالیٰ عنہ کو زخمی کیا گیاوہ بے ہو ش ہو گئے تب ان پر بلند آواز سے چیخ و پکار کی گئی جب ان کو افاقہ ہوا تو انھوں نے کہا: کیا تم لوگ جانتے نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فر مایا:\"میت کو زندہ کے رونے سے عذاب دیا جا تا ہے؟\""}],[2089,"۔ ( ابو اسحاق ) شیبانی نے ابو بردہ سے اور انھوں نے اپنے والد ( سیدنا ابو موسیٰ اشعری رضی اللہ تعالیٰ عنہ ) سے روایت کی ، انھوں نے کہا : جب سیدنا عمر رضی اللہ تعالیٰ عنہ کو زخمی کیا گیا تو سیدنا صہیب رضی اللہ تعالیٰ عنہ نے یہ کہنا شروع کر دیا : ہائے میرا بھا ئی ! تو سیدنا عمر رضی اللہ تعالیٰ عنہ نے ان سے کہا : صہیب !کیا تمھیں معلوم نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" زندہ کے رونے سے میت کو عذاب دیا جا تا ہے :","",{"u2":"۔(ابو اسحاق)شیبانی نے ابو بردہ سے اور انھوں نے اپنے والد (حضرت ابو موسیٰ اشعری رضی اللہ تعالیٰ عنہ)سے روایت کی، انھوں نے کہا: جب حضڑت عمر رضی اللہ تعالیٰ عنہ کو زخمی کیا گیا تو حضرت صہیب رضی اللہ تعالیٰ عنہ نے یہ کہنا شروع کر دیا:ہائے میرا بھا ئی! تو حضرت عمر رضی اللہ تعالیٰ عنہ نے ان سے کہا: صہیب!کیا تمھیں معلوم نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"زندہ کے رونے سے میت کو عذاب دیا جا تا ہے:\""}],[2090,"عبد الملک بن عمیر نے ابو بردہ بن ابی موسیٰ سے اور انھوں نے ( اپنے والد ) سیدنا ابو موسیٰ رضی اللہ تعالیٰ عنہ سے روا یت کی ، انھوں نے کہا : جب سیدنا عمر رضی اللہ تعالیٰ عنہ زخمی ہو ئے تو صہیب رضی اللہ تعالیٰ عنہ اپنے گھر سے آئے یہاں تک کہ سیدنا عمر رضی اللہ تعالیٰ عنہ کے پا س اندر داخل ہو ئے اور ان کے سامنے کھڑے ہو کر رونے لگے تو سیدنا عمر رضی اللہ تعالیٰ عنہ نے ان سے کہا : کیوں رو رہے ہو؟ کیا مجھ پر رو رہے ہو ؟ کہا : اللہ کی قسم !ہاں ، امیر المومنین!آپ ہی پر رو رہا ہوں ۔ تو انھوں نے کہا : اللہ کی قسم !تمھیں خوب علم ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا تھا جس پر آہ و بکا کی جا ئے اسے عذاب دیا جا تا ہے ۔ ( عبد الملک بن عمیر نے ) کہا : میں نے یہ حدیث موسیٰ بن طلحہ کے سامنے بیان کی تو انھوں نے کہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا کہا کرتی تھیں ( یہ ) یہودیوں کا معاملہ تھا ۔ ( دیکھیے حدیث نمبر2153 ) ۔","",{"u2":"عبد الملک بن عمیر نے ابو بردہ بن ابی موسیٰ سے اور انھوں نے (اپنے والد) حضرت ابو موسیٰ رضی اللہ تعالیٰ عنہ سے روا یت کی، انھوں نے کہا: جب حضرت عمر رضی اللہ تعالیٰ عنہ زخمی ہو ئے تو صہیب رضی اللہ تعالیٰ عنہ اپنے گھر سے آئے یہاں تک کہ حضرت عمر رضی اللہ تعالیٰ عنہ کے پا س اندر داخل ہو ئے اور ان کے سامنے کھڑے ہو کر رونے لگے تو حضرت عمر رضی اللہ تعالیٰ عنہ نے ان سے کہا: کیوں رو رہے ہو؟ کیا مجھ پر رو رہے ہو؟ کہا: اللہ کی قسم!ہاں،امیر المومنین!آپ ہی پر رو رہا ہوں۔تو انھوں نے کہا: اللہ کی قسم!تمھیں خوب علم ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا تھا جس پر آہ و بکا کی جا ئے اسے عذاب دیا جا تا ہے۔\n(عبد الملک بن عمیر نے) کہا: میں نے یہ حدیث موسیٰ بن طلحہ کے سامنے بیان کی تو انھوں نے کہا:حضرت عائشہ رضی اللہ تعالیٰ عنہا کہا کرتی تھیں (یہ) یہودیوں کا معاملہ تھا۔(دیکھیے حدیث نمبر2153)۔"}],[2091,"سیدنا انس رضی اللہ تعالیٰ عنہ سے روایت ہے کہ جب سیدنا عمر رضی اللہ تعالیٰ عنہ کو زخمی کر دیا گیا تو سیدہ حفصہ رضی اللہ تعالیٰ عنہا نے ان پر واویلا کیا انھوں نے کہا : اے حفصہ !کیا تم نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے نہیں سنا کہ جس پر واویلا کیاجا تا ہے اسے عذاب دیا جا تا ہے اور ( اسی طرح ) صہیب رضی اللہ تعالیٰ عنہ نے بھی واویلا کیا تو سیدنا عمر رضی اللہ تعالیٰ عنہ نے کہا : صہیب !کیا تمھیں علم نہیں : \" جس پر واویلا کیا جا ئے اس کو عذاب دیا جا تا ہے ؟","",{"u2":"حضرت انس رضی اللہ تعالیٰ عنہ سے روایت ہے کہ جب حضرت عمر رضی اللہ تعالیٰ عنہ کو زخمی کر دیا گیا تو حضرت حفصہ رضی اللہ تعالیٰ عنہا نے ان پر واویلا کیا انھوں نے کہا: اے حفصہ!کیا تم نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے نہیں سنا کہ جس پر واویلا کیاجا تا ہے اسے عذاب دیا جا تا ہے اور (اسی طرح)صہیب رضی اللہ تعالیٰ عنہ نے بھی واویلا کیا تو حضرت عمر رضی اللہ تعالیٰ عنہ نے کہا: صہیب!کیا تمھیں علم نہیں:\"جس پر واویلا کیا جا ئے اس کو عذاب دیا جا تا ہے؟\""}],[2092,"ایوب نے عبد اللہ بن ابی ملیکہ سے روا یت کی ، انھوں نے کہا : میں سیدنا ابن عمر رضی اللہ تعالیٰ عنہ کے پہلو میں بیٹھا ہوا تھا ۔ ہم سیدنا عثمان رضی اللہ تعالیٰ عنہ کی صاحبزادی ام ابان کے جنازے کا انتظار کر رہے تھے جبکہ عمرو بن عثمان بھی ان کے پا س تھے اتنے میں سیدنا ابن عباس رضی اللہ تعالیٰ عنہ آئے انھیں لے کر آنے والا ایک آدمی لا یا میرے خیال میں اس نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ کو سیدنا ابن عمر رضی اللہ تعالیٰ عنہ کی بیٹھنے کی جگہ کے بارے میں بتا یا تو وہ آکر میرے پہلو میں بیٹھ گئے میں ان دو نوں کے در میان میں تھا اچانک گھر ( کے اندر ) سے ( رونے کی ) آواز آئی تو ابن عمر رضی اللہ تعالیٰ عنہ نے ۔ ۔ ۔ اور ایسا لگتا تھا وہ عمرو ( بن عثمان ) کو اشارہ کر رہے ہیں کہ وہ انھیں اور ان کو روکیں ۔ ۔ ۔ کہا میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا ہے بلا شبہ میت کو اس کے گھر والوں کے رو نے سے عذاب دیا جا تا ہے : \" ( عبد اللہ بن ابی ملیکہ نے ) کہا : سیدنا عبد اللہ رضی اللہ تعالیٰ عنہ نے اس کو بلا شرط و قید ( یعنی ہر طرح کے رو نے کے حوالے سے ) بیان کیا ۔ اس پر سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے کہا : ہم امیر المو منین سیدنا عمربن خطا ب رضی اللہ تعالیٰ عنہ کے ساتھ تھے حتیٰ کہ جب ہم بیداء کے مقام پر پہنچے تو انھوں نے ایک آدمی کو درخت کے سائے میں پڑا ؤڈالے دیکھا انھوں نے مجھ سے کہا : جا ؤ اور میرے لیے پتہ کرو کہ وہ کو ن آدمی ہے میں گیا تو دیکھا وہ صہیب رضی اللہ تعالیٰ عنہ تھے میں ان کے پاس واپس آیا اور کہا : آپ نے مجھے حکم دیا تھا کہ میں آپ کے لیے پتہ کروں کہ وہ کو ن شخص ہیں تو وہ صہیب رضی اللہ تعالیٰ عنہ ہیں انھوں نے کہا : ( جاؤ اور ) ان کو حکم ( پہنچا ) دو کہ وہ ہمارے ساتھ ( قافلے میں ) آجا ئیں ۔ میں نے کہا : ان کے ساتھ ان کے گھر والے ہیں انھوں نے کہا : چاہے ان کے ساتھ ان کے گھر والے ( بھی ) ہیں شامل ہو جا ئیں ) بسا اوقات ایوب نے ( بس یہاں تک کہا ) ان سے کہو کہ وہ ہمارے ساتھ ( قافلے میں ) شامل ہو جائیں ۔ ۔ ۔ جب ہم مدینہ پہنچے تو زیادہ وقت نہ گزرا تھا کہ امیر المو منین زخمی کردیے گئے صہیب رضی اللہ تعالیٰ عنہ یہ کہتے ہو ئے آئے ہائے میرا بھائی !ہائے میرا ساتھی!تو عمر رضی اللہ تعالیٰ عنہ نے کہا کیا تمھیں معلوم نہیں یا ( کہا : تم نے سنا نہیں ۔ ۔ ۔ ایوب نے کہا : یا انھوں نے ( اس کے بجا ئے ( او لم تعلم ...اولم تسمع کیا تمھیں پتہ نہیں اور تم نے سنا نہیں \" کے الفاظ کہے ۔ ۔ ۔ کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" میت کو اس کے گھر والوں کے بعض ( طرح کے ) رونے سے عذاب دیا جاتا ہے ( ابن ابی ملیکہ نے ) کہا : سیدنا عبداللہ رضی اللہ تعالیٰ عنہ نے اس ( رونے کے لفظ ) کو بلا قید بیان کیا جبکہ سیدنا عمر رضی اللہ تعالیٰ عنہ نے ( لفظ ) بعض ( کی قید ) کے ساتھ کہاتھا ۔ میں ( ابن ابی ملکہ ) اٹھ کر سیدہ عائشہ رضی اللہ تعالیٰ عنہا کی خدمت میں حاضر ہوا اور سیدنا ابن عمر رضی اللہ تعالیٰ عنہ نے جو کہا تھا ان کو بتا یا انھوں نے کہا نہیں اللہ کی قسم !رسول اللہ صلی اللہ علیہ وسلم نے یہ کبھی نہیں فر ما یا کہ میت کو کسی ایک کے رونے کی وجہ سے عذاب دیا جا تا ہے بلکہ آپ نے فر ما یا ہے : \" اللہ تعا لیٰ کا فر کے عذاب میں اس کے گھر والوں کے رو نے کی وجہ سے اضافہ کر دیتا ہے ( کیونکہ کا فروں نے اپنی اولاد کو بلند آواز سے رونا سکھایا ہوتا ہے رہا بغیر آواز کے رونا تو اس کی ذمہ داری رونے والے پر نہیں کیونکہ ) بے شک اللہ ہی ہے جس نے ہنسایا اور رلایا ۔ \" اور بو جھ اٹھا نے والی کو ئی جان کسی دوسری کا بو جھ نہیں اٹھا ئے گی ۔ ( آواز کے بغیر محض آنسوؤں سے رونے کا نہ رونے والے کو گنا ہ ہے نہ اس کے بڑوں کو کیونکہ وہ بھی اس کے ذمہ دار نہیں ۔ ) ایوب نے کہا : ابن ابی ملیکہ نے کہاں مجھ سے قاسم بن محمد نے بیان کیا انھوں نے کہا : جب سیدہ عائشہ رضی اللہ تعالیٰ عنہا کو سیدنا عمر اور ابن عمر رضی اللہ تعالیٰ عنہ کی یہ بات پہنچی تو انھوں نے کہا : تم مجھے ایسے دو افراد کی حدیث بیان کرتے ہو جو نہ ( خود جھوٹ بولنے والے ہیں اور نہ جھٹلائے جا نے والے ہیں لیکن ( بعض اوقات ) سماع ( سننا ) غلط ہو جا تا ہے ( کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے ایک اور سیاق میں یہ با ت کی تھی دیکھیے حدیث نمبر2153 ۔ 2156 ) ۔ ۔","",{"u2":"ایوب نے عبد اللہ بن ابی ملیکہ سے روا یت کی، انھوں نے کہا: میں حضرت ابن عمر رضی اللہ تعالیٰ عنہ کے پہلو میں بیٹھا ہوا تھا۔ہم حضرت عثمان رضی اللہ تعالیٰ عنہ کی صاحبزادی ام ابان کے جنازے کا انتظار کر رہے تھے جبکہ عمرو بن عثمان بھی ان کے پا س تھے اتنے میں حضرت ابن عباس رضی اللہ تعالیٰ عنہ آئے انھیں لے کر آنے والا ایک آدمی لا یا میرے خیال میں اس نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ کو حضرت ابن عمر رضی اللہ تعالیٰ عنہ کی بیٹھنے کی جگہ کے بارے میں بتا یا تو وہ آکر میرے پہلو میں بیٹھ گئے میں ان دو نوں کے در میان میں تھا اچانک گھر (کے اندر) سے (رونے کی) آواز آئی تو ابن عمر رضی اللہ تعالیٰ عنہ نے۔۔۔اور ایسا لگتا تھا وہ عمرو (بن عثمان) کو اشارہ کر رہے ہیں کہ وہ انھیں اور ان کو روکیں۔۔۔کہا میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا ہے بلا شبہ میت کو اس کے گھر والوں کے رو نے سے عذاب دیا جا تا ہے:\"(عبد اللہ بن ابی ملیکہ نے) کہا: حضرت عبد اللہ رضی اللہ تعالیٰ عنہ نے اس کو بلا شرط و قید (یعنی ہر طرح کے رو نے کے حوالے سے) بیان کیا۔اس پر حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے کہا: ہم امیر المو منین حضرت عمربن خطا ب رضی اللہ تعالیٰ عنہ کے ساتھ تھے حتیٰ کہ جب ہم بیداء کے مقام پر پہنچے تو انھوں نے ایک آدمی کو درخت کے سائے میں پڑا ؤڈالے دیکھا انھوں نے مجھ سے کہا:جا ؤ اور میرے لیے پتہ کرو کہ وہ کو ن آدمی ہے میں گیا تو دیکھا وہ صہیب رضی اللہ تعالیٰ عنہ تھے میں ان کے پاس واپس آیا اور کہا:آپ نے مجھے حکم دیا تھا کہ میں آپ کے لیے پتہ کروں کہ وہ کو ن شخص ہیں تو وہ صہیب رضی اللہ تعالیٰ عنہ ہیں انھوں نے کہا: (جاؤ اور) ان کو حکم (پہنچا) دو کہ وہ ہمارے ساتھ (قافلے میں) آجا ئیں۔میں نے کہا: ان کے ساتھ ان کے گھر والے ہیں انھوں نے کہا: چاہے ان کے ساتھ ان کے گھر والے (بھی) ہیں شامل ہو جا ئیں) بسا اوقات ایوب نے (بس یہاں تک کہا) ان سے کہو کہ وہ ہمارے ساتھ (قافلے میں) شامل ہو جائیں۔۔۔جب ہم مدینہ پہنچے تو زیادہ وقت نہ گزرا تھا کہ امیر المو منین زخمی کردیے گئے صہیب رضی اللہ تعالیٰ عنہ یہ کہتے ہو ئے آئے ہائے میرا بھائی!ہائے میرا ساتھی!تو عمر رضی اللہ تعالیٰ عنہ نے کہا کیا تمھیں معلوم نہیں یا (کہا:تم نے سنا نہیں۔۔۔ایوب نے کہا: یا انھوں نے (اس کے بجا ئے (او لم تعلم ...اولم تسمع کیا تمھیں پتہ نہیں اور تم نے سنا نہیں \"کے الفاظ کہے۔۔۔کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"میت کو اس کے گھر والوں کے بعض (طرح کے) رونے سے عذاب دیا جاتا ہے (ابن ابی ملیکہ نے) کہا:حضرت عبداللہ رضی اللہ تعالیٰ عنہ نے اس (رونے کے لفظ) کو بلا قید بیان کیا جبکہ حضرت عمر رضی اللہ تعالیٰ عنہ نے (لفظ) بعض (کی قید)کے ساتھ کہاتھا۔میں (ابن ابی ملکہ) اٹھ کر حضرت عائشہ رضی اللہ تعالیٰ عنہا کی خدمت میں حاضر ہوا اور حضرت ابن عمر رضی اللہ تعالیٰ عنہ نے جو کہا تھا ان کو بتا یا انھوں نے کہا نہیں اللہ کی قسم!رسول اللہ صلی اللہ علیہ وسلم نے یہ کبھی نہیں فر ما یا کہ میت کو کسی ایک کے رونے کی وجہ سے عذاب دیا جا تا ہے بلکہ آپ نے فر ما یا ہے:\" اللہ تعا لیٰ کا فر کے عذاب میں اس کے گھر والوں کے رو نے کی وجہ سے اضافہ کر دیتا ہے (کیونکہ کا فروں نے اپنی اولاد کو بلند آواز سے رونا سکھایا ہوتا ہے رہا بغیر آواز کے رونا تو اس کی ذمہ داری رونے والے پر نہیں کیونکہ)بے شک اللہ ہی ہے جس نے ہنسایا اور رلایا۔\"اور بو جھ اٹھا نے والی کو ئی جان کسی دوسری کا بو جھ نہیں اٹھا ئے گی۔(آواز کے بغیر محض آنسوؤں سے رونے کا نہ رونے والے کو گنا ہ ہے نہ اس کے بڑوں کو کیونکہ وہ بھی اس کے ذمہ دار نہیں۔)ایوب نے کہا:ابن ابی ملیکہ نے کہاں مجھ سے قاسم بن محمد نے بیان کیا انھوں نے کہا: جب حضرت عائشہ رضی اللہ تعالیٰ عنہا کو حضرت عمر اور ابن عمر رضی اللہ تعالیٰ عنہ کی یہ بات پہنچی تو انھوں نے کہا:تم مجھے ایسے دو افراد کی حدیث بیان کرتے ہو جو نہ (خود جھوٹ بولنے والے ہیں اور نہ جھٹلائے جا نے والے ہیں لیکن (بعض اوقات)سماع (سننا) غلط ہو جا تا ہے (کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے ایک اور سیاق میں یہ با ت کی تھی دیکھیے حدیث نمبر2153۔2156)۔۔"}],[2093,"(ابن جریج نے کہا : مجھے عبد اللہ بن ابی ملیکہ نے خبر دی انھوں نے کہا : سیدنا عثمان بن عفان رضی اللہ تعالیٰ عنہ کی صاحبزادی مکہ میں فو ت ہو گئی توہم ان کے جنا زے میں شرکت کے لیے آئے سیدنا ابن عمر اور سیدنا ابن عبا س رضی اللہ تعالیٰ عنہ بھی تشریف لا ئے ۔ میں ان دو نوں کے درمیان میں بیٹھا تھا میں ان میں سے ایک کے پاس بیٹھا تھا پھر دوسرا آکر میرے پہلو میں بیٹھ گیا سیدنا عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ نے عمرو بن عثمان سے اور وہ ان کے رو برو بیٹھے ہو ئے تھے کہا : تم رو نے سے رو کتے کیوں نہیں ؟بے شک رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا تھا \" میت کو اس کے گھروالوں کے اس پر رونے سے عذاب دیا جا تا ہے ۔ اس پر ابن عباس رضی اللہ تعالیٰ عنہ نے کہا : سیدنا عمر رضی اللہ تعالیٰ عنہ اس کے بعض طرح کے رونے سے ) کہا کرتے تھے پھر انھوں نے ( مکمل ) حدیث بیان کی کہا : میں عمر رضی اللہ تعالیٰ عنہ کے ساتھ مکہ سے لو ٹا حتیٰ کہ جب ہم مقام بیداء پر پہنچے تو اچانک انھیں درخت کے سائے تلے کچھ اونٹ سوار دکھا ئی دیے انھوں نے کہا : جا کر دیکھو یہ اونٹ سوار کو ن ہیں ؟ میں نے دیکھا تو وہ صہیب رضی اللہ تعالیٰ عنہ تھے میں نے ( آکر ) انھیں بتا یا تو انھوں نے کہا : انھیں میرے پاس بلا ؤ ۔ میں لو ٹ کر صہیب رضی اللہ تعالیٰ عنہ کے پاس گیا ۔ میں نے کہا : چلیے امیر المومنین کے ساتھ ہو جائیے اس کے بعد جب سیدنا عمر رضی اللہ تعالیٰ عنہ زخمی کر دیے گئے تو صہیب رضی اللہ تعالیٰ عنہ روتے ہو ئے اندر آئے کہہ رہے تھے ہائے میرا بھا ئی ! ہا ئے میرا ساتھی !تو سیدنا عمر رضی اللہ تعالیٰ عنہ نے کہا صہیب ! کیا تم مجھ پر رو رہے ہو؟حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے فر مایا ہے : \" میت کو اس کے گھر والوں کے بعض ( طرح کے ) رونے سے عذاب دیا جا تا ہے ۔ سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے کہا : جب سیدنا عمر رضی اللہ تعالیٰ عنہ وفات پا گئے تو میں نے یہ بات سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے بیان کی انھوں نے کہا : اللہ عمر پر رحم فر ما ئے !اللہ کی قسم !نہیں رسول اللہ صلی اللہ علیہ وسلم نے یہ نہیں فر ما یا کہ اللہ تعا لیٰ مومن کو کسی کے رونے کی وجہ سے عذاب دیتا ہے بلکہ آپ نے فر ما یا : \" اللہ تعا لیٰ کا فرکے عذاب کو اس کے گھر والوں کے اس پر رونے کی وجہ سے بڑھا دیتا ہے ۔ \" کہا اور سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : اور تمھا رے لیے قرآن کا فی ہے ( جس میں یہ ہے ) اور بو جھ اٹھا نے والی کو ئی جا ن کسی دوسری جا ن کا بوجھ نہیں اٹھا ئے گی ۔ اسکے ساتھ سیدنا ابن عباس رضی اللہ تعالیٰ عنہ نے کہا اور اللہ ہی ہنساتا ہے اور رلا تا ہے ۔ ابن ابی ملیکہ نے نے کہا : اللہ کی قسم !سیدنا ابن عمر رضی اللہ تعالیٰ عنہ نے ( جواب میں ) کچھ نہیں کہا ۔","",{"u2":"ابن جریج نے کہا: مجھے عبد اللہ بن ابی ملیکہ نے خبر دی انھوں نے کہا: حضرت عثمان بن عفان رضی اللہ تعالیٰ عنہ کی صاحبزادی مکہ میں فو ت ہو گئی توہم ان کے جنا زے میں شرکت کے لیے آئے حضرت ابن عمر اور حضرت ابن عبا س رضی اللہ تعالیٰ عنہ بھی تشریف لا ئے۔میں ان دو نوں کے درمیان میں بیٹھا تھا میں ان میں سے ایک کے پاس بیٹھا تھا پھر دوسرا آکر میرے پہلو میں بیٹھ گیا حضرت عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ نے عمرو بن عثمان سے اور وہ ان کے رو برو بیٹھے ہو ئے تھے کہا: تم رو نے سے رو کتے کیوں نہیں؟بے شک رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا تھا \"میت کو اس کے گھروالوں کے اس پررونے سے عذاب دیا جا تا ہے۔اس پر ابن عباس رضی اللہ تعالیٰ عنہ نے کہا: حضرت عمر رضی اللہ تعالیٰ عنہ اس کے بعض طرح کے رونے سے) کہا کرتے تھے پھر انھوں نے (مکمل) حدیث بیان کی کہا: میں عمر رضی اللہ تعالیٰ عنہ کے ساتھ مکہ سے لو ٹا حتیٰ کہ جب ہم مقام بیداء پر پہنچے تو اچانک انھیں درخت کے سائے تلے کچھ اونٹ سوار دکھا ئی دیے انھوں نے کہا: جا کر دیکھو یہ اونٹ سوار کو ن ہیں؟ میں نے دیکھا تو وہ صہیب رضی اللہ تعالیٰ عنہ تھے میں نے (آکر) انھیں بتا یا تو انھوں نے کہا: انھیں میرے پاس بلا ؤ۔میں لو ٹ کر صہیب رضی اللہ تعالیٰ عنہ کے پاس گیا۔میں نے کہا: چلیے امیر المومنین کے ساتھ ہو جائیے اس کے بعد جب حضرت عمر رضی اللہ تعالیٰ عنہ زخمی کر دیے گئے تو صہیب رضی اللہ تعالیٰ عنہ روتے ہو ئے اندر آئے کہہ رہے تھے ہائے میرا بھا ئی! ہا ئے میرا ساتھی!تو حضرت عمر رضی اللہ تعالیٰ عنہ نے کہا صہیب! کیا تم مجھ پر رو رہے ہو؟حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے فر مایا ہے:\"میت کو اس کے گھر والوں کے بعض (طرح کے) رونے سے عذاب دیا جا تا ہے۔حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے کہا: جب حضرت عمر رضی اللہ تعالیٰ عنہ وفات پا گئے تو میں نے یہ بات حضرت عائشہ رضی اللہ تعالیٰ عنہا سے بیان کی انھوں نے کہا: اللہ عمر پر رحم فر ما ئے!اللہ کی قسم!نہیں رسول اللہ صلی اللہ علیہ وسلم نے یہ نہیں فر ما یا کہ اللہ تعا لیٰ مومن کو کسی کے رونے کی وجہ سے عذاب دیتا ہے بلکہ آپ نے فر ما یا:\"اللہ تعا لیٰ کا فرکے عذاب کو اس کے گھر والوں کے اس پر رونے کی وجہ سے بڑھا دیتا ہے۔\"کہا اور حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا: اور تمھا رے لیے قرآن کا فی ہے (جس میں یہ ہے) اور بو جھ اٹھا نے والی کو ئی جا ن کسی دوسری جا ن کا بوجھ نہیں اٹھا ئے گی۔اسکے ساتھ حضرت ابن عباس رضی اللہ تعالیٰ عنہ نے کہا اور اللہ ہی ہنساتا ہے اور رلا تا ہے۔ابن ابی ملیکہ نے نے کہا: اللہ کی قسم!حضرت ابن عمر رضی اللہ تعالیٰ عنہ نے (جواب میں) کچھ نہیں کہا۔"}],[2094,"عمرو ( بن دینا ر ) نے ابن ابی ملیکہ سے روا یت کی ، انھوں نے کہا : ہم سیدنا عثمان رضی اللہ تعالیٰ عنہ کی صاحبزادی اُم ابان کے جنا زے میں ( حاضر ) تھے ۔ ۔ ۔ اور مذکورہ حدیث بیان کی ، انھوں ( عمرو ) نے سیدنا عمر رضی اللہ تعالیٰ عنہ سے ( آگے ) نبی صلی اللہ علیہ وسلم سے روا یت مرفوع ہو نے کی صراحت نہیں کی جس طرح ایوب اور ابن جریج نے اس کی صراحت کی ہے اور ان دو نوں کی حدیث سے زیادہ مکمل ہے ۔","",{"u2":"عمرو (بن دینا ر)نے ابن ابی ملیکہ سے روا یت کی، انھوں نے کہا: ہم حضرت عثمان رضی اللہ تعالیٰ عنہ کی صاحبزادی اُم ابان کے جنا زے میں (حاضر) تھے۔۔۔اور مذکورہ حدیث بیان کی،انھوں (عمرو) نے حضرت عمر رضی اللہ تعالیٰ عنہ سے (آگے) نبی صلی اللہ علیہ وسلم سے روا یت مرفوع ہو نے کی صراحت نہیں کی جس طرح ایوب اور ابن جریج نے اس کی صراحت کی ہے اور ان دو نوں کی حدیث سے زیادہ مکمل ہے۔"}],[2095,"سالم نے سیدنا عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" میت کو زندہ کے رونے سے عذاب دیا جا تا ہے ۔","",{"u2":"سالم نے حضرت عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"میت کو زندہ کے رونے سے عذاب دیا جا تا ہے۔"}],[2096,"حماد بن زید نے ہشام بن عروہ سے انھوں نے اپنے والد سے روا یت کی انھوں نے کہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے سامنے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ کا روایت کردہ قول بیان کیا گیا : میت کو اس کے گھر والوں کے رونے سے عذاب دیا جا تا ہے تو انھوں نے کہا : اللہ عبد الرحمٰن پر رحم فر ما ئے انھوں نے ایک چیز کو سنا لیکن ( پوری طرح ) محفوظ نہ رکھا ( امرواقع یہ ہے کہ ) رسول اللہ صلی اللہ علیہ وسلم کے سامنے ایک یہودی کا جنا زہ گزرا اور وہ لو گ اس پر رو رہے تھے تو آپ نے فر ما یا : \" تم رو رہے ہو اور اسے عذاب دیا جا رہا ہے ۔","",{"u2":"حماد بن زید نے ہشام بن عروہ سے انھوں نے اپنے والد سے روا یت کی انھوں نے کہا: حضرت عائشہ رضی اللہ تعالیٰ عنہا کے سامنے حضرت ابن عمر رضی اللہ تعالیٰ عنہ کا روایت کردہ قول بیان کیا گیا:میت کو اس کے گھر والوں کے رونے سے عذاب دیا جا تا ہے تو انھوں نے کہا: اللہ عبد الرحمٰن پر رحم فر ما ئے انھوں نے ایک چیز کو سنا لیکن (پوری طرح) محفوظ نہ رکھا (امرواقع یہ ہے کہ) رسول اللہ صلی اللہ علیہ وسلم کے سامنے ایک یہودی کا جنا زہ گزرا اور وہ لو گ اس پر رو رہے تھے تو آپ نے فر ما یا:\"تم رو رہے ہو اور اسے عذاب دیا جا رہا ہے۔"}],[2097,"ابو اسامہ نے ہشام سے اور انھوں نے اپنے والد ( عروہ ) سے روایت کی انھوں نے کہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے پاس اس بات کا ذکر کیا گیا کہ سیدنا ابن عمر رضی اللہ تعالیٰ عنہ رسول اللہ صلی اللہ علیہ وسلم سے مرفوعاً یہ بیان کرتے ہیں میت کو اس کی قبر میں اس کے گھر والوں کے رونے سے عذاب دیا جا تا ہے ۔ \" انھوں نے کہا : وہ ( ابن عمر رضی اللہ تعالیٰ عنہ ) بھول گئے ہیں رسول اللہ صلی اللہ علیہ وسلم نے تو یہ فر ما یا تھا : \" اس ( مرنے والے ) کو اس کی غلطی یا گناہ کی وجہ سے عذاب دیا جا رہا ہے اور اس کے گھر والے اب اسی وقت اس پر رورہے ہیں اور یہ ( بھول ) ان ( اعبداللہ رضی اللہ تعالیٰ عنہ ) کی اس روا یت کے مانند ہے کہ رسول اللہ صلی اللہ علیہ وسلم بدر کے دب اس کنویں ( کے کنارے ) پر کھڑے ہو ئے جس بدر میں قتل ہو نے والے مشرکوں کی لا شیں تھیں تو آپ نے ان سے جو کہنا تھا کہا ( اور فرمایا : \" اب ) جو میں کہہ رہا ہوں وہ اس کو بخوبی سن رہے ہیں ۔ حالا نکہ ( اس بات میں بھی ) وہ بھول گئے آپ نے تو فر ما یا تھا : \" یہ لو گ بخوبی جانتے ہیں کہ میں ان سے ( دنیامیں ) جو کہا کرتا تھا وہ حق تھا ۔ \" پھر انھوں ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا ) نے ( یہ آیتیں پڑھیں ) \" اور بے شک تو مردوں کو نہیں سنا سکتا ۔ \" اور تو ہر گز انھیں سنانے والا نہیں جو قبروں میں ہیں ( گویا ) آپ یہ کہہ رہے ہیں : جبکہ وہ آگ میں اپنے ٹھکانے بنا چکے ہیں ( اور وہ اچھی طرح جان چکے ہیں کہ جو ان سے کہا گیا تھا وہی سچ ہے یعنی ابن عمر رضی اللہ تعالیٰ عنہ ان دو روایتوں کا اصل بیان محفوظ نہیں رکھ سکے ۔)","",{"u2":"ابو اسامہ نے ہشام سے اور انھوں نے اپنے والد (عروہ) سے روایت کی انھوں نے کہا: حضرت عائشہ رضی اللہ تعالیٰ عنہا کے پاس اس بات کا ذکر کیا گیا کہ حضرت ابن عمر رضی اللہ تعالیٰ عنہ رسول اللہ صلی اللہ علیہ وسلم سے مرفوعاً یہ بیان کرتے ہیں میت کو اس کی قبر میں اس کے گھر والوں کے رونے سے عذاب دیا جا تا ہے۔\"انھوں نے کہا: وہ (ابن عمر رضی اللہ تعالیٰ عنہ) بھول گئے ہیں رسول اللہ صلی اللہ علیہ وسلم نے تو یہ فر ما یا تھا:\"اس(مرنےوالے) کو اس کی غلطی یا گناہ کی وجہ سے عذاب دیا جا رہا ہے اور اس کے گھر والے اب اسی وقت اس پر رورہے ہیں اور یہ (بھول) ان (اعبداللہ رضی اللہ تعالیٰ عنہ) کی اس روا یت کے مانند ہے کہ رسول اللہ صلی اللہ علیہ وسلم بدر کے دب اس کنویں (کے کنارے) پر کھڑے ہو ئے جس بدر میں قتل ہو نے والے مشرکوں کی لا شیں تھیں تو آپ نے ان سے جو کہنا تھا کہا (اور فرمایا:\"اب) جو میں کہہ رہا ہوں وہ اس کو بخوبی سن رہے ہیں۔حالا نکہ (اس بات میں بھی) وہ بھول گئے آپ نے تو فر ما یا تھا:\" یہ لو گ بخوبی جانتے ہیں کہ میں ان سے(دنیامیں) جو کہاکرتا تھا وہ حق تھا۔\"پھر انھوں (حضرت عائشہ رضی اللہ تعالیٰ عنہا) نے (یہ آیتیں پڑھیں)\"اور بے شک تو مردوں کو نہیں سنا سکتا۔\"اور تو ہر گز انھیں سنانے والا نہیں جو قبروں میں ہیں (گویا) آپ یہ کہہ رہے ہیں:جبکہ وہ آگ میں اپنے ٹھکانے بنا چکے ہیں (اور وہ اچھی طرح جان چکے ہیں کہ جو ان سے کہا گیا تھا وہی سچ ہے یعنی ابن عمر رضی اللہ تعالیٰ عنہ ان دو روایتوں کا اصل بیان محفوظ نہیں رکھ سکے۔)"}],[2098,"وکیع نے بیان کیا کہ ہمیں ہشام بن عروہ نے اسی سند سے ابو اسامہ کی حدیث کے ہم معنی حدیث سنا ئی اور ابو اسامہ کی ( مذکورہ بالا ) حدیث زیادہ مکمل ہے ۔","",{"u2":"وکیع نے بیان کیا کہ ہمیں ہشام بن عروہ نے اسی سند سے ابو اسامہ کی حدیث کے ہم معنی حدیث سنا ئی اور ابو اسامہ کی (مذکورہ بالا) حدیث زیادہ مکمل ہے۔"}],[2099,"عمرہ بنت عبد الرحمٰن نے خبردی کہ انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے سنا ( اس موقع پر ) ان کے سامنے بیان کیا گیا تھا سیدنا عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ کہتے ہیں میت کو زندہ کے رونے کی وجہ سے عذاب دیا جاتا ہے تو عائشہ رضی اللہ تعالیٰ عنہا نے کہا : اللہ ابو عبد الرحمٰن کو معاف فر ما ئے !یقیناً انھوں نے جھوٹ نہیں بو لا لیکن وہ بھول گئے ہیں یا ان سے غلطی ہو گئی ہے ( امرواقع یہ ہے کہ ) رسول اللہ صلی اللہ علیہ وسلم ایک یہودی عورت ( کے جنازے ) کے پاس سے گزرے جس پر آہ و بکارکی جا رہی تھی تو آپ نے فر ما یا : \" یہ لو گ اس پر رو رہے ہیں اور اس کو اس کی قبر میں عذاب دیا جا رہاہے ۔","",{"u2":"عمرہ بنت عبد الرحمٰن نے خبردی کہ انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے سنا (اس موقع پر) ان کے سامنے بیان کیا گیا تھا حضرت عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ کہتے ہیں میت کو زندہ کے رونے کی وجہ سے عذاب دیا جاتا ہے تو عائشہ رضی اللہ تعالیٰ عنہا نے کہا: اللہ ابو عبد الرحمٰن کو معاف فر ما ئے!یقیناً انھوں نے جھوٹ نہیں بو لا لیکن وہ بھول گئے ہیں یا ان سے غلطی ہو گئی ہے (امرواقع یہ ہے کہ) رسول اللہ صلی اللہ علیہ وسلم ایک یہودی عورت (کے جنازے) کے پاس سے گزرے جس پر آہ و بکارکی جا رہی تھی تو آپ نے فر ما یا:\"یہ لو گ اس پر رو رہے ہیں اور اس کو اس کی قبر میں عذاب دیا جا رہاہے۔"}],[2100,"وکیع نے سعید بن عبید طائی اور محمد بن قیس سے اور انھوں نے علی بن ربیعہ سے روایت کی ، انھوں نے کہا : کو فہ میں سب سے پہلے جس پر نو حہ کیا گیا وہ قرظہ بن کعب تھا اس پر سیدنا مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا ہے ۔ \" جس پر نوھہ کیا گیا اسے قیامت کے دن اس پر کیے جا نے والے نو حے ( کی وجہ ) سے عذاب دیا جا ئے گا ۔","",{"u2":"وکیع نے سعید بن عبید طائی اور محمد بن قیس سے اور انھوں نے علی بن ربیعہ سے روایت کی،انھوں نے کہا: کو فہ میں سب سے پہلے جس پر نو حہ کیا گیا وہ قرظہ بن کعب تھا اس پر حضرت مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ نے کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا ہے۔\"جس پر نوھہ کیا گیا اسے قیامت کے دن اس پر کیے جا نے والے نو حے (کی وجہ) سے عذاب دیا جا ئے گا۔\""}],[2101,"ہمیں علی بن مسہر نے حدیث بیان کی ، ( کہا ) ہمیں محمد بن قیس نے علی بن ربیعہ سے خبر دی انھوں نے سیدنا مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اس ( سابقہ حدیث ) کے مانند روایت کی ۔","",{"u2":"ہمیں علی بن مسہر نے حدیث بیان کی،(کہا) ہمیں محمد بن قیس نے علی بن ربیعہ سے خبر دی انھوں نے حضرت مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اس (سابقہ حدیث) کے مانند روایت کی۔"}],[2102,"مروان بن معاویہ فزاری نے کہا : ہمیں سعید بن عبید طا ئی نے علی بن ربیعہ سے حدیث سنا ئی انھوں نے سیدنا مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اس ( سابقہ حدیث ) کے مانند روایت کی ۔","",{"u2":"مروان بن معاویہ فزاری نے کہا: ہمیں سعید بن عبید طا ئی نے علی بن ربیعہ سے حدیث سنا ئی انھوں نے حضرت مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اس (سابقہ حدیث) کے مانند روایت کی۔"}],[2103,"سیدنا ابو مالک اشعری رضی اللہ تعالیٰ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" میری امت میں جا ہلیت کے کا موں میں سے چار باتیں ( موجود ) ہیں وہ ان کو ترک نہیں کریں گے اَحساب ( باپ دادا کے اصلی یا مزعومہ کا ر ناموں ) پر فخر کرنا ( دوسروں کے ) نسب پر طعن کرنا ستاروں کے ذریعے سے بارش مانگنا اور نوحہ کرنا ۔ اور فر ما یا \" نوحہ کرنے والی جب اپنی مو ت سے پہلے تو بہ نہ کرے تو قیامت کے دن اس کو اس حالت میں اٹھا یا جا ئے گا کہ اس ( کے بدن ) پر تار کول کا لباس اور خارش کی قمیص ہو گی ۔","",{"u2":"حضرت ابو مالک اشعری رضی اللہ تعالیٰ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"میری امت میں جا ہلیت کے کا موں میں سے چار باتیں (موجود) ہیں وہ ان کو ترک نہیں کریں گے اَحساب (باپ داداکے اصلی یا مزعومہ کا ر ناموں) پر فخر کرنا (دوسروں کے) نسب پر طعن کرنا ستاروں کے ذریعے سے بارش مانگنا اور نوحہ کرنا۔اور فر ما یا \"نوحہ کرنے والی جب اپنی مو ت سے پہلے تو بہ نہ کرے تو قیامت کے دن اس کو اس حالت میں اٹھا یا جا ئے گا کہ اس (کے بدن) پر تار کول کا لباس اور خارش کی قمیص ہو گی۔\""}],[2104,"‏عبد الوہاب نے کہا : میں نے یحییٰ بن سعید سے سنا وہ کہہ رہے تھے مجھے عمرہ نے بتا یا کہ انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے سنا وہ فر ما رہی تھیں جب رسول اللہ صلی اللہ علیہ وسلم کو زید بن حارثہ جعفر بن ابی طالب اور عبد اللہ بن رواحہ رضی اللہ تعالیٰ عنہ کے قتل ( شہید ) ہو نے کی خبر پہنچی تو رسول اللہ صلی اللہ علیہ وسلم اس طرح ) مسجد میں ) بیٹھے کہ آپ ( کے چہرہ انور ) پر غم کا پتہ چل رہا تھا کہا : میں دروازے کی جھری ۔ ۔ ۔ دروازے کی درز ۔ ۔ ۔ ے دیکھ رہی تھی کہ آپ کے پاس ایک آدمی آیا اور کہنے لگا اللہ کے رسول صلی اللہ علیہ وسلم !جعفر ( کے خاندان ) کی عورتیں اور اس نے ان کے رونے کا تذکرہ کیا آپ نے اسے حکم دیا کہ وہ جا کر انھیں روکے وہ چلا گیا وہ ( دوبارہ ) آپ کے پاس آیا اور بتا یا کہ انھوں نے اس کی بات نہیں مانی آپ نے اسے دوبارہ حکم دیا کہ وہ جا کر انھیں روکے وہ گیا اور پھر ( تیسری بار ) آپ کے پاس آکر کہنے لگا : اللہ کی قسم !اللہ کے رسول !وہ ہم پر غالب آگئی ہیں کہا : : ان ( عائشہ رضی اللہ تعالیٰ عنہا ) کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" جاؤ اور ان کے منہ میں مٹی ڈال دو ۔ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : میں نے ( دل میں ) کہا : اللہ تیری ناک خاک آلود کرے !اللہ کی قسم !نہ تم وہ کا م کرتے ہو جس کا رسول اللہ صلی اللہ علیہ وسلم نے تمھیں حکم دیا ہے اور نہ ہی تم نے ( باربار بتا کر ) رسول اللہ صلی اللہ علیہ وسلم کو تکلیف ( دینا ) ترک کیا ہے ۔","",{"u2":"‏عبد الوہاب نے کہا: میں نے یحییٰ بن سعید سے سنا وہ کہہ رہے تھے مجھے عمرہ نے بتا یا کہ انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے سنا وہ فر ما رہی تھیں جب رسول اللہ صلی اللہ علیہ وسلم کو زید بن حارثہ جعفر بن ابی طالب اور عبد اللہ بن رواحہ رضی اللہ تعالیٰ عنہ کے قتل (شہید) ہو نے کی خبر پہنچی تو رسول اللہ صلی اللہ علیہ وسلم اس طرح)مسجد میں) بیٹھے کہ آپ (کے چہرہ انور) پر غم کا پتہ چل رہا تھا کہا: میں دروازے کی جھری۔۔۔دروازے کی درز۔۔۔ے دیکھ رہی تھی کہ آپ کے پاس ایک آدمی آیا اور کہنے لگا اللہ کے رسول صلی اللہ علیہ وسلم!جعفر (کے خاندان) کی عورتیں اور اس نے ان کے رونے کا تذکرہ کیا آپ نے اسے حکم دیا کہ وہ جا کر انھیں روکے وہ چلا گیا وہ (دوبارہ) آپ کے پاس آیا اور بتا یا کہ انھوں نے اس کی بات نہیں مانی آپ نے اسے دوبارہ حکم دیا کہ وہ جا کر انھیں روکے وہ گیا اور پھر (تیسری بار) آپ کے پاس آکر کہنے لگا:اللہ کی قسم!اللہ کے رسول!وہ ہم پر غالب آگئی ہیں کہا::ان(عائشہ رضی اللہ تعالیٰ عنہا) کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"جاؤ اور ان کے منہ میں مٹی ڈال دو۔حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا: میں نے (دل میں) کہا: اللہ تیری ناک خاک آلود کرے!اللہ کی قسم!نہ تم وہ کا م کرتے ہو جس کا رسول اللہ صلی اللہ علیہ وسلم نے تمھیں حکم دیا ہے اور نہ ہی تم نے (باربار بتا کر) رسول اللہ صلی اللہ علیہ وسلم کو تکلیف (دینا) ترک کیا ہے۔"}],[2105,"عبد اللہ بن نمیر ، معاویہ بن صالح اور عبد العزیز بن مسلم نے یحییٰ بن سعید سے اس سند کے ساتھ اسی طرح روایت کی اور عبد العزیز کی حدیث میں ہے تم رسول اللہ صلی اللہ علیہ وسلم کو مشقت میں ڈالنے سے باز نہیں آئے ۔","",{"u2":"عبد اللہ بن نمیر،معاویہ بن صالح اور عبد العزیز بن مسلم نے یحییٰ بن سعید سے اس سند کے ساتھ اسی طرح روایت کی اور عبد العزیز کی حدیث میں ہے تم رسول اللہ صلی اللہ علیہ وسلم کو مشقت میں ڈالنے سے باز نہیں آئے۔"}],[2106,"محمد ( بن سیرین ) نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے بیعت کے ساتھ ہم سے یہ عہد لیا کہ ہم نو حہ نہیں کریں گی تو ہم میں سے ان پانچ عورتوں : ام سلیم ، امعلاء ابو سیر ہ کی بیٹی ، معاذ رضی اللہ تعالیٰ عنہ کی بیوی یا ابو سیرہ کی بیٹی اور معاذ رضی اللہ تعالیٰ عنہ کی بیوی کے سواکسی نے ( کماحقہ ) اس کی پاسداری نہیں کی ۔","",{"u2":"محمد (بن سیرین) نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے بیعت کے ساتھ ہم سے یہ عہد لیا کہ ہم نو حہ نہیں کریں گی تو ہم میں سے ان پانچ عورتوں:ام سلیم،امعلاء ابو سیر ہ کی بیٹی،معاذ رضی اللہ تعالیٰ عنہ کی بیوی یا ابو سیرہ کی بیٹی اور معاذ رضی اللہ تعالیٰ عنہ کی بیوی کے سواکسی نے (کماحقہ) اس کی پاسداری نہیں کی۔"}],[2107,"ہشام نے حفصہ سے اور انھوں نے سیدنا عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے بیعت میں ہم سے یہ عہد لیا کہ تم نو حہ نہیں کرو گی ہم میں سے پانچ کے سوا کسی نے اس کی ( کماحقہ ) پاسداری نہیں کی ، ان ( پانچ ) میں سے ایک ام سلیم رضی اللہ تعالیٰ عنہا ہیں ۔","",{"u2":"ہشام نے حفصہ سے اور انھوں نے حضرت عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے بیعت میں ہم سے یہ عہد لیا کہ تم نو حہ نہیں کرو گی ہم میں سے پانچ کے سوا کسی نے اس کی (کماحقہ) پاسداری نہیں کی،ان (پانچ) میں سے ایک ام سلیم رضی اللہ تعالیٰ عنہا ہیں۔"}],[2108,"عاصم نے حفصہ سے اور انھوں نے سیدنا اُم عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : جب یہ آیت نازل ہو ئی : \" عورتیں آپ سے بیعت کریں کہ وہ اللہ تعا لیٰ کے ساتھ کسی کو شریک نہیں ٹھہرائیں گی ۔ ۔ ۔ اور کسی نیک کا م میں آپ کی مخالفت نہیں کریں گی ۔ \" کہا : اس ( عہد ) میں سے ایک نو حہ گری ( کی شق ) بھی تھی تو میں نے کہا : اے اللہ کے رسول اللہ صلی اللہ علیہ وسلم !فلا ں خاندان کے سوا کیونکہ انھوں نے جا ہلیت کے دور میں ( نوھہ کرنے پر ) میرے ساتھ تعاون کیا تھا تو اب میرے لیے بھی لا زمی ہے کہ میں ( ایک بار ) ان کے ساتھ تعاون کروں ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" فلاں کے خاندان کے سوا ۔","",{"u2":"عاصم نے حفصہ سے اور انھوں نے حضرت اُم عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی، انھوں نے کہا: جب یہ آیت نازل ہو ئی:\"عورتیں آپ سے بیعت کریں کہ وہ اللہ تعا لیٰ کے ساتھ کسی کو شریک نہیں ٹھہرائیں گی۔۔۔اور کسی نیک کا م میں آپ کی مخالفت نہیں کریں گی۔\" کہا: اس (عہد) میں سے ایک نو حہ گری (کی شق) بھی تھی تو میں نے کہا: اے اللہ کے رسول اللہ صلی اللہ علیہ وسلم!فلا ں خاندان کے سوا کیونکہ انھوں نے جا ہلیت کے دور میں (نوھہ کرنے پر) میرے ساتھ تعاون کیا تھا تو اب میرے لیے بھی لا زمی ہے کہ میں (ایک بار) ان کے ساتھ تعاون کروں۔اس پر رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"فلاں کے خاندان کے سوا۔\""}],[2109,"محمد بن سیرین نے کہا : سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا نے فر ما یا ہمیں جنازوں کے ساتھ جا نے سے روکا جا تا تھا لیکن ہمیں سختی کے ساتھ حکم نہیں دیا گیا ۔","",{"u2":"محمد بن سیرین نے کہا: حضرت ام عطیہ رضی اللہ تعالیٰ عنہا نے فر ما یا ہمیں جنازوں کے ساتھ جا نے سے روکا جا تا تھا لیکن ہمیں سختی کے ساتھ حکم نہیں دیا گیا۔"}],[2110,"حفصہ نے حجرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روا یت کی ، انھوں نے کہا : ہمیں جنازوں کے ساتھ جا نے سے رو کا گیا لیکن ہمیں سختی کے ساتھ حکم نہیں دیا گیا ۔","",{"u2":"حفصہ نے حجرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روا یت کی، انھوں نے کہا: ہمیں جنازوں کے ساتھ جا نے سے رو کا گیا لیکن ہمیں سختی کے ساتھ حکم نہیں دیا گیا۔"}],[2111,"یزید بن زریع نے ایوب سے انھوں نے محمد بن سیرین سے اور انھوں نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : جب ہم رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی کو غسل دے رہی تھیں تو آپ صلی اللہ علیہ وسلم ہمارے پاس تشریف لا ئے آپ نے فر ما یا : \" اس کو تین پانچ یا اگر تمھا ری را ئے ہو تو اس سے زائد مرتبہ پانی اور بیری ( کے پتوں ) سے غسل دو اور آخری بار میں کا فوریا کا فورمیں سے کچھ ڈال دینا اور جب تم فارغ ہو جا ؤ تو مجھے اطلا ع کر دینا ۔ جب ہم فارغ ہو گئیں تو ہم نے آپ کو اطلا ع دی تو آپ نے ہمیں اپنا تہبند دیا اور فر ما یا : \" اس کو اس کے جسم کے ساتھ لپیٹ دو","",{"u2":"یزید بن زریع نے ایوب سے انھوں نے محمد بن سیرین سے اور انھوں نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی، انھوں نے کہا: جب ہم رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی کو غسل دے رہی تھیں تو آپ صلی اللہ علیہ وسلم ہمارے پاس تشریف لا ئے آپ نے فر ما یا:\"اس کو تین پانچ یا اگر تمھا ری را ئے ہو تو اس سے زائد مرتبہ پانی اور بیری (کے پتوں) سے غسل دو اور آخری بار میں کا فوریا کا فورمیں سے کچھ ڈال دینا اور جب تم فارغ ہو جا ؤ تو مجھے اطلا ع کر دینا۔جب ہم فارغ ہو گئیں تو ہم نے آپ کو اطلا ع دی تو آپ نے ہمیں اپنا تہبند دیا اور فر ما یا:\" اس کو اس کے جسم کے ساتھ لپیٹ دو\""}],[2112,"حفصہ بنت سیرین نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : ہم نے ان ( کے بالوں ) کی کنگھی کر کے تین گندھی ہو ئی لٹیں بنا دیں","",{"u2":"حفصہ بنت سیرین نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی، انھوں نے کہا: ہم نے ان (کے بالوں) کی کنگھی کر کے تین گندھی ہو ئی لٹیں بنا دیں"}],[2113,"مالک بن انس ، حماد اور ابن علیہ نے ایوب سے انھوں نے محمد سے اور انھوں نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : نبی اکرم صلی اللہ علیہ وسلم کی بیٹیوں میں سے ایک وفات پاگئیں ۔ ابن علیہ کی حدیث میں ( یوں ) ہے ( ام عطیہ رضی اللہ تعالیٰ عنہا نے ) کہا : رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لا ئے اور ہم آپ کی بیٹی کو غسل دے رہی تھیں اور مالک کی حدیث میں ہے کہا : جب آپ کی بیٹی وفات پا گئیں تو آپ ہمارے پاس تشریف لا ئے ۔ ۔ ۔ ( اس سے آگے ) ام عطیہ رضی اللہ تعالیٰ عنہا سے محمد ، ان سے ایوب اور ان سے یزید کی حدیث کے مانند ہے","",{"u2":"مالک بن انس،حماد اور ابن علیہ نے ایوب سے انھوں نے محمد سے اور انھوں نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی،انھوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم کی بیٹیوں میں سے ایک وفات پاگئیں۔ابن علیہ کی حدیث میں (یوں) ہے (ام عطیہ رضی اللہ تعالیٰ عنہا نے) کہا: رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لا ئے اور ہم آپ کی بیٹی کو غسل دے رہی تھیں اور مالک کی حدیث میں ہے کہا: جب آپ کی بیٹی وفات پا گئیں تو آپ ہمارے پاس تشریف لا ئے۔۔۔(اس سے آگے)ام عطیہ رضی اللہ تعالیٰ عنہا سے محمد،ان سے ایوب اور ان سے یزید کی حدیث کے مانند ہے"}],[2114,"۔ حماد نے ایوب سے ، انھوں نے حفصہ سے اور انھوں نے حجرت ام عطیہ رضی اللہ تعالیٰ عنہا سے اس ( سابقہ حدیث ) کی طرح روایت بیان کی ، اس کے سوا کہ آپ نے فر ما یا : \" تین ، پانچ سات یا اگر تمھاری رائے ہو تو اس سے زائد بار ( غسل دینا ۔ ) حفصہ نے ام عطیہ رضی اللہ تعالیٰ عنہا سے کہا : ہم نے ان کے سر ( کے بالوں ) کی تین گندھی ہو ئی لٹیں بنا دیں ۔","",{"u2":"۔ حماد نے ایوب سے،انھوں نے حفصہ سے اور انھوں نے حجرت ام عطیہ رضی اللہ تعالیٰ عنہا سے اس (سابقہ حدیث) کی طرح روایت بیان کی، اس کے سوا کہ آپ نے فر ما یا:\"تین،پانچ سات یا اگر تمھاری رائے ہو تو اس سے زائد بار (غسل دینا۔)حفصہ نے ام عطیہ رضی اللہ تعالیٰ عنہا سے کہا:ہم نے ان کے سر (کے بالوں) کی تین گندھی ہو ئی لٹیں بنا دیں۔"}],[2115,"(اسماعیل ) ابن علیہ نے کہا : ہمیں ایوب نے خبر دی ، انھوں نے کہا : حفصہ نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے ( بیان کرتے ہو ئے ) کہا : ( رسول اللہ صلی اللہ علیہ وسلم نے ) فر ما یا : اس کو طاق تعداد میں تین ، پانچ یا سات مرتبہ غسل دو ۔ کہا اور ام عطیہ رضی اللہ تعالیٰ عنہا نے کہا : ہم نے ان ( کے بالوں ) کی کنگھی کر کے تین مینڈھیاں بنا دیں ۔","",{"u2":"(اسماعیل)ابن علیہ نے کہا: ہمیں ایوب نے خبر دی،انھوں نے کہا: حفصہ نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے (بیان کرتے ہو ئے) کہا: (رسول اللہ صلی اللہ علیہ وسلم نے)فر ما یا:اس کو طاق تعداد میں تین،پانچ یا سات مرتبہ غسل دو۔کہا اور ام عطیہ رضی اللہ تعالیٰ عنہا نے کہا: ہم نے ان (کے بالوں) کی کنگھی کر کے تین مینڈھیاں بنا دیں۔"}],[2116,"عاصم احول نے حفصہ بنت سیرین سے اور انھوں نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا : جب رسول اللہ صلی اللہ علیہ وسلم کی ( بڑی ) بیٹی زینب رضی اللہ تعالیٰ عنہا وفات پا گئیں تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں فر ما یا : \" اسے طاق تعداد میں تین یا پنچ مرتبہ غسل دو اور پانچویں بار ( پانی میں ) کا فور ۔ ۔ ۔ یا کچھ کا فور ۔ ۔ ۔ ڈال دینا اور جب تم غسل سے فارغ ہو جا ؤتو مجھے بتا نا ۔ \" ہم نے آپ کو بتا یا تو آپ نے ہمیں اپنا تہبند دیا اور فر ما یا : \" اس ( تہبند ) کو اس کے جسم کے ساتھ لپیٹ دو ۔","",{"u2":"عاصم احول نے حفصہ بنت سیرین سے اور انھوں نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم کی (بڑی) بیٹی زینب رضی اللہ تعالیٰ عنہا وفات پا گئیں تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں فر ما یا:\"اسے طاق تعداد میں تین یا پنچ مرتبہ غسل دو اور پانچویں بار (پانی میں) کا فور۔۔۔یا کچھ کا فور۔۔۔ڈال دینا اور جب تم غسل سے فارغ ہو جا ؤتو مجھے بتا نا۔\"ہم نے آپ کو بتا یا تو آپ نے ہمیں اپنا تہبند دیا اور فر ما یا:\"اس (تہبند) کو اس کے جسم کے ساتھ لپیٹ دو۔\""}],[2117,"ہشا م بن حسان نے حفصہ بنت سیرین سے اور انھوں نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشر یف لا ئے اور ہم آپ کی بیٹیوں میں سے ایک کو غسل دے رہی تھیں تو آپ نے فر ما یا : \" اسے طاق تعداد میں پانچ یا اس سے زائد بار غسل دینا ۔ ( آگے ) ایوب اور عاصم کی حدیث کے ہم معنی ( حدیث بیان کی ) اس حدیث میں انھوں نے کہا : ( ام عطیہ رضی اللہ تعالیٰ عنہا نے ) کہا : ہم نے ان کے بالوں کو تین تہائیوں میں گو ندھ دیا ان کے سر کے دو نوں طرف اور انکی پیشانی کے بال ۔","",{"u2":"ہشا م بن حسان نے حفصہ بنت سیرین سے اور انھوں نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی، انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشر یف لا ئے اور ہم آپ کی بیٹیوں میں سے ایک کو غسل دے رہی تھیں تو آپ نے فر ما یا:\"اسے طاق تعداد میں پانچ یا اس سے زائد بار غسل دینا۔(آگے) ایوب اور عاصم کی حدیث کے ہم معنی (حدیث بیان کی) اس حدیث میں انھوں نے کہا: (ام عطیہ رضی اللہ تعالیٰ عنہا نے)کہا: ہم نے ان کے بالوں کو تین تہائیوں میں گو ندھ دیا ان کے سر کے دو نوں طرف اور انکی پیشانی کے بال۔"}],[2118,"ہشیم نے خالد سے خبردی انھوں نے حفصہ بنت سیرین سے اور انھوں نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جہاں انھیں اپنی بیٹی کو غسل دینے کا حکم دیا تو ( وہاں یہ بھی ) فر ما یا : \" ان کی دائیں جانب سے اور اس کے وضو کے اعضا ء سے ( غسل کی ابتداء کرو ۔)","",{"u2":"ہشیم نے خالد سے خبردی انھوں نے حفصہ بنت سیرین سے اور انھوں نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جہاں انھیں اپنی بیٹی کو غسل دینے کا حکم دیا تو (وہاں یہ بھی) فر ما یا:\"ان کی دائیں جانب سے اور اس کے وضو کے اعضا ء سے (غسل کی ابتداء کرو۔(\""}],[2119,"اسماعیل ابن علیہ نے خالد سے انھوں نے حفصہ سے اور انھوں نے سیدہ ام عطیہ رضی اللہ تعالیٰ عنہا سے روا یت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیٹی کے غسل کے بارے میں ان سے فر ما یا : \" ان کی دائیں جا نب سے اور ان کے وضو کے اعضاء سے آغاز کرو ۔","",{"u2":"اسماعیل ابن علیہ نے خالد سے انھوں نے حفصہ سے اور انھوں نے حضرت ام عطیہ رضی اللہ تعالیٰ عنہا سے روا یت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیٹی کے غسل کے بارے میں ان سے فر ما یا:\" ان کی دائیں جا نب سے اور ان کے وضو کے اعضاء سے آغاز کرو۔"}],[2120,"ابو معاویہ نے اعمش سے انھوں نے شقیق سے اور انھوں نے سیدنا خباب بن ارت رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اللہ کے راستے میں ہجرت کی ۔ ہم اللہ کی رضاچا ہتے تھے تو ( اس کے وعدے کے مطا بق ) ہمارا اجر اللہ پر واجب ہو گیا ۔ ہم میں سے کچھ لو گ چلے گئے انھوں نے ( دنیا میں ) اپنے اجر میں سے کچھ نہیں لیا ان میں سے ایک مصعب بن عمیر رضی اللہ تعالیٰ عنہا تھے وہ احد کے دن شہید ہو ئے تو ان کے لیے ایک دھاری دار چادر کے سوا کو ئی چیز نہ ملی جس میں ان کو کفن دیا جا تا ۔ جب ہم اس کو ان کے سر پر ڈالتے تو ان کے پا ؤں باہر نکل جا تے اور جب ہم اسے ان کے پیروں پر رکھتے تو سر نکل جا تا ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" اس کو ان کے سر والے حصے پر ڈال دا اور پاؤں پر کچھ اذخر ( گھاس ) ڈال دو ۔ اور ہم میں سے کو ئی ایسا ہے جس کے لیے پھل پک چکا ہے اور وہ اس کو چن رہا ہے","",{"u2":"ابو معاویہ نے اعمش سے انھوں نے شقیق سے اور انھوں نے حضرت خباب بن ارت رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا: ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اللہ کے راستے میں ہجرت کی۔ہم اللہ کی رضاچا ہتے تھے تو (اس کے وعدے کے مطا بق) ہمارا اجر اللہ پر واجب ہو گیا۔ ہم میں سے کچھ لو گ چلے گئے انھوں نے (دنیا میں) اپنے اجر میں سے کچھ نہیں لیا ان میں سے ایک مصعب بن عمیر رضی اللہ تعالیٰ عنہا تھے وہ احد کے دن شہید ہو ئے تو ان کے لیے ایک دھاری دار چادر کے سوا کو ئی چیز نہ ملی جس میں ان کو کفن دیا جا تا۔جب ہم اس کو ان کے سر پر ڈالتے تو ان کے پا ؤں باہر نکل جا تے اور جب ہم اسے ان کے پیروں پر رکھتے تو سر نکل جا تا۔اس پر رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\" اس کو ان کے سر والے حصے پر ڈال دا اور پاؤں پر کچھ اذخر (گھاس) ڈال دو۔ اور ہم میں سے کو ئی ایسا ہے جس کے لیے پھل پک چکا ہے اور وہ اس کو چن رہا ہے -"}],[2121,"جریر عیسیٰ بن یو نس علی بن مسہر اور ابن عیینہ نے اعمش سے اسی سند کے ساتھ اسی طرح حدیث بیان کی ۔","",{"u2":"جریر عیسیٰ بن یو نس علی بن مسہر اور ابن عیینہ نے اعمش سے اسی سند کے ساتھ اسی طرح حدیث بیان کی۔"}],[2122,"ابو معاویہ نے ہشام بن عروہ سے انھوں نے اپنے والد ( عروہ ) سے انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کو سحول ( یمن ) سے لا ئے جا نے والے تین سفید سوتی کپڑوں میں کفن دیا گیا ان میں نہ قمیص تھی اور نہ عمامہ البتہ حُلے ( ہم رنگ چادروں پر مشتمل جوڑے ) کے حوالے سے لو گ اشتباہ میں پڑگئے بلا شبہ وہ آپ کے لیے خرید ا گیا تھا تا کہ آپ کو اس میں کفن دیا جا ئے ۔ پھر اس حلے کو چھوڑ دیا گیا اور آپ کو سحول کے تین سفید کپڑوں میں کفن دیا گیا اور اس ( حلے ) کو عبد اللہ بن ابی بکر رضی اللہ تعالیٰ عنہ نے لے لیا اور کہا : میں اس کو ( اپنے پاس ) محفوظ رکھوں گا یہاں تک کہ اس میں خود اپنے کفن کا انتظام کروں گا بعد میں کہا : اگر اسکو اللہ تعا لیٰ اپنے نبی کے لیے پسند فر ماتا تو آپ کو اس میں کفن ( دینے کا بندوبست کر ) دیتا اس لیے انھوں نے اسے فروخت کردیا اور اس کی قیمت صدقہ کر دی ۔","",{"u2":"ابو معاویہ نے ہشام بن عروہ سے انھوں نے اپنے والد (عروہ) سے انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کو سحول (یمن) سے لا ئے جا نے والے تین سفید سوتی کپڑوں میں کفن دیا گیا ان میں نہ قمیص تھی اور نہ عمامہ البتہ حُلے (ہم رنگ چادروں پر مشتمل جوڑے) کے حوالے سے لو گ اشتباہ میں پڑگئے بلا شبہ وہ آپ کے لیے خرید ا گیا تھا تا کہ آپ کو اس میں کفن دیا جا ئے۔پھر اس حلے کو چھوڑ دیا گیا اور آپ کو سحول کے تین سفید کپڑوں میں کفن دیا گیا اور اس (حلے)کو عبد اللہ بن ابی بکر رضی اللہ تعالیٰ عنہ نے لے لیا اور کہا: میں اس کو (اپنے پاس) محفوظ رکھوں گا یہاں تک کہ اس میں خود اپنے کفن کا انتظام کروں گا بعد میں کہا: اگر اسکو اللہ تعا لیٰ اپنے نبی کے لیے پسند فر ماتا تو آپ کو اس میں کفن (دینے کا بندوبست کر)دیتا اس لیے انھوں نے اسے فروخت کردیا اور اس کی قیمت صدقہ کر دی۔"}],[2123,"علی بن مسہر نے کہا : ہمیں ہشام بن عروہ نے اپنے والد ( عروہ ) سے حدیث سنا ئی انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کو عبد اللہ بن ابی بکر رضی اللہ تعالیٰ عنہ کے ایک یمنی حلے میں لپیٹا ( کفن دیا ) گیا پھر اس کو اتاردیا گیا اور آپ کو سحول کے تین سفید یمنی کپڑوں میں کفن دیا گیا جن میں نہ قمیص تھی اور نہ عمامہ ۔ عبد اللہ رضی اللہ تعالیٰ عنہ نے وہ حلہ اٹھا لیا اور کہا : مجھے اس میں کفن دیا جا ئے گا پھر کہا : رسول اللہ صلی اللہ علیہ وسلم کو اس میں کفن نہیں دیا گیا تو مجھے اس میں کفن دیا جا ئے گا !چنانچہ انھوں نے اس کو صدقہ کردیا ۔","",{"u2":"علی بن مسہر نے کہا: ہمیں ہشام بن عروہ نے اپنے والد (عروہ) سے حدیث سنا ئی انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کو عبد اللہ بن ابی بکر رضی اللہ تعالیٰ عنہ کے ایک یمنی حلے میں لپیٹا (کفن دیا) گیا پھر اس کو اتاردیا گیا اور آپ کو سحول کے تین سفید یمنی کپڑوں میں کفن دیا گیا جن میں نہ قمیص تھی اور نہ عمامہ۔عبد اللہ رضی اللہ تعالیٰ عنہ نے وہ حلہ اٹھا لیا اور کہا: مجھے اس میں کفن دیا جا ئے گا پھر کہا: رسول اللہ صلی اللہ علیہ وسلم کو اس میں کفن نہیں دیا گیا تو مجھے اس میں کفن دیا جا ئے گا!چنانچہ انھوں نے اس کو صدقہ کردیا۔"}],[2124,"حفص بن غیاث ، ابن عیینہ ، ابن ادریس ، عبدہ ، وکیع اور عبد العزیز سب نے ہشام سے اسی سند کے ساتھ روایت کی اور ان کی حدیث میں عبد اللہ بن ابی بکر رضی اللہ تعالیٰ عنہ کا واقعہ نہیں ہے ۔","",{"u2":"حفص بن غیاث، ابن عیینہ،ابن ادریس،عبدہ،وکیع اور عبد العزیز سب نے ہشام سے اسی سند کے ساتھ روایت کی اور ان کی حدیث میں عبد اللہ بن ابی بکر رضی اللہ تعالیٰ عنہ کا واقعہ نہیں ہے۔"}],[2125,"ابو سلمہ ( عبد اللہ بن عبد الرحمان بن عوف رضی اللہ تعالیٰ عنہ ) سے روایت ہے کہ انھوں نے کہا : میں نے نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے سوال کیا : میں نے ان سے کہا : رسول اللہ صلی اللہ علیہ وسلم کو کتنے کپڑوں میں کفن دیا گیا تھا ؟تو انھوں نے کہا : تین سحولی کپڑوں میں ۔","",{"u2":"ابو سلمہ (عبد اللہ بن عبد الرحمان بن عوف رضی اللہ تعالیٰ عنہ) سے روایت ہے کہ انھوں نے کہا: میں نے نبی صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے سوال کیا:میں نے ان سے کہا: رسول اللہ صلی اللہ علیہ وسلم کو کتنے کپڑوں میں کفن دیا گیا تھا؟تو انھوں نے کہا: تین سحولی کپڑوں میں۔"}],[2126,"صالح ( بن کیسان ) نے ابن شہاب ( زہری سے روایت کی ، انھیں ابو سلمہ بن عبد الرحمان نے خبردی کہ ام المومنین سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : جب رسول اللہ صلی اللہ علیہ وسلم فوت ہو ئے تو آپ کو دھاری دار یمنی چادر سے ڈھا نپا گیا ۔)","",{"u2":"صالح (بن کیسان) نے ابن شہاب (زہری سے روایت کی،انھیں ابو سلمہ بن عبد الرحمان نے خبردی کہ ام المومنین حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم فوت ہو ئے تو آپ کو دھاری دار یمنی چادر سے ڈھا نپا گیا۔"}],[2127,"معمر اور شہاب نے ( ابن شہاب ) زہری سے اسی سند کے ساتھ بالکل اسی طرح حدیث روایت کی ۔","",{"u2":"معمر اور شہاب نے (ابن شہاب) زہری سے اسی سند کے ساتھ بالکل اسی طرح حدیث روایت کی۔"}],[2128,"سیدنا جا بر بن عبد اللہ رضی اللہ تعالیٰ عنہ بیان کر تے ہیں کہ ایک دن نبی اکرم صلی اللہ علیہ وسلم نے خطبہ دیا ، آپ نے اپنے اصحاب میں سے ایک آدمی کا تذکرہ فر ما یا جو فوت ہوا تو اس کو معمولی ( کپڑے میں ) کفن دیا گیا اور رات ہی کو دفن کر دیا گیا تو نبی اکرم صلی اللہ علیہ وسلم نے کسی بھی آدمی کو رات کو دفن کرنے سے ڈانٹ کر روکا یہاں تک کہ اس کی ( شان شایان طریقے سے ) نماز جنازہ ادا کی جا ئے اولاًیہ کہ کو ئی انسان اس پر مجبور ہو جا ئے اور نبی اکرم صلی اللہ علیہ وسلم نے فر ما یا : \" جب تم میں سے کو ئی شخص اپنے بھا ئی کو کفن دے تو اسے اچھا کفن دے ۔","",{"u2":"حضرت جا بر بن عبد اللہ رضی اللہ تعالیٰ عنہ بیان کر تے ہیں کہ ایک دن نبی اکرم صلی اللہ علیہ وسلم نے خطبہ دیا،آپ نے اپنے اصحاب میں سے ایک آدمی کا تذکرہ فر ما یا جو فوت ہوا تو اس کو معمولی (کپڑے میں) کفن دیا گیا اور رات ہی کو دفن کر دیا گیا تو نبی اکرم صلی اللہ علیہ وسلم نے کسی بھی آدمی کو رات کو دفن کرنے سے ڈانٹ کر روکا یہاں تک کہ اس کی (شان شایان طریقے سے) نماز جنازہ ادا کی جا ئے اولاًیہ کہ کو ئی انسان اس پر مجبور ہو جا ئے اور نبی اکرم صلی اللہ علیہ وسلم نے فر ما یا:\"جب تم میں سے کو ئی شخص اپنے بھا ئی کو کفن دے تو اسے اچھا کفن دے۔"}],[2129,"سفیان بن عیینہ نے زہری سے انھوں نے سعید ( بن مسیب ) سے انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فر ما یا جنا زے ( کو لے جا نے ) میں جلدی کرو ، اگر وہ ( میت ) نیک ہے تو جس کی طرف تم اس کو لے جا رہے ہو وہ خیرہے اگر وہ اس کے سوا ہے تو پھر وہ شر ہے جسے تم اپنی گردنوں سے اتاردو گے ۔","",{"u2":"سفیان بن عیینہ نے زہری سے انھوں نے سعید (بن مسیب)سے انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی،آپ نے فر ما یا جنا زے (کو لے جا نے) میں جلدی کرو،اگر وہ (میت) نیک ہے تو جس کی طرف تم اس کو لے جا رہے ہو وہ خیرہے اگر وہ اس کے سوا ہے تو پھر وہ شر ہے جسے تم اپنی گردنوں سے اتاردو گے۔"}],[2130,"معمر اور محمد بن ابی حفصہ دو نوں نے زہری سے ، انھوں نے سعید ( بن مسیب ) سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے ، انھوں نے نبی صلی اللہ علیہ وسلم سے ( یہی حدیث ) روایت کی ، لیکن معمر کی حدیث میں ہے انھوں نے کہا : میں اس کے سوا اور کچھ نہیں جا نتا کہ انھوں ( ابو ہریرہ رضی اللہ تعالیٰ عنہ ) نے اس حدیث کو مرفوع ( رسول اللہ صلی اللہ علیہ وسلم سے ) بیان کیا ہے ۔","",{"u2":"معمر اور محمد بن ابی حفصہ دو نوں نے زہری سے، انھوں نے سعید (بن مسیب) سے، انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے، انھوں نے نبی صلی اللہ علیہ وسلم سے(یہی حدیث) روایت کی، لیکن معمر کی حدیث میں ہے انھوں نے کہا: میں اس کے سوا اور کچھ نہیں جا نتا کہ انھوں (ابو ہریرہ رضی اللہ تعالیٰ عنہ) نے اس حدیث کو مرفوع (رسول اللہ صلی اللہ علیہ وسلم سے) بیان کیا ہے۔"}],[2131,"ابو امامہ بن سہل بن حنیف نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا ہے : \" جنا زے میں جلدی کرو اگر ( میت ) نیک ہے تو تم نے اسے بھلا ئی کے قریب کر دیا اور اگر وہ اس کے سوا ہے تو شر ہے جسے تم اپنی گردنوں سے اتار دو گے ۔","",{"u2":"ابو امامہ بن سہل بن حنیف نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روا یت کی انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا ہے:\" جنا زے میں جلدی کرو اگر (میت) نیک ہے تو تم نے اسے بھلا ئی کے قریب کر دیا اور اگر وہ اس کے سوا ہے تو شر ہے جسے تم اپنی گردنوں سے اتار دو گے۔"}],[2132,"ابو طا ہر حرملہ یحییٰ اور ہارون بن سعید ایلی ۔ ۔ ۔ اس روایت کے الفا ظ ہارون اور حرملہ کے ہیں ۔ ۔ ۔ میں سے ہارون نے کہا : ہمیں حدیث سنا ئی اور دو سرے دو نوں نے کہا : ہمیں ابن وہب نے خبر دی ، انھوں نے نے کہا : مجھے یو نس نے ابن شہاب سے خبر دی کہا : مجھے عبد الرحمان بن ہر مزا عرج نے حدیث بیان کی کہ سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \"\" جو شخص جنا زے میں شریک رہا یہاں تک کہ نماز جنا زہ ادا کر لی گئی تو اس کے لیے ایک قیراط ہے اور جو اس ( جنازے ) میں شریک رہاحتیٰ کہ اس کو دفن کر دیا گیا تو اس کے لیے دو قیراط ہیں ۔ \"\" پوچھا گیا : دو قیراط سے کہا مراد ہے ؟ آپ صلی اللہ علیہ وسلم نے فر ما یا : \"\" دو بڑے پہاڑوں کے مانند ۔ ابو طا ہر کی حدیث یہاں ختم ہو گئی ۔ دوسرے دو اساتذہ نے اضافہ کیا : ابن شہاب نے کہا : سالم بن عبد اللہ بن عمرنے کہا : کہ سیدنا ابن عمر رضی اللہ تعالیٰ عنہ نماز جنازہ پڑھ کر لو ٹ آتے تھے جب ان کو سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ کی حدیث پہنچی تو انھوں نے نے کہایقیناًہم نے بہت سے قیراطوں میں نقصان اٹھا یا ۔","",{"u2":"ابو طا ہر حرملہ یحییٰ اور ہارون بن سعید ایلی۔۔۔اس روایت کے الفا ظ ہارون اور حرملہ کے ہیں۔۔۔میں سے ہارون نے کہا: ہمیں حدیث سنا ئی اور دو سرے دو نوں نے کہا: ہمیں ابن وہب نے خبر دی،انھوں نے نے کہا: مجھے یو نس نے ابن شہاب سے خبر دی کہا: مجھے عبد الرحمان بن ہر مزا عرج نے حدیث بیان کی کہ حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"جو شخص جنا زے میں شریک رہا یہاں تک کہ نماز جنا زہ ادا کر لی گئی تو اس کے لیے ایک قیراط ہے اور جو اس (جنازے) میں شریک رہاحتیٰ کہ اس کو دفن کر دیا گیا تو اس کے لیے دو قیراط ہیں۔\"پوچھا گیا: دو قیراط سے کہا مراد ہے؟ آپ صلی اللہ علیہ وسلم نے فر ما یا:\"دو بڑے پہاڑوں کے مانند۔ابو طا ہر کی حدیث یہاں ختم ہو گئی۔\nدوسرے دو اساتذہ نے اضافہ کیا:ابن شہاب نے کہا: سالم بن عبد اللہ بن عمرنے کہا: کہ حضرت ابن عمر رضی اللہ تعالیٰ عنہ نماز جنازہ پڑھ کر لو ٹ آتے تھے جب ان کو حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ کی حدیث پہنچی تو انھوں نے نے کہایقیناًہم نے بہت سے قیراطوں میں نقصان اٹھا یا۔"}],[2133,"عبد الاعلیٰ اور عبد الررزاق نے معمر سے انھوںے زہری سے ، انھوں نے سعید بن مسیب سے انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں ے نبی صلی اللہ علیہ وسلم سے ( یہ روایت ) ان الفاظ : \" دو عظیم پہاڑوں تک بیان کی اور اس کے بعد والا حصہ بیان نہیں کیا ۔ اور عبد لاعلیٰ کی حدیث میں ہے ۔ یہاں تک کہ اس ( کے دفن ) سے فراغت ہو جا ئے ۔ \" اور عبد الررزاق کی حدیث میں ہے : \" یہاں تک کہ اس کو لحد میں رکھ دیا جا ئے ۔","",{"u2":"عبد الاعلیٰ اور عبد الررزاق نے معمر سے انھوںے زہری سے، انھوں نے سعید بن مسیب سے انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں ے نبی صلی اللہ علیہ وسلم سے (یہ روایت) ان الفاظ:\"دو عظیم پہاڑوں تک بیان کی اور اس کے بعد والا حصہ بیان نہیں کیا۔اور عبد لاعلیٰ کی حدیث میں ہے۔یہاں تک کہ اس (کے دفن) سے فراغت ہو جا ئے۔\"اور عبد الررزاق کی حدیث میں ہے:\"یہاں تک کہ اس کو لحد میں رکھ دیا جا ئے۔"}],[2134,"‏عقیل بن خالد نے ابن شہاب سے روایت کی کہ انھوں نے کہا : مجھے کئی لو گوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے حدیث سنا ئی اور انھوں نے نبی صلی اللہ علیہ وسلم سے جس طرح معمر کی حدیث ہے اور کہا : اور جو اس کو دفن کیے جا نے تک اس کے ساتھ رہا ۔","",{"u2":"‏عقیل بن خالد نے ابن شہاب سے روایت کی کہ انھوں نے کہا: مجھے کئی لو گوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے حدیث سنا ئی اور انھوں نے نبی صلی اللہ علیہ وسلم سے جس طرح معمر کی حدیث ہے اور کہا: اور جو اس کو دفن کیے جا نے تک اس کے ساتھ رہا۔"}],[2135,"سہیل کے والد ابو صالح نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روا یت کی ، فر ما یا : \" جس نے نماز جنازہ ادا کی اور اس کے پیچھے ( قبر ستان ) نہیں گیا تو اس کے لیے ایک قیراط ( اجر ) ہے اور اگر وہ اس کے پیچھے گیا تو اس کے لیے دو قیراط ہیں ۔ پو چھا گیا : دو قیراط کیا ہیں؟ فر ما یا : \" ان دو نوں میں سے چھوٹا اُحد پہاڑ کے مانند ہے ۔","",{"u2":"سہیل کے والد ابو صالح نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روا یت کی، فر ما یا:\"جس نے نماز جنازہ ادا کی اور اس کے پیچھے (قبر ستان) نہیں گیا تو اس کے لیے ایک قیراط (اجر) ہے اور اگر وہ اس کے پیچھے گیا تو اس کے لیے دو قیراط ہیں۔پو چھا گیا: دو قیراط کیا ہیں؟ فر ما یا:\"ان دو نوں میں سے چھوٹا اُحد پہاڑ کے مانند ہے۔"}],[2136,"نا فع نے کہا : سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے کہا گیا کہ ابو ہریرہ رضی اللہ تعالیٰ عنہ کہتے ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے ہو ئے سنا : \" جو شخص جنازے کے پیچھے چلا تو اس کے لیے قیراط اجرہے اس پر ابن عمر رضی اللہ تعالیٰ عنہ نے کہا : ابو ہریرہ رضی اللہ تعالیٰ عنہ نے ہمیں کثرت سے احادیث سنا ئی ہیں اس کے بعد انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے پا س پیغا م بھیجا اور ان سے پو چھا تو انھوں نے سیدنا ابو ہر یرہ رضی اللہ تعالیٰ عنہ کی تصدیق فر ما ئی اس پر سیدنا ابن عمر رضی اللہ تعالیٰ عنہ نے کہا : یقیناً ہم نے بہت سے قیراطوں ( کے حصول ) میں کو تا ہی کی ۔","",{"u2":"نا فع نے کہا: حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے کہا گیا کہ ابو ہریرہ رضی اللہ تعالیٰ عنہ کہتے ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے ہو ئے سنا:\"جو شخص جنازے کے پیچھے چلا تو اس کے لیے قیراط اجرہے اس پر ابن عمر رضی اللہ تعالیٰ عنہ نے کہا: ابو ہریرہ رضی اللہ تعالیٰ عنہ نے ہمیں کثرت سے احادیث سنا ئی ہیں اس کے بعد انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا کے پا س پیغا م بھیجا اور ان سے پو چھا تو انھوں نے حضرت ابو ہر یرہ رضی اللہ تعالیٰ عنہ کی تصدیق فر ما ئی اس پر حضرت ابن عمر رضی اللہ تعالیٰ عنہ نے کہا: یقیناً ہم نے بہت سے قیراطوں (کے حصول) میں کو تا ہی کی۔"}],[2137,"ابو حازم نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فر ما یا : \" جس نے نماز جنازہ ادا کیتو اس کے لیے قیراط ہے اور جو اس کے ساتھ گیا حتیٰ کہ اسے قبر میں اتاردیا گیا تو ( اس کے لیے ) دو قیراط ہیں ۔ ( ابو حازم نے ) کہا میں نے کہا : اے ابو ہریرہ رضی اللہ تعالیٰ عنہ قیراط کیا ہے ؟ انھوں نے کہا : احد پہاڑ کے مانند ۔","",{"u2":"ابو حازم نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوںنے نبی صلی اللہ علیہ وسلم سے روایت کی،آپ نے فر ما یا:\" جس نے نماز جنازہ ادا کیتو اس کے لیے قیراط ہے اور جو اس کے ساتھ گیا حتیٰ کہ اسے قبر میں اتاردیا گیا تو (اس کے لیے) دو قیراط ہیں۔(ابو حازم نے) کہا میں نے کہا: اے ابو ہریرہ رضی اللہ تعالیٰ عنہ قیراط کیا ہے؟ انھوں نے کہا: احد پہاڑ کے مانند۔"}],[2138,"داودبن عامر بن سعد بن ابی وقاص نے اپنے والد ( عامر ) سے حدیث بیان کی کہ وہ سیدنا عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ کے پا س بیٹھے ہو ئے تھے کہ صاحب مقصود خباب رضی اللہ تعالیٰ عنہ نے آکر کہا : اے عبد اللہ بن عمر!کیا آپ نے ہمیں سنا ابو ہریرہ رضی اللہ تعالیٰ عنہ کیا کہتے ہیں ؟ بلا شبہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے ہو ئے سنا ہے ۔ جو شخص جنازے کے ساتھ اس کے گھر سے نکا اور اس کی نماز جنا زہ ادا کی پھر اس کے ساتھ رہا حتیٰ کے اس کو دفن کر دیا گیا تو اس کے لیے بطور اجر دو قیرا ط ہیں ہر قیراط اُحد ( پہاڑ ) کے مانند ہے اور جس نے اس کی نماز جنازہ اداکی اور لو ٹ آیا اس کا اجر احد پہاڑ جیسا ہے ( یہ بات سنکر ) سیدنا ابن عمر رضی اللہ تعالیٰ عنہ نے خباب رضی اللہ تعالیٰ عنہ کو سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے پاس بھیجا ( تا کہ ) وہ ان سے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ کے قول کے بارے میں دریافت دریافت کریں اور پھر واپس آکر ان کو بتا ئیں کہ انھوں ( سیدہ عائشہ رضی اللہ تعالیٰ عنہا ) نے کیا کہا ۔ ( اس دوران میں ) ابن عمر رضی اللہ تعالیٰ عنہ نے مسجد کی کنکریوں سے ایک مٹھی بھرلی اور ان کو اپنے ہاتھ میں الٹ پلٹ کرنے لگے یہاں تک کہ پیام رساں ان کے پاس واپس آگیا اس نے کہا : سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا ہے کہ ابو ہریرہ رضی اللہ تعالیٰ عنہ نے سچ کہا ہے اس پر ابن عمر رضی اللہ تعالیٰ عنہ نے وہ کنکریاں جو ان کے ہاتھ میں تھیں زمین پر دے ماریں پھر کہا یقیناًہم نے بہت قیراطوں ( کے حصول ) میں کو تا ہی کی ۔","",{"u2":"داودبن عامر بن سعد بن ابی وقاص نے اپنے والد(عامر) سے حدیث بیان کی کہ وہ حضرت عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ کے پا س بیٹھے ہو ئے تھے کہ صاحب مقصود خباب رضی اللہ تعالیٰ عنہ نے آکر کہا: اے عبد اللہ بن عمر!کیا آپ نے ہمیں سنا ابو ہریرہ رضی اللہ تعالیٰ عنہ کیا کہتے ہیں؟ بلا شبہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ما تے ہو ئے سنا ہے۔ جو شخص جنازے کے ساتھ اس کے گھر سے نکا اور اس کی نماز جنا زہ ادا کی پھر اس کے ساتھ رہا حتیٰ کے اس کو دفن کر دیا گیا تو اس کے لیے بطور اجر دو قیرا ط ہیں ہر قیراط اُحد (پہاڑ) کے مانند ہے اور جس نے اس کی نماز جنازہ اداکی اور لو ٹ آیا اس کا اجر احد پہاڑ جیسا ہے (یہ بات سنکر) حضرت ابن عمر رضی اللہ تعالیٰ عنہ نے خباب رضی اللہ تعالیٰ عنہ کو حضرت عائشہ رضی اللہ تعالیٰ عنہا کے پاس بھیجا (تا کہ) وہ ان سے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ کے قول کے بارے میں دریافت دریافت کریں اور پھر واپس آکر ان کو بتا ئیں کہ انھوں (حضرت عائشہ رضی اللہ تعالیٰ عنہا) نے کیا کہا۔(اس دوران میں) ابن عمر رضی اللہ تعالیٰ عنہ نے مسجد کی کنکریوں سے ایک مٹھی بھرلی اور ان کواپنے ہاتھ میں الٹ پلٹ کرنے لگے یہاں تک کہ پیام رساں ان کے پاس واپس آگیا اس نے کہا: حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہاہے کہ ابو ہریرہ رضی اللہ تعالیٰ عنہ نے سچ کہا ہے اس پر ابن عمر رضی اللہ تعالیٰ عنہ نے وہ کنکریاں جو ان کے ہاتھ میں تھیں زمین پر دے ماریں پھر کہا یقیناًہم نے بہت قیراطوں (کے حصول) میں کو تا ہی کی۔"}],[2139,"شعبہ نے کہا : ہمیں قتادہ نے سالم بن ابی جعد سے حدیث سنا ئی انھوں نے معدان ابن ابی طلحہ یعمری سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام ثوبان رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" جس نے نماز جنا زہ پڑھی اس کے لیے ایک قیراط ہے اور اگر وہ اس کے دفن میں شامل ہوا تو اس کے لیے دو قیرا ط ہیں ( ایک ) قیرا ط احد ( پہاڑ ) کے ما نند ہے ۔","",{"u2":"شعبہ نے کہا:ہمیں قتادہ نے سالم بن ابی جعد سے حدیث سنا ئی انھوں نے معدان ابن ابی طلحہ یعمری سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام ثوبان رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\" جس نے نماز جنا زہ پڑھی اس کے لیے ایک قیراط ہے اور اگر وہ اس کے دفن میں شامل ہوا تو اس کے لیے دو قیرا ط ہیں (ایک) قیرا ط احد (پہاڑ) کے ما نند ہے۔"}],[2140,"ہشام سعید اور ابان نے قتادہ سے اسی سند کے ساتھ سابقہ حدیث کے مانند روایت کی سعید اور ہشام کی حدیث میں ہے نبی صلی اللہ علیہ وسلم سے قیراط کے بارے میں دریافت کیا گیا تو آپ نے فر ما یا : \" احد ( پہاڑ ) کے مانند ۔","",{"u2":"ہشام سعید اور ابان نے قتادہ سے اسی سند کے ساتھ سابقہ حدیث کے مانند روایت کی سعید اور ہشام کی حدیث میں ہے نبی صلی اللہ علیہ وسلم سے قیراط کے بارے میں دریافت کیا گیا تو آپ نے فر ما یا:\" احد (پہاڑ) کے مانند۔"}],[2141,"اسلام بن ابی مطیع نے ایوب سے انھوں نے ابو قلابہ سے انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے دودھ شریک بھا ئی عبداللہ بن یزید سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روا یت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \"\" کو ئی بھی ( مسلمان ) مرنے والا جس کی نماز جناز ہ مسلمانو کی ایک جماعت جن کی تعداد سو تک پہنچی ہو ادا کرے وہ سب اس کی سفارش کریں تو اس کے بارے میں ان کی سفارش قبول کر لی جا تی ہے ۔ ( سلام نے ) کہا میں نے یہ حدیث شعیب بن حجاب کو بیان کی تو انھوں نے کہا مجھے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ نے بھی یہ حدیث نبی صلی اللہ علیہ وسلم سے بیان کی ۔","",{"u2":"اسلام بن ابی مطیع نے ایوب سے انھوں نے ابو قلابہ سے انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا کے دودھ شریک بھا ئی عبداللہ بن یزید سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روا یت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"کو ئی بھی (مسلمان) مرنے والا جس کی نماز جناز ہ مسلمانو کی ایک جماعت جن کی تعداد سو تک پہنچی ہو ادا کرے وہ سب اس کی سفارش کریں تو اس کے بارے میں ان کی سفارش قبول کر لی جا تی ہے۔\n(سلام نے) کہا میں نے یہ حدیث شعیب بن حجاب کو بیان کی تو انھوں نے کہا مجھے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ نے بھی یہ حدیث نبی صلی اللہ علیہ وسلم سے بیان کی۔"}],[2142,"ہارون بن معروف ہارون بن سعید ایلی اور ولید بن شجاع میں سے ولید نے کہا : مجھے حدیث سنا ئی اور دوسرے دو نوں نے کہا : ہمیں حدیث سنا ئی ابن وہب نے انھوں نے کہا : مجھے ابو صخر نے شر یک بن عبد اللہ بن ابی نمر سے خبر دی انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ کے آزاد کردہ غلا م کریب سے اور انھوں نے سیدنا عبد اللہ بن عبا س رضی اللہ تعالیٰ عنہ سے روا یت کی کہ قدید یا عسفان میں ان کے ایک بیٹے کا انتقال ہو گیا تو انھوں نے کہا : کریب !دیکھو اس کے ( جنازے کے ) لیے کتنے لو گ جمع ہو چکے ہیں ۔ میں با ہر نکلا تو دیکھا کہ اس کی خا طر ( خاصے ) لو گ جمع ہو چکے ہیں تو میں نے ان کو اطلا ع دی ۔ انھوں نے پو چھا تو کہتے ہو کہ وہ چا لیس ہوں گے ؟ انھوں نے جواب دیا : ہاں ۔ تو انھوں نے فر ما یا : اس ( میت ) کو ( گھر سے ) باہر نکا لو کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا ہے : جو بھی مسلمان فوت ہو جا تا ہے اور اس کے جنا زے پر ( ایسے ) چالیس آدمی ( نماز ادا کرنے کے لیے ) کھڑے ہو جا تے ہیں جو اللہ کے ساتھ کسی چیز کو شریک نہیں ٹھہر اتے تو اللہ تعا لیٰ اس کے بارے میں ان کی سفارش کو قبول فر ما لیتا ہے ۔ ابن معروف کی روا یت میں ہے انھوں نے شریک بن ابی نمر سے انھوں نے کریب سے اور انھوں نے سیدنا ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی ۔ ( اس سند میں شریک کے والد اور ابو نمر کے بیٹے عبد اللہ کا نام لیے بغیر دادا کی طرف منسوب کرتے ہو ئے شریک بن ابی نمر کہا گیا ہے ۔)","",{"u2":"ہارون بن معروف ہارون بن سعید ایلی اور ولید بن شجاع میں سے ولید نے کہا: مجھے حدیث سنا ئی اور دوسرے دو نوں نے کہا: ہمیں حدیث سنا ئی ابن وہب نے انھوں نے کہا: مجھے ابو صخر نے شر یک بن عبد اللہ بن ابی نمر سے خبر دی انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ کے آزاد کردہ غلا م کریب سے اور انھوں نے حضرت عبد اللہ بن عبا س رضی اللہ تعالیٰ عنہ سے روا یت کی کہ قدید یا عسفان میں ان کے ایک بیٹے کا انتقال ہو گیا تو انھوں نے کہا: کریب!دیکھو اس کے (جنازے کے) لیے کتنے لو گ جمع ہو چکے ہیں۔میں با ہر نکلا تو دیکھا کہ اس کی خا طر (خاصے) لو گ جمع ہو چکے ہیں تو میں نے ان کو اطلا ع دی۔انھوں نے پو چھا تو کہتے ہو کہ وہ چا لیس ہوں گے؟ انھوں نے جواب دیا: ہاں۔تو انھوں نے فر ما یا:اس (میت) کو (گھر سے) باہر نکا لو کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا ہے: جو بھی مسلمان فوت ہو جا تا ہے اور اس کے جنا زے پر (ایسے)چالیس آدمی (نماز ادا کرنے کے لیے) کھڑے ہو جا تے ہیں جو اللہ کے ساتھ کسی چیز کو شریک نہیں ٹھہر اتے تو اللہ تعا لیٰ اس کے بارے میں ان کی سفارش کو قبول فر ما لیتا ہے۔\nابن معروف کی روا یت میں ہے انھوں نے شریک بن ابی نمر سے انھوں نے کریب سے اور انھوں نے حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت کی۔(اس سند میں شریک کے والد اور ابو نمر کے بیٹے عبد اللہ کا نام لیے بغیر داداکی طرف منسوب کرتے ہو ئے شریک بن ابی نمر کہا گیا ہے۔)"}],[2143,"عبد العزیز بن صہیب نے سیدنا انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ایک جنازہ گزرا تو اس کی اچھی صفت بیان کی گئی اس پر نبی اکرم صلی اللہ علیہ وسلم نے فر ما یا : \" واجب ہو گئی واجب ہو گئی واجب ہو گئی ، اس کے بعد ایک اور جنازہ گزرا تو اس کی بری صفت بیان کی گئی تو نبی اکرم صلی اللہ علیہ وسلم نے فر ما یا : \" واجب ہو گئی واجب ہو گئی واجب ہو گئی اس پر سیدنا عمر رضی اللہ تعالیٰ عنہ نے کہا : آپ پر میرے ماں باپ فدا ہوں! ایک جنازہ گزرا اور اس کی اچھی صفت بیان کی گئی تو آپ نے فر ما یا : \" واجب ہو گئی واجب ہو گئی واجب ہو گئی ۔ ایک اور جنازہ گزرا اور اس کی بری صفت بیان کی گئی تو آپ نے فر ما یا واجب ہو گئی واجب ہو گئی واجب ہو گئی \" ( اس کا مطلب کیا ہے؟ ) تو رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" جس کی تم لو گوں نے اچھی صفت بیان کی اس کے لیے جنت واجب ہو گئی اور جس کی تم نے بری صفت بیان کی اس کے لیے آگ واجب ہو گئی تم زمین میں اللہ کے گواہ ہو تم زمین میں اللہ کے گواہ ہو تم زمین میں اللہ کے گواہ ہو ۔","",{"u2":"عبد العزیز بن صہیب نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:ایک جنازہ گزرا تو اس کی اچھی صفت بیان کی گئی اس پر نبی اکرم صلی اللہ علیہ وسلم نے فر ما یا: \"واجب ہو گئی واجب ہو گئی واجب ہو گئی،اس کے بعد ایک اور جنازہ گزرا تو اس کی بری صفت بیان کی گئی تو نبی اکرم صلی اللہ علیہ وسلم نے فر ما یا:\" واجب ہو گئی واجب ہو گئی واجب ہو گئی اس پرحضرت عمر رضی اللہ تعالیٰ عنہ نے کہا: آپ پر میرے ماں باپ فدا ہوں! ایک جنازہ گزرا اور اس کی اچھی صفت بیان کی گئی تو آپ نے فر ما یا:\" واجب ہو گئی واجب ہو گئی واجب ہو گئی۔ایک اور جنازہ گزرا اور اس کی بری صفت بیان کی گئی تو آپ نے فر ما یا واجب ہو گئی واجب ہو گئی واجب ہو گئی\"(اس کا مطلب کیا ہے؟) تو رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\"جس کی تم لو گوں نےاچھی صفت بیان کی اس کے لیے جنت واجب ہو گئی اور جس کی تم نے بری صفت بیان کی اس کے لیے آگ واجب ہو گئی تم زمین میں اللہ کے گواہ ہو تم زمین میں اللہ کے گواہ ہو تم زمین میں اللہ کے گواہ ہو۔"}],[2144,"ثابت نے سیدنا انس رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا : نبی اکرم صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا ۔ ۔ ۔ اس کے بعد انھوں نے انس سے عبد العزیز کی ( سابقہ ) حدیث کے ہم معنی حدیث بیان کی البتہ عبد العزیز کی حدیث زیادہ مکمل ہے ۔","",{"u2":"ثابت نے حضرت انس رضی اللہ تعالیٰ عنہ سے روایت کی انھوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا۔۔۔اس کے بعد انھوں نے انس سے عبد العزیز کی (سابقہ) حدیث کے ہم معنی حدیث بیان کی البتہ عبد العزیز کی حدیث زیادہ مکمل ہے۔"}],[2145,"امام مالک بن انس نے محمد بن عمرو بن حلحلہ سے ، انھوں نے معبد بن کعب بن مالک سے اور انھوں نے سیدنا قتادہ بن ربعی رضی اللہ تعالیٰ عنہ سے روایت کی ، وہ حدیث بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا تو آپ نے فر ما یا : \" آرام پانے والا ہے یا اس سے آرام ملنے والا ہے ۔ انھوں ( صحابہ ) نے پو چھا اے اللہ کے رسول صلی اللہ علیہ وسلم !آرام پانے والا یا جس سے آرام ملنے والا ہے سے کیا مراد ہے؟ تو آپ نے فر ما یا : \" بندہ مومن دنیا کی تکا لیف سے آرام پا تا ہے اور فاجر بندے ( کے مرنے ) سے لو گ شہر درخت اور حیوانات آرام پاتے ہیں ۔","",{"u2":"امام مالک بن انس نے محمد بن عمرو بن حلحلہ سے،انھوں نے معبد بن کعب بن مالک سے اور انھوں نے حضرت قتادہ بن ربعی رضی اللہ تعالیٰ عنہ سے روایت کی، وہ حدیث بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا تو آپ نے فر ما یا:\"آرام پانے والا ہے یا اس سے آرام ملنے والا ہے۔انھوں (صحابہ) نے پو چھا اے اللہ کے رسول صلی اللہ علیہ وسلم!آرام پانے والا یا جس سے آرام ملنے والا ہے سے کیا مراد ہے؟ تو آپ نے فر ما یا:\"بندہ مومن دنیا کی تکا لیف سے آرام پا تا ہے اور فاجر بندے (کے مرنے) سے لو گ شہر درخت اور حیوانات آرام پاتے ہیں۔"}],[2146,"یحییٰ بن سعید اور عبد الرزاق نے عبد اللہ بن سعید سے انھوں نے محمد بن عمرو سے انھوں نے کعب بن مالک کے بیٹے ( معبد ) سے انھوں نے سیدنا ابو قتادہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے ( سابقہ حدیث کے مانند ) روایت بیان کی اور یحییٰ کی حدیث میں ہے : \" وہ ( مومن بندہ ) اللہ کی رحمت میں آکر دنیا کی اذیت اور تکان سے آرام حاصل کر لیتا ہے ۔","",{"u2":"یحییٰ بن سعید اور عبد الرزاق نے عبد اللہ بن سعید سے انھوں نے محمد بن عمرو سے انھوں نے کعب بن مالک کے بیٹے (معبد) سے انھوں نے حضرت ابو قتادہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے (سابقہ حدیث کے مانند) روایت بیان کی اور یحییٰ کی حدیث میں ہے:\"وہ (مومن بندہ) اللہ کی رحمت میں آکر دنیا کی اذیت اور تکان سے آرام حاصل کر لیتا ہے۔"}],[2147,"امام مالکؒ نے ابن شہاب سے ، انھوں نے سعید بن مسیب سے اور انھوں نے سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جس دن نجاشی فوت ہوئے ، لوگوں کو ان کی وفات کی اطلاع دی ، آپ صلی اللہ علیہ وسلم ان ( صحابہ کرام رضوان اللہ عنھم اجمعین ) کے ساتھ باہر جنازہ گاہ میں گئے اور آپ صلی اللہ علیہ وسلم نے چارتکبیریں کہیں ۔","",{"u2":"امام مالک رحمہ اللہ نے ابن شہاب سے،انھوں نے سعید بن مسیب سے اور انھوں نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جس دن نجاشی فوت ہوئے،لوگوں کو ان کی وفات کی اطلاع دی،آپ صلی اللہ علیہ وسلم ان (صحابہ کرام رضوان اللہ عنھم اجمعین) کے ساتھ باہر جنازہ گاہ میں گئے اور آپ صلی اللہ علیہ وسلم نے چارتکبیریں کہیں۔"}],[2148,"عقیل بن خالد نے ابن شہاب سے ، انھوں نے سعید بن مسیب اور ابو سلمہ بن عبدالرحمان سے اور ان دونوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حبشہ والے ( حکمران ) نجاشی کی ، جس دن وہ فوت ہوئے ، موت کی خبر دی اور فرمایا : \"\" اپنے بھائی کے لئے بخشش کی دعا کرو ۔ \"\" ابن شہاب نے کہا : مجھے سعید بن مسیب نے حدیث سنائی کہ ان کو سیدنا ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جنازہ گاہ میں ان کی صفیں بنوائیں ، نماز ( جنازہ ) پڑھائی اور اور پر چار تکبیریں کہیں ۔","",{"u2":"عقیل بن خالد نے ابن شہاب سے،انھوں نے سعید بن مسیب اور ابو سلمہ بن عبدالرحمان سے اور ان دونوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حبشہ والے(حکمران) نجاشی کی،جس دن وہ فوت ہوئے،موت کی خبر دی اور فرمایا:\"اپنے بھائی کے لئے بخشش کی دعاکرو۔\"\nابن شہاب نے کہا: مجھے سعید بن مسیب نے حدیث سنائی کہ ان کو حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جنازہ گاہ میں ان کی صفیں بنوائیں،نماز(جنازہ) پڑھائی اور اور پر چار تکبیریں کہیں۔"}],[2149,"صالح نے دونوں سندوں کے ساتھ ابن شہاب سے عقیل ( بن خالد ) کی روایت کے مانند روایت کی ۔","",{"u2":"صالح نے دونوں سندوں کے ساتھ ابن شہاب سے عقیل (بن خالد) کی روایت کے مانند روایت کی۔"}],[2150,"سعید بن میناء نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اصمحہ نجاشی کی نماز جنازہ ادا کی تو اس پر چار تکبیریں کہیں ۔","",{"u2":"سعید بن میناء نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اصمحہ نجاشی کی نمازجنازہ ادا کی تو اس پر چار تکبیریں کہیں۔"}],[2151,"عطاء نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" آج اللہ کا ایک نیک بندہ اصمحہ فوت ہوگیا ہے ۔ \" اس کے بعد آپ صلی اللہ علیہ وسلم کھڑے ہوئے ، ہماری امامت کرائی اور اس کی نماز جنازہ ادا کی ۔","",{"u2":"عطاء نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"آج اللہ کا ایک نیک بندہ اصمحہ فوت ہوگیا ہے۔\"اس کے بعد آپ صلی اللہ علیہ وسلم کھڑے ہوئے،ہماری امامت کرائی اور اس کی نماز جنازہ ادا کی۔"}],[2152,"ابو زبیر نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بلاشبہ تمھارا ایک بھائی وفات پاگیا ہے ، لہٰذا تم لوگ اٹھو اور اس پر نماز ( جنازہ ) پڑھو ۔ \" ( جابر رضی اللہ تعالیٰ عنہ نے ) کہا : اس پر ہم اٹھے تو آپ صلی اللہ علیہ وسلم نے ہماری دو صفیں بنائیں ۔","",{"u2":"ابو زبیر نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"بلاشبہ تمھارا ایک بھائی وفات پاگیا ہے،لہذا تم لوگ اٹھو اور اس پر نماز(جنازہ) پڑھو۔\"(جابر رضی اللہ تعالیٰ عنہ نے) کہا:اس پر ہم اٹھے تو آپ صلی اللہ علیہ وسلم نے ہماری دو صفیں بنائیں۔"}]]);
